if(!window.__twConvDone){window.__twConvDone=true;var CONV_DATA={en:[{stage:1,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"التعارف مع جار جديد",grammar:{id:"en-a-an-the",title:"a / an / the",titleAr:"أدوات التعريف والتنكير",covers:1},conv:{id:"en-stage1",speakers:["Neighbor (الجار)","New Neighbor (الجار الجديد)"],turns:[{s:0,t:"Hi! Are you the new neighbor?",ar:"مرحبًا! هل أنت الجار الجديد؟"},{s:1,t:"Yeah, that's me. I just moved in today.",ar:"نعم، هذا أنا. انتقلت للتو اليوم."},{s:0,t:"Welcome to our street! It's a nice place.",ar:"أهلًا بك في شارعنا! إنه مكان لطيف."},{s:1,t:"Thanks! It looks quiet and friendly.",ar:"شكرًا! يبدو هادئًا وودودًا."},{s:0,t:"It is. I live in the house next to yours.",ar:"نعم. أعيش في البيت المجاور لبيتك."},{s:1,t:"Oh, great. So we're neighbors now.",ar:"أوه، رائع. إذن نحن جيران الآن."},{s:0,t:"Yes! Where are you from?",ar:"نعم! من أين أنت؟"},{s:1,t:"I'm from a small town in the north.",ar:"أنا من بلدة صغيرة في الشمال."},{s:0,t:"Really? And what do you do?",ar:"حقًا؟ وماذا تعمل؟"},{s:1,t:"I'm a teacher. I teach English at a school.",ar:"أنا معلم. أدرّس الإنجليزية في مدرسة."},{s:0,t:"Cool! My daughter is a student there.",ar:"رائع! ابنتي طالبة هناك."},{s:1,t:"Oh, nice. How old is she?",ar:"أوه، جميل. كم عمرها؟"},{s:0,t:"She's twelve. And my son is nine.",ar:"عمرها اثنتا عشرة سنة. وابني عمره تسع سنوات."},{s:1,t:"That's a good age. Do you have a big family?",ar:"هذا عمر جميل. هل لديك عائلة كبيرة؟"},{s:0,t:"Not really. Just my wife, the two kids, and me.",ar:"ليست كبيرة فعلًا. زوجتي فقط والطفلان وأنا."},{s:1,t:"Same here. It's just me and my wife.",ar:"وأنا كذلك. أنا وزوجتي فقط."},{s:0,t:"Do you have any brothers or sisters?",ar:"هل لديك إخوة أو أخوات؟"},{s:1,t:"Yeah, one brother and one sister. They're both married.",ar:"نعم، أخ واحد وأخت واحدة. وكلاهما متزوج."},{s:0,t:"And your parents? Do they live near here?",ar:"ووالداك؟ هل يعيشان قريبًا من هنا؟"},{s:1,t:"No, they live far away, in the south.",ar:"لا، يعيشان بعيدًا، في الجنوب."},{s:0,t:"I see. My mother lives with us, by the way.",ar:"فهمت. أمي تعيش معنا، بالمناسبة."},{s:1,t:"That's nice. How old is she?",ar:"هذا جميل. كم عمرها؟"},{s:0,t:"She's sixty-five. She loves this neighborhood.",ar:"عمرها خمسة وستون عامًا. تحب هذا الحي."},{s:1,t:"I can see why. It's green and quiet.",ar:"أستطيع أن أفهم لماذا. إنه أخضر وهادئ."},{s:0,t:"Yeah. So, when's your birthday?",ar:"نعم. إذن، متى عيد ميلادك؟"},{s:1,t:"In April. April the fifth. And yours?",ar:"في نيسان. الخامس من نيسان. وأنت؟"},{s:0,t:"Mine is in August. August the twentieth.",ar:"عيد ميلادي في آب. العشرون من آب."},{s:1,t:"Ha! We're both summer babies, more or less.",ar:"ها! كلانا من مواليد الصيف، تقريبًا."},{s:0,t:"True. Hey, what's your phone number?",ar:"صحيح. مهلًا، ما رقم هاتفك؟"},{s:1,t:"Sure. It's five-five-five, oh-one-two-three.",ar:"بالتأكيد. إنه خمسة خمسة خمسة، صفر واحد اثنان ثلاثة."},{s:0,t:"Got it. And your email address?",ar:"فهمت. وعنوان بريدك الإلكتروني؟"},{s:1,t:"It's my name at mail dot com. I'll write it down for you.",ar:"بريدي الإلكتروني هو اسمي ثم at ثم mail dot com. سأكتبه لك."},{s:0,t:"Perfect, thanks. Oh, do you like coffee?",ar:"ممتاز، شكرًا. أوه، هل تحب القهوة؟"},{s:1,t:"I love it. But I don't drink it at night.",ar:"أحبها كثيرًا. لكنني لا أشربها في الليل."},{s:0,t:"Me neither. Come over tomorrow morning?",ar:"وأنا كذلك. هل تأتي إلينا صباح الغد؟"},{s:1,t:"I'd love to. What time?",ar:"أحب ذلك. في أي وقت؟"},{s:0,t:"Around nine o'clock. My wife makes great cake.",ar:"حوالي التاسعة. زوجتي تصنع كعكًا رائعًا."},{s:1,t:"Sounds wonderful. See you then!",ar:"يبدو رائعًا. أراك حينها!"},{s:0,t:"See you! And welcome again!",ar:"أراك! وأهلًا بك مرة أخرى!"}]}},{stage:2,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"في السوق والمقهى",grammar:{id:"en-would-like",title:"Would like",titleAr:"Would like للطلب المهذب",covers:1},conv:{id:"en-stage2",speakers:["Seller (البائع)","Customer (الزبون)"],turns:[{s:1,t:"Good morning! What is fresh today?",ar:"صباح الخير! ما الطازج اليوم؟"},{s:0,t:"Good morning! The tomatoes and the carrots are fresh.",ar:"صباح الخير! الطماطم والجزر طازجان."},{s:1,t:"Great. I'd like a kilo of tomatoes, please.",ar:"رائع. أريد كيلو من الطماطم، من فضلك."},{s:0,t:"Sure. Anything else?",ar:"بالتأكيد. أي شيء آخر؟"},{s:1,t:"Yeah, some onions and two kilos of potatoes.",ar:"نعم، بعض البصل وكيلوين من البطاطا."},{s:0,t:"Here you are. Do you need fruit too?",ar:"تفضل. هل تحتاج فواكه أيضًا؟"},{s:1,t:"Hmm. How much are the apples?",ar:"همم. بكم التفاح؟"},{s:0,t:"Two dollars a kilo. They're sweet and red.",ar:"دولاران للكيلو. إنها حلوة وحمراء."},{s:1,t:"OK, I'll take a kilo. And a kilo of bananas.",ar:"حسنًا، سآخذ كيلوًا. وكيلو من الموز."},{s:0,t:"Good choice. Do you want some bread?",ar:"اختيار جيد. هل تريد بعض الخبز؟"},{s:1,t:"Yes, please. One loaf of bread.",ar:"نعم، من فضلك. رغيف خبز واحد."},{s:0,t:"White or brown bread?",ar:"خبز أبيض أم أسمر؟"},{s:1,t:"Brown, please. It's healthier.",ar:"أسمر، من فضلك. إنه أصح."},{s:0,t:"True. We also have cheese and butter.",ar:"صحيح. لدينا أيضًا جبن وزبدة."},{s:1,t:"Oh, I'd like a piece of cheese.",ar:"أوه، أريد قطعة جبن."},{s:0,t:"This one is delicious. Try a little.",ar:"هذه لذيذة. جرّب قليلًا."},{s:1,t:"Mmm, you're right. It's really good.",ar:"ممم، أنت محق. إنها جيدة فعلًا."},{s:0,t:"And some milk? Or eggs?",ar:"وبعض الحليب؟ أو البيض؟"},{s:1,t:"Yes, a bottle of milk and six eggs.",ar:"نعم، زجاجة حليب وست بيضات."},{s:0,t:"Anything for dinner tonight?",ar:"أي شيء لعشاء الليلة؟"},{s:1,t:"Hmm, some chicken, please. A small one.",ar:"همم، بعض الدجاج، من فضلك. دجاجة صغيرة."},{s:0,t:"Here it is. That's twelve dollars in all.",ar:"ها هي. المجموع اثنا عشر دولارًا."},{s:1,t:"Twelve? That's cheap! Here you are.",ar:"اثنا عشر؟ هذا رخيص! تفضل."},{s:0,t:"Thank you! Come again soon.",ar:"شكرًا لك! تعال مرة أخرى قريبًا."},{s:1,t:"I will. Oh, wait — where's the cafe?",ar:"سأفعل. أوه، انتظر — أين المقهى؟"},{s:0,t:"—Just across the street, next to the bank.",ar:"—على الجانب الآخر من الشارع، بجانب المصرف."},{s:1,t:"Perfect. I'd like a coffee and a sandwich.",ar:"ممتاز. أريد قهوة وساندويتش."},{s:0,t:"The cafe is great. Their soup is fantastic.",ar:"المقهى رائع. حساؤهم مذهل."},{s:1,t:"Really? Then I'll try the soup too.",ar:"حقًا؟ إذن سأجرب الحساء أيضًا."},{s:0,t:"And maybe some ice cream after?",ar:"وربما بعض الآيس كريم بعدها؟"},{s:1,t:"Uh-huh. With chocolate, of course.",ar:"أمم. بالشوكولاتة، بالطبع."},{s:0,t:"Ha! Enjoy your lunch.",ar:"ها! استمتع بغدائك."},{s:1,t:"Thanks! See you tomorrow.",ar:"شكرًا! أراك غدًا."},{s:0,t:"Bye! Have a nice day!",ar:"إلى اللقاء! أتمنى لك يومًا سعيدًا!"},{s:1,t:"You too!",ar:"وأنت أيضًا!"},{s:0,t:"Oh, and don't forget your bag!",ar:"أوه، ولا تنسَ حقيبتك!"},{s:1,t:"Oh no, thanks! I almost forgot it.",ar:"أوه لا، شكرًا! كدت أنساها."},{s:0,t:"No problem. Bye!",ar:"لا مشكلة. إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:3,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"زيارة بيت جديد",grammar:{id:"en-there-is-are",title:"There is / There are",titleAr:"هناك There is/are",covers:1},conv:{id:"en-stage3",speakers:["Host (المضيف)","Guest (الضيف)"],turns:[{s:0,t:"Welcome to my new apartment!",ar:"أهلًا بك في شقتي الجديدة!"},{s:1,t:"Wow, it's beautiful! And so big!",ar:"واو، إنها جميلة! وكبيرة جدًا!"},{s:0,t:"Thanks! Come in, please. Sit down.",ar:"شكرًا! ادخل، من فضلك. اجلس."},{s:1,t:"Thank you. Is this your living room?",ar:"شكرًا لك. هل هذه غرفة معيشتك؟"},{s:0,t:"Yes, it is. There's a big sofa and a TV.",ar:"نعم. فيها أريكة كبيرة وتلفاز."},{s:1,t:"I love the blue sofa. It's very comfortable.",ar:"أحب الأريكة الزرقاء. إنها مريحة جدًا."},{s:0,t:"Yeah, and there are two chairs next to it.",ar:"نعم، وهناك كرسيان بجانبها."},{s:1,t:"And that picture on the wall is amazing.",ar:"وتلك الصورة على الحائط مذهلة."},{s:0,t:"My mother painted it. She's an artist.",ar:"أمي رسمتها. إنها فنانة."},{s:1,t:"Really? She's very good.",ar:"حقًا؟ إنها جيدة جدًا."},{s:0,t:"Come and see the kitchen. It's over here.",ar:"تعال وشاهد المطبخ. إنه من هنا."},{s:1,t:"Oh, it's small but nice. Is there a table?",ar:"أوه، إنه صغير لكنه لطيف. هل توجد طاولة؟"},{s:0,t:"Yes, there's a small table and four chairs.",ar:"نعم، توجد طاولة صغيرة وأربعة كراسٍ."},{s:1,t:"Perfect for breakfast. And the fridge?",ar:"مثالية للفطور. والثلاجة؟"},{s:0,t:"It's in the corner, next to the door.",ar:"إنها في الزاوية، بجانب الباب."},{s:1,t:"I see. How many bedrooms are there?",ar:"فهمت. كم عدد غرف النوم؟"},{s:0,t:"There are two bedrooms and one bathroom.",ar:"توجد غرفتا نوم وحمام واحد."},{s:1,t:"Is there a bathroom upstairs too?",ar:"هل يوجد حمام في الطابق العلوي أيضًا؟"},{s:0,t:"No, there's only one, downstairs.",ar:"لا، يوجد واحد فقط، في الطابق السفلي."},{s:1,t:"OK. And is there a garden?",ar:"حسنًا. وهل توجد حديقة؟"},{s:0,t:"Yes! There's a small garden behind the house.",ar:"نعم! توجد حديقة صغيرة خلف البيت."},{s:1,t:"With flowers? I love flowers.",ar:"فيها أزهار؟ أنا أحب الأزهار."},{s:0,t:"Yeah, red and yellow flowers. And a big tree.",ar:"نعم، أزهار حمراء وصفراء. وشجرة كبيرة."},{s:1,t:"Wonderful. Is there a garage for the car?",ar:"رائع. هل يوجد مرآب للسيارة؟"},{s:0,t:"No, there isn't. But there's a bus stop near here.",ar:"لا، لا يوجد. لكن توجد محطة حافلات قريبة من هنا."},{s:1,t:"That's fine. I usually walk anyway.",ar:"هذا جيد. أنا أمشي عادة على أي حال."},{s:0,t:"Me too. The supermarket is only five minutes away.",ar:"وأنا كذلك. السوبرماركت على بعد خمس دقائق فقط."},{s:1,t:"That's so useful. Is it expensive here?",ar:"هذا مفيد جدًا. هل الأسعار غالية هنا؟"},{s:0,t:"Not really. The rent is OK for this area.",ar:"ليست كذلك فعلًا. الإيجار مناسب لهذه المنطقة."},{s:1,t:"Good to know. I like your home a lot.",ar:"من الجيد معرفة ذلك. أحب بيتك كثيرًا."},{s:0,t:"Thanks! Would you like some tea?",ar:"شكرًا! هل تريد بعض الشاي؟"},{s:1,t:"Yes, please. With a little sugar.",ar:"نعم، من فضلك. مع قليل من السكر."},{s:0,t:"Here you are. Let's sit in the garden.",ar:"تفضل. لنجلس في الحديقة."},{s:1,t:"Great idea. It's warm and sunny today.",ar:"فكرة رائعة. الجو دافئ ومشمس اليوم."},{s:0,t:"Yeah, I love days like this.",ar:"نعم، أحب أيامًا كهذه."},{s:1,t:"Me too. Thanks for the visit!",ar:"وأنا كذلك. شكرًا على الزيارة!"},{s:0,t:"Any time! Come again soon.",ar:"في أي وقت! تعال مرة أخرى قريبًا."},{s:1,t:"I will. Bye!",ar:"سأفعل. إلى اللقاء!"}]}},{stage:4,topic:"clothes",topicAr:"الملابس والتسوق",topicEn:"Clothes & Shopping",topicDe:"Kleidung und Einkaufen",emoji:"👕",title:"شراء ملابس جديدة",grammar:{id:"en-imperatives",title:"Imperatives",titleAr:"الأمر Imperatives",covers:1},conv:{id:"en-stage4",speakers:["Seller (البائع)","Customer (الزبون)"],turns:[{s:0,t:"Hello! Welcome to our shop!",ar:"مرحبًا! أهلًا بك في متجرنا!"},{s:1,t:"Hi! I'm looking for a jacket.",ar:"مرحبًا! أبحث عن سترة."},{s:0,t:"Sure! What color do you like?",ar:"بالتأكيد! أي لون تحب؟"},{s:1,t:"Hmm, black or blue. Something warm.",ar:"همم، أسود أو أزرق. شيء دافئ."},{s:0,t:"Try this one. It's warm and cheap.",ar:"جرّب هذه. إنها دافئة ورخيصة."},{s:1,t:"Nice. How much is it?",ar:"جميلة. بكم هي؟"},{s:0,t:"Forty dollars. It's on sale today.",ar:"أربعون دولارًا. إنها مخفضة اليوم."},{s:1,t:"Forty? That's a good price.",ar:"أربعون؟ هذا سعر جيد."},{s:0,t:"Try it on. The mirror is over there.",ar:"جرّبها. المرآة هناك."},{s:1,t:"OK. Hmm, it's a little big.",ar:"حسنًا. همم، إنها كبيرة قليلًا."},{s:0,t:"No problem. Try a smaller size.",ar:"لا مشكلة. جرّب مقاسًا أصغر."},{s:1,t:"This one is better. Much better.",ar:"هذه أفضل. أفضل بكثير."},{s:0,t:"It looks great on you. Really.",ar:"تبدو رائعة عليك. حقًا."},{s:1,t:"Thanks! I'll take it.",ar:"شكرًا! سآخذها."},{s:0,t:"Great. Do you need anything else?",ar:"رائع. هل تحتاج أي شيء آخر؟"},{s:1,t:"Yeah, a pair of jeans, please.",ar:"نعم، بنطال جينز، من فضلك."},{s:0,t:"What size? Thirty-two or thirty-four?",ar:"أي مقاس؟ اثنان وثلاثون أم أربعة وثلاثون؟"},{s:1,t:"Thirty-two, please.",ar:"اثنان وثلاثون، من فضلك."},{s:0,t:"Here you are. And a shirt to go with them?",ar:"تفضل. وقميص معه؟"},{s:1,t:"Maybe a white shirt. A plain one.",ar:"ربما قميص أبيض. قميص بسيط."},{s:0,t:"Here. This white shirt is very popular.",ar:"ها هو. هذا القميص الأبيض مشهور جدًا."},{s:1,t:"Hmm, it's nice, but it's too expensive.",ar:"همم، إنه جميل، لكنه غالٍ جدًا."},{s:0,t:"Wait, look at this one. It's cheaper.",ar:"انتظر، انظر إلى هذا. إنه أرخص."},{s:1,t:"Oh, I like this one. How much?",ar:"أوه، أحب هذا. بكم؟"},{s:0,t:"Fifteen dollars. And the jeans are thirty.",ar:"خمسة عشر دولارًا. والجينز بثلاثين."},{s:1,t:"OK, I'll take both.",ar:"حسنًا، سآخذ الاثنين."},{s:0,t:"Good choice. Do you want a hat too?",ar:"اختيار جيد. هل تريد قبعة أيضًا؟"},{s:1,t:"No, thanks. But I need new shoes.",ar:"لا، شكرًا. لكنني أحتاج حذاءً جديدًا."},{s:0,t:"Our shoes are upstairs. Go up and look.",ar:"أحذيتنا في الطابق العلوي. اصعد وانظر."},{s:1,t:"Hmm, maybe next time. I have enough bags.",ar:"همم، ربما في المرة القادمة. لدي أكياس كافية."},{s:0,t:"Ha! OK. Let's check out, then.",ar:"ها! حسنًا. لندفع إذن."},{s:1,t:"Can I pay by card?",ar:"هل يمكنني الدفع بالبطاقة؟"},{s:0,t:"Of course. Put your card here, please.",ar:"بالطبع. ضع بطاقتك هنا، من فضلك."},{s:1,t:"Done. Is there a bag for the clothes?",ar:"تم. هل توجد حقيبة للملابس؟"},{s:0,t:"Yes, here you are. Have a nice day!",ar:"نعم، تفضل. أتمنى لك يومًا سعيدًا!"},{s:1,t:"You too. Bye!",ar:"وأنت أيضًا. إلى اللقاء!"},{s:0,t:"Bye! Come again!",ar:"إلى اللقاء! تعال مرة أخرى!"},{s:1,t:"Oh wait, I forgot my coat!",ar:"أوه انتظر، نسيت معطفي!"},{s:0,t:"Here it is. Don't forget it again!",ar:"ها هو. لا تنسَه مرة أخرى!"},{s:1,t:"Ha! Thanks. Bye!",ar:"ها! شكرًا. إلى اللقاء!"}]}},{stage:5,topic:"routine",topicAr:"اليوم الروتيني والمدرسة والعمل",topicEn:"Daily Routine, School & Work",topicDe:"Alltag, Schule und Arbeit",emoji:"⏰",title:"يوم دراسي كامل",grammar:{id:"en-time-expressions",title:"Time expressions",titleAr:"تعابير الوقت",covers:1},conv:{id:"en-stage5",speakers:["Student (الطالب)","Classmate (زميل الدراسة)"],turns:[{s:0,t:"Good morning! Did you wake up early?",ar:"صباح الخير! هل استيقظت باكرًا؟"},{s:1,t:"No! I woke up at seven. I'm so tired.",ar:"لا! استيقظت في السابعة. أنا متعب جدًا."},{s:0,t:"Me too. I went to bed late last night.",ar:"وأنا كذلك. ذهبت إلى الفراش متأخرًا الليلة الماضية."},{s:1,t:"Why? What did you do?",ar:"لماذا؟ ماذا فعلت؟"},{s:0,t:"I studied for the English exam. Until midnight.",ar:"درست لامتحان الإنجليزية. حتى منتصف الليل."},{s:1,t:"Oh no. Was it difficult?",ar:"أوه لا. هل كان صعبًا؟"},{s:0,t:"A little. But I think I did OK.",ar:"قليلًا. لكن أظن أنني أبليت حسنًا."},{s:1,t:"Good luck! When is the exam?",ar:"حظًا سعيدًا! متى الامتحان؟"},{s:0,t:"Tomorrow morning, at nine o'clock.",ar:"صباح الغد، في التاسعة."},{s:1,t:"Then study again tonight, but not too late.",ar:"إذن ادرس مرة أخرى الليلة، لكن ليس متأخرًا جدًا."},{s:0,t:"Yeah, you're right. What lessons do we have today?",ar:"نعم، أنت محق. ما الدروس التي لدينا اليوم؟"},{s:1,t:"First, math. Then geography and science.",ar:"أولًا، الرياضيات. ثم الجغرافيا والعلوم."},{s:0,t:"Ugh, math again? I don't like it.",ar:"أوه، الرياضيات مرة أخرى؟ لا أحبها."},{s:1,t:"Me neither. But I love science.",ar:"وأنا كذلك. لكنني أحب العلوم."},{s:0,t:"Yeah, science is interesting. And history?",ar:"نعم، العلوم ممتعة. والتاريخ؟"},{s:1,t:"History is after lunch. At one o'clock.",ar:"التاريخ بعد الغداء. في الواحدة."},{s:0,t:"OK. Did you do your homework?",ar:"حسنًا. هل أنجزت واجبك؟"},{s:1,t:"Yes, I did it yesterday evening.",ar:"نعم، أنجزته مساء أمس."},{s:0,t:"Really? I forgot about it. Can you help me?",ar:"حقًا؟ نسيته. هل يمكنك مساعدتي؟"},{s:1,t:"Sure, at lunch time. We have twenty minutes.",ar:"بالتأكيد، في وقت الغداء. لدينا عشرون دقيقة."},{s:0,t:"Thanks! You're a good friend.",ar:"شكرًا! أنت صديق جيد."},{s:1,t:"No problem. Oh, what time is it now?",ar:"لا مشكلة. أوه، كم الساعة الآن؟"},{s:0,t:"It's eight fifteen. Class starts soon.",ar:"إنها الثامنة والربع. يبدأ الدرس قريبًا."},{s:1,t:"Quick! Let's go to the classroom.",ar:"بسرعة! لنذهب إلى الصف."},{s:0,t:"Wait, I need my books. They're in my bag.",ar:"انتظر، أحتاج كتبي. إنها في حقيبتي."},{s:1,t:"Hurry up! The teacher is already there.",ar:"أسرع! المعلم موجود هناك بالفعل."},{s:0,t:"OK, OK. I'm coming.",ar:"حسنًا، حسنًا. أنا قادم."},{s:1,t:"After school, do you want to play football?",ar:"بعد المدرسة، هل تريد أن تلعب كرة القدم؟"},{s:0,t:"I'd love to, but I have to study.",ar:"أحب ذلك، لكن عليّ أن أدرس."},{s:1,t:"Just for an hour? Come on!",ar:"لساعة واحدة فقط؟ هيا!"},{s:0,t:"Hmm, OK. One hour, then I go home.",ar:"همم، حسنًا. ساعة واحدة، ثم أذهب إلى البيت."},{s:1,t:"Deal! At four o'clock, at the park.",ar:"اتفقنا! في الرابعة، في الحديقة."},{s:0,t:"Perfect. And on Friday we have no school!",ar:"ممتاز. وفي يوم الجمعة ليس لدينا مدرسة!"},{s:1,t:"Really? That's fantastic!",ar:"حقًا؟ هذا رائع!"},{s:0,t:"Yeah. Friday is my favorite day.",ar:"نعم. الجمعة هو يومي المفضل."},{s:1,t:"Mine too. See you in class!",ar:"وأنا كذلك. أراك في الصف!"},{s:0,t:"See you!",ar:"أراك!"}]}},{stage:6,topic:"weather",topicAr:"الأوقات والطقس",topicEn:"Times & Weather",topicDe:"Zeiten und Wetter",emoji:"🌤️",title:"الطقس وعطلة نهاية الأسبوع",grammar:{id:"en-time-expressions",title:"Time expressions",titleAr:"تعابير الوقت",covers:1},conv:{id:"en-stage6",speakers:["Friend (الصديق)","Neighbor (الجار)"],turns:[{s:0,t:"Hello! What a sunny day!",ar:"مرحبًا! يا له من يوم مشمس!"},{s:1,t:"Yeah, it's beautiful. Warm and bright.",ar:"نعم، إنه جميل. دافئ ومشرق."},{s:0,t:"Finally! Yesterday it was so cold.",ar:"أخيرًا! أمس كان الجو باردًا جدًا."},{s:1,t:"I know. And it rained all day.",ar:"أعلم. وأمطرت طوال اليوم."},{s:0,t:"Ugh, I hate rain in winter.",ar:"أوه، أكره المطر في الشتاء."},{s:1,t:"Me too. But summer is coming soon.",ar:"وأنا كذلك. لكن الصيف قادم قريبًا."},{s:0,t:"When? In June or July?",ar:"متى؟ في حزيران أم تموز؟"},{s:1,t:"In June. June is usually hot here.",ar:"في حزيران. حزيران عادة حار هنا."},{s:0,t:"Good. I love hot weather.",ar:"جيد. أحب الطقس الحار."},{s:1,t:"Really? I prefer spring. Not too hot, not too cold.",ar:"حقًا؟ أنا أفضل الربيع. ليس حارًا جدًا ولا باردًا جدًا."},{s:0,t:"Spring is nice too. The flowers are so pretty.",ar:"الربيع جميل أيضًا. الأزهار جميلة جدًا."},{s:1,t:"Yeah. And in autumn the leaves are yellow and red.",ar:"نعم. وفي الخريف تكون الأوراق صفراء وحمراء."},{s:0,t:"True. So, what are you doing this weekend?",ar:"صحيح. إذن، ماذا تفعل في عطلة نهاية الأسبوع هذه؟"},{s:1,t:"On Saturday I'm going to the beach.",ar:"يوم السبت سأذهب إلى الشاطئ."},{s:0,t:"The beach? Is it warm enough to swim?",ar:"إلى الشاطئ؟ هل الجو دافئ بما يكفي للسباحة؟"},{s:1,t:"I think so. It will be twenty-eight degrees.",ar:"أظن ذلك. ستكون الحرارة ثماني وعشرين درجة."},{s:0,t:"Wow, that's hot! Can I come with you?",ar:"واو، هذا حار! هل يمكنني المجيء معك؟"},{s:1,t:"Of course! Bring your swimsuit and a hat.",ar:"بالطبع! أحضر ملابس السباحة وقبعة."},{s:0,t:"And sunscreen. I don't want to get burned.",ar:"وكريمًا واقيًا من الشمس. لا أريد أن أحترق."},{s:1,t:"Good idea. And bring some water too.",ar:"فكرة جيدة. وأحضر بعض الماء أيضًا."},{s:0,t:"What about Sunday? Any plans?",ar:"وماذا عن الأحد؟ هل لديك خطط؟"},{s:1,t:"On Sunday I'll stay home. I'm tired.",ar:"يوم الأحد سأبقى في البيت. أنا متعب."},{s:0,t:"Stay home? On a sunny Sunday?",ar:"تبقى في البيت؟ في أحد مشمس؟"},{s:1,t:"Yeah, I need to rest. And read a book.",ar:"نعم، أحتاج إلى الراحة. وقراءة كتاب."},{s:0,t:"Hmm, OK. Maybe I'll go for a walk instead.",ar:"همم، حسنًا. ربما سأذهب للمشي بدلًا من ذلك."},{s:1,t:"In the park? The trees there are beautiful now.",ar:"في الحديقة؟ الأشجار هناك جميلة الآن."},{s:0,t:"Yeah. Or I could ride my bike.",ar:"نعم. أو يمكنني ركوب دراجتي."},{s:1,t:"Nice. What time will you go to the beach on Saturday?",ar:"جميل. في أي وقت ستذهب إلى الشاطئ يوم السبت؟"},{s:0,t:"At ten in the morning. Before it gets too hot.",ar:"في العاشرة صباحًا. قبل أن يصبح الجو حارًا جدًا."},{s:1,t:"Perfect. I'll meet you at your house at nine thirty.",ar:"ممتاز. سأقابلك عند بيتك في التاسعة والنصف."},{s:0,t:"Deal. Oh, look — a cloud! Is it going to rain?",ar:"اتفقنا. أوه، انظر — سحابة! هل ستمطر؟"},{s:1,t:"No, don't worry. It's just one small cloud.",ar:"لا، لا تقلق. إنها سحابة صغيرة واحدة فقط."},{s:0,t:"Ha! OK. See you on Saturday, then.",ar:"ها! حسنًا. أراك يوم السبت إذن."},{s:1,t:"See you! And bring your umbrella, just in case.",ar:"أراك! وأحضر مظلتك، تحسبًا."},{s:0,t:"Very funny. Bye!",ar:"مضحك جدًا. إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:7,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"مكالمة ودعوة",grammar:{id:"en-can",title:"can for polite requests",titleAr:"can للطلب بأدب",covers:1},conv:{id:"en-stage7",speakers:["Caller (المتصل)","Friend (الصديق)"],turns:[{s:0,t:"Hi! Are you free on Saturday?",ar:"مرحبًا! هل أنت متفرغ يوم السبت؟"},{s:1,t:"Hi! Yeah, I think so. Why?",ar:"مرحبًا! نعم، أظن ذلك. لماذا؟"},{s:0,t:"I'm having a small party at my house.",ar:"سأقيم حفلة صغيرة في بيتي."},{s:1,t:"A party? For what?",ar:"حفلة؟ لمناسبة ماذا؟"},{s:0,t:"My birthday! I turn twenty-one on Saturday.",ar:"عيد ميلادي! سأبلغ الحادية والعشرين يوم السبت."},{s:1,t:"No way! Happy birthday! What time?",ar:"مستحيل! عيد ميلاد سعيد! في أي وقت؟"},{s:0,t:"At seven in the evening. Can you come?",ar:"في السابعة مساءً. هل يمكنك المجيء؟"},{s:1,t:"Of course! I'd love to come.",ar:"بالطبع! أحب أن آتي."},{s:0,t:"Great! Can you bring your guitar?",ar:"رائع! هل يمكنك إحضار غيتارك؟"},{s:1,t:"Sure. Do you want me to play and sing?",ar:"بالتأكيد. هل تريد مني أن أعزف وأغني؟"},{s:0,t:"Yes, please! Everyone loves your songs.",ar:"نعم، من فضلك! الجميع يحب أغانيك."},{s:1,t:"Ha, OK. Who else is coming?",ar:"ها، حسنًا. من سيأتي أيضًا؟"},{s:0,t:"My family, and some friends from school.",ar:"عائلتي، وبعض الأصدقاء من المدرسة."},{s:1,t:"How many people in all?",ar:"كم عدد الأشخاص في المجموع؟"},{s:0,t:"About fifteen. It's a small party.",ar:"حوالي خمسة عشر. إنها حفلة صغيرة."},{s:1,t:"Nice. Can I bring my brother too?",ar:"جميل. هل يمكنني إحضار أخي أيضًا؟"},{s:0,t:"Yes, of course! The more, the merrier.",ar:"نعم، بالطبع! كلما زاد العدد كان أفضل."},{s:1,t:"Great. What can I bring? Cake? Juice?",ar:"رائع. ماذا يمكنني أن أحضر؟ كعك؟ عصير؟"},{s:0,t:"Hmm, bring some juice, please. I have cake.",ar:"همم، أحضر بعض العصير، من فضلك. لدي كعك."},{s:1,t:"OK. Orange juice or apple juice?",ar:"حسنًا. عصير برتقال أم عصير تفاح؟"},{s:0,t:"Orange juice, please. And some fruit.",ar:"عصير برتقال، من فضلك. وبعض الفاكهة."},{s:1,t:"Got it. Do you need help with the food?",ar:"فهمت. هل تحتاج مساعدة في الطعام؟"},{s:0,t:"Maybe. Can you come early, at five?",ar:"ربما. هل يمكنك المجيء مبكرًا، في الخامسة؟"},{s:1,t:"Yeah, I can. I'll help you cook.",ar:"نعم، أستطيع. سأساعدك في الطبخ."},{s:0,t:"Thanks! You're the best.",ar:"شكرًا! أنت الأفضل."},{s:1,t:"Ha! So, what will we eat?",ar:"ها! إذن، ماذا سنأكل؟"},{s:0,t:"Pizza, salad, and my mom's famous cake.",ar:"بيتزا وسلطة وكعك أمي الشهير."},{s:1,t:"Yum! I love your mom's cake.",ar:"لذيذ! أحب كعك أمك."},{s:0,t:"Me too. Oh, can you call our friend and tell him?",ar:"وأنا كذلك. أوه، هل يمكنك الاتصال بصديقنا وإخباره؟"},{s:1,t:"Hmm, I don't have his number. Can you text me?",ar:"همم، ليس لدي رقمه. هل يمكنك مراسلتي؟"},{s:0,t:"Sure, I'll send you a message now.",ar:"بالتأكيد، سأرسل لك رسالة الآن."},{s:1,t:"Perfect. And don't worry, I'll be there.",ar:"ممتاز. ولا تقلق، سأكون هناك."},{s:0,t:"I know. See you on Saturday!",ar:"أعلم. أراك يوم السبت!"},{s:1,t:"See you! And happy birthday again!",ar:"أراك! وعيد ميلاد سعيد مرة أخرى!"},{s:0,t:"Thanks! Bye!",ar:"شكرًا! إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:8,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"إلى المحطة والبحر",grammar:{id:"en-do-does",title:"do / does auxiliary",titleAr:"do/does كفعل مساعد",covers:1},conv:{id:"en-stage8",speakers:["Driver (السائق)","Passenger (الراكب)"],turns:[{s:1,t:"Hello! To the station, please.",ar:"مرحبًا! إلى المحطة، من فضلك."},{s:0,t:"Sure. Get in. Which station?",ar:"بالتأكيد. اصعد. أي محطة؟"},{s:1,t:"The train station. I have a train at ten.",ar:"محطة القطار. لدي قطار في العاشرة."},{s:0,t:"OK. It's not far. About ten minutes.",ar:"حسنًا. ليست بعيدة. حوالي عشر دقائق."},{s:1,t:"Good. Is there a lot of traffic today?",ar:"جيد. هل توجد حركة مرور كثيفة اليوم؟"},{s:0,t:"A little. There's a big truck on the road.",ar:"قليلًا. توجد شاحنة كبيرة على الطريق."},{s:1,t:"Oh no. Will I be late?",ar:"أوه لا. هل سأتأخر؟"},{s:0,t:"No, don't worry. We'll go a different way.",ar:"لا، لا تقلق. سنسلك طريقًا مختلفًا."},{s:1,t:"Thanks. Turn left here, or go straight?",ar:"شكرًا. انعطف يسارًا هنا، أم اذهب مباشرة؟"},{s:0,t:"Go straight, then turn right at the bank.",ar:"اذهب مباشرة، ثم انعطف يمينًا عند المصرف."},{s:1,t:"I see. Is the station near the center?",ar:"فهمت. هل المحطة قريبة من المركز؟"},{s:0,t:"Yeah, it's in the center of town.",ar:"نعم، إنها في وسط المدينة."},{s:1,t:"Perfect. Where are you going after this?",ar:"ممتاز. إلى أين ستذهب بعد هذا؟"},{s:0,t:"To the airport. A tourist needs a ride.",ar:"إلى المطار. سائح يحتاج إلى توصيلة."},{s:1,t:"The airport is far, isn't it?",ar:"المطار بعيد، أليس كذلك؟"},{s:0,t:"Yeah, about thirty miles. It takes an hour.",ar:"نعم، حوالي ثلاثين ميلًا. يستغرق ساعة."},{s:1,t:"Wow. Do you like driving all day?",ar:"واو. هل تحب القيادة طوال اليوم؟"},{s:0,t:"Mostly, yes. I meet a lot of people.",ar:"في الغالب، نعم. أقابل الكثير من الناس."},{s:1,t:"That's nice. I travel by train a lot.",ar:"هذا جميل. أسافر بالقطار كثيرًا."},{s:0,t:"Where are you going today? On vacation?",ar:"إلى أين تذهب اليوم؟ في إجازة؟"},{s:1,t:"Yes! To the sea. To a small island.",ar:"نعم! إلى البحر. إلى جزيرة صغيرة."},{s:0,t:"An island? That sounds wonderful.",ar:"جزيرة؟ هذا يبدو رائعًا."},{s:1,t:"Yeah. My friend lives there, near the ocean.",ar:"نعم. صديقي يعيش هناك، قرب المحيط."},{s:0,t:"Lucky you! How long is the trip?",ar:"يا لك من محظوظ! كم تستغرق الرحلة؟"},{s:1,t:"The train takes two hours, then a boat.",ar:"القطار يستغرق ساعتين، ثم قارب."},{s:0,t:"A boat! Do you like boats?",ar:"قارب! هل تحب القوارب؟"},{s:1,t:"I love them. The sea is so blue and calm.",ar:"أحبها. البحر أزرق وهادئ جدًا."},{s:0,t:"Nice. Don't forget your passport and ticket!",ar:"جميل. لا تنسَ جواز سفرك وتذكرتك!"},{s:1,t:"I have them right here, in my bag.",ar:"لديهما هنا، في حقيبتي."},{s:0,t:"Good. Here we are — the station!",ar:"جيد. ها نحن — المحطة!"},{s:1,t:"Great! How much is the ride?",ar:"رائع! كم تكلفة الرحلة؟"},{s:0,t:"Eight dollars, please.",ar:"ثمانية دولارات، من فضلك."},{s:1,t:"Here you are. Keep the change.",ar:"تفضل. احتفظ بالباقي."},{s:0,t:"Thank you! Have a great vacation!",ar:"شكرًا لك! أتمنى لك إجازة رائعة!"},{s:1,t:"Thanks! Bye!",ar:"شكرًا! إلى اللقاء!"},{s:0,t:"Bye! And enjoy the island!",ar:"إلى اللقاء! واستمتع بالجزيرة!"},{s:1,t:"I will!",ar:"سأفعل!"}]}},{stage:9,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"مريض وعند الطبيب",grammar:{id:"en-have-has",title:"have / has and have got",titleAr:"have/has و have got للملكية",covers:1},conv:{id:"en-stage9",speakers:["Doctor (الطبيب)","Patient (المريض)"],turns:[{s:1,t:"Hello! I need a doctor.",ar:"مرحبًا! أحتاج إلى طبيب."},{s:0,t:"Hello. Come in and sit down. What's wrong?",ar:"مرحبًا. ادخل واجلس. ما المشكلة؟"},{s:1,t:"I have a bad headache and a fever.",ar:"لدي صداع شديد وحمى."},{s:0,t:"I see. How long have you had it?",ar:"فهمت. منذ متى وأنت تعاني منه؟"},{s:1,t:"Since yesterday. I feel terrible.",ar:"منذ الأمس. أشعر بالسوء."},{s:0,t:"Do you have a cough too?",ar:"هل لديك سعال أيضًا؟"},{s:1,t:"Yeah, a little. And my throat hurts.",ar:"نعم، قليلًا. وحلقي يؤلمني."},{s:0,t:"Open your mouth, please. Say ah.",ar:"افتح فمك، من فضلك. قل آه."},{s:1,t:"Ah.",ar:"آه."},{s:0,t:"Your throat is red. Do you have a cold?",ar:"حلقك أحمر. هل لديك نزلة برد؟"},{s:1,t:"I think so. I was in the rain on Monday.",ar:"أظن ذلك. كنت تحت المطر يوم الاثنين."},{s:0,t:"That explains it. Do your arms or legs hurt?",ar:"هذا يفسر الأمر. هل تؤلمك ذراعاك أو ساقاك؟"},{s:1,t:"My legs are OK, but my head hurts a lot.",ar:"ساقاي بخير، لكن رأسي يؤلمني كثيرًا."},{s:0,t:"Let me check your eyes and ears.",ar:"دعني أفحص عينيك وأذنيك."},{s:1,t:"OK. Is it serious, doctor?",ar:"حسنًا. هل الأمر خطير، يا دكتور؟"},{s:0,t:"No, don't worry. It's just a cold.",ar:"لا، لا تقلق. إنها مجرد نزلة برد."},{s:1,t:"Phew. That's good news.",ar:"أوه. هذه أخبار جيدة."},{s:0,t:"But you need to rest. Stay in bed for two days.",ar:"لكنك تحتاج إلى الراحة. ابقَ في الفراش لمدة يومين."},{s:1,t:"Two days? I have work tomorrow.",ar:"يومان؟ لدي عمل غدًا."},{s:0,t:"No work. Your body needs to rest.",ar:"لا عمل. جسمك يحتاج إلى الراحة."},{s:1,t:"OK, doctor. What medicine do I need?",ar:"حسنًا، يا دكتور. ما الدواء الذي أحتاجه؟"},{s:0,t:"Take these pills twice a day, after food.",ar:"خذ هذه الحبوب مرتين في اليوم، بعد الطعام."},{s:1,t:"Twice a day. Got it. And water?",ar:"مرتين في اليوم. فهمت. والماء؟"},{s:0,t:"Drink a lot of water and hot tea.",ar:"اشرب الكثير من الماء والشاي الساخن."},{s:1,t:"Should I eat anything special?",ar:"هل يجب أن آكل شيئًا خاصًا؟"},{s:0,t:"Eat soup and fruit. No cold drinks.",ar:"كُل الحساء والفاكهة. لا مشروبات باردة."},{s:1,t:"OK. No ice cream, then?",ar:"حسنًا. لا آيس كريم إذن؟"},{s:0,t:"Ha! No ice cream for now.",ar:"ها! لا آيس كريم في الوقت الحالي."},{s:1,t:"That's sad. I love ice cream.",ar:"هذا محزن. أحب الآيس كريم."},{s:0,t:"You can have it when you feel better.",ar:"يمكنك تناوله عندما تشعر بتحسن."},{s:1,t:"Deal. When should I come back?",ar:"اتفقنا. متى يجب أن أعود؟"},{s:0,t:"Come back on Friday if you still feel sick.",ar:"عُد يوم الجمعة إذا كنت ما زلت تشعر بالمرض."},{s:1,t:"OK. How much do I pay?",ar:"حسنًا. كم يجب أن أدفع؟"},{s:0,t:"Twenty dollars. Pay at the desk, please.",ar:"عشرون دولارًا. ادفع عند المكتب، من فضلك."},{s:1,t:"Thank you, doctor. Goodbye!",ar:"شكرًا لك، يا دكتور. إلى اللقاء!"},{s:0,t:"Get well soon! And drink your tea!",ar:"أتمنى لك الشفاء العاجل! واشرب شايك!"},{s:1,t:"I will. Bye!",ar:"سأفعل. إلى اللقاء!"}]}},{stage:10,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"عطلة نهاية الأسبوع: رياضة وموسيقى",grammar:{id:"en-habits",title:"Present simple for habits",titleAr:"المضارع للعادات",covers:1},conv:{id:"en-stage10",speakers:["Player (اللاعب)","Friend (الصديق)"],turns:[{s:0,t:"What do you do at the weekend?",ar:"ماذا تفعل في عطلة نهاية الأسبوع؟"},{s:1,t:"I usually play football with my friends.",ar:"ألعب كرة القدم عادة مع أصدقائي."},{s:0,t:"Really? What position do you play?",ar:"حقًا؟ في أي مركز تلعب؟"},{s:1,t:"I play in the front. I like to score goals.",ar:"ألعب في الهجوم. أحب تسجيل الأهداف."},{s:0,t:"Ha! Are you good at it?",ar:"ها! هل أنت جيد في ذلك؟"},{s:1,t:"Pretty good. Last week I scored two goals.",ar:"جيد جدًا. الأسبوع الماضي سجلت هدفين."},{s:0,t:"Wow! That's fantastic. When do you play?",ar:"واو! هذا رائع. متى تلعب؟"},{s:1,t:"Every Saturday morning, at the park.",ar:"كل صباح سبت، في الحديقة."},{s:0,t:"And what do you do on Sunday?",ar:"وماذا تفعل يوم الأحد؟"},{s:1,t:"On Sunday I play the guitar and sing.",ar:"يوم الأحد أعزف على الغيتار وأغني."},{s:0,t:"Oh, you sing too? What kind of music?",ar:"أوه، أنت تغني أيضًا؟ أي نوع من الموسيقى؟"},{s:1,t:"I like pop music. And sometimes I listen to jazz.",ar:"أحب موسيقى البوب. وأحيانًا أستمع إلى الجاز."},{s:0,t:"Cool. Do you play in a band?",ar:"رائع. هل تعزف في فرقة؟"},{s:1,t:"Yeah, a small band. We practice twice a week.",ar:"نعم، فرقة صغيرة. نتدرب مرتين في الأسبوع."},{s:0,t:"That's amazing. Where do you practice?",ar:"هذا مذهل. أين تتدربون؟"},{s:1,t:"At my friend's house. He has a big room.",ar:"في بيت صديقي. لديه غرفة كبيرة."},{s:0,t:"Nice. Do you watch sports on TV too?",ar:"جميل. هل تشاهد الرياضة على التلفاز أيضًا؟"},{s:1,t:"Yeah, I watch basketball every Friday night.",ar:"نعم، أشاهد كرة السلة كل ليلة جمعة."},{s:0,t:"Basketball! I prefer tennis, to be honest.",ar:"كرة السلة! أنا أفضل التنس، بصراحة."},{s:1,t:"Tennis is great too. Do you play it?",ar:"التنس رائع أيضًا. هل تلعبه؟"},{s:0,t:"Sometimes. I'm not very good, but it's fun.",ar:"أحيانًا. لست جيدًا جدًا، لكنه ممتع."},{s:1,t:"Ha! The important thing is to have fun.",ar:"ها! المهم هو أن تستمتع."},{s:0,t:"True. Do you go to the gym too?",ar:"صحيح. هل تذهب إلى النادي الرياضي أيضًا؟"},{s:1,t:"Yeah, three times a week. I run and swim.",ar:"نعم، ثلاث مرات في الأسبوع. أركض وأسبح."},{s:0,t:"You swim? I love swimming in summer.",ar:"أنت تسبح؟ أحب السباحة في الصيف."},{s:1,t:"Me too. The pool near my house is great.",ar:"وأنا كذلك. المسبح قرب بيتي رائع."},{s:0,t:"What about books? Do you like to read?",ar:"وماذا عن الكتب؟ هل تحب القراءة؟"},{s:1,t:"Yeah, I read a lot. I love stories about animals.",ar:"نعم، أقرأ كثيرًا. أحب القصص عن الحيوانات."},{s:0,t:"Animals? Like lions and elephants?",ar:"الحيوانات؟ مثل الأسود والفيلة؟"},{s:1,t:"Yeah! And horses. I rode a horse once, on a farm.",ar:"نعم! والخيول. ركبت حصانًا مرة، في مزرعة."},{s:0,t:"No way! Was it scary?",ar:"مستحيل! هل كان مخيفًا؟"},{s:1,t:"A little. But the farmer helped me.",ar:"قليلًا. لكن المزارع ساعدني."},{s:0,t:"Did you see cows and sheep there too?",ar:"هل رأيت أبقارًا وأغنامًا هناك أيضًا؟"},{s:1,t:"Yeah, and a pig and a dog. It was so much fun.",ar:"نعم، وخنزيرًا وكلبًا. كان ممتعًا جدًا."},{s:0,t:"Ha! I want to go to a farm one day.",ar:"ها! أريد الذهاب إلى مزرعة يومًا ما."},{s:1,t:"Let's go together in spring. It'll be great.",ar:"لنذهب معًا في الربيع. سيكون رائعًا."},{s:0,t:"Deal! So, football on Saturday?",ar:"اتفقنا! إذن، كرة القدم يوم السبت؟"},{s:1,t:"Yeah. At nine. Don't be late!",ar:"نعم. في التاسعة. لا تتأخر!"},{s:0,t:"I won't. See you then!",ar:"لن أتأخر. أراك حينها!"},{s:1,t:"See you!",ar:"أراك!"}]}},{stage:11,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"حديث عن المهن في المدرسة",grammar:{id:"en-a-an-the",title:"a / an / the",titleAr:"أدوات التعريف والتنكير",covers:1},conv:{id:"en-stage11",speakers:["Teacher (المعلم)","Cook (الطباخ)"],turns:[{s:0,t:"Good morning! What do you do?",ar:"صباح الخير! ماذا تعمل؟"},{s:1,t:"Good morning! I'm a cook. I work in a restaurant.",ar:"صباح الخير! أنا طباخ. أعمل في مطعم."},{s:0,t:"A cook! That's a great job.",ar:"طباخ! هذه وظيفة رائعة."},{s:1,t:"Thanks! I love it. And you? Are you a teacher?",ar:"شكرًا! أحبها. وأنت؟ هل أنت معلم؟"},{s:0,t:"Yes, I am. I teach at the school near here.",ar:"نعم، أنا كذلك. أدرّس في المدرسة القريبة من هنا."},{s:1,t:"Nice. What do you teach?",ar:"جميل. ماذا تدرّس؟"},{s:0,t:"English and art. The students are great.",ar:"الإنجليزية والفن. الطلاب رائعون."},{s:1,t:"Art! Can you draw and paint?",ar:"الفن! هل يمكنك الرسم والتلوين؟"},{s:0,t:"Yeah, a little. I like to paint pictures.",ar:"نعم، قليلًا. أحب رسم اللوحات."},{s:1,t:"That's a nice skill. When do you work?",ar:"هذه مهارة جميلة. متى تعمل؟"},{s:0,t:"From Monday to Friday, from eight to three.",ar:"من الاثنين إلى الجمعة، من الثامنة إلى الثالثة."},{s:1,t:"And I work from Tuesday to Sunday. It's hard.",ar:"وأنا أعمل من الثلاثاء إلى الأحد. إنه عمل شاق."},{s:0,t:"Sunday too? That's a long week.",ar:"الأحد أيضًا؟ هذا أسبوع طويل."},{s:1,t:"Yeah, but I love cooking. It's my life.",ar:"نعم، لكنني أحب الطبخ. إنه حياتي."},{s:0,t:"What do you cook best?",ar:"ما أفضل ما تطبخ؟"},{s:1,t:"Pizza and pasta. And fish on Friday.",ar:"البيتزا والمعكرونة. والسمك يوم الجمعة."},{s:0,t:"Yum! Do you work with a big team?",ar:"لذيذ! هل تعمل مع فريق كبير؟"},{s:1,t:"Yes, five people. Two waiters and three cooks.",ar:"نعم، خمسة أشخاص. نادلان وثلاثة طهاة."},{s:0,t:"A waiter is an important job too.",ar:"النادل وظيفة مهمة أيضًا."},{s:1,t:"True. And the driver brings our food every morning.",ar:"صحيح. والسائق يجلب طعامنا كل صباح."},{s:0,t:"What about a doctor or a nurse? Hard jobs.",ar:"وماذا عن الطبيب أو الممرضة؟ وظائف صعبة."},{s:1,t:"Very hard. My sister is a nurse at the hospital.",ar:"صعبة جدًا. أختي ممرضة في المستشفى."},{s:0,t:"Really? That's wonderful work.",ar:"حقًا؟ هذا عمل رائع."},{s:1,t:"Yeah. And my brother is a police officer.",ar:"نعم. وأخي ضابط شرطة."},{s:0,t:"Wow, your family works hard!",ar:"واو، عائلتك تعمل بجد!"},{s:1,t:"Ha! What about your family?",ar:"ها! وماذا عن عائلتك؟"},{s:0,t:"My father is a farmer. He has a big farm.",ar:"أبي مزارع. لديه مزرعة كبيرة."},{s:1,t:"A farmer! Does he grow vegetables?",ar:"مزارع! هل يزرع الخضروات؟"},{s:0,t:"Yes, and fruit. And he has a dog and a cat.",ar:"نعم، والفاكهة. ولديه كلب وقطة."},{s:1,t:"Nice. Is your mother a teacher too?",ar:"جميل. هل أمك معلمة أيضًا؟"},{s:0,t:"No, she's a singer. She sings in a theater.",ar:"لا، إنها مغنية. تغني في مسرح."},{s:1,t:"A singer! That's fantastic.",ar:"مغنية! هذا رائع."},{s:0,t:"Yeah. So, many jobs, one family.",ar:"نعم. إذن، وظائف كثيرة، عائلة واحدة."},{s:1,t:"Ha! True. What do your students want to be?",ar:"ها! صحيح. ماذا يريد طلابك أن يصبحوا؟"},{s:0,t:"Some want to be doctors. Some want to be actors.",ar:"بعضهم يريد أن يصبح طبيبًا. وبعضهم يريد أن يصبح ممثلًا."},{s:1,t:"Actors and actresses! That's fun.",ar:"ممثلون وممثلات! هذا ممتع."},{s:0,t:"Yeah. And one girl wants to be a scientist.",ar:"نعم. وفتاة واحدة تريد أن تصبح عالمة."},{s:1,t:"A scientist! The future is bright.",ar:"عالمة! المستقبل مشرق."},{s:0,t:"I hope so. OK, I have to go now. Class starts.",ar:"أتمنى ذلك. حسنًا، عليّ الذهاب الآن. يبدأ الدرس."},{s:1,t:"Me too. The restaurant opens at eleven.",ar:"وأنا كذلك. يفتح المطعم في الحادية عشرة."},{s:0,t:"See you soon! And good luck at work!",ar:"أراك قريبًا! وحظًا سعيدًا في العمل!"},{s:1,t:"You too! Bye!",ar:"وأنت أيضًا! إلى اللقاء!"}]}},{stage:12,topic:"services",topicAr:"الخدمات والطوارئ",topicEn:"Services & Emergencies",topicDe:"Dienstleistungen und Notfälle",emoji:"🏦",title:"مشاوير في المدينة",grammar:{id:"en-can",title:"can for polite requests",titleAr:"can للطلب بأدب",covers:1},conv:{id:"en-stage12",speakers:["Customer (الزبون)","Friend (الصديق)"],turns:[{s:1,t:"Good morning! Where do we go first?",ar:"صباح الخير! إلى أين نذهب أولًا؟"},{s:0,t:"Good morning! First, to the bank, please.",ar:"صباح الخير! أولًا، إلى المصرف، من فضلك."},{s:1,t:"The bank? Can I come with you?",ar:"إلى المصرف؟ هل يمكنني المجيء معك؟"},{s:0,t:"Of course. I need to get some money.",ar:"بالطبع. أحتاج إلى سحب بعض المال."},{s:1,t:"How much money do you need?",ar:"كم من المال تحتاج؟"},{s:0,t:"About a hundred dollars. For the week.",ar:"حوالي مئة دولار. للأسبوع."},{s:1,t:"OK. Is the bank far from here?",ar:"حسنًا. هل المصرف بعيد من هنا؟"},{s:0,t:"No, it's next to the supermarket.",ar:"لا، إنه بجانب السوبرماركت."},{s:1,t:"Great. And after the bank?",ar:"رائع. وبعد المصرف؟"},{s:0,t:"To the post office. I have to send a letter.",ar:"إلى مكتب البريد. عليّ إرسال رسالة."},{s:1,t:"A letter? Who do you write to?",ar:"رسالة؟ لمن تكتب؟"},{s:0,t:"To my uncle. He lives in another country.",ar:"إلى عمي. يعيش في بلد آخر."},{s:1,t:"Oh, nice. Do you send it by air mail?",ar:"أوه، جميل. هل ترسلها بالبريد الجوي؟"},{s:0,t:"Yeah. It takes a week, more or less.",ar:"نعم. تستغرق أسبوعًا، تقريبًا."},{s:1,t:"And then? Where next?",ar:"وبعد ذلك؟ إلى أين بعدها؟"},{s:0,t:"To the library. I need a book for school.",ar:"إلى المكتبة. أحتاج كتابًا للمدرسة."},{s:1,t:"What book? A story book?",ar:"أي كتاب؟ كتاب قصص؟"},{s:0,t:"No, a dictionary. My old one is very old.",ar:"لا، قاموس. قاموسي القديم قديم جدًا."},{s:1,t:"Ha! A dictionary is very useful.",ar:"ها! القاموس مفيد جدًا."},{s:0,t:"Yeah. And I want a newspaper too.",ar:"نعم. وأريد صحيفة أيضًا."},{s:1,t:"You read the news every day?",ar:"هل تقرأ الأخبار كل يوم؟"},{s:0,t:"Almost every day. I like to know what's happening.",ar:"تقريبًا كل يوم. أحب أن أعرف ما يحدث."},{s:1,t:"Me too. I read the news on my phone.",ar:"وأنا كذلك. أقرأ الأخبار على هاتفي."},{s:0,t:"Same. Oh, and I need to go to the pharmacy.",ar:"وأنا كذلك. أوه، وأحتاج إلى الذهاب إلى الصيدلية."},{s:1,t:"The pharmacy? Are you sick?",ar:"إلى الصيدلية؟ هل أنت مريض؟"},{s:0,t:"No, no. Just some medicine for my mom.",ar:"لا، لا. فقط بعض الدواء لأمي."},{s:1,t:"I see. Is your mom OK?",ar:"فهمت. هل أمك بخير؟"},{s:0,t:"Yeah, she's fine. Just a small cold.",ar:"نعم، هي بخير. مجرد نزلة برد صغيرة."},{s:1,t:"Good. Can we stop at the market too?",ar:"جيد. هل يمكننا التوقف عند السوق أيضًا؟"},{s:0,t:"Sure. What do you need there?",ar:"بالتأكيد. ماذا تحتاج هناك؟"},{s:1,t:"Some vegetables. And maybe a magazine.",ar:"بعض الخضروات. وربما مجلة."},{s:0,t:"A magazine? Which one?",ar:"مجلة؟ أي واحدة؟"},{s:1,t:"A sports magazine. I love football.",ar:"مجلة رياضية. أحب كرة القدم."},{s:0,t:"Ha! OK. Let's go, then. It's already nine.",ar:"ها! حسنًا. لنذهب إذن. إنها التاسعة بالفعل."},{s:1,t:"Wait — do we have time for a coffee?",ar:"انتظر — هل لدينا وقت لقهوة؟"},{s:0,t:"Yeah, after the bank. There's a cafe near it.",ar:"نعم، بعد المصرف. توجد مقهى قربه."},{s:1,t:"Perfect. Let's go!",ar:"ممتاز. لنذهب!"},{s:0,t:"Let's go!",ar:"لنذهب!"}]}},{stage:13,topic:"street",topicAr:"كلام الشارع",topicEn:"Street Talk",topicDe:"Street Talk",emoji:"",title:"كاد أن يصدمني!",grammar:{id:"en-imperatives",title:"Imperatives",titleAr:"الأمر Imperatives",covers:1},conv:{id:"en-stage13",speakers:["Driver (السائق)","Pedestrian (الماشي)"],turns:[{s:0,t:"Hey! Watch it! I almost hit you!",ar:"مهلًا! انتبه! كدت أن أصدمك!"},{s:1,t:"Almost? You were driving way too fast!",ar:"كدت؟ كنت تقود بسرعة كبيرة جدًا!"},{s:0,t:"I was not fast. You just walked into the street without looking.",ar:"لم أكن مسرعًا. أنت من مشيت في الشارع دون أن تنظر."},{s:1,t:"I looked! You came out of nowhere, man.",ar:"نظرت! ظهرت من العدم يا رجل."},{s:0,t:"Damn. Okay, okay. Are you hurt?",ar:"تبًا. حسنًا، حسنًا. هل تأذيت؟"},{s:1,t:"No, I'm fine. But my heart is beating so fast.",ar:"لا، أنا بخير. لكن قلبي يخفق بسرعة كبيرة."},{s:0,t:"I'm sorry. I was in a hurry, and I didn't see you in time.",ar:"أنا آسف. كنت مستعجلًا، ولم أرك في الوقت المناسب."},{s:1,t:"Well, slow down next time. This is a street, not a race track.",ar:"حسنًا، تمهّل في المرة القادمة. هذا شارع، وليس مضمار سباق."},{s:0,t:"You're right. Shit, that was close.",ar:"أنت محق. اللعنة، كان ذلك وشيكًا جدًا."},{s:1,t:"Yeah, it was. Just be careful, okay?",ar:"نعم، كان كذلك. فقط كن حذرًا، حسنًا؟"},{s:0,t:"I will. Take care, man. Sorry again.",ar:"سأكون حذرًا. اعتنِ بنفسك يا رجل. آسف مرة أخرى."},{s:1,t:"It's okay. Drive safe.",ar:"لا بأس. قُد بأمان."}]}}],de:[{stage:1,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"التعارف مع جار جديد",grammar:{id:"de-der-die-das",title:"der / die / das",titleAr:"أدوات التعريف der/die/das",covers:1},conv:{id:"de-stage1",speakers:["Nachbar (الجار)","Neuer Nachbar (الجار الجديد)"],turns:[{s:0,t:"Hallo! Willkommen in unserer Straße.",ar:"مرحبًا! أهلًا بك في شارعنا."},{s:1,t:"Vielen Dank! Ich bin glücklich.",ar:"شكرًا جزيلًا! أنا سعيد."},{s:0,t:"Wie heißt du, bitte?",ar:"ما اسمك، من فضلك؟"},{s:1,t:"Ich bin dein neuer Nachbar aus Berlin.",ar:"أنا جارك الجديد من برلين."},{s:0,t:"Woher kommst du ursprünglich?",ar:"من أين أنت أصلًا؟"},{s:1,t:"Ich komme aus Syrien, aus Damaskus.",ar:"أنا من سوريا، من دمشق."},{s:0,t:"Wie lange wohnst du schon hier?",ar:"منذ متى تسكن هنا؟"},{s:1,t:"Erst zwei Wochen, im roten Haus.",ar:"أسبوعان فقط، في البيت الأحمر."},{s:0,t:"Wohnst du hier allein?",ar:"هل تسكن هنا وحدك؟"},{s:1,t:"Nein, mit meiner Familie und unserem Hund.",ar:"لا، مع عائلتي وكلبنا."},{s:0,t:"Wie viele Kinder hast du?",ar:"كم طفلًا لديك؟"},{s:1,t:"Zwei Kinder, einen Sohn und eine Tochter.",ar:"طفلان، ابن وابنة."},{s:0,t:"Wie alt sind deine Kinder?",ar:"كم عمر أطفالك؟"},{s:1,t:"Mein Sohn ist acht, meine Tochter ist fünf.",ar:"ابني عمره ثماني سنوات، وابنتي خمس."},{s:0,t:"Gehen sie hier zur Schule?",ar:"هل يذهبون إلى المدرسة هنا؟"},{s:1,t:"Ja, in der Schule beim Park.",ar:"نعم، في المدرسة قرب الحديقة."},{s:0,t:"Meine Kinder gehen auch dorthin!",ar:"أطفالي يذهبون هناك أيضًا!"},{s:1,t:"Wunderbar! Sie können zusammen spielen.",ar:"رائع! يستطيعون اللعب معًا."},{s:0,t:"Welche Sprachen sprichst du?",ar:"ما اللغات التي تتحدثها؟"},{s:1,t:"Arabisch und ein bisschen Deutsch.",ar:"العربية وقليل من الألمانية."},{s:0,t:"Sprichst du auch Englisch?",ar:"هل تتحدث الإنجليزية أيضًا؟"},{s:1,t:"Ja, ein bisschen Englisch bei der Arbeit.",ar:"نعم، قليل من الإنجليزية في العمل."},{s:0,t:"Was ist dein Beruf?",ar:"ما عملك؟"},{s:1,t:"Ich bin Lehrer, ich unterrichte Kinder.",ar:"أنا معلم، أُعلّم الأطفال."},{s:0,t:"Ich arbeite in einem kleinen Geschäft.",ar:"أنا أعمل في متجر صغير."},{s:1,t:"Was machst du gern in der Freizeit?",ar:"ماذا تحب في وقت الفراغ؟"},{s:0,t:"Ich mag Fußball und gute Bücher.",ar:"أحب كرة القدم والكتب الجيدة."},{s:1,t:"Ich mag Musik und lange Spaziergänge.",ar:"أحب الموسيقى والمشي الطويل."},{s:0,t:"Spielst du am Sonntag Fußball?",ar:"هل تلعب كرة القدم يوم الأحد؟"},{s:1,t:"Ja, im Park mit Freunden.",ar:"نعم، في الحديقة مع الأصدقاء."},{s:0,t:"Kann ich deine Nummer haben?",ar:"هل أستطيع أخذ رقم هاتفك؟"},{s:1,t:"Ja! Ich schreibe sie hier für dich.",ar:"نعم! سأكتبها هنا لك."},{s:0,t:"Danke! Trinken wir morgen Kaffee?",ar:"شكرًا! هل نشرب القهوة غدًا؟"},{s:1,t:"Ja, um zehn Uhr morgens.",ar:"نعم، في العاشرة صباحًا."},{s:0,t:"Bei mir, in der Nähe des Parks?",ar:"عندي في البيت، قرب الحديقة؟"},{s:1,t:"Perfekt! Ich bringe einen Kuchen mit.",ar:"ممتاز! سأحضر كعكة."},{s:0,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:1,t:"Ich bringe morgen früh einen Kuchen mit.",ar:"سأحضر كعكة صباح الغد."},{s:0,t:"Super! Meine Familie liebt Kuchen.",ar:"رائع! عائلتي تحب الكعك."},{s:1,t:"Meine Tochter hat im Mai Geburtstag.",ar:"ابنتي عيد ميلادها في أيار."},{s:0,t:"Wie alt wird sie dann?",ar:"كم سيكون عمرها حينها؟"},{s:1,t:"Sie wird dann sechs Jahre alt.",ar:"سيكون عمرها ست سنوات حينها."},{s:0,t:"Wir feiern mit einer großen Party!",ar:"سنحتفل بحفلة كبيرة!"},{s:1,t:"Wunderbar! Wir sehen uns morgen wieder.",ar:"رائع! سنلتقي مجددًا غدًا."},{s:0,t:"Nochmals willkommen! Bis morgen!",ar:"أهلًا بك مجددًا! أراك غدًا!"},{s:1,t:"Danke! Tschüss, mein neuer Freund!",ar:"شكرًا! إلى اللقاء، يا صديقي الجديد!"}]}},{stage:2,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"في السوق والمقهى",grammar:{id:"de-modalverben",title:"Modalverben",titleAr:"الأفعال المساعدة Modalverben",covers:3},conv:{id:"de-stage2",speakers:["Verkäufer (البائع)","Kunde (الزبون)"],turns:[{s:1,t:"Guten Morgen! Was ist heute frisch?",ar:"صباح الخير! ما الطازج اليوم؟"},{s:0,t:"Guten Morgen! Alles ist heute frisch.",ar:"صباح الخير! كل شيء طازج اليوم."},{s:1,t:"Ich brauche zuerst Essen für das Frühstück.",ar:"أحتاج طعامًا للفطور أولًا."},{s:0,t:"Brot, Käse, Eier und Milch?",ar:"خبز وجبن وبيض وحليب؟"},{s:1,t:"Ja, und Honig und Orangensaft.",ar:"نعم، وعسل وعصير برتقال."},{s:0,t:"Hier ist warmes Brot vom Bauernhof.",ar:"هذا خبز دافئ من المزرعة."},{s:1,t:"Wie viel kostet das Brot, bitte?",ar:"كم سعر الخبز، من فضلك؟"},{s:0,t:"Zwei Euro, heute sehr günstig.",ar:"يوروان، رخيص جدًا اليوم."},{s:1,t:"Gut! Ich nehme zwei Brote, bitte.",ar:"جيد! سآخذ خبزين، من فضلك."},{s:0,t:"Welches Gemüse brauchst du?",ar:"ما الخضار التي تحتاجها؟"},{s:1,t:"Tomaten, Kartoffeln und Karotten, bitte.",ar:"طماطم وبطاطا وجزر، من فضلك."},{s:0,t:"Für Suppe oder für Salat?",ar:"للحساء أم للسلطة؟"},{s:1,t:"Für Suppe heute Abend, mit meiner Oma.",ar:"لحساء الليلة، مع جدتي."},{s:0,t:"Eine gute Suppe braucht frisches Gemüse.",ar:"الحساء الجيد يحتاج خضارًا طازجة."},{s:1,t:"Und Obst für ein Picknick morgen.",ar:"وفواكه لنزهة غدًا."},{s:0,t:"Äpfel, Bananen oder Orangen?",ar:"تفاح أم موز أم برتقال؟"},{s:1,t:"Rote Äpfel, bitte. Ich liebe Äpfel.",ar:"تفاح أحمر، من فضلك. أحب التفاح."},{s:0,t:"Wie viele Äpfel möchtest du?",ar:"كم تفاحة تريد؟"},{s:1,t:"Sechs Äpfel, für Kuchen und Picknick.",ar:"ست تفاحات، للكعك والنزهة."},{s:0,t:"Wir backen Apfelkuchen am Sonntag.",ar:"نحن نخبز كعكة تفاح يوم الأحد."},{s:1,t:"Mit Mehl, Wasser und Äpfeln?",ar:"بالطحين والماء والتفاح؟"},{s:0,t:"Ja, und Zucker und warme Milch.",ar:"نعم، وسكر وحليب دافئ."},{s:1,t:"Wie viel kostet alles zusammen?",ar:"كم سعر كل شيء معًا؟"},{s:0,t:"Zwanzig Euro, bitte. Bar oder Karte?",ar:"عشرون يورو، من فضلك. نقدًا أم بطاقة؟"},{s:1,t:"Das ist teuer. Geht es günstiger?",ar:"هذا غالٍ. هل يوجد أرخص؟"},{s:0,t:"Achtzehn Euro, ein guter Preis.",ar:"ثمانية عشر يورو، سعر جيد."},{s:1,t:"Gut, ich nehme es. Hier sind zwanzig.",ar:"جيد، سآخذه. هذه عشرون."},{s:0,t:"Zwei Euro zurück. Danke!",ar:"يوروان باقي. شكرًا!"},{s:1,t:"Entschuldigung, kannst du den Preis wiederholen?",ar:"عذرًا، هل تستطيع تكرار السعر؟"},{s:0,t:"Achtzehn Euro, mit zwei Euro zurück.",ar:"ثمانية عشر يورو، مع يوروان باقي."},{s:1,t:"Perfekt! Und jetzt einen Kaffee, bitte?",ar:"ممتاز! وقهوة الآن، من فضلك؟"},{s:0,t:"Kleiner oder großer Kaffee heute?",ar:"قهوة صغيرة أم كبيرة اليوم؟"},{s:1,t:"Groß, bitte. Mit heißer Milch.",ar:"كبيرة، من فضلك. مع حليب ساخن."},{s:0,t:"Und auch ein Stück Kuchen?",ar:"وقطعة كعك أيضًا؟"},{s:1,t:"Ja, Schokoladenkuchen, mein Favorit.",ar:"نعم، كعك شوكولاتة، المفضل عندي."},{s:0,t:"Das sind vier Euro mehr.",ar:"هذا أربعة يورو إضافية."},{s:1,t:"Bitte sehr. Der Kuchen ist lecker!",ar:"تفضل. الكعك لذيذ!"},{s:0,t:"Kochst du zu Hause Abendessen?",ar:"هل تطبخ العشاء في البيت؟"},{s:1,t:"Ja, Fisch und Reis am Freitag.",ar:"نعم، سمك وأرز يوم الجمعة."},{s:0,t:"Und am Samstag im Restaurant?",ar:"وفي المطعم يوم السبت؟"},{s:1,t:"Ja, mit meinem Vater, Suppe und Fisch.",ar:"نعم، مع أبي، حساء وسمك."},{s:0,t:"Das kleine Restaurant beim Park?",ar:"المطعم الصغير قرب الحديقة؟"},{s:1,t:"Ja! Der Kellner ist sehr freundlich.",ar:"نعم! النادل لطيف جدًا."},{s:0,t:"Komm am Sonntagmorgen wieder!",ar:"تعال مجددًا صباح الأحد!"},{s:1,t:"Ich komme mit meiner ganzen Familie!",ar:"سآتي مع عائلتي كلها!"},{s:0,t:"Wunderbar! Einen schönen Tag!",ar:"رائع! يومًا سعيدًا!"}]}},{stage:3,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"زيارة بيت جديد",grammar:{id:"de-separable",title:"Trennbare Verben",titleAr:"الأفعال المنفصلة",covers:2},conv:{id:"de-stage3",speakers:["Gastgeber (المضيف)","Gast (الضيف)"],turns:[{s:0,t:"Willkommen in meinem kleinen Haus!",ar:"أهلًا بك في بيتي الصغير!"},{s:1,t:"Danke! Es ist sehr schön!",ar:"شكرًا! إنه جميل جدًا!"},{s:0,t:"Komm herein! Das ist das Wohnzimmer.",ar:"تفضل بالدخول! هذه غرفة الجلوس."},{s:1,t:"Wie viele Zimmer hast du?",ar:"كم غرفة لديك؟"},{s:0,t:"Vier Zimmer und ein kleiner Garten.",ar:"أربع غرف وحديقة صغيرة."},{s:1,t:"Zeig mir bitte die Küche!",ar:"أرني المطبخ، من فضلك!"},{s:0,t:"Die Küche ist warm und groß.",ar:"المطبخ دافئ وكبير."},{s:1,t:"Eine Katze! Ist das deine Katze?",ar:"قطة! هل هذه قطتك؟"},{s:0,t:"Ja, sie kommt jeden Morgen.",ar:"نعم، تأتي كل صباح."},{s:1,t:"Wir geben ihr Milch und Fisch.",ar:"نعطيها حليبًا وسمكًا."},{s:0,t:"Mein blaues Zimmer ist oben.",ar:"غرفتي الزرقاء في الأعلى."},{s:1,t:"Und wo ist das Bad?",ar:"وأين الحمام؟"},{s:0,t:"Neben meinem Zimmer, rechts.",ar:"بجانب غرفتي، على اليمين."},{s:1,t:"Der Garten ist grün und ruhig.",ar:"الحديقة خضراء وهادئة."},{s:0,t:"Wir pflanzen Samen und gießen täglich.",ar:"نزرع البذور ونسقي كل يوم."},{s:1,t:"Blumen öffnen sich in der warmen Sonne.",ar:"الزهور تتفتح في الشمس الدافئة."},{s:0,t:"Samstag ist unser Putztag.",ar:"السبت هو يوم التنظيف عندنا."},{s:1,t:"Wer putzt dann die Fenster?",ar:"من ينظف النوافذ حينها؟"},{s:0,t:"Meine Schwester, und ich putze mein Zimmer.",ar:"أختي، وأنا أنظف غرفتي."},{s:1,t:"Und Mama ordnet die Bücher?",ar:"وأمي ترتب الكتب؟"},{s:0,t:"Ja, und das Haus glänzt schön.",ar:"نعم، والبيت يلمع جميلًا."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Das Haus glänzt nach dem Putztag.",ar:"البيت يلمع بعد يوم التنظيف."},{s:1,t:"Wo sind bitte die Schlüssel?",ar:"أين المفاتيح، من فضلك؟"},{s:0,t:"Unter dem Blumentopf, der Ersatzschlüssel.",ar:"تحت أصيص الزهرة، المفتاح الاحتياطي."},{s:1,t:"Gut! Ich verliere immer meine Schlüssel.",ar:"جيد! أنا أضيع مفاتيحي دائمًا."},{s:0,t:"Wir suchen unter Stühlen und Schränken.",ar:"نبحث تحت الكراسي والخزائن."},{s:1,t:"Kann ich heute Nacht hier schlafen?",ar:"هل أستطيع النوم هنا الليلة؟"},{s:0,t:"Ja, im warmen Gästezimmer.",ar:"نعم، في غرفة الضيوف الدافئة."},{s:1,t:"Liest du Geschichten vor dem Schlafen?",ar:"هل تقرأ قصصًا قبل النوم؟"},{s:0,t:"Ja, und Musik macht Putzen lustig.",ar:"نعم، والموسيقى تجعل التنظيف ممتعًا."},{s:1,t:"Wie hoch ist hier die Miete?",ar:"كم الإيجار هنا؟"},{s:0,t:"Sechshundert Euro, mit dem Garten.",ar:"ستمئة يورو، مع الحديقة."},{s:1,t:"Das ist gut für vier Zimmer.",ar:"هذا جيد لأربع غرف."},{s:0,t:"Willst du die Wohnung nebenan?",ar:"هل تريد الشقة المجاورة؟"},{s:1,t:"Ja! Sie ist nah beim Park.",ar:"نعم! إنها قرب الحديقة."},{s:0,t:"Dann besuch uns am Sonntag wieder!",ar:"إذن زرنا مجددًا يوم الأحد!"},{s:1,t:"Ich bringe Kuchen und warmes Brot mit.",ar:"سأحضر كعكًا وخبزًا دافئًا."},{s:0,t:"Perfekt! Wir essen im Garten.",ar:"ممتاز! سنأكل في الحديقة."},{s:1,t:"Danke für den schönen Besuch!",ar:"شكرًا على الزيارة الجميلة!"}]}},{stage:4,topic:"clothes",topicAr:"الملابس والتسوق",topicEn:"Clothes & Shopping",topicDe:"Kleidung und Einkaufen",emoji:"👕",title:"شراء ملابس جديدة",grammar:{id:"de-der-die-das",title:"der / die / das",titleAr:"أدوات التعريف der/die/das",covers:3},conv:{id:"de-stage4",speakers:["Verkäufer (البائع)","Kunde (الزبون)"],turns:[{s:0,t:"Hallo! Willkommen in unserem Geschäft!",ar:"مرحبًا! أهلًا بك في متجرنا!"},{s:1,t:"Hallo! Ich brauche Kleidung für den Winter.",ar:"مرحبًا! أحتاج ملابس للشتاء."},{s:0,t:"Ein Kleid, Schuhe oder ein Mantel?",ar:"فستان أم حذاء أم معطف؟"},{s:1,t:"Zuerst ein rotes Kleid, bitte.",ar:"أولًا، فستان أحمر، من فضلك."},{s:0,t:"Für eine Schulparty, richtig?",ar:"لحفلة المدرسة، صحيح؟"},{s:1,t:"Ja! Ich probiere drei Kleider an, bitte.",ar:"نعم! سأجرب ثلاثة فساتين، من فضلك."},{s:0,t:"Die Kabine ist dort drüben.",ar:"غرفة القياس هناك."},{s:1,t:"Dieses passt gut, aber es ist lang.",ar:"هذا يناسبني جيدًا، لكنه طويل."},{s:0,t:"Wir haben auch ein kürzeres Modell.",ar:"لدينا موديل أقصر أيضًا."},{s:1,t:"Perfekt! Wie viel kostet es?",ar:"ممتاز! كم سعره؟"},{s:0,t:"Dreißig Euro, reine Baumwolle.",ar:"ثلاثون يورو، قطن بجودة جيدة."},{s:1,t:"Das ist teuer. Fünfundzwanzig, bitte?",ar:"هذا غالٍ. خمسة وعشرون، من فضلك؟"},{s:0,t:"Achtundzwanzig, ein fairer Preis heute.",ar:"ثمانية وعشرون، سعر عادل اليوم."},{s:1,t:"Gut, ich nehme das rote Kleid.",ar:"جيد، سآخذ الفستان الأحمر."},{s:0,t:"Brauchst du auch neue Schuhe?",ar:"هل تحتاج حذاءً جديدًا أيضًا؟"},{s:1,t:"Ja, meine alten Schuhe sind klein.",ar:"نعم، حذائي القديم صار صغيرًا."},{s:0,t:"Blaue Laufschuhe, sehr schnell!",ar:"حذاء جري أزرق، سريع جدًا!"},{s:1,t:"Kann ich sie anprobieren, bitte?",ar:"هل أستطيع تجربتها، من فضلك؟"},{s:0,t:"Ja, welche Größe trägst du?",ar:"نعم، ما مقاسك؟"},{s:1,t:"Größe achtunddreißig, bitte. Nicht größer.",ar:"مقاس ثمانية وثلاثون، من فضلك. ليس أكبر."},{s:0,t:"Hier sind sie. Sie passen perfekt!",ar:"ها هي. تناسبك تمامًا!"},{s:1,t:"Entschuldigung, kannst du die Größe wiederholen?",ar:"عذرًا، هل تستطيع تكرار المقاس؟"},{s:0,t:"Achtunddreißig, die blauen Laufschuhe.",ar:"ثمانية وثلاثون، حذاء الجري الأزرق."},{s:1,t:"Super! Und ein gelber Sonnenhut?",ar:"رائع! وقبعة شمس صفراء؟"},{s:0,t:"Ein großer gelber Hut für den Sommer.",ar:"قبعة صفراء كبيرة للصيف."},{s:1,t:"Und ein kleiner rosa Hut, bitte.",ar:"وقبعة وردية صغيرة، من فضلك."},{s:0,t:"Für deine kleine Schwester, richtig?",ar:"لأختك الصغيرة، صحيح؟"},{s:1,t:"Ja! Sie liebt rosa Hüte.",ar:"نعم! تحب القبعات الوردية."},{s:0,t:"Probiere den roten Mantel vor dem Winter an.",ar:"جرّب المعطف الأحمر قبل الشتاء."},{s:1,t:"Er ist lang und sehr warm.",ar:"إنه طويل ودافئ جدًا."},{s:0,t:"Für Schnee nimm warme Schneestiefel.",ar:"للثلج، خذ حذاء ثلج دافئًا."},{s:1,t:"Und ein gelber Regenmantel für Regen?",ar:"ومعطف مطر أصفر للمطر؟"},{s:0,t:"Ja, und teile den Schirm gern.",ar:"نعم، وشارك المظلة بلطف."},{s:1,t:"Machst du hier bunte Mützen?",ar:"هل تصنع قبعات ملونة هنا؟"},{s:0,t:"Ja, Mützen und Handschuhe, handgemacht.",ar:"نعم، قبعات وقفازات، صناعة يدوية."},{s:1,t:"Wie viel kostet alles zusammen?",ar:"كم سعر كل شيء معًا؟"},{s:0,t:"Achtzig Euro. Bar oder Karte?",ar:"ثمانون يورو. نقدًا أم بطاقة؟"},{s:1,t:"Karte, bitte. Hier ist sie.",ar:"بطاقة، من فضلك. تفضل."},{s:0,t:"Danke! Brauchst du eine Tüte?",ar:"شكرًا! هل تحتاج إلى كيس؟"},{s:1,t:"Ja, eine große Tüte, bitte. Tschüss!",ar:"نعم، كيس كبير، من فضلك. إلى اللقاء!"}]}},{stage:5,topic:"routine",topicAr:"اليوم الروتيني والمدرسة والعمل",topicEn:"Daily Routine, School & Work",topicDe:"Alltag, Schule und Arbeit",emoji:"⏰",title:"يوم دراسي كامل",grammar:{id:"de-time-am-um",title:"Zeit: am / um",titleAr:"الوقت am/um",covers:5},conv:{id:"de-stage5",speakers:["Schüler (الطالب)","Mitschüler (زميل الدراسة)"],turns:[{s:0,t:"Guten Morgen! Bist du früh aufgewacht?",ar:"صباح الخير! هل استيقظت باكرًا؟"},{s:1,t:"Ja, mein lauter Wecker hat mich geweckt.",ar:"نعم، ساعتي الصاخبة أيقظتني."},{s:0,t:"Ich esse sehr schnell Frühstück.",ar:"أنا آكل الفطور بسرعة كبيرة."},{s:1,t:"Brot und Milch, dann meine Tasche.",ar:"خبز وحليب، ثم حقيبتي."},{s:0,t:"Ist deine Tasche für die Schule fertig?",ar:"هل حقيبتك جاهزة للمدرسة؟"},{s:1,t:"Ja, Bücher, Stift und Mittagessen.",ar:"نعم، كتب وقلم وغداء."},{s:0,t:"Wir fahren um acht mit dem Bus.",ar:"نذهب بالحافلة في الثامنة."},{s:1,t:"Die Haltestelle ist nah bei meinem Haus.",ar:"موقف الحافلة قرب بيتي."},{s:0,t:"Die erste Stunde um halb zehn.",ar:"الدرس الأول في التاسعة والنصف."},{s:1,t:"Zuerst Mathe, dann Zeichnen, richtig?",ar:"الرياضيات أولًا، ثم الرسم، صحيح؟"},{s:0,t:"Ja, und Lesen und Schreiben auch.",ar:"نعم، والقراءة والكتابة أيضًا."},{s:1,t:"Pause ist um Viertel nach zehn.",ar:"الاستراحة في العاشرة والربع."},{s:0,t:"Wir spielen in der Pause Fußball.",ar:"نلعب كرة القدم في الاستراحة."},{s:1,t:"Ich laufe schnell und springe hoch!",ar:"أنا أركض بسرعة وأقفز عاليًا!"},{s:0,t:"Du hast gestern das Rennen gewonnen!",ar:"لقد ربحت السباق أمس!"},{s:1,t:"Mit einem großen Lächeln, ja!",ar:"بابتسامة كبيرة، نعم!"},{s:0,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:1,t:"Ich habe gestern das Rennen gewonnen!",ar:"ربحت السباق أمس!"},{s:0,t:"Was essen wir zu Mittag?",ar:"ماذا نأكل للغداء؟"},{s:1,t:"Sandwiches und Saft im Garten.",ar:"سندويشات وعصير في الحديقة."},{s:0,t:"Nach der Schule zuerst Hausaufgaben, richtig?",ar:"بعد المدرسة، الواجبات أولًا، صحيح؟"},{s:1,t:"Ja, dann spiele und lese ich.",ar:"نعم، ثم ألعب وأقرأ."},{s:0,t:"Mein Vater arbeitet in der Bibliothek.",ar:"أبي يعمل في المكتبة."},{s:1,t:"Er fährt morgens mit dem Bus.",ar:"يذهب بالحافلة صباحًا."},{s:0,t:"Er ordnet Bücher und hilft Menschen.",ar:"يرتب الكتب ويساعد الناس."},{s:1,t:"Am Samstag helfe ich meiner Mutter.",ar:"يوم السبت، أساعد أمي."},{s:0,t:"Morgens auf dem Markt?",ar:"في السوق صباحًا؟"},{s:1,t:"Ja, und wir finden leckere Überraschungen.",ar:"نعم، ونجد مفاجآت لذيذة."},{s:0,t:"Im Urlaub sind die Morgen langsam.",ar:"في العطلة، الصباحات على مهل."},{s:1,t:"Langsames Frühstück und ein Lieblingsbuch.",ar:"فطور على مهل وكتاب مفضل."},{s:0,t:"Und ein Lied mit der Familie?",ar:"وأغنية مع العائلة؟"},{s:1,t:"Ja! Heute keine Schule, nur Freude!",ar:"نعم! لا مدرسة اليوم، فقط فرح!"},{s:0,t:"Montagmorgen ist wieder Schulbus.",ar:"صباح الاثنين حافلة المدرسة مجددًا."},{s:1,t:"Mit meinem lieben Freund, Zeichenstunde.",ar:"مع صديقي العزيز، درس الرسم."},{s:0,t:"Meine Lieblingsstunde der Woche!",ar:"درسي المفضل في الأسبوع!"},{s:1,t:"Ich lerne auch Fahrrad fahren.",ar:"أنا أتعلم ركوب الدراجة أيضًا."},{s:0,t:"Mit deinem großen Bruder, richtig?",ar:"مع أخيك الكبير، صحيح؟"},{s:1,t:"Ja! Lustige Stürze, dann gewinne ich!",ar:"نعم! سقوطات مضحكة، ثم أنتصر!"},{s:0,t:"Familienabend: Spiele, Lachen, Fernsehen.",ar:"مساء العائلة: ألعاب وضحك وتلفاز."},{s:1,t:"Und eine Geschichte vor dem Schlafen.",ar:"وقصة قبل النوم."},{s:0,t:"Ich lese jede Nacht eine Geschichte.",ar:"أنا أقرأ قصة كل ليلة."},{s:1,t:"Dann schlafen, und ein neuer Tag!",ar:"ثم النوم، ويوم جديد!"},{s:0,t:"Bis morgen um acht!",ar:"أراك غدًا في الثامنة!"},{s:1,t:"An der Haltestelle! Tschüss!",ar:"عند موقف الحافلة! إلى اللقاء!"}]}},{stage:6,topic:"weather",topicAr:"الأوقات والطقس",topicEn:"Times & Weather",topicDe:"Zeiten und Wetter",emoji:"🌤️",title:"الطقس وعطلة نهاية الأسبوع",grammar:{id:"de-sein-haben",title:"sein / haben",titleAr:"sein و haben الشاذان",covers:2},conv:{id:"de-stage6",speakers:["Freund (الصديق)","Nachbar (الجار)"],turns:[{s:0,t:"Hallo! Was für ein sonniger Tag!",ar:"مرحبًا! يا له من يوم مشمس!"},{s:1,t:"Hallo! Ich liebe alle Jahreszeiten.",ar:"مرحبًا! أحب كل الفصول."},{s:0,t:"Frühlingsblumen, Sommersonne, richtig?",ar:"زهور الربيع وشمس الصيف، صحيح؟"},{s:1,t:"Herbstblätter und weißer Winterschnee.",ar:"أوراق الخريف وثلج الشتاء الأبيض."},{s:0,t:"Letzte Woche nur Regen, die ganze Woche!",ar:"الأسبوع الماضي، مطر فقط، طوال الأسبوع!"},{s:1,t:"Ich trage jeden Tag meinen Schirm.",ar:"أحمل مظلتي كل يوم."},{s:0,t:"Und springst du vor Freude in Pfützen?",ar:"وتقفز في البرك بفرح؟"},{s:1,t:"Ja! Und warte geduldig auf Sonne.",ar:"نعم! وأنتظر الشمس بصبر."},{s:0,t:"Wie viel Uhr ist es jetzt, bitte?",ar:"كم الساعة الآن، من فضلك؟"},{s:1,t:"Es ist drei, Zeit zum Spielen!",ar:"إنها الثالثة، وقت اللعب!"},{s:0,t:"Schulzeit, Spielzeit, Schlafenszeit.",ar:"وقت المدرسة ووقت اللعب ووقت النوم."},{s:1,t:"Jede Zeit hat ihre eigene Geschichte.",ar:"لكل وقت حكايته الخاصة."},{s:0,t:"Donner und Blitz in der Nacht!",ar:"رعد وبرق في الليل!"},{s:1,t:"Ich habe dann ein bisschen Angst.",ar:"أنا أخاف قليلًا حينها."},{s:0,t:"Zähle die Geräusche mit deinem Vater.",ar:"عدّ الأصوات مع أبيك."},{s:1,t:"Dann wird der Sturm ein Spiel.",ar:"حينها تصير العاصفة لعبة."},{s:0,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:1,t:"Der Sturm wird ein sicheres Spiel.",ar:"تصير العاصفة لعبة آمنة."},{s:0,t:"Schau! Ein Regenbogen nach dem Regen!",ar:"انظر! قوس قزح بعد المطر!"},{s:1,t:"Ich zähle sieben Farben mit meiner Schwester.",ar:"أعدّ سبعة ألوان مع أختي."},{s:0,t:"Und malst du ihn in dein Heft?",ar:"وترسمه في دفترك؟"},{s:1,t:"Ja, um ihn bei mir zu behalten.",ar:"نعم، ليبقى معي."},{s:0,t:"Ein heißer Sommertag am Strand!",ar:"يوم صيفي حارّ على الشاطئ!"},{s:1,t:"Ich baue eine Burg aus Sand.",ar:"أنا أبني قلعة من الرمل."},{s:0,t:"Im Schatten einer Palme?",ar:"في ظل شجرة نخيل؟"},{s:1,t:"Ja, und trinke glücklich kaltes Wasser.",ar:"نعم، وأشرب الماء البارد بسعادة."},{s:0,t:"Goldene Herbstblätter fallen herunter.",ar:"أوراق الخريف الذهبية تتساقط."},{s:1,t:"Ich sammle sie in einem großen Korb.",ar:"أجمعها في سلة كبيرة."},{s:0,t:"Und machst du ein Bild für Oma?",ar:"وتصنع منها لوحة لجدتك؟"},{s:1,t:"Ja! Sie liebt Herbstbilder.",ar:"نعم! تحب لوحات الخريف."},{s:0,t:"Der erste Schnee macht das Dorf weiß.",ar:"أول ثلج يحوّل القرية إلى بيضاء."},{s:1,t:"Weiße Flocken, ein Schneemann, kleine Füße.",ar:"رقائق بيضاء ورجل ثلج وأقدام صغيرة."},{s:0,t:"Frühlingssonne öffnet die Blumen.",ar:"شمس الربيع تفتح الزهور."},{s:1,t:"Bienen summen und Vögel bauen Nester.",ar:"النحل يطنّ والطيور تبني أعشاشًا."},{s:0,t:"Graue Wolken verstecken heute die Sonne.",ar:"غيوم رمادية تخفي الشمس اليوم."},{s:1,t:"Rätst du mit mir Wolkenformen?",ar:"هل تخمن معي أشكال الغيوم؟"},{s:0,t:"Leichter Regen, dann wieder ein Regenbogen!",ar:"مطر خفيف، ثم قوس قزح مجددًا!"},{s:1,t:"Perfektes Wetter für unseren Wochenendspaziergang!",ar:"طقس ممتاز لنزهتنا في عطلة نهاية الأسبوع!"}]}},{stage:7,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"مكالمة ودعوة",grammar:{id:"de-modalverben",title:"Modalverben",titleAr:"الأفعال المساعدة Modalverben",covers:3},conv:{id:"de-stage7",speakers:["Anrufer (المتصل)","Freund (الصديق)"],turns:[{s:0,t:"Hi! Bist du am Samstag frei?",ar:"مرحبًا! هل أنت متفرغ يوم السبت؟"},{s:1,t:"Hi! Ja, ich bin frei.",ar:"مرحبًا! نعم، أنا متفرغ."},{s:0,t:"Zuerst, Entschuldigung, ich war gestern spät.",ar:"أولًا، عذرًا، تأخرت أمس."},{s:1,t:"Im Park, ich habe lange gewartet.",ar:"في الحديقة، انتظرت طويلًا."},{s:0,t:"Nochmals Entschuldigung! Verzeihst du mir, bitte?",ar:"عذرًا مجددًا! هل تسامحني، من فضلك؟"},{s:1,t:"Ich verzeihe! Dann haben wir zusammen gespielt.",ar:"أنا أسامح! ثم لعبنا معًا."},{s:0,t:"Kann ich morgen deinen Stift leihen?",ar:"هل أستطيع استعارة قلمك غدًا؟"},{s:1,t:"Ja, und auch mein Lineal.",ar:"نعم، ومسطرتي أيضًا."},{s:0,t:"Ich helfe dir mit meinem Buch.",ar:"أساعدك بكتابي."},{s:1,t:"Höfliche Bitten unter guten Freunden!",ar:"طلبات مهذبة بين أصدقاء جيدين!"},{s:0,t:"Kannst du mir heute bitte helfen?",ar:"هل تستطيع مساعدتي، من فضلك، اليوم؟"},{s:1,t:"Gern! Was trägst du?",ar:"بكل سرور! ماذا تحمل؟"},{s:0,t:"Eine schwere Tasche, bis zur Haltestelle.",ar:"حقيبة ثقيلة، إلى موقف الحافلة."},{s:1,t:"Ich helfe dir bis zur Haltestelle.",ar:"سأساعدك حتى موقف الحافلة."},{s:0,t:"Danke! Du bist sehr nett.",ar:"شكرًا! أنت لطيف جدًا."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Du bist sehr nett, mein Freund.",ar:"أنت لطيف جدًا، يا صديقي."},{s:1,t:"Jetzt, komm am Samstag zu meiner Party!",ar:"الآن، تعال إلى حفلتي يوم السبت!"},{s:0,t:"Eine Party? Um wie viel Uhr, bitte?",ar:"حفلة؟ في أي وقت، من فضلك؟"},{s:1,t:"Um sieben Uhr abends.",ar:"في السابعة مساءً."},{s:0,t:"Wo ist die Party, bitte?",ar:"أين الحفلة، من فضلك؟"},{s:1,t:"Bei mir, in der Nähe des Parks.",ar:"في بيتي، قرب الحديقة."},{s:0,t:"Super! Kann ich einen Freund mitbringen?",ar:"رائع! هل أستطيع إحضار صديق؟"},{s:1,t:"Ja, natürlich! Bring ihn mit.",ar:"نعم، بالتأكيد! أحضره معك."},{s:0,t:"Welches Essen machst du?",ar:"ما الطعام الذي ستعده؟"},{s:1,t:"Pizza und Kuchen, alle lieben sie.",ar:"بيتزا وكعك، الجميع يحبهما."},{s:0,t:"Perfekt! Ich liebe Pizza auch.",ar:"ممتاز! أحب البيتزا أيضًا."},{s:1,t:"Kannst du Getränke mitbringen, bitte?",ar:"هل تستطيع إحضار مشروبات، من فضلك؟"},{s:0,t:"Ja, Saft und kaltes Wasser.",ar:"نعم، عصير وماء بارد."},{s:1,t:"Mein Geburtstag ist auch im Mai!",ar:"عيد ميلادي في أيار أيضًا!"},{s:0,t:"Am fünften Mai, richtig?",ar:"في الخامس من أيار، صحيح؟"},{s:1,t:"Ja! Ich lade alle meine Freunde ein.",ar:"نعم! أدعو كل أصدقائي."},{s:0,t:"Wir feiern zu Hause, mit Liedern?",ar:"نحتفل في البيت، مع أغنيات؟"},{s:1,t:"Ja, wir singen und essen Kuchen.",ar:"نعم، نغني ونأكل الكعك."},{s:0,t:"Kerzen auf dem Kuchen, und Geschenke?",ar:"شموع على الكعك، وهدايا؟"},{s:1,t:"Ja, Geschenke von Freunden, mit Freude.",ar:"نعم، هدايا من الأصدقاء، بفرح."},{s:1,t:"Danke! Komm nicht zu spät!",ar:"شكرًا! لا تتأخر!"},{s:0,t:"Ich komme um sieben, versprochen.",ar:"سآتي في السابعة، أعدك."},{s:1,t:"Wunderbar! Ich warte auf dich.",ar:"رائع! سأنتظرك."},{s:0,t:"Bis Samstag! Tschüss!",ar:"أراك السبت! إلى اللقاء!"},{s:1,t:"Warte! Noch eine Frage, bitte?",ar:"انتظر! سؤال آخر، من فضلك؟"},{s:0,t:"Ja, frag mich, mein Freund.",ar:"نعم، اسألني، يا صديقي."},{s:1,t:"Treffen wir uns am Sonntag im Park?",ar:"هل نلتقي في الحديقة يوم الأحد؟"},{s:0,t:"Ja! Sonntag im Park, tschüss!",ar:"نعم! الأحد في الحديقة، إلى اللقاء!"}]}},{stage:8,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"إلى المحطة والبحر",grammar:{id:"de-separable",title:"Trennbare Verben",titleAr:"الأفعال المنفصلة",covers:2},conv:{id:"de-stage8",speakers:["Fahrer (السائق)","Fahrgast (الراكب)"],turns:[{s:1,t:"Hallo! Zum Bahnhof, bitte.",ar:"مرحبًا! إلى المحطة، من فضلك."},{s:0,t:"Hallo! Kein Problem. Bitte einsteigen.",ar:"مرحبًا! لا مشكلة. تفضل بالجلوس."},{s:1,t:"Wie lange dauert die Fahrt?",ar:"كم تستغرق الرحلة؟"},{s:0,t:"Etwa fünfzehn Minuten, keine Sorge.",ar:"حوالي خمس عشرة دقيقة، لا تقلق."},{s:1,t:"Gut. Ich habe einen Zug.",ar:"جيد. عندي قطار."},{s:0,t:"Um wie viel Uhr fährt dein Zug?",ar:"في أي وقت قطارك؟"},{s:1,t:"Um elf, glaube ich. Richtig?",ar:"في الحادية عشرة، أعتقد. صحيح؟"},{s:0,t:"Keine Sorge, wir sind schnell.",ar:"لا تقلق، نحن سريعون."},{s:1,t:"Können wir durch den Park fahren?",ar:"هل نستطيع الذهاب عبر الحديقة؟"},{s:0,t:"Ja, aber heute ist es langsamer.",ar:"نعم، لكنه أبطأ اليوم."},{s:1,t:"Warum ist es heute langsamer?",ar:"لماذا هو أبطأ اليوم؟"},{s:0,t:"Weil es viel Verkehr gibt.",ar:"لأن هناك ازدحامًا كثيرًا."},{s:1,t:"Dann nimm die Hauptstraße.",ar:"إذن اسلك الشارع الرئيسي."},{s:0,t:"Gute Idee. Wir kommen bald an.",ar:"فكرة جيدة. سنصل قريبًا."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Wir kommen bald am Bahnhof an.",ar:"سنصل إلى المحطة قريبًا."},{s:1,t:"Danke! Wie viel, bitte?",ar:"شكرًا! كم الحساب، من فضلك؟"},{s:0,t:"Zwölf Euro, bitte. Danke!",ar:"اثنا عشر يورو، من فضلك. شكرًا!"},{s:1,t:"Hier sind fünfzehn. Behalte den Rest.",ar:"هذه خمسة عشر. احتفظ بالباقي."},{s:0,t:"Danke! Gute Reise!",ar:"شكرًا! رحلة سعيدة!"},{s:1,t:"Ich bin neu in dieser Stadt.",ar:"أنا جديد في هذه المدينة."},{s:1,t:"Wie finde ich später den Bahnhof?",ar:"كيف أجد المحطة لاحقًا؟"},{s:0,t:"Geh geradeaus, dann rechts, dann links.",ar:"اذهب مباشرة، ثم يمينًا، ثم يسارًا."},{s:1,t:"Ist der Bahnhof nah von hier?",ar:"هل المحطة قريبة من هنا؟"},{s:0,t:"Ja, sehr nah, zehn Minuten.",ar:"نعم، قريبة جدًا، عشر دقائق."},{s:1,t:"Dann nehme ich einen Bus in die Stadt.",ar:"ثم سأركب حافلة إلى المدينة."},{s:0,t:"Kaufe Fahrkarten vor der Busfahrt.",ar:"اشترِ التذاكر قبل ركوب الحافلة."},{s:1,t:"Wo steigen wir aus, bitte?",ar:"أين ننزل، من فضلك؟"},{s:0,t:"Im Stadtzentrum, letzte Haltestelle.",ar:"في وسط المدينة، المحطة الأخيرة."},{s:1,t:"Im Juni reisen wir ans Meer.",ar:"في حزيران، سنسافر إلى البحر."},{s:0,t:"Wann fahrt ihr genau los?",ar:"متى تغادرون بالضبط؟"},{s:1,t:"Am zehnten Juni, morgens.",ar:"في العاشر من حزيران، صباحًا."},{s:0,t:"Mit dem Bus, mit Taschen und Freude?",ar:"بالحافلة، مع حقائب وفرح؟"},{s:1,t:"Ja! Wir schwimmen und kehren glücklich zurück.",ar:"نعم! نسبح ونعود سعداء."},{s:0,t:"Brauchst du eine Rückfahrkarte?",ar:"هل تحتاج تذكرة عودة؟"},{s:1,t:"Ja, für Sonntagabend, bitte.",ar:"نعم، لمساء الأحد، من فضلك."},{s:0,t:"Der Bus fährt um sechs genau.",ar:"الحافلة تغادر في السادسة بالضبط."},{s:1,t:"Perfekt! Ich bin pünktlich.",ar:"ممتاز! سأكون في الوقت."},{s:0,t:"Wir sind da! Der Bahnhof, bitte.",ar:"وصلنا! المحطة، من فضلك."},{s:1,t:"Danke für die gute Fahrt!",ar:"شكرًا على الرحلة الجيدة!"},{s:0,t:"Schöne Reise ans Meer!",ar:"رحلة سعيدة إلى البحر!"},{s:1,t:"Tschüss! Bis zur Rückkehr!",ar:"إلى اللقاء! أراك عند العودة!"}]}},{stage:9,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"مريض وعند الطبيب",grammar:{id:"de-sein-haben",title:"sein / haben",titleAr:"sein و haben الشاذان",covers:1},conv:{id:"de-stage9",speakers:["Arzt (الطبيب)","Patient (المريض)"],turns:[{s:1,t:"Hallo! Ich brauche einen Arzt.",ar:"مرحبًا! أحتاج إلى طبيب."},{s:0,t:"Hallo! Was ist das Problem?",ar:"مرحبًا! ما المشكلة؟"},{s:1,t:"Ich bin heute krank, sehr krank.",ar:"أنا مريض اليوم، مريض جدًا."},{s:0,t:"Was tut dir weh? Kopf oder Hals?",ar:"ما الذي يؤلمك؟ الرأس أم الحلق؟"},{s:1,t:"Mein Kopf und mein Hals tun weh.",ar:"رأسي وحلقي يؤلمانني."},{s:0,t:"Seit wann, bitte? Seit gestern?",ar:"منذ متى، من فضلك؟ منذ أمس؟"},{s:1,t:"Seit gestern Morgen, Herr Doktor.",ar:"منذ صباح أمس، يا دكتور."},{s:0,t:"Schläfst du nachts gut?",ar:"هل تنام جيدًا في الليل؟"},{s:1,t:"Nein, ich schlafe sehr schlecht.",ar:"لا، أنام سيئًا جدًا."},{s:0,t:"Weil du zu viel arbeitest?",ar:"لأنك تعمل كثيرًا؟"},{s:1,t:"Ja, ich arbeite bis Mitternacht.",ar:"نعم، أعمل حتى منتصف الليل."},{s:0,t:"Du brauchst Ruhe und weniger Stress.",ar:"تحتاج إلى راحة وضغط أقل."},{s:1,t:"Ich bleibe den ganzen Tag im Bett?",ar:"هل أبقى في السرير طوال اليوم؟"},{s:0,t:"Ja, Bett, Wasser und warme Suppe.",ar:"نعم، سرير وماء وحساء دافئ."},{s:1,t:"Ich trinke jeden Tag viel Wasser.",ar:"أشرب كثيرًا من الماء كل يوم."},{s:0,t:"Gut! Und iss Suppe zum Abendessen.",ar:"جيد! وكل الحساء للعشاء."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Iss heute Abend warme Suppe.",ar:"كل حساءً دافئًا لعشاء الليلة."},{s:1,t:"Meine Mutter kam heute mit mir.",ar:"أمي جاءت معي اليوم."},{s:0,t:"Gut! Mach bitte den Mund auf.",ar:"جيد! افتح فمك، من فضلك."},{s:1,t:"Sieht es schlimm aus, Herr Doktor?",ar:"هل يبدو سيئًا، يا دكتور؟"},{s:0,t:"Ein roter Hals, aber keine Gefahr.",ar:"حلق أحمر، لكن لا خطر."},{s:1,t:"Welche Medizin nehme ich?",ar:"ما الدواء الذي آخذه؟"},{s:0,t:"Nimm diese Tablette zweimal täglich.",ar:"خذ هذه الحبة مرتين في اليوم."},{s:1,t:"Nach dem Essen oder vorher?",ar:"بعد الطعام أم قبله؟"},{s:0,t:"Nach dem Essen, mit viel Wasser.",ar:"بعد الطعام، مع كثير من الماء."},{s:1,t:"Kaufe ich sie in der Apotheke?",ar:"هل أشتريها من الصيدلية؟"},{s:0,t:"Ja, beschreibe dort Kopfschmerzen und Husten.",ar:"نعم، صف الصداع والسعال هناك."},{s:1,t:"Mein Kopf tut weh und ich huste.",ar:"رأسي يؤلمني وأنا أسعل."},{s:0,t:"Der Apotheker gibt gute Medizin.",ar:"الصيدلاني يعطي دواءً جيدًا."},{s:1,t:"Wann nehme ich die Tabletten?",ar:"متى آخذ الحبوب؟"},{s:0,t:"Morgens und abends, nach dem Essen.",ar:"صباحًا ومساءً، بعد الطعام."},{s:1,t:"Wann komme ich wieder?",ar:"متى آتي مرة أخرى؟"},{s:0,t:"Komm nächsten Montagmorgen wieder.",ar:"تعال مرة أخرى صباح الاثنين القادم."},{s:1,t:"Montag um neun Uhr passt gut.",ar:"الاثنين في التاسعة يناسبني."},{s:0,t:"Ruh dich gut aus, trink Wasser, iss Suppe.",ar:"ارتح جيدًا، اشرب الماء، كل الحساء."},{s:1,t:"Danke, Herr Doktor! Ich fühle mich besser.",ar:"شكرًا، يا دكتور! أشعر بتحسن."},{s:0,t:"Gut. Gute Besserung, mein Patient!",ar:"جيد. شفاء عاجل، يا مريضي!"},{s:1,t:"Ich bleibe zu Hause, bis ich mich wohl fühle.",ar:"سأبقى في البيت حتى أشعر بالعافية."},{s:0,t:"Perfekt! Tschüss, und bleib gesund!",ar:"ممتاز! إلى اللقاء، وابقَ بصحة!"}]}},{stage:10,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"عطلة نهاية الأسبوع: رياضة وموسيقى",grammar:{id:"de-verbendungen",title:"Verbendungen",titleAr:"نهايات الفعل Verbendungen",covers:2},conv:{id:"de-stage10",speakers:["Spieler (اللاعب)","Freund (الصديق)"],turns:[{s:0,t:"Was machst du am Wochenende?",ar:"ماذا تفعل في عطلة نهاية الأسبوع؟"},{s:1,t:"Fußball, Lesen und Zeichnen, und du?",ar:"كرة القدم والقراءة والرسم، وأنت؟"},{s:0,t:"Ich spiele Fußball und lese Bücher.",ar:"ألعب كرة القدم وأقرأ الكتب."},{s:1,t:"Treffen wir uns am Sonntag im Park?",ar:"هل نلتقي في الحديقة يوم الأحد؟"},{s:0,t:"Ja! Unter dem großen Baum.",ar:"نعم! تحت الشجرة الكبيرة."},{s:1,t:"Wir spielen dort zusammen Ball.",ar:"نلعب بالكرة هناك معًا."},{s:0,t:"Am Samstag schwimme ich auch.",ar:"يوم السبت، أسبح أيضًا."},{s:1,t:"Im Schwimmbad, mit Freunden?",ar:"في المسبح، مع الأصدقاء؟"},{s:0,t:"Ja! Ich lerne dort schwimmen.",ar:"نعم! أتعلم السباحة هناك."},{s:1,t:"Und spielst du glücklich im Wasser?",ar:"وتلعب بسعادة في الماء؟"},{s:0,t:"Ja! Wasserspiele machen großen Spaß.",ar:"نعم! ألعاب الماء ممتعة جدًا."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Wasserspiele machen großen Spaß!",ar:"ألعاب الماء ممتعة جدًا!"},{s:1,t:"Um wie viel Uhr schwimmst du samstags?",ar:"في أي وقت تسبح يوم السبت؟"},{s:0,t:"Um zehn Uhr morgens.",ar:"في العاشرة صباحًا."},{s:1,t:"Ich komme mit dir, bitte!",ar:"سآتي معك، من فضلك!"},{s:0,t:"Perfekt! Bring deinen blauen Badeanzug mit.",ar:"ممتاز! أحضر ملابس السباحة الزرقاء."},{s:1,t:"Und meine Gitarre? Ich spiele Gitarre.",ar:"وغيتاري؟ أنا أعزف الغيتار."},{s:0,t:"Du spielst Gitarre? Jeden Tag?",ar:"أنت تعزف الغيتار؟ كل يوم؟"},{s:1,t:"Ja, ich übe jeden einzelnen Tag.",ar:"نعم، أتدرب كل يوم."},{s:0,t:"Kannst du ein einfaches Lied singen?",ar:"هل تستطيع غناء أغنية بسيطة؟"},{s:1,t:"Ja, und spiele es für Freunde.",ar:"نعم، وأعزفه للأصدقاء."},{s:0,t:"Spiel am Sonntag für uns, bitte!",ar:"اعزف لنا يوم الأحد، من فضلك!"},{s:1,t:"Gern! Ein fröhliches Lied.",ar:"بكل سرور! أغنية سعيدة."},{s:0,t:"Malst du auch Bilder?",ar:"هل ترسم الصور أيضًا؟"},{s:1,t:"Ja, ich male im Park.",ar:"نعم، أرسم في الحديقة."},{s:0,t:"Blumen, Bäume und unser Fußball?",ar:"زهور وأشجار وكرة قدمنا؟"},{s:1,t:"Ja! Und meine Gitarre, natürlich.",ar:"نعم! وغيتاري، بالطبع."},{s:0,t:"Sonntag: Fußball, Lieder und Bilder!",ar:"الأحد: كرة قدم وأغانٍ ورسوم!"},{s:1,t:"Und Schwimmen am Samstagmorgen!",ar:"والسباحة صباح السبت!"},{s:0,t:"Bring Freunde, Bälle und Gitarren mit!",ar:"أحضر الأصدقاء والكرات والغيتارات!"},{s:1,t:"Ein perfektes Wochenende, mein Freund!",ar:"عطلة نهاية أسبوع ممتازة، يا صديقي!"},{s:0,t:"Läufst du beim Fußball schnell?",ar:"هل تركض بسرعة في كرة القدم؟"},{s:1,t:"Ja, und ich springe sehr hoch!",ar:"نعم، وأقفز عاليًا جدًا!"},{s:0,t:"Du gewinnst jedes Spiel, richtig?",ar:"أنت تربح كل مباراة، صحيح؟"},{s:1,t:"Nicht jedes Spiel, aber mit Freude!",ar:"ليست كل مباراة، لكن بفرح!"},{s:0,t:"Bis Sonntag im Park!",ar:"أراك الأحد في الحديقة!"},{s:1,t:"Sonntag im Park! Tschüss!",ar:"الأحد في الحديقة! إلى اللقاء!"}]}},{stage:11,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"حديث عن المهن في المدرسة",grammar:{id:"de-profession-no-article",title:"Berufe ohne Artikel",titleAr:"المهن بدون أداة",covers:3},conv:{id:"de-stage11",speakers:["Lehrer (المعلم)","Koch (الطباخ)"],turns:[{s:0,t:"Guten Morgen! Was machst du beruflich?",ar:"صباح الخير! ماذا تعمل؟"},{s:1,t:"Guten Morgen! Ich bin Koch.",ar:"صباح الخير! أنا طباخ."},{s:0,t:"Ein Koch! In unserer Schulküche?",ar:"طباخ! في مطبخ مدرستنا؟"},{s:1,t:"Ja! Ich koche Suppe und Brot.",ar:"نعم! أطبخ الحساء والخبز."},{s:0,t:"Und ich bin Lehrer hier.",ar:"وأنا معلم هنا."},{s:1,t:"Was unterrichtest du die Kinder?",ar:"ماذا تُعلّم الأطفال؟"},{s:0,t:"Lesen und Schreiben, jeden Tag.",ar:"القراءة والكتابة، كل يوم."},{s:1,t:"Hilfst du den kleinen Kindern?",ar:"هل تساعد الأطفال الصغار؟"},{s:0,t:"Ja, und ich liebe meine Arbeit.",ar:"نعم، وأحب عملي."},{s:1,t:"Ich probiere das Essen, dann serviere ich.",ar:"أتذوق الطعام، ثم أقدمه."},{s:0,t:"Mit einem Lächeln für die Kinder?",ar:"بابتسامة للأطفال؟"},{s:1,t:"Immer! Kinder lieben warme Suppe.",ar:"دائمًا! الأطفال يحبون الحساء الدافئ."},{s:0,t:"Wer bringt die Kinder hierher?",ar:"من يحضر الأطفال إلى هنا؟"},{s:1,t:"Der Busfahrer, jeden Morgen.",ar:"سائق الحافلة، كل صباح."},{s:0,t:"Ein guter Fahrer, nett und vorsichtig?",ar:"سائق جيد، لطيف وحذر؟"},{s:1,t:"Ja! Und der Bäcker bringt Brot.",ar:"نعم! والخباز يحضر الخبز."},{s:0,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:1,t:"Der Bäcker bringt täglich frisches Brot.",ar:"الخباز يحضر خبزًا طازجًا يوميًا."},{s:0,t:"Und der Arzt hilft kranken Kindern?",ar:"والطبيب يساعد الأطفال المرضى؟"},{s:1,t:"Ja, im Krankenhaus bei der Schule.",ar:"نعم، في المستشفى قرب المدرسة."},{s:0,t:"Um wie viel Uhr beginnst du die Arbeit?",ar:"في أي وقت تبدأ العمل؟"},{s:1,t:"Um sieben, vor den Kindern.",ar:"في السابعة، قبل الأطفال."},{s:0,t:"Ich beginne um acht, mit Unterricht.",ar:"أبدأ في الثامنة، بالدروس."},{s:1,t:"Wann beendest du die Arbeit?",ar:"متى تنهي العمل؟"},{s:0,t:"Um drei, dann gehe ich nach Hause.",ar:"في الثالثة، ثم أذهب إلى البيت."},{s:1,t:"Kochst du auch zu Hause?",ar:"هل تطبخ في البيت أيضًا؟"},{s:0,t:"Nein, zu Hause lese ich Bücher.",ar:"لا، في البيت أقرأ الكتب."},{s:0,t:"Was hast du vor der Schule gekocht?",ar:"ماذا كنت تطبخ قبل المدرسة؟"},{s:1,t:"In einem Restaurant, Suppe und Fisch.",ar:"في مطعم، حساء وسمك."},{s:0,t:"Und jetzt, Mittagessen für Kinder?",ar:"والآن، غداء للأطفال؟"},{s:1,t:"Ja! Suppe, Brot und Saft.",ar:"نعم! حساء وخبز وعصير."},{s:0,t:"Essen die Kinder um zwölf glücklich?",ar:"هل يأكل الأطفال بسعادة في الثانية عشرة؟"},{s:1,t:"Ja, um zwölf, in der Kantine.",ar:"نعم، في الثانية عشرة، في المقصف."},{s:0,t:"Magst du deine Arbeit, Koch?",ar:"هل تحب عملك، يا طباخ؟"},{s:1,t:"Ja! Kochen macht mich glücklich.",ar:"نعم! الطبخ يسعدني."},{s:0,t:"Unterrichten macht mich auch glücklich.",ar:"التعليم يسعدني أيضًا."},{s:1,t:"Gute Berufe helfen vielen Menschen.",ar:"المهن الجيدة تساعد كثيرًا من الناس."},{s:0,t:"Lehrer, Köche, Fahrer, Bäcker, Ärzte!",ar:"معلمون وطباخون وسائقون وخبازون وأطباء!"},{s:1,t:"Alle arbeiten zusammen für die Kinder.",ar:"كلهم يعملون معًا من أجل الأطفال."},{s:0,t:"Bis morgen in der Schule!",ar:"أراك غدًا في المدرسة!"},{s:1,t:"Morgen, warme Suppe um zwölf!",ar:"غدًا، حساء دافئ في الثانية عشرة!"},{s:0,t:"Tschüss! Einen schönen Tag!",ar:"إلى اللقاء! يومًا سعيدًا!"}]}},{stage:12,topic:"services",topicAr:"الخدمات والطوارئ",topicEn:"Services & Emergencies",topicDe:"Dienstleistungen und Notfälle",emoji:"🏦",title:"مشاوير في المدينة",grammar:{id:"de-modalverben",title:"Modalverben",titleAr:"الأفعال المساعدة Modalverben",covers:2},conv:{id:"de-stage12",speakers:["Kunde (الزبون)","Freund (الصديق)"],turns:[{s:1,t:"Guten Morgen! Wohin gehen wir?",ar:"صباح الخير! إلى أين نذهب؟"},{s:0,t:"Guten Morgen! Zuerst zur Bank.",ar:"صباح الخير! أولًا، إلى البنك."},{s:1,t:"Warum die Bank? Ein neues Konto?",ar:"لماذا البنك؟ حساب جديد؟"},{s:0,t:"Ja! Ich eröffne heute ein Konto.",ar:"نعم! سأفتح حسابًا اليوم."},{s:1,t:"Nimmst du auch eine Karte?",ar:"هل ستأخذ بطاقة أيضًا؟"},{s:0,t:"Ja, eine Karte für den Automaten.",ar:"نعم، بطاقة للجهاز."},{s:1,t:"Behalte deine Geheimnummer sicher!",ar:"حافظ على رقمك السري آمنًا!"},{s:0,t:"Natürlich! Ich verrate sie nie.",ar:"بالطبع! لن أخبر به أبدًا."},{s:1,t:"Hebst du jetzt Geld ab?",ar:"هل ستسحب مالًا الآن؟"},{s:0,t:"Ja, fünfzig Euro aus dem Automaten.",ar:"نعم، خمسون يورو من الجهاز."},{s:1,t:"Entschuldigung, kannst du das bitte wiederholen?",ar:"عذرًا، هل تستطيع تكرار ذلك، من فضلك؟"},{s:0,t:"Fünfzig Euro aus dem Automaten.",ar:"خمسون يورو من الجهاز."},{s:1,t:"Als Nächstes die Post, richtig?",ar:"بعدها، مكتب البريد، صحيح؟"},{s:0,t:"Ja! Ein Paket für meine Oma.",ar:"نعم! طرد لجدتي."},{s:1,t:"Und auch ein Brief, mit Adresse?",ar:"ورسالة أيضًا، مع العنوان؟"},{s:0,t:"Ja, ich schreibe die Adresse hier.",ar:"نعم، أكتب العنوان هنا."},{s:1,t:"Wie viel kostet die Briefmarke, bitte?",ar:"كم سعر الطابع، من فضلك؟"},{s:0,t:"Zwei Euro. Wann kommt es an?",ar:"يوروان. متى يصل؟"},{s:1,t:"In drei Tagen, hoffe ich.",ar:"خلال ثلاثة أيام، آمل ذلك."},{s:0,t:"Gut! Oma wartet glücklich.",ar:"جيد! جدتي تنتظر بسعادة."},{s:1,t:"Jetzt die Apotheke, mein Kopf tut weh.",ar:"الآن الصيدلية، رأسي يؤلمني."},{s:0,t:"Und du hustest auch, mein Freund?",ar:"وأنت تسعل أيضًا، يا صديقي؟"},{s:1,t:"Ja, Kopfschmerzen und Husten seit dem Morgen.",ar:"نعم، صداع وسعال منذ الصباح."},{s:0,t:"Beschreibe es gut in der Apotheke.",ar:"صفه جيدًا في الصيدلية."},{s:1,t:"Ich brauche Medizin für meinen Kopf.",ar:"أحتاج دواءً لرأسي."},{s:0,t:"Tabletten morgens und abends?",ar:"حبوب صباحًا ومساءً؟"},{s:1,t:"Ja, nach dem Essen, mit viel Wasser.",ar:"نعم، بعد الطعام، مع كثير من الماء."},{s:0,t:"Gut! Ruhe hilft dir, dich besser zu fühlen.",ar:"جيد! الراحة تساعدك على الشعور بتحسن."},{s:1,t:"Schau! Ein Mann fällt auf der Straße!",ar:"انظر! رجل يسقط في الشارع!"},{s:0,t:"Hilfe! Wir müssen ihm schnell helfen!",ar:"النجدة! يجب أن نساعده بسرعة!"},{s:1,t:"Frag diese Frau um Hilfe!",ar:"اطلب المساعدة من تلك المرأة، من فضلك!"},{s:0,t:"Sie ruft sofort die Polizei.",ar:"إنها تتصل بالشرطة فورًا."},{s:1,t:"Wo ist das nächste Krankenhaus?",ar:"أين أقرب مستشفى؟"},{s:0,t:"Beim Park, fünf Minuten entfernt.",ar:"قرب الحديقة، على بعد خمس دقائق."},{s:1,t:"Wir helfen ihm, bis der Arzt kommt.",ar:"نساعده حتى يأتي الطبيب."},{s:0,t:"Der Arzt kommt sehr schnell, gut.",ar:"الطبيب يأتي بسرعة كبيرة، جيد."},{s:1,t:"Danke für deine mutige Hilfe!",ar:"شكرًا على مساعدتك الشجاعة!"},{s:0,t:"Wir sind Freunde, wir helfen zusammen.",ar:"نحن أصدقاء، نساعد معًا."},{s:1,t:"Was für ein Tag! Bank, Post, Apotheke.",ar:"يا له من يوم! بنك وبريد وصيدلية."},{s:0,t:"Und Hilfe auf der Straße auch.",ar:"ومساعدة في الشارع أيضًا."},{s:1,t:"Wir beenden die Besorgungen, glücklich und müde.",ar:"ننهي المشاوير، سعداء ومتعبون."},{s:0,t:"Tee zu Hause jetzt, mein Freund?",ar:"شاي في البيت الآن، يا صديقي؟"},{s:1,t:"Ja! Tee und Kuchen, bitte.",ar:"نعم! شاي وكعك، من فضلك."},{s:0,t:"Warte, noch eine Besorgung morgen?",ar:"انتظر، مشوار آخر غدًا؟"},{s:1,t:"Morgen nur Ruhe, keine Besorgungen!",ar:"غدًا، راحة فقط، لا مشاوير!"},{s:0,t:"Tschüss! Ein guter Tag, mein Freund!",ar:"إلى اللقاء! يوم جيد، يا صديقي!"}]}}]};var CONV_DATA_A2={en:[{stage:1,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"سنتان في الحي الجديد",grammar:{id:"en-present-perfect",title:"Present perfect",titleAr:"المضارع التام",covers:1},conv:{id:"en-stage1-a2",speakers:["Neighbor (الجار)","New Neighbor (الجار الجديد)"],turns:[{s:0,t:"Hey! You're the new neighbor, right? We've never met!",ar:"مرحبًا! أنت الجار الجديد، صحيح؟ لم نلتقِ من قبل!"},{s:1,t:"Yeah, that's me. I've just moved in next door.",ar:"نعم، هذا أنا. انتقلت للسكن في البيت المجاور للتو."},{s:0,t:"No way! I've lived here for two years now.",ar:"مستحيل! أنا أسكن هنا منذ سنتين الآن."},{s:1,t:"Really? Have you met all the neighbors yet?",ar:"حقًا؟ هل قابلت كل الجيران حتى الآن؟"},{s:0,t:"Almost all of them. They're a friendly crowd.",ar:"تقريبًا كلهم. إنهم مجموعة ودودة."},{s:1,t:"Good to know. I've already met the lady across the street.",ar:"من الجيد معرفة ذلك. قابلت السيدة التي تسكن عبر الشارع بالفعل."},{s:0,t:"Ah, Mrs. — I mean, the lady with the dog? She's great.",ar:"آه، السيدة — أعني، السيدة صاحبة الكلب؟ إنها رائعة."},{s:1,t:"Yeah! Her dog ran into me this morning. It was so funny.",ar:"نعم! كلبها ركض نحوي هذا الصباح. كان مضحكًا جدًا."},{s:0,t:"Ha! He's friendly, but he's huge. Don't worry, he won't hurt you.",ar:"ها! إنه ودود، لكنه ضخم. لا تقلق، لن يؤذيك."},{s:1,t:"I hope so. I've never had a dog myself.",ar:"أتمنى ذلك. لم يكن لدي كلب من قبل."},{s:0,t:"So — what do you do? Are you a teacher, an engineer, or something else?",ar:"إذن — ماذا تعمل؟ هل أنت معلم، أم مهندس، أم شيء آخر؟"},{s:1,t:"Nope. I've only been here for three weeks.",ar:"لا. أنا هنا منذ ثلاثة أسابيع فقط."},{s:0,t:"Wow. And the salary? I mean, is the pay fair for the work?",ar:"واو. والراتب؟ أعني، هل الأجر عادل مقابل العمل؟"},{s:1,t:"Yeah, I've just started at the hospital downtown.",ar:"نعم، بدأت للتو العمل في المستشفى وسط المدينة."},{s:0,t:"Nice! My brother works there too. He's a doctor, and his boss is really strict.",ar:"جميل! أخي يعمل هناك أيضًا. إنه طبيب، ومديره صارم جدًا."},{s:1,t:"No way! Maybe we've already met him. What's his name—",ar:"مستحيل! ربما قابلناه بالفعل. ما اسمه—"},{s:0,t:"—Sorry, I can't remember if I told you. Anyway, welcome!",ar:"—عذرًا، لا أتذكر إن كنت أخبرتك. على أي حال، أهلًا بك!"},{s:1,t:"Thanks! I'm so pleased we moved here. The old apartment was noisy and small.",ar:"شكرًا! أنا سعيد جدًا لأننا انتقلنا إلى هنا. الشقة القديمة كانت صاخبة وصغيرة."},{s:0,t:"It is quiet. Mostly. Except on weekends, to be honest.",ar:"إنه هادئ. غالبًا. باستثناء عطلات نهاية الأسبوع، بصراحة."},{s:1,t:"Uh-huh. What happens on weekends?",ar:"أها. ماذا يحدث في عطلات نهاية الأسبوع؟"},{s:0,t:"The kids play soccer in the street. It's loud, but it's fun.",ar:"الأطفال يلعبون كرة القدم في الشارع. إنه صاخب، لكنه ممتع."},{s:1,t:"I don't mind that. I grew up in a crowded city, so normally I sleep fine with noise.",ar:"لا يزعجني ذلك. نشأت في مدينة مزدحمة، لذا عادة أنام جيدًا مع الضوضاء."},{s:0,t:"Really? Most people complain about the noise.",ar:"حقًا؟ معظم الناس يشتكون من الضوضاء."},{s:1,t:"I mean, a little noise is fine. Silence makes me nervous.",ar:"أعني، القليل من الضوضاء لا بأس به. الصمت يجعلني متوترًا."},{s:0,t:"Fair enough. Hey, do you need any tools? I've got a hammer and a lot more.",ar:"معقول. مهلًا، هل تحتاج أي أدوات؟ لدي مطرقة والكثير غيرها."},{s:1,t:"Not yet. I've opened about half the boxes. The rest can wait.",ar:"ليس بعد. فتحت نحو نصف الصناديق. الباقي يمكن أن ينتظر."},{s:0,t:"I can help if you want. I've got a strong back, and I can lift heavy boxes easily.",ar:"يمكنني المساعدة إن أردت. ظهري قوي، ويمكنني رفع الصناديق الثقيلة بسهولة."},{s:1,t:"That's so kind! But you've already done enough by saying hi.",ar:"هذا لطف كبير منك! لكنك فعلت ما يكفي بمجرد أن قلت مرحبًا."},{s:0,t:"Come on, neighbors help each other. That's the tradition in this street.",ar:"هيا، الجيران يساعدون بعضهم. هذه هي العادة في هذا الشارع."},{s:1,t:"Well, in that case, I've got a heavy table that needs two people.",ar:"حسنًا، في هذه الحالة، لدي طاولة ثقيلة تحتاج شخصين."},{s:0,t:"Perfect. Let's do it now. I've got an hour, and my schedule is clear.",ar:"ممتاز. لنفعلها الآن. لدي ساعة، وجدولي فارغ."},{s:1,t:"Are you sure? I don't wanna be a problem.",ar:"هل أنت متأكد؟ لا أريد أن أكون مشكلة."},{s:0,t:"You're not a problem at all. Seriously, it's no trouble.",ar:"أنت لست مشكلة إطلاقًا. بجدية، لا إزعاج في ذلك."},{s:1,t:"Okay, thanks! I've never met such a nice neighbor before.",ar:"حسنًا، شكرًا! لم أقابل جارًا لطيفًا مثلك من قبل."},{s:0,t:"And I've never met a new neighbor with such good manners!",ar:"وأنا لم أقابل جارًا جديدًا بآداب جيدة مثل هذه!"},{s:1,t:"Ha! Deal. Let's get that table inside.",ar:"ها! اتفقنا. لنُدخل تلك الطاولة."},{s:0,t:"After you. And welcome to the street — for real this time.",ar:"تفضل. وأهلًا بك في الشارع — هذه المرة بجدية."},{s:1,t:"Thanks. I think I'm gonna like it here.",ar:"شكرًا. أظن أنني سأحب العيش هنا."},{s:0,t:"You will. We've all been here for years, and the community here is really friendly.",ar:"ستحبه. نحن جميعًا هنا منذ سنوات، والمجتمع هنا ودود جدًا."},{s:1,t:"That's exactly what I wanted to hear.",ar:"هذا بالضبط ما أردت سماعه."},{s:0,t:"Good. Now, let's move that table before it rains. The storm is coming fast.",ar:"جيد. الآن، لننقل تلك الطاولة قبل أن تمطر. العاصفة قادمة بسرعة."},{s:1,t:"Right behind you!",ar:"خلفك مباشرة!"},{s:0,t:"Oh, and one more thing — the Wi-Fi password is on the gate, next to the lock.",ar:"أوه، وشيء آخر — كلمة مرور الواي فاي على البوابة، بجانب القفل."},{s:1,t:"You've gotta be kidding me. That's the best welcome ever.",ar:"لا بد أنك تمزح. هذا أفضل ترحيب على الإطلاق."}]}},{stage:2,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"مقارنة في السوق والمطعم",grammar:{id:"en-comparatives",title:"Comparatives",titleAr:"المقارنة",covers:1},conv:{id:"en-stage2-a2",speakers:["Seller (البائع)","Customer (الزبون)"],turns:[{s:0,t:"Morning! What are you looking for today? We've got fresh stuff.",ar:"صباح الخير! عمَّ تبحث اليوم؟ لدينا أشياء طازجة."},{s:1,t:"Hi! I need some beef and a few vegetables. Is the beef fresh?",ar:"مرحبًا! أحتاج بعض لحم البقر وبعض الخضار. هل اللحم طازج؟"},{s:0,t:"Fresh this morning. It's better than yesterday's, I promise. The quality is excellent.",ar:"طازج من هذا الصباح. إنه أفضل من لحم الأمس، أعدك. الجودة ممتازة."},{s:1,t:"Good. And how much is it per kilo?",ar:"جيد. وكم سعره للكيلو؟"},{s:0,t:"Twelve dollars. That's cheaper than the shop downtown.",ar:"اثنا عشر دولارًا. هذا أرخص من المحل وسط المدينة."},{s:1,t:"Hmm, that's still a bit expensive for me. Can you do ten?",ar:"همم، ما زال غاليًا قليلًا بالنسبة لي. هل يمكنك أن تجعله عشرة؟"},{s:0,t:"Ten? Come on, that's too low. Eleven, and I'll add some sauce for free. That's my best offer.",ar:"عشرة؟ هيا، هذا قليل جدًا. أحد عشر، وسأضيف بعض الصلصة مجانًا. هذا أفضل عرض لدي."},{s:1,t:"Deal! Now, what about the beans? Are they cheaper here or at the market?",ar:"اتفقنا! الآن، ماذا عن الفاصوليا؟ هل هي أرخص هنا أم في السوق؟"},{s:0,t:"Here, for sure. The market is more expensive and less fresh.",ar:"هنا، بالتأكيد. السوق أغلى وأقل طزاجة."},{s:1,t:"Okay, give me a kilo of beans and some lemons too.",ar:"حسنًا، أعطني كيلو فاصوليا وبعض الليمون أيضًا."},{s:0,t:"Sure. The lemons are the sweetest ones we've had all week. Taste one!",ar:"بالتأكيد. الليمون هو أحلى ما لدينا طوال الأسبوع. تذوق واحدة!"},{s:1,t:"Nice. Do you have any dessert? Something sweet?",ar:"جميل. هل لديك أي حلوى؟ شيء حلو؟"},{s:0,t:"We've got cookies and jam. The cookies are softer than the ones at the bakery.",ar:"لدينا بسكويت ومربى. البسكويت أطرى من بسكويت المخبز."},{s:1,t:"I'll take the cookies. Oh, and a bottle of oil too.",ar:"سآخذ البسكويت. أوه، وزجاجة زيت أيضًا."},{s:0,t:"The oil is on the top shelf — the biggest bottle is the best value. It's a good quantity for the price.",ar:"الزيت على الرف العلوي — أكبر زجاجة هي الأفضل قيمة. إنها كمية جيدة مقابل السعر."},{s:1,t:"Got it. How much is everything so far?",ar:"فهمت. كم يبلغ المجموع حتى الآن؟"},{s:0,t:"Let's see... thirty-four dollars in total. That's the full amount, with tax.",ar:"لنرَ… أربعة وثلاثون دولارًا بالمجموع. هذا هو المبلغ الكامل، مع الضريبة."},{s:1,t:"Cash. Here's forty. Keep the change — no, wait, I need it!",ar:"نقدًا. هذه أربعون. احتفظ بالباقي — لا، انتظر، أحتاجه!"},{s:0,t:"Ha! Six dollars back. Here you go.",ar:"ها! ستة دولارات باقية. تفضل."},{s:1,t:"Thanks. Hey, is this restaurant yours too?",ar:"شكرًا. مهلًا، هل هذا المطعم لك أيضًا؟"},{s:0,t:"Yeah, my brother runs it. The food there is excellent, and the service is fast.",ar:"نعم، أخي يديره. الطعام هناك ممتاز، والخدمة سريعة."},{s:1,t:"I've heard that! Is it better than the place on the corner?",ar:"سمعت ذلك! هل هو أفضل من المكان الذي على الزاوية؟"},{s:0,t:"Way better. And quieter, too. You should check it out tonight.",ar:"أفضل بكثير. وأهدأ أيضًا. يجب أن تجربه الليلة."},{s:1,t:"I might. Do they have fish? I love fish more than meat.",ar:"ربما. هل لديهم سمك؟ أنا أحب السمك أكثر من اللحم."},{s:0,t:"They do, and it's the freshest fish in town. Grilled, with lemon. The smell is amazing.",ar:"لديهم، وهو أطازج سمك في المدينة. مشوي، مع الليمون. رائحته مذهلة."},{s:1,t:"Sounds great. Is it spicy? I can't eat spicy food.",ar:"يبدو رائعًا. هل هو حار؟ لا أستطيع أكل الطعام الحار."},{s:0,t:"Not at all. Mild and tasty. The chef is a real expert, and his recipes are famous.",ar:"إطلاقًا. خفيف ولذيذ. الطباخ خبير حقيقي، ووصفاته مشهورة."},{s:1,t:"Perfect. One more thing — do you have any candy for my kid?",ar:"ممتاز. شيء آخر — هل لديك أي حلوى لطفلي؟"},{s:0,t:"Sure! The red ones are the sweetest. Kids love them.",ar:"بالتأكيد! الحمراء هي الأحلى. الأطفال يحبونها."},{s:1,t:"Great, I'll take a small bag. My kid's gonna be so happy.",ar:"رائع، سآخذ كيسًا صغيرًا. طفلي سيكون سعيدًا جدًا."},{s:0,t:"I bet! Anything else? Some fruit? The apples are huge today, and they're really sweet.",ar:"أراهن على ذلك! أي شيء آخر؟ بعض الفاكهة؟ التفاح ضخم اليوم، وحلو جدًا."},{s:1,t:"No, that's it. I've spent enough for one day!",ar:"لا، هذا كل شيء. أنفقت ما يكفي ليوم واحد!"},{s:0,t:"Ha! Come back soon. Next time, I'll give you a better price — perhaps ten percent off.",ar:"ها! عُد قريبًا. في المرة القادمة، سأعطيك سعرًا أفضل — ربما خصم عشرة بالمئة."},{s:1,t:"I'll hold you to that! See you tomorrow.",ar:"سأحاسبك على ذلك! أراك غدًا."},{s:0,t:"See you! And don't forget — dinner at my brother's place tonight!",ar:"أراك! ولا تنسَ — العشاء في مطعم أخي الليلة!"},{s:1,t:"I won't forget. Bye!",ar:"لن أنسى. إلى اللقاء!"},{s:0,t:"Bye! Have a good day!",ar:"إلى اللقاء! أتمنى لك يومًا سعيدًا!"},{s:1,t:"Oh wait — I forgot the nuts! Do you have any?",ar:"أوه انتظر — نسيت المكسرات! هل لديك أي منها؟"},{s:0,t:"Sure! The almonds are over there. They're fresh and crunchy. My kids eat them every day.",ar:"بالتأكيد! اللوز هناك. إنه طازج ومقرمش. أطفالي يأكلونه كل يوم."},{s:1,t:"Give me a small bag. My mom loves them.",ar:"أعطني كيسًا صغيرًا. أمي تحبها."},{s:0,t:"Here you go. Five dollars. That's the last of them today. We sold a lot this morning.",ar:"تفضل. خمسة دولارات. هذه آخر كمية اليوم. بعنا الكثير هذا الصباح."},{s:1,t:"Lucky me! Okay, now I'm really going. Bye!",ar:"كم أنا محظوظ! حسنًا، الآن سأذهب فعلًا. إلى اللقاء!"},{s:0,t:"Bye! Don't be a stranger!",ar:"إلى اللقاء! لا تكن غريبًا!"},{s:1,t:"Never!",ar:"أبدًا!"}]}},{stage:3,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"بينما كنا نرتب البيت",grammar:{id:"en-past-continuous",title:"Past continuous",titleAr:"الماضي المستمر",covers:1},conv:{id:"en-stage3-a2",speakers:["Host (المضيف)","Guest (الضيف)"],turns:[{s:0,t:"Come in, come in! We were just moving the furniture around.",ar:"ادخل، ادخل! كنا للتو ننقل الأثاث."},{s:1,t:"Wow, your place looks different! Were you cleaning all day?",ar:"واو، بيتك يبدو مختلفًا! هل كنت تنظف طوال اليوم؟"},{s:0,t:"Pretty much. While I was washing the floor, my brother was painting the wall. It was a big task.",ar:"تقريبًا. بينما كنت أغسل الأرضية، كان أخي يدهن الجدار. كانت مهمة كبيرة."},{s:1,t:"The wall looks great. What color is that? It's so bright.",ar:"الجدار يبدو رائعًا. ما هذا اللون؟ إنه مشرق جدًا."},{s:0,t:"It's a light blue. We were looking for something fresh and calm. The color makes the room feel wide.",ar:"إنه أزرق فاتح. كنا نبحث عن شيء منعش وهادئ. اللون يجعل الغرفة تبدو واسعة."},{s:1,t:"You picked well. And the carpet? It's new, right?",ar:"اخترت جيدًا. والسجادة؟ إنها جديدة، صحيح؟"},{s:0,t:"Yeah, we bought it last week. It's softer than the old one.",ar:"نعم، اشتريناها الأسبوع الماضي. إنها أنعم من القديمة."},{s:1,t:"Nice. Were you hanging the lamp when I knocked?",ar:"جميل. هل كنت تعلّق المصباح عندما طرقت الباب؟"},{s:0,t:"Ha! Yes. I was standing on a chair, and the chair was shaking. I almost fell!",ar:"ها! نعم. كنت واقفًا على كرسي، والكرسي كان يهتز. كدت أسقط!"},{s:1,t:"Oh no! Be careful. You could've fallen and hurt your knee.",ar:"أوه لا! كن حذرًا. كان بإمكانك أن تسقط وتؤذي ركبتك."},{s:0,t:"I know, I know. My brother was laughing the whole time.",ar:"أعلم، أعلم. كان أخي يضحك طوال الوقت."},{s:1,t:"Where is he now? Was he helping with the kitchen too?",ar:"أين هو الآن؟ هل كان يساعد في المطبخ أيضًا؟"},{s:0,t:"He was fixing the stove while I was cleaning the oven.",ar:"كان يصلح الموقد بينما كنت أنظف الفرن."},{s:1,t:"The oven was so dirty. I'm glad it's clean now.",ar:"كان الفرن متسخًا جدًا. أنا سعيد أنه نظيف الآن."},{s:0,t:"Me too. While we were working, the radio was playing old songs. We were singing along loudly.",ar:"وأنا أيضًا. بينما كنا نعمل، كان الراديو يعزف أغاني قديمة. كنا نغني معها بصوت عالٍ."},{s:1,t:"That sounds fun. Were you singing along?",ar:"هذا يبدو ممتعًا. هل كنت تغني معها؟"},{s:0,t:"Of course! I was singing, he was dancing — it was a mess. We laughed until our stomachs hurt.",ar:"بالطبع! كنت أغني، وكان يرقص — كان الأمر فوضى. ضحكنا حتى آلمتنا بطوننا."},{s:1,t:"I wish I'd been here! What about the bedroom?",ar:"ليتني كنت هنا! ماذا عن غرفة النوم؟"},{s:0,t:"We were moving the bed when the phone rang.",ar:"كنا ننقل السرير عندما رن الهاتف."},{s:1,t:"And? Who was it?",ar:"وماذا؟ من كان؟"},{s:0,t:"It was Mom. She was asking about the new closet. She wants to see it this weekend.",ar:"كانت أمي. كانت تسأل عن الخزانة الجديدة. تريد رؤيتها في عطلة نهاية الأسبوع هذه."},{s:1,t:"The closet is huge! Where did you get it?",ar:"الخزانة ضخمة! من أين حصلت عليها؟"},{s:0,t:"From the shop downtown. It was the cheapest big one they had.",ar:"من المحل وسط المدينة. كانت أرخص واحدة كبيرة لديهم."},{s:1,t:"Smart. And the mirror on the wall? It looks old.",ar:"ذكي. والمرآة على الجدار؟ تبدو قديمة."},{s:0,t:"It is old. It was hanging in my grandfather's house. The frame is thick wood, very strong.",ar:"إنها قديمة. كانت معلقة في بيت جدي. إطارها خشب سميك، قوي جدًا."},{s:1,t:"Wow, that's cool. It's got a nice wooden frame.",ar:"واو، هذا رائع. إطارها الخشبي جميل."},{s:0,t:"Yeah. While I was cleaning it, I found a small crack in the corner. It's hard to see.",ar:"نعم. بينما كنت أنظفها، وجدت شرخًا صغيرًا في الزاوية. من الصعب رؤيته."},{s:1,t:"You can't even see it. It still looks beautiful.",ar:"لا يمكنك حتى رؤيته. ما زالت تبدو جميلة."},{s:0,t:"Thanks! Now sit down. I was making tea when you arrived.",ar:"شكرًا! الآن اجلس. كنت أعد الشاي عندما وصلت."},{s:1,t:"Perfect timing. I was just thinking about tea.",ar:"توقيت مثالي. كنت أفكر للتو في الشاي."},{s:0,t:"With milk or without? I was boiling the water twice — I forgot the first time, stupid me!",ar:"بالحليب أم بدونه؟ غليت الماء مرتين — نسيت في المرة الأولى، يا لي من غبي!"},{s:1,t:"Ha! Without milk, please. And maybe a cookie?",ar:"ها! بدون حليب، من فضلك. وربما بسكويتة؟"},{s:0,t:"Of course. The cookies were baking while we were talking.",ar:"بالطبع. كان البسكويت يُخبز بينما كنا نتحدث."},{s:1,t:"Mmm, I can smell them! This house feels like home now.",ar:"ممم، أستطيع شم رائحتها! هذا البيت يشعر المرء فيه بأنه في بيته الآن."},{s:0,t:"That's the idea. Stay a while — we're not done yet. There's still a lot to do.",ar:"هذه هي الفكرة. ابقَ قليلًا — لم ننتهِ بعد. ما زال هناك الكثير لنفعله."},{s:1,t:"I will. But no more chairs and lamps for me!",ar:"سأبقى. لكن لا مزيد من الكراسي والمصابيح بالنسبة لي!"},{s:0,t:"Deal. Tea first, work later.",ar:"اتفقنا. الشاي أولًا، والعمل لاحقًا."},{s:1,t:"Deal.",ar:"اتفقنا."},{s:0,t:"Oh, I almost forgot — the cookies are ready. Smell that?",ar:"أوه، كدت أنسى — البسكويت جاهز. هل تشم ذلك؟"},{s:1,t:"Mmm! They smell amazing. You're a great cook, you know.",ar:"ممم! رائحتها مذهلة. أنت طباخ رائع، كما تعلم."},{s:0,t:"Ha! I just follow my mom's recipe. She taught me everything. I was a lazy student, though!",ar:"ها! أنا فقط أتبع وصفة أمي. علمتني كل شيء. لكنني كنت طالبًا كسولًا!"},{s:1,t:"Well, she taught you well. These are delicious.",ar:"حسنًا، علمتك جيدًا. إنها لذيذة."},{s:0,t:"Thanks! Take some home for your kids. Put them in a bag — there's a paper bag on the table.",ar:"شكرًا! خذ بعضًا لبيتك لأطفالك. ضعها في كيس — يوجد كيس ورقي على الطاولة."},{s:1,t:"I will. They'll love you forever for this.",ar:"سأفعل. سيحبونك للأبد بسبب هذا."}]}},{stage:4,topic:"clothes",topicAr:"الملابس والتسوق",topicEn:"Clothes & Shopping",topicDe:"Kleidung und Einkaufen",emoji:"👕",title:"أفضل محل ملابس في المدينة",grammar:{id:"en-superlatives",title:"Superlatives",titleAr:"صيغة التفضيل العليا",covers:1},conv:{id:"en-stage4-a2",speakers:["Seller (البائع)","Customer (الزبون)"],turns:[{s:0,t:"Hi! Welcome to our shop. Are you looking for something special today? A shirt, a jacket, or something else?",ar:"مرحبًا! أهلًا بك في محلنا. هل تبحث عن شيء معين اليوم؟ قميص، أم سترة، أم شيء آخر؟"},{s:1,t:"Yeah, I need a new jacket. Something warm but not too heavy.",ar:"نعم، أحتاج سترة جديدة. شيء دافئ لكن ليس ثقيلًا جدًا."},{s:0,t:"You've come to the right place. We've got the best jackets in the city — famous all over town.",ar:"لقد جئت إلى المكان الصحيح. لدينا أفضل السترات في المدينة — مشهورة في جميع أنحاء المدينة."},{s:1,t:"That's what they all say! Show me the cheapest good one.",ar:"هذا ما يقوله الجميع! أرني أرخص واحدة جيدة."},{s:0,t:"Ha! Fair enough. This blue one is popular — soft, warm, and light.",ar:"ها! معقول. هذه الزرقاء مشهورة — ناعمة ودافئة وخفيفة."},{s:1,t:"It looks nice. But is it the warmest one you've got?",ar:"تبدو جميلة. لكن هل هي أدفأ واحدة لديك؟"},{s:0,t:"Not the warmest, but it's the most comfortable, for sure.",ar:"ليست الأدفأ، لكنها الأكثر راحة، بالتأكيد."},{s:1,t:"Hmm. What about that black one? It looks thicker.",ar:"همم. ماذا عن تلك السوداء؟ تبدو أسمك."},{s:0,t:"That one's the thickest we have. Great for cold days, but a bit heavy. The material is thick wool.",ar:"تلك هي الأسمك لدينا. رائعة للأيام الباردة، لكنها ثقيلة قليلًا. خامة الصوف سميكة."},{s:1,t:"I don't like heavy clothes. What size is the blue one?",ar:"لا أحب الملابس الثقيلة. ما مقاس الزرقاء؟"},{s:0,t:"That's a medium. Do you want to try it on?",ar:"هذا مقاس متوسط. هل تريد تجربتها؟"},{s:1,t:"Yeah, sure. Where's the changing room?",ar:"نعم، بالتأكيد. أين غرفة القياس؟"},{s:0,t:"Right over there, next to the mirror. Take your time. There's no rush at all.",ar:"هناك تمامًا، بجانب المرآة. خذ وقتك. لا عجلة إطلاقًا."},{s:1,t:"Okay... wow, it fits perfectly! And it's so soft.",ar:"حسنًا… واو، مقاسها مثالي! وهي ناعمة جدًا."},{s:0,t:"It looks great on you! That color is the best one for you. It really suits your style.",ar:"تبدو رائعة عليك! هذا اللون هو الأنسب لك. إنه يناسب أسلوبك فعلًا."},{s:1,t:"You think so? How much is it?",ar:"هل تعتقد ذلك؟ كم سعرها؟"},{s:0,t:"Sixty dollars. But today it's on sale — fifty.",ar:"ستون دولارًا. لكنها اليوم في عرض — خمسون."},{s:1,t:"Fifty is still a lot. Is there a cheaper one like it?",ar:"خمسون ما زال كثيرًا. هل توجد واحدة أرخص مثلها؟"},{s:0,t:"There's this gray one. It's the least expensive in the shop. But the fashion is a bit old.",ar:"توجد هذه الرمادية. إنها الأقل سعرًا في المحل. لكن موضتها قديمة قليلًا."},{s:1,t:"Let me see... no, the blue one is nicer. The gray is too plain.",ar:"دعني أرَ… لا، الزرقاء أجمل. الرمادية عادية جدًا."},{s:0,t:"I agree. The blue one is the prettiest jacket here, honestly.",ar:"أوافقك. الزرقاء هي أجمل سترة هنا، بصراحة."},{s:1,t:"Okay, I'll take it. But do you have a belt that goes with it?",ar:"حسنًا، سآخذها. لكن هل لديك حزام يناسبها؟"},{s:0,t:"Sure! This brown belt is the best match. It's real leather, and the buckle is silver.",ar:"بالتأكيد! هذا الحزام البني هو الأنسب. إنه جلد حقيقي، وإبزيمه فضي."},{s:1,t:"How much is the belt?",ar:"كم سعر الحزام؟"},{s:0,t:"Fifteen dollars. With the jacket, that's sixty-five in total.",ar:"خمسة عشر دولارًا. مع السترة، يصبح المجموع خمسة وستين."},{s:1,t:"Hmm, can you do sixty for both? I'm a regular customer, you know.",ar:"همم، هل يمكنك أن تجعلهما ستين معًا؟ أنا زبون دائم، كما تعلم."},{s:0,t:"You're a regular? Then sixty it is. You've got the best deal today.",ar:"أنت زبون دائم؟ إذن ستون. لقد حصلت على أفضل صفقة اليوم."},{s:1,t:"Awesome! Do you have socks too? Mine are full of holes.",ar:"رائع! هل لديك جوارب أيضًا؟ جواربي مليئة بالثقوب."},{s:0,t:"Ha! We've got the softest socks in town. Three pairs for ten dollars. They're really popular.",ar:"ها! لدينا أنعم الجوارب في المدينة. ثلاثة أزواج بعشرة دولارات. إنها مشهورة جدًا."},{s:1,t:"I'll take them. And maybe a hat? The coldest days are coming.",ar:"سآخذها. وربما قبعة؟ أبرد الأيام قادمة."},{s:0,t:"This wool hat is the warmest one we have. Try it on. It's perfect for winter.",ar:"هذه القبعة الصوفية هي أدفأ واحدة لدينا. جرّبها. إنها مثالية للشتاء."},{s:1,t:"Perfect! It fits great. How much?",ar:"مثالي! مقاسها رائع. كم سعرها؟"},{s:0,t:"Twelve dollars. So that's seventy-two in total.",ar:"اثنا عشر دولارًا. إذن يصبح المجموع اثنين وسبعين."},{s:1,t:"Okay, here's my card. This is the most I've spent on clothes in months!",ar:"حسنًا، هذه بطاقتي. هذا أكثر ما أنفقته على الملابس منذ أشهر!"},{s:0,t:"And the best you've looked in months, too. Come back soon! We get new clothes every week.",ar:"وأفضل ما بدوت عليه منذ أشهر أيضًا. عُد قريبًا! نحصل على ملابس جديدة كل أسبوع."},{s:1,t:"I will. Thanks for your help — you're the friendliest seller in the city.",ar:"سأعود. شكرًا لمساعدتك — أنت ألطف بائع في المدينة."},{s:0,t:"Aw, thanks! Have a great day!",ar:"أوه، شكرًا! أتمنى لك يومًا رائعًا!"},{s:1,t:"You too! Bye!",ar:"وأنت أيضًا! إلى اللقاء!"},{s:0,t:"Bye! See you soon!",ar:"إلى اللقاء! أراك قريبًا!"},{s:1,t:"Oh, one last thing — do you sell gloves? My hands freeze in winter.",ar:"أوه، شيء أخير — هل تبيع قفازات؟ يداي تتجمدان في الشتاء."},{s:0,t:"We do! The leather ones are the warmest. Want to check them out? They're on sale.",ar:"نعم! الجلدية هي الأدفأ. هل تريد رؤيتها؟ إنها في عرض."},{s:1,t:"Next time. My wallet's empty now!",ar:"في المرة القادمة. محفظتي فارغة الآن!"},{s:0,t:"Ha! Next time, then. Bye!",ar:"ها! إذن في المرة القادمة. إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:5,topic:"routine",topicAr:"اليوم الروتيني والمدرسة والعمل",topicEn:"Daily Routine, School & Work",topicDe:"Alltag, Schule und Arbeit",emoji:"⏰",title:"ماذا فعلت أمس؟",grammar:{id:"en-past-irregular",title:"Past simple: irregular verbs",titleAr:"الماضي البسيط: الأفعال غير المنتظمة",covers:1},conv:{id:"en-stage5-a2",speakers:["Student (الطالب)","Classmate (زميل الدراسة)"],turns:[{s:0,t:"Hey! What did you do yesterday? You look so tired.",ar:"مرحبًا! ماذا فعلت أمس؟ تبدو متعبًا جدًا."},{s:1,t:"Ugh, don't ask. I woke up late and missed the bus.",ar:"أوه، لا تسأل. استيقظت متأخرًا وفاتني الحافلة."},{s:0,t:"No way! Did you run to school?",ar:"مستحيل! هل ركضت إلى المدرسة؟"},{s:1,t:"I ran all the way. My legs still hurt.",ar:"ركضت طوال الطريق. ما زالت ساقاي تؤلمانني."},{s:0,t:"That's rough. What did the teacher say? Was she angry?",ar:"هذا قاسٍ. ماذا قال المعلم؟ هل كانت غاضبة؟"},{s:1,t:"She didn't say much. She just gave me a look, you know?",ar:"لم تقل الكثير. فقط نظرت إليّ نظرة، كما تعلم؟"},{s:0,t:"Ha! I know that look. Did you eat breakfast at least?",ar:"ها! أعرف تلك النظرة. هل تناولت الفطور على الأقل؟"},{s:1,t:"Nope. I forgot. I only drank some water.",ar:"لا. نسيت. شربت بعض الماء فقط."},{s:0,t:"That's bad. You need food. Did you buy anything at lunch? A sandwich, or something hot?",ar:"هذا سيئ. أنت بحاجة إلى طعام. هل اشتريت شيئًا في الغداء؟ ساندويتشًا، أم شيئًا ساخنًا؟"},{s:1,t:"Yeah, I bought a sandwich and an apple. It was okay.",ar:"نعم، اشتريت ساندويتشًا وتفاحة. كان مقبولًا."},{s:0,t:"What did we do in math class? I missed it too.",ar:"ماذا فعلنا في حصة الرياضيات؟ فاتتني أنا أيضًا."},{s:1,t:"We took a test. It was hard — I didn't finish it.",ar:"أجرينا اختبارًا. كان صعبًا — لم أكمله."},{s:0,t:"Oh no. Did anyone finish it? Even the smart kids?",ar:"أوه لا. هل أكمله أحد؟ حتى الأطفال الأذكياء؟"},{s:1,t:"Only two students. The teacher said it was the hardest test this year.",ar:"طالبان فقط. قالت المعلمة إنه أصعب اختبار هذا العام."},{s:0,t:"Great. Just great. What did you do after school?",ar:"رائع. رائع جدًا. ماذا فعلت بعد المدرسة؟"},{s:1,t:"I went to the library and studied for two hours.",ar:"ذهبت إلى المكتبة ودرست لمدة ساعتين."},{s:0,t:"Wow, that's serious. Did you understand the lesson? The math was really hard.",ar:"واو، هذا جدي. هل فهمت الدرس؟ كانت الرياضيات صعبة جدًا."},{s:1,t:"Mostly. I read the book again and it made sense.",ar:"غالبًا. قرأت الكتاب مرة أخرى فصار مفهومًا."},{s:0,t:"Nice. Did you watch the game last night?",ar:"جميل. هل شاهدت المباراة الليلة الماضية؟"},{s:1,t:"No, I fell asleep at nine! I was so tired.",ar:"لا، غفوت في التاسعة! كنت متعبًا جدًا."},{s:0,t:"You missed a great game. We won three to one! It was an exciting match.",ar:"فاتتك مباراة رائعة. فزنا ثلاثة لواحد! كانت مباراة مثيرة."},{s:1,t:"Are you kidding? I can't believe I missed it.",ar:"هل تمزح؟ لا أصدق أنني فاتتني."},{s:0,t:"I recorded it. Wanna watch it tonight at my place?",ar:"سجلتها. هل تريد مشاهدتها الليلة في بيتي؟"},{s:1,t:"Yes! I'll bring snacks. What do you want?",ar:"نعم! سأجلب وجبات خفيفة. ماذا تريد؟"},{s:0,t:"Bring chips and juice. And don't be late this time! The game starts at seven sharp.",ar:"اجلب رقائق وعصيرًا. ولا تتأخر هذه المرة! تبدأ المباراة في السابعة تمامًا."},{s:1,t:"Ha! I won't. I set three alarms already.",ar:"ها! لن أتأخر. ضبطت ثلاثة منبهات بالفعل."},{s:0,t:"Good. Oh, did you hear? The teacher gave us homework.",ar:"جيد. أوه، هل سمعت؟ أعطتنا المعلمة واجبًا."},{s:1,t:"Ugh. What is it? Don't tell me it's math again.",ar:"أوه. ما هو؟ لا تقل لي إنه رياضيات مرة أخرى."},{s:0,t:"It is math. Ten problems. We have to finish them by Friday. The teacher was very clear.",ar:"إنها رياضيات. عشر مسائل. يجب أن ننهيها بحلول الجمعة. كانت المعلمة واضحة جدًا."},{s:1,t:"Ten? That's too much. I hate math homework.",ar:"عشر؟ هذا كثير جدًا. أكره واجب الرياضيات."},{s:0,t:"Me too. But let's do it together tomorrow. It'll be faster — and more fun.",ar:"وأنا أيضًا. لكن لنفعله معًا غدًا. سيكون أسرع — وأكثر متعة."},{s:1,t:"Deal. I'll come to your place after lunch.",ar:"اتفقنا. سآتي إلى بيتك بعد الغداء."},{s:0,t:"Perfect. And bring your notebook — I lost mine. Again. I always lose things.",ar:"ممتاز. وأحضر دفترك — فقدت دفتري. مرة أخرى. أنا دائمًا أفقد الأشياء."},{s:1,t:"You lost it? Again? That's the third time this month!",ar:"فقدته؟ مرة أخرى؟ هذه المرة الثالثة هذا الشهر!"},{s:0,t:"I know, I know. I'm a mess. Anyway, see you tomorrow.",ar:"أعلم، أعلم. أنا فوضوي. على أي حال، أراك غدًا."},{s:1,t:"See you! And get some sleep tonight, okay?",ar:"أراك! ونم جيدًا الليلة، حسنًا؟"},{s:0,t:"I'll try. Bye!",ar:"سأحاول. إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"},{s:0,t:"Oh wait — one more thing. Did you bring your English book today?",ar:"أوه انتظر — شيء آخر. هل أحضرت كتاب الإنجليزية اليوم؟"},{s:1,t:"Yeah, it's in my bag. Why?",ar:"نعم، إنه في حقيبتي. لماذا؟"},{s:0,t:"The teacher wants it tomorrow. Don't forget it at home. She'll be really mad.",ar:"المعلمة تريده غدًا. لا تنسَه في البيت. ستغضب كثيرًا."},{s:1,t:"I won't. It's always in my bag. Trust me.",ar:"لن أنساه. إنه دائمًا في حقيبتي. صدقني."},{s:0,t:"Okay, okay. See you at seven tonight for the game. Don't be late, okay?",ar:"حسنًا، حسنًا. أراك في السابعة الليلة لمشاهدة المباراة. لا تتأخر، حسنًا؟"},{s:1,t:"Seven sharp. Don't be late!",ar:"السابعة تمامًا. لا تتأخر!"}]}},{stage:6,topic:"weather",topicAr:"الأوقات والطقس",topicEn:"Times & Weather",topicDe:"Zeiten und Wetter",emoji:"🌤️",title:"إذا مطرت، ماذا نفعل؟",grammar:{id:"en-conditional-1",title:"First conditional",titleAr:"الشرطية الأولى",covers:1},conv:{id:"en-stage6-a2",speakers:["Friend (الصديق)","Neighbor (الجار)"],turns:[{s:0,t:"Look at that sky! If it rains, we're gonna get soaked.",ar:"انظر إلى تلك السماء! إذا أمطرت، سنبتل تمامًا."},{s:1,t:"Yeah, those clouds look bad. If we leave now, we'll make it home dry.",ar:"نعم، تلك الغيوم تبدو سيئة. إذا غادرنا الآن، سنصل إلى البيت جافين."},{s:0,t:"But the game starts in ten minutes! If we stay, we'll miss the bus.",ar:"لكن المباراة تبدأ بعد عشر دقائق! إذا بقينا، سنفوت الحافلة."},{s:1,t:"I know. If it rains hard, the game will stop anyway.",ar:"أعلم. إذا أمطرت بغزارة، ستتوقف المباراة على أي حال."},{s:0,t:"True. What if we watch from the café? It's warm and dry there. They have great coffee, too.",ar:"صحيح. ماذا لو شاهدنا من المقهى؟ إنه دافئ وجاف هناك. لديهم قهوة رائعة أيضًا."},{s:1,t:"Good idea! If we go to the café, we can drink hot tea too.",ar:"فكرة جيدة! إذا ذهبنا إلى المقهى، يمكننا أن نشرب شايًا ساخنًا أيضًا."},{s:0,t:"And if it gets cold, we'll just stay inside. No problem. The café is open late.",ar:"وإذا برد الجو، سنبقى في الداخل فقط. لا مشكلة. المقهى مفتوح حتى وقت متأخر."},{s:1,t:"Wait — do you have an umbrella? I left mine at home.",ar:"انتظر — هل لديك مظلة؟ تركت مظلتي في البيت."},{s:0,t:"Nope. If we run, we'll only get a little wet.",ar:"لا. إذا ركضنا، سنبتل قليلًا فقط."},{s:1,t:"A little wet? Have you seen that rain? It's gonna pour!",ar:"قليلًا؟ هل رأيت ذلك المطر؟ إنه سيهطل بغزارة!"},{s:0,t:"Okay, okay. If we wait five minutes, the rain might stop. Let's hope so.",ar:"حسنًا، حسنًا. إذا انتظرنا خمس دقائق، قد يتوقف المطر. لنأمل ذلك."},{s:1,t:"It won't stop. Look — the wind is getting stronger.",ar:"لن يتوقف. انظر — الرياح تزداد قوة."},{s:0,t:"Hmm. If the wind gets worse, the trees might fall. That's scary. The storm is really strong.",ar:"همم. إذا ازدادت الرياح سوءًا، قد تسقط الأشجار. هذا مخيف. العاصفة قوية فعلًا."},{s:1,t:"Don't be silly. The trees are strong. But let's move, anyway.",ar:"لا تكن سخيفًا. الأشجار قوية. لكن لننتقل، على أي حال."},{s:0,t:"Where to? If we go left, we'll reach the café in two minutes.",ar:"إلى أين؟ إذا ذهبنا يسارًا، سنصل إلى المقهى في دقيقتين."},{s:1,t:"Left it is. Run!",ar:"يسارًا إذن. اركض!"},{s:0,t:"Wait for me! I'm not as fast as you!",ar:"انتظرني! لست سريعًا مثلك!"},{s:1,t:"Hurry! If we don't run, we'll be wet all day!",ar:"أسرع! إذا لم نركض، سنبقى مبللين طوال اليوم!"},{s:0,t:"I'm coming! Oh no, my shoe—",ar:"أنا قادم! أوه لا، حذائي—"},{s:1,t:"—Your shoe is fine! Keep running!",ar:"—حذاؤك بخير! واصل الركض!"},{s:0,t:"Okay, okay! We're almost there. I can see the café!",ar:"حسنًا، حسنًا! كدنا نصل. أستطيع رؤية المقهى!"},{s:1,t:"Made it! Whew. If we'd stayed outside, we'd be soaked.",ar:"وصلنا! أوف. لو بقينا في الخارج، لكنا قد ابتللنا تمامًا."},{s:0,t:"Totally. Now, if we order tea, we'll warm up fast. And the cake here is delicious.",ar:"تمامًا. الآن، إذا طلبنا شايًا، سندفأ بسرعة. والكعك هنا لذيذ."},{s:1,t:"Tea and cake! If the rain stops, we'll go back to the game.",ar:"شاي وكعك! إذا توقف المطر، سنعود إلى المباراة."},{s:0,t:"And if it doesn't stop, we'll watch it here on TV.",ar:"وإذا لم يتوقف، سنشاهده هنا على التلفاز."},{s:1,t:"Perfect plan. You know, I love rainy days like this.",ar:"خطة مثالية. تعلم، أنا أحب الأيام الممطرة مثل هذه."},{s:0,t:"Me too. If it rains tomorrow, let's do the same thing. Same time, same place.",ar:"وأنا أيضًا. إذا أمطرت غدًا، لنفعل الشيء نفسه. نفس الوقت، نفس المكان."},{s:1,t:"Deal! Same time, same café.",ar:"اتفقنا! نفس الوقت، نفس المقهى."},{s:0,t:"Deal. Now, do you want sugar in your tea? One spoon or two?",ar:"اتفقنا. الآن، هل تريد سكرًا في الشاي؟ ملعقة واحدة أم اثنتان؟"},{s:1,t:"Two spoons, please. I'm freezing!",ar:"ملعقتان، من فضلك. أنا أتجمد من البرد!"},{s:0,t:"Here you go. Hot tea fixes everything. Drink it slowly — it's really hot.",ar:"تفضل. الشاي الساخن يصلح كل شيء. اشربه ببطء — إنه ساخن جدًا."},{s:1,t:"Almost everything. My shoes are still wet!",ar:"تقريبًا كل شيء. حذائي ما زال مبللًا!"},{s:0,t:"Ha! Put them near the heater. They'll dry soon. Don't worry about it.",ar:"ها! ضعهما قرب المدفأة. سيجفان قريبًا. لا تقلق بشأن ذلك."},{s:1,t:"Good idea. Thanks, man.",ar:"فكرة جيدة. شكرًا يا صديقي."},{s:0,t:"Anytime. That's what friends are for.",ar:"في أي وقت. هذا ما يكون الأصدقاء من أجله."},{s:1,t:"Cheers to that.",ar:"نخب ذلك."},{s:0,t:"Cheers!",ar:"نخب!"},{s:1,t:"Look! The rain is stopping. The sun is coming out!",ar:"انظر! المطر يتوقف. الشمس تخرج!"},{s:0,t:"Finally! If the sun stays out, we can go back to the game. The field will be wet, though.",ar:"أخيرًا! إذا بقيت الشمس، يمكننا العودة إلى المباراة. لكن الملعب سيكون مبللًا."},{s:1,t:"Let's finish our tea first. No rush.",ar:"لننهِ شاينا أولًا. لا عجلة."},{s:0,t:"Agreed. This tea is too good to leave. And the weather is getting better every minute.",ar:"موافق. هذا الشاي جيد جدًا لتركه. والطقس يتحسن كل دقيقة."},{s:1,t:"And the cake! I want another piece.",ar:"والكعك! أريد قطعة أخرى."},{s:0,t:"Ha! Order it. If we win the game later, I'll pay. If we lose, you pay!",ar:"ها! اطلبه. إذا فزنا في المباراة لاحقًا، سأدفع. وإذا خسرنا، تدفع أنت!"},{s:1,t:"Deal!",ar:"اتفقنا!"}]}},{stage:7,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"أخبار من المكالمة",grammar:{id:"en-reported-speech",title:"Reported speech",titleAr:"الكلام المنقول",covers:1},conv:{id:"en-stage7-a2",speakers:["Caller (المتصل)","Friend (الصديق)"],turns:[{s:0,t:"Hey! I just got off the phone with my cousin. You're not gonna believe this.",ar:"مرحبًا! انتهيت للتو من مكالمة مع ابن عمي. لن تصدق هذا."},{s:1,t:"What? Tell me! What did he say?",ar:"ماذا؟ أخبرني! ماذا قال؟"},{s:0,t:"What? Tell me! What did he say? I can tell by your voice it's big news!",ar:"ماذا؟ أخبرني! ماذا قال؟ أستطيع أن أعرف من صوتك أنه خبر كبير!"},{s:1,t:"No way! Did he say why?",ar:"مستحيل! هل قال لماذا؟"},{s:0,t:"He said he got a job there. A really good one.",ar:"قال إنه حصل على وظيفة هناك. وظيفة جيدة جدًا."},{s:1,t:"Wow. Did he say where? New York? California?",ar:"واو. هل قال أين؟ نيويورك؟ كاليفورنيا؟"},{s:0,t:"He said he got a job there — a really good one. He'll earn a lot more money.",ar:"قال إنه حصل على وظيفة هناك — وظيفة جيدة جدًا. سيكسب مالًا أكثر بكثير."},{s:1,t:"Chicago! That's so cool. Did he say if he's excited?",ar:"شيكاغو! هذا رائع جدًا. هل قال إنه متحمس؟"},{s:0,t:"He told me it's in Chicago. He starts in June, and he'll live alone at first.",ar:"أخبرني أنها في شيكاغو. يبدأ في يونيو، وسيعيش وحده في البداية."},{s:1,t:"I bet. Did he ask you to visit him?",ar:"أراهن على ذلك. هل طلب منك زيارته؟"},{s:0,t:"He said he's certainly excited, but nervous too. It's a big change.",ar:"قال إنه متحمس بالتأكيد، لكنه متوتر أيضًا. إنه تغيير كبير."},{s:1,t:"Lucky you! Are you gonna go?",ar:"كم أنت محظوظ! هل ستذهب؟"},{s:0,t:"I bet. Did he ask you to visit him? I'd love an opportunity like that.",ar:"أراهن على ذلك. هل طلب منك زيارته؟ أحب فرصة مثل هذه."},{s:1,t:"What did your mom say when she heard the news?",ar:"ماذا قالت أمك عندما سمعت الخبر؟"},{s:0,t:"What did your mom say when she heard the news? Was she surprised?",ar:"ماذا قالت أمك عندما سمعت الخبر؟ هل كانت متفاجئة؟"},{s:1,t:"Of course. Did he say anything about his house here?",ar:"بالطبع. هل قال أي شيء عن بيته هنا؟"},{s:0,t:"Of course. Did he say anything about his house here? What's gonna happen to it?",ar:"بالطبع. هل قال أي شيء عن بيته هنا؟ ماذا سيحدث له؟"},{s:1,t:"Interesting. Did he mention his car?",ar:"مثير للاهتمام. هل ذكر سيارته؟"},{s:0,t:"He said he's selling that too. He wants a fresh start.",ar:"قال إنه سيبيعها أيضًا. يريد بداية جديدة."},{s:1,t:"A fresh start... I get it. Did he say goodbye to everyone?",ar:"بداية جديدة… أفهم ذلك. هل ودّع الجميع؟"},{s:0,t:"A fresh start... I get it. Did he say goodbye to everyone? Or not yet?",ar:"بداية جديدة… أفهم ذلك. هل ودّع الجميع؟ أم ليس بعد؟"},{s:1,t:"A party! When? Did he say when?",ar:"حفلة! متى؟ هل قال متى؟"},{s:0,t:"A party! When? Did he say when? I need the exact date.",ar:"حفلة! متى؟ هل قال متى؟ أحتاج إلى التاريخ الدقيق."},{s:1,t:"I'm in! Should I bring anything?",ar:"سأحضر! هل أجلب شيئًا؟"},{s:0,t:"He said next Friday, at his place. Everyone's invited. It'll be a great celebration.",ar:"قال الجمعة القادمة، في بيته. الجميع مدعوون. ستكون احتفالية رائعة."},{s:1,t:"I can do that. Oh — did he say how long the flight is?",ar:"يمكنني ذلك. أوه — هل قال كم تستغرق الرحلة؟"},{s:0,t:"I can do that. Oh — did he say how long the flight is? Fourteen hours is a long time.",ar:"يمكنني ذلك. أوه — هل قال كم تستغرق الرحلة؟ أربع عشرة ساعة مدة طويلة."},{s:1,t:"Fourteen hours! I'd go crazy on a plane that long.",ar:"أربع عشرة ساعة! سأجن على متن طائرة كل هذه المدة."},{s:0,t:"Ha! He said the same thing. But he's still going.",ar:"ها! قال الشيء نفسه. لكنه ما زال ذاهبًا."},{s:1,t:"Well, good for him. I'm really happy for him.",ar:"حسنًا، جيد له. أنا سعيد جدًا من أجله."},{s:0,t:"Well, good for him. I'm really happy for him. He deserves this chance.",ar:"حسنًا، جيد له. أنا سعيد جدًا من أجله. إنه يستحق هذه الفرصة."},{s:1,t:"He'd better! Or we'll be really mad.",ar:"من الأفضل أن يفعل! وإلا سنغضب كثيرًا."},{s:0,t:'He knows. He promised — he said, "I promise I\'ll call."',ar:"إنه يعلم. وعد — قال: «أعدك أنني سأتصل»."},{s:1,t:"Good. So, Friday, his place, party. I'm writing it down.",ar:"جيد. إذن، الجمعة، بيته، حفلة. سأكتبها."},{s:0,t:"Do that. And wear something nice! The party will be full of people.",ar:"افعل ذلك. وارتدِ شيئًا أنيقًا! ستكون الحفلة مليئة بالناس."},{s:1,t:"I will. See you Friday!",ar:"سأفعل. أراك يوم الجمعة!"},{s:0,t:"See you!",ar:"أراك!"},{s:1,t:"Wait, what time is the party? Did he say?",ar:"انتظر، في أي وقت الحفلة؟ هل قال؟"},{s:0,t:"He said seven o'clock. Don't be late — you know how he is.",ar:"قال السابعة مساءً. لا تتأخر — أنت تعرف كيف هو."},{s:1,t:"Seven. Got it. I'll be there at seven sharp.",ar:"السابعة. فهمت. سأكون هناك في السابعة تمامًا."},{s:0,t:"Good. He said he's making his famous food too.",ar:"جيد. قال إنه سيعد طعامه المشهور أيضًا."},{s:1,t:"His famous food? Now I'm really excited!",ar:"طعامه المشهور؟ الآن أنا متحمس فعلًا!"},{s:0,t:"Me too. Okay, I've gotta go. Talk later!",ar:"وأنا أيضًا. حسنًا، يجب أن أذهب. نتحدث لاحقًا!"},{s:1,t:"Talk later!",ar:"نتحدث لاحقًا!"}]}},{stage:8,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"كيف كنا نسافر من قبل؟",grammar:{id:"en-used-to",title:"Used to",titleAr:"used to (عادة في الماضي)",covers:1},conv:{id:"en-stage8-a2",speakers:["Driver (السائق)","Passenger (الراكب)"],turns:[{s:0,t:"Morning! Ready for the trip? The bus leaves in ten minutes.",ar:"صباح الخير! مستعد للرحلة؟ الحافلة تغادر بعد عشر دقائق."},{s:1,t:"Ready! I used to travel by bus all the time when I was a kid.",ar:"مستعد! كنت أسافر بالحافلة طوال الوقت عندما كنت طفلًا."},{s:0,t:"Really? We used to take the train everywhere. It was slower, but fun. The views were beautiful.",ar:"حقًا؟ كنا نركب القطار في كل مكان. كان أبطأ، لكنه ممتع. كانت المناظر جميلة."},{s:1,t:"The train? I used to hate the train. It was always so crowded.",ar:"القطار؟ كنت أكره القطار. كان مزدحمًا دائمًا."},{s:0,t:"Ha! And now you love it? People change. That's life, I suppose.",ar:"ها! والآن تحبه؟ الناس يتغيرون. هذه هي الحياة، أظن."},{s:1,t:"I do now. I used to think it was boring, but now I read on the train.",ar:"أحبه الآن. كنت أظن أنه ممل، لكنني الآن أقرأ في القطار."},{s:0,t:"Nice. Did you use to travel with your family? Every summer, or just sometimes?",ar:"جميل. هل كنت تسافر مع عائلتك؟ كل صيف، أم أحيانًا فقط؟"},{s:1,t:"Yeah, every summer. We used to visit my grandfather in the village.",ar:"نعم، كل صيف. كنا نزور جدي في القرية."},{s:0,t:"The village! We used to go there too. The road was terrible back then.",ar:"القرية! كنا نذهب إلى هناك أيضًا. كان الطريق سيئًا في ذلك الوقت."},{s:1,t:"Oh yeah. It used to take five hours! Now it takes two.",ar:"أوه نعم. كان يستغرق خمس ساعات! الآن يستغرق ساعتين."},{s:0,t:"The village! We used to go there too. The road was terrible back then — full of holes.",ar:"القرية! كنا نذهب إلى هناك أيضًا. كان الطريق سيئًا في ذلك الوقت — مليئًا بالحفر."},{s:1,t:"I remember! It was so narrow. Cars used to wait on both sides.",ar:"أتذكر! كان ضيقًا جدًا. كانت السيارات تنتظر على الجانبين."},{s:0,t:"Oh yeah. It used to take five hours! Now it takes two. The new highway is much better.",ar:"أوه نعم. كان يستغرق خمس ساعات! الآن يستغرق ساعتين. الطريق السريع الجديد أفضل بكثير."},{s:1,t:"Good thing they built a new one. Do you use to fly at all?",ar:"من الجيد أنهم بنوا واحدًا جديدًا. هل تسافر بالطائرة أبدًا؟"},{s:0,t:"And the driver used to drive so slowly over it. So careful. Everyone was scared.",ar:"وكان السائق يقود ببطء شديد فوقه. حذر جدًا. كان الجميع خائفين."},{s:1,t:"Twice a year! Where do you usually go?",ar:"مرتين في السنة! إلى أين تذهب عادة؟"},{s:0,t:"Mostly overseas, for work. Last year I went to London.",ar:"غالبًا إلى الخارج، للعمل. العام الماضي ذهبت إلى لندن."},{s:1,t:"London! I used to dream about London when I was young.",ar:"لندن! كنت أحلم بلندن عندما كنت صغيرًا."},{s:0,t:"Maybe next year. Right now, I'm saving money. Traveling overseas is expensive.",ar:"ربما العام القادم. الآن، أنا أدخر المال. السفر إلى الخارج مكلف."},{s:1,t:"Maybe next year. Right now, I'm saving money.",ar:"ربما العام القادم. الآن، أنا أدخر المال."},{s:0,t:"Smart. Hey, the bus is here. Let's get on. Hurry, before it leaves without us!",ar:"ذكي. مهلًا، الحافلة هنا. لنركب. أسرع، قبل أن تغادر بدوننا!"},{s:1,t:"Wait — I need a ticket. Do they sell them on the bus?",ar:"انتظر — أحتاج تذكرة. هل يبيعونها على الحافلة؟"},{s:0,t:"Yeah, the driver sells them. It's five dollars.",ar:"نعم، السائق يبيعها. سعرها خمسة دولارات."},{s:1,t:"Okay. Where do you wanna sit? Front or back?",ar:"حسنًا. أين تريد أن تجلس؟ في الأمام أم في الخلف؟"},{s:0,t:"Okay. Where do you wanna sit? Front or back? The front seats are more comfortable.",ar:"حسنًا. أين تريد أن تجلس؟ في الأمام أم في الخلف؟ مقاعد الأمام أكثر راحة."},{s:1,t:"Me too! Funny, we used to have the same problems.",ar:"وأنا أيضًا! مضحك، كنا نعاني من نفس المشاكل."},{s:0,t:"Front. I used to get sick in the back when I was a kid. My stomach couldn't take it.",ar:"في الأمام. كنت أشعر بالغثيان في الخلف عندما كنت طفلًا. معدتي لم تكن تتحمل ذلك."},{s:1,t:"Nice. How long is the trip? Two hours?",ar:"جميل. كم تستغرق الرحلة؟ ساعتان؟"},{s:0,t:"About two hours. We'll be there by noon.",ar:"نحو ساعتين. سنصل بحلول الظهر."},{s:1,t:"Good. I'm gonna sleep a little. Wake me up before we arrive.",ar:"جيد. سأنام قليلًا. أيقظني قبل أن نصل."},{s:0,t:"About two hours. We'll be there by noon. The route is direct, no stops.",ar:"نحو ساعتين. سنصل بحلول الظهر. الطريق مباشر، بلا توقف."},{s:1,t:"Ha! I don't snore. I used to, maybe, but not anymore.",ar:"ها! أنا لا أشخر. ربما كنت أشخر، لكن ليس بعد الآن."},{s:0,t:"Sure. But don't snore! And don't kick my seat, okay?",ar:"بالتأكيد. لكن لا تشخر! ولا تركل مقعدي، حسنًا؟"},{s:1,t:"Thanks, driver. See you in two hours.",ar:"شكرًا أيها السائق. أراك بعد ساعتين."},{s:0,t:"Ha! I don't snore. I used to, maybe, but not anymore. I sleep quietly now.",ar:"ها! أنا لا أشخر. ربما كنت أشخر، لكن ليس بعد الآن. أنام بهدوء الآن."},{s:1,t:"Oh! Sorry! Well, see you when we get there.",ar:"أوه! عذرًا! حسنًا، أراك عندما نصل."},{s:0,t:"See you then!",ar:"أراك حينها!"},{s:1,t:"Actually, one question — is there food on this bus? I'm starving.",ar:"في الحقيقة، سؤال واحد — هل يوجد طعام في هذه الحافلة؟ أنا جائع جدًا."},{s:0,t:"No food, but there's a stop in an hour. We can grab something there.",ar:"لا طعام، لكن توجد محطة بعد ساعة. يمكننا أن نأخذ شيئًا هناك."},{s:1,t:"An hour? Ugh. I should've eaten breakfast.",ar:"ساعة؟ أوه. كان يجب أن أتناول الفطور."},{s:0,t:"I have an apple. Want it?",ar:"لدي تفاحة. هل تريدها؟"},{s:1,t:"Really? You're a lifesaver. Thanks!",ar:"حقًا؟ أنت منقذ. شكرًا!"},{s:0,t:"No problem. Now sleep — I'll wake you at the stop.",ar:"لا مشكلة. الآن نم — سأوقظك عند المحطة."},{s:1,t:"You're the best. Good night — I mean, good morning!",ar:"أنت الأفضل. تصبح على خير — أعني، صباح الخير!"}]}},{stage:9,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"نصائح الطبيب",grammar:{id:"en-should-must-have-to",title:"Should, must, have to",titleAr:"should و must و have to للوجوب والنصيحة",covers:1},conv:{id:"en-stage9-a2",speakers:["Doctor (الطبيب)","Patient (المريض)"],turns:[{s:0,t:"Good morning! What brings you in today? You don't look well. Sit down and tell me.",ar:"صباح الخير! ما الذي جاء بك اليوم؟ لا تبدو بخير. اجلس وأخبرني."},{s:1,t:"Morning, Doctor. I feel terrible. I've had a fever since yesterday.",ar:"صباح الخير، دكتور. أشعر بشعور سيئ. لدي حمى منذ أمس."},{s:0,t:"A fever? How high? Did you take your temperature? And how do you feel now?",ar:"حمى؟ كم بلغت؟ هل قست حرارتك؟ وكيف تشعر الآن؟"},{s:1,t:"Yeah, it was 38.5 last night. And my head hurts a lot.",ar:"نعم، كانت 38.5 الليلة الماضية. ورأسي يؤلمني كثيرًا."},{s:0,t:"A little cough. And my throat hurts when I swallow. It burns a lot.",ar:"سعال خفيف. وحلقي يؤلمني عندما أبتلع. إنه يحرق كثيرًا."},{s:1,t:"A little cough. And my throat hurts when I swallow.",ar:"سعال خفيف. وحلقي يؤلمني عندما أبتلع."},{s:0,t:'Okay. Open your mouth, please. Say "ah."',ar:"حسنًا. افتح فمك، من فضلك. قل «آه»."},{s:1,t:"Ah...",ar:"آه…"},{s:0,t:"Your throat is red. It looks like the flu. Have you been around sick people recently?",ar:"حلقك أحمر. يبدو مثل الإنفلونزا. هل كنت قرب أشخاص مرضى مؤخرًا؟"},{s:1,t:"Yeah, my brother had the flu last week. I guess I caught it from him.",ar:"نعم، أخي أصيب بالإنفلونزا الأسبوع الماضي. أظن أنني التقطتها منه."},{s:0,t:"That makes sense. You must rest. You have to stay home for three days.",ar:"هذا منطقي. يجب أن ترتاح. عليك البقاء في البيت ثلاثة أيام."},{s:1,t:"Three days? But I have work! I can't miss three days.",ar:"ثلاثة أيام؟ لكن لدي عمل! لا أستطيع أن أغيب ثلاثة أيام."},{s:0,t:"You have to. If you work now, you'll get worse. And you'll make others ill. That's the danger.",ar:"عليك ذلك. إذا عملت الآن، ستسوء حالتك. وستجعل الآخرين مرضى. هذا هو الخطر."},{s:1,t:"You're right. What medicine should I take?",ar:"أنت محق. ما الدواء الذي يجب أن آخذه؟"},{s:0,t:"Take this medicine twice a day, after food. And drink lots of water.",ar:"خذ هذا الدواء مرتين في اليوم، بعد الطعام. واشرب الكثير من الماء."},{s:1,t:"Should I take anything for the headache?",ar:"هل يجب أن آخذ شيئًا للصداع؟"},{s:0,t:"Should I take anything for the headache? The pain is really bad.",ar:"هل يجب أن آخذ شيئًا للصداع؟ الألم سيئ جدًا."},{s:1,t:"Got it. Should I eat anything special?",ar:"فهمت. هل يجب أن آكل شيئًا معينًا؟"},{s:0,t:"Eat light food — soup, bread, fruit. You should avoid spicy food.",ar:"كل طعامًا خفيفًا — حساء، خبز، فاكهة. يجب أن تتجنب الطعام الحار."},{s:1,t:"No spicy food? Ugh. That's my favorite.",ar:"لا طعام حار؟ أوه. هذا طعامي المفضل."},{s:0,t:"Eat light food — soup, bread, fruit. You should avoid spicy food and cigarettes, too.",ar:"كل طعامًا خفيفًا — حساء، خبز، فاكهة. يجب أن تتجنب الطعام الحار والسجائر أيضًا."},{s:1,t:"Okay. What about exercise? Can I go for a run?",ar:"حسنًا. ماذا عن التمارين؟ هل يمكنني الذهاب للجري؟"},{s:0,t:"No spicy food? Ugh. That's my favorite. This is gonna be a difficult week.",ar:"لا طعام حار؟ أوه. هذا طعامي المفضل. سيكون هذا أسبوعًا صعبًا."},{s:1,t:"Fine, fine. No running. Can I at least watch TV?",ar:"حسنًا، حسنًا. لا جري. هل يمكنني على الأقل مشاهدة التلفاز؟"},{s:0,t:"Of course! TV is fine. But you should sleep a lot. Sleep helps you heal.",ar:"بالطبع! التلفاز لا بأس به. لكن يجب أن تنام كثيرًا. النوم يساعدك على الشفاء."},{s:1,t:"I'll try. I haven't slept well in days.",ar:"سأحاول. لم أنم جيدًا منذ أيام."},{s:0,t:"Fine, fine. No running. Can I at least watch TV? Or listen to music?",ar:"حسنًا، حسنًا. لا جري. هل يمكنني على الأقل مشاهدة التلفاز؟ أو الاستماع إلى الموسيقى؟"},{s:1,t:"Eight hours? I'll do my best.",ar:"ثماني ساعات؟ سأبذل قصارى جهدي."},{s:0,t:"Of course! TV is fine. But you should sleep a lot. Sleep helps you heal. Your body needs it.",ar:"بالطبع! التلفاز لا بأس به. لكن يجب أن تنام كثيرًا. النوم يساعدك على الشفاء. جسمك يحتاجه."},{s:1,t:"Three days. Okay. How much do I owe you?",ar:"ثلاثة أيام. حسنًا. كم أدين لك؟"},{s:0,t:"Fifty dollars for the visit. The medicine is extra.",ar:"خمسون دولارًا للزيارة. الدواء إضافي."},{s:1,t:"Here's my card. Thanks, Doctor. You've been really helpful.",ar:"هذه بطاقتي. شكرًا، دكتور. كنت متعاونًا جدًا."},{s:0,t:"Good. Now, you should come back in three days so I can check you again. Don't forget.",ar:"جيد. الآن، يجب أن تعود بعد ثلاثة أيام لأفحصك مرة أخرى. لا تنسَ."},{s:1,t:"I promise. Bye!",ar:"أعدك. إلى اللقاء!"},{s:0,t:"Bye! Take care!",ar:"إلى اللقاء! اعتنِ بنفسك!"},{s:1,t:"Oh, Doctor, one last thing — can I drink coffee?",ar:"أوه، دكتور، شيء أخير — هل يمكنني شرب القهوة؟"},{s:0,t:"You're welcome. Get well soon — and remember, no work, no running! Rest is the best medicine.",ar:"على الرحب والسعة. أتمنى لك الشفاء العاجل — وتذكر، لا عمل، لا جري! الراحة هي أفضل دواء."},{s:1,t:"Okay, water it is. And fruit juice?",ar:"حسنًا، الماء إذن. وعصير الفاكهة؟"},{s:0,t:"Fruit juice is fine too. Just no cold drinks with ice.",ar:"عصير الفاكهة جيد أيضًا. فقط لا مشروبات باردة مع الثلج."},{s:1,t:"Got it. No ice. Anything else I should know?",ar:"فهمت. لا ثلج. أي شيء آخر يجب أن أعرفه؟"},{s:0,t:"Yes — wash your hands often. You don't want to make your family ill.",ar:"نعم — اغسل يديك كثيرًا. لا تريد أن تجعل عائلتك مرضى."},{s:1,t:"I will. Thanks again, Doctor!",ar:"سأفعل. شكرًا مرة أخرى، دكتور!"},{s:0,t:"Okay, water it is. And fruit juice? Juice is good for me, right?",ar:"حسنًا، الماء إذن. وعصير الفاكهة؟ العصير جيد لي، صحيح؟"},{s:1,t:"I'm going. Bye!",ar:"أنا ذاهب. إلى اللقاء!"}]}},{stage:10,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"هواية جديدة",grammar:{id:"en-phrasal-verbs",title:"Phrasal verbs",titleAr:"الأفعال المركبة",covers:1},conv:{id:"en-stage10-a2",speakers:["Player (اللاعب)","Friend (الصديق)"],turns:[{s:0,t:"Hey! You're late. The game started ten minutes ago! We already missed the first goal!",ar:"مرحبًا! تأخرت. بدأت المباراة قبل عشر دقائق! لقد فاتنا الهدف الأول بالفعل!"},{s:1,t:"Sorry! I got stuck in traffic. Did I miss anything good?",ar:"عذرًا! علقت في الزحام. هل فاتني شيء جيد؟"},{s:0,t:"Yeah, we scored already! It was an amazing goal.",ar:"نعم، سجلنا بالفعل! كان هدفًا مذهلًا."},{s:1,t:"No way! Who scored?",ar:"مستحيل! من سجل؟"},{s:0,t:"I heard he's a real athlete. Did he play professional before? He looks really strong.",ar:"سمعت أنه رياضي حقيقي. هل لعب احترافيًا من قبل؟ يبدو قويًا جدًا."},{s:1,t:"I heard he's a real athlete. Did he play professional before?",ar:"سمعت أنه رياضي حقيقي. هل لعب احترافيًا من قبل؟"},{s:0,t:"I think so. He used to play for a big team. Anyway, sit down!",ar:"أظن ذلك. كان يلعب لفريق كبير. على أي حال، اجلس!"},{s:1,t:"Okay, okay. So, what's the score now?",ar:"حسنًا، حسنًا. إذن، ما النتيجة الآن؟"},{s:0,t:"Then go for it! The coach is looking for new players. You have the ability, I'm sure.",ar:"إذن، افعلها! المدرب يبحث عن لاعبين جدد. لديك القدرة، أنا متأكد."},{s:1,t:"We will. Hey, I've been thinking — I wanna try out for the team too.",ar:"سنفعل. مهلًا، كنت أفكر — أريد أن أجرب نفسي للفريق أيضًا."},{s:0,t:"You? Really? When did you get into soccer?",ar:"أنت؟ حقًا؟ متى بدأت تهتم بكرة القدم؟"},{s:1,t:"I mean, I used to play as a kid. I was pretty good.",ar:"أعني، كنت ألعب عندما كنت طفلًا. كنت جيدًا جدًا."},{s:0,t:"You're right. When's the next training? I need the schedule — the exact days and times.",ar:"أنت محق. متى التدريب القادم؟ أحتاج الجدول — الأيام والأوقات الدقيقة."},{s:1,t:"I'm nervous, though. What if I mess up?",ar:"لكنني متوتر. ماذا لو أخطأت؟"},{s:0,t:"Come on! Everyone messes up sometimes. You just gotta try.",ar:"هيا! الجميع يخطئ أحيانًا. عليك فقط أن تحاول."},{s:1,t:"You're right. When's the next training?",ar:"أنت محق. متى التدريب القادم؟"},{s:0,t:"I won't. I've been running every morning this week. My legs are stronger already.",ar:"لن أستسلم. كنت أركض كل صباح هذا الأسبوع. ساقاي أقوى بالفعل."},{s:1,t:"Tuesday, six, early. Got it. What should I practice?",ar:"الثلاثاء، السادسة، مبكرًا. فهمت. ماذا يجب أن أتدرب؟"},{s:0,t:"Work on your running and your kicks. And don't give up easily.",ar:"تدرّب على الجري والركل. ولا تستسلم بسهولة."},{s:1,t:"I won't. I've been running every morning this week.",ar:"لن أستسلم. كنت أركض كل صباح هذا الأسبوع."},{s:0,t:"Yes! This is the best game ever! The crowd is going wild!",ar:"نعم! هذه أفضل مباراة على الإطلاق! الجمهور يجن!"},{s:1,t:"Oh! Pass it! Pass it! Yes! Shoot!",ar:"أوه! مررها! مررها! نعم! سدد!"},{s:0,t:"I know! We might actually win the whole competition. That would be incredible.",ar:"أعلم! قد نفوز فعلًا بالبطولة كلها. سيكون ذلك مذهلًا."},{s:1,t:"Yes! This is the best game ever!",ar:"نعم! هذه أفضل مباراة على الإطلاق!"},{s:0,t:"I know! We might actually win the whole competition.",ar:"أعلم! قد نفوز فعلًا بالبطولة كلها."},{s:1,t:"Don't jinx it! There's still twenty minutes left.",ar:"لا تنحسها! ما زالت هناك عشرون دقيقة."},{s:0,t:"Me neither. Hey, after the game, wanna hang out? Grab some food? I'm starving.",ar:"وأنا أيضًا. مهلًا، بعد المباراة، هل تريد أن نقضي وقتًا معًا؟ نأكل شيئًا؟ أنا جائع جدًا."},{s:1,t:"I can't calm down! This is so exciting!",ar:"لا أستطيع أن أهدأ! هذا مثير جدًا!"},{s:0,t:"Me neither. Hey, after the game, wanna hang out? Grab some food?",ar:"وأنا أيضًا. مهلًا، بعد المباراة، هل تريد أن نقضي وقتًا معًا؟ نأكل شيئًا؟"},{s:1,t:"Sure! I'm starving. Let's check out that new place downtown.",ar:"بالتأكيد! أنا جائع جدًا. لنجرب ذلك المكان الجديد وسط المدينة."},{s:0,t:"Deal. Oh look — the game is starting again. Focus! No more talking.",ar:"اتفقنا. أوه انظر — المباراة تبدأ من جديد. ركّز! لا مزيد من الكلام."},{s:1,t:"Deal. Oh look — the game is starting again. Focus!",ar:"اتفقنا. أوه انظر — المباراة تبدأ من جديد. ركّز!"},{s:0,t:"I'm focused! Come on, guys! Let's go!",ar:"أنا مركز! هيا يا شباب! لننطلق!"},{s:1,t:"Let's go!",ar:"هيا!"},{s:0,t:"If we win this, I'll buy you dinner. If we lose, I'll still buy you dinner — I'm in a good mood.",ar:"إذا فزنا بهذه، سأشتري لك العشاء. وإذا خسرنا، سأشتري لك العشاء أيضًا — أنا في مزاج جيد."},{s:1,t:"And if we lose, I'll buy you dinner. Deal?",ar:"وإذا خسرنا، سأشتري لك العشاء. اتفقنا؟"},{s:0,t:"Deal!",ar:"اتفقنا!"},{s:1,t:"Look, the game is almost over. Five minutes left!",ar:"انظر، المباراة على وشك الانتهاء. خمس دقائق متبقية!"},{s:0,t:"They're coming close... no! Our goalkeeper saved it! What a save!",ar:"إنهم يقتربون… لا! حارس مرمانا أنقذها! يا له من تصدٍّ!"},{s:1,t:"They're coming close... no! Our goalkeeper saved it!",ar:"إنهم يقتربون… لا! حارس مرمانا أنقذها!"},{s:0,t:"What a save! He's the hero of the game!",ar:"يا له من تصدٍّ! إنه بطل المباراة!"},{s:1,t:"It's over! We won! Two to zero!",ar:"انتهت! فزنا! اثنان لصفر!"},{s:0,t:"Yes! Dinner's on me, remember? Let's go eat! We deserve it after this game.",ar:"نعم! العشاء عليّ، تذكر؟ لنذهب لنأكل! نستحق ذلك بعد هذه المباراة."},{s:1,t:"I remember! Let's go!",ar:"أتذكر! لنذهب!"}]}},{stage:11,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"خطط للمستقبل",grammar:{id:"en-will-going-to",title:"Will and going to",titleAr:"will و going to (المستقبل)",covers:1},conv:{id:"en-stage11-a2",speakers:["Teacher (المعلم)","Cook (الطباخ)"],turns:[{s:0,t:"So, what do you wanna be when you grow up? I mean, after school? What's your dream?",ar:"إذن، ماذا تريد أن تكون عندما تكبر؟ أعني، بعد المدرسة؟ ما حلمك؟"},{s:1,t:"Hmm. I've been thinking about it a lot. I think I'll be a cook.",ar:"همم. كنت أفكر في ذلك كثيرًا. أظن أنني سأكون طباخًا."},{s:0,t:"A cook! That's great. You're already a good cook.",ar:"طباخ! هذا رائع. أنت بالفعل طباخ جيد."},{s:1,t:"Thanks! I love cooking. My mom taught me everything.",ar:"شكرًا! أحب الطبخ. أمي علمتني كل شيء."},{s:0,t:"So what's your plan? Are you gonna study cooking? There's a good school downtown.",ar:"إذن ما خطتك؟ هل ستدرس الطبخ؟ توجد مدرسة جيدة وسط المدينة."},{s:1,t:"Yeah, I'm going to apply to a cooking school next year.",ar:"نعم، سأتقدم إلى مدرسة طهي العام القادم."},{s:0,t:"Nice! And after that? Will you work in a restaurant? Or open your own place immediately?",ar:"جميل! وبعد ذلك؟ هل ستعمل في مطعم؟ أم تفتح مكانك الخاص فورًا؟"},{s:1,t:"At first, yes. I'll work in a small restaurant and learn from the chef.",ar:"في البداية، نعم. سأعمل في مطعم صغير وأتعلم من الطباخ."},{s:0,t:"Smart plan. And one day, you'll open your own place, right? Your own business.",ar:"خطة ذكية. وفي يوم ما، ستفتح مكانك الخاص، صحيح؟ عملك الخاص."},{s:1,t:"That's the dream! I'll have my own restaurant with my own menu.",ar:"هذا هو الحلم! سيكون لدي مطعمي الخاص بقائمتي الخاصة."},{s:0,t:"I can see it now. What kind of food will you serve?",ar:"أستطيع رؤيته الآن. ما نوع الطعام الذي ستقدمه؟"},{s:1,t:"Everything! But mostly traditional food. My grandmother's recipes.",ar:"كل شيء! لكن غالبًا الطعام التقليدي. وصفات جدتي."},{s:0,t:"Oh, I love traditional food. Your grandmother's recipes are the best. I remember her soup.",ar:"أوه، أحب الطعام التقليدي. وصفات جدتك هي الأفضل. أتذكر حساءها."},{s:1,t:"They are! I'm gonna learn them all by heart.",ar:"إنها كذلك! سأتعلمها جميعًا عن ظهر قلب."},{s:0,t:"Ha! That's a lot of recipes. Will you hire other cooks too?",ar:"ها! هذه وصفات كثيرة. هل ستوظف طباخين آخرين أيضًا؟"},{s:1,t:"Of course. I'll need a team. Maybe five or six people.",ar:"بالطبع. سأحتاج فريقًا. ربما خمسة أو ستة أشخاص."},{s:0,t:"Of course. I'll need a team. Maybe five or six people. A good assistant, too.",ar:"بالطبع. سأحتاج فريقًا. ربما خمسة أو ستة أشخاص. ومساعد جيد أيضًا."},{s:1,t:"Yeah, I'll need a good manager. Money is not my strong point.",ar:"نعم، سأحتاج مديرًا جيدًا. المال ليس نقطة قوتي."},{s:0,t:"Don't worry. You'll figure it out. You're smart.",ar:"لا تقلق. ستفهم الأمر. أنت ذكي."},{s:1,t:"I hope so. What about you? What are you gonna do?",ar:"أتمنى ذلك. ماذا عنك؟ ماذا ستفعل؟"},{s:0,t:"Don't worry. You'll figure it out. You're smart. And I'll help you if you need me.",ar:"لا تقلق. ستفهم الأمر. أنت ذكي. وسأساعدك إذا احتجتني."},{s:1,t:"A teacher! That suits you. You're so patient.",ar:"معلم! هذا يناسبك. أنت صبور جدًا."},{s:0,t:"Me? I'm going to be a teacher. An English teacher. I've wanted this for years.",ar:"أنا؟ سأكون معلمًا. معلم إنجليزية. أردت هذا لسنوات."},{s:1,t:"Four years is long. Will you work while you study?",ar:"أربع سنوات طويلة. هل ستعمل أثناء الدراسة؟"},{s:0,t:"Yeah, I'll work part-time. Maybe in a shop or a café.",ar:"نعم، سأعمل بدوام جزئي. ربما في محل أو مقهى."},{s:1,t:"That'll be hard, but you'll manage. You're strong.",ar:"سيكون ذلك صعبًا، لكنك ستدبر أمرك. أنت قوي."},{s:0,t:"That'll be hard, but you'll manage. You're strong. And teaching is a great profession.",ar:"سيكون ذلك صعبًا، لكنك ستدبر أمرك. أنت قوي. والتدريس مهنة عظيمة."},{s:1,t:"Little kids? They can be wild! Are you sure?",ar:"أطفال صغار؟ يمكن أن يكونوا مشاغبين! هل أنت متأكد؟"},{s:0,t:"Ha! I'm sure. I love kids. They make me laugh every day.",ar:"ها! أنا متأكد. أحب الأطفال. يجعلونني أضحك كل يوم."},{s:1,t:"Okay, I believe you. Hey — in ten years, I'll cook, you'll teach.",ar:"حسنًا، أصدقك. مهلًا — بعد عشر سنوات، سأطبخ، وأنت ستعلّم."},{s:0,t:"Ha! I'm sure. I love kids. They make me laugh every day. Little kids are the best.",ar:"ها! أنا متأكد. أحب الأطفال. يجعلونني أضحك كل يوم. الأطفال الصغار هم الأفضل."},{s:1,t:"Yeah. Let's make a promise: in ten years, we meet here again.",ar:"نعم. لنتعاهد: بعد عشر سنوات، نلتقي هنا مرة أخرى."},{s:0,t:"Promise! And I'll bring my students to your restaurant.",ar:"أعدك! وسأجلب طلابي إلى مطعمك."},{s:1,t:"And I'll cook them the best meal ever. Deal?",ar:"وسأطبخ لهم أفضل وجبة على الإطلاق. اتفقنا؟"},{s:0,t:"Yeah. Let's make a promise: in ten years, we meet here again. Same place, same time.",ar:"نعم. لنتعاهد: بعد عشر سنوات، نلتقي هنا مرة أخرى. نفس المكان، نفس الوقت."},{s:1,t:"You know what? I'm gonna start tomorrow. No waiting.",ar:"تعلم ماذا؟ سأبدأ غدًا. بلا انتظار."},{s:0,t:"Tomorrow? That's fast! What will you do first?",ar:"غدًا؟ هذا سريع! ماذا ستفعل أولًا؟"},{s:1,t:"I'll watch cooking videos and practice my grandmother's soup.",ar:"سأشاهد فيديوهات طبخ وأتدرب على حساء جدتي."},{s:0,t:"You know what? I'm gonna start tomorrow. No waiting. I'll watch cooking videos and practice.",ar:"تعلم ماذا؟ سأبدأ غدًا. بلا انتظار. سأشاهد فيديوهات طبخ وأتدرب."},{s:1,t:"See? We're already on our way. Ten years will fly by.",ar:"أرأيت؟ نحن في طريقنا بالفعل. عشر سنوات ستمر بسرعة."},{s:0,t:"They will. Hey, thanks for talking about this with me.",ar:"ستمر. مهلًا، شكرًا لتحدثك معي عن هذا."},{s:1,t:"Anytime. That's what friends are for, right?",ar:"في أي وقت. هذا ما يكون الأصدقاء من أجله، صحيح؟"},{s:0,t:"They will. Hey, thanks for talking about this with me. It really helped me think.",ar:"ستمر. مهلًا، شكرًا لتحدثك معي عن هذا. لقد ساعدني فعلًا على التفكير."},{s:1,t:"Oh no! Run!",ar:"أوه لا! اركض!"}]}},{stage:12,topic:"services",topicAr:"الخدمات والطوارئ",topicEn:"Services & Emergencies",topicDe:"Dienstleistungen und Notfälle",emoji:"🏦",title:"في المدينة: طلبات وخدمات",grammar:{id:"en-passive",title:"Passive voice",titleAr:"المبني للمجهول",covers:1},conv:{id:"en-stage12-a2",speakers:["Customer (الزبون)","Friend (الصديق)"],turns:[{s:0,t:"Hi! I need some help. My phone was stolen yesterday. It was a terrible day.",ar:"مرحبًا! أحتاج بعض المساعدة. سُرق هاتفي أمس. كان يومًا فظيعًا."},{s:1,t:"Oh no! I'm so sorry. Was it reported to the police?",ar:"أوه لا! أنا آسف جدًا. هل أبلغت الشرطة؟"},{s:0,t:"Yes, it was reported this morning. They said they'll look for it.",ar:"نعم، أُبلغت هذا الصباح. قالوا إنهم سيبحثون عنه."},{s:1,t:"Good. Do you need a new phone? We have some good ones here.",ar:"جيد. هل تحتاج هاتفًا جديدًا؟ لدينا بعض الهواتف الجيدة هنا."},{s:0,t:"Maybe. But first, my number needs to be blocked. Can it be done here? Immediately?",ar:"ربما. لكن أولًا، يجب حظر رقمي. هل يمكن فعل ذلك هنا؟ فورًا؟"},{s:1,t:"Yes, it can be done right now. I'll just need your ID.",ar:"نعم، يمكن فعله الآن. سأحتاج فقط إلى هويتك."},{s:0,t:"Here it is. How long will it take?",ar:"هذه هي. كم سيستغرق الأمر؟"},{s:1,t:"Five minutes. While we wait, would you like to look at the new phones?",ar:"خمس دقائق. بينما ننتظر، هل تود إلقاء نظرة على الهواتف الجديدة؟"},{s:0,t:"Here it is. How long will it take? I don't have much time today.",ar:"هذه هي. كم سيستغرق الأمر؟ ليس لدي وقت كثير اليوم."},{s:1,t:"It's the newest model. It's sold all over the world.",ar:"إنه أحدث طراز. يُباع في جميع أنحاء العالم."},{s:0,t:"How much is it?",ar:"كم سعره؟"},{s:1,t:"Four hundred dollars. But it can be paid in parts — monthly.",ar:"أربعمئة دولار. لكن يمكن دفعه على أقساط — شهريًا."},{s:0,t:"Sure. This one looks nice. Is it expensive? What's the price?",ar:"بالتأكيد. هذا يبدو جميلًا. هل هو غالٍ؟ ما السعر؟"},{s:1,t:"Forty dollars a month, for ten months. No extra money.",ar:"أربعون دولارًا في الشهر، لمدة عشرة أشهر. بدون مال إضافي."},{s:0,t:"Not bad. Is the camera good? I take a lot of photos.",ar:"ليس سيئًا. هل الكاميرا جيدة؟ ألتقط الكثير من الصور."},{s:1,t:"Excellent. It's used by professional photographers, actually.",ar:"ممتازة. يستخدمها مصورون محترفون، في الحقيقة."},{s:0,t:"Monthly? That's good. How much per month? Forty dollars is okay for me.",ar:"شهريًا؟ هذا جيد. كم في الشهر؟ أربعون دولارًا مقبول بالنسبة لي."},{s:1,t:"This battery lasts two days. It's the best one we've ever sold.",ar:"هذه البطارية تدوم يومين. إنها أفضل واحدة بعناها على الإطلاق."},{s:0,t:"Two days! Okay, I'm interested. Can I keep my old number?",ar:"يومان! حسنًا، أنا مهتم. هل يمكنني الاحتفاظ برقمي القديم؟"},{s:1,t:"Yes, your number can be kept. We'll move it to the new phone.",ar:"نعم، يمكن الاحتفاظ برقمك. سننقله إلى الهاتف الجديد."},{s:0,t:"Not bad. Is the camera good? I take a lot of photos. I love photography.",ar:"ليس سيئًا. هل الكاميرا جيدة؟ ألتقط الكثير من الصور. أحب التصوير."},{s:1,t:"Were they saved to the cloud? If yes, they can be downloaded again.",ar:"هل حُفظت في السحابة؟ إذا كان الأمر كذلك، يمكن تنزيلها مرة أخرى."},{s:0,t:"I think so. I hope so. My family photos were on that phone.",ar:"أظن ذلك. أتمنى ذلك. كانت صور عائلتي على ذلك الهاتف."},{s:1,t:"Don't worry. We'll check. Now, your number is blocked. Done!",ar:"لا تقلق. سنتحقق. الآن، تم حظر رقمك. انتهى!"},{s:0,t:"Two days! Okay, I'm interested. Can I keep my old number? It's important to me.",ar:"يومان! حسنًا، أنا مهتم. هل يمكنني الاحتفاظ برقمي القديم؟ إنه مهم بالنسبة لي."},{s:1,t:"You're welcome. So, do you want the new phone?",ar:"على الرحب والسعة. إذن، هل تريد الهاتف الجديد؟"},{s:0,t:"Yeah, I'll take it. Let's do it.",ar:"نعم، سآخذه. لنفعلها."},{s:1,t:"Great! I'll set it up for you. It'll be ready in ten minutes.",ar:"رائع! سأجهزه لك. سيكون جاهزًا في عشر دقائق."},{s:0,t:"I think so. I hope so. My family photos were on that phone. All my memories.",ar:"أظن ذلك. أتمنى ذلك. كانت صور عائلتي على ذلك الهاتف. كل ذكرياتي."},{s:1,t:"Of course! Here you go.",ar:"بالطبع! تفضل."},{s:0,t:"Don't worry. We'll check. Now, your number is blocked. Done! It was quick.",ar:"لا تقلق. سنتحقق. الآن، تم حظر رقمك. انتهى! كان سريعًا."},{s:1,t:"Good. She sounds worried. Tell her we'll take care of you.",ar:"جيد. تبدو قلقة. أخبرها أننا سنعتني بك."},{s:0,t:"I will. Okay, is my phone ready?",ar:"سأفعل. حسنًا، هل هاتفي جاهز؟"},{s:1,t:"Almost. Just one more minute.",ar:"تقريبًا. دقيقة واحدة أخرى فقط."},{s:0,t:"Great! I'll set it up for you. It'll be ready in ten minutes. Just wait here.",ar:"رائع! سأجهزه لك. سيكون جاهزًا في عشر دقائق. انتظر هنا فقط."},{s:1,t:"Thank you! That's really nice to hear.",ar:"شكرًا لك! هذا لطيف جدًا أن أسمعه."},{s:0,t:"You're welcome. I'll tell all my friends about this place.",ar:"على الرحب والسعة. سأخبر جميع أصدقائي عن هذا المكان."},{s:1,t:"Please do! Have a great day!",ar:"افعل ذلك من فضلك! أتمنى لك يومًا رائعًا!"},{s:0,t:"Good. She sounds worried. Tell her we'll take care of you. Don't worry about a thing.",ar:"جيد. تبدو قلقة. أخبرها أننا سنعتني بك. لا تقلق بشأن أي شيء."},{s:1,t:"Sure! The SIM is free with the new phone.",ar:"بالتأكيد! الشريحة مجانية مع الهاتف الجديد."},{s:0,t:"I will. Okay, is my phone ready? I need to call my boss and tell him everything.",ar:"سأفعل. حسنًا، هل هاتفي جاهز؟ أحتاج إلى الاتصال بمديري وإخباره بكل شيء."},{s:1,t:"That's how we do it here. Take care, and good luck!",ar:"هكذا نفعل الأمور هنا. اعتنِ بنفسك، وحظًا سعيدًا!"},{s:0,t:"Thanks! Bye!",ar:"شكرًا! إلى اللقاء!"},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:13,topic:"culture",topicAr:"الثقافة والقصص اليومية",topicEn:"Culture & Daily Stories",topicDe:"Kultur und Alltagsgeschichten",emoji:"🎭",title:"حكايات الجد في رمضان",grammar:{id:"en-reported-speech",title:"Reported speech",titleAr:"الكلام المنقول",covers:1},conv:{id:"en-stage13-a2",speakers:["Grandfather (الجد)","Grandson (الحفيد)"],turns:[{s:0,t:"Grandpa, tell me a story! Mom said you tell the best stories. Oh my God, I love your stories!",ar:"جدي، احكِ لي قصة! قالت أمي إنك تحكي أفضل القصص. يا إلهي، أنا أحب قصصك!"},{s:1,t:"Ha! Sit down, my boy. Which one do you want? The king or the frog? The queen loved the frog too, and the whole palace laughed at his dream.",ar:"ها! اجلس يا بني. أي واحدة تريد؟ الملك أم الضفدع؟ وكانت الملكة تحب الضفدع أيضًا، وضحك القصر كله على حلمه."},{s:0,t:"The frog! No wait — the king! Hmm, the frog.",ar:"الضفدع! لا انتظر — الملك! همم، الضفدع."},{s:1,t:"The frog it is. A long, long time ago, in an ancient village, there lived a little frog. He lived near a deep lake, under a tall tower.",ar:"الضفدع إذن. منذ زمن طويل، طويل، في قرية قديمة، كان يعيش ضفدع صغير. كان يعيش قرب بحيرة عميقة، تحت برج طويل."},{s:0,t:"Was he a normal frog, or a magic one?",ar:"هل كان ضفدعًا عاديًا، أم سحريًا؟"},{s:1,t:"Ah, good question! He was a normal frog, but he had a big dream. He dreamed about the moon, the desert, and the sea.",ar:"آه، سؤال جيد! كان ضفدعًا عاديًا، لكن كان لديه حلم كبير. كان يحلم بالقمر، والصحراء، والبحر."},{s:0,t:"What did he dream about?",ar:"بماذا كان يحلم؟"},{s:1,t:'He dreamed about the moon. Every night, he looked up and said, "One day, I\'ll touch the moon." He wanted to see other planets and the stars, but the moon was his first goal.',ar:"كان يحلم بالقمر. كل ليلة، كان ينظر إلى الأعلى ويقول: «يومًا ما، سألمس القمر». أراد أن يرى الكواكب الأخرى والنجوم، لكن القمر كان هدفه الأول."},{s:0,t:"That's impossible! Frogs can't touch the moon!",ar:"هذا مستحيل! الضفادع لا تستطيع لمس القمر!"},{s:1,t:"That's what all the other animals said. The monkey laughed at him. The monkey lived in the forest, high in the trees, and he laughed all day.",ar:"هذا ما قالته كل الحيوانات الأخرى. ضحك القرد عليه. كان القرد يعيش في الغابة، عاليًا في الأشجار، وكان يضحك طوال اليوم."},{s:0,t:"The monkey? What did he say?",ar:"القرد؟ ماذا قال؟"},{s:1,t:'He said, "Little frog, you\'re crazy! The moon is too far." He jumped over the bridge every morning, and his legs got stronger.',ar:"قال: «أيها الضفدع الصغير، أنت مجنون! القمر بعيد جدًا». كان يقفز فوق الجسر كل صباح، وصارت ساقاه أقوى."},{s:0,t:"Mean monkey! What did the frog do?",ar:"قرد شرير! ماذا فعل الضفدع؟"},{s:1,t:"He didn't give up. He practiced jumping every single day. The spider watched him quietly from her web, day after day.",ar:"لم يستسلم. تدرب على القفز كل يوم. كانت العنكبوت تراقبه بهدوء من شبكتها، يومًا بعد يوم."},{s:0,t:"Every day? For how long?",ar:"كل يوم؟ لمدة كم؟"},{s:1,t:"For a whole year! He jumped higher and higher. The spider watched him from her web. She said his dream was beautiful, and she gave him a secret gift.",ar:"لمدة عام كامل! قفز أعلى وأعلى. كانت العنكبوت تراقبه من شبكتها. قالت إن حلمه جميل، وأعطته هدية سرية."},{s:0,t:"Did the spider laugh too?",ar:"هل ضحكت العنكبوت أيضًا؟"},{s:1,t:'No! She said, "Keep going, little friend. I believe in you." From the hill he could see the whole valley, the river, and the village.',ar:"لا! قالت: «واصل، أيها الصديق الصغير. أنا أؤمن بك». من التلة كان يستطيع رؤية الوادي كله، والنهر، والقرية."},{s:0,t:"Nice spider. So, did he reach the moon?",ar:"عنكبوت لطيفة. إذن، هل وصل إلى القمر؟"},{s:1,t:"Not the moon... but one night, he jumped so high that he landed on a high hill. The night was quiet, and the moon looked enormous in the dark sky.",ar:"ليس إلى القمر… لكن في إحدى الليالي، قفز عاليًا جدًا حتى هبط على تلة عالية. كانت الليلة هادئة، وبدا القمر ضخمًا في السماء المظلمة."},{s:0,t:"And? What did he see from the hill?",ar:"وماذا؟ ماذا رأى من التلة؟"},{s:1,t:"He saw the whole village, the lake, and the moon — big and bright, right in front of him. He felt alive again, and he told the story to all his friends.",ar:"رأى القرية كلها، والبحيرة، والقمر — كبيرًا ومشرقًا، أمامه مباشرة. شعر بأنه حي مرة أخرى، وحكى القصة لجميع أصدقائه."},{s:0,t:"Wow! So he was happy, even without touching it?",ar:"واو! إذن كان سعيدًا، حتى دون أن يلمسه؟"},{s:1,t:'Exactly! He said, "I didn\'t touch the moon, but I got closer than anyone ever did."',ar:"بالضبط! قال: «لم ألمس القمر، لكنني اقتربت منه أكثر من أي أحد»."},{s:0,t:"That's a great story, Grandpa. What's the lesson?",ar:"هذه قصة رائعة يا جدي. ما العبرة؟"},{s:1,t:"The lesson is: dream big, work hard, and don't listen to people who laugh at you.",ar:"العبرة هي: احلم كبيرًا، واعمل بجد، ولا تستمع إلى من يسخرون منك."},{s:0,t:"I like that. Did your grandpa tell you this story?",ar:"أحب ذلك. هل حكى لك جدك هذه القصة؟"},{s:1,t:"He did! He told me when I was your age, sitting right here. The story is a century old.",ar:"نعم! حكاها لي عندما كنت في عمرك، جالسًا هنا تمامًا. القصة عمرها قرن."},{s:0,t:"Really? So this story is really old!",ar:"حقًا؟ إذن هذه القصة قديمة جدًا!"},{s:0,t:"One day, I'll tell it to my kids too. Maybe at a family wedding, or on a quiet night.",ar:"يومًا ما، سأحكيها لأطفالي أيضًا. ربما في حفل زفاف عائلي، أو في ليلة هادئة."},{s:1,t:"That's the spirit! Now, do you want another story? The king one?",ar:"هذه هي الروح! الآن، هل تريد قصة أخرى؟ قصة الملك؟"},{s:0,t:"Yes! Tell me the king one!",ar:"نعم! احكِ لي قصة الملك!"},{s:1,t:"Okay, but it's getting late. One more, and then bed.",ar:"حسنًا، لكن الوقت تأخر. واحدة أخرى، ثم النوم."},{s:0,t:"Deal! Go on, Grandpa!",ar:"اتفقنا! هيا يا جدي!"},{s:1,t:"Well, the king was a kind man, but he had one problem — he couldn't laugh. His country was at war.",ar:"حسنًا، كان الملك رجلًا طيبًا، لكن كانت لديه مشكلة واحدة — لم يستطع الضحك. كانت بلاده في حرب."},{s:0,t:"He couldn't laugh? Not even once?",ar:"لم يستطع الضحك؟ ولا مرة واحدة؟"},{s:1,t:"Not once! His people tried everything — jokes, songs, dancing. Nothing worked. Even the army sang for him.",ar:"ولا مرة! حاول شعبه كل شيء — النكات، والأغاني، والرقص. لم ينجح شيء. حتى الجيش غنى له."},{s:0,t:"Poor king. So what happened? Did a soldier help him, or a wise old man?",ar:"مسكين الملك. إذن ماذا حدث؟ هل ساعده جندي، أم رجل عجوز حكيم؟"},{s:1,t:"Ah, that's for tomorrow night, my boy. It's bedtime now!",ar:"آه، هذا لليلة الغد يا بني. حان وقت النوم الآن!"},{s:0,t:"No way! You can't stop there!",ar:"مستحيل! لا يمكنك التوقف هنا!"},{s:1,t:"I can, and I will. Good stories need a good ending — tomorrow.",ar:"يمكنني، وسأفعل. القصص الجيدة تحتاج نهاية جيدة — غدًا."},{s:0,t:"Fine! But you promise?",ar:"حسنًا! لكن هل تعدني؟"},{s:1,t:"I promise. Good night, my boy.",ar:"أعدك. تصبح على خير يا بني."},{s:0,t:"Good night, Grandpa!",ar:"تصبح على خير يا جدي!"}]}},{stage:14,topic:"technology",topicAr:"التكنولوجيا والإنترنت",topicEn:"Technology & Internet",topicDe:"Technologie und Internet",emoji:"💻",title:"إصلاح الهاتف في المحل",grammar:{id:"en-passive",title:"Passive voice",titleAr:"المبني للمجهول",covers:1},conv:{id:"en-stage14-a2",speakers:["Technician (فني الصيانة)","Customer (الزبون)"],turns:[{s:0,t:"Hi! My phone is broken. The screen is black and it won't turn on. It just died suddenly.",ar:"مرحبًا! هاتفي معطل. الشاشة سوداء ولن يعمل. لقد توقف فجأة."},{s:1,t:"No problem. Let me take a look. When did it stop working?",ar:"لا مشكلة. دعني ألقي نظرة. متى توقف عن العمل؟"},{s:0,t:"This morning. I dropped it on the floor and then — nothing. I was so surprised.",ar:"هذا الصباح. أسقطته على الأرض ثم — لا شيء. كنت متفاجئًا جدًا."},{s:1,t:"I see. Did you try charging it? Sometimes the error is in the charger, not the phone.",ar:"أرى. هل حاولت شحنه؟ أحيانًا يكون الخطأ في الشاحن، وليس في الهاتف."},{s:0,t:"Yeah, I charged it for two hours. Still nothing.",ar:"نعم، شحنته لمدة ساعتين. ما زال لا شيء."},{s:1,t:"Okay. Let me open it up. Hmm... the battery looks fine. The inside looks clean, and there's no sign of water damage.",ar:"حسنًا. دعني أفتحه. همم… البطارية تبدو سليمة. الداخل يبدو نظيفًا، ولا يوجد أي علامة على تلف بسبب الماء."},{s:0,t:"Is it the screen? Can it be fixed? Or do I need a new mobile?",ar:"هل المشكلة في الشاشة؟ هل يمكن إصلاحها؟ أم أحتاج إلى هاتف محمول جديد؟"},{s:1,t:"I think so. The screen is broken inside. It needs a new one. I can replace it today.",ar:"أظن ذلك. الشاشة مكسورة من الداخل. تحتاج إلى واحدة جديدة. يمكنني استبداله اليوم."},{s:0,t:"How much will it cost?",ar:"كم سيكلف ذلك؟"},{s:1,t:"About eighty dollars. And it'll take one hour. That's the usual price for this repair.",ar:"نحو ثمانين دولارًا. وسيستغرق ساعة واحدة. هذا هو السعر المعتاد لهذا الإصلاح."},{s:0,t:"Eighty? That's a lot. Is there a cheaper option?",ar:"ثمانون؟ هذا كثير. هل يوجد خيار أرخص؟"},{s:1,t:"There's a used screen for fifty. It works fine, but it's not new.",ar:"توجد شاشة مستعملة بخمسين. تعمل بشكل جيد، لكنها ليست جديدة."},{s:0,t:"Hmm. I'll take the new one. I don't wanna fix it again in a month. I need a good solution, not a quick fix.",ar:"همم. سآخذ الجديدة. لا أريد إصلاحها مرة أخرى بعد شهر. أحتاج إلى حل جيد، وليس إصلاحًا سريعًا."},{s:1,t:"Smart choice. Now, do you want me to save your photos first?",ar:"اختيار ذكي. الآن، هل تريد أن أحفظ صورك أولًا؟"},{s:0,t:"Yes, please! My photos are so important. Are they still on the phone?",ar:"نعم، من فضلك! صوري مهمة جدًا. هل ما زالت على الهاتف؟"},{s:1,t:"Let's check. I'll connect it to my laptop and download everything. I'll search for your files and save them all.",ar:"لنتحقق. سأوصله بحاسوبي المحمول وأنزّل كل شيء. سأبحث عن ملفاتك وأحفظها كلها."},{s:0,t:"Thank you! I was so worried about losing them.",ar:"شكرًا لك! كنت قلقًا جدًا من فقدانها."},{s:1,t:"Don't worry. Your files are safe with me. Oh, and your apps too. I copy the data first, so nothing gets lost.",ar:"لا تقلق. ملفاتك آمنة معي. أوه، وتطبيقاتك أيضًا. أنسخ البيانات أولًا، حتى لا يضيع شيء."},{s:0,t:"Great. Hey, while you work — is there a virus on my phone? It's been so slow. I think I clicked a bad link.",ar:"رائع. مهلًا، بينما تعمل — هل يوجد فيروس على هاتفي؟ كان بطيئًا جدًا. أظن أنني نقرت على رابط سيئ."},{s:1,t:"Maybe. I'll check for viruses after the screen. It might need a clean-up.",ar:"ربما. سأتحقق من الفيروسات بعد الشاشة. قد يحتاج إلى تنظيف."},{s:0,t:"Okay. How long will the whole thing take?",ar:"حسنًا. كم سيستغرق كل شيء؟"},{s:1,t:"About two hours. You can wait here, or come back later. Most users wait here and watch TV.",ar:"نحو ساعتين. يمكنك الانتظار هنا، أو العودة لاحقًا. معظم المستخدمين ينتظرون هنا ويشاهدون التلفاز."},{s:0,t:"I'll wait. I need my phone today. Can I use your Wi-Fi?",ar:"سأنتظر. أحتاج هاتفي اليوم. هل يمكنني استخدام الواي فاي الخاص بك؟"},{s:1,t:"Sure! The password is on the wall. The network is fast. You can watch videos or listen to audio.",ar:"بالتأكيد! كلمة المرور على الجدار. الشبكة سريعة. يمكنك مشاهدة الفيديوهات أو الاستماع إلى الصوتيات."},{s:0,t:"Thanks. Oh, do you also fix laptops? Mine is really slow too. I think it's a technology problem.",ar:"شكرًا. أوه، هل تصلح الحواسيب المحمولة أيضًا؟ حاسوبي بطيء جدًا أيضًا. أظن أنها مشكلة تقنية."},{s:1,t:"Yeah, we fix laptops, tablets, everything electronic.",ar:"نعم، نصلح الحواسيب المحمولة، والأجهزة اللوحية، وكل شيء إلكتروني."},{s:0,t:"Good to know. I'll bring my laptop next week.",ar:"من الجيد معرفة ذلك. سأحضر حاسوبي الأسبوع القادم."},{s:1,t:"Bring it anytime. Oh — your phone is downloading your files now.",ar:"أحضره في أي وقت. أوه — هاتفك ينزّل ملفاتك الآن."},{s:0,t:"Already? That was fast!",ar:"بالفعل؟ كان ذلك سريعًا!"},{s:1,t:"Fast internet, fast work. Now let's put in the new screen. The process is quick.",ar:"إنترنت سريع، عمل سريع. الآن لنركّب الشاشة الجديدة. العملية سريعة."},{s:0,t:"Go for it. I'm excited to get my phone back. All my chats and photos are on it.",ar:"افعلها. أنا متحمس لاستعادة هاتفي. كل محادثاتي وصوري عليها."},{s:1,t:"Almost done... and... there! Turn it on! I'll test the digital display first.",ar:"كدت أنتهي… و… ها هو! شغّله! سأختبر الشاشة الرقمية أولًا."},{s:0,t:"It works! The screen is perfect! Thank you so much! I can finally print my photos again.",ar:"إنه يعمل! الشاشة مثالية! شكرًا جزيلًا! يمكنني أخيرًا طباعة صوري مرة أخرى."},{s:1,t:"You're welcome! That'll be eighty dollars.",ar:"على الرحب والسعة! سيكون ذلك ثمانين دولارًا."},{s:0,t:"Here's my card. And here's a tip for the great service.",ar:"هذه بطاقتي. وهذه بقشيش للخدمة الرائعة."},{s:1,t:"Thank you! Come back anytime. And be careful with that phone!",ar:"شكرًا لك! عُد في أي وقت. وكن حذرًا مع ذلك الهاتف!"},{s:0,t:"I will! No more dropping it. Bye!",ar:"سأكون حذرًا! لن أسقطه مرة أخرى. إلى اللقاء!"},{s:1,t:"Bye! Take care!",ar:"إلى اللقاء! اعتنِ بنفسك!"},{s:0,t:"Wait — before I go, how do I back up my photos? I don't wanna lose them again.",ar:"انتظر — قبل أن أذهب، كيف أنسخ صوري احتياطيًا؟ لا أريد أن أفقدها مرة أخرى."},{s:1,t:"Easy. I'll show you. Turn on auto-backup in your settings. It saves everything online. And if you have any problems, come back — we support our customers.",ar:"سهل. سأريك. فعّل النسخ الاحتياطي التلقائي في الإعدادات. إنه يحفظ كل شيء عبر الإنترنت. وإذا واجهت أي مشاكل، عُد — نحن ندعم زبائننا."},{s:0,t:"Auto-backup... got it. Is it free? I'll recommend you to everyone.",ar:"النسخ الاحتياطي التلقائي… فهمت. هل هو مجاني؟ سأوصي بك للجميع."},{s:1,t:"The first part is free. If you need more space, it's a few dollars a month.",ar:"الجزء الأول مجاني. إذا احتجت مساحة أكبر، فهي بضعة دولارات في الشهر."},{s:0,t:"Worth it. Okay, I'm all set. Thanks again! And I'll leave a good review on your site.",ar:"يستحق ذلك. حسنًا، أنا جاهز. شكرًا مرة أخرى! وسأترك تقييمًا جيدًا على موقعك."},{s:1,t:"Anytime! Bye!",ar:"في أي وقت! إلى اللقاء!"}]}},{stage:15,topic:"environment",topicAr:"البيئة والطبيعة",topicEn:"Environment & Nature",topicDe:"Umwelt und Natur",emoji:"🌳",title:"تنظيف الحديقة يوم السبت",grammar:{id:"en-conditional-1",title:"First conditional",titleAr:"الشرط الأول",covers:1},conv:{id:"en-stage15-a2",speakers:["Volunteer (متطوع)","Neighbor (الجار)"],turns:[{s:0,t:"Morning! Ready for the big clean-up? We've got a lot to do today. The earth needs our help!",ar:"صباح الخير! مستعد لعملية التنظيف الكبيرة؟ لدينا الكثير لنفعله اليوم. الأرض تحتاج إلى مساعدتنا!"},{s:1,t:"Ready! I brought gloves and big bags. Where do we start?",ar:"مستعد! أحضرت قفازات وأكياسًا كبيرة. من أين نبدأ؟"},{s:0,t:"Let's start at the park. If we clean the park first, we'll feel good all day.",ar:"لنبدأ في الحديقة. إذا نظفنا الحديقة أولًا، سنشعر بشعور جيد طوال اليوم."},{s:1,t:"Good plan. Look at all this garbage! It's everywhere. On the ground, in the grass, near the trees.",ar:"خطة جيدة. انظر إلى كل هذه القمامة! إنها في كل مكان. على الأرض، وفي العشب، قرب الأشجار."},{s:0,t:"I know. It's terrible. If people stopped throwing trash, the park would be beautiful. The climate is changing, too.",ar:"أعلم. إنه فظيع. لو توقف الناس عن رمي القمامة، لكانت الحديقة جميلة. المناخ يتغير أيضًا."},{s:1,t:"Totally. Okay, plastic bottles go in the blue bag, okay? And metal cans go in the red one.",ar:"تمامًا. حسنًا، الزجاجات البلاستيكية تذهب في الكيس الأزرق، حسنًا؟ وعلب المعدن تذهب في الحمراء."},{s:0,t:"Right. And paper goes in the green bag. We recycle everything we can. It's our system. Everyone in town uses it now.",ar:"صحيح. والورق يذهب في الكيس الأخضر. نعيد تدوير كل ما نستطيع. إنه نظامنا. الجميع في المدينة يستخدمه الآن."},{s:1,t:"Do you recycle at home too?",ar:"هل تعيد التدوير في البيت أيضًا؟"},{s:0,t:"Yeah, of course. If everyone recycled, there'd be much less pollution. And the sea would be cleaner for the fish.",ar:"نعم، بالطبع. لو أعاد الجميع التدوير، لكان هناك تلوث أقل بكثير. وسيصبح البحر أنظف للأسماك."},{s:1,t:"True. Hey, look — there's a plastic bag in the lake!",ar:"صحيح. مهلًا، انظر — توجد كيس بلاستيكي في البحيرة!"},{s:0,t:"Ugh. I'll get it. If we don't take it out, the fish will get hurt.",ar:"أوه. سأخرجه. إذا لم نخرجه، ستتأذى الأسماك."},{s:1,t:"Careful! Don't fall in! The water is deep and cold.",ar:"كن حذرًا! لا تسقط! الماء عميق وبارد."},{s:0,t:"I'm fine. Got it! One less bag in the water.",ar:"أنا بخير. أمسكته! كيس أقل في الماء."},{s:1,t:"Nice! You're a hero today.",ar:"جميل! أنت بطل اليوم."},{s:0,t:"Ha! Not a hero. Just a neighbor who cares.",ar:"ها! لست بطلًا. مجرد جار يهتم."},{s:1,t:"Well, the park needs more people like you. Look, more volunteers are coming!",ar:"حسنًا، الحديقة تحتاج المزيد من الأشخاص مثلك. انظر، المزيد من المتطوعين قادمون!"},{s:0,t:"Great! If more people help, we'll finish by noon.",ar:"رائع! إذا ساعد المزيد من الناس، سننتهي بحلول الظهر."},{s:1,t:"I hope so. My back already hurts!",ar:"أتمنى ذلك. ظهري يؤلمني بالفعل!"},{s:0,t:"Take a break. Drink some water. There's no rush. Sit on that stone and rest your legs.",ar:"خذ استراحة. اشرب بعض الماء. لا عجلة. اجلس على تلك الحجارة وأرح ساقيك."},{s:1,t:"Thanks. Hey, what about the trees? Some of them look sick.",ar:"شكرًا. مهلًا، ماذا عن الأشجار؟ بعضها يبدو مريضًا."},{s:0,t:"Yeah, the dry weather hurt them. If it rains this week, they'll get better. The dry season hurt them.",ar:"نعم، الطقس الجاف أضر بها. إذا أمطرت هذا الأسبوع، ستتحسن. الموسم الجاف أضر بها."},{s:1,t:"I hope it rains. The whole forest needs water.",ar:"أتمنى أن تمطر. الغابة كلها تحتاج إلى الماء."},{s:0,t:"Me too. You know, nature gives us so much. We should protect it. The forest, the sea, the desert — all of it.",ar:"وأنا أيضًا. تعلم، الطبيعة تعطينا الكثير. يجب أن نحميها. الغابة، والبحر، والصحراء — كلها."},{s:1,t:"Exactly. If we protect nature, nature protects us. That's the simple truth.",ar:"بالضبط. إذا حمينا الطبيعة، ستحمينا الطبيعة. هذه هي الحقيقة البسيطة."},{s:0,t:"Well said! Okay, break's over. Let's get back to work.",ar:"أحسنت القول! حسنًا، انتهت الاستراحة. لنعد إلى العمل."},{s:1,t:"Let's go! The grass needs us. Ha!",ar:"لنذهب! العشب يحتاجنا. ها!"},{s:0,t:"Ha! And the flowers too. Look how pretty they are when the trash is gone.",ar:"ها! والزهور أيضًا. انظر كم هي جميلة عندما تختفي القمامة."},{s:1,t:"So pretty. I wish the park always looked like this.",ar:"جميلة جدًا. أتمنى أن تبدو الحديقة هكذا دائمًا."},{s:0,t:"It can — if we keep coming back. Same time next Saturday?",ar:"يمكن أن تبدو كذلك — إذا واصلنا العودة. نفس الوقت السبت القادم؟"},{s:1,t:"Count me in! I'll bring my kids too. They should learn this.",ar:"اعتمد عليّ! سأحضر أطفالي أيضًا. يجب أن يتعلموا هذا."},{s:0,t:"Perfect! Kids love helping. And they'll learn to love nature.",ar:"ممتاز! الأطفال يحبون المساعدة. وسيتعلمون حب الطبيعة."},{s:1,t:"That's the idea. Okay, last bag — done!",ar:"هذه هي الفكرة. حسنًا، آخر كيس — انتهينا!"},{s:0,t:"Done! Look at the park now. It's a different place! It feels like a green valley now.",ar:"انتهينا! انظر إلى الحديقة الآن. إنها مكان مختلف! تبدو كوادٍ أخضر الآن."},{s:1,t:"It really is. Great work, everyone!",ar:"إنها كذلك فعلًا. عمل رائع، أيها الجميع!"},{s:0,t:"Great work! See you next Saturday!",ar:"عمل رائع! أراك السبت القادم!"},{s:1,t:"See you!",ar:"أراك!"},{s:0,t:"Wait, before we go — look at the lake now. It's so clean!",ar:"انتظر، قبل أن نذهب — انظر إلى البحيرة الآن. إنها نظيفة جدًا!"},{s:1,t:"It is! The water is clear. You can even see the fish.",ar:"إنها كذلك! الماء صافٍ. يمكنك حتى رؤية الأسماك."},{s:0,t:"Beautiful. If we come every week, this park will be the best in the city.",ar:"جميلة. إذا جئنا كل أسبوع، ستكون هذه الحديقة الأفضل في المدينة."},{s:1,t:"It already is! Okay, let's take a photo to remember today.",ar:"إنها كذلك بالفعل! حسنًا، لنلتقط صورة لتذكر اليوم."},{s:0,t:"Smile! Perfect. I'll send it to the group.",ar:"ابتسم! مثالية. سأرسلها إلى المجموعة."},{s:1,t:"Great idea. They'll all wanna join next time.",ar:"فكرة رائعة. سيرغبون جميعًا في الانضمام في المرة القادمة."},{s:0,t:"I hope so. The more, the better!",ar:"أتمنى ذلك. كلما زاد العدد، كان أفضل!"},{s:1,t:"See you Saturday!",ar:"أراك يوم السبت!"}]}},{stage:16,topic:"media",topicAr:"وسائل الإعلام والأخبار",topicEn:"Media & News",topicDe:"Medien und Nachrichten",emoji:"📺",title:"أخبار المساء",grammar:{id:"en-present-perfect",title:"Present perfect",titleAr:"المضارع التام",covers:1},conv:{id:"en-stage16-a2",speakers:["Friend (الصديق)","Neighbor (الجار)"],turns:[{s:0,t:"Did you watch the news last night? It was crazy! The whole country is talking about it.",ar:"هل شاهدت الأخبار الليلة الماضية؟ كانت جنونية! البلد كله يتحدث عنها."},{s:1,t:"No, I missed it. What happened? Tell me everything.",ar:"لا، فاتتني. ماذا حدث؟ أخبرني بكل شيء."},{s:0,t:"Well, first, the president gave a big speech about the economy.",ar:"حسنًا، أولًا، ألقى الرئيس خطابًا كبيرًا عن الاقتصاد."},{s:1,t:"The president? What did he say?",ar:"الرئيس؟ ماذا قال؟"},{s:0,t:"He said the government will create new jobs next year.",ar:"قال إن الحكومة ستوفر وظائف جديدة العام القادم."},{s:1,t:"New jobs? That's good news. Did he say how many?",ar:"وظائف جديدة؟ هذا خبر جيد. هل قال كم عددها؟"},{s:0,t:"He said thousands. But, you know, politicians promise a lot. Our region needs jobs.",ar:"قال الآلاف. لكن، كما تعلم، السياسيون يعدون بالكثير. منطقتنا تحتاج إلى الوظائف."},{s:1,t:"Ha! True. What else was on the news?",ar:"ها! صحيح. ماذا كان أيضًا في الأخبار؟"},{s:0,t:"There was a story about a thief who stole a famous painting.",ar:"كانت هناك قصة عن لص سرق لوحة مشهورة."},{s:1,t:"A painting? From a gallery? That's a serious crime.",ar:"لوحة؟ من معرض؟ هذه جريمة خطيرة."},{s:0,t:"Yeah, from a gallery downtown. The painting is worth millions! It was painted a century ago, they said.",ar:"نعم، من معرض وسط المدينة. اللوحة تساوي الملايين! قالوا إنها رُسمت قبل قرن."},{s:1,t:"Millions! Did the police catch him?",ar:"الملايين! هل ألقت الشرطة القبض عليه؟"},{s:0,t:"Not yet. The police said they're looking for him everywhere. The police think it was a professional criminal.",ar:"ليس بعد. قالت الشرطة إنهم يبحثون عنه في كل مكان. تعتقد الشرطة أنه مجرم محترف."},{s:1,t:"Wow. That's like a movie! What else? Was there anything about the war?",ar:"واو. هذا مثل فيلم! ماذا أيضًا؟ هل كان هناك أي شيء عن الحرب؟"},{s:0,t:"There was also a story about a new virus. Doctors say don't worry, though.",ar:"كانت هناك أيضًا قصة عن فيروس جديد. يقول الأطباء لا تقلقوا، مع ذلك."},{s:1,t:"A virus? Ugh. I hate hearing about viruses.",ar:"فيروس؟ أوه. أكره سماع أخبار الفيروسات."},{s:0,t:"Me too. But they said it's not serious. Just wash your hands and stay healthy. The disease is not dangerous, they said.",ar:"وأنا أيضًا. لكنهم قالوا إنه ليس خطيرًا. فقط اغسل يديك وحافظ على صحتك. قالوا إن المرض ليس خطيرًا."},{s:1,t:"Okay, good. Any happy news?",ar:"حسنًا، جيد. أي أخبار سعيدة؟"},{s:0,t:"Yes! A local team won a big competition. They got a gold prize! The whole city is celebrating.",ar:"نعم! فاز فريق محلي بمسابقة كبيرة. حصلوا على جائزة ذهبية! المدينة كلها تحتفل."},{s:1,t:"That's great! I love happy news. Who won?",ar:"هذا رائع! أحب الأخبار السعيدة. من فاز؟"},{s:0,t:"A team of young scientists. They invented a new device for clean water. What a discovery!",ar:"فريق من العلماء الشباب. اخترعوا جهازًا جديدًا للمياه النظيفة. يا له من اكتشاف!"},{s:1,t:"Amazing! See, the news isn't all bad.",ar:"مذهل! أرأيت، الأخبار ليست كلها سيئة."},{s:0,t:"You're right. Oh, and the weather — it's gonna be hot all week.",ar:"أنت محق. أوه، والطقس — سيكون حارًا طوال الأسبوع."},{s:1,t:"Hot? How hot?",ar:"حار؟ كم ستبلغ الحرارة؟"},{s:0,t:"Thirty-five degrees! The hottest week this year. The heat is terrible.",ar:"خمس وثلاثون درجة! أحر أسبوع هذا العام. الحرارة فظيعة."},{s:1,t:"Thirty-five! I'll stay inside with the air conditioning.",ar:"خمس وثلاثون! سأبقى في الداخل مع التكييف."},{s:0,t:"Me too. Hey, did you hear about the new movie? It's number one at the box office.",ar:"وأنا أيضًا. مهلًا، هل سمعت عن الفيلم الجديد؟ إنه الأول في شباك التذاكر."},{s:1,t:"No! What's it about?",ar:"لا! عمَّ يتحدث؟"},{s:0,t:"It's a comedy about a man who wins the lottery and loses the ticket. The audience laughed the whole time.",ar:"إنها كوميديا عن رجل يفوز باليانصيب ويفقد التذكرة. ضحك الجمهور طوال الوقت."},{s:1,t:"Ha! That sounds funny. We should go see it.",ar:"ها! هذا يبدو مضحكًا. يجب أن نذهب لمشاهدته."},{s:0,t:"Let's go this weekend. Saturday night?",ar:"لنذهب في عطلة نهاية الأسبوع هذه. ليلة السبت؟"},{s:1,t:"Saturday works for me. Seven o'clock?",ar:"السبت يناسبني. السابعة مساءً؟"},{s:0,t:"Seven it is. I'll buy the tickets online.",ar:"السابعة إذن. سأشتري التذاكر عبر الإنترنت."},{s:1,t:"Perfect. Now, turn off the news — let's watch something fun.",ar:"ممتاز. الآن، أطفئ الأخبار — لنشاهد شيئًا ممتعًا."},{s:0,t:"Good idea. News all day makes me tired.",ar:"فكرة جيدة. الأخبار طوال اليوم تجعلني متعبًا."},{s:1,t:"Me too. Let's watch a comedy. I need a laugh.",ar:"وأنا أيضًا. لنشاهد كوميديا. أحتاج إلى ضحكة."},{s:0,t:"A comedy it is. Popcorn? Let's get a big bag and enjoy the film.",ar:"كوميديا إذن. فشار؟ لنشترِ كيسًا كبيرًا ونستمتع بالفيلم."},{s:1,t:"Always popcorn!",ar:"دائمًا الفشار!"},{s:0,t:"Oh wait — did you hear? The new smartphone is out today!",ar:"أوه انتظر — هل سمعت؟ الهاتف الذكي الجديد صدر اليوم!"},{s:1,t:"Really? Is it expensive?",ar:"حقًا؟ هل هو غالٍ؟"},{s:0,t:"Very! But the camera is incredible, they say.",ar:"جدًا! لكن الكاميرا مذهلة، كما يقولون."},{s:1,t:"Every year they say that. My phone still works fine.",ar:"كل عام يقولون ذلك. هاتفي ما زال يعمل بشكل جيد."},{s:0,t:"Mine too. Let's not watch the ads — they'll make us want it!",ar:"هاتفي أيضًا. دعنا لا نشاهد الإعلانات — ستجعلنا نريده!"},{s:1,t:"Ha! Too late. I already want it.",ar:"ها! فات الأوان. أنا أريده بالفعل."}]}},{stage:17,topic:"education",topicAr:"التعليم والدراسة",topicEn:"Education & Study",topicDe:"Bildung und Studium",emoji:"🎓",title:"الاستعداد للامتحان",grammar:{id:"en-will-going-to",title:"will / going to",titleAr:"المستقبل will و going to",covers:1},conv:{id:"en-stage17-a2",speakers:["Teacher (المعلم)","Student (الطالب)"],turns:[{s:0,t:"Okay, class. The exam is next week. Are you ready? Pay attention, please.",ar:"حسنًا، يا طلاب. الامتحان الأسبوع القادم. هل أنتم مستعدون؟ انتبهوا، من فضلكم."},{s:1,t:"Not really, teacher. I'm so nervous. What if I fail?",ar:"ليس فعلًا، أستاذ. أنا متوتر جدًا. ماذا لو رسبت؟"},{s:0,t:"Don't worry. If you study a little every day, you'll pass.",ar:"لا تقلق. إذا درست قليلًا كل يوم، ستنجح."},{s:1,t:"But there's so much to learn! Words, grammar, everything! I feel so much stress.",ar:"لكن هناك الكثير لتعلمه! كلمات، وقواعد، وكل شيء! أشعر بتوتر كبير."},{s:0,t:"I know. But you're smarter than you think. Let's make a plan.",ar:"أعلم. لكنك أذكى مما تظن. لنضع خطة."},{s:1,t:"A plan? Okay. Where do we start? Give me the steps, one by one.",ar:"خطة؟ حسنًا. من أين نبدأ؟ أعطني الخطوات، واحدة تلو الأخرى."},{s:0,t:"First, review your notes every evening. Just twenty minutes. It's the best method.",ar:"أولًا، راجع ملاحظاتك كل مساء. عشرون دقيقة فقط. إنها أفضل طريقة."},{s:1,t:"Twenty minutes? That's easy. What else?",ar:"عشرون دقيقة؟ هذا سهل. ماذا أيضًا؟"},{s:0,t:"Second, practice writing. Write a short essay every day.",ar:"ثانيًا، تدرّب على الكتابة. اكتب مقالًا قصيرًا كل يوم."},{s:1,t:"An essay? Every day? That's hard!",ar:"مقال؟ كل يوم؟ هذا صعب!"},{s:0,t:"Start small. Five sentences. Then ten. You'll get better fast.",ar:"ابدأ صغيرًا. خمس جمل. ثم عشر. ستتحسن بسرعة."},{s:1,t:"Okay, I'll try. What about the words? I forget them so fast. My memory is terrible.",ar:"حسنًا، سأحاول. ماذا عن الكلمات؟ أنساها بسرعة كبيرة. ذاكرتي سيئة."},{s:0,t:"That's normal. Read them, say them out loud, and use them in sentences. Repeat them daily.",ar:"هذا طبيعي. اقرأها، وقلها بصوت عالٍ، واستخدمها في جمل. كررها يوميًا."},{s:1,t:"Use them in sentences... okay. And grammar? Grammar is my weak point.",ar:"استخدمها في جمل… حسنًا. والقواعد؟ القواعد هي نقطة ضعفي."},{s:0,t:"Grammar is easier if you practice. Do the exercises in your book. They explain everything clearly.",ar:"القواعد أسهل إذا تدربت. قم بالتمارين في كتابك. إنها تشرح كل شيء بوضوح."},{s:1,t:"I did some exercises yesterday. I got most of them right! I did them correctly this time.",ar:"قمت ببعض التمارين أمس. أجبت عن معظمها بشكل صحيح! أجبت عنها بشكل صحيح هذه المرة."},{s:0,t:"See? You're doing great. What about listening?",ar:"أرأيت؟ أنت تقوم بعمل رائع. ماذا عن الاستماع؟"},{s:1,t:"I listen to English songs every day. Does that help? The singing helps me remember words.",ar:"أستمع إلى الأغاني الإنجليزية كل يوم. هل يساعد ذلك؟ الغناء يساعدني على تذكر الكلمات."},{s:0,t:"It helps a lot! Songs teach you real English. Keep doing it.",ar:"يساعد كثيرًا! الأغاني تعلمك الإنجليزية الحقيقية. واصل فعل ذلك."},{s:1,t:"I will. Teacher, what will the exam be like?",ar:"سأفعل. أستاذ، كيف سيكون الامتحان؟"},{s:0,t:"There are four parts: reading, writing, listening, and speaking.",ar:"هناك أربعة أجزاء: القراءة، والكتابة، والاستماع، والتحدث."},{s:1,t:"Speaking? I have to speak? In front of everyone?",ar:"التحدث؟ يجب أن أتحدث؟ أمام الجميع؟"},{s:0,t:"No, just with me. We'll have a short conversation. Like this one.",ar:"لا، معي فقط. سنجري محادثة قصيرة. مثل هذه."},{s:1,t:"Oh, that's not so bad. I can talk, I think.",ar:"أوه، هذا ليس سيئًا. يمكنني التحدث، أظن."},{s:0,t:"Of course you can! You're talking to me right now, in English! That's real progress.",ar:"بالطبع يمكنك! أنت تتحدث معي الآن، بالإنجليزية! هذا تقدم حقيقي."},{s:1,t:"Ha! You're right. Okay, I'm feeling better already.",ar:"ها! أنت محق. حسنًا، أشعر بتحسن بالفعل."},{s:0,t:"Good. Now, do you have any questions about the exam?",ar:"جيد. الآن، هل لديك أي أسئلة عن الامتحان؟"},{s:1,t:"Yeah — how long is it?",ar:"نعم — كم يستغرق؟"},{s:0,t:"Two hours. With a short break in the middle.",ar:"ساعتان. مع استراحة قصيرة في المنتصف."},{s:1,t:"Two hours. Okay. And what should I bring?",ar:"ساعتان. حسنًا. وماذا يجب أن أحضر؟"},{s:0,t:"Bring a pen, your ID, and water. Nothing else.",ar:"أحضر قلمًا، وهويتك، وماء. لا شيء آخر."},{s:1,t:"No books? No dictionary?",ar:"لا كتب؟ لا قاموس؟"},{s:0,t:"No books. But don't worry — you've studied well. I believe in you. You can succeed.",ar:"لا كتب. لكن لا تقلق — لقد درست جيدًا. أنا أؤمن بك. يمكنك النجاح."},{s:1,t:"Thanks, teacher. That means a lot.",ar:"شكرًا، أستاذ. هذا يعني الكثير."},{s:0,t:"You're welcome. Now go home and start your plan. Twenty minutes tonight!",ar:"على الرحب والسعة. الآن اذهب إلى البيت وابدأ خطتك. عشرون دقيقة الليلة!"},{s:1,t:"Twenty minutes. I promise. See you tomorrow, teacher!",ar:"عشرون دقيقة. أعدك. أراك غدًا، أستاذ!"},{s:0,t:"See you tomorrow! Good luck!",ar:"أراك غدًا! حظًا سعيدًا!"},{s:1,t:"Thanks! Bye!",ar:"شكرًا! إلى اللقاء!"},{s:0,t:"Oh, one more thing — check your name on the list by the door on exam day. Look for your name carefully.",ar:"أوه، شيء آخر — تحقق من اسمك في القائمة بجانب الباب يوم الامتحان. ابحث عن اسمك بعناية."},{s:1,t:"The list? Okay. What if my name isn't there?",ar:"القائمة؟ حسنًا. ماذا لو لم يكن اسمي هناك؟"},{s:0,t:"Then come and find me. Don't panic. It happens sometimes.",ar:"إذن تعال وابحث عني. لا تفزع. يحدث ذلك أحيانًا."},{s:1,t:"Okay. I feel ready now. Really, I do.",ar:"حسنًا. أشعر أنني مستعد الآن. حقًا، أشعر بذلك."},{s:0,t:"You are ready. Now go! Study, sleep, and believe in yourself.",ar:"أنت مستعد. الآن اذهب! ادرس، ونم، وآمن بنفسك."},{s:1,t:"I will! Bye, teacher!",ar:"سأفعل! إلى اللقاء، أستاذ!"}]}},{stage:18,topic:"street",topicAr:"كلام الشارع",topicEn:"Street Talk",topicDe:"Street Talk",emoji:"",title:"الموسيقى الصاخبة",grammar:{id:"en-should-must-have-to",title:"Should, must, have to",titleAr:"should و must و have to للوجوب والنصيحة",covers:1},conv:{id:"en-stage18-a2",speakers:["Neighbor (الجار)","Loud Neighbor (الجارة الصاخبة)"],turns:[{s:0,t:"Hey! It's two in the morning! Turn that music down!",ar:"مهلًا! إنها الثانية بعد منتصف الليل! اخفضي هذه الموسيقى!"},{s:1,t:"Relax, man. It's just one song.",ar:"اهدأ يا رجل. إنها أغنية واحدة فقط."},{s:0,t:"One song? You've been playing it all night! My kids can't sleep.",ar:"أغنية واحدة؟ وأنتِ تشغلينها طوال الليل! أطفالي لا يستطيعون النوم."},{s:1,t:"Your kids? That's not my problem.",ar:"أطفالك؟ هذه ليست مشكلتي."},{s:0,t:"It IS your problem when your music shakes my walls!",ar:"بل هي مشكلتك عندما تهز موسيقاك جدران بيتي!"},{s:1,t:"Oh, come on. Don't be such a pain in the ass.",ar:"أوه، هيّا. لا تكن مزعجًا إلى هذا الحد."},{s:0,t:"I'm serious. Turn it down, or I'll call the police.",ar:"أنا جاد. اخفضي الصوت، وإلا سأتصل بالشرطة."},{s:1,t:"Call them, then. What are they going to do, huh?",ar:"اتصلي بهم إذن. ماذا سيفعلون، هاه؟"},{s:0,t:"You know what? You're acting like a real bitch tonight.",ar:"أتعلمين؟ أنتِ تتصرفين كحقيرة حقيقية الليلة."},{s:1,t:"What did you just call me? Say that again!",ar:"ماذا ناديتني للتو؟ قولي ذلك مجددًا!"},{s:0,t:"You heard me. And shut up with that music — I'm done being nice.",ar:"سمعتِني. وأغلقي هذه الموسيقى — لقد سئمت من التلطف."},{s:1,t:"Fine! I'll turn it down. But don't ever talk to me like that again.",ar:"حسنًا! سأخفض الصوت. لكن لا تتحدث معي بهذه الطريقة مجددًا أبدًا."},{s:0,t:"Then don't blast music at two in the morning. Good night.",ar:"إذن لا تشغلي الموسيقى بصوت عالٍ في الثانية بعد منتصف الليل. تصبحين على خير."},{s:1,t:"Yeah, yeah. Good night.",ar:"نعم، نعم. تصبح على خير."}]}}],de:[{stage:1,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"سنتان في الحي الجديد",grammar:{id:"de-perfekt",title:"Perfekt",titleAr:"الماضي التام (Perfekt)",covers:1},conv:{id:"de-stage1-a2",speakers:["Nachbar (الجار)","Neuer Nachbar (الجار الجديد)"],turns:[{s:0,t:"Hallo, Nachbar! Ich habe dich lange nicht gesehen.",ar:"مرحبًا، جاري! لم أرك منذ زمن طويل."},{s:1,t:"Ja, ich bin vor zwei Jahren hierher gezogen.",ar:"نعم، انتقلت إلى هنا قبل سنتين."},{s:0,t:"Wirklich? Ich habe deine Familie nie gesehen.",ar:"حقًا؟ لم أرَ عائلتك أبدًا."},{s:1,t:"Sie hat mich zweimal besucht, im Sommer.",ar:"لقد زارتني مرتين، في الصيف."},{s:0,t:"Hast du schon einmal in dieser Stadt gearbeitet?",ar:"هل عملت في هذه المدينة من قبل؟"},{s:1,t:"Nein, ich habe hier nie gearbeitet. Ich habe in Kairo gearbeitet.",ar:"لا، لم أعمل هنا أبدًا. عملت في القاهرة."},{s:0,t:"Ich habe hier schon zehn Jahre lang gewohnt.",ar:"لقد سكنت هنا عشر سنوات."},{s:1,t:"Hast du alle Nachbarn kennengelernt?",ar:"هل تعرفت على كل الجيران؟"},{s:0,t:"Fast alle. Ich habe den Bäcker und den Lehrer kennengelernt.",ar:"تقريبًا كلهم. تعرفت على الخباز والمعلم."},{s:1,t:"Ich habe den Bäcker heute Morgen gerade getroffen.",ar:"قابلت الخباز للتو هذا الصباح."},{s:0,t:"Er hat hier zwanzig Jahre lang Brot gebacken.",ar:"إنه يخبز الخبز هنا منذ عشرين سنة."},{s:1,t:"Hast du sein süßes Brot schon probiert?",ar:"هل جربت خبزه الحلو من قبل؟"},{s:0,t:"Ja, ich habe es oft probiert. Es ist wunderbar.",ar:"نعم، جربته مرات كثيرة. إنه رائع."},{s:1,t:"Ich habe schon etwas für meine Kinder gekauft.",ar:"اشتريت بعضًا منه لأطفالي بالفعل."},{s:0,t:"Wie viele Kinder hast du jetzt?",ar:"كم طفلًا لديك الآن؟"},{s:1,t:"Ich habe zwei Kinder, einen Sohn und eine Tochter.",ar:"لدي طفلان، ولد وبنت."},{s:0,t:"Haben sie schon mit der Schule hier angefangen?",ar:"هل بدأوا المدرسة هنا بعد؟"},{s:1,t:"Ja, sie haben dieses Jahr mit der Schule angefangen.",ar:"نعم، بدأوا المدرسة هذه السنة."},{s:0,t:"Mein Sohn hat mit deiner Tochter gelernt, glaube ich.",ar:"أعتقد أن ابني درس مع ابنتك."},{s:1,t:"Ja, sie sind schon gute Freunde geworden.",ar:"نعم، أصبحا صديقين حميمين بالفعل."},{s:0,t:"Hast du den neuen Park bei der Schule besucht?",ar:"هل زرت الحديقة الجديدة قرب المدرسة؟"},{s:1,t:"Noch nicht. Ich habe diese Woche keine Zeit gehabt.",ar:"ليس بعد. لم يكن لدي وقت هذا الأسبوع."},{s:0,t:"Ich bin jeden Abend in diesem Monat dort spazieren gegangen.",ar:"مشيت هناك كل مساء هذا الشهر."},{s:1,t:"Hat der Park sich seit letztem Jahr stark verändert?",ar:"هل تغيرت الحديقة كثيرًا منذ السنة الماضية؟"},{s:0,t:"Ja, er hat sich sehr verändert. Es gibt jetzt neue Bäume.",ar:"نعم، تغيرت كثيرًا. هناك أشجار جديدة الآن."},{s:1,t:"Ich habe auch von dem neuen Spielplatz gehört.",ar:"سمعت عن ملعب الأطفال الجديد أيضًا."},{s:0,t:"Die Kinder haben dort jeden Tag gespielt.",ar:"الأطفال يلعبون هناك كل يوم."},{s:1,t:"Hast du schon einmal in einem anderen Land gelebt?",ar:"هل عشت في بلد آخر من قبل؟"},{s:0,t:"Ja, ich habe drei Jahre in Deutschland gelebt.",ar:"نعم، عشت في ألمانيا ثلاث سنوات."},{s:1,t:"Hast du dort Deutsch gelernt?",ar:"هل تعلمت الألمانية هناك؟"},{s:0,t:"Ja, ich habe ein bisschen Deutsch gelernt.",ar:"نعم، تعلمت قليلًا من الألمانية."},{s:1,t:"Ich wollte schon immer eine neue Sprache lernen.",ar:"لطالما أردت تعلم لغة جديدة."},{s:0,t:"Du hast die richtige Straße gefunden, mein Freund.",ar:"لقد جئت إلى الشارع الصحيح، يا صديقي."},{s:1,t:"Ich habe mich hier seit dem ersten Tag zu Hause gefühlt.",ar:"شعرت أنني في بيتي هنا منذ اليوم الأول."},{s:0,t:"Wir haben eine kleine Party für Samstag vorbereitet.",ar:"لقد جهزنا حفلة صغيرة ليوم السبت."},{s:1,t:"Hast du auch die anderen Nachbarn eingeladen?",ar:"هل دعوت الجيران الآخرين أيضًا؟"},{s:0,t:"Ja, ich habe alle in unserer Straße eingeladen.",ar:"نعم، دعوت كل من في شارعنا."},{s:1,t:"Ich habe Saft und Kuchen für die Party gekauft.",ar:"اشتريت عصيرًا وكعكًا للحفلة."},{s:0,t:"Perfekt! Ich habe Tee und Kaffee gemacht.",ar:"ممتاز! لقد أعددت الشاي والقهوة."},{s:1,t:"Hat deine Frau etwas Besonderes gekocht?",ar:"هل طبخت زوجتك شيئًا خاصًا؟"},{s:0,t:"Sie hat ihr berühmtes Reisgericht gekocht.",ar:"لقد طبخت طبق الأرز المشهور لديها."},{s:1,t:"Ich habe es noch nie probiert. Ich freue mich!",ar:"لم أتذوقه أبدًا. أنا متحمس!"},{s:0,t:"Du hast nicht lange hier gelebt, aber du gehörst hierher.",ar:"لم تسكن هنا طويلًا، لكنك واحد منا."},{s:1,t:"Danke! Ich habe hier ein richtiges Zuhause gefunden.",ar:"شكرًا! لقد وجدت بيتًا حقيقيًا هنا."}]}},{stage:2,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"مقارنة في السوق والمطعم",grammar:{id:"de-komparativ-superlativ",title:"Komparativ und Superlativ",titleAr:"المقارنة والتفضيل",covers:1},conv:{id:"de-stage2-a2",speakers:["Verkäufer (البائع)","Kunde (الزبون)"],turns:[{s:0,t:"Willkommen! Unser Gemüse ist frischer als ihres.",ar:"أهلًا! خضارنا أطازج من خضارهم."},{s:1,t:"Wirklich? Ihre Preise sind höher als letzte Woche.",ar:"حقًا؟ أسعارك أعلى من الأسبوع الماضي."},{s:0,t:"Ein bisschen höher, aber die Qualität ist besser.",ar:"أعلى قليلًا، لكن الجودة أفضل."},{s:1,t:"Ist dieser Käse billiger als der dort?",ar:"هل هذا الجبن أرخص من الجبن هناك؟"},{s:0,t:"Ja, er ist billiger und auch leckerer.",ar:"نعم، إنه أرخص وألذ أيضًا."},{s:1,t:"Ich möchte etwas Gesünderes für meine Kinder.",ar:"أريد شيئًا أصحّ لأطفالي."},{s:0,t:"Diese Äpfel sind süßer als die roten dort.",ar:"هذه التفاحات أحلى من تلك الحمراء."},{s:1,t:"Wie viel kosten die Orangen heute?",ar:"بكم البرتقال اليوم؟"},{s:0,t:"Zwei Dollar pro Kilo, billiger als gestern.",ar:"دولاران للكيلو، أرخص من أمس."},{s:1,t:"Das ist immer noch teurer als der andere Markt.",ar:"هذا ما زال أغلى من السوق الآخر."},{s:0,t:"Aber unser Obst ist größer und saftiger.",ar:"لكن فاكهتنا أكبر وأكثر عصارة."},{s:1,t:"Haben Sie Brot, das weicher ist als dieses?",ar:"هل لديك خبز أطرى من هذا؟"},{s:0,t:"Ja, das Brot von heute Morgen ist das weichste.",ar:"نعم، خبز هذا الصباح هو الأطرى."},{s:1,t:"Ich nehme das weichste Brot, bitte.",ar:"سآخذ أطرى خبز، من فضلك."},{s:0,t:"Möchten Sie Tee? Unser Tee ist der beste in der Stadt.",ar:"هل تريد شايًا؟ شاينا هو الأفضل في المدينة."},{s:1,t:"Ist er stärker als der Tee zu Hause?",ar:"هل هو أقوى من الشاي في البيت؟"},{s:0,t:"Viel stärker, und auch süßer.",ar:"أقوى بكثير، وأحلى أيضًا."},{s:1,t:"Dann trinke ich ihn hier, mit meinem Freund.",ar:"إذن سأشربه هنا، مع صديقي."},{s:0,t:"Ihr Freund isst jeden Tag hier, oder?",ar:"صديقك يأكل هنا كل يوم، أليس كذلك؟"},{s:1,t:"Ja, er sagt, Ihr Essen ist das beste.",ar:"نعم، يقول إن طعامك هو الأفضل."},{s:0,t:"Danke! Er ist unser nettester Kunde.",ar:"شكرًا! إنه ألطف زبون لدينا."},{s:1,t:"Welches Restaurant ist besser, Ihres oder das neue?",ar:"أي مطعم أفضل، مطعمك أم المطعم الجديد؟"},{s:0,t:"Unseres ist kleiner, aber das Essen ist besser.",ar:"مطعمنا أصغر، لكن الطعام أفضل."},{s:1,t:"Das neue ist größer, aber teurer.",ar:"المطعم الجديد أكبر، لكنه أغلى."},{s:0,t:"Und ihre Tische sind kleiner als unsere.",ar:"وطاولاتهم أصغر من طاولاتنا."},{s:1,t:"Ich mag Ihren Laden lieber. Er ist wärmer.",ar:"أحب مكانك أكثر. إنه أدفأ."},{s:0,t:"Wir kochen langsamer, aber mit mehr Liebe.",ar:"نطبخ ببطء أكثر، لكن بحب أكبر."},{s:1,t:"Darum ist Ihre Suppe die leckerste.",ar:"لذلك حساؤكم هو الألذ."},{s:0,t:"Probieren Sie diesen Kuchen. Er ist süßer als Honig.",ar:"جرب هذه الكعكة. إنها أحلى من العسل."},{s:1,t:"Wow! Es ist der süßeste Kuchen, den ich gegessen habe.",ar:"رائع! إنها أحلى كعكة أكلتها."},{s:0,t:"Meine Mutter macht ihn. Sie ist die beste Köchin.",ar:"أمي تصنعها. إنها أفضل طباخة."},{s:1,t:"Ist Ihr Kaffee besser als der Kaffee nebenan?",ar:"هل قهوتك أفضل من قهوة المقهى المجاور؟"},{s:0,t:"Unserer ist dunkler und stärker, ganz sicher.",ar:"قهوتنا أغمق وأقوى، بالتأكيد."},{s:1,t:"Geben Sie mir die größte Tasse, bitte.",ar:"أعطني أكبر كوب، من فضلك."},{s:0,t:"Bitte schön. Er ist heute heißer als sonst.",ar:"تفضل. إنها أسخن من المعتاد اليوم."},{s:1,t:"Perfekt. Kalte Tage brauchen den heißesten Kaffee.",ar:"ممتاز. الأيام الباردة تحتاج أسخن قهوة."},{s:0,t:"Wie viel ist alles zusammen, mein Freund?",ar:"كم حساب كل شيء، يا صديقي؟"},{s:1,t:"Ich bezahle. Heute bin ich dran.",ar:"دعني أدفع. اليوم دوري."},{s:0,t:"Der Kaffee geht heute auf mich, mein Freund.",ar:"القهوة على حسابي اليوم، يا صديقي."},{s:1,t:"Sie sind der netteste Verkäufer auf dem Markt.",ar:"أنت ألطف بائع في السوق."},{s:0,t:"Kommen Sie morgen wieder. Der Fisch wird frischer sein.",ar:"عد غدًا. السمك سيكون أطازج."},{s:1,t:"Ich komme früher als heute.",ar:"سآتي أبكر من اليوم."},{s:0,t:"Gut! Frühe Kunden bekommen den besten Fisch.",ar:"جيد! الزبائن المبكرون يحصلون على أفضل سمك."},{s:1,t:"Bis morgen, mein Freund. Danke!",ar:"أراك غدًا، يا صديقي. شكرًا!"}]}},{stage:3,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"بينما كنا نرتب البيت",grammar:{id:"de-wechselpraepositionen",title:"Wechselpräpositionen",titleAr:"حروف الجر المتبدلة",covers:1},conv:{id:"de-stage3-a2",speakers:["Gastgeber (المضيف)","Gast (الضيف)"],turns:[{s:0,t:"Willkommen! Komm herein, bitte. Stell die Tasche neben die Tür.",ar:"أهلًا! تفضل بالدخول. ضع الحقيبة بجانب الباب."},{s:1,t:"Danke! Die Tasche steht jetzt neben der Tür.",ar:"شكرًا! الحقيبة الآن بجانب الباب."},{s:0,t:"Gut. Leg das Buch auf den Tisch, bitte.",ar:"جيد. ضع الكتاب على الطاولة، من فضلك."},{s:1,t:"Das Buch liegt jetzt auf dem Tisch.",ar:"الكتاب الآن على الطاولة."},{s:0,t:"Stell die Lampe auf den Tisch, neben das Buch.",ar:"ضع المصباح على الطاولة، بجانب الكتاب."},{s:1,t:"Die Lampe steht jetzt auf dem Tisch, neben dem Buch.",ar:"المصباح الآن على الطاولة، بجانب الكتاب."},{s:0,t:"Häng das Bild an die Wand, über das Sofa.",ar:"علّق الصورة على الجدار، فوق الأريكة."},{s:1,t:"Das Bild hängt jetzt an der Wand, über dem Sofa.",ar:"الصورة الآن على الجدار، فوق الأريكة."},{s:0,t:"Leg den Teppich unter den Tisch, bitte.",ar:"ضع السجادة تحت الطاولة، من فضلك."},{s:1,t:"Der Teppich liegt jetzt unter dem Tisch.",ar:"السجادة الآن تحت الطاولة."},{s:0,t:"Stell die Stühle um den Tisch herum.",ar:"ضع الكراسي حول الطاولة."},{s:1,t:"Die Stühle stehen jetzt um den Tisch.",ar:"الكراسي الآن حول الطاولة."},{s:0,t:"Geh in die Küche und hol die Tassen.",ar:"اذهب إلى المطبخ وأحضر الأكواب."},{s:1,t:"Ich bin in der Küche. Wo sind die Tassen?",ar:"أنا في المطبخ. أين الأكواب؟"},{s:0,t:"Die Tassen sind in dem Schrank, über dem Herd.",ar:"الأكواب في الخزانة، فوق الموقد."},{s:1,t:"Ich stelle die Tassen auf das Tablett.",ar:"أضع الأكواب على الصينية."},{s:0,t:"Und der Tee? Er ist in der Küche, auf dem Herd.",ar:"والشاي؟ إنه في المطبخ، على الموقد."},{s:1,t:"Ich bringe den Tee ins Wohnzimmer.",ar:"أحضر الشاي إلى غرفة الجلوس."},{s:0,t:"Setz dich auf das Sofa, neben mich.",ar:"اجلس على الأريكة، بجانبي."},{s:1,t:"Ich sitze jetzt auf dem Sofa, neben dir.",ar:"أجلس الآن على الأريكة، بجانبك."},{s:0,t:"Leg die Zeitung auf den Tisch, neben die Lampe.",ar:"ضع الجريدة على الطاولة، بجانب المصباح."},{s:1,t:"Die Zeitung liegt auf dem Tisch, neben der Lampe.",ar:"الجريدة على الطاولة، بجانب المصباح."},{s:0,t:"Wo ist die Katze? Sie ist unter dem Bett.",ar:"أين القطة؟ إنها تحت السرير."},{s:1,t:"Sie kommt unter dem Bett hervor, siehst du?",ar:"إنها تخرج من تحت السرير، أترى؟"},{s:0,t:"Sie springt auf das Sofa, neben uns.",ar:"إنها تقفز على الأريكة، بجانبنا."},{s:1,t:"Jetzt sitzt sie auf dem Sofa, zwischen uns.",ar:"الآن تجلس على الأريكة، بيننا."},{s:0,t:"Stell die Blumen in die Vase, auf den Tisch.",ar:"ضع الزهور في المزهرية، على الطاولة."},{s:1,t:"Die Blumen sind jetzt in der Vase, auf dem Tisch.",ar:"الزهور الآن في المزهرية، على الطاولة."},{s:0,t:"Häng deine Jacke an die Garderobe, bitte.",ar:"علّق معطفك على المشجب، من فضلك."},{s:1,t:"Meine Jacke hängt jetzt an der Garderobe.",ar:"معطفي الآن على المشجب."},{s:0,t:"Gehst du in den Garten, oder bleibst du hier?",ar:"هل تذهب إلى الحديقة، أم تبقى هنا؟"},{s:1,t:"Ich bleibe im Wohnzimmer, es ist warm hier.",ar:"أبقى في غرفة الجلوس، الجو دافئ هنا."},{s:0,t:"Stell deine Schuhe vor die Tür, bitte.",ar:"ضع حذاءك أمام الباب، من فضلك."},{s:1,t:"Meine Schuhe stehen jetzt vor der Tür.",ar:"حذائي الآن أمام الباب."},{s:0,t:"Der Schlüssel liegt auf dem Schrank, siehst du ihn?",ar:"المفتاح على الخزانة، هل تراه؟"},{s:1,t:"Ja, ich lege ihn in meine Tasche.",ar:"نعم، أضعه في حقيبتي."},{s:0,t:"Setz dich ans Fenster, die Aussicht ist schön.",ar:"اجلس عند النافذة، المنظر جميل."},{s:1,t:"Ich sitze am Fenster und trinke meinen Tee.",ar:"أجلس عند النافذة وأشرب شايي."},{s:0,t:"Das Haus ist jetzt schön und sauber, oder?",ar:"البيت الآن جميل ونظيف، أليس كذلك؟"},{s:1,t:"Ja, alles steht an seinem Platz.",ar:"نعم، كل شيء في مكانه."},{s:0,t:"Komm morgen wieder, dann sitzen wir im Garten.",ar:"تعال غدًا مرة أخرى، حينها نجلس في الحديقة."},{s:1,t:"Gern! Dann bringe ich Kuchen mit.",ar:"بكل سرور! حينها أحضر الكعك معي."},{s:0,t:"Wir stellen den Kuchen auf den Tisch, in den Garten.",ar:"نضع الكعك على الطاولة، في الحديقة."},{s:1,t:"Und wir sitzen auf den Stühlen, unter dem Baum.",ar:"ونجلس على الكراسي، تحت الشجرة."}]}},{stage:4,topic:"clothes",topicAr:"الملابس والتسوق",topicEn:"Clothes & Shopping",topicDe:"Kleidung und Einkaufen",emoji:"👕",title:"أفضل محل ملابس في المدينة",grammar:{id:"de-adjektivendungen",title:"Adjektivendungen",titleAr:"نهايات الصفات",covers:1},conv:{id:"de-stage4-a2",speakers:["Verkäufer (البائع)","Kunde (الزبون)"],turns:[{s:0,t:"Willkommen! Suchen Sie einen neuen Mantel?",ar:"أهلًا! هل تبحث عن معطف جديد؟"},{s:1,t:"Ja, ich suche einen warmen Mantel für den Winter.",ar:"نعم، أبحث عن معطف دافئ للشتاء."},{s:0,t:"Dieser warme Mantel ist sehr gut und nicht teuer.",ar:"هذا المعطف الدافئ جيد جدًا وليس غاليًا."},{s:1,t:"Der graue Mantel gefällt mir. Ist er warm genug?",ar:"المعطف الرمادي يعجبني. هل هو دافئ بما فيه الكفاية؟"},{s:0,t:"Ja, der graue Mantel ist der wärmste Mantel hier.",ar:"نعم، المعطف الرمادي هو أدفأ معطف هنا."},{s:1,t:"Ich möchte auch eine schöne Jacke kaufen.",ar:"أريد أيضًا شراء سترة جميلة."},{s:0,t:"Diese schöne Jacke passt gut zu dem Mantel.",ar:"هذه السترة الجميلة تناسب المعطف."},{s:1,t:"Die blaue Jacke ist schön. Was kostet sie?",ar:"السترة الزرقاء جميلة. كم سعرها؟"},{s:0,t:"Die blaue Jacke kostet vierzig Euro, ein guter Preis.",ar:"السترة الزرقاء سعرها أربعون يورو، سعر جيد."},{s:1,t:"Haben Sie ein rotes Hemd in meiner Größe?",ar:"هل لديك قميص أحمر بمقاسي؟"},{s:0,t:"Ja, ein rotes Hemd in Größe L ist hier.",ar:"نعم، قميص أحمر بمقاس L هنا."},{s:1,t:"Das rote Hemd ist schön, aber zu teuer für mich.",ar:"القميص الأحمر جميل، لكنه غالٍ عليّ."},{s:0,t:"Ein billiges Hemd in Blau ist dort, sehen Sie?",ar:"قميص رخيص باللون الأزرق هناك، أترى؟"},{s:1,t:"Das billige Hemd gefällt mir nicht so gut.",ar:"القميص الرخيص لا يعجبني كثيرًا."},{s:0,t:"Dann nehmen Sie das schöne Hemd, es passt Ihnen.",ar:"إذن خذ القميص الجميل، إنه يناسبك."},{s:1,t:"Ich brauche auch eine lange Hose für die Arbeit.",ar:"أحتاج أيضًا بنطلونًا طويلًا للعمل."},{s:0,t:"Diese lange Hose ist bequem und modern.",ar:"هذا البنطلون الطويل مريح وعصري."},{s:1,t:"Die schwarze Hose ist zu lang für mich.",ar:"البنطلون الأسود طويل جدًا عليّ."},{s:0,t:"Eine kürzere Hose in Schwarz haben wir auch.",ar:"لدينا أيضًا بنطلون أقصر باللون الأسود."},{s:1,t:"Die kürzere Hose passt perfekt, danke!",ar:"البنطلون الأقصر يناسب تمامًا، شكرًا!"},{s:0,t:"Möchten Sie einen warmen Schal dazu?",ar:"هل تريد وشاحًا دافئًا معه؟"},{s:1,t:"Ja, einen weichen Schal in Weiß, bitte.",ar:"نعم، وشاحًا ناعمًا باللون الأبيض، من فضلك."},{s:0,t:"Der weiche Schal ist aus reiner Wolle.",ar:"الوشاح الناعم من صوف خالص."},{s:1,t:"Ein weicher Schal ist genau richtig im Winter.",ar:"وشاح ناعم مناسب تمامًا في الشتاء."},{s:0,t:"Und schöne Handschuhe? Wir haben warme Handschuhe.",ar:"وقفازات جميلة؟ لدينا قفازات دافئة."},{s:1,t:"Die warmen Handschuhe sind gut, ich nehme sie.",ar:"القفازات الدافئة جيدة، سآخذها."},{s:0,t:"Ein schöner Hut passt gut zu dem Mantel.",ar:"قبعة جميلة تناسب المعطف."},{s:1,t:"Der schöne Hut ist mir zu groß, leider.",ar:"القبعة الجميلة كبيرة عليّ، للأسف."},{s:0,t:"Ein kleinerer Hut in Braun ist hier.",ar:"قبعة أصغر باللون البني هنا."},{s:1,t:"Der kleinere Hut sitzt gut, ich kaufe ihn.",ar:"القبعة الأصغر تناسب جيدًا، سأشتريها."},{s:0,t:"Das ist eine gute Wahl, wirklich!",ar:"هذا اختيار جيد، حقًا!"},{s:1,t:"Was ist der beste Mantel in Ihrem Geschäft?",ar:"ما أفضل معطف في متجرك؟"},{s:0,t:"Der beste Mantel ist dieser graue Mantel hier.",ar:"أفضل معطف هو هذا المعطف الرمادي هنا."},{s:1,t:"Und das schönste Kleid für meine Tochter?",ar:"وأجمل فستان لابنتي؟"},{s:0,t:"Das schönste Kleid ist das gelbe Kleid dort.",ar:"أجمل فستان هو الفستان الأصفر هناك."},{s:1,t:"Ein gelbes Kleid ist perfekt für den Sommer.",ar:"فستان أصفر مثالي للصيف."},{s:0,t:"Die neuen Schuhe sind auch sehr bequem.",ar:"الأحذية الجديدة مريحة جدًا أيضًا."},{s:1,t:"Die bequemen Schuhe kaufe ich nächste Woche.",ar:"الأحذية المريحة سأشتريها الأسبوع المقبل."},{s:0,t:"Alles zusammen kostet neunzig Euro, bitte.",ar:"المجموع تسعون يورو، من فضلك."},{s:1,t:"Neunzig Euro ist ein guter Preis, danke.",ar:"تسعون يورو سعر جيد، شكرًا."},{s:0,t:"Kommen Sie bald wieder, wir haben neue Sachen.",ar:"تعال قريبًا مرة أخرى، لدينا أشياء جديدة."},{s:1,t:"Gern! Ihr Geschäft ist das beste in der Stadt.",ar:"بكل سرور! متجرك هو الأفضل في المدينة."},{s:0,t:"Danke! Sie sind ein freundlicher Kunde.",ar:"شكرًا! أنت زبون لطيف."},{s:1,t:"Auf Wiedersehen! Bis nächste Woche!",ar:"إلى اللقاء! حتى الأسبوع المقبل!"}]}},{stage:5,topic:"routine",topicAr:"اليوم الروتيني والمدرسة والعمل",topicEn:"Daily Routine, School & Work",topicDe:"Alltag, Schule und Arbeit",emoji:"⏰",title:"ماذا فعلت أمس؟",grammar:{id:"de-trennbar-vergangenheit",title:"Trennbare Verben in der Vergangenheit",titleAr:"الأفعال المنفصلة في الماضي",covers:1},conv:{id:"de-stage5-a2",speakers:["Schüler (الطالب)","Mitschüler (زميل الدراسة)"],turns:[{s:0,t:"Hallo! Wann bist du gestern aufgestanden?",ar:"مرحبًا! متى استيقظت أمس؟"},{s:1,t:"Ich bin um sechs Uhr aufgestanden.",ar:"استيقظت في السادسة."},{s:0,t:"Hast du deine Mutter angerufen?",ar:"هل اتصلت بأمك؟"},{s:1,t:"Nein, ich habe meinen Freund angerufen.",ar:"لا، اتصلت بصديقي."},{s:0,t:"Bist du mit dem Bus zur Schule gefahren?",ar:"هل ذهبت بالحافلة إلى المدرسة؟"},{s:1,t:"Nein, ich bin mit meinem Vater mitgefahren.",ar:"لا، ذهبت مع أبي."},{s:0,t:"Was hast du in der Schule gemacht?",ar:"ماذا فعلت في المدرسة؟"},{s:1,t:"Wir haben einen Test geschrieben, er war schwer.",ar:"كتبنا اختبارًا، كان صعبًا."},{s:0,t:"Hast du deine Bücher eingepackt?",ar:"هل حزمت كتبك؟"},{s:1,t:"Ja, ich habe alles eingepackt, auch mein Heft.",ar:"نعم، حزمت كل شيء، حتى دفتري."},{s:0,t:"Was hast du in der Pause gemacht?",ar:"ماذا فعلت في الاستراحة؟"},{s:1,t:"Ich habe mit Freunden Fußball gespielt.",ar:"لعبت كرة القدم مع الأصدقاء."},{s:0,t:"Hast du gestern eingekauft?",ar:"هل تسوقت أمس؟"},{s:1,t:"Ja, ich habe Brot und Milch eingekauft.",ar:"نعم، اشتريت خبزًا وحليبًا."},{s:0,t:"Wann bist du nach Hause zurückgekommen?",ar:"متى عدت إلى البيت؟"},{s:1,t:"Ich bin um drei Uhr zurückgekommen.",ar:"عدت في الثالثة."},{s:0,t:"Hast du deine Hausaufgaben gemacht?",ar:"هل قمت بواجباتك؟"},{s:1,t:"Ja, ich habe sie sofort gemacht.",ar:"نعم، قمت بها فورًا."},{s:0,t:"Hast du am Abend ferngesehen?",ar:"هل شاهدت التلفاز في المساء؟"},{s:1,t:"Nein, ich habe ein Buch gelesen.",ar:"لا، قرأت كتابًا."},{s:0,t:"Bist du früh eingeschlafen?",ar:"هل نمت مبكرًا؟"},{s:1,t:"Ja, ich bin um zehn eingeschlafen.",ar:"نعم، نمت في العاشرة."},{s:0,t:"Hast du deinen Freund gestern angerufen?",ar:"هل اتصلت بصديقك أمس؟"},{s:1,t:"Ja, ich habe ihn zweimal angerufen.",ar:"نعم، اتصلت به مرتين."},{s:0,t:"Hat dich deine Mutter aufgeweckt?",ar:"هل أيقظتك أمك؟"},{s:1,t:"Ja, sie hat mich um sechs aufgeweckt.",ar:"نعم، أيقظتني في السادسة."},{s:0,t:"Bist du heute früh aufgestanden?",ar:"هل استيقظت مبكرًا اليوم؟"},{s:1,t:"Ja, ich bin um halb sieben aufgestanden.",ar:"نعم، استيقظت في السادسة والنصف."},{s:0,t:"Was hast du zum Frühstück vorbereitet?",ar:"ماذا حضرت للفطور؟"},{s:1,t:"Ich habe Brot und Tee vorbereitet.",ar:"حضرت خبزًا وشايًا."},{s:0,t:"Hast du an dem Spiel teilgenommen?",ar:"هل شاركت في المباراة؟"},{s:1,t:"Ja, ich habe teilgenommen und ein Tor geschossen.",ar:"نعم، شاركت وسجلت هدفًا."},{s:0,t:"Bist du nach dem Spiel nach Hause gegangen?",ar:"هل ذهبت إلى البيت بعد المباراة؟"},{s:1,t:"Nein, ich bin mit Freunden ausgegangen.",ar:"لا، خرجت مع الأصدقاء."},{s:0,t:"Wohin seid ihr ausgegangen?",ar:"إلى أين خرجتم؟"},{s:1,t:"Wir sind in den Park gegangen.",ar:"ذهبنا إلى الحديقة."},{s:0,t:"Hast du deine Jacke angezogen?",ar:"هل ارتديت معطفك؟"},{s:1,t:"Ja, ich habe sie schnell angezogen.",ar:"نعم، ارتديته بسرعة."},{s:0,t:"Hast du dein Zimmer aufgeräumt?",ar:"هل رتبت غرفتك؟"},{s:1,t:"Ja, ich habe alles aufgeräumt, auch mein Bett.",ar:"نعم، رتبت كل شيء، حتى سريري."},{s:0,t:"Wann hast du angefangen, Deutsch zu lernen?",ar:"متى بدأت تتعلم الألمانية؟"},{s:1,t:"Ich habe vor zwei Jahren angefangen.",ar:"بدأت قبل سنتين."},{s:0,t:"Du hast gestern viel gemacht, wirklich!",ar:"فعلت الكثير أمس، حقًا!"},{s:1,t:"Ja, es war ein guter Tag.",ar:"نعم، كان يومًا جيدًا."}]}},{stage:6,topic:"weather",topicAr:"الأوقات والطقس",topicEn:"Times & Weather",topicDe:"Zeiten und Wetter",emoji:"🌤️",title:"إذا مطرت، ماذا نفعل؟",grammar:{id:"de-nebensaetze",title:"Nebensätze mit weil, wenn, dass",titleAr:"الجمل التابعة (weil / wenn / dass)",covers:1},conv:{id:"de-stage6-a2",speakers:["Freund (الصديق)","Nachbar (الجار)"],turns:[{s:0,t:"Sieh den Himmel! Ich glaube, dass es bald regnet.",ar:"انظر إلى السماء! أعتقد أنه سيمطر قريبًا."},{s:1,t:"Ja, ich bleibe zu Hause, weil es regnet.",ar:"نعم، أبقى في البيت، لأنه يمطر."},{s:0,t:"Wenn es regnet, trinken wir Tee zu Hause.",ar:"إذا مطرت، نشرب الشاي في البيت."},{s:1,t:"Ich mache Tee, weil du meinen Tee liebst.",ar:"أحضر الشاي، لأنك تحب شايي."},{s:0,t:"Wenn die Sonne scheint, gehen wir in den Park.",ar:"إذا أشرقت الشمس، نذهب إلى الحديقة."},{s:1,t:"Ich freue mich, dass die Sonne scheint.",ar:"أنا سعيد لأن الشمس مشرقة."},{s:0,t:"Wenn es warm ist, sitzen wir im Garten.",ar:"إذا كان الجو دافئًا، نجلس في الحديقة."},{s:1,t:"Ich sitze gern im Garten, weil es dort schön ist.",ar:"أحب الجلوس في الحديقة، لأنه جميل هناك."},{s:0,t:"Wenn es kalt ist, bleibe ich im Haus.",ar:"إذا كان الجو باردًا، أبقى في البيت."},{s:1,t:"Ich bleibe im Haus, weil ich krank bin.",ar:"أبقى في البيت، لأنني مريض."},{s:0,t:"Ich glaube, dass es morgen schneit.",ar:"أعتقد أنه سيثلج غدًا."},{s:1,t:"Wenn es schneit, spielen die Kinder im Schnee.",ar:"إذا ثلجت، يلعب الأطفال في الثلج."},{s:0,t:"Die Kinder sind glücklich, weil sie Schnee lieben.",ar:"الأطفال سعداء، لأنهم يحبون الثلج."},{s:1,t:"Wenn der Wind stark ist, schließen wir die Fenster.",ar:"إذا كانت الرياح قوية، نغلق النوافذ."},{s:0,t:"Wir schließen die Fenster, weil es kalt ist.",ar:"نغلق النوافذ، لأنه بارد."},{s:1,t:"Ich hoffe, dass das Wetter morgen gut ist.",ar:"آمل أن يكون الطقس جيدًا غدًا."},{s:0,t:"Wenn das Wetter gut ist, kommst du morgen?",ar:"إذا كان الطقس جيدًا، هل تأتي غدًا؟"},{s:1,t:"Ja, wenn das Wetter gut ist, komme ich gern.",ar:"نعم، إذا كان الطقس جيدًا، آتي بكل سرور."},{s:0,t:"Ich koche gut, weil ich gern koche.",ar:"أطبخ جيدًا، لأنني أحب الطبخ."},{s:1,t:"Wenn du gut kochst, bringe ich Kuchen mit.",ar:"إذا طبخت جيدًا، أحضر الكعك معي."},{s:0,t:"Ich weiß, dass du Kuchen liebst.",ar:"أعلم أنك تحب الكعك."},{s:1,t:"Wenn wir einen Film sehen, mache ich Popcorn.",ar:"إذا شاهدنا فيلمًا، أحضر الفشار."},{s:0,t:"Ich bleibe zu Hause, weil der Sturm kommt.",ar:"أبقى في البيت، لأن العاصفة قادمة."},{s:1,t:"Wenn der Sturm kommt, lesen wir Bücher.",ar:"إذا جاءت العاصفة، نقرأ الكتب."},{s:0,t:"Ich lese gern, weil ich neue Wörter lerne.",ar:"أحب القراءة، لأنني أتعلم كلمات جديدة."},{s:1,t:"Wenn ich neue Wörter lerne, spreche ich besser.",ar:"إذا تعلمت كلمات جديدة، أتحدث بشكل أفضل."},{s:0,t:"Wenn es am Sonntag sonnig ist, gehen wir aus.",ar:"إذا كان الجو مشمسًا يوم الأحد، نخرج."},{s:1,t:"Ich gehe gern aus, weil die Stadt schön ist.",ar:"أحب الخروج، لأن المدينة جميلة."},{s:0,t:"Wenn wir ausgehen, besuchen wir den Markt.",ar:"إذا خرجنا، نزور السوق."},{s:1,t:"Ich kaufe Obst, weil es frisch ist.",ar:"أشتري الفاكهة، لأنها طازجة."},{s:0,t:"Wenn der Bus spät ist, gehen wir zu Fuß.",ar:"إذا تأخرت الحافلة، نمشي على الأقدام."},{s:1,t:"Ich gehe zu Fuß, weil ich gern laufe.",ar:"أمشي على الأقدام، لأنني أحب المشي."},{s:0,t:"Ich fahre dich, weil du müde bist.",ar:"أوصلك بالسيارة، لأنك متعب."},{s:1,t:"Danke! Ich freue mich, dass du mein Freund bist.",ar:"شكرًا! أنا سعيد لأنك صديقي."},{s:0,t:"Wenn es morgen regnet, rufst du mich an?",ar:"إذا مطرت غدًا، هل تتصل بي؟"},{s:1,t:"Ja, wenn es regnet, rufe ich dich früh an.",ar:"نعم، إذا مطرت، أتصل بك مبكرًا."},{s:0,t:"Ich warte auf dich, wenn du mich anrufst.",ar:"سأنتظرك إذا اتصلت بي."},{s:1,t:"Wenn wir uns morgen treffen, planen wir die Reise.",ar:"إذا التقينا غدًا، نخطط للرحلة."},{s:0,t:"Ich glaube, dass die Reise schön wird.",ar:"أعتقد أن الرحلة ستكون جميلة."},{s:1,t:"Wenn die Reise lang ist, nehmen wir Essen mit.",ar:"إذا كانت الرحلة طويلة، نأخذ طعامًا معنا."},{s:0,t:"Wir essen im Park, weil das Wetter gut ist.",ar:"نأكل في الحديقة، لأن الطقس جيد."},{s:1,t:"Das ist ein guter Plan, mein Freund.",ar:"هذه خطة جيدة، يا صديقي."},{s:0,t:"Ich bin glücklich, weil du glücklich bist.",ar:"أنا سعيد، لأنك سعيد."},{s:1,t:"Ja! Wenn wir zusammen sind, ist alles gut.",ar:"نعم! إذا كنا معًا، فكل شيء جيد."}]}},{stage:7,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"أخبار من المكالمة",grammar:{id:"de-modal-past",title:"Modalverben in der Vergangenheit",titleAr:"أفعال الوجوب في الماضي",covers:1},conv:{id:"de-stage7-a2",speakers:["Anrufer (المتصل)","Freund (الصديق)"],turns:[{s:0,t:"Hallo! Ich musste gestern lange arbeiten.",ar:"مرحبًا! اضطررت للعمل طويلًا أمس."},{s:1,t:"Wirklich? Musstest du bis spät arbeiten?",ar:"حقًا؟ هل اضطررت للعمل حتى وقت متأخر؟"},{s:0,t:"Ja, ich musste bis zehn Uhr arbeiten.",ar:"نعم، اضطررت للعمل حتى العاشرة."},{s:1,t:"Konntest du danach noch schlafen?",ar:"هل استطعت النوم بعدها؟"},{s:0,t:"Nein, ich konnte nicht gut schlafen.",ar:"لا، لم أستطع النوم جيدًا."},{s:1,t:"Wolltest du heute frei haben?",ar:"هل أردت أن تأخذ إجازة اليوم؟"},{s:0,t:"Ja, ich wollte heute frei haben, aber es ging nicht.",ar:"نعم، أردت إجازة اليوم، لكن لم يكن ممكنًا."},{s:1,t:"Musste deine Frau auch arbeiten?",ar:"هل اضطرت زوجتك للعمل أيضًا؟"},{s:0,t:"Nein, sie durfte heute zu Hause bleiben.",ar:"لا، سُمح لها بالبقاء في البيت اليوم."},{s:1,t:"Konnte sie den ganzen Tag ausruhen?",ar:"هل استطاعت الراحة طوال اليوم؟"},{s:0,t:"Ja, sie konnte lange schlafen und lesen.",ar:"نعم، استطاعت النوم طويلًا والقراءة."},{s:1,t:"Was wolltet ihr am Wochenende machen?",ar:"ماذا أردتم أن تفعلوا في عطلة الأسبوع؟"},{s:0,t:"Wir wollten in den Park gehen, aber es regnete.",ar:"أردنا الذهاب إلى الحديقة، لكنها أمطرت."},{s:1,t:"Musstet ihr dann zu Hause bleiben?",ar:"هل اضطررتم للبقاء في البيت حينها؟"},{s:0,t:"Ja, wir mussten zu Hause bleiben und Tee trinken.",ar:"نعم، اضطررنا للبقاء في البيت وشرب الشاي."},{s:1,t:"Durftet ihr wenigstens fernsehen?",ar:"هل سُمح لكم على الأقل بمشاهدة التلفاز؟"},{s:0,t:"Ja, wir durften fernsehen und Bücher lesen.",ar:"نعم، سُمح لنا بمشاهدة التلفاز وقراءة الكتب."},{s:1,t:"Solltest du heute zum Arzt gehen?",ar:"هل كان يجب أن تذهب إلى الطبيب اليوم؟"},{s:0,t:"Ja, ich sollte zum Arzt gehen, aber ich hatte keine Zeit.",ar:"نعم، كان يجب أن أذهب إلى الطبيب، لكن لم يكن لدي وقت."},{s:1,t:"Mochtest du den Film gestern Abend?",ar:"هل أعجبك الفيلم مساء أمس؟"},{s:0,t:"Ja, ich mochte ihn sehr, er war lustig.",ar:"نعم، أعجبني كثيرًا، كان مضحكًا."},{s:1,t:"Wollte dein Bruder auch kommen?",ar:"هل أراد أخوك أن يأتي أيضًا؟"},{s:0,t:"Nein, er wollte lieber zu Hause bleiben.",ar:"لا، أراد البقاء في البيت بالأحرى."},{s:1,t:"Konnte er nicht kommen, oder wollte er nicht?",ar:"هل لم يستطع المجيء، أم لم يرد؟"},{s:0,t:"Er konnte nicht kommen, er musste arbeiten.",ar:"لم يستطع المجيء، اضطر للعمل."},{s:1,t:"Musste er am Sonntag auch arbeiten?",ar:"هل اضطر للعمل يوم الأحد أيضًا؟"},{s:0,t:"Nein, am Sonntag durfte er frei haben.",ar:"لا، يوم الأحد سُمح له بالإجازة."},{s:1,t:"Was sollte er am Sonntag machen?",ar:"ماذا كان يجب أن يفعل يوم الأحد؟"},{s:0,t:"Er sollte seine Mutter besuchen, das war wichtig.",ar:"كان يجب أن يزور أمه، كان ذلك مهمًا."},{s:1,t:"Konnte er seine Mutter besuchen?",ar:"هل استطاع زيارة أمه؟"},{s:0,t:"Ja, er konnte sie besuchen und mit ihr essen.",ar:"نعم، استطاع زيارتها والأكل معها."},{s:1,t:"Mochte seine Mutter das Essen?",ar:"هل أعجب أمه الطعام؟"},{s:0,t:"Ja, sie mochte es sehr, es war lecker.",ar:"نعم، أعجبها كثيرًا، كان لذيذًا."},{s:1,t:"Wolltest du auch mitkommen?",ar:"هل أردت أن تأتي معنا أيضًا؟"},{s:0,t:"Ja, ich wollte mitkommen, aber ich war müde.",ar:"نعم، أردت المجيء معكم، لكنني كنت متعبًا."},{s:1,t:"Musstest du früh schlafen gehen?",ar:"هل اضطررت للنوم مبكرًا؟"},{s:0,t:"Ja, ich musste früh schlafen, ich war sehr müde.",ar:"نعم، اضطررت للنوم مبكرًا، كنت متعبًا جدًا."},{s:1,t:"Konntest du gut schlafen?",ar:"هل استطعت النوم جيدًا؟"},{s:0,t:"Ja, ich konnte sehr gut schlafen, danke.",ar:"نعم، استطعت النوم جيدًا جدًا، شكرًا."},{s:1,t:"Sollten wir uns morgen wieder treffen?",ar:"هل يجب أن نلتقي غدًا مرة أخرى؟"},{s:0,t:"Ja, wir sollten uns morgen um zehn treffen.",ar:"نعم، يجب أن نلتقي غدًا في العاشرة."},{s:1,t:"Ich wollte dich das schon lange fragen.",ar:"أردت أن أسألك هذا منذ زمن طويل."},{s:0,t:"Frag mich! Ich musste lange auf dich warten.",ar:"اسألني! اضطررت لانتظارك طويلًا."},{s:1,t:"Danke, mein Freund! Wir konnten gut sprechen.",ar:"شكرًا، يا صديقي! استطعنا التحدث جيدًا."}]}},{stage:8,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"كيف كنا نسافر من قبل؟",grammar:{id:"de-relativsaetze",title:"Relativsätze",titleAr:"الجمل الوصلية",covers:1},conv:{id:"de-stage8-a2",speakers:["Fahrer (السائق)","Fahrgast (الراكب)"],turns:[{s:0,t:"Guten Morgen! Wohin fahren Sie heute?",ar:"صباح الخير! إلى أين تذهب اليوم؟"},{s:1,t:"In die Altstadt, in der ich früher wohnte.",ar:"إلى البلدة القديمة، التي كنت أعيش فيها سابقًا."},{s:0,t:"Die Altstadt, die sehr schön ist, liegt weit weg.",ar:"البلدة القديمة، الجميلة جدًا، بعيدة."},{s:1,t:"Ja, der Bus, der dorthin fährt, ist alt.",ar:"نعم، الحافلة التي تذهب إلى هناك قديمة."},{s:0,t:"Der Fahrer, der den Bus fährt, ist mein Freund.",ar:"السائق الذي يقود الحافلة صديقي."},{s:1,t:"Der Mann, der neben mir sitzt, liest ein Buch.",ar:"الرجل الذي يجلس بجانبي يقرأ كتابًا."},{s:0,t:"Das Buch, das er liest, ist sehr gut.",ar:"الكتاب الذي يقرأه جيد جدًا."},{s:1,t:"Die Frau, die dort steht, wartet auf den Bus.",ar:"المرأة التي تقف هناك تنتظر الحافلة."},{s:0,t:"Das Kind, das bei ihr ist, spielt mit einem Ball.",ar:"الطفل الذي معها يلعب بالكرة."},{s:1,t:"Der Ball, der rot ist, rollt auf die Straße.",ar:"الكرة الحمراء تتدحرج إلى الشارع."},{s:0,t:"Die Straße, auf der wir fahren, ist neu.",ar:"الشارع الذي نسير فيه جديد."},{s:1,t:"Das Haus, in dem ich wohne, ist alt.",ar:"البيت الذي أسكن فيه قديم."},{s:0,t:"Die Stadt, in der wir leben, ist groß.",ar:"المدينة التي نعيش فيها كبيرة."},{s:1,t:"Der Park, in dem wir spielen, ist schön.",ar:"الحديقة التي نلعب فيها جميلة."},{s:0,t:"Die Schule, in die mein Sohn geht, ist neu.",ar:"المدرسة التي يذهب إليها ابني جديدة."},{s:1,t:"Der Lehrer, der dort arbeitet, ist sehr nett.",ar:"المعلم الذي يعمل هناك لطيف جدًا."},{s:0,t:"Die Kinder, die dort lernen, sind glücklich.",ar:"الأطفال الذين يتعلمون هناك سعداء."},{s:1,t:"Das Brot, das ich kaufe, ist frisch.",ar:"الخبز الذي أشتريه طازج."},{s:0,t:"Der Bäcker, der es backt, ist mein Nachbar.",ar:"الخباز الذي يخبزه جاري."},{s:1,t:"Der Markt, auf dem wir einkaufen, ist groß.",ar:"السوق الذي نتسوق فيه كبير."},{s:0,t:"Die Äpfel, die ich dort kaufe, sind süß.",ar:"التفاح الذي أشتريه هناك حلو."},{s:1,t:"Der Fluss, an dem wir sitzen, ist ruhig.",ar:"النهر الذي نجلس عنده هادئ."},{s:0,t:"Die Brücke, über die wir fahren, ist alt.",ar:"الجسر الذي نعبره قديم."},{s:1,t:"Das Dorf, aus dem ich komme, ist klein.",ar:"القرية التي أتيت منها صغيرة."},{s:0,t:"Die Menschen, die dort wohnen, sind freundlich.",ar:"الناس الذين يعيشون هناك ودودون."},{s:1,t:"Der Zug, mit dem wir fahren, ist schnell.",ar:"القطار الذي نسافر به سريع."},{s:0,t:"Die Frau, mit der ich spreche, ist meine Schwester.",ar:"المرأة التي أتحدث معها أختي."},{s:1,t:"Der Mann, von dem ich spreche, ist mein Bruder.",ar:"الرجل الذي أتحدث عنه أخي."},{s:0,t:"Das Buch, von dem ich Ihnen erzählt habe, ist gut.",ar:"الكتاب الذي حدثتكم عنه جيد."},{s:1,t:"Die Stadt, von der ich träume, ist Berlin.",ar:"المدينة التي أحلم بها هي برلين."},{s:0,t:"Der Tag, an dem wir uns trafen, war schön.",ar:"اليوم الذي التقينا فيه كان جميلًا."},{s:1,t:"Die Zeit, in der wir jung waren, war schön.",ar:"الوقت الذي كنا فيه صغارًا كان جميلًا."},{s:0,t:"Das Haus, vor dem wir stehen, ist mein Haus.",ar:"البيت الذي نقف أمامه بيتي."},{s:1,t:"Der Garten, hinter dem wir sitzen, ist groß.",ar:"الحديقة التي نجلس خلفها كبيرة."},{s:0,t:"Die Katze, die auf dem Sofa sitzt, ist meine Katze.",ar:"القطة التي تجلس على الأريكة قطتي."},{s:1,t:"Der Hund, der im Garten spielt, ist mein Hund.",ar:"الكلب الذي يلعب في الحديقة كلبي."},{s:0,t:"Die Freunde, die mich besuchen, sind nett.",ar:"الأصدقاء الذين يزورونني لطيفون."},{s:1,t:"Das Essen, das meine Mutter kocht, ist lecker.",ar:"الطعام الذي تطبخه أمي لذيذ."},{s:0,t:"Die Musik, die wir hören, ist schön.",ar:"الموسيقى التي نسمعها جميلة."},{s:1,t:"Der Film, den wir sehen, ist lustig.",ar:"الفيلم الذي نشاهده مضحك."},{s:0,t:"Die Reise, die wir planen, wird schön.",ar:"الرحلة التي نخطط لها ستكون جميلة."},{s:1,t:"Die Zukunft, von der wir träumen, ist nah.",ar:"المستقبل الذي نحلم به قريب."},{s:0,t:"Der Bus, in dem wir sitzen, fährt in die Stadt.",ar:"الحافلة التي نجلس فيها تذهب إلى المدينة."},{s:1,t:"Ja! Die Stadt, die wir lieben, ist groß und schön.",ar:"نعم! المدينة التي نحبها كبيرة وجميلة."}]}},{stage:9,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"نصائح الطبيب",grammar:{id:"de-passiv",title:"Passiv",titleAr:"المبني للمجهول",covers:1},conv:{id:"de-stage9-a2",speakers:["Arzt (الطبيب)","Patient (المريض)"],turns:[{s:0,t:"Guten Morgen! Was fehlt Ihnen heute?",ar:"صباح الخير! ما الذي يؤلمك اليوم؟"},{s:1,t:"Ich habe Kopfschmerzen und bin sehr müde.",ar:"لدي صداع وأنا متعب جدًا."},{s:0,t:"Der Kopf wird jetzt untersucht, bitte setzen Sie sich.",ar:"سيُفحص الرأس الآن، اجلس من فضلك."},{s:1,t:"Wird das Blut auch untersucht?",ar:"هل سيُفحص الدم أيضًا؟"},{s:0,t:"Ja, das Blut wird morgen im Labor untersucht.",ar:"نعم، سيُفحص الدم غدًا في المختبر."},{s:1,t:"Wird mir ein Medikament gegeben?",ar:"هل سيُعطى لي دواء؟"},{s:0,t:"Ja, ein Medikament wird Ihnen zweimal am Tag gegeben.",ar:"نعم، سيُعطى لك دواء مرتين في اليوم."},{s:1,t:"Wie wird das Medikament genommen?",ar:"كيف يُؤخذ الدواء؟"},{s:0,t:"Es wird nach dem Essen, mit Wasser, genommen.",ar:"يُؤخذ بعد الطعام، مع الماء."},{s:1,t:"Wird das Medikament in der Apotheke verkauft?",ar:"هل يُباع الدواء في الصيدلية؟"},{s:0,t:"Ja, es wird in jeder Apotheke verkauft.",ar:"نعم، يُباع في كل صيدلية."},{s:1,t:"Wird der Arm auch untersucht?",ar:"هل سيُفحص الذراع أيضًا؟"},{s:0,t:"Ja, der Arm wird jetzt untersucht.",ar:"نعم، سيُفحص الذراع الآن."},{s:1,t:"Wird der Blutdruck gemessen?",ar:"هل سيُقاس ضغط الدم؟"},{s:0,t:"Ja, der Blutdruck wird jeden Tag gemessen.",ar:"نعم، يُقاس ضغط الدم كل يوم."},{s:1,t:"Wird das Herz auch untersucht?",ar:"هل سيُفحص القلب أيضًا؟"},{s:0,t:"Ja, das Herz wird mit einem Gerät untersucht.",ar:"نعم، سيُفحص القلب بجهاز."},{s:1,t:"Was wird mir geraten?",ar:"بماذا يُنصح لي؟"},{s:0,t:"Es wird Ihnen geraten, viel Wasser zu trinken.",ar:"يُنصح لك بشرب الكثير من الماء."},{s:1,t:"Wird mir auch Sport empfohlen?",ar:"هل يُوصى لي بالرياضة أيضًا؟"},{s:0,t:"Ja, ein Spaziergang wird jeden Tag empfohlen.",ar:"نعم، يُوصى بالمشي كل يوم."},{s:1,t:"Wird die Übung im Park gemacht?",ar:"هل تُمارس التمارين في الحديقة؟"},{s:0,t:"Ja, die Übungen werden im Park gemacht.",ar:"نعم، تُمارس التمارين في الحديقة."},{s:1,t:"Wird das Essen im Krankenhaus gegeben?",ar:"هل يُعطى الطعام في المستشفى؟"},{s:0,t:"Ja, das Essen wird dreimal am Tag gegeben.",ar:"نعم، يُعطى الطعام ثلاث مرات في اليوم."},{s:1,t:"Wird das Zimmer jeden Tag gereinigt?",ar:"هل تُنظف الغرفة كل يوم؟"},{s:0,t:"Ja, das Zimmer wird jeden Morgen gereinigt.",ar:"نعم، تُنظف الغرفة كل صباح."},{s:1,t:"Wird die Tür nachts geschlossen?",ar:"هل يُغلق الباب ليلًا؟"},{s:0,t:"Ja, die Tür wird um zehn Uhr geschlossen.",ar:"نعم، يُغلق الباب في العاشرة."},{s:1,t:"Wird das Bett auch gemacht?",ar:"هل يُرتب السرير أيضًا؟"},{s:0,t:"Ja, das Bett wird jeden Morgen gemacht.",ar:"نعم، يُرتب السرير كل صباح."},{s:1,t:"Was wird morgen gemacht?",ar:"ماذا سيُفعل غدًا؟"},{s:0,t:"Morgen wird eine neue Untersuchung gemacht.",ar:"غدًا سيُجرى فحص جديد."},{s:1,t:"Wird die Untersuchung weh tun?",ar:"هل سيؤلم الفحص؟"},{s:0,t:"Nein, die Untersuchung wird nicht weh tun.",ar:"لا، لن يؤلم الفحص."},{s:1,t:"Wird mir alles erklärt?",ar:"هل سيُشرح لي كل شيء؟"},{s:0,t:"Ja, alles wird Ihnen genau erklärt.",ar:"نعم، سيُشرح لك كل شيء بدقة."},{s:1,t:"Wird der Termin nächste Woche gemacht?",ar:"هل سيُحدد الموعد الأسبوع المقبل؟"},{s:0,t:"Ja, der Termin wird für nächste Woche gemacht.",ar:"نعم، سيُحدد الموعد للأسبوع المقبل."},{s:1,t:"Vielen Dank, Herr Doktor! Alles wird gut, oder?",ar:"شكرًا جزيلًا، يا دكتور! كل شيء سيكون بخير، أليس كذلك؟"},{s:0,t:"Ja, alles wird gut, wenn Sie sich ausruhen.",ar:"نعم، كل شيء سيكون بخير، إذا استرحت."},{s:1,t:"Ich werde mich ausruhen, das verspreche ich.",ar:"سأستريح، هذا وعد مني."},{s:0,t:"Gut! Das Medikament wird Ihnen helfen.",ar:"جيد! الدواء سيساعدك."},{s:1,t:"Auf Wiedersehen, Herr Doktor! Danke schön!",ar:"إلى اللقاء، يا دكتور! شكرًا جزيلًا!"}]}},{stage:10,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"هواية جديدة",grammar:{id:"de-reflexiv",title:"Reflexive Verben",titleAr:"الأفعال الانعكاسية",covers:1},conv:{id:"de-stage10-a2",speakers:["Spieler (اللاعب)","Freund (الصديق)"],turns:[{s:0,t:"Hallo! Freust du dich auf das Spiel?",ar:"مرحبًا! هل أنت متحمس للمباراة؟"},{s:1,t:"Ja, ich freue mich sehr auf das Spiel.",ar:"نعم، أنا متحمس جدًا للمباراة."},{s:0,t:"Bereite dich gut vor, das Spiel ist wichtig.",ar:"استعد جيدًا، المباراة مهمة."},{s:1,t:"Ich bereite mich vor, ich ziehe meine Schuhe an.",ar:"أستعد، أرتدي حذائي."},{s:0,t:"Entspann dich vor dem Spiel, sei ruhig.",ar:"استرخِ قبل المباراة، كن هادئًا."},{s:1,t:"Ich entspanne mich, ich atme tief ein.",ar:"أسترخي، أتنفس بعمق."},{s:0,t:"Melde dich für das Turnier an, bitte.",ar:"سجّل نفسك للبطولة، من فضلك."},{s:1,t:"Ich melde mich heute noch an.",ar:"سأسجل نفسي اليوم."},{s:0,t:"Treffen wir uns um fünf Uhr im Park?",ar:"هل نلتقي في الخامسة في الحديقة؟"},{s:1,t:"Ja, wir treffen uns um fünf Uhr dort.",ar:"نعم، نلتقي في الخامسة هناك."},{s:0,t:"Beeil dich, der Bus fährt bald ab.",ar:"أسرع، الحافلة ستغادر قريبًا."},{s:1,t:"Ich beeile mich, ich bin schon fertig.",ar:"أسرع، أنا جاهز بالفعل."},{s:0,t:"Setz dich hier hin und ruh dich aus.",ar:"اجلس هنا واسترح."},{s:1,t:"Ich setze mich hin und ruhe mich aus.",ar:"أجلس وأستريح."},{s:0,t:"Wärm dich auf, bevor das Spiel beginnt.",ar:"قم بالإحماء قبل أن تبدأ المباراة."},{s:1,t:"Ich wärme mich auf, ich laufe schon.",ar:"أقوم بالإحماء، أنا أركض بالفعل."},{s:0,t:"Konzentrier dich auf den Ball, nicht auf die Zuschauer.",ar:"ركز على الكرة، وليس على الجمهور."},{s:1,t:"Ich konzentriere mich auf den Ball.",ar:"أركز على الكرة."},{s:0,t:"Verletz dich nicht, pass gut auf!",ar:"لا تجرح نفسك، انتبه جيدًا!"},{s:1,t:"Ich verletze mich nicht, ich passe auf.",ar:"لن أجرح نفسي، أنا منتبه."},{s:0,t:"Freu dich nicht zu früh, das Spiel läuft noch.",ar:"لا تفرح مبكرًا، المباراة ما زالت جارية."},{s:1,t:"Ich freue mich erst, wenn wir gewinnen.",ar:"سأفرح فقط عندما نفوز."},{s:0,t:"Erinnerst du dich an das letzte Spiel?",ar:"هل تتذكر المباراة الأخيرة؟"},{s:1,t:"Ja, ich erinnere mich gut daran.",ar:"نعم، أتذكرها جيدًا."},{s:0,t:"Damals haben wir uns sehr angestrengt.",ar:"حينها بذلنا جهدًا كبيرًا."},{s:1,t:"Wir haben uns angestrengt, aber wir haben verloren.",ar:"بذلنا جهدًا، لكننا خسرنا."},{s:0,t:"Ärger dich nicht, nächstes Mal gewinnen wir.",ar:"لا تغضب، في المرة القادمة سنفوز."},{s:1,t:"Ich ärgere mich nicht, ich trainiere mehr.",ar:"لا أغضب، سأتدرب أكثر."},{s:0,t:"Dusch dich nach dem Spiel, du bist nass.",ar:"استحم بعد المباراة، أنت مبلل."},{s:1,t:"Ich dusche mich gleich nach dem Spiel.",ar:"سأستحم مباشرة بعد المباراة."},{s:0,t:"Zieh dich um, deine Sachen sind nass.",ar:"غيّر ملابسك، ملابسك مبللة."},{s:1,t:"Ich ziehe mich um und ruhe mich aus.",ar:"أغير ملابسي وأستريح."},{s:0,t:"Fühlst du dich besser jetzt?",ar:"هل تشعر بتحسن الآن؟"},{s:1,t:"Ja, ich fühle mich viel besser jetzt.",ar:"نعم، أشعر بتحسن كبير الآن."},{s:0,t:"Verabschiede dich von den anderen Spielern.",ar:"ودّع اللاعبين الآخرين."},{s:1,t:"Ich verabschiede mich von allen, bis morgen!",ar:"أودع الجميع، حتى الغد!"},{s:0,t:"Morgen treffen wir uns wieder, um zehn Uhr.",ar:"غدًا نلتقي مجددًا، في العاشرة."},{s:1,t:"Ich freue mich schon auf morgen.",ar:"أنا متحمس بالفعل للغد."},{s:0,t:"Denk an das Training, es beginnt um neun.",ar:"تذكر التدريب، يبدأ في التاسعة."},{s:1,t:"Ich denke daran, ich vergesse es nicht.",ar:"أتذكره، لن أنساه."},{s:0,t:"Pass auf dich auf, mein Freund.",ar:"اعتنِ بنفسك، يا صديقي."},{s:1,t:"Ich passe auf mich auf, danke dir.",ar:"سأعتني بنفسي، شكرًا لك."},{s:0,t:"Wir sehen uns morgen, viel Spaß heute!",ar:"نراك غدًا، استمتع اليوم!"},{s:1,t:"Danke! Ich freue mich schon sehr.",ar:"شكرًا! أنا متحمس جدًا بالفعل."}]}},{stage:11,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"خطط للمستقبل",grammar:{id:"de-praeteritum",title:"Präteritum",titleAr:"الماضي البسيط (Präteritum)",covers:1},conv:{id:"de-stage11-a2",speakers:["Lehrer (المعلم)","Koch (الطباخ)"],turns:[{s:0,t:"Guten Tag! Was machten Sie früher?",ar:"مرحبًا! ماذا كنت تفعل سابقًا؟"},{s:1,t:"Ich arbeitete in einem kleinen Restaurant.",ar:"كنت أعمل في مطعم صغير."},{s:0,t:"Wo war das Restaurant? In dieser Stadt?",ar:"أين كان المطعم؟ في هذه المدينة؟"},{s:1,t:"Nein, es war in einem kleinen Dorf.",ar:"لا، كان في قرية صغيرة."},{s:0,t:"Wie kamen Sie in die Stadt?",ar:"كيف جئت إلى المدينة؟"},{s:1,t:"Ich kam vor zehn Jahren mit meiner Familie.",ar:"جئت قبل عشر سنوات مع عائلتي."},{s:0,t:"Was machten Sie in den ersten Jahren?",ar:"ماذا فعلت في السنوات الأولى؟"},{s:1,t:"Ich lernte Deutsch und kochte zu Hause.",ar:"تعلمت الألمانية وطبخت في البيت."},{s:0,t:"Wer half Ihnen in dieser Zeit?",ar:"من ساعدك في ذلك الوقت؟"},{s:1,t:"Mein Bruder half mir, er arbeitete auch hier.",ar:"أخي ساعدني، كان يعمل هنا أيضًا."},{s:0,t:"Wann begannen Sie, richtig zu kochen?",ar:"متى بدأت الطبخ حقًا؟"},{s:1,t:"Ich begann vor fünf Jahren in einem Hotel.",ar:"بدأت قبل خمس سنوات في فندق."},{s:0,t:"Was kochten Sie in dem Hotel?",ar:"ماذا كنت تطبخ في الفندق؟"},{s:1,t:"Ich kochte Suppen, Fleisch und süße Sachen.",ar:"كنت أطبخ الحساء واللحم والحلويات."},{s:0,t:"Gaben die Gäste Ihnen gute Noten?",ar:"هل أعطاك الضيوف تقييمات جيدة؟"},{s:1,t:"Ja, sie gaben mir immer gute Noten.",ar:"نعم، كانوا يعطونني دائمًا تقييمات جيدة."},{s:0,t:"Fanden Sie die Arbeit schwer?",ar:"هل وجدت العمل صعبًا؟"},{s:1,t:"Ja, sie war schwer, aber ich lernte viel.",ar:"نعم، كان صعبًا، لكنني تعلمت الكثير."},{s:0,t:"Was machten Sie nach der Arbeit?",ar:"ماذا كنت تفعل بعد العمل؟"},{s:1,t:"Ich las Bücher über das Kochen.",ar:"كنت أقرأ كتبًا عن الطبخ."},{s:0,t:"Schrieben Sie auch eigene Rezepte?",ar:"هل كتبت وصفاتك الخاصة أيضًا؟"},{s:1,t:"Ja, ich schrieb viele Rezepte in ein Heft.",ar:"نعم، كتبت وصفات كثيرة في دفتر."},{s:0,t:"Tranken Sie Tee mit den anderen Köchen?",ar:"هل شربت الشاي مع الطهاة الآخرين؟"},{s:1,t:"Ja, wir tranken Tee und sprachen über Rezepte.",ar:"نعم، كنا نشرب الشاي ونتحدث عن الوصفات."},{s:0,t:"Aßen Sie auch in dem Hotel?",ar:"هل أكلت في الفندق أيضًا؟"},{s:1,t:"Ja, wir aßen zusammen nach der Arbeit.",ar:"نعم، كنا نأكل معًا بعد العمل."},{s:0,t:"Fuhren Sie oft in andere Städte?",ar:"هل سافرت كثيرًا إلى مدن أخرى؟"},{s:1,t:"Ja, ich fuhr nach Berlin und nach München.",ar:"نعم، سافرت إلى برلين وميونخ."},{s:0,t:"Blieben Sie lange in Berlin?",ar:"هل بقيت طويلًا في برلين؟"},{s:1,t:"Nein, ich blieb nur drei Tage dort.",ar:"لا، بقيت ثلاثة أيام فقط هناك."},{s:0,t:"Was dachten Sie über die Stadt?",ar:"ماذا فكرت في المدينة؟"},{s:1,t:"Ich dachte, sie war sehr schön und groß.",ar:"اعتقدت أنها جميلة وكبيرة جدًا."},{s:0,t:"Wussten Sie schon damals, dass Sie Koch werden?",ar:"هل عرفت منذ ذلك الحين أنك ستصبح طباخًا؟"},{s:1,t:"Ja, ich wusste es schon als Kind.",ar:"نعم، عرفت ذلك منذ الطفولة."},{s:0,t:"Brachten Sie Ihrer Familie Geschenke mit?",ar:"هل أحضرت هدايا لعائلتك؟"},{s:1,t:"Ja, ich brachte ihnen Bücher und Süßigkeiten.",ar:"نعم، أحضرت لهم كتبًا وحلويات."},{s:0,t:"Standen Sie jeden Tag früh auf?",ar:"هل كنت تستيقظ مبكرًا كل يوم؟"},{s:1,t:"Ja, ich stand jeden Tag um fünf auf.",ar:"نعم، كنت أستيقظ كل يوم في الخامسة."},{s:0,t:"Wurden Sie auch manchmal müde?",ar:"هل كنت تتعب أحيانًا أيضًا؟"},{s:1,t:"Ja, ich wurde oft müde, aber ich war glücklich.",ar:"نعم، كنت أتعب كثيرًا، لكنني كنت سعيدًا."},{s:0,t:"Das war ein gutes Leben, oder?",ar:"كانت حياة جيدة، أليس كذلك؟"},{s:1,t:"Ja, es war ein gutes Leben, wirklich.",ar:"نعم، كانت حياة جيدة، حقًا."},{s:0,t:"Und jetzt planen Sie ein eigenes Restaurant?",ar:"والآن تخطط لمطعمك الخاص؟"},{s:1,t:"Ja, ich plane es schon lange, es wird schön.",ar:"نعم، أخطط له منذ زمن طويل، سيكون جميلًا."}]}},{stage:12,topic:"services",topicAr:"الخدمات والطوارئ",topicEn:"Services & Emergencies",topicDe:"Dienstleistungen und Notfälle",emoji:"🏦",title:"في المدينة: طلبات وخدمات",grammar:{id:"de-praepositionen-kasus",title:"Präpositionen mit Kasus",titleAr:"حروف الجر والحالات",covers:1},conv:{id:"de-stage12-a2",speakers:["Kunde (الزبون)","Freund (الصديق)"],turns:[{s:0,t:"Guten Tag! Ich komme von dem Amt.",ar:"مرحبًا! أنا قادم من المكتب."},{s:1,t:"Was möchten Sie? Ich arbeite bei dem Amt.",ar:"ماذا تريد؟ أنا أعمل في المكتب."},{s:0,t:"Ich brauche Hilfe mit dem Formular.",ar:"أحتاج مساعدة مع الاستمارة."},{s:1,t:"Ich helfe Ihnen mit dem Formular, gern.",ar:"سأساعدك مع الاستمارة، بكل سرور."},{s:0,t:"Das Formular ist für meinen Sohn.",ar:"الاستمارة لابني."},{s:1,t:"Für Ihren Sohn? Er ist noch jung.",ar:"لابنك؟ إنه ما زال صغيرًا."},{s:0,t:"Ja, er geht zur Schule in der Stadt.",ar:"نعم، يذهب إلى المدرسة في المدينة."},{s:1,t:"Die Schule ist in der Stadt, bei dem Park.",ar:"المدرسة في المدينة، عند الحديقة."},{s:0,t:"Ich wohne bei dem Park, in einem alten Haus.",ar:"أسكن عند الحديقة، في بيت قديم."},{s:1,t:"Das Haus bei dem Park ist sehr schön.",ar:"البيت عند الحديقة جميل جدًا."},{s:0,t:"Ich komme aus dem Dorf, aus einer kleinen Stadt.",ar:"أنا قادم من القرية، من مدينة صغيرة."},{s:1,t:"Aus einer kleinen Stadt? Willkommen in unserer Stadt!",ar:"من مدينة صغيرة؟ أهلًا بك في مدينتنا!"},{s:0,t:"Ich fahre mit dem Bus zur Arbeit.",ar:"أذهب بالحافلة إلى العمل."},{s:1,t:"Mit dem Bus? Die Fahrt dauert lange?",ar:"بالحافلة؟ الرحلة تستغرق وقتًا طويلًا؟"},{s:0,t:"Nein, mit dem Bus dauert sie zwanzig Minuten.",ar:"لا، بالحافلة تستغرق عشرين دقيقة."},{s:1,t:"Nach der Arbeit gehe ich nach Hause.",ar:"بعد العمل أذهب إلى البيت."},{s:0,t:"Zu Hause koche ich für meine Familie.",ar:"في البيت أطبخ لعائلتي."},{s:1,t:"Für Ihre Familie? Das ist sehr nett.",ar:"لعائلتك؟ هذا لطف كبير."},{s:0,t:"Ja, ich koche gern für meine Kinder.",ar:"نعم، أحب الطبخ لأطفالي."},{s:1,t:"Von dem Markt kaufe ich frisches Brot.",ar:"من السوق أشتري خبزًا طازجًا."},{s:0,t:"Das Brot von dem Markt ist sehr gut.",ar:"خبز السوق جيد جدًا."},{s:1,t:"Ich gehe zu dem Markt jeden Morgen.",ar:"أذهب إلى السوق كل صباح."},{s:0,t:"Zu dem Markt? Das ist weit von hier.",ar:"إلى السوق؟ إنه بعيد من هنا."},{s:1,t:"Nein, er ist zu Fuß nur zehn Minuten entfernt.",ar:"لا، إنه على بعد عشر دقائق مشيًا فقط."},{s:0,t:"Ich warte auf den Bus an der Haltestelle.",ar:"أنتظر الحافلة في موقف الحافلات."},{s:1,t:"An der Haltestelle? Da ist es kalt im Winter.",ar:"في الموقف؟ الجو بارد هناك في الشتاء."},{s:0,t:"Ja, aber ich warte mit meinem Freund.",ar:"نعم، لكنني أنتظر مع صديقي."},{s:1,t:"Mit Ihrem Freund? Das ist gut.",ar:"مع صديقك؟ هذا جيد."},{s:0,t:"Nach dem Winter kommt der Frühling.",ar:"بعد الشتاء يأتي الربيع."},{s:1,t:"Im Frühling gehen wir in den Park.",ar:"في الربيع نذهب إلى الحديقة."},{s:0,t:"In dem Park spielen die Kinder gern.",ar:"في الحديقة يحب الأطفال اللعب."},{s:1,t:"Die Kinder spielen gern in dem Park.",ar:"الأطفال يحبون اللعب في الحديقة."},{s:0,t:"Ich sitze auf einer Bank, unter einem Baum.",ar:"أجلس على مقعد، تحت شجرة."},{s:1,t:"Auf einer Bank? Da ist es schön und ruhig.",ar:"على مقعد؟ المكان جميل وهادئ هناك."},{s:0,t:"Ja, ich lese dort ein Buch.",ar:"نعم، أقرأ هناك كتابًا."},{s:1,t:"Ein Buch von einem guten Autor?",ar:"كتاب لمؤلف جيد؟"},{s:0,t:"Ja, von einem Autor aus unserer Stadt.",ar:"نعم، لمؤلف من مدينتنا."},{s:1,t:"Ich kaufe das Buch in dem Laden dort.",ar:"أشتري الكتاب من المتجر هناك."},{s:0,t:"In dem Laden? Er ist teuer, oder?",ar:"من المتجر؟ إنه غالٍ، أليس كذلك؟"},{s:1,t:"Nein, er ist billig und die Bücher sind gut.",ar:"لا، إنه رخيص والكتب جيدة."},{s:0,t:"Vielen Dank für Ihre Hilfe heute!",ar:"شكرًا جزيلًا على مساعدتك اليوم!"},{s:1,t:"Gern geschehen! Kommen Sie bald wieder.",ar:"على الرحب! تعال قريبًا مرة أخرى."},{s:0,t:"Ich komme gern wieder, in der nächsten Woche.",ar:"سأعود بكل سرور، في الأسبوع المقبل."},{s:1,t:"Bis dann! Einen schönen Tag noch!",ar:"حتى ذلك الحين! أتمنى لك يومًا سعيدًا!"}]}},{stage:13,topic:"culture",topicAr:"الثقافة والقصص اليومية",topicEn:"Culture & Daily Stories",topicDe:"Kultur und Alltagsgeschichten",emoji:"🎭",title:"حكايات الجد في رمضان",grammar:{id:"de-relativsaetze",title:"Relativsätze",titleAr:"الجمل الموصولة",covers:2},conv:{id:"de-stage13-a2",speakers:["Großvater (الجد)","Enkel (الحفيد)"],turns:[{s:0,t:"Ich erinnere mich gut an die alten Tage, mein lieber Enkel.",ar:"أتذكر الأيام القديمة جيدًا، يا حفيدي العزيز."},{s:1,t:"Großvater, erzähl mir bitte eine Geschichte aus deiner Kindheit.",ar:"جدي، حدّثني قصة من طفولتك، من فضلك."},{s:0,t:"Als ich jung war, feierten wir Ramadan ganz anders.",ar:"عندما كنت صغيرًا، كنا نحتفل برمضان بشكل مختلف تمامًا."},{s:1,t:"Was hat deine Familie am Abend gemacht?",ar:"ماذا كانت عائلتك تفعل في المساء؟"},{s:0,t:"Die Mutter, die sehr gut kochen konnte, machte das Essen für alle.",ar:"الأم، التي كانت تجيد الطبخ جيدًا، كانت تعد الطعام للجميع."},{s:1,t:"Hat dein Vater euch Geschichten nach dem Essen erzählt?",ar:"هل كان أبوك يروي لكم القصص بعد العشاء؟"},{s:0,t:"Ja, er erzählte uns die Geschichte, die ich nie vergessen habe.",ar:"نعم، كان يروي لنا القصة التي لم أنسها أبدًا."},{s:1,t:"Das klingt schön. Hast du seinen Geschichten geglaubt?",ar:"هذا يبدو جميلًا. هل كنت تصدق قصصه؟"},{s:0,t:"Natürlich! Die Großmutter, die viele Geschichten kannte, sagte immer die Wahrheit.",ar:"بالطبع! الجدة، التي كانت تعرف قصصًا كثيرة، كانت تقول الحقيقة دائمًا."},{s:1,t:"Was war deine Lieblingsgeschichte, Großvater?",ar:"ما كانت قصتك المفضلة، يا جدي؟"},{s:0,t:"Ich liebte die Geschichte von dem Händler, der seinem Nachbarn half.",ar:"كنت أحب قصة التاجر الذي ساعد جاره."},{s:1,t:"Was hat der Händler zu seinem Nachbarn gesagt?",ar:"ماذا قال التاجر لجاره؟"},{s:0,t:"Er sagte, dass er sein Brot jeden Tag mit ihm teilen würde.",ar:"قال إنه سيشاركه خبزه كل يوم."},{s:1,t:"Hat der Nachbar seine Hilfe angenommen?",ar:"هل قبل الجار مساعدته؟"},{s:0,t:"Zuerst sagte er, dass er nichts von anderen Menschen brauchte.",ar:"في البداية قال إنه لا يحتاج شيئًا من الآخرين."},{s:1,t:"Aber später hat er seine Meinung geändert, oder?",ar:"لكن لاحقًا غيّر رأيه، أليس كذلك؟"},{s:0,t:"Ja, er sagte dem Händler, dass seine Kinder hungrig waren.",ar:"نعم، أخبر التاجر أن أطفاله كانوا جائعين."},{s:1,t:"Sind sie danach gute Freunde geworden?",ar:"هل أصبحا صديقين جيدين بعد ذلك؟"},{s:0,t:"Sie wurden wie Brüder. Mein Vater sagte, dass die Güte nie stirbt.",ar:"أصبحا مثل الأخوين. كان أبي يقول إن الطيبة لا تموت أبدًا."},{s:1,t:"Ich mag diese Geschichte. Erzähl mir bitte noch eine.",ar:"أعجبتني هذه القصة. حدّثني قصة أخرى، من فضلك."},{s:0,t:"Mein Lehrer sagte, dass das Fest der beste Tag des Jahres war.",ar:"قال معلمي إن العيد كان أفضل يوم في السنة."},{s:1,t:"Was hast du am Festtag getragen?",ar:"ماذا كنت تلبس في يوم العيد؟"},{s:0,t:"Die Kleider, die meine Mutter mir gekauft hatte, waren ganz neu.",ar:"الملابس التي اشترتها أمي لي كانت جديدة تمامًا."},{s:1,t:"Hast du deine Verwandten nach dem Gebet besucht?",ar:"هل كنت تزور أقاربك بعد الصلاة؟"},{s:0,t:"Ja, wir haben sie alle besucht. Mein Onkel sagte, dass wir immer willkommen waren.",ar:"نعم، كنا نزورهم جميعًا. قال عمي إننا مرحب بنا دائمًا."},{s:1,t:"Haben sie dir Süßigkeiten und Geld gegeben?",ar:"هل كانوا يعطونك الحلوى والنقود؟"},{s:0,t:"Sie gaben uns Süßigkeiten und sagten, dass wir gute Kinder waren.",ar:"كانوا يعطوننا الحلوى ويقولون إننا أطفال طيبون."},{s:1,t:"Ich wünschte, ich könnte diese Tage sehen, Großvater.",ar:"أتمنى لو أستطيع رؤية تلك الأيام، يا جدي."},{s:0,t:"Das kannst du. Ich sagte deinem Vater, dass unsere Traditionen nie verschwinden dürfen.",ar:"تستطيع. قلت لأبيك إن تقاليدنا يجب ألا تختفي أبدًا."},{s:1,t:"Was hat dein Vater über die alten Lieder gesagt?",ar:"ماذا قال أبوك عن الأغاني القديمة؟"},{s:0,t:"Er sagte, dass die alten Lieder besser waren als die neuen.",ar:"قال إن الأغاني القديمة كانت أفضل من الجديدة."},{s:1,t:"Kannst du eines von ihnen für mich singen?",ar:"هل يمكنك أن تغني لي واحدة منها؟"},{s:0,t:"Ich werde es für dich singen, aber meine Stimme ist nicht mehr so gut wie früher.",ar:"سأغنيها لك، لكن صوتي لم يعد جيدًا كما كان من قبل."},{s:1,t:"Das ist egal. Ich möchte es nur hören.",ar:"لا يهم ذلك. أريد فقط أن أسمعها."},{s:0,t:"Hör gut zu. Meine Mutter sagte mir, dass dieses Lied sehr alt war.",ar:"استمع جيدًا. قالت أمي لي إن هذه الأغنية قديمة جدًا."},{s:1,t:"Es ist ein schönes Lied. Wer hat es geschrieben?",ar:"إنها أغنية جميلة. من كتبها؟"},{s:0,t:"Niemand weiß es. Die Leute sagten, dass es aus den Bergen kam.",ar:"لا أحد يعرف. كان الناس يقولون إنها جاءت من الجبال."},{s:1,t:"Ich werde meinen Freunden in der Schule von diesem Lied erzählen.",ar:"سأخبر أصدقائي في المدرسة عن هذه الأغنية."},{s:0,t:"Gut. Sag ihnen, dass unsere Kultur reich und schön ist.",ar:"جيد. أخبرهم أن ثقافتنا غنية وجميلة."},{s:1,t:"Das werde ich. Danke für die Geschichten, Großvater.",ar:"سأفعل. شكرًا على القصص، يا جدي."},{s:0,t:"Gern geschehen. Denk daran, mein Lieber, Geschichten halten unsere Familie zusammen.",ar:"على الرحب والسعة. تذكر يا عزيزي، القصص تبقي عائلتنا متماسكة."},{s:1,t:"Ich werde daran denken. Können wir morgen wieder sprechen?",ar:"سأتذكر. هل يمكننا أن نتحدث مرة أخرى غدًا؟"},{s:0,t:"Natürlich. Ich werde dir die Geschichte von dem mutigen Fischer erzählen.",ar:"بالطبع. سأروي لك قصة الصياد الشجاع."},{s:1,t:"Ich kann es kaum erwarten! Gute Nacht, Großvater.",ar:"لا أستطيع الانتظار! تصبح على خير، يا جدي."}]}},{stage:14,topic:"technology",topicAr:"التكنولوجيا والإنترنت",topicEn:"Technology & Internet",topicDe:"Technologie und Internet",emoji:"💻",title:"إصلاح الهاتف في المحل",grammar:{id:"de-passiv",title:"Passiv",titleAr:"المبني للمجهول",covers:2},conv:{id:"de-stage14-a2",speakers:["Techniker (فني الصيانة)","Kunde (الزبون)"],turns:[{s:0,t:"Guten Morgen. Wie kann ich Ihnen heute helfen?",ar:"صباح الخير. كيف يمكنني مساعدتك اليوم؟"},{s:1,t:"Mein Handy ist gestern gefallen, und der Bildschirm ist kaputt.",ar:"سقط هاتفي أمس، والشاشة مكسورة."},{s:0,t:"Das tut mir leid. Wann wurde es gekauft?",ar:"يؤسفني ذلك. متى تم شراؤه؟"},{s:1,t:"Es wurde vor zwei Jahren gekauft, aber es hat sehr gut funktioniert.",ar:"تم شراؤه قبل سنتين، لكنه كان يعمل جيدًا."},{s:0,t:"Lassen Sie mich schauen. Der Bildschirm wurde stark beschädigt.",ar:"دعني أنظر إليه. الشاشة تضررت بشدة."},{s:1,t:"Kann es repariert werden, oder muss es ersetzt werden?",ar:"هل يمكن إصلاحه، أم يجب استبداله؟"},{s:0,t:"Es kann repariert werden. Ein neuer Bildschirm wird heute eingebaut.",ar:"يمكن إصلاحه. سيتم تركيب شاشة جديدة اليوم."},{s:1,t:"Wie viel wird es kosten?",ar:"كم سيكلف ذلك؟"},{s:0,t:"Die Reparatur wurde heute Morgen auf fünfzig Dollar geschätzt.",ar:"تم تقدير الإصلاح بخمسين دولارًا هذا الصباح."},{s:1,t:"Das ist ein fairer Preis. Wie lange wird es dauern?",ar:"هذا سعر عادل. كم سيستغرق من الوقت؟"},{s:0,t:"Es wird in zwei Stunden fertig sein. Sie können hier warten.",ar:"سيكون جاهزًا خلال ساعتين. يمكنك الانتظار هنا."},{s:1,t:"Danke. Wurden meine Daten auf dem Handy gespeichert?",ar:"شكرًا. هل تم حفظ بياناتي على الهاتف؟"},{s:0,t:"Ihre Fotos wurden letzte Woche in der Cloud gespeichert.",ar:"تم حفظ صورك في السحابة الأسبوع الماضي."},{s:1,t:"Gut. Ich habe mir Sorgen um meine Fotos und Nachrichten gemacht.",ar:"جيد. كنت قلقًا بشأن صوري ورسائلي."},{s:0,t:"Keine Sorge. Alles wurde automatisch gesichert.",ar:"لا تقلق. تم نسخ كل شيء احتياطيًا تلقائيًا."},{s:1,t:"Mein Handy wurde jeden Tag für die Arbeit benutzt. Ich brauche es bald zurück.",ar:"كان هاتفي يُستخدم للعمل كل يوم. أحتاجه قريبًا."},{s:0,t:"Ich verstehe. Das Handy wird getestet, bevor Sie es mitnehmen.",ar:"أفهم. سيتم اختبار الهاتف قبل أن تأخذه."},{s:1,t:"Ist der Akku auch beschädigt?",ar:"هل البطارية متضررة أيضًا؟"},{s:0,t:"Nein, der Akku wurde geprüft und ist in Ordnung.",ar:"لا، تم فحص البطارية وهي بخير."},{s:1,t:"Das sind gute Nachrichten. Sollte ich eine Schutzhülle kaufen?",ar:"هذه أخبار جيدة. هل يجب أن أشتري غطاءً واقيًا؟"},{s:0,t:"Ja, eine starke Hülle sollte benutzt werden, um das Handy zu schützen.",ar:"نعم، يجب استخدام غطاء قوي لحماية الهاتف."},{s:1,t:"Ich werde eine kaufen. Welche Hülle wird empfohlen?",ar:"سأشتري واحدة. أي غطاء يُنصح به؟"},{s:0,t:"Diese schwarze Hülle wurde für Ihr Handymodell gemacht.",ar:"هذا الغطاء الأسود صُنع خصيصًا لطراز هاتفك."},{s:1,t:"Wie viel kostet sie?",ar:"كم سعرها؟"},{s:0,t:"Sie wird in unserem Geschäft für zehn Dollar verkauft.",ar:"تُباع بعشرة دولارات في محلنا."},{s:1,t:"Ich nehme sie. Kann auch ein Displayschutz angebracht werden?",ar:"سآخذها. هل يمكن تركيب واقي شاشة أيضًا؟"},{s:0,t:"Natürlich. Er wird nach der Reparatur angebracht.",ar:"بالطبع. سيتم تركيبه بعد الإصلاح."},{s:1,t:"Mein altes Handy wurde letztes Jahr gestohlen. Das will ich nicht wieder erleben.",ar:"سُرق هاتفي القديم العام الماضي. لا أريد أن يحدث ذلك مرة أخرى."},{s:0,t:"Das tut mir leid. Ein Passwort sollte auf jedem Handy eingestellt werden.",ar:"يؤسفني ذلك. يجب تعيين كلمة مرور على كل هاتف."},{s:1,t:"Sie haben recht. Mein Passwort wird heute Abend geändert.",ar:"أنت محق. سيتم تغيير كلمة مروري الليلة."},{s:0,t:"Auch Ihr Standort sollte eingeschaltet werden, wenn Sie reisen.",ar:"أيضًا، يجب تشغيل الموقع عند السفر."},{s:1,t:"Danke für den Rat. Ich werde vorsichtiger sein.",ar:"شكرًا على النصيحة. سأكون أكثر حذرًا."},{s:0,t:"Ihr Handy ist jetzt fertig. Es wurde repariert und getestet.",ar:"هاتفك جاهز الآن. تم إصلاحه واختباره."},{s:1,t:"Das war schnell! Lassen Sie mich es prüfen.",ar:"كان ذلك سريعًا! دعني أتحقق منه."},{s:0,t:"Der Bildschirm sieht neu aus, und der Touchscreen wurde auch repariert.",ar:"الشاشة تبدو جديدة، وشاشة اللمس تم إصلاحها أيضًا."},{s:1,t:"Es funktioniert perfekt. Vielen Dank.",ar:"إنه يعمل بشكل مثالي. شكرًا جزيلًا."},{s:0,t:"Gern geschehen. Die Reparatur wurde für drei Monate garantiert.",ar:"على الرحب والسعة. الإصلاح مضمون لمدة ثلاثة أشهر."},{s:1,t:"Wenn ein Problem gefunden wird, komme ich zurück.",ar:"إذا وُجدت مشكلة، سأعود."},{s:0,t:"Bitte. Unser Geschäft wird jeden Tag geöffnet, außer am Freitag.",ar:"تفضل. محلنا مفتوح كل يوم ما عدا الجمعة."},{s:1,t:"Ich werde meinen Freunden von Ihrem guten Service erzählen.",ar:"سأخبر أصدقائي عن خدمتك الجيدة."},{s:0,t:"Danke. Eine gute Bewertung wäre sehr nett.",ar:"شكرًا. سيكون التقييم الجيد لطيفًا جدًا."},{s:1,t:"Ich werde heute Abend eine schreiben. Auf Wiedersehen, und danke noch einmal.",ar:"سأكتب واحدًا الليلة. وداعًا، وشكرًا مرة أخرى."},{s:0,t:"Auf Wiedersehen. Passen Sie diesmal gut auf Ihr Handy auf!",ar:"وداعًا. اعتنِ بهاتفك هذه المرة!"},{s:1,t:"Das werde ich. Einen schönen Tag noch!",ar:"سأفعل. أتمنى لك يومًا سعيدًا!"}]}},{stage:15,topic:"environment",topicAr:"البيئة والطبيعة",topicEn:"Environment & Nature",topicDe:"Umwelt und Natur",emoji:"🌳",title:"تنظيف الحديقة يوم السبت",grammar:{id:"de-nebensaetze",title:"Nebensätze",titleAr:"الجمل التابعة",covers:2},conv:{id:"de-stage15-a2",speakers:["Freiwilliger (متطوع)","Nachbar (جار)"],turns:[{s:0,t:"Guten Morgen, mein Nachbar. Wirst du am Samstag mitmachen?",ar:"صباح الخير، يا جاري. هل ستشارك يوم السبت؟"},{s:1,t:"Was plant ihr am Samstag zu machen?",ar:"ماذا تخططون لفعله يوم السبت؟"},{s:0,t:"Wir werden den Park putzen, weil er sehr schmutzig ist.",ar:"سننظف الحديقة لأنها متسخة جدًا."},{s:1,t:"Das ist eine tolle Idee. Wann werden wir anfangen?",ar:"هذه فكرة رائعة. متى سنبدأ؟"},{s:0,t:"Wir fangen um neun Uhr morgens an. Wenn du früh kommst, bekommst du Handschuhe.",ar:"سنبدأ في التاسعة صباحًا. إذا جئت مبكرًا، ستحصل على قفازات."},{s:1,t:"Ich komme um halb neun. Was soll ich mitbringen?",ar:"سآتي في الثامنة والنصف. ماذا يجب أن أحضر؟"},{s:0,t:"Bring eine Wasserflasche mit, weil es heiß werden kann.",ar:"أحضر زجاجة ماء لأن الجو قد يصبح حارًا."},{s:1,t:"Ich bringe Wasser und Sandwiches für alle mit.",ar:"سأحضر الماء والسندويشات للجميع."},{s:0,t:"Danke. Wenn mehr Leute mitmachen, wird der Park wunderschön aussehen.",ar:"شكرًا. إذا شارك المزيد من الناس، ستبدو الحديقة رائعة."},{s:1,t:"Ich werde auch meine Kinder bitten, zu helfen. Sie lieben den Park.",ar:"سأطلب من أطفالي المساعدة أيضًا. إنهم يحبون الحديقة."},{s:0,t:"Das ist wunderbar. Wenn die Kinder helfen, lernen sie, die Natur zu schützen.",ar:"هذا رائع. إذا ساعد الأطفال، سيتعلمون حماية الطبيعة."},{s:1,t:"Wir müssen auch Bäume pflanzen. Der Park hat sehr wenige Bäume.",ar:"نحتاج أيضًا إلى زراعة الأشجار. الحديقة فيها أشجار قليلة جدًا."},{s:0,t:"Ja, wenn wir zehn Bäume pflanzen, wird die Luft sauberer.",ar:"نعم، إذا زرعنا عشر أشجار، سيكون الهواء أنظف."},{s:1,t:"Woher bekommen wir die Bäume?",ar:"من أين سنحصل على الأشجار؟"},{s:0,t:"Die Stadt wird sie uns geben. Wenn wir heute fragen, kommen sie am Freitag an.",ar:"ستعطينا إياها المدينة. إذا سألنا اليوم، ستصل يوم الجمعة."},{s:1,t:"Ich werde heute Nachmittag das Stadtbüro anrufen.",ar:"سأتصل بمكتب المدينة بعد ظهر اليوم."},{s:0,t:"Gut. Wenn sie zustimmen, pflanzen wir die Bäume auch am Samstag.",ar:"جيد. إذا وافقوا، سنزرع الأشجار يوم السبت أيضًا."},{s:1,t:"Was ist mit dem Müll im Fluss? Er sieht schrecklich aus.",ar:"ماذا عن القمامة في النهر؟ إنها تبدو فظيعة."},{s:0,t:"Wenn wir den Fluss nicht putzen, werden die Fische sterben.",ar:"إذا لم ننظف النهر، ستموت الأسماك."},{s:1,t:"Du hast recht. Wir müssen Wasser sparen und es sauber halten.",ar:"أنت محق. يجب أن نوفر الماء ونبقيه نظيفًا."},{s:0,t:"Wenn alle Wasser sparen, gibt es genug für uns alle.",ar:"إذا وفر الجميع الماء، سيكون هناك ما يكفي لنا جميعًا."},{s:1,t:"Ich werde den Wasserhahn in meiner Küche reparieren. Er verschwendet viel Wasser.",ar:"سأصلح الصنبور في مطبخي. إنه يهدر الكثير من الماء."},{s:0,t:"Das ist ein guter Anfang. Wenn du ihn reparierst, sparst du auch Geld.",ar:"هذه بداية جيدة. إذا أصلحته، ستوفر المال أيضًا."},{s:1,t:"Ich werde meinen Kindern auch beibringen, den Wasserhahn zuzudrehen.",ar:"سأعلم أطفالي أيضًا إغلاق الصنبور."},{s:0,t:"Perfekt. Wenn Kinder früh lernen, schützen sie die Natur für immer.",ar:"ممتاز. إذا تعلم الأطفال مبكرًا، سيحمون الطبيعة للأبد."},{s:1,t:"Was machen wir mit dem Müll, den wir sammeln?",ar:"ماذا سنفعل بالقمامة التي نجمعها؟"},{s:0,t:"Wir stecken ihn in große Säcke. Wenn wir ihn trennen, kann er recycelt werden.",ar:"سنضعها في أكياس كبيرة. إذا فصلناها، يمكن إعادة تدويرها."},{s:1,t:"Ich wusste nicht, dass Plastik recycelt werden kann.",ar:"لم أكن أعرف أن البلاستيك يمكن إعادة تدويره."},{s:0,t:"Ja, wenn wir Plastik recyceln, werden weniger Bäume gefällt.",ar:"نعم، إذا أعدنا تدوير البلاستيك، سيتم قطع أشجار أقل."},{s:1,t:"Ich werde ab heute zu Hause recyceln.",ar:"سأبدأ إعادة التدوير في المنزل من اليوم."},{s:0,t:"Ausgezeichnet. Wenn jede Familie recycelt, wird unsere Stadt viel sauberer.",ar:"ممتاز. إذا أعادت كل عائلة التدوير، ستكون مدينتنا أنظف بكثير."},{s:1,t:"Wie viele Leute werden am Samstag kommen?",ar:"كم عدد الأشخاص الذين سيأتون يوم السبت؟"},{s:0,t:"Etwa dreißig Leute werden kommen. Wenn das Wetter gut ist, kommen noch mehr.",ar:"سيأتي حوالي ثلاثين شخصًا. إذا كان الطقس جيدًا، سيأتي المزيد."},{s:1,t:"Ich hoffe, dass es nicht regnet. Wenn es regnet, putzen wir am Sonntag.",ar:"أتمنى ألا تمطر. إذا أمطرت، سننظف يوم الأحد."},{s:0,t:"Das ist der Plan. Wenn es regnet, schicke ich allen eine Nachricht.",ar:"هذه هي الخطة. إذا أمطرت، سأرسل رسالة للجميع."},{s:1,t:"Ich werde heute Abend die Wettervorhersage prüfen.",ar:"سأتحقق من توقعات الطقس الليلة."},{s:0,t:"Gut. Wenn die Sonne scheint, haben wir einen schönen Tag.",ar:"جيد. إذا أشرقت الشمس، سيكون لدينا يوم جميل."},{s:1,t:"Ich freue mich. Der Park wird wieder schön sein.",ar:"أنا متحمس. ستعود الحديقة جميلة مرة أخرى."},{s:0,t:"Ja, und wenn wir uns um ihn kümmern, bleibt er schön.",ar:"نعم، وإذا اعتنينا بها، ستبقى جميلة."},{s:1,t:"Ich verspreche, jeden Monat zu helfen.",ar:"أعدك بأن أساعد كل شهر."},{s:0,t:"Danke, mein Nachbar. Zusammen können wir unsere Stadt verändern.",ar:"شكرًا، يا جاري. معًا يمكننا تغيير مدينتنا."},{s:1,t:"Bis Samstag um halb neun!",ar:"أراك يوم السبت في الثامنة والنصف!"},{s:0,t:"Bis dann. Vergiss deine Wasserflasche nicht!",ar:"أراك حينها. لا تنسَ زجاجة الماء!"},{s:1,t:"Ich werde sie nicht vergessen. Auf Wiedersehen!",ar:"لن أنساها. وداعًا!"}]}},{stage:16,topic:"media",topicAr:"وسائل الإعلام والأخبار",topicEn:"Media & News",topicDe:"Medien und Nachrichten",emoji:"📺",title:"أخبار المساء",grammar:{id:"de-perfekt",title:"Perfekt",titleAr:"الماضي التام",covers:2},conv:{id:"de-stage16-a2",speakers:["Mein Freund (صديقي)","Meine Nachbarin (جارتي)"],turns:[{s:0,t:"Hast du heute die Nachrichten gesehen?",ar:"هل شاهدت الأخبار اليوم؟"},{s:1,t:"Nein, ich habe sie noch nicht gesehen. Ist etwas Wichtiges passiert?",ar:"لا، لم أشاهدها بعد. هل حدث شيء مهم؟"},{s:0,t:"Ja, die Stadt hat eine neue Bibliothek im Zentrum eröffnet.",ar:"نعم، افتتحت المدينة مكتبة جديدة في المركز."},{s:1,t:"Wirklich? Ich habe jahrelang auf eine Bibliothek gewartet!",ar:"حقًا؟ لقد انتظرت مكتبة لسنوات!"},{s:0,t:"Ich habe sie schon besucht. Sie ist schön und sehr groß.",ar:"لقد زرتها بالفعل. إنها جميلة وكبيرة جدًا."},{s:1,t:"Welche Bücher hast du dort gesehen?",ar:"ما الكتب التي رأيتها هناك؟"},{s:0,t:"Ich habe viele Bücher auf Englisch und Deutsch gesehen.",ar:"لقد رأيت الكثير من الكتب بالإنجليزية والألمانية."},{s:1,t:"Das ist wunderbar. Hast du ein Buch ausgeliehen?",ar:"هذا رائع. هل استعرت كتابًا؟"},{s:0,t:"Ja, ich habe ein Buch über die Geschichte unserer Stadt ausgeliehen.",ar:"نعم، لقد استعرت كتابًا عن تاريخ مدينتنا."},{s:1,t:"Ich habe noch nie ein Geschichtsbuch gelesen. Ist es interessant?",ar:"لم أقرأ كتاب تاريخ أبدًا. هل هو ممتع؟"},{s:0,t:"Es ist sehr interessant. Ich habe schon fünfzig Seiten gelesen.",ar:"إنه ممتع جدًا. لقد قرأت خمسين صفحة بالفعل."},{s:1,t:"Ich habe gerade einen Roman beendet. Er war über einen mutigen Seemann.",ar:"لقد أنهيت للتو رواية. كانت عن بحار شجاع."},{s:0,t:"Hast du den Film über diesen Seemann schon einmal gesehen?",ar:"هل شاهدت يومًا الفيلم عن ذلك البحار؟"},{s:1,t:"Nein, ich habe ihn nicht gesehen. Ist er gut?",ar:"لا، لم أشاهده. هل هو جيد؟"},{s:0,t:"Er ist ausgezeichnet. Ich habe ihn dreimal gesehen.",ar:"إنه ممتاز. لقد شاهدته ثلاث مرات."},{s:1,t:"Dreimal! Du hast ihn wirklich geliebt.",ar:"ثلاث مرات! لقد أحببته حقًا."},{s:0,t:"Ja, das habe ich. Hast du die neue Dokumentation über das Meer gesehen?",ar:"نعم، أحببته. هل شاهدت الفيلم الوثائقي الجديد عن البحر؟"},{s:1,t:"Ich habe von ihr gehört, aber ich habe sie noch nicht gesehen.",ar:"لقد سمعت عنه، لكنني لم أشاهده بعد."},{s:0,t:"Sie wurde gestern Abend im Fernsehen gezeigt. Die Bilder waren fantastisch.",ar:"عُرض على التلفاز الليلة الماضية. كانت الصور مذهلة."},{s:1,t:"Ich habe sie verpasst. Wurde sie wiederholt?",ar:"لقد فاتني. هل تمت إعادته؟"},{s:0,t:"Sie wird am Sonntag wiederholt. Ich habe schon meinen Wecker gestellt.",ar:"ستتم إعادته يوم الأحد. لقد ضبطت المنبه بالفعل."},{s:1,t:"Danke, dass du es mir gesagt hast. Ich habe ihn schon lange sehen wollen.",ar:"شكرًا لإخباري. لقد أردت رؤيته منذ وقت طويل."},{s:0,t:"Hast du heute die Zeitung gelesen?",ar:"هل قرأت الصحيفة اليوم؟"},{s:1,t:"Ja, ich habe sie gelesen. Das Wetter hat sich diese Woche sehr verändert.",ar:"نعم، قرأتها. لقد تغير الطقس كثيرًا هذا الأسبوع."},{s:0,t:"Das habe ich auch bemerkt. Es hat drei Tage lang geregnet.",ar:"لقد لاحظت ذلك أيضًا. لقد أمطرت لمدة ثلاثة أيام."},{s:1,t:"Die Bauern haben sich über den Regen gefreut.",ar:"لقد كان المزارعون سعداء بالمطر."},{s:0,t:"Ja, sie haben Regen für ihre Felder gebraucht.",ar:"نعم، لقد احتاجوا المطر لحقولهم."},{s:1,t:"Hast du morgens schon einmal Radio gehört?",ar:"هل استمعت يومًا إلى الراديو في الصباح؟"},{s:0,t:"Ja, ich habe seit zwei Jahren jeden Morgen Radio gehört.",ar:"نعم، لقد استمعت إليه كل صباح لمدة سنتين."},{s:1,t:"Welches Programm hat dir am besten gefallen?",ar:"ما البرنامج الذي أعجبك أكثر؟"},{s:0,t:"Das Programm über Wissenschaft und Weltraum hat mir am besten gefallen.",ar:"لقد أعجبني البرنامج عن العلم والفضاء أكثر من غيره."},{s:1,t:"Ich habe dieses Programm gehört. Der Moderator hat alles sehr klar erklärt.",ar:"لقد سمعت ذلك البرنامج. لقد شرح المقدّم كل شيء بوضوح شديد."},{s:0,t:"Er hat zehn Jahre lang beim Radio gearbeitet.",ar:"لقد عمل في الراديو لمدة عشر سنوات."},{s:1,t:"Das ist eine lange Zeit. Hat er ein Buch geschrieben?",ar:"هذه مدة طويلة. هل كتب كتابًا؟"},{s:0,t:"Ja, er hat zwei Bücher über die Sterne geschrieben.",ar:"نعم، لقد كتب كتابين عن النجوم."},{s:1,t:"Ich habe eines von ihnen gekauft. Es liegt jetzt auf meinem Tisch.",ar:"لقد اشتريت واحدًا منهما. إنه على طاولتي الآن."},{s:0,t:"Hast du angefangen, es zu lesen?",ar:"هل بدأت بقراءته؟"},{s:1,t:"Ja, ich habe es angefangen, und ich habe viele neue Dinge gelernt.",ar:"نعم، لقد بدأته، وتعلمت الكثير من الأشياء الجديدة."},{s:0,t:"Das ist toll. Die Nachrichten sind mit guten Büchern interessanter geworden.",ar:"هذا رائع. أصبحت الأخبار أكثر إثارة مع الكتب الجيدة."},{s:1,t:"Ich stimme dir zu. Wir haben heute über viele gute Dinge gesprochen.",ar:"أوافقك. لقد تحدثنا عن أشياء جيدة كثيرة اليوم."},{s:0,t:"Ja, das haben wir. Lass uns morgen Abend wieder treffen.",ar:"نعم، تحدثنا. لنتقابل مرة أخرى غدًا مساءً."},{s:1,t:"Ich habe unser Gespräch genossen. Bis morgen!",ar:"لقد استمتعت بحديثنا. أراك غدًا!"},{s:0,t:"Ich auch. Einen schönen Abend noch, meine Nachbarin!",ar:"وأنا أيضًا. أتمنى لك أمسية سعيدة، يا جارتي!"},{s:1,t:"Danke. Auf Wiedersehen!",ar:"شكرًا. وداعًا!"}]}},{stage:17,topic:"education",topicAr:"التعليم والدراسة",topicEn:"Education & Study",topicDe:"Bildung und Studium",emoji:"🎓",title:"الاستعداد للامتحان",grammar:{id:"de-modal-past",title:"Modalverben in der Vergangenheit",titleAr:"الأفعال الناقصة في الماضي",covers:2},conv:{id:"de-stage17-a2",speakers:["Lehrer (المعلم)","Schüler (الطالب)"],turns:[{s:0,t:"Guten Morgen. Was wolltest du dieses Jahr lernen?",ar:"صباح الخير. ماذا أردت أن تتعلم هذا العام؟"},{s:1,t:"Ich wollte Englisch und Deutsch lernen. Ich musste sehr hart arbeiten.",ar:"أردت تعلم الإنجليزية والألمانية. وكان عليّ أن أعمل بجد شديد."},{s:0,t:"Das ist ein guter Plan. Musstest du am Ende des Jahres eine Prüfung machen?",ar:"هذه خطة جيدة. هل كان عليك خوض امتحان في نهاية العام؟"},{s:1,t:"Ja, ich musste die A2-Prüfung im Juni machen. Ich sollte mich jeden Tag vorbereiten.",ar:"نعم، كان عليّ خوض امتحان A2 في يونيو. وكان يجب أن أستعد كل يوم."},{s:0,t:"Ausgezeichnet. Was wolltest du zuerst machen?",ar:"ممتاز. ماذا أردت أن تفعل أولًا؟"},{s:1,t:"Ich wollte jeden Tag eine Geschichte lesen und fünfundzwanzig Wörter lernen.",ar:"أردت قراءة قصة واحدة كل يوم وتعلم خمس وعشرين كلمة."},{s:0,t:"Das konnte dir sehr helfen. Konntest du auch das Sprechen üben?",ar:"كان ذلك سيساعدك كثيرًا. هل استطعت التدرب على التحدث أيضًا؟"},{s:1,t:"Ja, ich konnte jeden Abend mit meinem Freund sprechen. Wir mussten auf Englisch sprechen.",ar:"نعم، استطعت التحدث مع صديقي كل مساء. كان علينا التحدث بالإنجليزية."},{s:0,t:"Sehr gut. Wolltest du auch Filme auf Englisch sehen?",ar:"جيد جدًا. هل أردت مشاهدة أفلام بالإنجليزية أيضًا؟"},{s:1,t:"Ja, ich wollte jede Woche einen Film mit Untertiteln sehen.",ar:"نعم، أردت مشاهدة فيلم واحد كل أسبوع مع الترجمة."},{s:0,t:"Das konnte dein Hören verbessern. Musstest du auch Sätze schreiben?",ar:"كان ذلك سيحسّن استماعك. هل كان عليك كتابة جمل أيضًا؟"},{s:1,t:"Ja, ich musste jeden Tag zehn Sätze in mein Heft schreiben.",ar:"نعم، كان عليّ كتابة عشر جمل كل يوم في دفتري."},{s:0,t:"Was wolltest du mit der Grammatik machen?",ar:"ماذا أردت أن تفعل بشأن القواعد؟"},{s:1,t:"Ich wollte jede Woche eine Grammatikregel lernen.",ar:"أردت تعلم قاعدة نحوية واحدة كل أسبوع."},{s:0,t:"Gut. Ich konnte dir Übungen für jede Regel geben.",ar:"جيد. استطعت إعطاءك تمارين لكل قاعدة."},{s:1,t:"Danke. Sollten die Übungen schwer sein?",ar:"شكرًا. هل كان يجب أن تكون التمارين صعبة؟"},{s:0,t:"Sie sollten ein bisschen schwer sein, aber du konntest viel lernen.",ar:"كان يجب أن تكون صعبة قليلًا، لكنك استطعت تعلم الكثير."},{s:1,t:"Ich hatte keine Angst. Ich wollte mein Bestes geben.",ar:"لم أكن خائفًا. أردت بذل قصارى جهدي."},{s:0,t:"Das ist die richtige Einstellung. Wann wolltest du anfangen?",ar:"هذا هو الموقف الصحيح. متى أردت أن تبدأ؟"},{s:1,t:"Ich wollte morgen früh um sieben Uhr anfangen.",ar:"أردت البدء غدًا صباحًا في السابعة."},{s:0,t:"Wolltest du allein oder in einer Gruppe lernen?",ar:"هل أردت الدراسة وحدك أم مع مجموعة؟"},{s:1,t:"Ich wollte mit meinen Freunden lernen. Wir mussten uns gegenseitig helfen.",ar:"أردت الدراسة مع أصدقائي. كان علينا مساعدة بعضنا بعضًا."},{s:0,t:"Zusammen zu lernen ist eine gute Idee. Konntet ihr euch in der Bibliothek treffen?",ar:"الدراسة معًا فكرة جيدة. هل استطعتم اللقاء في المكتبة؟"},{s:1,t:"Ja, wir konnten uns jeden Samstag in der Bibliothek treffen.",ar:"نعم، استطعنا اللقاء في المكتبة كل يوم سبت."},{s:0,t:"Wie lange konntest du jeden Tag lernen?",ar:"كم استطعت الدراسة كل يوم؟"},{s:1,t:"Ich konnte jeden Tag zwei Stunden lernen, und am Wochenende mehr.",ar:"استطعت الدراسة ساعتين كل يوم، وأكثر في عطلة نهاية الأسبوع."},{s:0,t:"Das war genug. Wolltest du auch einen Online-Kurs machen?",ar:"هذا كان كافيًا. هل أردت أخذ دورة عبر الإنترنت أيضًا؟"},{s:1,t:"Ja, ich wollte nächsten Monat an einem Online-Kurs teilnehmen.",ar:"نعم، أردت الانضمام إلى دورة عبر الإنترنت الشهر المقبل."},{s:0,t:"Welchen Kurs wolltest du wählen?",ar:"أي دورة أردت أن تختار؟"},{s:1,t:"Ich wollte den Kurs über alltägliches Englisch wählen.",ar:"أردت اختيار الدورة عن الإنجليزية اليومية."},{s:0,t:"Eine gute Wahl. Konnten deine Eltern dir helfen?",ar:"اختيار جيد. هل استطاع والداك مساعدتك؟"},{s:1,t:"Ja, sie konnten mir helfen. Mein Vater wollte mir neue Bücher kaufen.",ar:"نعم، استطاعا مساعدتي. أراد أبي شراء كتب جديدة لي."},{s:0,t:"Wunderbar. Was wolltest du nach der Prüfung machen?",ar:"رائع. ماذا أردت أن تفعل بعد الامتحان؟"},{s:1,t:"Nach der Prüfung wollte ich reisen und mein Englisch üben.",ar:"بعد الامتحان، أردت السفر والتدرب على لغتي الإنجليزية."},{s:0,t:"Wohin wolltest du reisen?",ar:"إلى أين أردت السفر؟"},{s:1,t:"Ich wollte London besuchen. Ich musste dort jeden Tag Englisch sprechen.",ar:"أردت زيارة لندن. كان عليّ التحدث بالإنجليزية كل يوم هناك."},{s:0,t:"Das wäre eine tolle Erfahrung gewesen. Ich war sicher, dass du es schaffen würdest.",ar:"كانت ستكون تجربة رائعة. كنت متأكدًا أنك ستنجح."},{s:1,t:"Danke, Lehrer. Dein Rat war sehr hilfreich.",ar:"شكرًا، يا معلم. كانت نصيحتك مفيدة جدًا."},{s:0,t:"Gern geschehen. Denk daran, ich konnte dir immer helfen.",ar:"على الرحب والسعة. تذكر، استطعت دائمًا مساعدتك."},{s:1,t:"Das werde ich nicht vergessen. Ich wollte jeden Tag hart arbeiten.",ar:"لن أنسى ذلك. أردت العمل بجد كل يوم."},{s:0,t:"Ich glaubte an dich. Viel Glück bei deinem Studium!",ar:"آمنت بك. بالتوفيق في دراستك!"},{s:1,t:"Danke. Ich werde dich morgen im Unterricht sehen.",ar:"شكرًا. سأراك في الصف غدًا."},{s:0,t:"Bis morgen. Vergiss dein Heft nicht!",ar:"أراك غدًا. لا تنسَ دفترك!"},{s:1,t:"Ich werde es nicht vergessen. Auf Wiedersehen, Lehrer!",ar:"لن أنساه. وداعًا، يا معلم!"}]}}]};var CONV_DATA_B1={en:[{stage:1,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"حياة جديدة في مدينة جديدة",grammar:{id:"en-b1-second-conditional",title:"Second conditional",titleAr:"الشرط الثاني",covers:1},conv:{id:"en-stage1-b1",speakers:["Old Friend (الصديق القديم)","New Friend (الصديق الجديد)"],turns:[{s:0,t:"No way! Is that really you? I haven't seen you in forever!",ar:"مستحيل! هل هذا أنت حقًا؟ لم أرك منذ زمن طويل!"},{s:1,t:"Yeah, it's me! I can't believe we ran into each other here.",ar:"نعم، إنه أنا! لا أصدق أننا التقينا هنا."},{s:0,t:"I mean, what are the odds? I've been living in this city for two years now, and I still wonder if I made the right choice.",ar:"أعني، ما احتمال حدوث ذلك؟ أعيش في هذه المدينة منذ سنتين الآن، وما زلت أتساءل إن كنت اتخذت القرار الصحيح."},{s:1,t:"Two years? That's amazing. I just moved here last month, to be honest. I'm still getting familiar with the streets.",ar:"سنتان؟ هذا مذهل. انتقلت إلى هنا الشهر الماضي فقط، بصراحة. ما زلت أتعرف على الشوارع."},{s:0,t:"Seriously? Well, welcome! How are you finding it so far? Do me a favor and tell me honestly — is it what you expected?",ar:"حقًا؟ حسنًا، أهلًا بك! كيف تجدها حتى الآن؟ أخبرني بصراحة — هل هي كما توقعت؟"},{s:1,t:"Honestly, it's a bit much. The traffic, the noise... it's totally different from home, and the pace of life is fairly crazy.",ar:"بصراحة، الأمر كثير بعض الشيء. الزحام والضوضاء... إنها مختلفة تمامًا عن الوطن، وإيقاع الحياة مجنون إلى حد ما."},{s:0,t:"Uh-huh, I get it. I felt exactly the same at first. I was so lonely in the beginning, and a bit upset most days.",ar:"أها، أفهمك. شعرت بالشيء نفسه تمامًا في البداية. كنت وحيدًا جدًا في البداية، ومنزعجًا بعض الشيء معظم الأيام."},{s:1,t:"Really? You always seemed so confident. I thought you'd fit right in. Obviously, I was wrong about that!",ar:"حقًا؟ كنت تبدو واثقًا دائمًا. ظننت أنك ستندمج فورًا. من الواضح أنني كنت مخطئًا في ذلك!"},{s:0,t:"Ha! I was faking it. I didn't know a single person here, and I was too shy to contact anyone.",ar:"ها! كنت أتظاهر. لم أكن أعرف شخصًا واحدًا هنا، وكنت خجولًا جدًا من التواصل مع أي شخص."},{s:1,t:"So what changed? You seem pretty relaxed now. Were you aware of how stressed you looked back then?",ar:"إذن ما الذي تغيّر؟ تبدو مرتاحًا جدًا الآن. هل كنت مدركًا لمدى توترك في ذلك الوقت؟"},{s:0,t:"I joined a football club, and I met some great people. Friendship takes time, you know? But the atmosphere there is so cheerful and calm.",ar:"انضممت إلى نادٍ لكرة القدم، وقابلت أشخاصًا رائعين. الصداقة تحتاج وقتًا، كما تعلم؟ لكن الأجواء هناك مرحة وهادئة جدًا."},{s:1,t:"That's good advice. I've been meaning to join something too. I really aim to meet new people this year.",ar:"هذه نصيحة جيدة. كنت أنوي الانضمام إلى شيء ما أيضًا. أهدف حقًا إلى مقابلة أشخاص جدد هذا العام."},{s:0,t:"You should! If I had more free time, I'd join a music club as well. I've always intended to learn the piano.",ar:"عليك أن تفعل! لو كان لدي وقت فراغ أكثر، لانضممت إلى نادٍ موسيقي أيضًا. لطالما نويت تعلم البيانو."},{s:1,t:"Music? I didn't know you played anything.",ar:"الموسيقى؟ لم أكن أعلم أنك تعزف على شيء."},{s:0,t:"I don't, really. But I've always admired people who can play the guitar. It always makes a strong impression on me.",ar:"لا، في الحقيقة. لكنني لطالما أعجبت بالأشخاص الذين يعزفون على الغيتار. إنه يترك دائمًا انطباعًا قويًا لدي."},{s:1,t:"Yeah, my brother's really talented. He plays by ear, no lessons at all. He has a neat little studio at home, actually.",ar:"نعم، أخي موهوب حقًا. يعزف بالسمع، دون أي دروس. لديه في الحقيقة استوديو صغير مرتب في البيت."},{s:0,t:"Wow, that's a real talent. I'd love to hear him play sometime. He could simply perform at my place one evening!",ar:"واو، هذه موهبة حقيقية. أود أن أسمعه يعزف يومًا ما. يمكنه ببساطة أن يعزف في بيتي ذات مساء!"},{s:1,t:"Sure! Come over on Friday. We're having a small get-together at my place. Plus, my brother will be there.",ar:"بالتأكيد! تعال يوم الجمعة. لدينا تجمع صغير في بيتي. إضافة إلى ذلك، أخي سيكون هناك."},{s:0,t:"I'd love to, but I'm not sure about Friday. Let me check my schedule. My intention was to rest that day, actually.",ar:"أود ذلك، لكنني لست متأكدًا بشأن الجمعة. دعني أتحقق من جدولي. كانت نيتي أن أستريح في ذلك اليوم، في الحقيقة."},{s:1,t:"No worries. Just let me know. Oh, and bring your friend from work if you want.",ar:"لا مشكلة. فقط أخبرني. وأحضر صديقك من العمل إن أردت."},{s:0,t:"Hmm, he's a bit shy around new people. But I'll ask him. He apologized last time for missing my party, so he owes me one.",ar:"همم، إنه خجول بعض الشيء مع الأشخاص الجدد. لكنني سأسأله. لقد اعتذر في المرة الماضية عن تفويت حفلتي، لذا فهو مدين لي بردّ الجميل."},{s:1,t:"That's fine. So, what do you do for work these days? Is the café job related to what you studied?",ar:"لا بأس. إذن، ماذا تعمل هذه الأيام؟ هل وظيفة المقهى مرتبطة بما درسته؟"},{s:0,t:"I'm a teacher now. I teach English at a language school downtown. It's a private school, mainly for adults.",ar:"أنا معلم الآن. أدرّس الإنجليزية في مدرسة لغات وسط المدينة. إنها مدرسة خاصة، أساسًا للبالغين."},{s:1,t:"No way! That's fantastic. I always thought you'd be great at it.",ar:"مستحيل! هذا رائع. كنت أظن دائمًا أنك ستكون ممتازًا في ذلك."},{s:0,t:"Thanks. It's hard work, but I really enjoy it. What about you? My relatives all ask me the same question, by the way.",ar:"شكرًا. إنه عمل شاق، لكنني أستمتع به حقًا. وماذا عنك؟ أقاربي جميعًا يسألونني السؤال نفسه، بالمناسبة."},{s:1,t:"I'm still figuring things out, to be honest. I work part-time in a café. I can barely afford the rent, but I manage.",ar:"ما زلت أحاول فهم الأمور، بصراحة. أعمل بدوام جزئي في مقهى. بالكاد أستطيع تحمل الإيجار، لكنني أتدبر أمري."},{s:0,t:"There's nothing wrong with that. You've got time to decide. And part-time work can teach you a lot, personally.",ar:"لا بأس في ذلك. لديك وقت لتقرر. والعمل بدوام جزئي يمكن أن يعلمك الكثير، على المستوى الشخصي."},{s:1,t:"I know, but my parents keep asking about my plans. It puts me under a lot of pressure. It's particularly hard at family dinners.",ar:"أعلم، لكن والديّ يسألان باستمرار عن خططي. هذا يضعني تحت ضغط كبير. إنه صعب بشكل خاص في عشاءات العائلة."},{s:0,t:"I totally understand. My ambition was to be a writer, and my dad just laughed. He said writing had no real value.",ar:"أفهمك تمامًا. كان طموحي أن أكون كاتبًا، ووالدي ضحك فقط. قال إن الكتابة ليس لها قيمة حقيقية."},{s:1,t:"Did he? That's rough. But look at you now — you're doing what you love, and success attracts success.",ar:"هل فعل؟ هذا قاسٍ. لكن انظر إليك الآن — أنت تفعل ما تحب، والنجاح يجذب النجاح."},{s:0,t:"Yeah, eventually I stopped worrying about what others think. It took a while, though. I had to learn to relate to people as I am, not as they want me to be.",ar:"نعم، توقفت في النهاية عن القلق بشأن ما يظنه الآخرون. لكن الأمر استغرق بعض الوقت. كان عليّ أن أتعلم التواصل مع الناس كما أنا، وليس كما يريدونني أن أكون."},{s:1,t:"I admire that. I wish I could be that brave.",ar:"أعجب بذلك. أتمنى لو كنت شجاعًا هكذا."},{s:0,t:"You are brave — you moved to a new city! That's a big step. And your English is perfectly fine, don't worry about it.",ar:"أنت شجاع — انتقلت إلى مدينة جديدة! هذه خطوة كبيرة. وإنجليزيتك جيدة تمامًا، لا تقلق بشأنها."},{s:1,t:"Thanks, man. That means a lot. So, any tips for a newcomer? What would you recommend first?",ar:"شكرًا يا صديقي. هذا يعني لي الكثير. إذن، أي نصائح لقادم جديد؟ ماذا توصي به أولًا؟"},{s:0,t:"First, explore the neighborhood. And don't be afraid to talk to strangers. People here are generally friendly — just say hi, and you'll naturally start a conversation.",ar:"أولًا، استكشف الحي. ولا تخف من التحدث إلى الغرباء. الناس هنا ودودون عمومًا — قل مرحبًا فقط، وستبدأ محادثة بشكل طبيعي."},{s:1,t:"Talk to strangers? That's not really my style. I'm not good at small talk, and I get mad at myself afterward.",ar:"التحدث إلى الغرباء؟ هذا ليس أسلوبي حقًا. لست جيدًا في الأحاديث القصيرة، وأغضب من نفسي بعد ذلك."},{s:0,t:"I know, I know. But people here are generally friendly. Just say hi. Most of them are pleasant, honestly.",ar:"أعلم، أعلم. لكن الناس هنا ودودون عمومًا. قل مرحبًا فقط. معظمهم لطيفون، بصراحة."},{s:1,t:"All right, I'll give it a try. What's the worst that could happen? Surely nothing terrible.",ar:"حسنًا، سأجرب. ما أسوأ ما يمكن أن يحدث؟ بالتأكيد لا شيء فظيع."},{s:0,t:"Exactly! And if you ever feel down, just call me. I'm serious. I'm always glad to help, and it's a pleasure to have you here.",ar:"بالضبط! وإذا شعرت بالضيق يومًا، اتصل بي فقط. أنا جاد. أنا سعيد دائمًا بالمساعدة، ومن دواعي سروري وجودك هنا."},{s:1,t:"I appreciate that. Honestly, I'm really glad we bumped into each other. I'm grateful for friends like you.",ar:"أقدّر ذلك. بصراحة، أنا سعيد حقًا لأننا التقينا. أنا ممتن لأصدقاء مثلك."},{s:0,t:"Me too. Hey, I've gotta run — my class starts in twenty minutes. I have an appointment with a student after that.",ar:"وأنا أيضًا. اسمع، يجب أن أذهب — حصتي تبدأ بعد عشرين دقيقة. لدي موعد مع طالب بعد ذلك."},{s:1,t:"Oh, sure! Go, go. We're gonna catch up properly this weekend. We can hang out and talk about various things.",ar:"أوه، بالتأكيد! اذهب، اذهب. سنلتقي بشكل صحيح في عطلة الأسبوع. يمكننا الخروج والتحدث عن أشياء متنوعة."},{s:0,t:"Deal. I'll text you. It was great seeing you again!",ar:"اتفقنا. سأرسل لك رسالة. كان من الرائع رؤيتك مجددًا!"},{s:1,t:"You too! Take care, and good luck with the class. And let me know about Friday — I need a definite answer by Thursday!",ar:"وأنت أيضًا! اعتنِ بنفسك، وحظًا سعيدًا في الحصة. وأخبرني عن الجمعة — أحتاج إلى إجابة محددة بحلول الخميس!"}]}},{stage:2,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"الطبخ في البيت أم الأكل في الخارج؟",grammar:{id:"en-b1-present-perfect-continuous",title:"Present perfect continuous",titleAr:"المضارع التام المستمر",covers:1},conv:{id:"en-stage2-b1",speakers:["Cook (الطباخ)","Guest (الضيف)"],turns:[{s:0,t:"Welcome! Come in, come in. I've been cooking all afternoon. I've been preparing a special celebration dinner.",ar:"أهلًا! تفضل، تفضل. كنت أطبخ طوال فترة ما بعد الظهر. كنت أجهّز عشاء احتفال خاص."},{s:1,t:"Wow, it smells amazing in here! What are you making? The bubbles in that pot look fantastic.",ar:"واو، الرائحة مذهلة هنا! ماذا تصنع؟ الفقاعات في ذلك القدر تبدو رائعة."},{s:0,t:"Chicken with rice, and a spicy sauce. My grandmother's recipe. The mixture of herbs in it is amazing.",ar:"دجاج مع الأرز، وصلصة حارة. وصفة جدتي. خليط الأعشاب فيها مذهل."},{s:1,t:"Spicy? How spicy are we talking? I'm not great with hot food. I like frozen yogurt better than spicy food, honestly.",ar:"حارة؟ كم هي حارة؟ أنا لست جيدًا مع الطعام الحار. أحب الزبادي المثلج أكثر من الطعام الحار، بصراحة."},{s:0,t:"Don't worry, it's mild. Just a little chili for flavor.",ar:"لا تقلق، إنها خفيفة. القليل من الفلفل الحار فقط للنكهة."},{s:1,t:"Okay, good. I once tried a curry that nearly killed me.",ar:"حسنًا، جيد. جربت مرة كاريًا كاد أن يقتلني."},{s:0,t:"Ha! I know that feeling. So, can I get you something to drink? We've got juice, soda, and alcohol-free beer. My cousin's alcoholic, so we never keep real alcohol in the house.",ar:"ها! أعرف ذلك الشعور. إذن، هل أقدم لك شيئًا تشربه؟ لدينا عصير وصودا وبيرة خالية من الكحول. ابن عمي مدمن كحول، لذلك لا نحتفظ أبدًا بكحول حقيقي في البيت."},{s:1,t:"Just water, please. I've been drinking coffee all day. Pour me a big glass, I'm so thirsty.",ar:"ماء فقط، من فضلك. كنت أشرب القهوة طوال اليوم. اسكب لي كوبًا كبيرًا، أنا عطشان جدًا."},{s:0,t:"Sure. Here you go. So, do you cook much at home?",ar:"بالتأكيد. تفضل. إذن، هل تطبخ كثيرًا في البيت؟"},{s:1,t:"To be honest, hardly ever. I usually order food or eat out. I admit it's lazy, but it's convenient.",ar:"بصراحة، نادرًا جدًا. عادة أطلب طعامًا أو آكل في الخارج. أعترف أنه كسل، لكنه مريح."},{s:0,t:"Really? But cooking at home is so much cheaper. And healthier too.",ar:"حقًا؟ لكن الطبخ في البيت أرخص بكثير. وأصح أيضًا."},{s:1,t:"I know, I know. But I never have time. Work eats up my whole day.",ar:"أعلم، أعلم. لكن ليس لدي وقت أبدًا. العمل يلتهم يومي كله."},{s:0,t:"I get it. But look, this dish only took thirty minutes. It's a piece of cake, and it's cheaper than having food delivered.",ar:"أفهمك. لكن انظر، هذا الطبق استغرق ثلاثين دقيقة فقط. إنه سهل جدًا، وأرخص من توصيل الطعام."},{s:1,t:"Thirty minutes? That can't be right. What's the secret?",ar:"ثلاثون دقيقة؟ لا يمكن أن يكون ذلك صحيحًا. ما السر؟"},{s:0,t:"The secret is planning. I prepare all the ingredients first, then I cook. I measure everything carefully.",ar:"السر هو التخطيط. أجهّز كل المكونات أولًا، ثم أطبخ. أقيس كل شيء بعناية."},{s:1,t:"Hmm, that makes sense. I always end up running to the shop mid-recipe.",ar:"همم، هذا منطقي. أنا دائمًا ينتهي بي الأمر بالركض إلى المتجر في منتصف الوصفة."},{s:0,t:"That's the classic mistake! Anyway, taste this sauce and tell me what you think.",ar:"هذا هو الخطأ الكلاسيكي! على أي حال، تذوق هذه الصلصة وأخبرني برأيك."},{s:1,t:"Mmm... wow! That's delicious. What's in it? Can I have another bite? It's so good.",ar:"ممم... واو! هذا لذيذ. ما مكوناته؟ هل يمكنني تناول لقمة أخرى؟ إنه جيد جدًا."},{s:0,t:"Tomatoes, garlic, a bit of flour to thicken it, and some herbs. And a little powder — a secret spice.",ar:"طماطم وثوم وقليل من الدقيق لتكثيفها وبعض الأعشاب. وقليل من المسحوق — بهار سري."},{s:1,t:"Flour in a sauce? I never would've guessed that.",ar:"دقيق في الصلصة؟ لم أكن لأخمن ذلك أبدًا."},{s:0,t:"Yeah, it's an old trick. My mom taught me. Now, help me set the table? And don't worry about payment — dinner's on me tonight.",ar:"نعم، إنها حيلة قديمة. أمي علمتني إياها. الآن، ساعدني في تجهيز الطاولة؟ ولا تقلق بشأن الدفع — العشاء على حسابي الليلة."},{s:1,t:"Of course. Plates, forks... where are the glasses?",ar:"بالطبع. الأطباق والشوك... أين الكؤوس؟"},{s:0,t:"In the cupboard above the sink. Careful, the shelf is a bit loose. The glasses are in a plastic container on the left.",ar:"في الخزانة فوق المغسلة. انتبه، الرف مرتخٍ بعض الشيء. الكؤوس في وعاء بلاستيكي على اليسار."},{s:1,t:"Got it. So, do you bake as well, or just cook?",ar:"فهمت. إذن، هل تخبز أيضًا، أم تطبخ فقط؟"},{s:0,t:"I bake on weekends. Bread, cakes... last week I tried frying doughnuts. I even made a fancy cake for my sister's birthday.",ar:"أخبز في عطلة الأسبوع. خبز وكعك... الأسبوع الماضي جربت قلي الدونات. حتى أنني صنعت كعكة فاخرة لعيد ميلاد أختي."},{s:1,t:"Doughnuts? Now you're talking! I could eat ten of those. A doughnut is the perfect treat after a long week.",ar:"دونات؟ الآن أنت تتحدث! يمكنني أن آكل عشرة منها. الدونات هي المكافأة المثالية بعد أسبوع طويل."},{s:0,t:"Ha! Well, I've been cutting down on sugar lately. My doctor warned me.",ar:"ها! حسنًا، قللت السكر مؤخرًا. طبيبي حذرني."},{s:1,t:"Seriously? What did he say exactly?",ar:"حقًا؟ ماذا قال بالضبط؟"},{s:0,t:"He said if I keep eating like this, I'll have problems. So I'm trying. I have to consume less sugar and less fat.",ar:"قال إنني إذا واصلت الأكل هكذا، سأواجه مشاكل. لذلك أحاول. يجب أن أستهلك سكرًا ودهونًا أقل."},{s:1,t:"That's fair. I should probably do the same. I drink way too much soda. As a consumer, I never read the label — I should start.",ar:"هذا عادل. ربما يجب أن أفعل الشيء نفسه. أشرب الكثير من المشروبات الغازية. كمستهلك، لا أقرأ الملصق أبدًا — يجب أن أبدأ."},{s:0,t:"Yeah, soda's full of sugar. Anyway — dinner's ready! Sit down.",ar:"نعم، المشروبات الغازية مليئة بالسكر. على أي حال — العشاء جاهز! اجلس."},{s:1,t:"Finally! I'm starving. This looks incredible.",ar:"أخيرًا! أنا جائع جدًا. هذا يبدو رائعًا."},{s:0,t:"Thanks! Take plenty, there's lots more in the pot. Take a big slice of chicken — there's plenty for everyone.",ar:"شكرًا! خذ الكثير، هناك المزيد في القدر. خذ شريحة كبيرة من الدجاج — هناك ما يكفي للجميع."},{s:1,t:"Don't mind if I do. Mmm, the chicken is so tender.",ar:"لا مانع لدي. ممم، الدجاج طري جدًا."},{s:0,t:"Glad you like it. The trick is to fry it quickly, then let it cook slowly. And always use a wide pan, not a small one.",ar:"سعيد أنه أعجبك. الحيلة هي قليه بسرعة، ثم تركه يُطهى ببطء. واستخدم دائمًا مقلاة واسعة، وليست صغيرة."},{s:1,t:"I'll remember that. Honestly, this beats any restaurant.",ar:"سأتذكر ذلك. بصراحة، هذا أفضل من أي مطعم."},{s:0,t:"That's the nicest thing anyone's said all week. Want seconds?",ar:"هذا ألطف شيء قاله أحد طوال الأسبوع. تريد المزيد؟"},{s:1,t:"I shouldn't, but... yeah, just a little more rice. The sauce is so good — it's not too liquid, not too solid.",ar:"لا يجب أن أفعل، لكن... نعم، القليل من الأرز فقط. الصلصة جيدة جدًا — ليست سائلة جدًا ولا صلبة جدًا."},{s:0,t:"Here. And save room for dessert — I've made apple pie. We can freeze the leftovers for another day.",ar:"تفضل. واترك مكانًا للحلوى — لقد صنعت فطيرة تفاح. يمكننا تجميد البقايا ليوم آخر."},{s:1,t:"Apple pie? You're killing me! I love it. Let's gather around the table for dessert — it's a family tradition.",ar:"فطيرة تفاح؟ أنت تقتلني! أحبها. لنتجمع حول الطاولة للحلوى — إنها تقليد عائلي."},{s:0,t:"I know, I know. But first, let's finish this. No rush.",ar:"أعلم، أعلم. لكن أولًا، لننهِ هذا. لا عجلة."},{s:1,t:"Deal. And next time, I'm cooking for you. Fair's fair. I'll cook on a special occasion, I promise.",ar:"اتفقنا. وفي المرة القادمة، سأطبخ لك. العدل عدل. سأطبخ في مناسبة خاصة، أعدك."},{s:0,t:"I'll hold you to that! But no ordering pizza and calling it cooking. Next time, no discounts, no delivery — real cooking!",ar:"سأحاسبك على ذلك! لكن لا تطلب بيتزا وتسميها طبخًا. في المرة القادمة، لا خصومات ولا توصيل — طبخ حقيقي!"},{s:1,t:"Ha! Fine, fine. I'll actually cook. I promise. And I'll keep the receipt, so you can see what I paid.",ar:"ها! حسنًا، حسنًا. سأطبخ فعلًا. أعدك. وسأحتفظ بالإيصال، حتى ترى ما دفعته."}]}},{stage:3,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"رحلة على الطريق",grammar:{id:"en-b1-relative-clauses",title:"Relative clauses",titleAr:"جمل الوصل",covers:1},conv:{id:"en-stage3-b1",speakers:["Traveler (المسافر)","Local Guide (المرشد المحلي)"],turns:[{s:0,t:"Hi! I'm looking for the bus that goes to the old town. Is this the right stop? I'm trying to locate the castle, but I can't find it on the map.",ar:"مرحبًا! أبحث عن الحافلة التي تذهب إلى المدينة القديمة. هل هذه المحطة الصحيحة؟ أحاول تحديد موقع القلعة، لكنني لا أستطيع العثور عليها على الخريطة."},{s:1,t:"Yeah, this is the one. The bus that leaves at ten is usually on time. It typically arrives two minutes early, actually.",ar:"نعم، هذه هي. الحافلة التي تغادر في العاشرة تكون في موعدها عادة. إنها عادة تصل قبل موعدها بدقيقتين، في الحقيقة."},{s:0,t:"Great. I've been waiting for ages. Do you know how long the journey takes? The bus was due ten minutes ago, apparently.",ar:"رائع. كنت أنتظر منذ زمن. هل تعرف كم تستغرق الرحلة؟ كان من المفترض أن تأتي الحافلة قبل عشر دقائق، على ما يبدو."},{s:1,t:"About forty minutes, depending on traffic. The road that goes through the hills is slow. Meanwhile, you can enjoy the view of the fields.",ar:"نحو أربعين دقيقة، حسب الزحام. الطريق الذي يمر عبر التلال بطيء. وفي هذه الأثناء، يمكنك الاستمتاع بمنظر الحقول."},{s:0,t:"Forty minutes isn't bad. I was worried it'd take hours. I was determined to get there today, despite the rain. Fasten your seatbelt — the road is bumpy.",ar:"أربعون دقيقة ليست سيئة. كنت قلقًا من أنها ستستغرق ساعات. كنت مصممًا على الوصول إلى هناك اليوم، رغم المطر. اربط حزام الأمان — الطريق وعر."},{s:1,t:"Nah, you'll be fine. Are you visiting for the first time?",ar:"لا، ستكون بخير. هل تزور للمرة الأولى؟"},{s:0,t:"Yeah, first time in this country. I flew in yesterday, and I'm still a bit jet-lagged. My arrival was late, and the airport was a mess.",ar:"نعم، المرة الأولى في هذا البلد. وصلت بالطائرة أمس، وما زلت متعبًا من فرق التوقيت. كان وصولي متأخرًا، وكان المطار في فوضى."},{s:1,t:"That explains the tired eyes! Where are you staying?",ar:"هذا يفسر العيون المتعبة! أين تقيم؟"},{s:0,t:"A small hotel near the port. The place where my friend stayed last year. I made a reservation online, and it was really cheap.",ar:"فندق صغير قرب الميناء. المكان الذي أقام فيه صديقي العام الماضي. قمت بحجز عبر الإنترنت، وكان رخيصًا حقًا."},{s:1,t:"Oh, that's a nice area. The port's beautiful at sunset. The native fishermen still sing old songs there in the evening.",ar:"أوه، هذه منطقة جميلة. الميناء جميل عند الغروب. الصيادون الأصليون ما زالوا يغنون أغاني قديمة هناك في المساء."},{s:0,t:"Good to know. So, what should I see first in the old town? I want to determine the best route before I start walking.",ar:"جيد أن أعرف. إذن، ماذا يجب أن أرى أولًا في المدينة القديمة؟ أريد تحديد أفضل طريق قبل أن أبدأ المشي."},{s:1,t:"The castle, for sure. It's the building that everyone photographs. There's a sailor's museum next to it too — the entrance is free.",ar:"القلعة، بالتأكيد. إنها المبنى الذي يصوره الجميع. وهناك متحف للبحارة بجانبها أيضًا — الدخول مجاني."},{s:0,t:"I've seen pictures. It looks huge! Is it far from the bus stop? Approximately how many minutes on foot?",ar:"رأيت صورًا. تبدو ضخمة! هل هي بعيدة عن محطة الحافلات؟ كم دقيقة تقريبًا سيرًا على الأقدام؟"},{s:1,t:"Not at all. Just walk straight ahead, then turn left at the square. There's a row of old shops on your right.",ar:"ليست بعيدة إطلاقًا. امشِ مستقيمًا، ثم انعطف يسارًا عند الساحة. هناك صف من المتاجر القديمة على يمينك."},{s:0,t:"Perfect. And is there anywhere to eat nearby? I'm starving. I haven't eaten since my departure this morning.",ar:"ممتاز. وهل يوجد مكان للأكل قريب؟ أنا جائع جدًا. لم آكل منذ مغادرتي هذا الصباح."},{s:1,t:"Plenty of places. There's a café that serves the best fish in town. They grill it over coal, and it tastes wonderful.",ar:"الكثير من الأماكن. هناك مقهى يقدم أفضل سمك في المدينة. يشوونه على الفحم، وطعمه رائع."},{s:0,t:"Fish? I love fish. But I got sick from seafood once, so I'm careful. I had a horrible stomach bug after eating oysters.",ar:"سمك؟ أحب السمك. لكنني مرضت من المأكولات البحرية مرة، لذلك أنا حذر. أصبت بمرض معدة فظيع بعد أكل المحار."},{s:1,t:"I get it. Well, the food here is fresh — the fishermen bring it in every morning.",ar:"أفهمك. حسنًا، الطعام هنا طازج — الصيادون يجلبونه كل صباح."},{s:0,t:"That sounds great. What else is worth seeing around here? What's the main attraction for tourists?",ar:"هذا يبدو رائعًا. ماذا أيضًا يستحق المشاهدة هنا؟ ما هو عامل الجذب الرئيسي للسياح؟"},{s:1,t:"The market, definitely. It's the place where locals buy everything. After that, walk to the beach — the sand is white, and you can collect shells.",ar:"السوق، بالتأكيد. إنه المكان الذي يشتري منه السكان كل شيء. بعد ذلك، امشِ إلى الشاطئ — الرمل أبيض، ويمكنك جمع الأصداف."},{s:0,t:"I love markets. I could spend hours just looking around. I love to escape the crowds and wander through small streets.",ar:"أحب الأسواق. يمكنني قضاء ساعات في التجول فقط. أحب الهروب من الزحام والتجول في الشوارع الصغيرة."},{s:1,t:"Me too. Oh — here's the bus! Quick, let's get on before it fills up. There's a sudden rush every morning at this time.",ar:"وأنا أيضًا. أوه — هذه الحافلة! بسرعة، لنصعد قبل أن تمتلئ. هناك اندفاع مفاجئ كل صباح في هذا الوقت."},{s:0,t:"Wait, I need a ticket first. Do they sell them on the bus? I need to exchange some currency too — do you know where?",ar:"انتظر، أحتاج تذكرة أولًا. هل يبيعونها في الحافلة؟ أحتاج إلى صرف بعض العملة أيضًا — هل تعرف أين؟"},{s:1,t:"Yeah, you can pay the driver. It's two dollars, exact change if you can. Or you can rent a car at the station — just check the tires first.",ar:"نعم، يمكنك الدفع للسائق. دولاران، والمبلغ الصحيح إن أمكن. أو يمكنك استئجار سيارة في المحطة — فقط افحص الإطارات أولًا."},{s:0,t:"Two dollars? That's cheap! Back home it'd cost twice as much. The fare is currently much higher in my city.",ar:"دولاران؟ هذا رخيص! في بلدي سيكلف ضعف ذلك. الأجرة حاليًا أعلى بكثير في مدينتي."},{s:1,t:"Yeah, transport here is pretty reasonable. Sit by the window — the view's great. You'll see the whole bay, and the boats with their white sails.",ar:"نعم، المواصلات هنا معقولة جدًا. اجلس بجانب النافذة — المنظر رائع. سترى الخليج كله، والقوارب بأشرعتها البيضاء."},{s:0,t:"Thanks. Wow, look at those hills! And the sea on the other side! What a sight — I need to take a photo.",ar:"شكرًا. واو، انظر إلى تلك التلال! والبحر على الجانب الآخر! يا له من مشهد — أحتاج إلى التقاط صورة."},{s:1,t:"Beautiful, right? The highway that runs along the coast is famous for this view.",ar:"جميل، أليس كذلك؟ الطريق السريع الذي يمتد على الساحل مشهور بهذا المنظر."},{s:0,t:"I can see why. I should've brought my camera. My phone will have to do. I wanted to take photos throughout the trip — especially of the rare birds in the east.",ar:"أرى السبب. كان يجب أن أحضر كاميرتي. هاتفي سيفي بالغرض. أردت التقاط صور طوال الرحلة — خاصة للطيور النادرة في الشرق."},{s:1,t:"Your phone's fine. Say, how long are you staying in the country? Will you take the tube to the capital, or the bus?",ar:"هاتفك جيد. قل لي، كم ستبقى في البلد؟ هل ستأخذ المترو إلى العاصمة، أم الحافلة؟"},{s:0,t:"Two weeks. Then I'm heading north to the mountains. The northern villages are famous for their old historical buildings. My final destination is a small village near the border.",ar:"أسبوعان. ثم أتوجه شمالًا إلى الجبال. القرى الشمالية مشهورة بمبانيها التاريخية القديمة. وجهتي النهائية قرية صغيرة قرب الحدود."},{s:1,t:"The mountains are stunning. But the weather there can change fast — pack a jacket. Fold your clothes tightly, and pack in layers.",ar:"الجبال مذهلة. لكن الطقس هناك يتغير بسرعة — احزم سترة. اطوِ ملابسك بإحكام، واحزم بطبقات."},{s:0,t:"Good tip. I packed light, which was probably a mistake. I forgot my tent, so I can't camp in the mountains now.",ar:"نصيحة جيدة. حزمت أمتعة خفيفة، وهذا كان خطأ على الأرجح. نسيت خيمتي، لذلك لا يمكنني التخييم في الجبال الآن."},{s:1,t:"You can buy cheap clothes at the market. No big deal. I always carry a rope when I hike — you never know when you'll need one.",ar:"يمكنك شراء ملابس رخيصة من السوق. لا مشكلة كبيرة. أحمل دائمًا حبلًا عندما أتنزه — لا تعرف أبدًا متى ستحتاجه."},{s:0,t:"True. By the way, is the border crossing to the north easy? Do they check customs, and is there any duty to pay?",ar:"صحيح. بالمناسبة، هل عبور الحدود إلى الشمال سهل؟ هل يفحصون الجمارك، وهل هناك أي رسوم يجب دفعها؟"},{s:1,t:"Usually, yeah. Just keep your passport handy. They check everyone. And don't carry spare fuel or a spare battery — they don't like that.",ar:"عادة، نعم. فقط احتفظ بجواز سفرك قريبًا. يفحصون الجميع. ولا تحمل وقودًا احتياطيًا أو بطارية احتياطية — لا يعجبهم ذلك."},{s:0,t:"Got it. Oh, look — we're nearly there! That must be the castle. The tower is located on the highest hill in the town.",ar:"فهمت. أوه، انظر — اقتربنا! لا بد أن تلك هي القلعة. البرج يقع على أعلى تل في المدينة."},{s:1,t:"That's it. The tower that sticks up above the roofs — you can't miss it. You can see the birds' wings from the top.",ar:"هذه هي. البرج الذي يعلو فوق الأسطح — لا يمكنك أن تخطئه. يمكنك رؤية أجنحة الطيور من الأعلى."},{s:0,t:"Amazing. Thanks so much for all the tips. You've been a lifesaver. This location is beautiful, and I hope to come back.",ar:"مذهل. شكرًا جزيلًا على كل النصائح. لقد أنقذتني. هذا الموقع جميل، وآمل أن أعود."},{s:1,t:"Anytime! Enjoy your trip. And if you get lost, just ask someone — people here love to help, whether you're a tourist or a local.",ar:"في أي وقت! استمتع برحلتك. وإذا ضللت الطريق، اسأل أي شخص — الناس هنا يحبون المساعدة، سواء كنت سائحًا أو محليًا."},{s:0,t:"I will. Oh no, the bus is moving again — I gotta go! The exit is at the back, right? Bye!",ar:"سأفعل. أوه لا، الحافلة تتحرك مجددًا — يجب أن أذهب! المخرج في الخلف، أليس كذلك؟ إلى اللقاء!"},{s:1,t:"Bye! Have a great day! And remember — whenever you need help, just ask.",ar:"إلى اللقاء! أتمنى لك يومًا رائعًا! وتذكر — كلما احتجت إلى مساعدة، اسأل فقط."}]}},{stage:4,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"وظيفة جديدة، قرارات صعبة",grammar:{id:"en-b1-passive-tenses",title:"Passive voice",titleAr:"المبني للمجهول",covers:1},conv:{id:"en-stage4-b1",speakers:["Job Seeker (الباحث عن عمل)","Manager (المدير)"],turns:[{s:0,t:"Good morning. Thanks for seeing me. I've been looking forward to this interview. I sent my application last week, and I was so happy to get your call.",ar:"صباح الخير. شكرًا لاستقبالي. كنت أتطلع إلى هذه المقابلة. أرسلت طلبي الأسبوع الماضي، وكنت سعيدًا جدًا بمكالمتكم."},{s:1,t:"Good morning, welcome. Please, sit down. Would you like some water? Our agent will join us in a minute — she's the one who found your CV.",ar:"صباح الخير، أهلًا بك. تفضل، اجلس. هل تريد بعض الماء؟ ستنضم إلينا وكيلتنا بعد دقيقة — إنها من وجدت سيرتك الذاتية."},{s:0,t:"Yes, please. I'm a bit nervous, to be honest. I really want this job — it's my dream profession.",ar:"نعم، من فضلك. أنا متوتر بعض الشيء، بصراحة. أريد هذه الوظيفة حقًا — إنها مهنة أحلامي."},{s:1,t:"Don't worry, that's normal. So, tell me a bit about yourself. What shift do you prefer — mornings or evenings?",ar:"لا تقلق، هذا طبيعي. إذن، أخبرني قليلًا عن نفسك. ما النوبة التي تفضلها — الصباح أم المساء؟"},{s:0,t:"Well, I've been working in sales for five years. I started as an assistant, and I was promoted last year. My employment record is clean, and I've never been fired.",ar:"حسنًا، أعمل في المبيعات منذ خمس سنوات. بدأت كمساعد، وتمت ترقيتي العام الماضي. سجل توظيفي نظيف، ولم يتم فصلي أبدًا."},{s:1,t:"That's impressive. Why are you looking for a new job now? Did you quit your last job, or were you let go?",ar:"هذا مثير للإعجاب. لماذا تبحث عن وظيفة جديدة الآن؟ هل استقلت من وظيفتك الأخيرة، أم تم الاستغناء عنك؟"},{s:0,t:"To be honest, I want a bigger challenge. My current job is fine, but there's no room to grow. I need a role with more responsibility.",ar:"بصراحة، أريد تحديًا أكبر. وظيفتي الحالية جيدة، لكن لا مجال للنمو. أحتاج إلى دور بمسؤولية أكبر."},{s:1,t:"I understand. Growth matters. What do you know about our company? We work in international trade, mostly with Asia.",ar:"أفهم. النمو مهم. ماذا تعرف عن شركتنا؟ نعمل في التجارة الدولية، معظمها مع آسيا."},{s:0,t:"Quite a lot, actually. I read that you were founded in 2010, and you've grown fast since then.",ar:"الكثير في الحقيقة. قرأت أنكم تأسستم عام 2010، ونموتم بسرعة منذ ذلك الحين."},{s:1,t:"Correct. We're proud of that. And what attracted you to this role?",ar:"صحيح. نحن فخورون بذلك. وما الذي جذبك إلى هذا الدور؟"},{s:0,t:"The job description mentioned teamwork and training, and that's exactly what I'm looking for. I also like that your management team is small and friendly.",ar:"الوصف الوظيفي ذكر العمل الجماعي والتدريب، وهذا بالضبط ما أبحث عنه. ويعجبني أيضًا أن فريق إدارتكم صغير وودود."},{s:1,t:"Good. We invest a lot in training. Our staff are given courses every year. It's our duty to help them grow.",ar:"جيد. نحن نستثمر كثيرًا في التدريب. يُمنح موظفونا دورات كل عام. من واجبنا مساعدتهم على النمو."},{s:0,t:"That's great to hear. Can I ask about the working hours? And do you hire many new people each year?",ar:"من الرائع سماع ذلك. هل يمكنني أن أسأل عن ساعات العمل؟ وهل توظفون العديد من الأشخاص الجدد كل عام؟"},{s:1,t:"Of course. It's nine to five, Monday to Friday. Sometimes we work shifts on weekends.",ar:"بالطبع. من التاسعة إلى الخامسة، من الاثنين إلى الجمعة. أحيانًا نعمل بنوبات في عطلة الأسبوع."},{s:0,t:"That works for me. And is the salary paid monthly? Is it a fixed salary, or does it change with sales? I'd like everything in the agreement before I sign.",ar:"هذا يناسبني. وهل يُدفع الراتب شهريًا؟ هل هو راتب ثابت، أم يتغير مع المبيعات؟ أود أن يكون كل شيء في الاتفاقية قبل أن أوقع."},{s:1,t:"Yes, at the end of each month. Plus a bonus if the team hits its targets. I can advise you on the bonus system later, if you like.",ar:"نعم، في نهاية كل شهر. إضافة إلى مكافأة إذا حقق الفريق أهدافه. يمكنني أن أنصحك بشأن نظام المكافآت لاحقًا، إذا أردت."},{s:0,t:"Sounds fair. What would my main responsibilities be? Would I work in marketing, or in sales?",ar:"يبدو عادلًا. ما مسؤولياتي الرئيسية؟ هل سأعمل في التسويق، أم في المبيعات؟"},{s:1,t:"You'd manage a small team, talk to clients, and report to me directly.",ar:"ستدير فريقًا صغيرًا، وتتحدث إلى العملاء، وتقدم تقاريرك لي مباشرة."},{s:0,t:"I can handle that. In my last job, I was responsible for twenty clients. I also trained new staff members every month.",ar:"أستطيع التعامل مع ذلك. في وظيفتي الأخيرة، كنت مسؤولًا عن عشرين عميلًا. ودرّبت أيضًا موظفين جددًا كل شهر."},{s:1,t:"Twenty? That's a lot. How did you manage the pressure? You must have nailed every deadline.",ar:"عشرون؟ هذا كثير. كيف تعاملت مع الضغط؟ لا بد أنك أنجزت كل موعد نهائي بإتقان."},{s:0,t:"I learned to organize my day. I make a list every morning, and I stick to it.",ar:"تعلمت تنظيم يومي. أضع قائمة كل صباح، وألتزم بها."},{s:1,t:"Smart. Now, a tricky question: what's your biggest weakness? Be honest — I can tell when people pretend.",ar:"ذكي. الآن، سؤال صعب: ما أكبر نقطة ضعف لديك؟ كن صادقًا — أستطيع أن أعرف عندما يتظاهر الناس."},{s:0,t:"Hmm. I tend to take on too much work. I'm learning to say no. I know I need a qualification in management to go further, though.",ar:"همم. أميل إلى تحمل الكثير من العمل. أتعلم أن أقول لا. أعلم أنني أحتاج إلى مؤهل في الإدارة للتقدم أكثر، مع ذلك."},{s:1,t:"That's an honest answer. Most people say something silly like 'I'm a perfectionist.'",ar:"هذه إجابة صادقة. معظم الناس يقولون شيئًا سخيفًا مثل 'أنا كمالي'."},{s:0,t:"Ha! Well, I've made that mistake before. So, when will I hear back?",ar:"ها! حسنًا، ارتكبت ذلك الخطأ من قبل. إذن، متى سأسمع الرد؟"},{s:1,t:"We'll decide by Friday. If you're chosen, you'll be called for a second interview.",ar:"سنقرر بحلول الجمعة. إذا تم اختيارك، ستُدعى لمقابلة ثانية."},{s:0,t:"Understood. One more thing — is there room for promotion here? I feel qualified for a senior role within two years.",ar:"مفهوم. شيء آخر — هل يوجد مجال للترقية هنا؟ أشعر أنني مؤهل لدور أعلى خلال سنتين."},{s:1,t:"Absolutely. Two of our managers started in your position. Hard work is noticed here. One of them started as a security guard, believe it or not.",ar:"بالتأكيد. اثنان من مديرينا بدآ في منصبك. العمل الجاد يُلاحظ هنا. أحدهما بدأ كحارس أمن، صدق أو لا تصدق."},{s:0,t:"That's exactly what I wanted to hear. I like a place where effort pays off. Hard work should lead to profit for everyone, not just the boss.",ar:"هذا بالضبط ما أردت سماعه. أحب مكانًا يُكافأ فيه الجهد. يجب أن يؤدي العمل الجاد إلى ربح للجميع، وليس للمدير فقط."},{s:1,t:"Good attitude. Now, do you have any questions for me?",ar:"موقف جيد. الآن، هل لديك أي أسئلة لي؟"},{s:0,t:"Just one. What do you enjoy most about working here? Is the trade union active here? I believe in workers' rights.",ar:"سؤال واحد فقط. ما أكثر ما تستمتع به في العمل هنا؟ هل النقابة العمالية نشطة هنا؟ أؤمن بحقوق العمال."},{s:1,t:"The people, honestly. The team is friendly, and we help each other out. We even have a small gym for fitness — it's free for staff.",ar:"الناس، بصراحة. الفريق ودود، ونساعد بعضنا بعضًا. لدينا حتى صالة رياضية صغيرة للياقة — مجانية للموظفين."},{s:0,t:"That's important to me. A good team makes all the difference. A team that takes risks together grows together.",ar:"هذا مهم بالنسبة لي. الفريق الجيد يصنع كل الفرق. الفريق الذي يخاطر معًا ينمو معًا."},{s:1,t:"I couldn't agree more. Well, thank you for coming in today.",ar:"أوافقك تمامًا. حسنًا، شكرًا لحضورك اليوم."},{s:0,t:"Thank you for your time. I really hope I get the job. If I don't qualify this time, I'll try again next year.",ar:"شكرًا لوقتك. آمل حقًا أن أحصل على الوظيفة. إذا لم أكن مؤهلًا هذه المرة، سأحاول مجددًا العام المقبل."},{s:1,t:"We'll be in touch. Oh — and good luck. You did well today.",ar:"سنكون على اتصال. أوه — وحظًا سعيدًا. أبليت بلاءً حسنًا اليوم."},{s:0,t:"Thanks! That means a lot. Have a great day! I hope I don't end up unemployed for long — I need to work.",ar:"شكرًا! هذا يعني لي الكثير. أتمنى لك يومًا رائعًا! آمل ألا أبقى عاطلًا عن العمل طويلًا — أحتاج إلى العمل."},{s:1,t:"You too. Take care! The other candidates are competitive, but I think you can beat them.",ar:"وأنت أيضًا. اعتنِ بنفسك! المرشحون الآخرون منافسون، لكنني أظن أنك تستطيع التغلب عليهم."},{s:0,t:"Wait — one last thing. Should I send a thank-you email? My father decided to retire last year, and a retired teacher told him a thank-you note always helps.",ar:"انتظر — شيء أخير. هل يجب أن أرسل بريدًا للشكر؟ والدي قرر التقاعد العام الماضي، وقال له معلم متقاعد إن رسالة شكر تساعد دائمًا."},{s:1,t:"It never hurts. Short and polite is perfect.",ar:"لا يضر أبدًا. قصير ومهذب مثالي."},{s:0,t:"Got it. I'll send one tonight. Bye! And thanks again — I know the unemployment rate is high, so I appreciate the chance.",ar:"فهمت. سأرسل واحدًا الليلة. إلى اللقاء! وشكرًا مجددًا — أعلم أن معدل البطالة مرتفع، لذلك أقدّر الفرصة."},{s:1,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:5,topic:"education",topicAr:"التعليم والدراسة",topicEn:"Education & Study",topicDe:"Bildung und Studium",emoji:"🎓",title:"الدراسة والامتحانات",grammar:{id:"en-b1-reported-speech-advanced",title:"Reported speech",titleAr:"الكلام المنقول",covers:1},conv:{id:"en-stage5-b1",speakers:["Student (الطالب)","Teacher (المعلم)"],turns:[{s:0,t:"Excuse me, Mr. Adams. Can I ask you something about the exam? I'm worried about my grade this term.",ar:"عذرًا، أستاذ آدمز. هل يمكنني أن أسألك شيئًا عن الامتحان؟ أنا قلق بشأن درجتي هذا الفصل."},{s:1,t:"Of course. What do you want to know?",ar:"بالطبع. ماذا تريد أن تعرف؟"},{s:0,t:"Well, Sarah told me that the exam would be next week. Is that true?",ar:"حسنًا، أخبرتني سارة أن الامتحان سيكون الأسبوع المقبل. هل هذا صحيح؟"},{s:1,t:"She's right. It's on Tuesday morning, at nine o'clock. And remember, the grammar clause question is worth ten points.",ar:"إنها محقة. إنه صباح الثلاثاء، في التاسعة. وتذكر، سؤال جملة الوصل في القواعد يساوي عشر نقاط."},{s:0,t:"Tuesday? That's so soon! I haven't even started revising. My academic record is good, but this exam scares me.",ar:"الثلاثاء؟ هذا قريب جدًا! لم أبدأ المراجعة حتى. سجلي الأكاديمي جيد، لكن هذا الامتحان يخيفني."},{s:1,t:"You should've started earlier. You knew about this exam a month ago. Secondary school is harder than primary school — you know that.",ar:"كان يجب أن تبدأ مبكرًا. كنت تعرف عن هذا الامتحان منذ شهر. المدرسة الثانوية أصعب من الابتدائية — أنت تعرف ذلك."},{s:0,t:"I know, I know. I've been so busy with my other assignments. I had difficulty with the chemistry assignment.",ar:"أعلم، أعلم. كنت مشغولًا جدًا بواجباتي الأخرى. واجهت صعوبة في واجب الكيمياء."},{s:1,t:"I understand. But you need a plan. Have you made a study schedule? A scientific approach works best — short sessions, often.",ar:"أفهم. لكنك تحتاج إلى خطة. هل وضعت جدولًا للدراسة؟ النهج العلمي يعمل بشكل أفضل — جلسات قصيرة، وكثيرًا."},{s:0,t:"Not really. I just read my notes again and again. It doesn't work very well. I get confused easily when I only read.",ar:"ليس حقًا. أقرأ ملاحظاتي مرارًا وتكرارًا. لا ينجح ذلك جيدًا. أشعر بالارتباك بسهولة عندما أقرأ فقط."},{s:1,t:"That's because passive reading isn't enough. You need to test yourself. Have you done an analysis of your mistakes? Repeated mistakes show a pattern.",ar:"لأن القراءة السلبية لا تكفي. تحتاج إلى اختبار نفسك. هل قمت بتحليل لأخطائك؟ الأخطاء المتكررة تُظهر نمطًا."},{s:0,t:"Test myself? How? I don't have any practice questions. Can you examine my essay and tell me what's wrong?",ar:"أختبر نفسي؟ كيف؟ ليس لدي أي أسئلة تدريبية. هل يمكنك فحص مقالي وإخباري بما هو خطأ؟"},{s:1,t:"I can give you some. And try explaining the ideas out loud, as if you're teaching someone. You'll see a big improvement in a week.",ar:"يمكنني أن أعطيك بعضها. وحاول شرح الأفكار بصوت عالٍ، كما لو كنت تُعلّم شخصًا. سترى تحسنًا كبيرًا خلال أسبوع."},{s:0,t:"That sounds strange, but I'll try it. What topics will the exam cover? Can you define the main terms first?",ar:"هذا يبدو غريبًا، لكنني سأجربه. ما المواضيع التي سيغطيها الامتحان؟ هل يمكنك تعريف المصطلحات الرئيسية أولًا؟"},{s:1,t:"Three chapters: the history chapter, the literature chapter, and the science one. There's also a presentation about the history project.",ar:"ثلاثة فصول: فصل التاريخ، وفصل الأدب، وفصل العلوم. وهناك أيضًا عرض تقديمي عن مشروع التاريخ."},{s:0,t:"The literature chapter is the hardest for me. All those poems and theories... I can never revise them properly.",ar:"فصل الأدب هو الأصعب بالنسبة لي. كل تلك القصائد والنظريات... لا أستطيع مراجعتها بشكل صحيح أبدًا."},{s:1,t:"Don't panic. Focus on the main ideas, not every little detail. The definition of each term is in the glossary.",ar:"لا تفزع. ركز على الأفكار الرئيسية، وليس على كل التفاصيل الصغيرة. تعريف كل مصطلح موجود في المسرد."},{s:0,t:"Okay. And will there be an essay question? I need to summarize the whole chapter in one page — that's hard.",ar:"حسنًا. وهل سيكون هناك سؤال مقالي؟ أحتاج إلى تلخيص الفصل كله في صفحة واحدة — هذا صعب."},{s:1,t:"Yes, one essay. You'll have a choice of two topics.",ar:"نعم، مقال واحد. سيكون لديك خياران من المواضيع."},{s:0,t:"Good. I prefer essays to multiple-choice questions, actually. A summary at the end helps me organize my thoughts.",ar:"جيد. أفضل المقالات على أسئلة الاختيار من متعدد، في الحقيقة. ملخص في النهاية يساعدني على تنظيم أفكاري."},{s:1,t:"Interesting. Most students say the opposite. Why do you prefer essays?",ar:"مثير للاهتمام. معظم الطلاب يقولون العكس. لماذا تفضل المقالات؟"},{s:0,t:"Because I can explain what I think. In multiple-choice, one small mistake ruins everything. And cheating is impossible in an essay — you have to think.",ar:"لأنني أستطيع شرح ما أفكر فيه. في الاختيار من متعدد، خطأ صغير واحد يفسد كل شيء. والغش مستحيل في المقال — يجب أن تفكر."},{s:1,t:"Fair point. Just remember to organize your essay — introduction, main points, conclusion.",ar:"نقطة عادلة. فقط تذكر أن تنظم مقالك — مقدمة ونقاط رئيسية وخاتمة."},{s:0,t:"I'll try. By the way, my friend said that you were going to give extra classes. He also said the previous exam was really hard.",ar:"سأحاول. بالمناسبة، قال صديقي إنك ستعطي دروسًا إضافية. وقال أيضًا إن الامتحان السابق كان صعبًا حقًا."},{s:1,t:"He's right. I'm running a review session on Friday afternoon. You should come.",ar:"إنه محق. سأدير جلسة مراجعة بعد ظهر الجمعة. يجب أن تأتي."},{s:0,t:"I will! What time exactly? I was previously in the morning group, but I can come in the afternoon. Are you prepared for many questions? I have a lot.",ar:"سآتي! في أي وقت بالضبط؟ كنت سابقًا في مجموعة الصباح، لكن يمكنني الحضور بعد الظهر. هل أنت مستعد للعديد من الأسئلة؟ لدي الكثير."},{s:1,t:"Three o'clock, in room 12. Bring your textbook and your questions. The science chapter is complex, so bring your notes too.",ar:"الثالثة، في الغرفة 12. أحضر كتابك وأسئلتك. فصل العلوم معقد، لذا أحضر ملاحظاتك أيضًا."},{s:0,t:"Perfect. Oh, one more thing — I heard the principal is visiting our class tomorrow. The bell rings at eight, so don't be late.",ar:"ممتاز. أوه، شيء آخر — سمعت أن المدير سيزور صفنا غدًا. يرن الجرس في الثامنة، لذا لا تتأخر."},{s:1,t:"Yes, he is. Don't worry, just be yourself. And please, no phones.",ar:"نعم، سيزورنا. لا تقلق، كن على طبيعتك فقط. ومن فضلك، لا هواتف."},{s:0,t:"No phones? But what if—",ar:"لا هواتف؟ لكن ماذا لو—"},{s:1,t:"—No exceptions. The principal was very clear about that. He said students who cheat will be punished.",ar:"لا استثناءات. كان المدير واضحًا جدًا بشأن ذلك. قال إن الطلاب الذين يغشون سيُعاقبون."},{s:0,t:"All right, all right. I get it. I need to study more effectively, not just longer.",ar:"حسنًا، حسنًا. فهمت. أحتاج إلى الدراسة بشكل أكثر فعالية، وليس لفترة أطول فقط."},{s:1,t:"Good. Now, tell me honestly — how many hours a day do you study?",ar:"جيد. الآن، أخبرني بصراحة — كم ساعة تدرس في اليوم؟"},{s:0,t:"Um... maybe one hour? Sometimes less.",ar:"همم... ربما ساعة واحدة؟ وأحيانًا أقل."},{s:1,t:"That's not enough, and you know it. You need at least three hours this week. In conclusion, your plan needs more work.",ar:"هذا لا يكفي، وأنت تعرف ذلك. تحتاج إلى ثلاث ساعات على الأقل هذا الأسبوع. وفي الختام، خطتك تحتاج إلى مزيد من العمل."},{s:0,t:"Three hours? That's a lot. But okay, I'll do my best. I will graduate next year, and I want good grades. Graduating with good grades is my biggest achievement.",ar:"ثلاث ساعات؟ هذا كثير. لكن حسنًا، سأبذل قصارى جهدي. سأتخرج العام المقبل، وأريد درجات جيدة. التخرج بدرجات جيدة هو أكبر إنجاز لي."},{s:1,t:"I believe you can do it. You're a clever student when you concentrate.",ar:"أؤمن أنك تستطيع. أنت طالب ذكي عندما تركز."},{s:0,t:"Thanks, sir. That really means a lot to me. My parents worked hard to educate me, and I don't want to let them down.",ar:"شكرًا يا أستاذ. هذا يعني لي الكثير حقًا. عمل والداي بجد لتعليمي، ولا أريد أن أخذلهما."},{s:1,t:"You're welcome. Now go and start revising. No more excuses!",ar:"على الرحب. الآن اذهب وابدأ المراجعة. لا مزيد من الأعذار!"},{s:0,t:"Yes, sir! I'm going straight to the library. The science laboratory is open too — I might do an experiment there.",ar:"نعم يا أستاذ! سأذهب مباشرة إلى المكتبة. مختبر العلوم مفتوح أيضًا — قد أجري تجربة هناك."},{s:1,t:"Good. And remember — if you get stuck, come and ask. That's what I'm here for.",ar:"جيد. وتذكر — إذا علقت، تعال واسأل. هذا ما أنا هنا من أجله."},{s:0,t:"I will. Thanks again for your help! Your educational videos on the school channel really help too.",ar:"سأفعل. شكرًا مجددًا على مساعدتك! مقاطعك التعليمية على قناة المدرسة تساعد حقًا أيضًا."},{s:1,t:"Anytime. Good luck on Tuesday!",ar:"في أي وقت. حظًا سعيدًا يوم الثلاثاء!"},{s:0,t:"Thanks! I'll need it. If I pass, I'll be the first educated person in my family.",ar:"شكرًا! سأحتاج إليه. إذا نجحت، سأكون أول شخص متعلم في عائلتي."},{s:1,t:"You won't, if you study. Now go!",ar:"لن تحتاجه، إذا درست. الآن اذهب!"},{s:0,t:"Going, going! And sir — I drew a diagram of the water cycle for the science chapter. Can you check it?",ar:"ذاهب، ذاهب! وأستاذ — رسمت مخططًا لدورة الماء لفصل العلوم. هل يمكنك التحقق منه؟"}]}},{stage:6,topic:"technology",topicAr:"التكنولوجيا والإنترنت",topicEn:"Technology & Internet",topicDe:"Technologie und Internet",emoji:"💻",title:"الهواتف والإنترنت",grammar:{id:"en-b1-gerund-infinitive",title:"Gerund and infinitive",titleAr:"المصدر واسم الفعل",covers:1},conv:{id:"en-stage6-b1",speakers:["Tech Support (الدعم الفني)","User (المستخدم)"],turns:[{s:0,t:"Hello, tech support. How can I help you today? Please tell me your account number first.",ar:"مرحبًا، الدعم الفني. كيف يمكنني مساعدتك اليوم؟ من فضلك أخبرني برقم حسابك أولًا."},{s:1,t:"Hi. I'm having a problem with my laptop. It keeps freezing.",ar:"مرحبًا. لدي مشكلة في حاسوبي المحمول. يستمر في التجمد."},{s:0,t:"I'm sorry to hear that. When did this start happening? Did it start after the automatic update?",ar:"آسف لسماع ذلك. متى بدأ هذا يحدث؟ هل بدأ بعد التحديث التلقائي؟"},{s:1,t:"Yesterday, right after I installed the new update. Now it freezes every ten minutes.",ar:"أمس، مباشرة بعد تثبيت التحديث الجديد. الآن يتجمد كل عشر دقائق."},{s:0,t:"I see. Have you tried restarting it? The system updates automatically, so a restart usually fixes it.",ar:"أرى. هل جربت إعادة تشغيله؟ النظام يتحدث تلقائيًا، لذا فإن إعادة التشغيل تصلح الأمر عادة."},{s:1,t:"Of course! I've restarted it about five times already. It doesn't help.",ar:"بالطبع! أعدت تشغيله نحو خمس مرات بالفعل. لا يساعد ذلك."},{s:0,t:"Okay. Let's try something else. Can you click on the settings icon for me? The AI in this laptop is supposed to fix small problems itself. Artificial intelligence is amazing, isn't it?",ar:"حسنًا. لنجرب شيئًا آخر. هل يمكنك النقر على أيقونة الإعدادات من أجلي؟ من المفترض أن الذكاء الاصطناعي في هذا الحاسوب يصلح المشاكل الصغيرة بنفسه. الذكاء الاصطناعي مذهل، أليس كذلك؟"},{s:1,t:"Sure. Uh, I can't find it. Where exactly is it? Is it on the keyboard, or on the screen? What's the function of that button, anyway?",ar:"بالتأكيد. آه، لا أستطيع العثور عليها. أين هي بالضبط؟ هل هي على لوحة المفاتيح، أم على الشاشة؟ ما وظيفة ذلك الزر، على أي حال؟"},{s:0,t:"It's in the bottom left corner. The little gear symbol.",ar:"إنها في الزاوية السفلية اليسرى. رمز الترس الصغير."},{s:1,t:"Found it! Okay, I'm in settings. What now? Uh-huh, I see the storage section.",ar:"وجدتها! حسنًا، أنا في الإعدادات. ماذا الآن؟ أها، أرى قسم التخزين."},{s:0,t:"Now click on 'System', then 'Storage'. Tell me how much free space you have. You can also access your files from the cloud. Is this laptop reliable, by the way?",ar:"الآن انقر على 'النظام'، ثم 'التخزين'. أخبرني كم مساحة حرة لديك. يمكنك أيضًا الوصول إلى ملفاتك من السحابة. هل هذا الحاسوب موثوق، بالمناسبة؟"},{s:1,t:"It says... only 2 gigabytes free. Is that bad?",ar:"يقول... غيغابايتان فقط حرة. هل هذا سيئ؟"},{s:0,t:"Yeah, that's the problem. Your hard drive is almost full. That's why it freezes. And your charging cable is damaged — look at it. Is it covered by the warranty?",ar:"نعم، هذه هي المشكلة. قرصك الصلب ممتلئ تقريبًا. لهذا يتجمد. وكابل الشحن لديك تالف — انظر إليه. هل يغطيه الضمان؟"},{s:1,t:"Oh no. But I don't even know what's taking up all the space!",ar:"أوه لا. لكنني لا أعرف حتى ما الذي يشغل كل المساحة!"},{s:0,t:"Probably old videos and photos. And too many ads saved in the browser cache — they eat space too.",ar:"على الأرجح مقاطع فيديو وصور قديمة. والكثير من الإعلانات المحفوظة في ذاكرة المتصفح — إنها تستهلك المساحة أيضًا."},{s:1,t:"Back up? No, I never do that. I keep meaning to, but I forget. I know, I know — it's careless of me.",ar:"نسخ احتياطي؟ لا، لا أفعل ذلك أبدًا. أنوي دائمًا، لكنني أنسى. أعلم، أعلم — هذا إهمال مني."},{s:0,t:"You really should. If your laptop crashes, you could lose everything. Attach your important files to an email and send them to yourself.",ar:"يجب عليك فعلًا. إذا تعطل حاسوبك، قد تفقد كل شيء. أرفق ملفاتك المهمة ببريد وأرسلها إلى نفسك."},{s:1,t:"Don't scare me! Okay, so what do I do first?",ar:"لا تخيفني! حسنًا، ماذا أفعل أولًا؟"},{s:0,t:"First, let's delete the temporary files. Click on 'Clean up' — it's right there. Then we'll scan the whole system for viruses.",ar:"أولًا، لنحذف الملفات المؤقتة. انقر على 'تنظيف' — إنها هناك. ثم سنفحص النظام كله بحثًا عن الفيروسات."},{s:1,t:"Done. Wow, it freed up 5 gigabytes! That was easy.",ar:"تم. واو، حرر 5 غيغابايت! كان ذلك سهلًا."},{s:0,t:"Great. Now, do you use the cloud? Uploading your photos there would help a lot. I listen to a podcast about tech while I work, by the way.",ar:"رائع. الآن، هل تستخدم السحابة؟ رفع صورك هناك سيساعد كثيرًا. أستمع إلى بودكاست عن التقنية أثناء عملي، بالمناسبة."},{s:1,t:"The cloud? I'm not sure I trust it. What if someone hacks my account?",ar:"السحابة؟ لست متأكدًا أنني أثق بها. ماذا لو اخترق أحد حسابي؟"},{s:0,t:"That's a fair concern. But with a strong password and two-step verification, it's very safe. Use a PIN that's hard to guess, too.",ar:"هذا قلق عادل. لكن مع كلمة مرور قوية والتحقق بخطوتين، إنها آمنة جدًا. استخدم رقمًا سريًا يصعب تخمينه أيضًا."},{s:1,t:"Hmm. Maybe I'll try it. My phone's always running out of space too.",ar:"همم. ربما سأجربها. هاتفي أيضًا تنفد مساحته دائمًا."},{s:0,t:"Most people have the same problem. By the way, is your Wi-Fi working okay?",ar:"معظم الناس لديهم المشكلة نفسها. بالمناسبة، هل يعمل الواي فاي لديك بشكل جيد؟"},{s:1,t:"Actually, no. The connection keeps dropping in my bedroom. It's so annoying.",ar:"في الحقيقة، لا. الاتصال ينقطع باستمرار في غرفة نومي. إنه مزعج جدًا."},{s:0,t:"That's probably because the router is too far away. Have you tried moving closer? The net is weak through thick walls.",ar:"هذا على الأرجح لأن جهاز التوجيه بعيد جدًا. هل جربت الاقتراب؟ الشبكة ضعيفة عبر الجدران السميكة."},{s:1,t:"I can't move my bedroom! Isn't there another solution? I watch a lot of commercial TV online, and it keeps buffering.",ar:"لا أستطيع نقل غرفة نومي! أليس هناك حل آخر؟ أشاهد الكثير من التلفاز التجاري عبر الإنترنت، ويستمر في التوقف."},{s:0,t:"Ha! Fair enough. You could get a Wi-Fi extender. They're cheap and easy to set up. The latest version even has a small screen.",ar:"ها! عادل بما يكفي. يمكنك شراء موسّع واي فاي. إنها رخيصة وسهلة التركيب. أحدث إصدار لديه شاشة صغيرة حتى."},{s:1,t:"An extender? I've never heard of that. How does it work?",ar:"موسّع؟ لم أسمع به من قبل. كيف يعمل؟"},{s:0,t:"You plug it in halfway between the router and your room, and it boosts the signal. A robot vacuum uses the same idea — it finds the strongest signal.",ar:"توصله في منتصف الطريق بين جهاز التوجيه وغرفتك، فيقوي الإشارة. المكنسة الروبوتية تستخدم الفكرة نفسها — تجد أقوى إشارة."},{s:1,t:"That sounds perfect. I'll order one tonight. Anything else I should know? My alarm never works on this phone, by the way.",ar:"هذا يبدو مثاليًا. سأطلب واحدًا الليلة. أي شيء آخر يجب أن أعرفه؟ المنبه لا يعمل أبدًا على هذا الهاتف، بالمناسبة."},{s:0,t:"Just one thing: don't ignore updates. They fix security problems. The new software version is much faster.",ar:"شيء واحد فقط: لا تتجاهل التحديثات. إنها تصلح مشاكل الأمان. إصدار البرنامج الجديد أسرع بكثير."},{s:1,t:"But updates always break something! Last time, my favorite app stopped working. And the printing stopped too — I couldn't print anything.",ar:"لكن التحديثات تكسر شيئًا دائمًا! في المرة الماضية، توقف تطبيقي المفضل عن العمل. وتوقفت الطباعة أيضًا — لم أستطع طباعة أي شيء."},{s:0,t:"I know, it's frustrating. But skipping them is riskier. Trust me on this.",ar:"أعلم، إنه محبط. لكن تخطيها أخطر. ثق بي في هذا."},{s:1,t:"Okay, okay. You win. I'll keep everything updated.",ar:"حسنًا، حسنًا. لقد فزت. سأبقي كل شيء محدثًا."},{s:0,t:"Good. Now restart your laptop once more, and it should run smoothly. You're gonna love how fast it feels.",ar:"جيد. الآن أعد تشغيل حاسوبك مرة أخرى، وسيعمل بسلاسة. ستحب مدى سرعته."},{s:1,t:"Restarting... Okay, it's back on. And it feels faster already!",ar:"أعيد التشغيل... حسنًا، عاد للعمل. ويبدو أسرع بالفعل!"},{s:0,t:"Excellent! Is there anything else I can help you with?",ar:"ممتاز! هل هناك أي شيء آخر يمكنني مساعدتك فيه؟"},{s:1,t:"No, that's everything. You've been really helpful. Thanks a lot!",ar:"لا، هذا كل شيء. كنت مفيدًا جدًا. شكرًا جزيلًا!"},{s:0,t:"You're welcome. Have a great day, and don't forget to back up your files!",ar:"على الرحب. أتمنى لك يومًا رائعًا، ولا تنسَ نسخ ملفاتك احتياطيًا!"},{s:1,t:"I won't! Bye!",ar:"لن أنسى! إلى اللقاء!"},{s:0,t:"Bye!",ar:"إلى اللقاء!"}]}},{stage:7,topic:"environment",topicAr:"البيئة والطبيعة",topicEn:"Environment & Nature",topicDe:"Umwelt und Natur",emoji:"🌳",title:"كوكبنا في خطر",grammar:{id:"en-b1-used-to-would",title:"Used to / would",titleAr:"اعتدت على / would",covers:1},conv:{id:"en-stage7-b1",speakers:["Environmental Activist (الناشط البيئي)","Engineer (المهندس)"],turns:[{s:0,t:"Thanks for coming to the meeting. I know you're busy, so I'll keep it short. Our environmental group meets every month. I'm the organizer, by the way.",ar:"شكرًا لحضورك الاجتماع. أعلم أنك مشغول، لذا سأختصر. مجموعتنا البيئية تجتمع كل شهر. أنا المنظم، بالمناسبة."},{s:1,t:"No problem. I've been meaning to learn more about your project anyway. I expected a small group, not twenty people!",ar:"لا مشكلة. كنت أنوي تعلم المزيد عن مشروعك على أي حال. توقعت مجموعة صغيرة، وليس عشرين شخصًا!"},{s:0,t:"Great. So, we're building a community garden on the empty land behind the school. We need every resource we can get — tools, seeds, water.",ar:"رائع. إذن، نحن نبني حديقة مجتمعية على الأرض الفارغة خلف المدرسة. نحتاج إلى كل مورد يمكننا الحصول عليه — أدوات وبذور وماء."},{s:1,t:"A garden? That sounds nice, but is it really worth the effort? The signs indicate that the soil is healthy, at least.",ar:"حديقة؟ هذا يبدو جميلًا، لكن هل يستحق الجهد حقًا؟ العلامات تشير إلى أن التربة صحية، على الأقل."},{s:0,t:"Absolutely. The soil there is rich, and kids used to play there years ago. There was even a bee colony in the old tree.",ar:"بالتأكيد. التربة هناك غنية، وكان الأطفال يلعبون هناك منذ سنوات. كان هناك حتى مستعمرة نحل في الشجرة القديمة."},{s:1,t:"Used to? What happened to the place?",ar:"كانوا يلعبون؟ ماذا حدث للمكان؟"},{s:0,t:"People started dumping waste there. Old tires, broken furniture, you name it. The dust was terrible in summer.",ar:"بدأ الناس يرمون النفايات هناك. إطارات قديمة وأثاث مكسور، وما شئت. كان الغبار فظيعًا في الصيف."},{s:1,t:"That's terrible. I used to walk past it every day, and it just got worse and worse.",ar:"هذا فظيع. كنت أمر بجانبه كل يوم، وكان يزداد سوءًا وسوءًا."},{s:0,t:"Exactly. So we decided to do something about it instead of just complaining.",ar:"بالضبط. لذلك قررنا أن نفعل شيئًا حيال ذلك بدلًا من مجرد الشكوى."},{s:1,t:"I respect that. But honestly, can a small garden really make a difference? It's such a tiny piece of land.",ar:"أحترم ذلك. لكن بصراحة، هل يمكن لحديقة صغيرة أن تحدث فرقًا حقًا؟ إنها قطعة أرض صغيرة جدًا."},{s:0,t:"It can. We already have twenty volunteers. We plant seeds, we water, we learn. A new branch of the group started in the next town too. Get involved — it's fun!",ar:"يمكنها. لدينا بالفعل عشرون متطوعًا. نزرع البذور ونسقي ونتعلم. بدأ فرع جديد للمجموعة في المدينة المجاورة أيضًا. شارك — إنه ممتع!"},{s:1,t:"Twenty volunteers? That's impressive. What do you grow there? We grow grain too — wheat and corn for the school kitchen.",ar:"عشرون متطوعًا؟ هذا مثير للإعجاب. ماذا تزرعون هناك؟ نزرع الحبوب أيضًا — قمح وذرة لمطبخ المدرسة."},{s:0,t:"Vegetables, mostly. Tomatoes, corn, beans. And we're planting trees along the fence, and we'll collect every fallen leaf for compost.",ar:"خضروات، في الغالب. طماطم وذرة وفاصوليا. ونزرع أشجارًا على طول السياج، وسنجمع كل ورقة ساقطة للسماد."},{s:1,t:"Trees are a good idea. They clean the air and give shade in summer. They also help the whole planet survive. Indoor plants help too, in a small way.",ar:"الأشجار فكرة جيدة. تنظف الهواء وتعطي ظلًا في الصيف. كما أنها تساعد الكوكب كله على البقاء. النباتات الداخلية تساعد أيضًا، بطريقة صغيرة."},{s:0,t:"Right. And we're using renewable energy for the water pump — a small solar panel. It's a global solution, really — everyone can do it.",ar:"صحيح. ونستخدم الطاقة المتجددة لمضخة المياه — لوح شمسي صغير. إنه حل عالمي حقًا — يمكن للجميع فعله."},{s:1,t:"Solar power? That's clever. I thought that stuff was only for rich people.",ar:"طاقة شمسية؟ هذا ذكي. ظننت أن هذه الأشياء للأغنياء فقط."},{s:0,t:"Not anymore. Prices have dropped a lot. If every house had one panel, we'd save a ton of energy. The heating bill would drop too.",ar:"ليس بعد الآن. انخفضت الأسعار كثيرًا. لو كان لكل بيت لوح واحد، لوفرنا الكثير من الطاقة. وستنخفض فاتورة التدفئة أيضًا."},{s:1,t:"Maybe. But what about the bigger problems — floods, hurricanes, earthquakes? They hit heavily populated areas hardest.",ar:"ربما. لكن ماذا عن المشاكل الأكبر — الفيضانات والأعاصير والزلازل؟ إنها تضرب المناطق المكتظة بالسكان بشدة."},{s:0,t:"Those are getting worse because of climate change. We can't stop them alone, but we can prepare. Future generations depend on what we do now.",ar:"إنها تزداد سوءًا بسبب تغير المناخ. لا نستطيع إيقافها وحدنا، لكن يمكننا الاستعداد. الأجيال القادمة تعتمد على ما نفعله الآن."},{s:1,t:"True. Last year's flood damaged half the shops on Main Street.",ar:"صحيح. فيضان العام الماضي ألحق الضرر بنصف متاجر الشارع الرئيسي."},{s:0,t:"I remember. My cousin's shop was under a meter of water. Mud everywhere. The force of the water broke the doors.",ar:"أتذكر. متجر ابن عمي كان تحت متر من الماء. طين في كل مكان. قوة الماء كسرت الأبواب."},{s:1,t:"Ugh, that's awful. So what else can ordinary people do? I want to do something practical, not just talk.",ar:"أوه، هذا فظيع. إذن ماذا يمكن للناس العاديين أن يفعلوا أيضًا؟ أريد أن أفعل شيئًا عمليًا، وليس مجرد الكلام."},{s:0,t:"Lots of things. Use less plastic, walk instead of driving, save water. We can't go backward — we have to move forward.",ar:"أشياء كثيرة. استخدم بلاستيكًا أقل، وامشِ بدلًا من القيادة، ووفّر الماء. لا يمكننا العودة إلى الوراء — يجب أن نتقدم."},{s:1,t:"I already walk to work. But plastic is everywhere — it's almost impossible to avoid. Clean water is essential for everyone, and we're wasting it.",ar:"أمشي إلى العمل بالفعل. لكن البلاستيك في كل مكان — يكاد يكون من المستحيل تجنبه. الماء النظيف ضروري للجميع، ونحن نهدره."},{s:0,t:"I know. That's why we need better laws, not just good habits. We need to expand the garden project to every school in the city.",ar:"أعلم. لهذا نحتاج إلى قوانين أفضل، وليس عادات جيدة فقط. نحتاج إلى توسيع مشروع الحديقة ليشمل كل مدرسة في المدينة."},{s:1,t:"Laws? Good luck with that. Politicians promise everything and do nothing. They announce big plans before every election.",ar:"قوانين؟ حظًا سعيدًا في ذلك. السياسيون يعدون بكل شيء ولا يفعلون شيئًا. يعلنون عن خطط كبيرة قبل كل انتخابات."},{s:0,t:"Some do nothing, sure. But if we vote and speak up, they have to listen. The announcement last week was actually good news.",ar:"بعضهم لا يفعل شيئًا، بالتأكيد. لكن إذا صوتنا وتحدثنا، يجب أن يستمعوا. الإعلان الأسبوع الماضي كان خبرًا جيدًا في الحقيقة."},{s:1,t:"Maybe you're right. I used to think one person couldn't change anything. I was wrong — indeed, small actions matter.",ar:"ربما أنت محق. كنت أظن أن شخصًا واحدًا لا يستطيع تغيير أي شيء. كنت مخطئًا — في الحقيقة، الأفعال الصغيرة مهمة."},{s:0,t:"And now?",ar:"والآن؟"},{s:1,t:"Now I'm not so sure. Your garden changed my mind a little. It had a real impact on me.",ar:"الآن لست متأكدًا. حديقتك غيّرت رأيي قليلًا. كان لها تأثير حقيقي عليّ."},{s:0,t:"That's the best compliment I've heard all week! So, will you join us on Saturday? You could assist with the planting — you know about soil. You can also donate some money, if you like.",ar:"هذا أفضل مجاملة سمعتها طوال الأسبوع! إذن، هل ستنضم إلينا يوم السبت؟ يمكنك المساعدة في الزراعة — أنت تعرف عن التربة. ويمكنك أيضًا التبرع ببعض المال، إذا أردت."},{s:1,t:"Saturday? I was planning to fix my garage, but... yeah, I'll come. My garage ceiling is leaking anyway — it can wait.",ar:"السبت؟ كنت أخطط لإصلاح مرآبي، لكن... نعم، سآتي. سقف مرآبي يتسرب على أي حال — يمكنه الانتظار."},{s:0,t:"Brilliant! Bring gloves if you have them. And old clothes — you'll get dirty. We even have a chain saw for the big branches.",ar:"رائع! أحضر قفازات إذا كانت لديك. وملابس قديمة — ستتسخ. لدينا حتى منشار جنزيري للأغصان الكبيرة."},{s:1,t:"Dirty? I don't mind dirt. I grew up on a farm, remember? We used to bury vegetable waste to make compost.",ar:"متسخ؟ لا أمانع التراب. نشأت في مزرعة، تذكر؟ كنا ندفن نفايات الخضروات لصنع السماد."},{s:0,t:"Oh, that's right! You'd know a thing or two about soil, then. Don't be frightened by the mess — it's part of the fun.",ar:"أوه، صحيح! إذن أنت تعرف شيئًا أو اثنين عن التربة. لا تخف من الفوضى — إنها جزء من المتعة."},{s:1,t:"A thing or two, yeah. My dad would plant everything by hand.",ar:"شيئًا أو اثنين، نعم. كان والدي يزرع كل شيء بيده."},{s:0,t:"Then we definitely need you. Nine o'clock, behind the school. Don't be late!",ar:"إذن نحن بحاجة إليك بالتأكيد. التاسعة، خلف المدرسة. لا تتأخر!"},{s:1,t:"I won't. See you there. And hey — thanks for not giving up on this place.",ar:"لن أتأخر. أراك هناك. واسمع — شكرًا لعدم استسلامك بشأن هذا المكان."},{s:0,t:"Thanks. See you Saturday!",ar:"شكرًا. أراك يوم السبت!"},{s:1,t:"See you!",ar:"أراك!"}]}},{stage:8,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"الصحة أولًا",grammar:{id:"en-b1-present-perfect-continuous",title:"Present perfect continuous: have been + -ing",titleAr:"المضارع التام المستمر: have been + ing",covers:1},conv:{id:"en-stage8-b1",speakers:["Patient (المريض)","Doctor (الطبيب)"],turns:[{s:0,t:"Good morning, doctor. Thanks for fitting me in today.",ar:"صباح الخير، دكتور. شكرًا لإدخالي اليوم."},{s:1,t:"Good morning. What's bothering you?",ar:"صباح الخير. ما الذي يزعجك؟"},{s:0,t:"Well, I've had a sore throat for three days, and I feel terrible. It hurts every time I breathe.",ar:"حسنًا، حلقي يؤلمني منذ ثلاثة أيام، وأشعر بشعور سيئ. يؤلمني في كل مرة أتنفس فيها."},{s:1,t:"I see. Do you have a fever as well? You look a bit pale, to be honest.",ar:"أرى. هل لديك حمى أيضًا؟ تبدو شاحبًا بعض الشيء، بصراحة."},{s:0,t:"A little, I think. And my muscles ache, especially my back and shoulders. My chest feels tight too.",ar:"قليلًا، أظن. وعضلاتي تؤلمني، خاصة ظهري وكتفيّ. وأشعر بضيق في صدري أيضًا."},{s:1,t:"Any coughing? Or trouble breathing?",ar:"أي سعال؟ أو صعوبة في التنفس؟"},{s:0,t:"Some coughing at night. It keeps me awake, to be honest. My lips are dry as well.",ar:"بعض السعال ليلًا. يبقيني مستيقظًا، بصراحة. شفتاي جافتان أيضًا."},{s:1,t:"Okay. Open your mouth and say 'ah', please.",ar:"حسنًا. افتح فمك وقل 'آه'، من فضلك."},{s:0,t:"Ahhh.",ar:"آههه."},{s:1,t:"Your throat is red and swollen. It's probably a virus, not bacteria. Can you stick out your tongue, please?",ar:"حلقك أحمر ومتورم. إنه على الأرجح فيروس، وليس بكتيريا. هل يمكنك إخراج لسانك، من فضلك؟"},{s:0,t:"A virus? So antibiotics won't help?",ar:"فيروس؟ إذن المضادات الحيوية لن تساعد؟"},{s:1,t:"That's right. If you rest and drink plenty of fluids, you'll feel better in a few days.",ar:"صحيح. إذا استرحت وشربت الكثير من السوائل، ستشعر بتحسن في غضون أيام قليلة."},{s:0,t:"Rest? I can't rest! I have a big project at work this week. I even hurt my toe rushing to the office.",ar:"راحة؟ لا أستطيع الراحة! لدي مشروع كبير في العمل هذا الأسبوع. حتى أنني آذيت إصبع قدمي وأنا أسرع إلى المكتب."},{s:1,t:"I understand, but if you keep pushing yourself, you'll only get worse. You'll suffer for weeks instead of days.",ar:"أفهم، لكن إذا واصلت الضغط على نفسك، ستزداد سوءًا فقط. ستعاني لأسابيع بدلًا من أيام."},{s:0,t:"Hmm. You're probably right. I haven't slept properly in weeks.",ar:"همم. أنت محق على الأرجح. لم أنم جيدًا منذ أسابيع."},{s:1,t:"That's part of the problem. Your body needs sleep to fight illness. A relaxing evening routine would help a lot. Lie down early and lay your phone aside — that's a sensible start.",ar:"هذا جزء من المشكلة. جسمك يحتاج إلى النوم لمحاربة المرض. روتين مسائي مريح سيساعد كثيرًا. استلقِ مبكرًا وضع هاتفك جانبًا — هذه بداية معقولة."},{s:0,t:"I know. I've been working late every night. It's a bad habit.",ar:"أعلم. كنت أعمل حتى وقت متأخر كل ليلة. إنها عادة سيئة."},{s:1,t:"Well, this is your body's way of saying 'slow down.' Listen to it. Your mental health matters as much as your body.",ar:"حسنًا، هذه طريقة جسمك لقول 'تمهّل'. استمع إليه. صحتك النفسية مهمة بقدر جسمك."},{s:0,t:"Okay, okay. What medicine should I take? Is there a treatment for the cough, or just for the fever?",ar:"حسنًا، حسنًا. ما الدواء الذي يجب أن آخذه؟ هل يوجد علاج للسعال، أم للحمى فقط؟"},{s:1,t:"I'll give you something for the pain and the fever. Take one tablet every six hours. No needles, don't worry!",ar:"سأعطيك شيئًا للألم والحمى. خذ قرصًا واحدًا كل ست ساعات. لا إبر، لا تقلق!"},{s:0,t:"And the cough? It's really annoying.",ar:"والسعال؟ إنه مزعج حقًا."},{s:1,t:"Warm tea with honey helps. And avoid cold drinks for a few days. Treat yourself kindly — rest is medicine too.",ar:"الشاي الدافئ مع العسل يساعد. وتجنب المشروبات الباردة لبضعة أيام. عامل نفسك بلطف — الراحة دواء أيضًا."},{s:0,t:"Honey in tea — my grandmother used to say the same thing!",ar:"العسل في الشاي — جدتي كانت تقول الشيء نفسه!"},{s:1,t:"Grandmothers are often right. Now, do you smoke? And do you eat enough iron — red meat, beans, spinach?",ar:"الجدات غالبًا على حق. الآن، هل تدخن؟ وهل تأكل ما يكفي من الحديد — لحم أحمر وفاصوليا وسبانخ؟"},{s:0,t:"No, I quit two years ago. Best decision I ever made.",ar:"لا، أقلعت منذ سنتين. أفضل قرار اتخذته في حياتي."},{s:1,t:"Excellent! That helps a lot. Do you exercise regularly? Is the back pain painful when you bend over?",ar:"ممتاز! هذا يساعد كثيرًا. هل تمارس الرياضة بانتظام؟ هل ألم الظهر مؤلم عندما تنحني؟"},{s:0,t:"Not really. I sit at a desk all day. My back is killing me. I injured it lifting a heavy box last year.",ar:"ليس حقًا. أجلس على مكتب طوال اليوم. ظهري يقتلني. أصبت به وأنا أرفع صندوقًا ثقيلًا العام الماضي."},{s:1,t:"That's common. If you walk for thirty minutes a day, your back will thank you. Just watch out for traffic — safety first!",ar:"هذا شائع. إذا مشيت ثلاثين دقيقة يوميًا، سيشكرك ظهرك. فقط انتبه للمرور — السلامة أولًا!"},{s:0,t:"Thirty minutes? I can do that. I could walk to work instead of driving.",ar:"ثلاثون دقيقة؟ أستطيع فعل ذلك. يمكنني المشي إلى العمل بدلًا من القيادة."},{s:1,t:"Perfect. Small changes make a big difference. And eat more vegetables. Tell me if the pain becomes sharp — that would be a warning sign.",ar:"مثالي. التغييرات الصغيرة تصنع فرقًا كبيرًا. وكُلْ المزيد من الخضروات. أخبرني إذا أصبح الألم حادًا — سيكون ذلك علامة تحذير."},{s:0,t:"Vegetables... my wife has been telling me the same thing for years. She says my cooking is poisonous!",ar:"الخضروات... زوجتي تخبرني بالشيء نفسه منذ سنوات. تقول إن طبخي سام!"},{s:1,t:"Listen to your wife! Now, I need to check your blood pressure. Roll up your sleeve. I need to remind you to come back in two weeks.",ar:"استمع إلى زوجتك! الآن، أحتاج إلى فحص ضغط دمك. ارفع كمك. أحتاج إلى تذكيرك بالعودة بعد أسبوعين."},{s:0,t:"Sure. Is it high? I've been worried about that.",ar:"بالتأكيد. هل هو مرتفع؟ كنت قلقًا بشأن ذلك."},{s:1,t:"It's a little high, but nothing serious. Less salt and less stress will help. If you ever feel chest pain, that's an emergency — call us immediately.",ar:"إنه مرتفع قليلًا، لكن لا شيء خطير. ملح أقل وتوتر أقل سيساعدان. إذا شعرت بألم في الصدر يومًا، فهذه حالة طارئة — اتصل بنا فورًا."},{s:0,t:"Less stress? Easier said than done, doctor. Stress is like a slow poison, isn't it?",ar:"توتر أقل؟ أسهل قولًا من فعلًا، دكتور. التوتر مثل سم بطيء، أليس كذلك؟"},{s:1,t:"I know. But try. Even ten minutes of quiet time a day helps your mind relax.",ar:"أعلم. لكن حاول. حتى عشر دقائق من الهدوء يوميًا تساعد عقلك على الاسترخاء."},{s:0,t:"Ten minutes of quiet... I can try that. Maybe in the morning, before work.",ar:"عشر دقائق من الهدوء... يمكنني تجربة ذلك. ربما في الصباح، قبل العمل."},{s:1,t:"Good plan. Now, if the fever gets worse, or if you have trouble breathing, come back immediately.",ar:"خطة جيدة. الآن، إذا ساءت الحمى، أو واجهت صعوبة في التنفس، عُد فورًا."},{s:0,t:"I will. How long before I feel normal again?",ar:"سأفعل. كم يستغرق الأمر قبل أن أشعر بأنني طبيعي مجددًا؟"},{s:1,t:"Usually four or five days. Take the medicine, rest, and drink lots of water.",ar:"عادة أربعة أو خمسة أيام. خذ الدواء واسترح واشرب الكثير من الماء."},{s:0,t:"Got it. Thanks, doctor. You've been really helpful.",ar:"فهمت. شكرًا، دكتور. كنت مفيدًا جدًا."},{s:1,t:"That's my job. Take care of yourself — and tell your wife I said hello!",ar:"هذا عملي. اعتنِ بنفسك — وأخبر زوجتك أنني أرسل تحياتي!"},{s:0,t:"I will. Goodbye!",ar:"سأفعل. إلى اللقاء!"},{s:1,t:"Goodbye! Get some rest!",ar:"إلى اللقاء! خذ بعض الراحة!"}]}},{stage:9,topic:"news",topicAr:"الأخبار والأحداث الجارية",topicEn:"News & Current Events",topicDe:"Nachrichten und Aktuelles",emoji:"📰",title:"الأخبار اليوم",grammar:{id:"en-b1-passive-tenses",title:"Passive voice: present, past and future",titleAr:"المبني للمجهول: الحاضر والماضي والمستقبل",covers:1},conv:{id:"en-stage9-b1",speakers:["News Anchor (مذيع الأخبار)","Reporter (المراسل)"],turns:[{s:0,t:"Good evening. Welcome to the news. Tonight's headline story is the election — and we have live results.",ar:"مساء الخير. أهلًا بكم في الأخبار. قصة الليلة الرئيسية هي الانتخابات — ولدينا نتائج مباشرة."},{s:1,t:"Thanks. The votes have been counted, and the results are finally in. The campaign lasted six long months.",ar:"شكرًا. تم فرز الأصوات، والنتائج وصلت أخيرًا. استمرت الحملة ستة أشهر طويلة."},{s:0,t:"So, who won? The whole country has been waiting for this. The result will affect the economy for years.",ar:"إذن، من فاز؟ البلد كله كان ينتظر هذا. النتيجة ستؤثر على الاقتصاد لسنوات."},{s:1,t:"It's close — really close. The current leader is ahead by just two percent. The political parties are waiting nervously.",ar:"إنها متقاربة — متقاربة جدًا. الزعيم الحالي متقدم بنسبة 2% فقط. الأحزاب السياسية تنتظر بتوتر."},{s:0,t:"Two percent? That's incredibly close. What happens now? Politics is never boring in this country.",ar:"2%؟ هذا متقارب بشكل لا يصدق. ماذا يحدث الآن؟ السياسة ليست مملة أبدًا في هذا البلد."},{s:1,t:"The other candidate has asked for a recount. He claims there were mistakes in three districts. Our editor is checking the numbers right now.",ar:"المرشح الآخر طلب إعادة فرز. يدعي وجود أخطاء في ثلاث مناطق. محررنا يتحقق من الأرقام الآن."},{s:0,t:"A recount could take days. People want answers now. The legal team is already preparing documents.",ar:"إعادة الفرز قد تستغرق أيامًا. الناس يريدون إجابات الآن. الفريق القانوني يجهز المستندات بالفعل."},{s:1,t:"I know. But the officials say they must follow the law, step by step. The economic impact of a delay could be serious.",ar:"أعلم. لكن المسؤولين يقولون إنهم يجب أن يتبعوا القانون، خطوة بخطوة. التأثير الاقتصادي للتأخير قد يكون خطيرًا."},{s:0,t:"Let's move on. What's happening with the protest downtown? The issue has divided the whole city.",ar:"لننتقل. ماذا يحدث مع الاحتجاج وسط المدينة؟ القضية قسمت المدينة كلها."},{s:1,t:"Hundreds of people gathered this morning. They're protesting against the new tax law. One victim of the tax rise spoke to our reporter. Poverty was the main topic of the speeches.",ar:"تجمع مئات الأشخاص هذا الصباح. يحتجون على قانون الضرائب الجديد. تحدث أحد ضحايا زيادة الضرائب إلى مراسلنا. كان الفقر الموضوع الرئيسي للخطب."},{s:0,t:"Was it peaceful? I heard there was fighting near the square.",ar:"هل كان سلميًا؟ سمعت أن هناك قتالًا قرب الساحة."},{s:1,t:"Mostly, yes. But later, a small group blocked the highway, and the police arrested twelve people. It turned violent for a few minutes. A drunk driver caused the first crash, actually.",ar:"في الغالب، نعم. لكن لاحقًا، أغلقت مجموعة صغيرة الطريق السريع، واعتقلت الشرطة اثني عشر شخصًا. تحول الأمر إلى عنف لبضع دقائق. تسبب سائق مخمور في الحادث الأول، في الحقيقة."},{s:0,t:"Twelve arrests. That's serious. What did the mayor say? Can you confirm the number — twelve, not twenty?",ar:"اثنا عشر اعتقالًا. هذا خطير. ماذا قال العمدة؟ هل يمكنك تأكيد العدد — اثنا عشر، وليس عشرين؟"},{s:1,t:"He said everyone has the right to protest, but blocking roads is illegal. The federal government agrees with him, by the way.",ar:"قال إن للجميع الحق في الاحتجاج، لكن إغلاق الطرق غير قانوني. الحكومة الفيدرالية توافق معه، بالمناسبة."},{s:0,t:"Fair enough. Now, the big story — the explosion at the factory yesterday. A bomb squad was called to the scene.",ar:"عادل بما يكفي. الآن، القصة الكبيرة — الانفجار في المصنع أمس. تم استدعاء فريق المتفجرات إلى الموقع."},{s:1,t:"Yes. The explosion happened at six in the morning. Three workers were injured. Experts say a gas tank could explode again if it's not removed.",ar:"نعم. حدث الانفجار في السادسة صباحًا. أصيب ثلاثة عمال. يقول الخبراء إن خزان غاز قد ينفجر مجددًا إذا لم يُزال."},{s:0,t:"Three injured. Are they okay?",ar:"ثلاثة مصابين. هل هم بخير؟"},{s:1,t:"Two are in a stable condition. One is still in the hospital, but doctors say he'll recover.",ar:"اثنان في حالة مستقرة. وواحد ما زال في المستشفى، لكن الأطباء يقولون إنه سيتعافى."},{s:0,t:"Good news, at least. What caused the explosion? The police will investigate the factory tomorrow. They think a gas pipe had been leaking for weeks.",ar:"أخبار جيدة، على الأقل. ما سبب الانفجار؟ ستقوم الشرطة بالتحقيق في المصنع غدًا. يظنون أن أنبوب غاز كان يتسرب منذ أسابيع."},{s:1,t:"Investigators think a gas pipe had been leaking for weeks. Nobody had checked it.",ar:"يظن المحققون أن أنبوب غاز كان يتسرب منذ أسابيع. لم يفحصه أحد."},{s:0,t:"That's shocking. The company should've checked it. Who's responsible? The punishment could be huge — a massive fine.",ar:"هذا صادم. كان يجب على الشركة فحصه. من المسؤول؟ قد تكون العقوبة ضخمة — غرامة هائلة."},{s:1,t:"That's what the police are investigating now. The factory manager has already been questioned. He could face a murder charge if a worker dies.",ar:"هذا ما تحقق فيه الشرطة الآن. تم استجواب مدير المصنع بالفعل. قد يواجه تهمة قتل إذا مات عامل."},{s:0,t:"We'll follow that story. Next — the court case everyone's talking about. The battle in court is expected to last weeks.",ar:"سنتابع تلك القصة. التالي — قضية المحكمة التي يتحدث عنها الجميع. من المتوقع أن تستمر المعركة في المحكمة أسابيع."},{s:1,t:"Right. The trial of the man accused of robbery started today. The prisoner arrived at court under heavy guard.",ar:"صحيح. بدأت اليوم محاكمة الرجل المتهم بالسرقة. وصل السجين إلى المحكمة تحت حراسة مشددة."},{s:0,t:"And the judge said what, exactly? The police found a weapon in the man's car, but his lawyer says it wasn't his.",ar:"وماذا قال القاضي بالضبط؟ وجدت الشرطة سلاحًا في سيارة الرجل، لكن محاميه يقول إنه ليس له."},{s:1,t:"He warned the press to be careful. The man is innocent until proven guilty, he said.",ar:"حذّر الصحافة وطلب منها توخي الحذر. الرجل بريء حتى تثبت إدانته، كما قال."},{s:0,t:"Of course. That's how the law works. How long will the trial last? A helicopter circled the court all morning — the press is everywhere.",ar:"بالطبع. هكذا يعمل القانون. كم ستستغرق المحاكمة؟ حلقت مروحية فوق المحكمة طوال الصباح — الصحافة في كل مكان."},{s:1,t:"Probably two weeks. The lawyers will present their evidence on Monday. The case involves the illegal import of goods, actually.",ar:"على الأرجح أسبوعان. سيقدم المحامون أدلتهم يوم الاثنين. القضية تتعلق بالاستيراد غير القانوني للبضائع، في الحقيقة."},{s:0,t:"Okay. Let's finish with some lighter news. The football championship? Our host city is ready for the final.",ar:"حسنًا. لننهِ ببعض الأخبار الخفيفة. بطولة كرة القدم؟ مدينتنا المضيفة جاهزة للنهائي."},{s:1,t:"Yes! Our team won last night, three to one. The captain scored twice. The whole nation celebrated. We're the champion team this year!",ar:"نعم! فاز فريقنا الليلة الماضية، ثلاثة لواحد. سجل القائد هدفين. احتفلت الأمة كلها. نحن الفريق البطل هذا العام!"},{s:0,t:"Three to one! I watched the second half. The crowd went crazy. Fans waved flags all night long.",ar:"ثلاثة لواحد! شاهدت الشوط الثاني. الجمهور جن جنونه. لوّح المشجعون بالأعلام طوال الليل."},{s:1,t:"They did. The whole stadium was on its feet. What a night! Even the local journal called it the game of the year. Entry to the stadium was free for kids.",ar:"فعلوا. الملعب كله كان واقفًا. يا لها من ليلة! حتى الصحيفة المحلية وصفتها بمباراة العام. كان الدخول إلى الملعب مجانيًا للأطفال."},{s:0,t:"And the weather for tomorrow? Rain in the north, sunshine in the south. The army's rescue operation continues in the flooded villages. The new policy on nuclear power will be discussed tomorrow.",ar:"والطقس ليوم غد؟ مطر في الشمال، وشمس في الجنوب. تستمر عملية إنقاذ الجيش في القرى التي غمرتها الفيضانات. ستتم مناقشة السياسة الجديدة بشأن الطاقة النووية غدًا."},{s:1,t:"Rain in the north, sunshine in the south. Temperatures around twenty degrees.",ar:"مطر في الشمال، وشمس في الجنوب. درجات الحرارة نحو عشرين درجة."},{s:0,t:"Not bad. That's all for tonight. Thanks for watching.",ar:"ليس سيئًا. هذا كل شيء الليلة. شكرًا للمشاهدة."},{s:1,t:"Thanks. And remember — if you see news happening, send us a photo!",ar:"شكرًا. وتذكروا — إذا رأيتم خبرًا يحدث، أرسلوا لنا صورة!"},{s:0,t:"Good night, everyone!",ar:"تصبحون على خير، جميعًا!"},{s:1,t:"Good night!",ar:"تصبح على خير!"}]}},{stage:10,topic:"business",topicAr:"الأعمال والمال",topicEn:"Business & Money",topicDe:"Geschäft und Geld",emoji:"📈",title:"بدء مشروع صغير",grammar:{id:"en-b1-modals-obligation",title:"Modals of obligation: must / have to / mustn't / don't have to",titleAr:"أفعال الوجوب: must / have to / mustn't / don't have to",covers:1},conv:{id:"en-stage10-b1",speakers:["Entrepreneur (رائد الأعمال)","Investor (المستثمر)"],turns:[{s:0,t:"Thanks for meeting me. I've been working on this business plan for six months. In addition, I've talked to fifty potential customers.",ar:"شكرًا لمقابلتي. كنت أعمل على خطة العمل هذه منذ ستة أشهر. بالإضافة إلى ذلك، تحدثت إلى خمسين عميلًا محتملًا."},{s:1,t:"You're welcome. So, tell me — what exactly is your business? Who is your biggest competitor?",ar:"على الرحب. إذن، أخبرني — ما عملك بالضبط؟ من هو أكبر منافس لك؟"},{s:0,t:"It's an online shop for handmade products. Bags, scarves, jewelry — all made locally. The administration is just me and my sister.",ar:"إنه متجر إلكتروني للمنتجات اليدوية. حقائب وأوشحة ومجوهرات — كلها مصنوعة محليًا. الإدارة هي أنا وأختي فقط."},{s:1,t:"Handmade products. Interesting. Who's your target customer? In comparison with big shops, you're tiny — is that a problem?",ar:"منتجات يدوية. مثير للاهتمام. من هو عميلك المستهدف؟ بالمقارنة مع المتاجر الكبيرة، أنت صغير — هل هذه مشكلة؟"},{s:0,t:"Mainly young women, aged twenty to thirty-five. They care about quality and originality. Our communication with them is mostly online.",ar:"أساسًا الشابات، من عمر عشرين إلى خمسة وثلاثين. يهتممن بالجودة والأصالة. تواصلنا معهن عبر الإنترنت في الغالب."},{s:1,t:"Okay. And how big is the market for this? The growth has been continuous for five years.",ar:"حسنًا. وما حجم السوق لهذا؟ النمو كان مستمرًا لمدة خمس سنوات."},{s:0,t:"Pretty big. Online shopping has grown by twenty percent a year in our country. That's a huge percentage for a small market.",ar:"كبير جدًا. التسوق الإلكتروني نما بنسبة 20% سنويًا في بلدنا. هذه نسبة ضخمة لسوق صغير."},{s:1,t:"Those numbers sound good. But the competition is fierce. What makes you different? Can you convince me in one sentence?",ar:"تلك الأرقام تبدو جيدة. لكن المنافسة شرسة. ما الذي يميزك؟ هل يمكنك إقناعي في جملة واحدة؟"},{s:0,t:"Our products are unique — no two are the same. And we tell the story of each maker. We commit to fair pay for every maker.",ar:"منتجاتنا فريدة — لا يوجد اثنان متشابهان. ونروي قصة كل صانع. نلتزم بأجر عادل لكل صانع."},{s:1,t:"I like that. People love a good story. What about your prices? What does the price consist of — materials, labor, delivery?",ar:"يعجبني ذلك. الناس يحبون قصة جيدة. ماذا عن أسعارك؟ مما يتكون السعر — مواد وعمل وتوصيل؟"},{s:0,t:"Higher than mass-produced goods, but fair. Our makers must earn a decent living. In contrast, big factories pay almost nothing.",ar:"أعلى من السلع المنتجة بكميات كبيرة، لكنها عادلة. يجب أن يكسب صانعونا عيشًا لائقًا. وعلى النقيض، المصانع الكبيرة تدفع القليل جدًا."},{s:1,t:"Fair point. Now, let's talk money. How much do you need to start? Do you use advanced software for the shop?",ar:"نقطة عادلة. الآن، لنتحدث عن المال. كم تحتاج للبدء؟ هل تستخدم برنامجًا متقدمًا للمتجر؟"},{s:0,t:"Fifty thousand dollars. Most of it goes to the website, marketing, and the first stock. We'll also export some products to other countries.",ar:"خمسون ألف دولار. معظمها يذهب للموقع والتسويق والمخزون الأول. سنصدر أيضًا بعض المنتجات إلى بلدان أخرى."},{s:1,t:"Fifty thousand. And when do you expect to make a profit? What if sales are slow — can you handle a loss?",ar:"خمسون ألفًا. ومتى تتوقع تحقيق ربح؟ ماذا لو كانت المبيعات بطيئة — هل يمكنك تحمل خسارة؟"},{s:0,t:"By the end of year two. Year one is about building the brand and gaining customers. It's about development, not profit.",ar:"بحلول نهاية السنة الثانية. السنة الأولى تدور حول بناء العلامة وكسب العملاء. إنها تتعلق بالتطوير، وليس الربح."},{s:1,t:"Year two. That's realistic, I suppose. What's your marketing plan? And how do you handle a complaint from a customer?",ar:"السنة الثانية. هذا واقعي، أفترض. ما خطتك التسويقية؟ وكيف تتعامل مع شكوى من عميل؟"},{s:0,t:"Social media first — short videos, photos, stories. And we work with local influencers. Our spending on ads is small but smart.",ar:"وسائل التواصل الاجتماعي أولًا — مقاطع قصيرة وصور وقصص. ونتعاون مع مؤثرين محليين. إنفاقنا على الإعلانات صغير لكنه ذكي."},{s:1,t:"Good. Social media is cheap and effective. Do you have a team already? And who supplies your materials? The supply of handmade goods is limited, so plan carefully.",ar:"جيد. وسائل التواصل الاجتماعي رخيصة وفعالة. هل لديك فريق بالفعل؟ ومن يورد موادك؟ إمداد السلع اليدوية محدود، لذا خطط بعناية."},{s:0,t:"A small one — me, my sister, and a part-time designer. We all work from home. My sister handles the property — the workshop and storage.",ar:"فريق صغير — أنا وأختي ومصمم بدوام جزئي. نعمل جميعًا من البيت. أختي تتولى الورشة والمخزن."},{s:1,t:"Working from home keeps costs down. Smart. What about delivery? Does the delivery company require a minimum number of packages?",ar:"العمل من البيت يبقي التكاليف منخفضة. ذكي. ماذا عن التوصيل؟ هل تشترط شركة التوصيل حدًا أدنى من الطرود؟"},{s:0,t:"We use a local delivery company. They charge five dollars per package. They accept coins and cards — no, just cards and online payment.",ar:"نستخدم شركة توصيل محلية. يتقاضون خمسة دولارات لكل طرد. يقبلون العملات المعدنية والبطاقات — لا، البطاقات والدفع الإلكتروني فقط."},{s:1,t:"Five dollars per package. That's reasonable. And returns? We need a proper system for returns, or customers will get angry.",ar:"خمسة دولارات لكل طرد. هذا معقول. والمرتجعات؟ نحتاج إلى نظام مناسب للمرتجعات، وإلا سيغضب العملاء."},{s:0,t:"Free returns within two weeks. Customers have to trust us, so we must be generous. Every supporter of our shop gets a small gift.",ar:"مرتجعات مجانية خلال أسبوعين. يجب أن يثق بنا العملاء، لذلك يجب أن نكون كرماء. كل داعم لمتجرنا يحصل على هدية صغيرة."},{s:1,t:"Generous returns can be expensive. Are you sure about that? The range of products is big — returns could hurt.",ar:"المرتجعات السخية قد تكون مكلفة. هل أنت متأكد من ذلك؟ تشكيلة المنتجات كبيرة — المرتجعات قد تضر."},{s:0,t:"I am. Happy customers come back, and they tell their friends. That's the best advertising.",ar:"أنا متأكد. العملاء السعداء يعودون، ويخبرون أصدقاءهم. هذا أفضل إعلان."},{s:1,t:"True. Word of mouth is powerful. Now, what's your biggest risk?",ar:"صحيح. الدعاية الشفهية قوية. الآن، ما أكبر مخاطرة لديك؟"},{s:0,t:"Honestly? Cash flow. If sales are slow in the first months, we could run out of money.",ar:"بصراحة؟ التدفق النقدي. إذا كانت المبيعات بطيئة في الأشهر الأولى، قد تنفد أموالنا."},{s:1,t:"That's the risk every new business faces. How will you handle it?",ar:"هذه هي المخاطرة التي يواجهها كل عمل جديد. كيف ستتعامل معها؟"},{s:0,t:"I've saved enough to cover six months of costs. And my sister has a part-time job too.",ar:"ادخرت ما يكفي لتغطية تكاليف ستة أشهر. وأختي لديها وظيفة بدوام جزئي أيضًا."},{s:1,t:"Good planning. I have to say, I'm impressed. You've thought this through.",ar:"تخطيط جيد. يجب أن أقول، أنا معجب. لقد فكرت في هذا جيدًا."},{s:0,t:"Thank you. That means a lot. So... what do you think? Will you invest?",ar:"شكرًا. هذا يعني لي الكثير. إذن... ما رأيك؟ هل ستستثمر؟"},{s:1,t:"I like the idea, and I like your attitude. But I need to see the full financial details first.",ar:"تعجبني الفكرة، ويعجبني موقفك. لكنني أحتاج إلى رؤية التفاصيل المالية الكاملة أولًا."},{s:0,t:"Of course. I'll send you the full report tonight — sales forecasts, costs, everything.",ar:"بالطبع. سأرسل لك التقرير الكامل الليلة — توقعات المبيعات والتكاليف وكل شيء."},{s:1,t:"Perfect. Send it over, and I'll get back to you by Friday.",ar:"مثالي. أرسله، وسأرد عليك بحلول الجمعة."},{s:0,t:"Great! I really appreciate your time today.",ar:"رائع! أقدّر وقتك اليوم حقًا."},{s:1,t:"My pleasure. One last tip: don't give up if the first months are hard. They always are.",ar:"بكل سرور. نصيحة أخيرة: لا تستسلم إذا كانت الأشهر الأولى صعبة. إنها كذلك دائمًا."},{s:0,t:"I won't. I've wanted this for years. I'm not quitting now.",ar:"لن أفعل. أردت هذا منذ سنوات. لن أستسلم الآن."},{s:1,t:"That's the spirit. Good luck — I mean it.",ar:"هذه هي الروح. حظًا سعيدًا — أعني ذلك."},{s:0,t:"Thanks! I'll be in touch tonight.",ar:"شكرًا! سأكون على اتصال الليلة."},{s:1,t:"Looking forward to it. Goodbye!",ar:"أتطلع إلى ذلك. إلى اللقاء!"},{s:0,t:"Goodbye!",ar:"إلى اللقاء!"}]}},{stage:11,topic:"culture",topicAr:"الثقافة والقصص اليومية",topicEn:"Culture & Daily Stories",topicDe:"Kultur und Alltagsgeschichten",emoji:"🎭",title:"الثقافة والفن",grammar:{id:"en-b1-present-perfect-past-simple",title:"Present perfect vs past simple",titleAr:"المضارع التام والماضي البسيط",covers:1},conv:{id:"en-stage11-b1",speakers:["Artist (الفنان)","Critic (الناقد)"],turns:[{s:0,t:"Welcome to the gallery! Have you seen the new exhibition yet? I was amazed by the new collection. The beauty of her work is in the light.",ar:"أهلًا بك في المعرض! هل رأيت المعرض الجديد بعد؟ اندهشت من المجموعة الجديدة. جمال عملها يكمن في الضوء."},{s:1,t:"Not yet. I've only just arrived. What's it about? Is it a central theme, or many different ones?",ar:"ليس بعد. وصلت للتو. ما موضوعه؟ هل هو موضوع مركزي، أم مواضيع مختلفة كثيرة؟"},{s:0,t:"It's about everyday life — street scenes, portraits, old traditions. The cultural identity of the town is everywhere here. The wedding category is my favorite — the bride, the ceremony, the marriage vows.",ar:"إنه عن الحياة اليومية — مشاهد الشوارع والصور الشخصية والتقاليد القديمة. الهوية الثقافية للمدينة موجودة في كل مكان هنا. فئة الزفاف هي المفضلة لدي — العروس والحفل وعهود الزواج."},{s:1,t:"Sounds fascinating. I love art that tells a story. A good narrative can change how you see the world.",ar:"يبدو مثيرًا للاهتمام. أحب الفن الذي يروي قصة. السرد الجيد يمكن أن يغير نظرتك إلى العالم."},{s:0,t:"Me too. Come, look at this one. It's my favorite piece in the whole show. The frame alone is a work of art.",ar:"وأنا أيضًا. تعال، انظر إلى هذه. إنها قطعتي المفضلة في المعرض كله. الإطار وحده عمل فني."},{s:1,t:"Wow. The colors are so strong. Who painted it? The colored pencils on the table are hers, I think.",ar:"واو. الألوان قوية جدًا. من رسمها؟ أقلام التلوين على الطاولة لها، أظن."},{s:0,t:"A young artist from the countryside. She painted it when she was only twenty. She grew up in a remote village, far from any city.",ar:"فنانة شابة من الريف. رسمتها عندما كان عمرها عشرين فقط. نشأت في قرية نائية، بعيدة عن أي مدينة."},{s:1,t:"Twenty? That's incredible. What's the story behind it? The plot is simple, but the feeling is deep.",ar:"عشرون؟ هذا لا يصدق. ما القصة وراءها؟ الحبكة بسيطة، لكن الشعور عميق."},{s:0,t:"It shows her grandmother's village. The old houses, the market, the people. Her grandmother wore a cotton dress in the painting. A diamond ring shines on her hand.",ar:"تُظهر قرية جدتها. البيوت القديمة والسوق والناس. جدتها ارتدت فستانًا قطنيًا في اللوحة. خاتم ألماس يلمع على يدها."},{s:1,t:"I can almost feel the place. The light is beautiful. It reminds me of my youth, summers in the village.",ar:"أكاد أشعر بالمكان. الضوء جميل. يذكرني بشبابي، بصيف القرية."},{s:0,t:"She's talented, no doubt. Have you seen her other work? Her photography exhibition was worldwide news last year.",ar:"إنها موهوبة، بلا شك. هل رأيت أعمالها الأخرى؟ كان معرضها للتصوير خبرًا عالميًا العام الماضي."},{s:1,t:"No, this is the first time I've heard of her. Has she exhibited before? I rarely follow new artists, to be honest.",ar:"لا، هذه أول مرة أسمع عنها. هل عرضت من قبل؟ نادرًا ما أتابع الفنانين الجدد، بصراحة."},{s:0,t:"Yes, twice. Once in the capital, and once abroad. Critics loved her. One critic wrote a highly positive review.",ar:"نعم، مرتين. مرة في العاصمة ومرة في الخارج. أحبها النقاد. كتب أحد النقاد مراجعة إيجابية للغاية."},{s:1,t:"I can see why. So, what do you think of modern art in general? What was the highlight of the show for you?",ar:"أرى السبب. إذن، ما رأيك في الفن الحديث عمومًا؟ ما أبرز ما في المعرض بالنسبة لك؟"},{s:0,t:"To be honest, some of it leaves me cold. A blank canvas with one dot? Come on! It's an ugly trick, if you ask me.",ar:"بصراحة، بعضه لا يحرّك فيّ شيئًا. لوحة فارغة بنقطة واحدة؟ هيا! إنها حيلة قبيحة، إن سألتني."},{s:1,t:"Ha! I know what you mean. But some modern pieces are powerful. Their strength is in the idea, not the paint.",ar:"ها! أعرف ما تقصد. لكن بعض القطع الحديثة قوية. قوتها في الفكرة، وليس في الطلاء."},{s:0,t:"Maybe. But I prefer art I can understand without reading a ten-page explanation. Similarly, I like music with clear lyrics.",ar:"ربما. لكنني أفضل فنًا أستطيع فهمه دون قراءة شرح من عشر صفحات. وبالمثل، أحب الموسيقى ذات الكلمات الواضحة."},{s:1,t:"Fair enough. What about music? Do you go to concerts much? The drum section in that folk band is incredible. The singer wears a fashionable leather jacket on stage.",ar:"عادل بما يكفي. ماذا عن الموسيقى؟ هل تذهب إلى الحفلات كثيرًا؟ قسم الطبول في تلك الفرقة الشعبية مذهل. المغنية ترتدي سترة جلدية عصرية على المسرح."},{s:0,t:"I used to go all the time. Now, with two kids, I mostly listen at home. We dance in the living room, frequently.",ar:"كنت أذهب طوال الوقت. الآن، مع طفلين، أستمع في البيت غالبًا. نرقص في غرفة المعيشة، كثيرًا."},{s:1,t:"I get it. Have you heard the new album by that folk band? They released it last month, and it's already famous. The production was difficult, but the result is wonderful.",ar:"أفهمك. هل سمعت الألبوم الجديد لتلك الفرقة الشعبية؟ أصدروه الشهر الماضي، وهو مشهور بالفعل. كان الإنتاج صعبًا، لكن النتيجة رائعة."},{s:0,t:"Yes! I've played it non-stop this week. The singer's voice is amazing. It's so smooth and gentle. The guitar string broke during the last episode of their show — what excitement!",ar:"نعم! شغلته بلا توقف هذا الأسبوع. صوت المغنية مذهل. إنه ناعم ولطيف جدًا. انكسر وتر الغيتار خلال الحلقة الأخيرة من عرضهم — يا لها من إثارة!"},{s:1,t:"I agree. And the lyrics are like poetry. Simple, but deep. Someone translated them into English, and the translation is beautiful. The length of the album is perfect — forty minutes.",ar:"أوافق. والكلمات مثل الشعر. بسيطة، لكنها عميقة. ترجمها شخص ما إلى الإنجليزية، والترجمة جميلة. مدة الألبوم مثالية — أربعون دقيقة."},{s:0,t:"Poetry and music go together so well. Do you read poetry? There's a famous quotation about poetry and music.",ar:"الشعر والموسيقى يذهبان معًا بشكل جيد. هل تقرأ الشعر؟ هناك اقتباس مشهور عن الشعر والموسيقى."},{s:1,t:"Sometimes. I love the old poets, but new ones surprise me too. One young poet quoted Shakespeare in her latest poem.",ar:"أحيانًا. أحب الشعراء القدماء، لكن الجدد يفاجئونني أيضًا. اقتبست شاعرة شابة شكسبير في قصيدتها الأخيرة."},{s:0,t:"There's a poetry night at the library on Friday. You should come. The performance starts at seven, and it's free.",ar:"هناك أمسية شعرية في المكتبة يوم الجمعة. يجب أن تأتي. يبدأ العرض في السابعة، وهو مجاني."},{s:1,t:"A poetry night? That sounds lovely. What time? I'll bring my sister — she loves spoken word poetry.",ar:"أمسية شعرية؟ هذا يبدو جميلًا. في أي وقت؟ سأحضر أختي — تحب الشعر المنطوق."},{s:0,t:"Seven o'clock. Local poets read their work, and anyone can join in. It's good entertainment for a Friday night. The producer of the show will introduce everyone. We love to entertain new people.",ar:"السابعة. يقرأ شعراء محليون أعمالهم، ويمكن لأي شخص المشاركة. إنه ترفيه جيد لليلة جمعة. منتج العرض سيقدم الجميع. نحب أن نستضيف أشخاصًا جددًا."},{s:1,t:"I'd love to go. Do I need a ticket? Should I get dressed up, or is it casual?",ar:"أود الذهاب. هل أحتاج إلى تذكرة؟ هل يجب أن أرتدي ملابس أنيقة، أم أنه غير رسمي؟"},{s:0,t:"No, it's free. Just show up. Oh — and they serve tea and cake. You can spot the poets by their notebooks.",ar:"لا، إنها مجانية. فقط احضر. أوه — ويقدمون الشاي والكعك. يمكنك تمييز الشعراء من دفاترهم."},{s:1,t:"Tea and cake? Now you're talking! Count me in. I'll bring a wool sweater — the library is always cold.",ar:"شاي وكعك؟ الآن أنت تتحدث! اعتبرني مشاركًا. سأحضر سترة صوفية — المكتبة باردة دائمًا."},{s:0,t:"Great! By the way, have you seen the play at the theater downtown? The leading actor is brilliant.",ar:"رائع! بالمناسبة، هل رأيت المسرحية في المسرح وسط المدينة؟ الممثل الرئيسي رائع."},{s:1,t:"Not yet, but I've heard great things. Is it a comedy or a drama? I heard it's a romantic comedy, actually. The costumes are beautiful, and the curtain rises at seven.",ar:"ليس بعد، لكنني سمعت أشياء رائعة. هل هي كوميديا أم دراما؟ سمعت أنها كوميديا رومانسية، في الحقيقة. الأزياء جميلة، ويرتفع الستار في السابعة."},{s:0,t:"A bit of both, actually. It's about a prince who gives up his crown. The royal family in the story is very strange.",ar:"قليل من الاثنين، في الحقيقة. إنها عن أمير يتخلى عن تاجه. العائلة الملكية في القصة غريبة جدًا."},{s:1,t:"A prince? Sounds like a fairy tale. Is there a princess too?",ar:"أمير؟ تبدو مثل قصة خيالية. هل هناك أميرة أيضًا؟"},{s:0,t:"It starts like one, but it turns into something much darker. A real mystery. The script was written by a local writer. There's a clue in the second act — watch for it.",ar:"تبدأ مثل واحدة، لكنها تتحول إلى شيء أكثر ظلمة بكثير. لغز حقيقي. كتب النص كاتب محلي. هناك دليل في الفصل الثاني — انتبه له."},{s:1,t:"Hmm, now I'm curious. Maybe I'll go this weekend. Can you persuade me with one more reason? The play represents our town's history — that's my reason.",ar:"همم، الآن أنا فضولي. ربما سأذهب في عطلة الأسبوع. هل يمكنك إقناعي بسبب آخر؟ المسرحية تمثل تاريخ مدينتنا — هذا هو سببي."},{s:0,t:"You should. Culture keeps life interesting, don't you think? Art reflects life — that's my favorite theory about it. My passion for theater started here, as a child.",ar:"يجب أن تفعل. الثقافة تُبقي الحياة ممتعة، ألا تظن؟ الفن يعكس الحياة — هذه نظريتي المفضلة عنه. بدأ شغفي بالمسرح هنا، عندما كنت طفلًا."},{s:1,t:"Absolutely. Life without stories, music, and art would be pretty dull. And the tickets are cheap, therefore there's no excuse.",ar:"بالتأكيد. الحياة دون قصص وموسيقى وفن ستكون مملة جدًا. والتذاكر رخيصة، لذلك لا عذر."},{s:0,t:"Well said. Now, let me show you the rest of the exhibition. The next room has a giant statue of a horse.",ar:"أحسنت القول. الآن، دعني أريك بقية المعرض. الغرفة التالية فيها تمثال عملاق لحصان."},{s:1,t:"Lead the way! And tell me about the documentary film they showed here last month.",ar:"قُد الطريق! وأخبرني عن الفيلم الوثائقي الذي عرضوه هنا الشهر الماضي."},{s:0,t:"This way. And watch out — the floor is a bit slippery here. The surface is polished marble, so it's shiny.",ar:"من هنا. وانتبه — الأرض زلقة بعض الشيء هنا. السطح رخام مصقول، لذا فهو لامع."},{s:1,t:"Thanks for the warning. So, who's the artist in the next room? I heard he paints with a special technique.",ar:"شكرًا على التحذير. إذن، من الفنان في الغرفة التالية؟ سمعت أنه يرسم بتقنية خاصة."},{s:0,t:"An old photographer. His portraits of fishermen are world-famous. One photo shows a sailor with a fur coat. The medium he uses is film, not digital. He loves to shoot portraits at sunset.",ar:"مصور قديم. صوره الشخصية للصيادين مشهورة عالميًا. إحدى الصور تُظهر بحارًا بمعطف من الفرو. الوسيط الذي يستخدمه هو الفيلم، وليس الرقمي. يحب تصوير البورتريهات عند الغروب."},{s:1,t:"Fishermen? I can't wait to see them. Do they have a ghost story in the exhibition too? I love ghost stories.",ar:"صيادون؟ لا أطيق الانتظار لرؤيتهم. هل لديهم قصة شبح في المعرض أيضًا؟ أحب قصص الأشباح."}]}},{stage:12,topic:"american",topicAr:"الحياة الأمريكية والعامية",topicEn:"American Life & Slang",topicDe:"Amerikanisches Leben und Slang",emoji:"🇺🇸",title:"الحياة في أمريكا",grammar:{id:"en-b1-second-conditional",title:"Second conditional: If + past simple, would + verb",titleAr:"الشرط الثاني: If + الماضي البسيط، would + الفعل",covers:1},conv:{id:"en-stage12-b1",speakers:["Immigrant (المهاجر)","American Friend (الصديق الأمريكي)"],turns:[{s:0,t:"Hey man, what's up? You look kinda lost. You must be a new immigrant — welcome to the city!",ar:"مرحبًا يا رجل، ما الأمر؟ تبدو تائهًا بعض الشيء. لا بد أنك مهاجر جديد — أهلًا بك في المدينة!"},{s:1,t:"Hey! Yeah, I'm totally lost. I'm looking for the subway station. Unlike back home, the streets here all look the same.",ar:"مرحبًا! نعم، أنا تائه تمامًا. أبحث عن محطة المترو. على عكس الوطن، كل الشوارع هنا تبدو متشابهة."},{s:0,t:"No worries, it's right around the corner. You're new here, right? This is the western part of the city — the old part is east.",ar:"لا تقلق، إنها حول الزاوية مباشرة. أنت جديد هنا، أليس كذلك؟ هذا هو الجزء الغربي من المدينة — الجزء القديم في الشرق."},{s:1,t:"Yeah, I moved here from overseas three weeks ago. Everything's so different. I successfully found an apartment, at least.",ar:"نعم، انتقلت إلى هنا من الخارج قبل ثلاثة أسابيع. كل شيء مختلف جدًا. وجدت شقة بنجاح، على الأقل."},{s:0,t:"I bet. Where are you from, if you don't mind me asking? Your story is valuable — I'd love to hear it.",ar:"أراهن. من أين أنت، إذا لم تمانع في سؤالي؟ قصتك قيّمة — أود سماعها."},{s:1,t:"I don't mind at all. I'm from Iraq, originally. Baghdad.",ar:"لا أمانع إطلاقًا. أنا من العراق أصلًا. بغداد."},{s:0,t:"Cool! I've never been, but I've heard the food is amazing. Food trucks are a big trend here now.",ar:"رائع! لم أذهب أبدًا، لكنني سمعت أن الطعام مذهل. عربات الطعام اتجاه كبير هنا الآن."},{s:1,t:"It is! I miss it so much. The food here is... different. I miss my mother's cooking, specifically her rice.",ar:"إنه كذلك! أفتقده كثيرًا. الطعام هنا... مختلف. أفتقد طبخ أمي، وتحديدًا أرزها."},{s:0,t:"Ha! Yeah, American food takes some getting used to. Have you tried a burger yet? It's a standard American meal.",ar:"ها! نعم، الطعام الأمريكي يحتاج بعض التعود. هل جربت البرغر بعد؟ إنها وجبة أمريكية قياسية."},{s:1,t:"I have. It was huge! I couldn't finish it. And the fries — a ton of them. Too much salt gives me an unpleasant feeling.",ar:"جربته. كان ضخمًا! لم أستطع إنهاءه. والبطاطس المقلية — كمية هائلة. الكثير من الملح يمنحني شعورًا غير مريح."},{s:0,t:"That's America for you — everything's supersized. You'll get used to it. The news about the new burger place spread fast.",ar:"هذه هي أمريكا بالنسبة لك — كل شيء بحجم ضخم. ستعتاد عليه. انتشر خبر مكان البرغر الجديد بسرعة."},{s:1,t:"Maybe. So, what's life like here, really? The good and the bad.",ar:"ربما. إذن، كيف هي الحياة هنا حقًا؟ الجيد والسيئ."},{s:0,t:"To be honest, it's a mixed bag. People are friendly, but everyone's always in a hurry. I'm unable to relax here — everything moves so fast.",ar:"بصراحة، فيها الجيد والسيئ. الناس ودودون، لكن الجميع دائمًا في عجلة. لا أستطيع الاسترخاء هنا — كل شيء يتحرك بسرعة كبيرة."},{s:1,t:"I've noticed that. Back home, we'd sit and talk for hours over tea. Upon arriving here, I missed that the most.",ar:"لاحظت ذلك. في بلدي، كنا نجلس ونتحدث لساعات على الشاي. عند وصولي إلى هنا، افتقدت ذلك أكثر من أي شيء."},{s:0,t:"Yeah, here it's more like grab a coffee and run. But people mean well. In the southern states, life is slower, they say.",ar:"نعم، هنا الأمر أشبه بأخذ قهوة والركض. لكن الناس يقصدون الخير. في الولايات الجنوبية، الحياة أبطأ، كما يقولون."},{s:1,t:"I believe you. What about work? Is it hard to find a job? Is there a suitable job for someone like me?",ar:"أصدقك. ماذا عن العمل؟ هل من الصعب إيجاد وظيفة؟ هل توجد وظيفة مناسبة لشخص مثلي؟"},{s:0,t:"It depends. If you speak English well and you're willing to work hard, you'll find something. I strongly recommend learning slang too.",ar:"يعتمد. إذا كنت تتحدث الإنجليزية جيدًا ومستعدًا للعمل بجد، ستجد شيئًا. أوصي بشدة بتعلم العامية أيضًا."},{s:1,t:"My English is okay, but slang confuses me. People say stuff I don't get. Whatever they say, I just smile and nod.",ar:"إنجليزيتي جيدة، لكن العامية تربكني. الناس يقولون أشياء لا أفهمها. مهما قالوا، أبتسم وأومئ فقط."},{s:0,t:"Like what? Give me an example. Oh — and my trainer at the gym says the same thing about slang.",ar:"مثل ماذا؟ أعطني مثالًا. أوه — ومدربي في الصالة الرياضية يقول الشيء نفسه عن العامية."},{s:1,t:"Like 'what's up?' — I kept answering with a weather report! It's written in my notebook as a joke now.",ar:"مثل 'ما الأمر؟' — كنت أجيب بتقرير عن الطقس! إنها مكتوبة في دفتري كنكتة الآن."},{s:0,t:"Ha! That's hilarious. 'What's up' just means 'hi'. Nobody wants a real answer. It's a bit unfair, honestly.",ar:"ها! هذا مضحك جدًا. 'ما الأمر' تعني فقط 'مرحبًا'. لا أحد يريد إجابة حقيقية. إنه غير عادل بعض الشيء، بصراحة."},{s:1,t:"I figured that out eventually. And 'cool' means good, 'awesome' means great... It's unlikely I'll master it in a month.",ar:"اكتشفت ذلك في النهاية. و'رائع' تعني جيدًا، و'مذهل' تعني عظيمًا... من غير المرجح أن أتقنها في شهر."},{s:0,t:"Exactly! You're picking it up fast. What else is confusing? You'll be fine, unless you stop practicing.",ar:"بالضبط! أنت تتعلم بسرعة. ماذا أيضًا مربك؟ ستكون بخير، ما لم تتوقف عن التدريب."},{s:1,t:"Tipping! Nobody told me I had to tip the waiter. I felt so embarrassed. I thought the service charge was enough — the extra tip seemed unnecessary.",ar:"الإكرامية! لم يخبرني أحد أنه يجب أن أعطي إكرامية للنادل. شعرت بالحرج الشديد. ظننت أن رسوم الخدمة كافية — الإكرامية الإضافية بدت غير ضرورية."},{s:0,t:"Oh man, yeah. Tipping is a big deal here. Fifteen to twenty percent, usually. The viewers on my favorite show talked about it last week.",ar:"أوه يا رجل، نعم. الإكرامية أمر كبير هنا. من 15 إلى 20 بالمئة عادة. تحدث المشاهدون في برنامجي المفضل عن ذلك الأسبوع الماضي."},{s:1,t:"I know now. If someone had told me earlier, I wouldn't have made that mistake. I had to weigh every dollar in my first month.",ar:"أعرف الآن. لو أخبرني أحد مبكرًا، لما ارتكبت ذلك الخطأ. كان عليّ أن أزن كل دولار في شهري الأول."},{s:0,t:"Don't sweat it. Everyone makes mistakes when they move to a new country. Theirs is a different culture — that's all.",ar:"لا تقلق. الجميع يرتكب أخطاء عند الانتقال إلى بلد جديد. ثقافتهم مختلفة — هذا كل شيء."},{s:1,t:"Thanks. So, what should I see in this city? Any tips? I saw a dog with a long tail in the park — it reminded me of home.",ar:"شكرًا. إذن، ماذا يجب أن أرى في هذه المدينة؟ أي نصائح؟ رأيت كلبًا بذيل طويل في الحديقة — ذكرني بالوطن."},{s:0,t:"Tons of stuff. The park, the museums, the food trucks downtown. Oh, and the baseball game! The technical rules are confusing, but the atmosphere is great. We can hunt for cheap tickets online.",ar:"أشياء كثيرة. الحديقة والمتاحف وعربات الطعام وسط المدينة. أوه، ومباراة البيسبول! القواعد الفنية مربكة، لكن الأجواء رائعة. يمكننا البحث عن تذاكر رخيصة عبر الإنترنت."},{s:1,t:"Baseball? I know nothing about it. Is it fun to watch? I need to do laundry first — even my underwear is dirty after the trip.",ar:"بيسبول؟ لا أعرف عنه شيئًا. هل من الممتع مشاهدته؟ أحتاج إلى غسل الملابس أولًا — حتى ملابسي الداخلية متسخة بعد الرحلة."},{s:0,t:"Totally! It's slow, but the atmosphere is great. Hot dogs, caps, the whole thing. You'll love it. My cousin got engaged at a game last year — he kissed his girlfriend on the big screen!",ar:"تمامًا! إنها بطيئة، لكن الأجواء رائعة. هوت دوغ وقبعات، وكل شيء. ستحبها. خطب ابن عمي في مباراة العام الماضي — قبّل صديقته على الشاشة الكبيرة!"},{s:1,t:"Hot dogs at a game — that's so American. I gotta try it.",ar:"هوت دوغ في مباراة — هذا أمريكي جدًا. يجب أن أجربه."},{s:0,t:"You do. Hey, if you're free on Saturday, wanna come with me? My friends are going.",ar:"يجب أن تفعل. اسمع، إذا كنت حرًا يوم السبت، هل تريد أن تأتي معي؟ أصدقائي ذاهبون."},{s:1,t:"Saturday? I'd love to! What time?",ar:"السبت؟ أود ذلك! في أي وقت؟"},{s:0,t:"Game starts at one. We meet at noon, grab some food first. The stadium is huge — don't get lost. If it rains, we stay indoors and watch it on TV.",ar:"تبدأ المباراة في الواحدة. نلتقي في الظهر، ونأخذ بعض الطعام أولًا. الملعب ضخم — لا تضل. إذا أمطرت، نبقى في الداخل ونشاهدها على التلفاز."},{s:1,t:"Perfect. I'll be there. Should I bring anything?",ar:"مثالي. سأكون هناك. هل يجب أن أحضر شيئًا؟"},{s:0,t:"Just yourself. And maybe a cap — the sun is brutal in those seats.",ar:"نفسك فقط. وربما قبعة — الشمس قاسية في تلك المقاعد."},{s:1,t:"A cap, got it. Thanks for everything, man. You're a lifesaver.",ar:"قبعة، فهمت. شكرًا على كل شيء يا رجل. أنت منقذ."},{s:0,t:"Anytime, buddy. Welcome to America!",ar:"في أي وقت يا صديقي. أهلًا بك في أمريكا!"},{s:1,t:"Thanks! I'm really glad I ran into you today.",ar:"شكرًا! أنا سعيد حقًا لأنني التقيت بك اليوم."},{s:0,t:"Me too. See you Saturday!",ar:"وأنا أيضًا. أراك يوم السبت!"},{s:1,t:"See you!",ar:"أراك!"}]}},{stage:13,topic:"philosophy",topicAr:"الفلسفة والأفكار",topicEn:"Philosophy & Ideas",topicDe:"Philosophie und Ideen",emoji:"🤔",title:"أسئلة كبيرة عن الحياة",grammar:{id:"en-b1-question-tags",title:"Question tags",titleAr:"الأسئلة الذيلية",covers:1},conv:{id:"en-stage13-b1",speakers:["Philosopher (الفيلسوف)","Student (الطالب)"],turns:[{s:0,t:"So, you've been reading philosophy. What got you interested? I mean, what's the basis of your interest — curiosity, or doubt? There's magic in a good question, I think.",ar:"إذن، كنت تقرأ الفلسفة. ما الذي أثار اهتمامك؟ أعني، ما أساس اهتمامك — الفضول، أم الشك؟ هناك سحر في السؤال الجيد، أظن."},{s:1,t:"Honestly? I started asking big questions, and nobody around me had answers. It was a bit frightening, actually.",ar:"بصراحة؟ بدأت أطرح أسئلة كبيرة، ولم يكن لدى أحد حولي إجابات. كان الأمر مخيفًا بعض الشيء، في الحقيقة."},{s:0,t:"That's how it starts. What kind of questions? The basic ones, or the strange ones?",ar:"هكذا يبدأ الأمر. أي نوع من الأسئلة؟ الأساسية، أم الغريبة؟"},{s:1,t:"Like... what is the truth? How do we know what's real? What is the content of a true statement, anyway?",ar:"مثل... ما هي الحقيقة؟ كيف نعرف ما هو حقيقي؟ ما مضمون العبارة الصادقة، على أي حال؟"},{s:0,t:"Ah, the classic questions. Philosophers have argued about those for thousands of years. The debate is historic, really.",ar:"آه، الأسئلة الكلاسيكية. الفلاسفة يجادلون حولها منذ آلاف السنين. النقاش تاريخي حقًا."},{s:1,t:"And they still haven't agreed? That seems like a waste of time, doesn't it? It's a disadvantage of philosophy, maybe.",ar:"وما زالوا لم يتفقوا؟ يبدو ذلك مضيعة للوقت، أليس كذلك؟ ربما هذا عيب في الفلسفة."},{s:0,t:"It might look that way. But the questions matter more than the answers, don't they? The consequence of asking is a better life.",ar:"قد يبدو الأمر كذلك. لكن الأسئلة أهم من الإجابات، أليس كذلك؟ نتيجة السؤال هي حياة أفضل."},{s:1,t:"Hmm. I never thought of it like that. So what have you learned from all this reading? Can you conclude anything at all?",ar:"همم. لم أفكر في الأمر هكذا أبدًا. إذن ماذا تعلمت من كل هذه القراءة؟ هل يمكنك استنتاج أي شيء على الإطلاق؟"},{s:0,t:"That most of what we believe comes from our culture, our family, our time. Our beliefs have a base in childhood, mostly.",ar:"أن معظم ما نؤمن به يأتي من ثقافتنا وعائلتنا وعصرنا. معتقداتنا لها أساس في الطفولة، في الغالب."},{s:1,t:"You mean our beliefs aren't really ours? That's a bit cruel, isn't it? It makes me feel like a copy.",ar:"تقصد أن معتقداتنا ليست حقًا لنا؟ هذا قاسٍ بعض الشيء، أليس كذلك؟ يجعلني أشعر أنني نسخة."},{s:0,t:"Partly, yes. If you'd been born in another country, you'd probably believe different things. Your religious beliefs, your politics — everything.",ar:"جزئيًا، نعم. لو وُلدت في بلد آخر، لربما آمنت بأشياء مختلفة. معتقداتك الدينية وسياستك — كل شيء."},{s:1,t:"That's a scary thought. So how can we know what's true? I feel disappointed that there's no simple answer. Nor is there a single method — every thinker has their own.",ar:"هذه فكرة مخيفة. إذن كيف يمكننا أن نعرف ما هو صحيح؟ أشعر بخيبة أمل لأنه لا توجد إجابة بسيطة. ولا توجد طريقة واحدة أيضًا — كل مفكر لديه طريقته."},{s:0,t:"We can't know for sure. But we can think carefully, ask questions, and test our ideas. That's the best path to wisdom. It often occurs to me that doubt is the beginning of wisdom.",ar:"لا يمكننا أن نعرف على وجه اليقين. لكن يمكننا التفكير بعناية وطرح الأسئلة واختبار أفكارنا. هذا أفضل طريق إلى الحكمة. يخطر لي غالبًا أن الشك هو بداية الحكمة."},{s:1,t:"Test ideas? Like scientists do? A chemist tests a chemical, and we test an idea — similar, in a way. Genetic engineering raises big questions too.",ar:"اختبار الأفكار؟ مثلما يفعل العلماء؟ الكيميائي يختبر مادة كيميائية، ونحن نختبر فكرة — متشابه، بطريقة ما. الهندسة الوراثية تثير أسئلة كبيرة أيضًا."},{s:0,t:"Exactly. Science and philosophy are cousins, really. Both start with wonder. But can philosophy prove anything at all?",ar:"بالضبط. العلم والفلسفة أبناء عمومة حقًا. كلاهما يبدأ بالدهشة. لكن هل يمكن للفلسفة أن تثبت أي شيء على الإطلاق؟"},{s:1,t:"Wonder... I like that word. So what about happiness? What makes a good life? Are pleasure and virtue equal in value? It's obvious that money alone isn't enough.",ar:"الدهشة... أحب تلك الكلمة. إذن ماذا عن السعادة؟ ما الذي يصنع حياة جيدة؟ هل المتعة والفضيلة متساويتان في القيمة؟ من الواضح أن المال وحده لا يكفي."},{s:0,t:"Ah, the big one! Some say pleasure, some say virtue, some say knowledge. Equally, some say it's about helping others.",ar:"آه، السؤال الكبير! البعض يقول المتعة، والبعض يقول الفضيلة، والبعض يقول المعرفة. وبالمثل، البعض يقول إنها تتعلق بمساعدة الآخرين."},{s:1,t:"And what do you say? I combine a few ideas — a little pleasure, a little purpose, a little peace.",ar:"وماذا تقول أنت؟ أجمع بين بعض الأفكار — قليل من المتعة وقليل من الهدف وقليل من السلام."},{s:0,t:"I say it's a mix. A good life needs friendship, purpose, and a bit of peace. Money doesn't necessarily bring happiness.",ar:"أقول إنه مزيج. الحياة الجيدة تحتاج إلى صداقة وهدف وقليل من السلام. المال لا يجلب السعادة بالضرورة."},{s:1,t:"Purpose... that's the hard part. I don't know what my purpose is yet. I feel a lack of direction, to be honest.",ar:"الهدف... هذا هو الجزء الصعب. لا أعرف ما هو هدفي بعد. أشعر بنقص في الاتجاه، بصراحة."},{s:0,t:"Most people don't, at your age. Purpose isn't found, it's built — step by step. An organized mind finds it faster.",ar:"معظم الناس لا يعرفون، في عمرك. الهدف لا يُوجد، بل يُبنى — خطوة بخطوة. العقل المنظم يجده أسرع."},{s:1,t:"Built. I like that. But what about religion? Where does faith fit in? Do you pray, or do you just think? Prayer is a daily habit for millions of people.",ar:"يُبنى. يعجبني ذلك. لكن ماذا عن الدين؟ أين يتناسب الإيمان؟ هل تصلي، أم تفكر فقط؟ الصلاة عادة يومية لملايين الناس."},{s:0,t:"For many people, faith gives meaning and comfort. For others, reason is enough. A priest once told me faith is a gift.",ar:"بالنسبة لكثير من الناس، الإيمان يعطي معنى وراحة. وبالنسبة لآخرين، العقل يكفي. قال لي كاهن ذات مرة إن الإيمان هبة."},{s:1,t:"Can both live together? Faith and reason, I mean. I think they can — one doesn't have to reject the other.",ar:"هل يمكن أن يعيشا معًا؟ الإيمان والعقل، أعني. أظن أنهما يستطيعان — لا يجب على أحدهما رفض الآخر."},{s:0,t:"They can, and they often do. The conflict is usually about power, not truth. Power and authority go together, unfortunately. We ought to question authority, not just obey it.",ar:"يمكنهما، وغالبًا ما يفعلان. الصراع عادة حول السلطة، وليس الحقيقة. القوة والسلطة تسيران معًا، للأسف. علينا أن نشكك في السلطة، وليس أن نطيعها فقط."},{s:1,t:"Power... that's an interesting point. Do you think people want truth, or just comfort? Experienced thinkers say comfort wins. The influence of the media is enormous — it shapes what we want.",ar:"السلطة... هذه نقطة مثيرة للاهتمام. هل تظن أن الناس يريدون الحقيقة، أم الراحة فقط؟ المفكرون ذوو الخبرة يقولون إن الراحة تفوز. تأثير الإعلام هائل — إنه يشكل ما نريد."},{s:0,t:"Mostly comfort, if I'm honest. Truth can be uncomfortable, even painful. A disappointing truth is harder than a pleasant lie. The importance of truth is easy to forget.",ar:"الراحة في الغالب، إن كنت صادقًا. الحقيقة قد تكون غير مريحة، بل مؤلمة. الحقيقة المخيبة للآمال أصعب من الكذبة المريحة. من السهل نسيان أهمية الحقيقة."},{s:1,t:"Painful truth or comfortable lie? That's a hard choice. I dislike both, to be honest — but I'd choose truth. The similarity between a lie and a story is thin — both are invented.",ar:"حقيقة مؤلمة أم كذبة مريحة؟ هذا خيار صعب. لا أحب أيًا منهما، بصراحة — لكنني سأختار الحقيقة. التشابه بين الكذبة والقصة ضئيل — كلتاهما مخترعة."},{s:0,t:"It is. But a lie always falls apart in the end. Truth lasts. Reality always wins, sooner or later. The substance of a good argument is evidence, not emotion.",ar:"إنه كذلك. لكن الكذبة تنهار دائمًا في النهاية. الحقيقة تدوم. الواقع يفوز دائمًا، عاجلًا أم آجلًا. جوهر الحجة الجيدة هو الدليل، وليس العاطفة."},{s:1,t:"I hope you're right. What about freedom? Are we really free? Or are we slaves to our habits? An enemy can be outside — or inside your own mind.",ar:"آمل أنك محق. ماذا عن الحرية؟ هل نحن أحرار حقًا؟ أم أننا عبيد لعاداتنا؟ العدو قد يكون في الخارج — أو داخل عقلك."},{s:0,t:"Free to choose, yes — but within limits. Our past, our habits, our society shape us. The immediate cause of a choice is often invisible. Indirect causes — like childhood — matter even more.",ar:"أحرار في الاختيار، نعم — لكن ضمن حدود. ماضينا وعاداتنا ومجتمعنا تشكلنا. السبب المباشر للاختيار غالبًا غير مرئي. الأسباب غير المباشرة — مثل الطفولة — مهمة أكثر."},{s:1,t:"So freedom isn't total. It's more like... freedom inside a cage? That's an old-fashioned idea, but it fits.",ar:"إذن الحرية ليست كاملة. إنها أشبه بـ... حرية داخل قفص؟ هذه فكرة قديمة الطراز، لكنها تناسب."},{s:0,t:"Ha! A big cage, maybe. But we can still choose how to live inside it. Even a servant can choose his attitude.",ar:"ها! قفص كبير، ربما. لكن ما زال بإمكاننا اختيار كيف نعيش داخله. حتى الخادم يستطيع اختيار موقفه."},{s:1,t:"That's strangely comforting. My thoughts race like a silent film, though. Eastern philosophy calls the mind a jumping monkey. Even my imaginary childhood friend would agree. Living on the edge of what we know is exciting, not scary.",ar:"هذا مريح بشكل غريب. أفكاري تتسابق مثل فيلم صامت، مع ذلك. الفلسفة الشرقية تسمي العقل قردًا يقفز. حتى صديقي الخيالي من الطفولة سيوافق. العيش على حافة ما نعرفه مثير، وليس مخيفًا."},{s:0,t:"Good. That means you're thinking. Philosophy should shake you up a little. I encourage you to keep asking questions. Intelligence without curiosity is like a car without fuel.",ar:"جيد. هذا يعني أنك تفكر. يجب أن تهزك الفلسفة قليلًا. أشجعك على الاستمرار في طرح الأسئلة. الذكاء دون فضول مثل سيارة بلا وقود."},{s:1,t:"It definitely is. So, what should I read next? Can you recommend a book? A short recommendation would help.",ar:"إنها تفعل بالتأكيد. إذن، ماذا يجب أن أقرأ بعد ذلك؟ هل يمكنك أن توصي بكتاب؟ توصية قصيرة ستساعد."},{s:0,t:"Start with something short. A few essays, not a huge book. And talk about them. A decade ago, I started the same way. Every element of a good life takes time to build.",ar:"ابدأ بشيء قصير. بعض المقالات، وليس كتابًا ضخمًا. وتحدث عنها. قبل عقد من الزمن، بدأت بالطريقة نفسها. كل عنصر من عناصر الحياة الجيدة يستغرق وقتًا ليُبنى."},{s:1,t:"Talk about them — with you, I hope? I keep a reference list of good books — I'll share it with you.",ar:"أتحدث عنها — معك، آمل؟ أحتفظ بقائمة مرجعية للكتب الجيدة — سأشاركها معك."},{s:0,t:"Anytime. Come back next week, and we'll argue about happiness. Anyone can participate — that's the rule.",ar:"في أي وقت. عُد الأسبوع المقبل، وسنتجادل حول السعادة. يمكن لأي شخص المشاركة — هذه هي القاعدة."},{s:1,t:"Deal. I look forward to it. Thanks for your time! My prediction: I'll be back with a hundred new questions.",ar:"اتفقنا. أتطلع إلى ذلك. شكرًا لوقتك! توقعي: سأعود بمئة سؤال جديد."},{s:0,t:"My pleasure. Keep asking questions — never stop. Remain curious, and you'll never be bored.",ar:"بكل سرور. استمر في طرح الأسئلة — لا تتوقف أبدًا. ابقَ فضوليًا، ولن تشعر بالملل أبدًا."},{s:1,t:"I won't. Goodbye! Oh — one more thing. Do you have a sample chapter I can read first?",ar:"لن أفعل. إلى اللقاء! أوه — شيء آخر. هل لديك فصل نموذجي يمكنني قراءته أولًا؟"},{s:0,t:"Goodbye!",ar:"إلى اللقاء!"}]}},{stage:14,topic:"psychology",topicAr:"علم النفس والعقل",topicEn:"Psychology & Mind",topicDe:"Psychologie und Geist",emoji:"🧠",title:"فهم العقل والمشاعر",grammar:{id:"en-b1-second-conditional",title:"Second conditional: If + past simple, would + verb",titleAr:"الشرط الثاني: If + الماضي البسيط، would + الفعل",covers:1},conv:{id:"en-stage14-b1",speakers:["Psychologist (عالم النفس)","Client (العميل)"],turns:[{s:0,t:"Welcome. Please, sit down. Make yourself comfortable. This is a safe place — nothing you say leaves this room.",ar:"أهلًا بك. تفضل، اجلس. اجعل نفسك مرتاحًا. هذا مكان آمن — لا شيء مما تقوله يغادر هذه الغرفة."},{s:1,t:"Thanks. I've never done this before. I feel a bit nervous, to be honest. I feel embarrassed talking about my feelings.",ar:"شكرًا. لم أفعل هذا من قبل. أشعر بالتوتر بعض الشيء، بصراحة. أشعر بالحرج من التحدث عن مشاعري."},{s:0,t:"That's completely normal. Most people feel that way at first. So, what brings you here? Take your time — there's no rush.",ar:"هذا طبيعي تمامًا. معظم الناس يشعرون هكذا في البداية. إذن، ما الذي جاء بك إلى هنا؟ خذ وقتك — لا عجلة."},{s:1,t:"Well... I've been feeling stressed for months. I can't sleep, I can't concentrate. My thoughts race all night — racing thoughts, my doctor called them.",ar:"حسنًا... أشعر بالتوتر منذ أشهر. لا أستطيع النوم، ولا أستطيع التركيز. أفكاري تتسابق طوال الليل — أفكار متسارعة، كما سماها طبيبي."},{s:0,t:"I'm sorry to hear that. When did it start? Was there an immediate cause, or did it build up slowly?",ar:"آسف لسماع ذلك. متى بدأ؟ هل كان هناك سبب مباشر، أم تراكم ببطء؟"},{s:1,t:"Around the time I started my new job. Everything changed at once. A new city, a new boss, a new routine — it was a lot.",ar:"في الوقت الذي بدأت فيه وظيفتي الجديدة. تغير كل شيء دفعة واحدة. مدينة جديدة ومدير جديد وروتين جديد — كان كثيرًا."},{s:0,t:"Big changes can be stressful, even good ones. How's your mood been lately? Up and down, or mostly down?",ar:"التغييرات الكبيرة قد تكون مرهقة، حتى الجيدة منها. كيف كان مزاجك مؤخرًا؟ متقلب، أم منخفض في الغالب؟"},{s:1,t:"Up and down. Some days I'm fine, other days I feel... empty. It's like a horror film in my head on bad days. I want to kick this bad habit of working all night.",ar:"صعودًا وهبوطًا. بعض الأيام أكون بخير، وأيام أخرى أشعر بـ... فراغ. إنه مثل فيلم رعب في رأسي في الأيام السيئة. أريد التخلص من هذه العادة السيئة بالعمل طوال الليل."},{s:0,t:"I understand. And your relationships — family, friends — how are they? Do you feel close to them, or distant?",ar:"أفهم. وعلاقاتك — العائلة والأصدقاء — كيف هي؟ هل تشعر بالقرب منهم، أم بالبعد؟"},{s:1,t:"Strained, I guess. I get annoyed easily, even with people I love. My reaction is too strong, and then I feel guilty. My wife says I need to spend time outdoors, not indoors all day.",ar:"متوترة، أظن. أنزعج بسهولة، حتى مع الأشخاص الذين أحبهم. رد فعلي قوي جدًا، ثم أشعر بالذنب. زوجتي تقول إنني أحتاج إلى قضاء وقت في الهواء الطلق، وليس في الداخل طوال اليوم."},{s:0,t:"That's a common symptom of stress. Your mind is tired, so small things feel huge. It's a normal reaction, not a weakness.",ar:"هذا عرض شائع للتوتر. عقلك متعب، لذلك تبدو الأشياء الصغيرة ضخمة. إنه رد فعل طبيعي، وليس ضعفًا."},{s:1,t:"That makes sense. I wish I could just relax, but I don't know how. I've tried, and I failed — it's embarrassing.",ar:"هذا منطقي. أتمنى لو أستطيع الاسترخاء فقط، لكنني لا أعرف كيف. حاولت وفشلت — إنه محرج."},{s:0,t:"That's what we're here to work on. First, tell me about your daily routine. What does a normal day look like for you?",ar:"هذا ما نحن هنا للعمل عليه. أولًا، أخبرني عن روتينك اليومي. كيف يبدو يومك العادي؟"},{s:1,t:"I wake up at six, work till seven in the evening, eat, watch TV, sleep. That's it. No leisure time at all, really.",ar:"أستيقظ في السادسة، وأعمل حتى السابعة مساءً، وآكل وأشاهد التلفاز وأنام. هذا كل شيء. لا وقت فراغ إطلاقًا، حقًا."},{s:0,t:"No exercise? No time for yourself at all? That can't go on — your body will break down eventually.",ar:"لا رياضة؟ لا وقت لنفسك إطلاقًا؟ لا يمكن أن يستمر هذا — جسمك سينهار في النهاية."},{s:1,t:"No time. Or at least, that's what I tell myself. I know it's an excuse, but it feels true.",ar:"لا وقت. أو على الأقل، هذا ما أقوله لنفسي. أعلم أنه عذر، لكنه يبدو حقيقيًا."},{s:0,t:"Hmm. If only you could see it from the outside — you'd see the problem clearly. Nor would you blame yourself so much.",ar:"همم. لو أمكنك فقط أن ترى الأمر من الخارج — لرأيت المشكلة بوضوح. ولما لومت نفسك كثيرًا أيضًا."},{s:1,t:"What do you mean? I'm not sure I follow.",ar:"ماذا تقصد؟ لست متأكدًا أنني أفهم."},{s:0,t:"Your life has no balance. Work takes everything, and nothing gives energy back. It's like a car with no fuel.",ar:"حياتك بلا توازن. العمل يأخذ كل شيء، ولا شيء يعيد الطاقة. إنها مثل سيارة بلا وقود."},{s:1,t:"You're right. I used to play football every week. I haven't played in a year. I miss it — I miss my friends there too.",ar:"أنت محق. كنت ألعب كرة القدم كل أسبوع. لم ألعب منذ سنة. أفتقدها — وأفتقد أصدقائي هناك أيضًا."},{s:0,t:"There it is. Exercise isn't a luxury — it's medicine for the mind. It helps with sleep, mood, everything.",ar:"ها هو الأمر. الرياضة ليست رفاهية — إنها دواء للعقل. تساعد في النوم والمزاج وكل شيء."},{s:1,t:"Medicine... I never thought of it that way. It's obvious now that you say it — I just never saw it.",ar:"دواء... لم أفكر في الأمر هكذا أبدًا. إنه واضح الآن بعد أن قلته — لم أره أبدًا."},{s:0,t:"Most people don't. Now, what about your childhood? Was it happy? Tell me a little about your family.",ar:"معظم الناس لا يفكرون. الآن، ماذا عن طفولتك؟ هل كانت سعيدة؟ أخبرني قليلًا عن عائلتك."},{s:1,t:"Mostly, yes. But my father was strict. I always felt I had to be perfect. He was a good man, but a hard one.",ar:"في الغالب، نعم. لكن والدي كان صارمًا. شعرت دائمًا أنه يجب أن أكون مثاليًا. كان رجلًا جيدًا، لكنه صعب."},{s:0,t:"That feeling often stays with us. It can make adults push themselves too hard. It can also affect your relations with others. Sex and closeness matter too — don't ignore that part of life.",ar:"ذلك الشعور غالبًا يبقى معنا. يمكن أن يجعل البالغين يضغطون على أنفسهم بشدة. ويمكن أن يؤثر أيضًا على علاقاتك بالآخرين. الجنس والقرب مهمان أيضًا — لا تتجاهل هذا الجزء من الحياة."},{s:1,t:"That sounds like me. I hate making mistakes. I feel guilty when I rest. My father would say rest is for the lazy. Sexual health is part of mental health too, you know.",ar:"هذا يبدو مثلي. أكره ارتكاب الأخطاء. أشعر بالذنب عندما أستريح. كان والدي يقول إن الراحة للكسالى. الصحة الجنسية جزء من الصحة النفسية أيضًا، كما تعلم."},{s:0,t:"Guilt for resting — that's a heavy burden to carry. Where do you think it comes from? Your father, or your school?",ar:"الشعور بالذنب للراحة — هذا عبء ثقيل تحمله. من أين تظن أنه يأتي؟ من والدك، أم من مدرستك؟"},{s:1,t:"Probably from my father. He always said rest is for the weak. He worked outdoors all his life, in the sun and rain.",ar:"على الأرجح من والدي. كان يقول دائمًا إن الراحة للضعفاء. عمل في الهواء الطلق طوال حياته، في الشمس والمطر."},{s:0,t:"He was wrong, you know. Rest is what makes hard work possible. Even machines need to stop and cool down.",ar:"كان مخطئًا، كما تعلم. الراحة هي ما يجعل العمل الجاد ممكنًا. حتى الآلات تحتاج إلى التوقف والتبريد."},{s:1,t:"I know that in my head. But my feelings don't—",ar:"أعرف ذلك في رأسي. لكن مشاعري لا—"},{s:0,t:"—Don't stop there. That's exactly why we're talking. Feelings and thoughts don't always agree.",ar:"—لا تتوقف هناك. لهذا السبب نتحدث بالضبط. المشاعر والأفكار لا تتفق دائمًا."},{s:1,t:"So what do I do? I can't just switch my feelings off. I wish I could, honestly.",ar:"إذن ماذا أفعل؟ لا أستطيع إيقاف مشاعري فقط. أتمنى لو أستطيع، بصراحة."},{s:0,t:"No, you can't. But you can notice them, name them, and choose what to do next. That's a skill — and skills can be learned. It takes practice, but it works.",ar:"لا، لا تستطيع. لكن يمكنك ملاحظتها وتسميتها واختيار ما تفعله بعد ذلك. هذه مهارة — والمهارات يمكن تعلمها. يتطلب الأمر تدريبًا، لكنه يعمل."},{s:1,t:"Notice them... like, 'I'm feeling angry right now'? Uh-huh, I think I get it.",ar:"ألاحظها... مثل، 'أشعر بالغضب الآن'؟ أها، أظن أنني فهمت."},{s:0,t:"Exactly! Naming an emotion takes away some of its power. Try it this week. Write it down if it helps.",ar:"بالضبط! تسمية العاطفة تسلب بعضًا من قوتها. جرب ذلك هذا الأسبوع. اكتبها إذا كان ذلك يساعد."},{s:1,t:"Okay, I'll try. Is there anything else I should do? I want to do this properly.",ar:"حسنًا، سأجرب. هل هناك أي شيء آخر يجب أن أفعله؟ أريد أن أفعل هذا بشكل صحيح."},{s:0,t:"Two small things. Walk for twenty minutes a day, and write down three good things each night. It's a simple technique, but it works.",ar:"شيئان صغيران. امشِ عشرين دقيقة يوميًا، واكتب ثلاثة أشياء جيدة كل ليلة. إنها تقنية بسيطة، لكنها تعمل."},{s:1,t:"Three good things? Even on bad days? What if I can't think of any?",ar:"ثلاثة أشياء جيدة؟ حتى في الأيام السيئة؟ ماذا لو لم أستطع التفكير في أي منها؟"},{s:0,t:"Especially on bad days. It trains your brain to notice the good. Possibly the best ten minutes of your day.",ar:"خاصة في الأيام السيئة. إنه يدرب عقلك على ملاحظة الجيد. ربما أفضل عشر دقائق في يومك."},{s:1,t:"That sounds simple. Almost too simple. But I'm gonna try it — I trust you.",ar:"هذا يبدو بسيطًا. بسيطًا جدًا تقريبًا. لكنني سأجربه — أثق بك."},{s:0,t:"Simple doesn't mean easy. But it works — the research is clear on that. The statistics are strong: most people feel better in a month. Shine a light on the good moments, and they grow.",ar:"بسيط لا يعني سهلًا. لكنه يعمل — البحث واضح في ذلك. الإحصاءات قوية: معظم الناس يشعرون بتحسن خلال شهر. ألقِ الضوء على اللحظات الجيدة، وستنمو."},{s:1,t:"All right. I'll give it a real try. When do I see you again? Same time next week?",ar:"حسنًا. سأجربه بجدية. متى أراك مجددًا؟ في الوقت نفسه الأسبوع المقبل؟"},{s:0,t:"Next Tuesday, same time. And remember — progress is slow, and that's okay. Be patient with yourself.",ar:"الثلاثاء المقبل، في الوقت نفسه. وتذكر — التقدم بطيء، وهذا جيد. كن صبورًا مع نفسك."},{s:1,t:"Slow is okay. I can live with that. Thank you, doctor. I feel slightly better already, just from talking.",ar:"بطيء جيد. يمكنني التعايش مع ذلك. شكرًا، دكتور. أشعر بتحسن طفيف بالفعل، من مجرد التحدث."},{s:0,t:"You're welcome. Take care of yourself this week. And if things get worse, call me — any time, day or night.",ar:"على الرحب. اعتنِ بنفسك هذا الأسبوع. وإذا ساءت الأمور، اتصل بي — في أي وقت، ليلًا أو نهارًا."},{s:1,t:"I will. Goodbye!",ar:"سأفعل. إلى اللقاء!"},{s:0,t:"Goodbye!",ar:"إلى اللقاء!"}]}},{stage:15,topic:"street",topicAr:"كلام الشارع",topicEn:"Street Talk",topicDe:"Street Talk",emoji:"",title:"شجار حول المال",grammar:{id:"en-b1-second-conditional",title:"Second conditional",titleAr:"الشرط الثاني",covers:1},conv:{id:"en-stage15-b1",speakers:["Alex (أليكس)","Chris (كريس)"],turns:[{s:0,t:"Chris, where's my money? It's been three months.",ar:"كريس، أين أموالي؟ لقد مرت ثلاثة أشهر."},{s:1,t:"Relax, Alex. I'll pay you back. I just need more time.",ar:"اهدأ يا أليكس. سأعيد لك المال. أحتاج فقط إلى مزيد من الوقت."},{s:0,t:"More time? You said that last month! And the month before!",ar:"مزيد من الوقت؟ قلت ذلك الشهر الماضي! والشهر الذي قبله!"},{s:1,t:"I know, I know. Things are just tight right now.",ar:"أعرف، أعرف. الأمور ضيقة الآن فحسب."},{s:0,t:"Tight? You just bought a new phone! Don't lie to me.",ar:"ضيقة؟ لقد اشتريت هاتفًا جديدًا للتو! لا تكذب عليّ."},{s:1,t:"That was different. I needed it for work.",ar:"كان ذلك مختلفًا. كنت أحتاجه للعمل."},{s:0,t:"Bullshit. You spent MY money on yourself.",ar:"هراء. أنفقت أموالي على نفسك."},{s:1,t:"Don't talk to me like that. I'm not your bitch.",ar:"لا تتحدث معي هكذا. لستُ كلبتك."},{s:0,t:"Then act like a friend! A real friend pays back what he owes.",ar:"إذن تصرف كصديق! الصديق الحقيقي يعيد ما عليه."},{s:1,t:"Fine! You want the truth? I lost the money. I gambled it.",ar:"حسنًا! تريد الحقيقة؟ خسرت المال. قامرت به."},{s:0,t:"You WHAT? You gambled my money? You bastard!",ar:"ماذا فعلت؟ قامرت بأموالي؟ يا وغد!"},{s:1,t:"I'm sorry, man. I'll get it back, I swear.",ar:"أنا آسف يا رجل. سأعيده، أقسم."},{s:0,t:"Fuck your sorry. I want my money by Friday — or we're done.",ar:"تبًا لاعتذارك. أريد أموالي بحلول يوم الجمعة — وإلا انتهينا."},{s:1,t:"Friday. Okay. You'll have it by Friday.",ar:"يوم الجمعة. حسنًا. ستحصل عليه بحلول يوم الجمعة."}]}}],de:[{conv:{id:"de-stage1-b1",speakers:["Bewerber (المتقدم للوظيفة)","Personalchefin (مديرة الموارد البشرية)"],turns:[{ar:"مرحبًا! شكرًا جزيلًا على الدعوة إلى مقابلة العمل.",s:0,t:"Guten Tag! Vielen Dank für die Einladung zum Vorstellungsgespräch."},{ar:"مرحبًا! أهلًا وسهلًا بك. تفضل بالجلوس. كيف حالك اليوم؟",s:1,t:"Guten Tag! Herzlich willkommen. Bitte nehmen Sie Platz. Wie geht es Ihnen heute?"},{ar:"شكرًا، أنا بخير. أنا سعيد جدًا بهذه المقابلة.",s:0,t:"Danke, mir geht es gut. Ich freue mich sehr auf dieses Gespräch."},{ar:"جميل. حدّثني باختصار عن نفسك من فضلك.",s:1,t:"Schön. Erzählen Sie mir bitte kurz etwas über sich."},{ar:"بكل سرور. عملت ثلاث سنوات بائعًا، وكان عليّ أن أقدّم المشورة لكثير من الزبائن.",s:0,t:"Gern. Ich habe drei Jahre als Verkäufer gearbeitet und musste dort viele Kunden beraten."},{ar:"هذا يبدو جيدًا. لماذا أردت تغيير المهنة؟",s:1,t:"Das klingt gut. Warum wollten Sie den Beruf wechseln?"},{ar:"أردت أن أطوّر نفسي. في وظيفتي القديمة لم أستطع للأسف تولّي مهام جديدة.",s:0,t:"Ich wollte mich weiterentwickeln. In meinem alten Job konnte ich leider keine neuen Aufgaben übernehmen."},{ar:"أفهم. ماذا كان عليك أن تفعل كل يوم في وظيفتك الأخيرة؟",s:1,t:"Verstehe. Was mussten Sie in Ihrer letzten Stelle jeden Tag machen?"},{ar:"كان عليّ أن أطلب البضائع، وأتحقق من الأسعار، وأن أحاسب الصندوق في نهاية اليوم.",s:0,t:"Ich musste Waren bestellen, Preise kontrollieren und am Ende des Tages die Kasse abrechnen."},{ar:"وهل كان مسموحًا لك أن تتخذ قرارات بمفردك أيضًا؟",s:1,t:"Und durften Sie auch allein Entscheidungen treffen?"},{ar:"نعم، في المشاكل الصغيرة كان مسموحًا لي أن أقرر بنفسي. أما في المسائل الكبيرة فكان عليّ أن أسأل مديري.",s:0,t:"Ja, bei kleinen Problemen durfte ich selbst entscheiden. Bei großen Fragen musste ich meinen Chef fragen."},{ar:"لماذا تتقدم للعمل عندنا تحديدًا؟",s:1,t:"Warum bewerben Sie sich gerade bei uns?"},{ar:"شركتكم لها سمعة جيدة جدًا. أردت منذ زمن طويل أن أعمل في فريق أكبر.",s:0,t:"Ihre Firma hat einen sehr guten Ruf. Ich wollte schon lange in einem größeren Team arbeiten."},{ar:"ما هي أكبر نقاط قوتك؟",s:1,t:"Was sind Ihre größten Stärken?"},{ar:"أنا صبور وموثوق. في السابق كنت أستطيع حتى تهدئة الزبائن الصعبين.",s:0,t:"Ich bin geduldig und zuverlässig. Früher konnte ich sogar schwierige Kunden beruhigen."},{ar:"وما هي نقطة ضعفك؟",s:1,t:"Und was ist Ihre Schwäche?"},{ar:"في السابق كان عليّ أن أفعل كل شيء بشكل مثالي، لكن الآن أستطيع أن أحدد الأولويات بشكل أفضل.",s:0,t:"Früher musste ich alles perfekt machen, aber jetzt kann ich besser Prioritäten setzen."},{ar:"كيف تتصور يوم عملك عندنا؟",s:1,t:"Wie stellen Sie sich Ihren Arbeitsalltag bei uns vor?"},{ar:"ينبغي أن أقدّم المشورة للزبائن، وأعالج الطلبات، وأتعاون بشكل وثيق مع الفريق.",s:0,t:"Ich sollte Kunden beraten, Bestellungen bearbeiten und im Team eng zusammenarbeiten."},{ar:"هل تستطيع العمل في عطلة نهاية الأسبوع أيضًا؟",s:1,t:"Könnten Sie auch am Wochenende arbeiten?"},{ar:"نعم، كنت أستطيع ذلك في وظيفتي القديمة. يومًا سبت في الشهر ليسا مشكلة.",s:0,t:"Ja, das konnte ich schon in meinem alten Job. Zwei Samstage im Monat sind kein Problem."},{ar:"ما مدى إجادتك للإنجليزية؟ في فريقنا كان علينا غالبًا أن نتحدث مع زبائن أجانب.",s:1,t:"Wie gut sprechen Sie Englisch? In unserem Team mussten wir oft mit ausländischen Kunden sprechen."},{ar:"إنجليزيتي جيدة. استطعت أن أتدرب كثيرًا في المدرسة وفي العمل.",s:0,t:"Mein Englisch ist gut. Ich konnte in der Schule und im Beruf viel üben."},{ar:"هل لديك خبرة بالحاسوب أيضًا؟",s:1,t:"Haben Sie auch Erfahrung mit dem Computer?"},{ar:"نعم، كان عليّ يوميًا أن أعمل بالبريد الإلكتروني والجداول ونظام الصندوق لدينا.",s:0,t:"Ja, ich musste täglich mit E-Mails, Tabellen und unserem Kassensystem arbeiten."},{ar:"ماذا أردت أن تتعلم في الأشهر الأولى عندنا؟",s:1,t:"Was wollten Sie in den ersten Monaten bei uns lernen?"},{ar:"أردت أن أتعرّف على منتجاتكم بدقة وأن أفهم سير العمل في المستودع.",s:0,t:"Ich wollte Ihre Produkte genau kennenlernen und die Abläufe im Lager verstehen."},{ar:"متى تستطيع أن تبدأ العمل عندنا؟",s:1,t:"Wann könnten Sie bei uns anfangen?"},{ar:"أستطيع أن أبدأ في الأول من الشهر القادم. قبل ذلك كان عليّ أن أنهي عقدي القديم.",s:0,t:"Ich könnte am ersten nächsten Monats anfangen. Vorher musste ich noch meinen alten Vertrag beenden."},{ar:"ما هي توقعاتك بالنسبة للراتب؟",s:1,t:"Wie hoch sind Ihre Gehaltsvorstellungen?"},{ar:"ينبغي أن أكون صريحًا: أتمنى راتبًا يناسب خبرتي.",s:0,t:"Ich sollte ehrlich sein: Ich wünsche mir ein Gehalt, das zu meiner Erfahrung passt."},{ar:"هذا عادل. نحن نقدم أيضًا بدل إجازة ودورات تدريبية.",s:1,t:"Das ist fair. Wir bieten zusätzlich Urlaubsgeld und Weiterbildungskurse an."},{ar:"هذا يسعدني جدًا. كان التدريب المستمر مهمًا جدًا بالنسبة لي في وظيفتي القديمة.",s:0,t:"Das freut mich sehr. Weiterbildung war mir in meinem alten Job sehr wichtig."},{ar:"هل لديك أسئلة أخرى لي؟",s:1,t:"Haben Sie noch Fragen an mich?"},{ar:"نعم، كم عدد أفراد الفريق الذي ينبغي أن أعمل فيه؟",s:0,t:"Ja, wie groß ist das Team, in dem ich arbeiten sollte?"},{ar:"الفريق يتكون من ثمانية أشخاص. ينبغي أن تعمل بشكل وثيق مع زميلين.",s:1,t:"Das Team hat acht Personen. Sie sollten eng mit zwei Kollegen zusammenarbeiten."},{ar:"يبدو جيدًا جدًا. هل كان مسموحًا بالعمل من المنزل عندكم؟",s:0,t:"Klingt sehr gut. Durfte man bei Ihnen auch im Homeoffice arbeiten?"},{ar:"يوم واحد في الأسبوع ممكن، لكن في المتجر كان علينا أن نكون حاضرين دائمًا.",s:1,t:"Einen Tag pro Woche ist möglich, aber im Laden mussten wir immer vor Ort sein."},{ar:"أنا أفهم ذلك. أردت أيضًا أن أعمل مباشرة مع الزبائن.",s:0,t:"Das verstehe ich. Ich wollte auch gern direkt mit Kunden arbeiten."},{ar:"جيد جدًا. سنتصل بك حتى نهاية الأسبوع.",s:1,t:"Sehr gut. Wir melden uns bis Ende der Woche bei Ihnen."},{ar:"شكرًا جزيلًا على المقابلة اللطيفة. أنا متحمس لردكم.",s:0,t:"Vielen Dank für das freundliche Gespräch. Ich freue mich auf Ihre Antwort."},{ar:"شكرًا لك أيضًا. أتمنى لك يومًا سعيدًا!",s:1,t:"Danke auch Ihnen. Ich wünsche Ihnen noch einen schönen Tag!"}]},emoji:"💼",grammar:{covers:1,id:"de-b1-modalverben-vergangenheit",title:"Modalverben in der Vergangenheit",titleAr:"الأفعال الناقصة في الماضي"},stage:1,title:"مقابلة عمل",topic:"jobs",topicAr:"المهن والعمل",topicDe:"Vorstellungsgespräch",topicEn:"Job interview"},{conv:{id:"de-stage2-b1",speakers:["Patient (المريض)","Ärztin (الطبيبة)"],turns:[{ar:"صباح الخير! لدي موعد في الساعة العاشرة، لأنني أعاني من صداع شديد منذ ثلاثة أيام.",s:0,t:"Guten Morgen! Ich habe einen Termin um zehn Uhr, weil ich seit drei Tagen starke Kopfschmerzen habe."},{ar:"صباح الخير! تفضل بالجلوس. أخبرني ما الذي يؤلمك.",s:1,t:"Guten Morgen! Bitte setzen Sie sich. Erzählen Sie mir, was Ihnen fehlt."},{ar:"أعاني من الصداع وأشعر بتعب شديد، رغم أنني نمت ثماني ساعات الليلة الماضية.",s:0,t:"Ich habe Kopfschmerzen und fühle mich sehr müde, obwohl ich letzte Nacht acht Stunden geschlafen habe."},{ar:"منذ متى تشعر بالألم بالضبط؟",s:1,t:"Seit wann haben Sie die Schmerzen genau?"},{ar:"بدأ الألم يوم الاثنين، لأنني عملت على الحاسوب لفترة طويلة جدًا في عطلة نهاية الأسبوع.",s:0,t:"Die Schmerzen haben am Montag angefangen, weil ich am Wochenende sehr lange am Computer gearbeitet habe."},{ar:"هل لديك حمى أو سعال أيضًا؟",s:1,t:"Haben Sie auch Fieber oder Husten?"},{ar:"لا، ليس لدي حمى، رغم أن حلقي يؤلمني قليلًا.",s:0,t:"Nein, ich habe kein Fieber, obwohl mein Hals ein bisschen weh tut."},{ar:"هل تتناول أدوية بانتظام؟",s:1,t:"Nehmen Sie regelmäßig Medikamente?"},{ar:"لا، أتناول أحيانًا فقط حبة مسكن، لأن الألم يختفي بعدها لبضع ساعات.",s:0,t:"Nein, ich nehme nur manchmal eine Schmerztablette, weil die Schmerzen dann für ein paar Stunden weggehen."},{ar:"هل تشرب ماءً كافيًا خلال اليوم؟",s:1,t:"Trinken Sie genug Wasser während des Tages?"},{ar:"ربما لا، لأنني في المكتب أنسى غالبًا أن أشرب.",s:0,t:"Wahrscheinlich nicht, weil ich im Büro oft vergesse zu trinken."},{ar:"قد يكون هذا سببًا. سأقيس ضغط دمك الآن، رغم أنك تشعر بصحة جيدة في العادة.",s:1,t:"Das kann ein Grund sein. Ich messe jetzt Ihren Blutdruck, obwohl Sie sich sonst gesund fühlen."},{ar:"هل ضغط الدم طبيعي؟",s:0,t:"Ist der Blutdruck in Ordnung?"},{ar:"نعم، ضغط الدم طبيعي. سأستمع إلى قلبك الآن، لأنني أريد أن أتأكد أن كل شيء بخير.",s:1,t:"Ja, der Blutdruck ist normal. Ich höre jetzt Ihr Herz ab, weil ich sicher sein will, dass alles gut ist."},{ar:"أنا قلق، لأن والدي كان يعاني كثيرًا من الصداع أيضًا.",s:0,t:"Ich mache mir Sorgen, weil mein Vater auch oft Kopfschmerzen hatte."},{ar:"أفهم ذلك، لكن قيمك جيدة، رغم أن الألم مستمر منذ ثلاثة أيام.",s:1,t:"Das verstehe ich, aber Ihre Werte sind gut, obwohl die Schmerzen schon drei Tage dauern."},{ar:"هل يجب أن أجري تحليل دم؟",s:0,t:"Muss ich eine Blutuntersuchung machen?"},{ar:"ليس اليوم، لأن الفحص لا يظهر أي شيء غير طبيعي. سننتظر أولًا.",s:1,t:"Heute nicht, weil die Untersuchung keine Auffälligkeiten zeigt. Wir warten erst einmal ab."},{ar:"ماذا يمكنني أن أفعل ضد الصداع؟",s:0,t:"Was kann ich gegen die Kopfschmerzen tun?"},{ar:"ينبغي أن تشرب ماءً أكثر وأن تأخذ فترات راحة، لأن العمل الطويل على الحاسوب يرهق العينين كثيرًا.",s:1,t:"Sie sollten mehr Wasser trinken und Pausen machen, weil lange Arbeit am Computer die Augen sehr anstrengt."},{ar:"سأحاول ذلك، رغم أنه من الصعب أحيانًا أخذ فترات راحة في المكتب.",s:0,t:"Ich versuche es, obwohl es im Büro manchmal schwer ist, Pausen zu machen."},{ar:"سأصف لك مسكنات خفيفة، لأنك يجب أن تنام بشكل أفضل ليلًا.",s:1,t:"Ich verschreibe Ihnen leichte Schmerztabletten, weil Sie nachts besser schlafen sollen."},{ar:"كم مرة يجب أن أتناول الحبوب؟",s:0,t:"Wie oft soll ich die Tabletten nehmen?"},{ar:"تناول حبة في الصباح وحبة في المساء، لكن لمدة ثلاثة أيام فقط، لأنها قد تُتعب المعدة.",s:1,t:"Nehmen Sie eine Tablette morgens und eine abends, aber nur drei Tage lang, weil sie den Magen belasten können."},{ar:"هل يجب أن أذهب إلى العمل مع ذلك؟",s:0,t:"Soll ich trotzdem zur Arbeit gehen?"},{ar:"نعم، يمكنك العمل رغم الصداع، لكن من فضلك دون ساعات إضافية.",s:1,t:"Ja, Sie können arbeiten, obwohl Sie Kopfschmerzen haben, aber bitte ohne Überstunden."},{ar:"هل يجوز لي أن أمارس الرياضة أيضًا؟",s:0,t:"Darf ich auch Sport machen?"},{ar:"الرياضة الخفيفة جيدة، لأن الحركة تحسّن تدفق الدم. لكن تجنّب المجهود الشاق.",s:1,t:"Leichter Sport ist gut, weil Bewegung die Durchblutung verbessert. Vermeiden Sie aber schwere Anstrengung."},{ar:"أنا آكل قليلًا في الآونة الأخيرة، لأنني لا أشعر بالشهية.",s:0,t:"Ich esse in letzter Zeit auch wenig, weil ich keinen Appetit habe."},{ar:"كُل بانتظام من فضلك، رغم أنك لا تشعر بالجوع. جسمك يحتاج إلى طاقة.",s:1,t:"Essen Sie bitte regelmäßig, obwohl Sie keinen Hunger haben. Ihr Körper braucht Energie."},{ar:"هل هناك شيء يجب أن أتجنبه حتمًا؟",s:0,t:"Gibt es etwas, das ich unbedingt vermeiden sollte?"},{ar:"تجنّب القهوة في المساء، لأن القهوة قد تزعج النوم.",s:1,t:"Vermeiden Sie Kaffee am Abend, weil Kaffee den Schlaf stören kann."},{ar:"متى يجب أن أعود؟",s:0,t:"Wann soll ich wiederkommen?"},{ar:"عُد بعد أسبوع، لأنني أريد حينها أن أرى إن كان الألم قد تحسّن.",s:1,t:"Kommen Sie in einer Woche wieder, weil ich dann sehen will, ob die Schmerzen besser geworden sind."},{ar:"وماذا إن ازداد الألم سوءًا قبل ذلك؟",s:0,t:"Und wenn die Schmerzen vorher schlimmer werden?"},{ar:"حينها تعال فورًا من فضلك، رغم أن لديك موعدًا بعد أسبوع.",s:1,t:"Dann kommen Sie bitte sofort wieder, obwohl Sie schon einen Termin in einer Woche haben."},{ar:"شكرًا جزيلًا على مساعدتك. أشعر بالاطمئنان أكثر، لأنك شرحت كل شيء بدقة.",s:0,t:"Vielen Dank für Ihre Hilfe. Ich fühle mich schon beruhigter, weil Sie alles genau erklärt haben."},{ar:"على الرحب والسعة. أتمنى لك الشفاء العاجل!",s:1,t:"Gern geschehen. Ich wünsche Ihnen gute Besserung!"},{ar:"شكرًا! إلى اللقاء!",s:0,t:"Danke! Auf Wiedersehen!"},{ar:"إلى اللقاء! وتذكّر: اشرب الكثير من الماء وخذ فترات راحة!",s:1,t:"Auf Wiedersehen! Und denken Sie daran: viel Wasser trinken und Pausen machen!"},{ar:"سأفعل ذلك، رغم أن يوم عملي غالبًا ما يكون مزدحمًا جدًا.",s:0,t:"Das werde ich tun, obwohl mein Arbeitstag oft sehr voll ist."},{ar:"أحسنت. إلى الأسبوع القادم!",s:1,t:"Gut so. Bis nächste Woche!"}]},emoji:"🩺",grammar:{covers:1,id:"de-b1-nebensatz-weil-obwohl",title:"Nebensätze mit weil / obwohl",titleAr:"الجمل التابعة مع weil و obwohl"},stage:2,title:"عند الطبيب",topic:"health",topicAr:"الصحة والجسم",topicDe:"Beim Arzt",topicEn:"At the doctor"},{conv:{id:"de-stage3-b1",speakers:["Kunde (الزبون)","Verkäuferin (البائعة)"],turns:[{ar:"مرحبًا! عذرًا، أودّ أن أناقش مشكلة في عملية شراء.",s:0,t:"Guten Tag! Entschuldigung, ich hätte gern ein Problem mit einem Kauf besprochen."},{ar:"مرحبًا! بالطبع، بكل سرور. ما الأمر؟",s:1,t:"Guten Tag! Natürlich, gerne. Worum geht es denn?"},{ar:"اشتريت آلة القهوة هذه أمس، لكنها للأسف لا تعمل بشكل صحيح.",s:0,t:"Ich habe gestern diese Kaffeemaschine gekauft, aber sie funktioniert leider nicht richtig."},{ar:"أنا آسفة لذلك. هل يمكنك أن تُريني من فضلك ما الذي لا يعمل بالضبط؟",s:1,t:"Das tut mir leid. Könnten Sie mir bitte zeigen, was genau nicht funktioniert?"},{ar:"نعم، بكل سرور. الماء لا يسخن، والقهوة طعمها بارد، رغم أنني ضبطت كل شيء بشكل صحيح.",s:0,t:"Ja, gern. Das Wasser wird nicht heiß, und der Kaffee schmeckt kalt, obwohl ich alles richtig eingestellt habe."},{ar:"أفهم. هل معك إيصال الشراء من فضلك؟",s:1,t:"Verstehe. Hätten Sie bitte den Kassenbon dabei?"},{ar:"نعم، ها هو. أودّ أن أستبدل الآلة أو أعيدها.",s:0,t:"Ja, hier ist er. Ich würde die Maschine gern umtauschen oder zurückgeben."},{ar:"لا مشكلة. هل تفضل أن تحصل على جهاز جديد أم أن تسترد أموالك؟",s:1,t:"Kein Problem. Würden Sie lieber ein neues Gerät haben oder Ihr Geld zurückbekommen?"},{ar:"سأكون راضيًا بجهاز جديد، إن كان يعمل بشكل جيد.",s:0,t:"Ich wäre mit einem neuen Gerät zufrieden, wenn es gut funktioniert."},{ar:"بالطبع. هل يمكنني أن أختبر الآلة هنا بسرعة؟",s:1,t:"Selbstverständlich. Könnte ich kurz die Maschine hier testen?"},{ar:"نعم، من فضلك. سيكون من الجيد أن نفحص ذلك معًا.",s:0,t:"Ja, bitte. Es wäre schön, wenn wir das zusammen prüfen könnten."},{ar:"أرى المشكلة: السخان لا يبدأ. يبدو أن هذا عيب مصنع.",s:1,t:"Ich sehe das Problem: Die Heizung startet nicht. Das dürfte ein Fabrikfehler sein."},{ar:"هذا بالضبط ما ظننته أنا أيضًا. هل يمكنك أن تُريني من فضلك موديلًا آخر؟",s:0,t:"Genau das habe ich auch gedacht. Würden Sie mir bitte ein anderes Modell zeigen?"},{ar:"بكل سرور. هذا الموديل هنا مشهور جدًا. هل يعجبك؟",s:1,t:"Gern. Dieses Modell hier ist sehr beliebt. Würde Ihnen das gefallen?"},{ar:"يبدو جيدًا، لكنه أغلى قليلًا. هل يمكنك أن تشرح لي فرق السعر؟",s:0,t:"Es sieht gut aus, aber es ist etwas teurer. Könnten Sie mir den Preisunterschied erklären?"},{ar:"بالطبع. هذا الموديل يكلف عشرين يورو أكثر، لكنه سيكون بضمان أطول.",s:1,t:"Natürlich. Dieses Modell kostet zwanzig Euro mehr, aber es hätte eine längere Garantie."},{ar:"همم، سأحتاج إلى التفكير في ذلك. هل من الممكن أن أحصل على نفس الموديل مرة أخرى؟",s:0,t:"Hm, ich müsste darüber nachdenken. Wäre es möglich, das gleiche Modell noch einmal zu bekommen?"},{ar:"نعم، لن يكون ذلك مشكلة. لدينا ثلاث قطع أخرى في المخزون.",s:1,t:"Ja, das wäre kein Problem. Wir haben noch drei Stück auf Lager."},{ar:"إذن سآخذ نفس الموديل بكل سرور. هل يمكنك أن تختبره مرة أخرى من أجلي من فضلك؟",s:0,t:"Dann nehme ich gern das gleiche Modell. Könnten Sie es bitte noch einmal für mich testen?"},{ar:"بكل سرور، سأختبره فورًا. لحظة من فضلك.",s:1,t:"Gern, ich teste es sofort. Einen Moment bitte."},{ar:"شكرًا جزيلًا. آمل أن يعمل هذا الجهاز بشكل أفضل.",s:0,t:"Vielen Dank. Ich hoffe, dass dieses Gerät besser funktioniert."},{ar:"إنه يعمل بشكل مثالي. الماء يسخن، والقهوة دافئة. هل توافق على ذلك؟",s:1,t:"Es funktioniert perfekt. Das Wasser wird heiß, und der Kaffee ist warm. Wären Sie damit einverstanden?"},{ar:"نعم، بكل سرور. هل يمكنني أن أمدّد الضمان أيضًا من فضلك؟",s:0,t:"Ja, sehr gern. Könnte ich bitte auch die Garantie verlängern?"},{ar:"نعم، سيكون ذلك ممكنًا مقابل عشرة يورو. هل ترغب في ذلك؟",s:1,t:"Ja, das wäre für zehn Euro möglich. Möchten Sie das?"},{ar:"نعم، هذا مهم جدًا بالنسبة لي، لأنني أستخدم الآلة كل يوم.",s:0,t:"Ja, das wäre mir sehr wichtig, weil ich die Maschine jeden Tag benutze."},{ar:"حسنًا، سأسجّل ذلك. هل تريد شيئًا آخر؟ ربما حبوب قهوة؟",s:1,t:"Gut, ich trage das ein. Möchten Sie noch etwas anderes? Vielleicht Kaffeebohnen?"},{ar:"شكرًا، هذا لطف منك، لكن اليوم أحتاج الآلة فقط.",s:0,t:"Danke, das wäre nett, aber heute brauche ich nur die Maschine."},{ar:"حسنًا. سأغلّف الجهاز الجديد لك. هل تحتاج كيسًا؟",s:1,t:"Alles klar. Ich packe das neue Gerät für Sie ein. Brauchen Sie eine Tüte?"},{ar:"لا، شكرًا. أريد فقط الإيصال الجديد.",s:0,t:"Nein, danke. Ich hätte gern nur den neuen Kassenbon."},{ar:"ها هو. الضمان ساري من اليوم لمدة سنتين.",s:1,t:"Hier ist er. Die Garantie gilt ab heute zwei Jahre."},{ar:"هل يمكنك أن تعطيني رقم هاتفك من فضلك، في حال حدوث مشاكل مرة أخرى؟",s:0,t:"Würden Sie mir bitte noch Ihre Telefonnummer geben, falls es wieder Probleme gibt?"},{ar:"بالطبع. هذه بطاقتنا وفيها الرقم. يمكنك الاتصال بنا في أي وقت.",s:1,t:"Natürlich. Hier ist unsere Karte mit der Nummer. Sie könnten uns jederzeit anrufen."},{ar:"شكرًا جزيلًا على مساعدتك اللطيفة. سيكون جميلًا لو كانت كل المحلات متعاونة هكذا.",s:0,t:"Vielen Dank für Ihre freundliche Hilfe. Es wäre schön, wenn alle Geschäfte so hilfsbereit wären."},{ar:"يسعدني سماع ذلك. أتمنى لك متعة كبيرة مع الآلة الجديدة!",s:1,t:"Das freut mich zu hören. Ich wünsche Ihnen viel Freude mit der neuen Maschine!"},{ar:"شكرًا! سأوصي بالمحل بالتأكيد.",s:0,t:"Danke! Ich würde das Geschäft auf jeden Fall weiterempfehlen."},{ar:"شكرًا جزيلًا! أتمنى لك يومًا سعيدًا!",s:1,t:"Vielen Dank! Einen schönen Tag noch!"},{ar:"لك أيضًا! إلى اللقاء!",s:0,t:"Ihnen auch! Auf Wiedersehen!"},{ar:"إلى اللقاء!",s:1,t:"Auf Wiedersehen!"},{ar:"آه، سؤال آخر: هل يمكنني أن أترك الآلة القديمة هنا؟",s:0,t:"Ach, eine Frage noch: Könnte ich die alte Maschine hier lassen?"},{ar:"نعم، بالطبع. سنعتني بالتخلص منها. لن يكون ذلك مشكلة.",s:1,t:"Ja, natürlich. Wir kümmern uns um die Entsorgung. Das wäre kein Problem."},{ar:"ممتاز، شكرًا مرة أخرى!",s:0,t:"Perfekt, vielen Dank noch einmal!"},{ar:"على الرحب والسعة!",s:1,t:"Gern geschehen!"}]},emoji:"🛍️",grammar:{covers:1,id:"de-b1-konjunktiv2-hoeflich",title:"Konjunktiv II: höfliche Bitten",titleAr:"صيغة التمني: الطلبات المهذبة"},stage:3,title:"شكوى في المحل",topic:"services",topicAr:"الخدمات والطوارئ",topicDe:"Reklamation im Geschäft",topicEn:"Complaint in a shop"},{conv:{id:"de-stage4-b1",speakers:["Wohnungssuchender (الباحث عن شقة)","Vermieterin (صاحبة الشقة)"],turns:[{ar:"مرحبًا! أنا مهتم بالشقة التي عرضتِها على الإنترنت.",s:0,t:"Guten Tag! Ich interessiere mich für die Wohnung, die Sie im Internet angeboten haben."},{ar:"مرحبًا! أهلًا وسهلًا بك. تفضل بالدخول. الشقة التي نؤجرها في الطابق الثاني.",s:1,t:"Guten Tag! Herzlich willkommen. Kommen Sie bitte herein. Die Wohnung, die wir vermieten, ist im zweiten Stock."},{ar:"شكرًا! كم مساحة الشقة المتاحة هنا؟",s:0,t:"Danke! Wie groß ist die Wohnung, die hier frei ist?"},{ar:"مساحة الشقة 65 مترًا مربعًا ولها ثلاث غرف، وكلها مضيئة ومريحة.",s:1,t:"Die Wohnung hat 65 Quadratmeter und drei Zimmer, die alle hell und freundlich sind."},{ar:"هذا يبدو جيدًا. هل توجد شرفة يمكن الجلوس عليها في الصيف؟",s:0,t:"Das klingt gut. Gibt es einen Balkon, auf dem man im Sommer sitzen kann?"},{ar:"نعم، توجد شرفة تطل على الجنوب وهي مشمسة جدًا.",s:1,t:"Ja, es gibt einen Balkon, der nach Süden zeigt und sehr sonnig ist."},{ar:"رائع! كيف هو المطبخ الذي ينتمي إلى الشقة؟",s:0,t:"Wunderbar! Wie ist die Küche, die zur Wohnung gehört?"},{ar:"المطبخ الذي تراه هنا جديد. فيه موقد وثلاجة وغسالة صحون.",s:1,t:"Die Küche, die Sie hier sehen, ist neu. Sie hat einen Herd, einen Kühlschrank und eine Spülmaschine."},{ar:"هذا عملي. هل الحمام الذي يقع بجانب غرفة النوم كبير بما فيه الكفاية؟",s:0,t:"Das ist praktisch. Ist das Bad, das neben dem Schlafzimmer liegt, groß genug?"},{ar:"نعم، الحمام فيه دش وحوض استحمام، وكلاهما جديد.",s:1,t:"Ja, das Bad hat eine Dusche und eine Badewanne, die beide neu sind."},{ar:"كم إيجار الشقة التي أعاينها الآن؟",s:0,t:"Wie hoch ist die Miete für die Wohnung, die ich gerade besichtige?"},{ar:"الإيجار الأساسي 650 يورو. وتضاف إليه تكاليف إضافية 150 يورو، تشمل التدفئة والماء.",s:1,t:"Die Kaltmiete beträgt 650 Euro. Dazu kommen Nebenkosten von 150 Euro, in denen Heizung und Wasser enthalten sind."},{ar:"هل يجب أن أدفع تأمينًا أسترده في النهاية؟",s:0,t:"Muss ich eine Kaution zahlen, die ich am Ende zurückbekomme?"},{ar:"نعم، التأمين يعادل إيجار شهرين، تدفعه عند الانتقال.",s:1,t:"Ja, die Kaution beträgt zwei Monatsmieten, die Sie bei Einzug überweisen."},{ar:"أفهم. كيف هو الموقع؟ هل يوجد سوبرماركت قريب؟",s:0,t:"Verstehe. Wie ist die Lage? Gibt es einen Supermarkt, der in der Nähe ist?"},{ar:"نعم، يوجد سوبرماركت يبعد خمس دقائق فقط سيرًا على الأقدام.",s:1,t:"Ja, es gibt einen Supermarkt, der nur fünf Minuten zu Fuß entfernt ist."},{ar:"ومحطة الحافلات التي يمكن منها الوصول إلى المدينة، هل هي بعيدة؟",s:0,t:"Und die Bushaltestelle, von der man in die Stadt kommt, ist sie weit weg?"},{ar:"لا، محطة الحافلات التي أمام المنزل مباشرة تغادر كل عشر دقائق.",s:1,t:"Nein, die Bushaltestelle, die direkt vor dem Haus ist, fährt alle zehn Minuten."},{ar:"هذا جيد جدًا. هل الحيوانات الأليفة مسموحة، التي يمكن أن تعيش في الشقة؟",s:0,t:"Das ist sehr gut. Sind Haustiere erlaubt, die in der Wohnung leben dürfen?"},{ar:"الحيوانات الأليفة الصغيرة مسموحة. أما كلب ينبح بصوت عالٍ جدًا فسيكون مشكلة.",s:1,t:"Kleine Haustiere sind erlaubt. Ein Hund, der sehr laut bellt, wäre allerdings ein Problem."},{ar:"ليس لدي حيوانات أليفة. أعمل في مكتب ليس بعيدًا من هنا.",s:0,t:"Ich habe keine Haustiere. Ich arbeite im Büro, das nicht weit von hier ist."},{ar:"هذا مثالي. من متى تريد الانتقال؟",s:1,t:"Das ist ideal. Ab wann möchten Sie einziehen?"},{ar:"يمكنني الانتقال من الأول من الشهر القادم. هل هذا ممكن؟",s:0,t:"Ich könnte ab dem ersten nächsten Monats einziehen. Ist das möglich?"},{ar:"نعم، الشقة التي تراها اليوم ستكون متاحة من الأول.",s:1,t:"Ja, die Wohnung, die Sie heute sehen, ist ab dem ersten frei."},{ar:"ما هي المستندات التي تحتاجينها مني والتي يجب أن أحضرها؟",s:0,t:"Welche Unterlagen brauchen Sie von mir, die ich mitbringen soll?"},{ar:"أحتاج إلى بطاقة هويتك، وشهادة راتب، وتقرير ائتماني لا يزيد عمره عن ثلاثة أشهر.",s:1,t:"Ich brauche Ihren Ausweis, eine Gehaltsbescheinigung und eine Schufa-Auskunft, die nicht älter als drei Monate ist."},{ar:"لا مشكلة. لدي كل المستندات التي تحتاجينها في المنزل بالفعل.",s:0,t:"Kein Problem. Ich habe alle Dokumente, die Sie brauchen, schon zu Hause."},{ar:"جيد جدًا. من سينتقل معك؟ هل تعيش بمفردك؟",s:1,t:"Sehr gut. Wer zieht mit Ihnen ein? Wohnen Sie allein?"},{ar:"نعم، أعيش بمفردي. أبحث عن شقة هادئة يمكنني العمل فيها بشكل جيد.",s:0,t:"Ja, ich wohne allein. Ich suche eine ruhige Wohnung, in der ich gut arbeiten kann."},{ar:"المنزل هادئ جدًا. الجيران الذين يعيشون هنا ودودون وهادئون.",s:1,t:"Das Haus ist sehr ruhig. Die Nachbarn, die hier wohnen, sind freundlich und leise."},{ar:"هل يوجد قبو يمكنني أن أضع فيه دراجتي؟",s:0,t:"Gibt es einen Keller, in dem ich mein Fahrrad abstellen kann?"},{ar:"نعم، يوجد قبو للدراجات يمكن لجميع المستأجرين استخدامه.",s:1,t:"Ja, es gibt einen Fahrradkeller, den alle Mieter benutzen dürfen."},{ar:"ممتاز! هل الإنترنت المتاح في المنزل سريع؟",s:0,t:"Perfekt! Ist das Internet, das im Haus verfügbar ist, schnell?"},{ar:"نعم، توجد ألياف ضوئية. التوصيلة التي تحتاجها موجودة بالفعل في الشقة.",s:1,t:"Ja, es gibt Glasfaser. Der Anschluss, den Sie brauchen, ist schon in der Wohnung."},{ar:"هذا يسعدني. هل يمكنني أن أرى غرفة النوم التي تقع في نهاية الممر؟",s:0,t:"Das freut mich. Darf ich noch das Schlafzimmer sehen, das am Ende des Flurs liegt?"},{ar:"بالطبع، تعال معي. الغرفة التي تراها الآن هي أكبر غرفة في الشقة.",s:1,t:"Natürlich, kommen Sie mit. Das Zimmer, das Sie jetzt sehen, ist das größte Zimmer der Wohnung."},{ar:"إنها جميلة ومضيئة حقًا. أعجبتني كثيرًا الشقة التي عاينتها اليوم.",s:0,t:"Sie ist wirklich schön und hell. Ich mag die Wohnung, die ich heute besichtigt habe, sehr."},{ar:"هذا يسعدني! هل تريد أن تأخذ الشقة؟",s:1,t:"Das freut mich! Möchten Sie die Wohnung nehmen?"},{ar:"نعم، بكل سرور. متى يمكنني توقيع عقد الإيجار الذي ستجهزينه؟",s:0,t:"Ja, sehr gern. Wann kann ich den Mietvertrag unterschreiben, den Sie vorbereiten?"},{ar:"سأرسل لك العقد الذي سأجهزه غدًا عبر البريد الإلكتروني.",s:1,t:"Ich schicke Ihnen den Vertrag, den ich morgen vorbereite, per E-Mail zu."},{ar:"شكرًا جزيلًا! أنا متحمس بالفعل للشقة التي سأسكن فيها قريبًا.",s:0,t:"Vielen Dank! Ich freue mich schon auf die Wohnung, in der ich bald wohnen werde."},{ar:"أنا سعيدة أيضًا. مرحبًا بك في المنزل! إلى اللقاء!",s:1,t:"Ich freue mich auch. Willkommen im Haus! Auf Wiedersehen!"},{ar:"إلى اللقاء وشكرًا جزيلًا على المعاينة!",s:0,t:"Auf Wiedersehen und vielen Dank für die Besichtigung!"}]},emoji:"🏠",grammar:{covers:1,id:"de-b1-relativsatz",title:"Relativsätze",titleAr:"الجمل الموصولة"},stage:4,title:"البحث عن شقة",topic:"home",topicAr:"المنزل والسكن",topicDe:"Wohnungssuche",topicEn:"Flat hunting"},{conv:{id:"de-stage5-b1",speakers:["Anrufer (المتصل)","Empfangsdame (موظفة الاستقبال)"],turns:[{ar:"مرحبًا، أريد أن أحجز موعدًا.",s:0,t:"Guten Tag, ich möchte gern einen Termin vereinbaren."},{ar:"مرحبًا، هذه عيادة الدكتور شنايدر. ما الأمر؟",s:1,t:"Guten Tag, das ist die Praxis Dr. Schneider. Worum geht es denn?"},{ar:"أعاني منذ ثلاثة أيام من صداع شديد وأحاول أن أرى الطبيب في أسرع وقت ممكن.",s:0,t:"Ich habe seit drei Tagen starke Kopfschmerzen und versuche, so schnell wie möglich einen Arzt zu sehen."},{ar:"يؤسفني ذلك. هل تنوي المجيء اليوم، أم يناسبك الغد أكثر؟",s:1,t:"Das tut mir leid. Haben Sie vor, heute noch zu kommen, oder passt Ihnen morgen besser?"},{ar:"آمل أن أحصل على موعد اليوم، لأن الألم يزداد سوءًا.",s:0,t:"Ich hoffe, heute noch einen Termin zu bekommen, weil die Schmerzen immer stärker werden."},{ar:"أفهم ذلك. من المهم أن نتصرف بسرعة. سأنظر في التقويم لحظة.",s:1,t:"Ich verstehe. Es ist wichtig, schnell zu handeln. Ich schaue kurz in den Kalender."},{ar:"شكرًا جزيلًا. سأنتظر لحظة بكل سرور.",s:0,t:"Vielen Dank. Ich warte gern einen Moment."},{ar:"لدينا اليوم موعد شاغر في الساعة الرابعة والنصف عصرًا. هل يناسبك؟",s:1,t:"Heute haben wir noch einen freien Termin um 16:30 Uhr. Passt Ihnen das?"},{ar:"في الرابعة والنصف من الصعب عليّ أن أصل في الوقت المحدد. يجب أن أنهي عملي في الرابعة أولًا.",s:0,t:"Um 16:30 Uhr ist es schwierig für mich, pünktlich zu sein. Ich muss erst um 16 Uhr Feierabend machen."},{ar:"لا مشكلة. يوجد أيضًا موعد في الخامسة والربع. هل هذا أفضل لك؟",s:1,t:"Kein Problem. Es gibt auch noch einen Termin um 17:15 Uhr. Ist das besser für Sie?"},{ar:"نعم، هذا يبدو جيدًا. قررت أن آتي في الخامسة والربع.",s:0,t:"Ja, das klingt gut. Ich entscheide mich, um 17:15 Uhr zu kommen."},{ar:"جيد جدًا. هل يمكنني تدوين اسمك وتاريخ ميلادك من فضلك؟",s:1,t:"Sehr gut. Darf ich bitte Ihren Namen und Ihr Geburtsdatum notieren?"},{ar:"بالطبع. اسمي يوناس بيكر، وقد وُلدت في 3 مايو 1990.",s:0,t:"Natürlich. Mein Name ist Jonas Becker, und ich bin am 3. Mai 1990 geboren."},{ar:"شكرًا. هل أنت مريض لدينا من قبل، أم تأتي إلينا لأول مرة؟",s:1,t:"Danke. Sind Sie bei uns schon Patient, oder kommen Sie zum ersten Mal zu uns?"},{ar:"آتي لأول مرة. أنوي أن أسجّل نفسي لديكم اليوم.",s:0,t:"Ich komme zum ersten Mal. Ich habe vor, mich heute bei Ihnen anzumelden."},{ar:"حسنًا. أحضر بطاقة التأمين الصحي من فضلك. من الضروري إظهارها في الزيارة الأولى.",s:1,t:"Alles klar. Dann bringen Sie bitte Ihre Versicherungskarte mit. Es ist notwendig, sie beim ersten Besuch zu zeigen."},{ar:"لا مشكلة، سأحضرها معي. هل يجب أن أحضر شيئًا آخر؟",s:0,t:"Kein Problem, ich werde sie mitbringen. Muss ich noch etwas anderes mitbringen?"},{ar:"من المفيد أن تحضر قائمة بأدويتك، إذا كنت تتناول أيًا منها.",s:1,t:"Es ist hilfreich, eine Liste Ihrer Medikamente mitzubringen, falls Sie welche nehmen."},{ar:"نعم، أتناول دواءً للصداع. سأحضر العلبة معي.",s:0,t:"Ja, ich nehme ein Medikament gegen Kopfschmerzen. Ich werde die Packung mitbringen."},{ar:"جيد جدًا. حاول أن تكون هنا قبل الموعد بعشر دقائق من فضلك.",s:1,t:"Sehr gut. Versuchen Sie bitte, zehn Minuten vor dem Termin da zu sein."},{ar:"سأحاول ذلك. هل يجب أن أملأ شيئًا مسبقًا؟",s:0,t:"Das werde ich versuchen. Muss ich vorher noch etwas ausfüllen?"},{ar:"نعم، نطلب من المرضى الجدد ملء استمارة. يستغرق ذلك خمس دقائق فقط.",s:1,t:"Ja, wir bitten neue Patienten, ein Formular auszufüllen. Das dauert nur fünf Minuten."},{ar:"لا مشكلة. هل توجد مواقف سيارات بالقرب من العيادة؟",s:0,t:"Kein Problem. Gibt es Parkplätze in der Nähe der Praxis?"},{ar:"نعم، أمام المبنى مباشرة توجد ثلاثة مواقف. لكن غالبًا ما يكون من الصعب إيجاد مكان هناك.",s:1,t:"Ja, direkt vor dem Haus gibt es drei Parkplätze. Es ist aber oft schwierig, dort einen Platz zu finden."},{ar:"إذن سآتي بالحافلة. من الأسهل المجيء بوسائل النقل العام.",s:0,t:"Dann fahre ich lieber mit dem Bus. Es ist einfacher, mit öffentlichen Verkehrsmitteln zu kommen."},{ar:"فكرة جيدة. محطة التوقف تبعد عنا دقيقتين فقط.",s:1,t:"Gute Idee. Die Haltestelle ist nur zwei Minuten von uns entfernt."},{ar:"ممتاز. هل يمكنك تأكيد الوقت مرة أخرى من فضلك؟",s:0,t:"Perfekt. Könnten Sie mir bitte noch einmal die Uhrzeit bestätigen?"},{ar:"بكل سرور. موعدك اليوم في الخامسة والربع مساءً مع الدكتور شنايدر.",s:1,t:"Gern. Ihr Termin ist heute um 17:15 Uhr bei Dr. Schneider."},{ar:"شكرًا جزيلًا. وإذا تأخرت، هل أتصل بكم؟",s:0,t:"Danke schön. Und falls ich mich verspäte, soll ich dann anrufen?"},{ar:"نعم، اتصل بنا من فضلك إذا تأخرت. سنحاول حينها تأجيل الموعد.",s:1,t:"Ja, bitte rufen Sie uns an, wenn Sie sich verspäten. Wir versuchen dann, den Termin zu verschieben."},{ar:"حسنًا. آمل أن أكون هناك في الوقت المحدد.",s:0,t:"Alles klar. Ich hoffe, pünktlich da zu sein."},{ar:"نتطلع إلى زيارتك. أتمنى لك الشفاء العاجل حتى بعد ظهر اليوم!",s:1,t:"Wir freuen uns auf Ihren Besuch. Gute Besserung bis heute Nachmittag!"},{s:0,t:"Noch eine Frage: Wie lange ist die Praxis heute geöffnet?",ar:"سؤال آخر: كم من الوقت تبقى العيادة مفتوحة اليوم؟"},{s:1,t:"Wir haben heute bis 18 Uhr geöffnet. Es ist also kein Problem, um 17:15 Uhr zu kommen.",ar:"نحن مفتوحون اليوم حتى السادسة مساءً. إذن لا مشكلة في المجيء في الخامسة والربع."},{s:0,t:"Gut. Und falls die Schmerzen schlimmer werden, soll ich dann früher kommen?",ar:"حسنًا. وإذا ازداد الألم سوءًا، هل يجب أن آتي في وقت أبكر؟"},{s:1,t:"Ja, dann rufen Sie uns bitte an. Es ist besser, früh zu kommen als lange zu warten.",ar:"نعم، اتصل بنا حينها من فضلك. من الأفضل المجيء مبكرًا بدلًا من الانتظار طويلًا."},{s:0,t:"Verstanden. Bekomme ich heute auch ein Rezept, wenn ich ein Medikament brauche?",ar:"مفهوم. هل سأحصل اليوم أيضًا على وصفة طبية إذا احتجت دواءً؟"},{s:1,t:"Ja, der Arzt kann Ihnen ein Rezept ausstellen. Es ist üblich, das Rezept direkt in der Apotheke einzulösen.",ar:"نعم، يمكن للطبيب أن يكتب لك وصفة. ومن المعتاد صرف الوصفة مباشرة في الصيدلية."},{s:0,t:"Perfekt, die Apotheke ist gleich um die Ecke. Ich freue mich, dass alles so einfach zu organisieren ist.",ar:"ممتاز، الصيدلية على بعد خطوات. يسعدني أن كل شيء بهذه السهولة في الترتيب."},{s:1,t:"Gern geschehen. Soll ich Ihnen noch eine Erinnerung per SMS schicken?",ar:"على الرحب والسعة. هل أرسل لك تذكيرًا برسالة نصية؟"},{ar:"شكرًا جزيلًا على مساعدتك. إلى اللقاء!",s:0,t:"Vielen Dank für Ihre Hilfe. Auf Wiederhören!"}]},emoji:"📞",grammar:{covers:1,id:"de-b1-infinitiv-zu",title:"Infinitiv mit zu",titleAr:"المصدر مع zu"},stage:5,title:"مكالمة هاتفية: حجز موعد",topic:"services",topicAr:"الخدمات والطوارئ",topicDe:"Am Telefon: Termin vereinbaren",topicEn:"Phone call: making an appointment"},{conv:{id:"de-stage6-b1",speakers:["Gast (الضيف)","Kellner (النادل)"],turns:[{ar:"عذرًا، هل يمكنك المجيء لحظة من فضلك؟",s:0,t:"Entschuldigung, könnten Sie bitte kurz kommen?"},{ar:"بالطبع، بكل سرور. كيف يمكنني مساعدتك؟",s:1,t:"Natürlich, gern. Womit kann ich Ihnen helfen?"},{ar:"للأسف يجب أن أقول إن طعامي بارد. كانت الشوربة أدفأ بكثير من الطبق الرئيسي.",s:0,t:"Ich muss leider sagen, dass mein Essen kalt ist. Die Suppe war viel wärmer als das Hauptgericht."},{ar:"أوه، يؤسفني ذلك جدًا. هذا لا يجوز أن يحدث. هل أطلب إعادة تسخين الطبق لك؟",s:1,t:"Oh, das tut mir sehr leid. Das darf nicht passieren. Darf ich das Gericht für Sie noch einmal warm machen lassen?"},{ar:"نعم، من فضلك. وبصراحة، شرائح اللحم أقسى من المرة الماضية. كانت أطرى بكثير عندما أكلت هنا قبل أسبوعين.",s:0,t:"Ja, bitte. Und ehrlich gesagt ist das Steak auch härter als letztes Mal. Es war viel zarter, als ich hier vor zwei Wochen gegessen habe."},{ar:"أفهم ذلك، وأعتذر مرة أخرى. هل أجلب لك طبق اليوم بدلًا من ذلك؟ إنه اليوم أشهر طبق في القائمة.",s:1,t:"Das verstehe ich, und ich entschuldige mich noch einmal. Soll ich Ihnen stattdessen das Tagesgericht bringen? Es ist heute das beliebteste Gericht auf der Karte."},{ar:"ما هو طبق اليوم؟ هل هو أفضل من شرائح اللحم؟",s:0,t:"Was ist das Tagesgericht heute? Ist es besser als das Steak?"},{ar:"اليوم لدينا سلمون مشوي مع الخضار. يقول كثير من الضيوف إن السلمون عندنا هو الألذ.",s:1,t:"Heute gibt es gebratenen Lachs mit Gemüse. Viele Gäste sagen, dass der Lachs bei uns am besten schmeckt."},{ar:"هذا يبدو جيدًا، لكنني أفضل اللحم على السمك. هل يوجد شيء آخر؟",s:0,t:"Das klingt gut, aber ich esse lieber Fleisch als Fisch. Gibt es noch etwas anderes?"},{ar:"لدينا أيضًا دجاج مع صلصة الفطر. إنه أطرى من شرائح اللحم ويُقدَّم بسرعة أكبر.",s:1,t:"Wir haben auch Hähnchen mit Pilzsoße. Das ist zarter als das Steak und wird schneller serviert."},{ar:"حسنًا، سآخذ الدجاج إذن. لكن انتبه من فضلك أن يُقدَّم ساخنًا فعلًا.",s:0,t:"Gut, dann nehme ich das Hähnchen. Aber bitte achten Sie darauf, dass es wirklich heiß serviert wird."},{ar:"بالطبع. سأبلغ المطبخ فورًا. هل تريد أن تشرب شيئًا في هذه الأثناء؟",s:1,t:"Selbstverständlich. Ich gebe das sofort in der Küche weiter. Möchten Sie in der Zwischenzeit noch etwas trinken?"},{ar:"نعم، كوب ماء من فضلك. الماء هنا أبرد وأعذب من المطاعم الأخرى بالمناسبة.",s:0,t:"Ja, ein Glas Wasser bitte. Das Wasser hier ist übrigens kälter und frischer als in anderen Restaurants."},{ar:"شكرًا على المجاملة. سأجلب لك الماء حالًا وأتحدث مع الطاهي.",s:1,t:"Danke für das Kompliment. Ich bringe Ihnen gleich das Wasser und spreche mit dem Koch."},{ar:"شكرًا. يجب أن أقول أيضًا إن الخدمة عادة جيدة جدًا. اليوم الطعام فقط هو ما خيّب أملي.",s:0,t:"Danke. Ich muss auch sagen, dass der Service sonst immer sehr gut ist. Heute ist es nur das Essen, das mich enttäuscht."},{ar:"يسعدني سماع ذلك، رغم أن الطعام لم يكن مثاليًا اليوم. نريد أن تعود إلى بيتك راضيًا.",s:1,t:"Das freut mich zu hören, auch wenn das Essen heute nicht perfekt war. Wir möchten, dass Sie zufrieden nach Hause gehen."},{ar:"آمل ذلك. كم يستغرق تقريبًا حتى يصل الطبق الجديد؟",s:0,t:"Das hoffe ich. Wie lange dauert es ungefähr, bis das neue Gericht kommt?"},{ar:"عشر دقائق على الأكثر. الدجاج يجهز أسرع من شرائح اللحم لأنه يحتاج إلى وقت أقصر.",s:1,t:"Höchstens zehn Minuten. Das Hähnchen ist schneller fertig als das Steak, weil es kürzer braten muss."},{ar:"عشر دقائق مقبولة. سأنتظر بكل سرور إذا كان الطعام جيدًا فعلًا حينها.",s:0,t:"Zehn Minuten sind in Ordnung. Ich warte gern, wenn das Essen dann wirklich gut ist."},{ar:"أعدك أننا سنبذل جهدًا أكبر هذه المرة. هذا أقل ما يمكننا فعله.",s:1,t:"Ich verspreche Ihnen, dass wir uns diesmal mehr Mühe geben. Das ist das Mindeste, was wir tun können."},{ar:"شكرًا جزيلًا. بالمناسبة، السلطة كانت ممتازة. كانت أطزج من السلطة التي أكلتها أمس في مكان آخر.",s:0,t:"Vielen Dank. Übrigens, der Salat war ausgezeichnet. Er war frischer als der Salat, den ich gestern woanders gegessen habe."},{ar:"سأخبر الطاهي بذلك. سيسعده هذا الثناء بالتأكيد.",s:1,t:"Das werde ich dem Koch sagen. Er freut sich bestimmt über das Lob."},{ar:"آه، ها هو الدجاج قد وصل. يبدو أفضل بكثير من شرائح اللحم قبل قليل.",s:0,t:"Ah, da ist das Hähnchen schon. Es sieht viel besser aus als das Steak vorhin."},{ar:"نعم، هذا دجاجك، وآمل أن يعجبك هذه المرة أكثر من أي شيء.",s:1,t:"Ja, hier ist Ihr Hähnchen, und ich hoffe, es schmeckt Ihnen diesmal am besten."},{ar:"نعم، الدجاج طري وساخن فعلًا. شكرًا جزيلًا على مساعدتك السريعة.",s:0,t:"Ja, das Hähnchen ist wirklich zart und heiß. Vielen Dank für Ihre schnelle Hilfe."},{ar:"على الرحب والسعة. كاعتذار، نريد أن نقدم لك الحلوى مجانًا. كعكة الشوكولاتة لدينا هي أشهر حلوى في المطعم كله.",s:1,t:"Gern geschehen. Als Entschuldigung möchten wir Ihnen den Nachtisch schenken. Unser Schokoladenkuchen ist der beliebteste Nachtisch im ganzen Restaurant."},{ar:"هذا لطف كبير منك. سآخذ قطعة كعك بكل سرور إذن.",s:0,t:"Das ist sehr freundlich von Ihnen. Dann nehme ich gern ein Stück Kuchen."},{s:1,t:"Wunderbar. Möchten Sie zum Kuchen noch einen Kaffee oder einen Tee? Unser Kaffee ist stärker als der in vielen Cafés.",ar:"رائع. هل تريد مع الكعك قهوة أو شايًا؟ قهوتنا أقوى من قهوة كثير من المقاهي."},{s:0,t:"Ja, einen Kaffee bitte. Aber bitte nicht zu stark, ich trinke lieber einen milden Kaffee.",ar:"نعم، قهوة من فضلك. لكن ليست قوية جدًا، أفضل قهوة خفيفة."},{s:1,t:"Natürlich, ich bestelle einen milden Kaffee. Er ist der mildeste Kaffee, den wir haben.",ar:"بالطبع، سأطلب قهوة خفيفة. إنها أخف قهوة لدينا."},{s:0,t:"Danke. Übrigens, das Hähnchen war wirklich ausgezeichnet. Es war saftiger als jedes Hähnchen, das ich in letzter Zeit gegessen habe.",ar:"شكرًا. بالمناسبة، الدجاج كان ممتازًا فعلًا. كان أطرى من أي دجاج أكلته مؤخرًا."},{s:1,t:"Das freut mich sehr! Unser Koch benutzt nur die frischesten Zutaten. Das Hähnchen kommt heute frischer als je zuvor vom Markt.",ar:"يسعدني ذلك جدًا! طاهينا يستخدم فقط أطزج المكونات. الدجاج يأتي اليوم من السوق أطزج من أي وقت مضى."},{s:0,t:"Das merkt man. Arbeiten Sie schon lange hier?",ar:"هذا واضح. هل تعمل هنا منذ وقت طويل؟"},{s:1,t:"Seit drei Jahren. Das ist das beste Restaurant, in dem ich je gearbeitet habe.",ar:"منذ ثلاث سنوات. هذا أفضل مطعم عملت فيه على الإطلاق."},{s:0,t:"Das glaube ich gern. Der Service hier ist freundlicher als in den meisten Restaurants in der Stadt.",ar:"أصدق ذلك بكل سرور. الخدمة هنا ألطف من معظم المطاعم في المدينة."},{s:1,t:"Vielen Dank, das ist das schönste Kompliment für uns. Darf ich Ihnen noch etwas bringen?",ar:"شكرًا جزيلًا، هذا أجمل مجاملة لنا. هل أجلب لك شيئًا آخر؟"},{s:0,t:"Nein, danke. Der Kaffee und der Kuchen reichen. Aber die Rechnung hätte ich gern, wenn ich fertig bin.",ar:"لا، شكرًا. القهوة والكعك يكفيان. لكن أريد الفاتورة من فضلك عندما أنتهي."},{s:1,t:"Selbstverständlich. Und keine Sorge, der Nachtisch geht auf das Haus, er ist heute der günstigste Nachtisch der Karte – nämlich kostenlos!",ar:"بالطبع. ولا تقلق، الحلوى على حساب المطعم، فهي اليوم أرخص حلوى في القائمة — مجانية!"},{s:0,t:"Das ist wirklich großzügig. Dann zahle ich nur das Hähnchen und den Kaffee.",ar:"هذا كرم حقيقي. إذن سأدفع فقط ثمن الدجاج والقهوة."},{s:1,t:"Genau. Und beim nächsten Mal bekommen Sie als Stammgast einen noch besseren Tisch – den schönsten Platz am Fenster.",ar:"بالضبط. وفي المرة القادمة ستحصل كزبون دائم على طاولة أفضل — أجمل مكان عند النافذة."},{s:0,t:"Das klingt verlockend. Ich komme bestimmt wieder, und dann hoffentlich ohne Beschwerde!",ar:"هذا مغرٍ. سأعود بالتأكيد، وآمل أن يكون ذلك دون شكوى!"},{s:1,t:"Vielen Dank für Ihren Besuch. Wir hoffen, Sie bald wieder bei uns begrüßen zu dürfen. Auf Wiedersehen!",ar:"شكرًا جزيلًا على زيارتك. نأمل أن نرحب بك قريبًا مرة أخرى لدينا. إلى اللقاء!"}]},emoji:"🍽️",grammar:{covers:1,id:"de-b1-komparativ-superlativ",title:"Komparativ und Superlativ",titleAr:"المقارنة والتفضيل"},stage:6,title:"شكوى في المطعم",topic:"food",topicAr:"الطعام والشراب",topicDe:"Beschwerde im Restaurant",topicEn:"Complaint in a restaurant"},{conv:{id:"de-stage7-b1",speakers:["Kunde (الزبون)","Bankberaterin (مستشارة البنك)"],turns:[{ar:"صباح الخير. لدي موعد معك لفتح حساب.",s:0,t:"Guten Morgen. Ich habe einen Termin bei Ihnen, um ein Konto zu eröffnen."},{ar:"صباح الخير، أهلًا وسهلًا بك. تفضل بالجلوس من فضلك. ما الموضوع بالضبط؟",s:1,t:"Guten Morgen, herzlich willkommen. Nehmen Sie bitte Platz. Worum geht es genau?"},{ar:"أنا جديد في ألمانيا وأحتاج إلى حساب جارٍ وبطاقة ائتمان معًا.",s:0,t:"Ich bin neu in Deutschland und brauche sowohl ein Girokonto als auch eine Kreditkarte."},{ar:"لا مشكلة، يمكننا ترتيب ذلك اليوم. هل أحضرت بطاقة هويتك وشهادة تسجيل السكن؟",s:1,t:"Kein Problem, das können wir heute einrichten. Haben Sie Ihren Ausweis und Ihre Meldebescheinigung dabei?"},{ar:"نعم، أحضرت كليهما. هذه أوراقي.",s:0,t:"Ja, ich habe beides dabei. Hier sind meine Unterlagen."},{ar:"شكرًا جزيلًا. ليست الهوية مهمة فحسب، بل شهادة التسجيل أيضًا، حتى نتمكن من تأكيد عنوانك.",s:1,t:"Vielen Dank. Nicht nur der Ausweis ist wichtig, sondern auch die Meldebescheinigung, damit wir Ihre Adresse bestätigen können."},{ar:"أفهم. كم يستغرق فتح الحساب؟",s:0,t:"Verstehe. Wie lange dauert es, bis das Konto eröffnet ist?"},{ar:"الحساب سيكون نشطًا اليوم. أما البطاقة فتستغرق وقتًا أطول، وتصل خلال أسبوع تقريبًا بالبريد.",s:1,t:"Das Konto ist heute schon aktiv. Die Karte dauert etwas länger, sie kommt in etwa einer Woche per Post."},{ar:"هذا جيد. هل يمكنني تحويل الأموال عبر الإنترنت أو في الفرع؟",s:0,t:"Das ist gut. Kann ich entweder online oder in der Filiale Geld überweisen?"},{ar:"نعم، يمكنك استخدام التطبيق أو التحويل هنا في الفرع. كلاهما ممكن.",s:1,t:"Ja, Sie können entweder die App benutzen oder hier in der Filiale überweisen. Beides ist möglich."},{ar:"أفضل استخدام التطبيق. هل هو آمن؟",s:0,t:"Ich nutze lieber die App. Ist sie sicher?"},{ar:"نعم، التطبيق آمن جدًا. وكلما استخدمته أكثر، تعرفت على جميع وظائفه بشكل أفضل.",s:1,t:"Ja, die App ist sehr sicher. Je öfter Sie sie benutzen, desto besser lernen Sie alle Funktionen kennen."},{ar:"من الجيد معرفة ذلك. كم يكلف الحساب شهريًا؟",s:0,t:"Gut zu wissen. Was kostet das Konto im Monat?"},{ar:"الحساب الجاري يكلف 4.90 يورو شهريًا. وفي المقابل، التحويلات والسحب النقدي في ألمانيا مجانيان.",s:1,t:"Das Girokonto kostet 4,90 Euro im Monat. Dafür sind sowohl Überweisungen als auch Bargeldabhebungen in Deutschland kostenlos."},{ar:"هذا يبدو عادلًا. هل يوجد حساب مجاني للطلاب؟",s:0,t:"Das klingt fair. Gibt es auch ein kostenloses Konto für Studenten?"},{ar:"نعم، الحساب مجاني للطلاب. هل أنت طالب أم تعمل بالفعل؟",s:1,t:"Ja, für Studenten ist das Konto kostenlos. Sind Sie Student oder arbeiten Sie schon?"},{ar:"أعمل بالفعل، لكنني ألتحق بدورة لغة بجانب العمل. أي أنني أتعلم الألمانية وأتطور مهنيًا في الوقت نفسه.",s:0,t:"Ich arbeite schon, aber ich mache nebenbei einen Sprachkurs. Ich lerne also sowohl Deutsch als auch beruflich dazu."},{ar:"هذا مثير للإعجاب. إذن الحساب الجاري العادي يناسبك جيدًا.",s:1,t:"Das ist beeindruckend. Dann passt das normale Girokonto gut zu Ihnen."},{ar:"أريد أيضًا أن أدخر المال. هل تقدمون حساب توفير؟",s:0,t:"Ich möchte außerdem Geld sparen. Bieten Sie auch ein Sparkonto an?"},{ar:"نعم، لدينا حساب توفير بفوائد جيدة. كلما ادخرت أكثر، حصلت على فوائد أكبر.",s:1,t:"Ja, wir haben ein Sparkonto mit guten Zinsen. Je mehr Sie sparen, desto mehr Zinsen bekommen Sie."},{ar:"مثير للاهتمام. هل يمكنني فتح حساب التوفير لاحقًا، أم يجب أن أقرر الآن؟",s:0,t:"Interessant. Kann ich das Sparkonto später eröffnen, oder muss ich mich jetzt entscheiden?"},{ar:"يمكنك أن تأخذ وقتك. لا يجب أن تقرر اليوم ولا غدًا، يمكنك فتح حساب التوفير في أي وقت.",s:1,t:"Sie können sich Zeit lassen. Sie müssen sich weder heute noch morgen entscheiden, das Sparkonto können Sie jederzeit eröffnen."},{ar:"شكرًا، هذا مطمئن. أريد أولًا استخدام الحساب الجاري ثم التفكير بهدوء في الادخار.",s:0,t:"Danke, das ist beruhigend. Ich möchte zuerst das Girokonto nutzen und dann in Ruhe über das Sparen nachdenken."},{ar:"هذا معقول جدًا. هل تريد أيضًا إعداد أمر دفع دائم لإيجارك؟",s:1,t:"Sehr vernünftig. Möchten Sie auch einen Dauerauftrag für Ihre Miete einrichten?"},{ar:"نعم، سيكون ذلك عمليًا. يجب أن يُدفع الإيجار تلقائيًا في الأول من كل شهر.",s:0,t:"Ja, das wäre praktisch. Die Miete soll am 1. jeden Monats automatisch bezahlt werden."},{ar:"بكل سرور. أحتاج لذلك رقم حساب مالك العقار والمبلغ.",s:1,t:"Gern. Dafür brauche ich die Kontonummer Ihres Vermieters und den Betrag."},{ar:"هذا عقد الإيجار وفيه كل البيانات. المبلغ 650 يورو.",s:0,t:"Hier ist der Mietvertrag mit allen Daten. Der Betrag ist 650 Euro."},{ar:"ممتاز. تم إعداد أمر الدفع الدائم. ليس الإيجار فقط، بل الكهرباء والإنترنت أيضًا يمكنك دفعهما تلقائيًا بهذه الطريقة.",s:1,t:"Perfekt. Der Dauerauftrag ist eingerichtet. Nicht nur die Miete, sondern auch Strom und Internet können Sie so automatisch bezahlen."},{ar:"رائع، هذا يوفر عليّ كثيرًا من الوقت. متى سأحصل على رقم حسابي؟",s:0,t:"Super, das spart mir viel Zeit. Wann bekomme ich meine Kontonummer?"},{ar:"رقم حسابك مكتوب على هذه الورقة. البطاقة والرقم السري يصلان بشكل منفصل بالبريد، لأسباب أمنية.",s:1,t:"Ihre Kontonummer steht auf diesem Blatt. Die Karte und die Geheimnummer kommen getrennt per Post, aus Sicherheitsgründen."},{ar:"مفهوم. هل يجب أن أوقع على شيء آخر؟",s:0,t:"Verstanden. Muss ich noch etwas unterschreiben?"},{ar:"نعم، وقّع هنا وهنا من فضلك. بذلك تؤكد فتح الحساب وأمر الدفع الدائم معًا.",s:1,t:"Ja, bitte unterschreiben Sie hier und hier. Damit bestätigen Sie sowohl die Kontoeröffnung als auch den Dauerauftrag."},{ar:"بكل سرور. إذن، هل أنجزت كل شيء الآن؟",s:0,t:"Gern. So, habe ich jetzt alles erledigt?"},{ar:"تقريبًا. إما أن نتصل بك عندما تصل البطاقة، أو ستصلك رسالة في التطبيق.",s:1,t:"Fast. Entweder rufen wir Sie an, wenn die Karte da ist, oder Sie bekommen eine Nachricht in der App."},{s:0,t:"Noch eine Frage: Kann ich auch Bargeld in Euro einzahlen, wenn ich welches habe?",ar:"سؤال آخر: هل يمكنني أيضًا إيداع النقود باليورو إذا كان لدي نقد؟"},{s:1,t:"Ja, natürlich. Sie können sowohl am Schalter als auch am Automaten Bargeld einzahlen.",ar:"نعم، بالطبع. يمكنك إيداع النقود سواء عند شباك الموظف أو في جهاز الصراف الآلي."},{s:0,t:"Und kann ich auch Geld ins Ausland überweisen? Ich möchte manchmal Geld an meine Familie schicken.",ar:"وهل يمكنني أيضًا تحويل الأموال إلى الخارج؟ أريد أحيانًا إرسال المال إلى عائلتي."},{s:1,t:"Ja, das geht. Eine Auslandsüberweisung dauert aber länger als eine Überweisung in Deutschland – meistens zwei bis drei Tage.",ar:"نعم، هذا ممكن. لكن التحويل إلى الخارج يستغرق وقتًا أطول من التحويل داخل ألمانيا — عادة يومين إلى ثلاثة أيام."},{s:0,t:"Das ist gut zu wissen. Ist eine Auslandsüberweisung auch teurer als eine normale Überweisung?",ar:"من الجيد معرفة ذلك. هل التحويل إلى الخارج أغلى أيضًا من التحويل العادي؟"},{s:1,t:"Ja, etwas teurer. Je größer der Betrag ist, desto günstiger ist die Gebühr im Verhältnis.",ar:"نعم، أغلى قليلًا. وكلما كان المبلغ أكبر، كانت الرسوم أرخص نسبيًا."},{ar:"رائع. شكرًا جزيلًا على صبرك وعلى الاستشارة المفصلة.",s:0,t:"Wunderbar. Vielen Dank für Ihre Geduld und die ausführliche Beratung."},{ar:"على الرحب والسعة. كلما كانت لديك أسئلة أكثر، ساعدنا بكل سرور. أتمنى لك يومًا سعيدًا!",s:1,t:"Gern geschehen. Je mehr Fragen Sie haben, desto lieber helfen wir Ihnen. Einen schönen Tag noch!"}]},emoji:"🏦",grammar:{covers:1,id:"de-b1-zweiteilige-konnektoren",title:"Zweiteilige Konnektoren",titleAr:"أدوات الربط الثنائية"},stage:7,title:"في البنك",topic:"services",topicAr:"الخدمات والطوارئ",topicDe:"Auf der Bank",topicEn:"At the bank"},{conv:{id:"de-stage8-b1",speakers:["Gast (ضيف)","Gastgeberin (صاحبة الحفلة)"],turns:[{ar:"مرحبًا! سعيد برؤيتك. كيف حالك؟",s:0,t:"Hallo! Schön, dich zu sehen. Wie geht es dir?"},{ar:"مرحبًا! أنا بخير جدًا، شكرًا. أهلًا بك في حفلتي! عندما دعوتك، لم أكن متأكدة إن كان لديك وقت.",s:1,t:"Hallo! Mir geht es sehr gut, danke. Willkommen auf meiner Party! Als ich dich eingeladen habe, war ich mir nicht sicher, ob du Zeit hast."},{ar:"بالطبع لدي وقت. عندما تأتي دعوة منك، لا يقول المرء لا!",s:0,t:"Natürlich habe ich Zeit. Wenn man eine Einladung von dir bekommt, sagt man nicht nein!"},{ar:"هذا لطف منك. عندما خططت للحفلة، أردت بشدة أن تكون موجودًا.",s:1,t:"Das ist lieb von dir. Als ich die Party geplant habe, wollte ich unbedingt, dass du dabei bist."},{ar:"أنا سعيد جدًا بوجودي هنا. الشقة تبدو رائعة. عندما كنت هنا آخر مرة، كانت غرفة المعيشة مختلفة تمامًا.",s:0,t:"Ich freue mich sehr, hier zu sein. Die Wohnung sieht toll aus. Als ich das letzte Mal hier war, war das Wohnzimmer noch ganz anders."},{ar:"نعم، جددنا الشقة في الصيف. عندما يقوم المرء بأعمال تجديد، يستغرق كل شيء وقتًا أطول من المخطط.",s:1,t:"Ja, wir haben im Sommer renoviert. Wenn man umbaut, dauert alles immer länger als geplant."},{ar:"هذا صحيح. عندما أفكر في تجديد شقتي، ما زلت أشعر بالصداع.",s:0,t:"Das stimmt. Wenn ich an meine eigene Renovierung denke, bekomme ich immer noch Kopfschmerzen."},{ar:"آه، حدثني عن ذلك! عندما انتقلت إلى شقتك، وعدتني أن تدعوني إلى العشاء.",s:1,t:"Ach, erzähl mir davon! Als du umgezogen bist, hast du mir doch versprochen, mich zum Essen einzuladen."},{ar:"صحيح، لقد وعدت بذلك. إذا كنا متفرغين الأسبوع المقبل، سأدعوك بكل سرور.",s:0,t:"Stimmt, das habe ich versprochen. Wenn wir nächste Woche beide frei sind, lade ich dich gern ein."},{ar:"هذا يبدو رائعًا. عندما التقينا آخر مرة، كان ذلك قبل شهرين، أليس كذلك؟",s:1,t:"Das klingt wunderbar. Als wir uns das letzte Mal getroffen haben, war das schon vor zwei Monaten, oder?"},{ar:"نعم، بالضبط. عندما رأيتك في الحديقة، كنت مع أختك.",s:0,t:"Ja, genau. Als ich dich im Park gesehen habe, warst du mit deiner Schwester unterwegs."},{ar:"صحيح، كنا نركض. عندما يكون الطقس جيدًا، نركض معًا كل صباح سبت.",s:1,t:"Richtig, wir waren joggen. Wenn das Wetter gut ist, laufen wir jeden Samstagmorgen zusammen."},{ar:"رياضي! عندما أستيقظ صباح السبت، أفضل البقاء ساعة أخرى في السرير.",s:0,t:"Sportlich! Wenn ich am Samstagmorgen aufwache, bleibe ich lieber noch eine Stunde im Bett."},{ar:"أعرف هذا الشعور. عندما كنت أدرس، كنت أنام حتى الظهر في عطلات نهاية الأسبوع.",s:1,t:"Das kenne ich. Als ich noch studiert habe, habe ich am Wochenende immer bis mittags geschlafen."},{ar:"والآن؟ عندما تكونين متفرغة، ماذا تحبين أن تفعلي؟",s:0,t:"Und jetzt? Wenn du frei hast, was machst du am liebsten?"},{ar:"عندما أكون متفرغة، أحب الطبخ أو لقاء الأصدقاء. عندما كنت صغيرة، كنت أحب الطبخ مع أمي.",s:1,t:"Wenn ich frei habe, koche ich gern oder treffe Freunde. Als ich klein war, habe ich schon gern mit meiner Mutter gekocht."},{ar:"هذا يفسر لماذا الطعام اليوم لذيذ جدًا! عندما رأيت البوفيه، عرفت فورًا أنك من طبخ.",s:0,t:"Das erklärt, warum das Essen heute so lecker ist! Als ich das Buffet gesehen habe, wusste ich sofort, dass du gekocht hast."},{ar:"شكرًا! إذا أعجبك شيء بشكل خاص، أخبرني، وسأعطيك الوصفة.",s:1,t:"Danke! Wenn dir etwas besonders gut schmeckt, sag mir Bescheid, dann gebe ich dir das Rezept."},{ar:"بكل سرور. المقبلات كانت رائعة. عندما تذوقت السلطة، اضطررت أن آخذ مرة أخرى فورًا.",s:0,t:"Sehr gern. Die Vorspeise war fantastisch. Als ich den Salat probiert habe, musste ich gleich noch einmal nehmen."},{ar:"يسعدني ذلك. إذا كان كل الضيوف راضين هكذا، فقد كان كل العمل يستحق العناء.",s:1,t:"Das freut mich. Wenn alle Gäste so zufrieden sind, hat sich die ganze Arbeit gelohnt."},{ar:"بالتأكيد. هل تعرفين كثيرًا من الناس هنا؟ عندما دخلت، لم أكن أعرف أحدًا تقريبًا.",s:0,t:"Bestimmt. Kennst du eigentlich viele Leute hier? Als ich reingekommen bin, kannte ich fast niemanden."},{ar:"معظمهم زملاء أو أصدقاء قدامى. إذا أردت، أقدمك بكل سرور لبعض الأشخاص.",s:1,t:"Die meisten sind Kollegen oder alte Freunde. Wenn du magst, stelle ich dich gern ein paar Leuten vor."},{ar:"نعم، بكل سرور! عندما يتعرف المرء على أشخاص جدد، تكون الحفلة أفضل مكان لذلك.",s:0,t:"Ja, gern! Wenn man neue Leute kennenlernt, ist eine Party der beste Ort dafür."},{ar:"بالضبط. عندما انتقلت إلى برلين قبل ثلاث سنوات، تعرفت على أفضل أصدقائي في حفلة.",s:1,t:"Genau. Als ich vor drei Jahren nach Berlin gezogen bin, habe ich auf einer Party meine besten Freunde kennengelernt."},{ar:"حقًا؟ عندما جئت إلى برلين، لم تكوني تعرفين أحدًا هناك؟",s:0,t:"Wirklich? Als du nach Berlin gekommen bist, kanntest du dort niemanden?"},{ar:"لا أحد. لو لم أذهب إلى حفلة في ذلك الوقت، لكنت وحيدة حتى اليوم.",s:1,t:"Niemanden. Wenn ich damals keine Party besucht hätte, wäre ich heute noch allein."},{ar:"لحسن الحظ أنك ذهبت! إذا وجدت أصدقاء جددًا هذا المساء، فالفضل يعود إليك.",s:0,t:"Zum Glück bist du gegangen! Wenn ich heute Abend neue Freunde finde, verdanke ich das dir."},{ar:"آمل ذلك! تعال، سأقدمك إلى يوناس ومريم. عندما وصلا، سألا عنك.",s:1,t:"Das hoffe ich! Komm, ich stelle dir Jonas und Miriam vor. Als sie angekommen sind, haben sie nach dir gefragt."},{ar:"أوه، كم هذا لطيف! إذا سألا عني، فهم يعرفونني من قصصك على الأرجح.",s:0,t:"Oh, wie nett! Wenn sie nach mir gefragt haben, kennen sie mich wohl von deinen Geschichten."},{ar:"بالطبع، أتحدث عنك كثيرًا. عندما كنا في عطلة معًا العام الماضي، حدثتهم عنك كثيرًا.",s:1,t:"Natürlich, ich erzähle oft von dir. Als wir letztes Jahr zusammen im Urlaub waren, habe ich ihnen viel von dir erzählt."},{ar:"الآن أصبحت فضوليًا! عندما نتحدث لاحقًا، يجب أن تخبريني ماذا قلت عني.",s:0,t:"Jetzt bin ich neugierig! Wenn wir uns später unterhalten, musst du mir sagen, was du erzählt hast."},{ar:"فقط أشياء جيدة، أعدك. عندما ساعدتني في الانتقال، أخبرت الجميع كم أنت صديق رائع.",s:1,t:"Nur Gutes, versprochen. Als du mir bei meinem Umzug geholfen hast, habe ich allen erzählt, was für ein guter Freund du bist."},{ar:"شكرًا، هذا لطف كبير. إذا استطعت مساعدتك في أي وقت، فقط أخبريني.",s:0,t:"Danke, das ist sehr lieb. Wenn ich dir irgendwann helfen kann, sag einfach Bescheid."},{ar:"سأفعل ذلك. الآن استمتع بالحفلة! إذا احتجت شيئًا، سأكون في المطبخ.",s:1,t:"Das werde ich. Jetzt genieß die Party! Wenn du etwas brauchst, bin ich in der Küche."},{ar:"شكرًا! إذا كنت صادقًا، فهذه أجمل حفلة منذ وقت طويل.",s:0,t:"Danke! Wenn ich ehrlich bin, ist das die schönste Party seit langem."},{ar:"هذا يسعدني جدًا. عندما استيقظت هذا الصباح، كنت ما زلت متوترة بشأن ما إذا كان كل شيء سينجح.",s:1,t:"Das freut mich riesig. Als ich heute Morgen aufgewacht bin, war ich noch nervös, ob alles klappt."},{s:0,t:"Das glaube ich dir. Wenn man so eine schöne Party organisiert, hat man allen Grund, stolz zu sein.",ar:"أصدقك. عندما ينظم المرء حفلة جميلة كهذه، يكون لديه كل الحق في الفخر."},{s:1,t:"Danke! Als ich heute Morgen aufgewacht bin, dachte ich noch, dass niemand kommen würde.",ar:"شكرًا! عندما استيقظت هذا الصباح، ظننت أن أحدًا لن يأتي."},{s:0,t:"Wie kommst du denn darauf? Wenn du eine Party machst, kommen immer alle gern.",ar:"كيف خطر لك ذلك؟ عندما تقيمين حفلة، يأتي الجميع بكل سرور دائمًا."},{s:1,t:"Das ist lieb. Wenn ich gewusst hätte, dass so viele kommen, hätte ich noch mehr Essen vorbereitet.",ar:"هذا لطف منك. لو كنت أعلم أن كثيرين سيأتون، لكنت أعددت طعامًا أكثر."},{s:0,t:"Es gibt mehr als genug. Wenn ich noch ein Stück Kuchen esse, platze ich!",ar:"يوجد أكثر من الكافي. إذا أكلت قطعة كعك أخرى، سأنفجر!"},{s:1,t:"Dann iss lieber noch ein Stück, solange es noch da ist. Wenn der Kuchen weg ist, ist er weg!",ar:"إذن كُل قطعة أخرى ما دام موجودًا. عندما ينتهي الكعك، ينتهي!"},{ar:"كل شيء يسير بشكل مثالي. إذا أقمت حفلة أخرى العام المقبل، سأكون موجودًا بالتأكيد!",s:0,t:"Alles klappt perfekt. Wenn du nächstes Jahr wieder eine Party machst, bin ich auf jeden Fall dabei!"}]},emoji:"🎉",grammar:{covers:1,id:"de-b1-wenn-als",title:"wenn oder als?",titleAr:"‏wenn أم als؟"},stage:8,title:"حديث عابر في حفلة",topic:"social",topicAr:"المواقف الاجتماعية",topicDe:"Small Talk auf einer Party",topicEn:"Small talk at a party"},{conv:{id:"de-stage9-b1",speakers:["Tourist (السائح)","Passantin (إحدى المارة)"],turns:[{ar:"عذرًا، هل يمكنك مساعدتي من فضلك؟ أبحث عن المتحف الجديد.",s:0,t:"Entschuldigung, können Sie mir bitte helfen? Ich suche das neue Museum."},{ar:"بالطبع، بكل سرور. المتحف الجديد ليس بعيدًا من هنا.",s:1,t:"Natürlich, gern. Das neue Museum ist nicht weit von hier."},{ar:"رائع. هل هو في هذا الاتجاه؟",s:0,t:"Wunderbar. Ist es in dieser Richtung?"},{ar:"نعم، امشِ في هذا الشارع الطويل مباشرة حتى الساحة الصغيرة.",s:1,t:"Ja, gehen Sie diese lange Straße geradeaus bis zum kleinen Platz."},{ar:"وماذا بعد؟ هل يجب أن أنعطف عند الكنيسة القديمة؟",s:0,t:"Und dann? Muss ich an der alten Kirche abbiegen?"},{ar:"بالضبط. عند الكنيسة القديمة تنعطف يسارًا.",s:1,t:"Genau. An der alten Kirche biegen Sie links ab."},{ar:"هل يوجد هناك لافتة كبيرة؟",s:0,t:"Gibt es dort ein großes Schild?"},{ar:"نعم، أمام المبنى الكبير توجد لافتة واضحة.",s:1,t:"Ja, vor dem großen Gebäude steht ein deutliches Schild."},{ar:"كم تستغرق الطريق مشيًا على الأقدام؟",s:0,t:"Wie lange dauert der Weg zu Fuß?"},{ar:"حوالي عشر دقائق. إنها طريق جميلة عبر الشارع الأخضر.",s:1,t:"Etwa zehn Minuten. Es ist ein schöner Weg durch die grüne Allee."},{ar:"هل يوجد في الطريق مقهى لطيف؟",s:0,t:"Gibt es unterwegs ein nettes Café?"},{ar:"نعم، بجانب الحديقة الصغيرة يوجد مقهى مريح.",s:1,t:"Ja, neben dem kleinen Park gibt es ein gemütliches Café."},{ar:"ممتاز. أحتاج بعد الرحلة الطويلة إلى قهوة قوية.",s:0,t:"Perfekt. Ich brauche nach dem langen Flug einen starken Kaffee."},{ar:"إذن أنصحك بالمقهى عند النافورة القديمة. له سمعة جيدة.",s:1,t:"Dann empfehle ich Ihnen das Café am alten Brunnen. Es hat einen guten Ruf."},{ar:"شكرًا. وأين أقرب محطة حافلات؟",s:0,t:"Danke. Und wo ist die nächste Bushaltestelle?"},{ar:"المحطة التالية مباشرة خلف الجسر العريض.",s:1,t:"Die nächste Haltestelle ist direkt hinter der breiten Brücke."},{ar:"هل ينطلق من هناك باص إلى محطة القطار الرئيسية؟",s:0,t:"Fährt von dort ein Bus zum Hauptbahnhof?"},{ar:"نعم، الباص السريع رقم اثني عشر ينطلق كل خمس عشرة دقيقة.",s:1,t:"Ja, der schnelle Bus Nummer zwölf fährt alle fünfzehn Minuten."},{ar:"هذا عملي. يجب أن أستقل القطار المتأخر هذا المساء.",s:0,t:"Das ist praktisch. Ich muss heute Abend noch den späten Zug nehmen."},{ar:"لا مشكلة. من المحطة تصل بسهولة إلى الفندق الحديث.",s:1,t:"Kein Problem. Vom Bahnhof aus kommen Sie leicht zum modernen Hotel."},{ar:"هل الفندق الحديث غالٍ؟",s:0,t:"Ist das moderne Hotel teuer?"},{ar:"لا، إنه فندق ودود بأسعار عادلة.",s:1,t:"Nein, es ist ein freundliches Hotel mit fairen Preisen."},{ar:"من الجيد معرفة ذلك. أبحث أيضًا عن مكان هادئ للقراءة.",s:0,t:"Gut zu wissen. Ich suche auch einen ruhigen Ort zum Lesen."},{ar:"إذن اذهب إلى الحديقة الهادئة خلف مبنى البلدية الأبيض.",s:1,t:"Dann gehen Sie in den stillen Garten hinter dem weißen Rathaus."},{ar:"يبدو رائعًا. هل الحديقة مفتوحة في عطلة نهاية الأسبوع؟",s:0,t:"Klingt wunderbar. Ist der Garten am Wochenende geöffnet?"},{ar:"نعم، الحديقة العامة مفتوحة كل يوم من الصباح حتى المساء.",s:1,t:"Ja, der öffentliche Garten ist jeden Tag von morgens bis abends geöffnet."},{ar:"وأين يمكنني شراء خريطة جيدة للمدينة؟",s:0,t:"Und wo kann ich eine gute Stadtkarte kaufen?"},{ar:"في الكشك الصغير عند الزاوية الضيقة توجد خريطة حديثة.",s:1,t:"In dem kleinen Kiosk an der engen Ecke gibt es eine aktuelle Karte."},{ar:"شكرًا جزيلًا على وصف الطريق المفصّل.",s:0,t:"Vielen Dank für die ausführliche Wegbeschreibung."},{ar:"على الرحب والسعة. أتمنى لك إقامة جميلة في مدينتنا الحيوية.",s:1,t:"Gern geschehen. Ich wünsche Ihnen einen schönen Aufenthalt in unserer lebhaften Stadt."},{ar:"سؤال أخير: هل القصر القديم مفتوح اليوم؟",s:0,t:"Eine letzte Frage: Ist das alte Schloss heute geöffnet?"},{ar:"نعم، القصر التاريخي مفتوح حتى السادسة مساءً.",s:1,t:"Ja, das historische Schloss ist bis achtzehn Uhr geöffnet."},{ar:"إذن سأزور أولًا القصر وبعدها المتحف الجديد.",s:0,t:"Dann besuche ich zuerst das Schloss und danach das neue Museum."},{ar:"فكرة جيدة. الطريق القصير بينهما جميل جدًا.",s:1,t:"Eine gute Idee. Der kurze Weg zwischen beiden ist sehr schön."},{ar:"أشكرك على مساعدتك اللطيفة.",s:0,t:"Ich danke Ihnen für Ihre freundliche Hilfe."},{ar:"لا داعي للشكر. استمتع ويومًا سعيدًا!",s:1,t:"Keine Ursache. Viel Spaß und einen angenehmen Tag!"},{ar:"شكرًا، وأتمنى لك يومًا جميلًا أيضًا!",s:0,t:"Danke, Ihnen auch einen schönen Tag!"},{ar:"إلى اللقاء!",s:1,t:"Auf Wiedersehen!"},{ar:"إلى اللقاء!",s:0,t:"Auf Wiedersehen!"},{ar:"آه، وانتبه جيدًا على الدرج الحاد المؤدي إلى القصر!",s:1,t:"Ach, und passen Sie auf der steilen Treppe zum Schloss gut auf!"},{ar:"شكرًا على التنبيه المهم. سأنتبه جيدًا.",s:0,t:"Danke für den wichtigen Hinweis. Ich passe gut auf."},{ar:"كل التوفيق!",s:1,t:"Alles Gute!"}]},emoji:"🗺️",grammar:{covers:1,id:"de-b1-adjektivdeklination",title:"Adjektivdeklination",titleAr:"تصريف الصفات"},stage:9,title:"وصف الطريق",topic:"travel",topicAr:"السفر والمواصلات",topicDe:"Wegbeschreibung",topicEn:"Asking for directions"},{conv:{id:"de-stage10-b1",speakers:["Antragsteller (مقدم الطلب)","Sachbearbeiterin (موظفة المكتب)"],turns:[{ar:"صباح الخير. أريد أن أقدم طلبًا للحصول على بطاقة هوية جديدة.",s:0,t:"Guten Morgen. Ich möchte einen neuen Ausweis beantragen."},{ar:"صباح الخير. هنا يُستلم طلبك ويُعالج.",s:1,t:"Guten Morgen. Hier wird Ihr Antrag entgegengenommen und bearbeitet."},{ar:"ما المستندات المطلوبة لذلك؟",s:0,t:"Welche Dokumente werden dafür benötigt?"},{ar:"أولًا يُطلب جواز سفر ساري المفعول. كما تُحتاج صورة حديثة.",s:1,t:"Zuerst wird ein gültiger Pass verlangt. Außerdem wird ein aktuelles Foto gebraucht."},{ar:"أحضرت معي جواز سفري وصورتين.",s:0,t:"Ich habe meinen Pass und zwei Fotos dabei."},{ar:"جيد جدًا. يجب ملء الاستمارة بالكامل.",s:1,t:"Sehr gut. Das Formular muss vollständig ausgefüllt werden."},{ar:"أين تُملأ الاستمارة؟ هنا عند الشباك؟",s:0,t:"Wo wird das Formular ausgefüllt? Hier am Schalter?"},{ar:"نعم، تُملأ الاستمارة هنا ثم تُفحص من قبلنا.",s:1,t:"Ja, das Formular wird hier ausgefüllt und dann von uns geprüft."},{ar:"هل يجب دفع الرسوم فورًا؟",s:0,t:"Muss die Gebühr sofort bezahlt werden?"},{ar:"نعم، تُدفع الرسوم عند الصندوق. ويُعطى لك إيصال.",s:1,t:"Ja, die Gebühr wird an der Kasse bezahlt. Eine Quittung wird Ihnen gegeben."},{ar:"كم تستغرق معالجة بطاقة الهوية؟",s:0,t:"Wie lange wird der Ausweis bearbeitet?"},{ar:"تُصنع بطاقة الهوية في حوالي أربعة أسابيع.",s:1,t:"Der Ausweis wird in etwa vier Wochen hergestellt."},{ar:"هل سيتم إبلاغي عندما تكون البطاقة جاهزة؟",s:0,t:"Werde ich informiert, wenn der Ausweis fertig ist?"},{ar:"نعم، ستُبلَّغ كتابيًا حالما يمكن استلام البطاقة.",s:1,t:"Ja, Sie werden schriftlich informiert, sobald der Ausweis abgeholt werden kann."},{ar:"هل يمكن لشخص آخر استلام البطاقة؟",s:0,t:"Kann der Ausweis auch von einer anderen Person abgeholt werden?"},{ar:"نعم، لكن يجب عندها تقديم وكالة رسمية.",s:1,t:"Ja, aber eine Vollmacht muss dann vorgelegt werden."},{ar:"فهمت. هل تُؤخذ بصمات أصابعي أيضًا؟",s:0,t:"Verstehe. Werden meine Fingerabdrücke auch genommen?"},{ar:"نعم، تُسجَّل بصمات الأصابع هنا رقميًا.",s:1,t:"Ja, die Fingerabdrücke werden hier digital erfasst."},{ar:"هل يمكن التقاط الصورة هنا أيضًا، أم يجب التقاطها في مكان آخر؟",s:0,t:"Ist das Foto hier auch möglich, oder muss es woanders gemacht werden?"},{ar:"عادةً تُلتقط الصورة في استوديو تصوير، لكنها تُقدَّم هنا أيضًا.",s:1,t:"Das Foto wird normalerweise in einem Fotostudio gemacht, aber hier wird es auch angeboten."},{ar:"حسنًا، إذن سألتقط الصورة هنا مباشرة.",s:0,t:"Gut, dann mache ich das Foto gleich hier."},{ar:"حسنًا. وقّع هنا من فضلك. يُمسح التوقيع ضوئيًا ويُحفظ.",s:1,t:"Alles klar. Bitte unterschreiben Sie hier. Die Unterschrift wird gescannt und gespeichert."},{ar:"هل تُحتجز بطاقة هويتي القديمة؟",s:0,t:"Wird mein alter Ausweis einbehalten?"},{ar:"لا، تُعاد إليك البطاقة القديمة، لكنها تُلغى صلاحيتها.",s:1,t:"Nein, der alte Ausweis wird Ihnen zurückgegeben, aber er wird entwertet."},{ar:"وماذا يحدث إذا احتجت إلى بطاقة هوية في هذه الأثناء؟",s:0,t:"Und was passiert, wenn ich in der Zwischenzeit einen Ausweis brauche?"},{ar:"عندها يُصدر لك بطاقة هوية مؤقتة.",s:1,t:"Dann wird Ihnen ein vorläufiger Ausweis ausgestellt."},{ar:"هذا يطمئنني. هل تُصدر البطاقة المؤقتة فورًا؟",s:0,t:"Das beruhigt mich. Wird der vorläufige Ausweis sofort ausgestellt?"},{ar:"نعم، تُصدر فورًا وتكون صالحة لثلاثة أشهر.",s:1,t:"Ja, er wird sofort ausgestellt und ist drei Monate gültig."},{ar:"شكرًا جزيلًا. هل تُعامل البيانات بسرية؟",s:0,t:"Vielen Dank. Werden die Daten vertraulich behandelt?"},{ar:"بالطبع. تُحفظ جميع البيانات بأمان ولا تُشارك مع الآخرين.",s:1,t:"Selbstverständlich. Alle Daten werden sicher gespeichert und nicht weitergegeben."},{ar:"هل يمكنني متابعة حالة طلبي عبر الإنترنت؟",s:0,t:"Kann ich den Stand meines Antrags online verfolgen?"},{ar:"نعم، تُعرض الحالة عبر الإنترنت حالما تتم معالجة الطلب.",s:1,t:"Ja, der Stand wird online angezeigt, sobald der Antrag bearbeitet wird."},{ar:"ممتاز. هل هناك شيء آخر يجب أن أعرفه؟",s:0,t:"Perfekt. Gibt es noch etwas, das ich wissen muss?"},{ar:"لا، هذا كل شيء. احتفظ بالإيصال جيدًا من فضلك.",s:1,t:"Nein, das war alles. Bitte bewahren Sie die Quittung gut auf."},{ar:"سأفعل ذلك. شكرًا جزيلًا على مساعدتك اللطيفة.",s:0,t:"Das mache ich. Vielen Dank für Ihre freundliche Hilfe."},{ar:"على الرحب والسعة. أتمنى لك يومًا سعيدًا!",s:1,t:"Gern geschehen. Einen schönen Tag noch!"},{ar:"شكرًا، لك أيضًا!",s:0,t:"Danke, Ihnen auch!"},{ar:"إلى اللقاء!",s:1,t:"Auf Wiedersehen!"},{ar:"إلى اللقاء!",s:0,t:"Auf Wiedersehen!"},{ar:"آه، لا تنسَ: الاستلام يتم فقط بموعد مسبق.",s:1,t:"Ach, vergessen Sie nicht: Die Abholung wird nur mit Termin gemacht."},{ar:"واضح، سأحجز الموعد عبر الإنترنت. شكرًا مرة أخرى!",s:0,t:"Alles klar, ich buche den Termin online. Danke noch einmal!"}]},emoji:"🏛️",grammar:{covers:1,id:"de-b1-passiv-praesens",title:"Passiv im Präsens",titleAr:"المبني للمجهول في الحاضر"},stage:10,title:"في المكتب الحكومي",topic:"services",topicAr:"الخدمات والطوارئ",topicDe:"Im Amt",topicEn:"At the authorities office"},{conv:{id:"de-stage11-b1",speakers:["Freund (صديق)","Freundin (صديقة)"],turns:[{ar:"مرحبًا! كيف كانت عطلتك في إيطاليا؟",s:0,t:"Hallo! Wie war dein Urlaub in Italien?"},{ar:"مرحبًا! كانت رائعة. سافرنا بالقطار إلى روما.",s:1,t:"Hallo! Er war wunderbar. Wir fuhren mit dem Zug nach Rom."},{ar:"كم بقيتم هناك؟",s:0,t:"Wie lange wart ihr dort?"},{ar:"بقينا عشرة أيام. كان الطقس مشمسًا ودافئًا.",s:1,t:"Wir blieben zehn Tage. Das Wetter war sonnig und warm."},{ar:"أين أقمتم؟",s:0,t:"Wo wohntet ihr?"},{ar:"أقمنا في فندق صغير في المدينة القديمة.",s:1,t:"Wir wohnten in einem kleinen Hotel in der Altstadt."},{ar:"ماذا فعلتم في اليوم الأول؟",s:0,t:"Was machtet ihr am ersten Tag?"},{ar:"في اليوم الأول زرنا الكولوسيوم. كان مثيرًا للإعجاب.",s:1,t:"Am ersten Tag besuchten wir das Kolosseum. Es war beeindruckend."},{ar:"هل رأيتم أيضًا المنتدى الروماني؟",s:0,t:"Habt ihr auch das Forum Romanum gesehen?"},{ar:"نعم، رأيناه في اليوم الثاني. بعدها أكلنا في مطعم صغير.",s:1,t:"Ja, wir sahen es am zweiten Tag. Danach aßen wir in einem kleinen Restaurant."},{ar:"هل كان الطعام جيدًا؟",s:0,t:"War das Essen gut?"},{ar:"كان ممتازًا. أكلنا كل يوم بيتزا ومعكرونة.",s:1,t:"Es war ausgezeichnet. Wir aßen jeden Tag Pizza und Pasta."},{ar:"وماذا كنتم تفعلون في المساء؟",s:0,t:"Und was machtet ihr abends?"},{ar:"في المساء كنا نخرج غالبًا للنزهة ونشرب قهوة في إحدى الساحات.",s:1,t:"Abends gingen wir oft spazieren und tranken einen Kaffee auf einem Platz."},{ar:"هل وجدتم المدينة غالية؟",s:0,t:"Fandet ihr die Stadt teuer?"},{ar:"قليلًا، لكننا وجدنا أيضًا مقاهي وأسواقًا رخيصة.",s:1,t:"Ein bisschen, aber wir fanden auch günstige Cafés und Märkte."},{ar:"هل ذهبتم أيضًا إلى البحر؟",s:0,t:"Seid ihr auch ans Meer gefahren?"},{ar:"نعم، سافرنا يومًا إلى نابولي ثم واصلنا إلى الساحل.",s:1,t:"Ja, wir fuhren einen Tag nach Neapel und dann weiter an die Küste."},{ar:"كيف كان البحر؟",s:0,t:"Wie war das Meer?"},{ar:"كان الماء صافيًا ودافئًا. سبحنا طوال فترة بعد الظهر.",s:1,t:"Das Wasser war klar und warm. Wir schwammen den ganzen Nachmittag."},{ar:"هل واجهتم مشاكل مع اللغة؟",s:0,t:"Hattet ihr Probleme mit der Sprache?"},{ar:"لا، معظم الناس كانوا يتحدثون الإنجليزية، وتعلمنا بعض الكلمات الإيطالية.",s:1,t:"Nein, die meisten Leute sprachen Englisch, und wir lernten ein paar italienische Wörter."},{ar:"ما أجمل تجربة مررت بها؟",s:0,t:"Was war dein schönstes Erlebnis?"},{ar:"كان غروب الشمس في روما جميلًا جدًا. جلسنا طويلًا على درج وشاهدنا.",s:1,t:"Der Sonnenuntergang in Rom war wunderschön. Wir saßen lange auf einer Treppe und sahen zu."},{ar:"هذا يبدو رومانسيًا. هل كان هناك شيء مزعج أيضًا؟",s:0,t:"Das klingt romantisch. Gab es auch etwas Unangenehmes?"},{ar:"نعم، في اليوم الخامس أمطرت بغزارة. بقينا في الفندق وقرأنا.",s:1,t:"Ja, am fünften Tag regnete es stark. Wir blieben im Hotel und lasen."},{ar:"وكيف كانت رحلة العودة؟",s:0,t:"Und wie war die Rückfahrt?"},{ar:"كانت رحلة العودة طويلة، لكننا نمنا معظم الوقت في القطار.",s:1,t:"Die Rückfahrt war lang, aber wir schliefen fast die ganze Zeit im Zug."},{ar:"هل ستسافرين إلى إيطاليا مرة أخرى؟",s:0,t:"Würdest du noch einmal nach Italien fahren?"},{ar:"بالتأكيد! في المرة القادمة أريد زيارة فلورنسا والبندقية.",s:1,t:"Auf jeden Fall! Nächstes Mal möchte ich Florenz und Venedig besuchen."},{ar:"إذن ربما نسافر معًا. أردت منذ زمن طويل الذهاب إلى البندقية.",s:0,t:"Dann fahren wir vielleicht zusammen. Ich wollte schon lange nach Venedig."},{ar:"سيكون ذلك رائعًا! لقد خططنا كثيرًا من قبل لرحلة مشتركة.",s:1,t:"Das wäre toll! Wir planten schon oft eine gemeinsame Reise."},{ar:"صحيح. هذه المرة سنفعلها فعلًا.",s:0,t:"Stimmt. Dieses Mal machen wir es wirklich."},{ar:"بالمناسبة، أريتك صوري. كانت على هاتفي.",s:1,t:"Ich zeigte dir übrigens meine Fotos. Sie lagen auf meinem Handy."},{ar:"نعم، رأيتها. كانت الصور جميلة فعلًا.",s:0,t:"Ja, ich sah sie. Die Fotos waren wirklich schön."},{ar:"أرسلت لك أيضًا بعضًا منها برسالة.",s:1,t:"Ich schickte dir auch ein paar per Nachricht."},{ar:"شكرًا! أنا متحمس بالفعل لعطلتنا القادمة.",s:0,t:"Danke! Ich freue mich schon auf unseren nächsten Urlaub."},{ar:"وأنا أيضًا. إلى اللقاء قريبًا!",s:1,t:"Ich auch. Bis bald!"},{ar:"إلى اللقاء قريبًا!",s:0,t:"Bis bald!"},{ar:"آه، كدت أنسى: أحضرت لك هدية صغيرة من روما.",s:1,t:"Ach, ich vergaß fast: Ich brachte dir ein kleines Geschenk aus Rom mit."},{ar:"كم هذا لطيف منك! شكرًا جزيلًا!",s:0,t:"Wie lieb von dir! Vielen Dank!"},{ar:"على الرحب والسعة!",s:1,t:"Gern geschehen!"}]},emoji:"✈️",grammar:{covers:1,id:"de-b1-praeteritum",title:"Präteritum",titleAr:"الماضي البسيط (Präteritum)"},stage:11,title:"الحديث عن العطلة",topic:"travel",topicAr:"السفر والمواصلات",topicDe:"Über den Urlaub sprechen",topicEn:"Talking about the holiday"},{conv:{id:"de-stage12-b1",speakers:["Diskutant (مشارك بالنقاش)","Diskutantin (مشاركة بالنقاش)"],turns:[{ar:"نهارك سعيد! هل تسمح بأن تخبرني باختصار برأيك في اقتراحنا؟",s:0,t:"Guten Tag! Würden Sie mir bitte kurz Ihre Meinung zu unserem Vorschlag sagen?"},{ar:"بكل سرور. أود أن أقول إن الاقتراح جيد، لكن يمكن تحسينه أكثر.",s:1,t:"Gern. Ich würde sagen, der Vorschlag ist gut, aber er könnte noch verbessert werden."},{ar:"هل يمكنك أن تشرح بدقة أكبر ما تقصد؟",s:0,t:"Könnten Sie bitte genauer erklären, was Sie meinen?"},{ar:"بالطبع. أرى أنه سيكون أفضل لو كان لدينا وقت أكثر للنقاش.",s:1,t:"Natürlich. Ich fände es besser, wenn wir mehr Zeit für die Diskussion hätten."},{ar:"أوافقك في ذلك. هل من الممكن تمديد الاجتماع ساعة إضافية؟",s:0,t:"Da stimme ich Ihnen zu. Wäre es möglich, das Treffen um eine Stunde zu verlängern?"},{ar:"سيكون ذلك حلًا جيدًا. هل تناقش ذلك مع المجموعة من فضلك؟",s:1,t:"Das wäre eine gute Lösung. Würden Sie das bitte mit der Gruppe besprechen?"},{ar:"نعم، سأفعل ذلك بكل سرور. هل لديك اقتراح آخر؟",s:0,t:"Ja, das mache ich gern. Hätten Sie noch einen anderen Vorschlag?"},{ar:"أود الحصول على أمثلة أكثر من الواقع العملي. ذلك سيساعدنا كثيرًا.",s:1,t:"Ich hätte gern mehr Beispiele aus der Praxis. Das würde uns sehr helfen."},{ar:"فكرة جيدة. هل يمكننا ربما دعوة خبير؟",s:0,t:"Gute Idee. Könnten wir vielleicht einen Experten einladen?"},{ar:"نعم، سيكون ذلك مفيدًا جدًا. هل تتولى ذلك؟",s:1,t:"Ja, das wäre sehr hilfreich. Würden Sie sich darum kümmern?"},{ar:"بالطبع. سأتصل به اليوم.",s:0,t:"Selbstverständlich. Ich würde ihn noch heute anrufen."},{ar:"شكرًا جزيلًا. ما رأيك في النقطة الثانية على قائمتنا؟",s:1,t:"Vielen Dank. Was halten Sie von dem zweiten Punkt auf unserer Liste?"},{ar:"بصراحة، سأكون حذرًا. قد تكون التكاليف مرتفعة جدًا.",s:0,t:"Ehrlich gesagt, ich wäre vorsichtig. Die Kosten könnten zu hoch sein."},{ar:"أفهم ذلك. هل يمكننا ربما تقسيم التكاليف إلى جزأين؟",s:1,t:"Das verstehe ich. Könnten wir die Kosten vielleicht in zwei Teile aufteilen?"},{ar:"ستكون فكرة ذكية. سأقترح ذلك بهذا الشكل.",s:0,t:"Das wäre eine kluge Idee. Ich würde das so vorschlagen."},{ar:"هل تلخص من فضلك المزايا والعيوب باختصار؟",s:1,t:"Würden Sie bitte auch die Vorteile und Nachteile kurz zusammenfassen?"},{ar:"بكل سرور. أكبر ميزة ستكون أننا سنستطيع العمل بشكل أسرع.",s:0,t:"Gern. Der größte Vorteil wäre, dass wir schneller arbeiten könnten."},{ar:"وأكبر عيب؟",s:1,t:"Und der größte Nachteil?"},{ar:"العيب سيكون أننا سنحتاج في البداية إلى وقت أكثر.",s:0,t:"Der Nachteil wäre, dass wir am Anfang mehr Zeit bräuchten."},{ar:"أفهم. هل تعطيني مثالًا آخر من فضلك؟",s:1,t:"Ich verstehe. Könnten Sie mir bitte noch ein Beispiel geben?"},{ar:"بالطبع. تخيل لو كان لدينا ضعف عدد الموظفين.",s:0,t:"Natürlich. Stellen Sie sich vor, wir hätten doppelt so viele Mitarbeiter."},{ar:"عندها سنستطيع إنهاء المشروع في وقت أبكر بكثير.",s:1,t:"Dann könnten wir das Projekt viel früher beenden."},{ar:"بالضبط. سأكون سعيدًا لو استطعنا الاتفاق على ذلك.",s:0,t:"Genau. Ich würde mich freuen, wenn wir uns darauf einigen könnten."},{ar:"وأنا أيضًا. هل يكون مناسبًا أن نتحدث عن ذلك مرة أخرى غدًا؟",s:1,t:"Ich auch. Wäre es in Ordnung, wenn wir morgen noch einmal darüber sprechen?"},{ar:"نعم، يناسبني جدًا. هل يناسبك الساعة العاشرة؟",s:0,t:"Ja, das wäre mir sehr recht. Würde Ihnen zehn Uhr passen?"},{ar:"الساعة العاشرة تناسبني جيدًا. هل ترسل لي المستندات مسبقًا من فضلك؟",s:1,t:"Zehn Uhr würde mir gut passen. Könnten Sie mir bitte vorher die Unterlagen schicken?"},{ar:"بالطبع. سأرسلها لك اليوم.",s:0,t:"Selbstverständlich. Ich würde sie Ihnen noch heute schicken."},{ar:"شكرًا جزيلًا على الحديث الودود.",s:1,t:"Vielen Dank für das freundliche Gespräch."},{ar:"أشكرك. سأكون سعيدًا بمناقشتك مجددًا قريبًا.",s:0,t:"Ich danke Ihnen. Ich würde mich freuen, bald wieder mit Ihnen zu diskutieren."},{ar:"بكل سرور. إلى اللقاء!",s:1,t:"Sehr gern. Auf Wiedersehen!"},{ar:"إلى اللقاء!",s:0,t:"Auf Wiedersehen!"},{ar:"آه، هل تخبرني باختصار أين المخرج؟",s:1,t:"Ach, könnten Sie mir noch kurz sagen, wo der Ausgang ist?"},{ar:"بالطبع. هل تتبعني من فضلك؟ سأريك الطريق.",s:0,t:"Natürlich. Würden Sie mir bitte folgen? Ich zeige Ihnen den Weg."},{ar:"شكرًا جزيلًا، هذا لطف كبير منك.",s:1,t:"Vielen Dank, das wäre sehr nett."},{ar:"على الرحب والسعة!",s:0,t:"Gern geschehen!"},{ar:"أتمنى لك يومًا جميلًا!",s:1,t:"Einen schönen Tag noch!"},{ar:"لك أيضًا!",s:0,t:"Ihnen auch!"},{ar:"إلى الغد في الساعة العاشرة!",s:1,t:"Bis morgen um zehn Uhr!"},{ar:"إلى الغد!",s:0,t:"Bis morgen!"},{ar:"أتطلع إلى ذلك!",s:1,t:"Ich freue mich darauf!"},{ar:"وأنا أيضًا!",s:0,t:"Ich mich auch!"}]},emoji:"💬",grammar:{covers:1,id:"de-b1-konjunktiv2-hoeflich",title:"Konjunktiv II: höfliche Bitten",titleAr:"صيغة التمني: الطلبات المهذبة"},stage:12,title:"إبداء الرأي والمناقشة",topic:"social",topicAr:"المواقف الاجتماعية",topicDe:"Meinung sagen: Diskussion",topicEn:"Giving opinions: discussion"}]};var CONV_DATA_B2={en:[{stage:1,topic:"environment",topicAr:"البيئة والطبيعة",topicEn:"Environment & Nature",topicDe:"Umwelt und Natur",emoji:"🌳",title:"النقاش حول المناخ",grammar:{id:"en-b2-third-conditional",title:"Third conditional",titleAr:"الشرط الثالث",covers:1},conv:{id:"en-stage1-b2",speakers:["Activist (الناشط البيئي)","Skeptic (المشكك)"],turns:[{s:0,t:"Okay, let's be honest — the planet's warming up, and we're running out of time.",ar:"حسنًا، لنكن صريحين — الكوكب يسخن، والوقت ينفد منا."},{s:1,t:"Yeah, I hear that all the time, but honestly, I reckon it's exaggerated.",ar:"نعم، أسمع ذلك طوال الوقت، لكن بصراحة، أظن أنه مبالغ فيه."},{s:0,t:"Exaggerated? The evidence is everywhere. If we'd acted twenty years ago, we wouldn't be in this mess now.",ar:"مبالغ فيه؟ الأدلة في كل مكان. لو تصرفنا قبل عشرين عامًا، لما كنا في هذه الفوضى الآن."},{s:1,t:"If we'd acted sooner, the economy would've collapsed. You can't just shut everything down.",ar:"لو تصرفنا مبكرًا، لكان الاقتصاد قد انهار. لا يمكنك إغلاق كل شيء هكذا."},{s:0,t:"Nobody's saying shut it all down. We're saying switch to solar and cut our carbon footprint.",ar:"لا أحد يقول أغلقوا كل شيء. نقول تحوّلوا إلى الطاقة الشمسية وخفّضوا بصمتنا الكربونية."},{s:1,t:"Solar's great on paper, but it's not affordable for most families yet.",ar:"الطاقة الشمسية رائعة على الورق، لكنها ليست في متناول معظم العائلات بعد."},{s:0,t:"It is affordable now — the price has dropped dramatically, and governments offer an incentive to install it.",ar:"هي في المتناول الآن — انخفض سعرها بشكل كبير، والحكومات تقدم حوافز لتركيبها."},{s:1,t:"An incentive? A few bucks off a huge bill? Come on.",ar:"حافز؟ بضعة دولارات من فاتورة ضخمة؟ هيا."},{s:0,t:"It's not just a few bucks. Look, if the government had invested in infrastructure earlier, panels would be everywhere by now.",ar:"ليست مجرد بضعة دولارات. انظر، لو استثمرت الحكومة في البنية التحتية مبكرًا، لكانت الألواح في كل مكان الآن."},{s:1,t:"Maybe. But what about wildlife? Those giant wind farms mess up habitats too.",ar:"ربما. لكن ماذا عن الحياة البرية؟ مزارع الرياح العملاقة تدمر الموائل أيضًا."},{s:0,t:"Fair point, but the destruction from fossil fuels is far worse — we're losing habitats every single day.",ar:"نقطة وجيهة، لكن الدمار الناتج عن الوقود الأحفوري أسوأ بكثير — نفقد الموائل كل يوم."},{s:1,t:"I mean, if we'd never discovered oil, we'd still be riding horses. You can't undo history.",ar:"أعني، لو لم نكتشف النفط أبدًا، لكنا ما زلنا نركب الخيول. لا يمكنك التراجع عن التاريخ."},{s:0,t:"True, but we can change the future. Agriculture alone pumps out a huge share of emissions.",ar:"صحيح، لكن يمكننا تغيير المستقبل. الزراعة وحدها تنتج حصة ضخمة من الانبعاثات."},{s:1,t:"So what, we stop eating? Farmers are barely getting by as it is.",ar:"إذن ماذا، نتوقف عن الأكل؟ المزارعون بالكاد يعيشون كما هم."},{s:0,t:"No one says stop eating. But if we'd supported sustainable farming sooner, our crops would be safer from drought now.",ar:"لا أحد يقول توقفوا عن الأكل. لكن لو دعمنا الزراعة المستدامة مبكرًا، لكانت محاصيلنا أكثر أمانًا من الجفاف الآن."},{s:1,t:"Drought, floods, whatever — the climate's always changed. It's natural.",ar:"جفاف، فيضانات، أيًا كان — المناخ يتغير دائمًا. هذا طبيعي."},{s:0,t:"It's changing way too fast to be natural, and the extent of the damage proves it.",ar:"إنه يتغير بسرعة كبيرة جدًا ليكون طبيعيًا، وحجم الضرر يثبت ذلك."},{s:1,t:"Alright, alright. Say I believe you — what do you actually want me to do?",ar:"حسنًا، حسنًا. لنفترض أنني أصدقك — ماذا تريد مني أن أفعل فعلًا؟"},{s:0,t:"Start small. Cut waste, use public transport, and push your council to protect the shore and the harbor.",ar:"ابدأ بخطوات صغيرة. قلل النفايات، استخدم المواصلات العامة، واضغط على مجلسك لحماية الشاطئ والميناء."},{s:1,t:"The council? They can't even fix the roads. They'd never fund conservation.",ar:"المجلس؟ لا يستطيعون حتى إصلاح الطرق. لن يمولوا أبدًا جهود الحفاظ على البيئة."},{s:0,t:"Then vote for people who will. If voters had demanded action years ago, the laws would already exist.",ar:"إذن صوّت لمن سيفعل. لو طالب الناخبون بالتحرك قبل سنوات، لكانت القوانين موجودة الآن."},{s:1,t:"Hmm. You know what, I watched a documentary last night — the one about the ocean.",ar:"همم. تعرف ماذا، شاهدت وثائقيًا الليلة الماضية — عن المحيط."},{s:0,t:"Oh yeah? The one with the coral reefs dying?",ar:"حقًا؟ الذي عن الشعاب المرجانية التي تموت؟"},{s:1,t:"Yeah, that one. It was... depressing, honestly. All that plastic.",ar:"نعم، ذلك. كان... محبطًا، بصراحة. كل ذلك البلاستيك."},{s:0,t:"Exactly. And plastic comes from oil. It's all connected — the air, the sea, the oxygen we breathe.",ar:"بالضبط. والبلاستيك يأتي من النفط. كل شيء مترابط — الهواء، البحر، الأكسجين الذي نتنفسه."},{s:1,t:"Okay, you've got my attention. But one person can't fix this.",ar:"حسنًا، لفتَّ انتباهي. لكن شخصًا واحدًا لا يستطيع إصلاح هذا."},{s:0,t:"One person can't, but millions can. Awareness spreads — that's how movements start.",ar:"شخص واحد لا يستطيع، لكن الملايين يستطيعون. الوعي ينتشر — هكذا تبدأ الحركات."},{s:1,t:"Movements... I guess. But I still think technology will save us, not protests.",ar:"الحركات... أظن ذلك. لكني ما زلت أعتقد أن التكنولوجيا ستنقذنا، لا الاحتجاجات."},{s:0,t:"Technology helps, sure. But if we'd relied only on tech, we'd have waited forever while the forests burned.",ar:"التكنولوجيا تساعد، بالتأكيد. لكن لو اعتمدنا على التكنولوجيا وحدها، لانتظرنا إلى الأبد بينما تحترق الغابات."},{s:1,t:"Fair enough. So where do we start — like, this week?",ar:"حسنًا. إذن من أين نبدأ — مثلًا، هذا الأسبوع؟"},{s:0,t:"This week? Join the beach cleanup on Saturday. Bring a friend.",ar:"هذا الأسبوع؟ انضم إلى حملة تنظيف الشاطئ يوم السبت. أحضر صديقًا."},{s:1,t:"A beach cleanup... I can do that. But I'm not hugging any trees.",ar:"تنظيف شاطئ... يمكنني فعل ذلك. لكنني لن أعانق أي أشجار."},{s:0,t:"Deal. No tree-hugging required. Just show up.",ar:"اتفقنا. لا حاجة لمعانقة الأشجار. فقط احضر."},{s:1,t:"Alright, I'm in. But if it rains, I'm out.",ar:"حسنًا، أنا معك. لكن إذا أمطرت، فأنا خارج."},{s:0,t:"If it rains, we'll still be there — with umbrellas. No excuses!",ar:"إذا أمطرت، سنكون هناك أيضًا — بالمظلات. لا أعذار!"},{s:1,t:"Ha! Fine. And hey — if we'd had this chat a year ago, I might've joined sooner.",ar:"ها! حسنًا. ومهلًا — لو أجرينا هذا الحديث قبل عام، ربما انضممت مبكرًا."},{s:0,t:"Better late than never. See you Saturday — and bring gloves.",ar:"أن تأتي متأخرًا خير من ألا تأتي. أراك السبت — وأحضر قفازات."},{s:1,t:"Gloves, got it. And I'll bring my cousin too — he's been talking about this stuff lately.",ar:"قفازات، فهمت. وسأحضر ابن عمي أيضًا — لقد كان يتحدث عن هذه الأمور مؤخرًا."},{s:0,t:"Perfect. The more people, the better. That's how change actually happens.",ar:"ممتاز. كلما زاد عدد الناس، كان أفضل. هكذا يحدث التغيير فعلًا."},{s:1,t:"Okay, okay, don't get all preachy on me now.",ar:"حسنًا، حسنًا، لا تبدأ بالوعظ عليّ الآن."},{s:0,t:"No preaching, I promise. Just... don't abandon the planet before you even try.",ar:"لا وعظ، أعدك. فقط... لا تتخلَّ عن الكوكب قبل أن تحاول أصلًا."},{s:0,t:"But a cleanup isn't enough, you know? We gotta push the council to assess the damage properly and tackle the root causes — a comprehensive study, not just guesses.",ar:"لكن التنظيف وحده لا يكفي، تعلم؟ يجب أن نضغط على المجلس لتقييم الضرر بشكل صحيح ومعالجة الأسباب الجذرية — دراسة شاملة، لا مجرد تخمينات."},{s:1,t:"A study? They'll hire a bunch of consultants and nothing will change.",ar:"دراسة؟ سيوظفون مجموعة من المستشارين ولن يتغير شيء."},{s:0,t:"The fundamental problem is we keep debating while the damage grows — the reefs are dying, the storms are getting worse.",ar:"المشكلة الأساسية هي أننا نواصل الجدال بينما يتزايد الضرر — الشعاب تموت، والعواصف تزداد سوءًا."},{s:1,t:"Last winter was brutal — my cousin's shop flooded twice, and the insurance barely covered it. He's still trying to recover.",ar:"الشتاء الماضي كان قاسيًا — متجر ابن عمي غمرته المياه مرتين، والتأمين بالكاد غطاه. وما زال يحاول التعافي."},{s:0,t:"Exactly — insurers are calling whole neighborhoods too risky to cover now. It's not abstract anymore.",ar:"بالضبط — شركات التأمين تعتبر أحياء كاملة خطيرة جدًا لتغطيتها الآن. الأمر لم يعد نظريًا."},{s:1,t:"Too risky to insure... So what happens to those families — do they just abandon their homes?",ar:"خطير جدًا للتأمين عليه... إذن ماذا يحدث لتلك العائلات — هل يتخلون عن بيوتهم فحسب؟"},{s:0,t:"Some do. They abandon homes their families lived in for generations. That's the human cost nobody talks about.",ar:"بعضهم يفعل. يتخلون عن بيوت عاشت فيها عائلاتهم لأجيال. هذه هي التكلفة البشرية التي لا يتحدث عنها أحد."},{s:1,t:"Human cost... I just assumed it was about polar bears and melting ice.",ar:"التكلفة البشرية... كنت أفترض فقط أن الأمر يتعلق بالدببة القطبية والجليد الذائب."},{s:0,t:"It's about people — farmers, fishermen, rural towns. And the solutions exist; we just lack the incentive to use them.",ar:"الأمر يتعلق بالناس — المزارعين، الصيادين، البلدات الريفية. والحلول موجودة؛ نفتقر فقط إلى الحافز لاستخدامها."},{s:1,t:"Lack the will... or lack the money? Going green sounds great until you see the fees.",ar:"نفتقر إلى الإرادة... أو نفتقر إلى المال؟ التحول إلى الأخضر يبدو رائعًا حتى ترى الرسوم."},{s:0,t:"Ultimately, doing nothing costs far more than acting — just ask anyone who lost a home to a flood.",ar:"في النهاية، عدم فعل شيء يكلف أكثر بكثير من التحرك — فقط اسأل أي شخص فقد منزله بسبب فيضان."},{s:1,t:"Yeah.",ar:"نعم."},{s:0,t:"Yeah? That's it?",ar:"نعم؟ هذا كل شيء؟"},{s:1,t:"No — I mean, you're right. I'll look into it thoroughly. But the economy—",ar:"لا — أعني، أنت محق. سأبحث في الأمر بدقة. لكن الاقتصاد—"},{s:0,t:"—The economy depends on a livable planet. That's the whole point.",ar:"—الاقتصاد يعتمد على كوكب صالح للعيش. هذه هي النقطة كلها."},{s:0,t:"The accurate figures are public — temperatures, sea levels, the lot. And additionally, the solutions create jobs: solar installers, engineers, a whole new workforce.",ar:"الأرقام الدقيقة علنية — درجات الحرارة، مستويات البحر، كل شيء. وبالإضافة إلى ذلك، الحلول تخلق وظائف: مركبو الطاقة الشمسية، مهندسون، قوى عاملة جديدة كاملة."},{s:1,t:"A whole new workforce? My cousin's been out of work for months — he'd take anything, honestly.",ar:"قوى عاملة جديدة كاملة؟ ابن عمي عاطل عن العمل منذ شهور — سيقبل أي شيء، بصراحة."},{s:0,t:"Then tell him to look into it. The training is free in some places, and the demand is considerable.",ar:"إذن أخبره أن يبحث في الأمر. التدريب مجاني في بعض الأماكن، والطلب كبير."},{s:1,t:"Considerable demand... Alright, I'll mention it. But I'm still not chaining myself to a tree.",ar:"طلب كبير... حسنًا، سأذكره. لكنني ما زلت لن أقيد نفسي بشجرة."},{s:0,t:"No chains needed. The approach is simple: show up, help out, and spread the word.",ar:"لا حاجة للقيود. النهج بسيط: احضر، وساعد، وانشر الكلمة."},{s:1,t:"Spread the word... I can do that. My group chat has like forty people in it.",ar:"انشر الكلمة... يمكنني فعل ذلك. مجموعة محادثتي فيها نحو أربعين شخصًا."},{s:0,t:"Forty people! If each of them brings one friend, that's a movement.",ar:"أربعون شخصًا! إذا أحضر كل منهم صديقًا واحدًا، فهذه حركة."},{s:1,t:"A movement... Okay, now you're getting dramatic. But fine — Saturday, I'm there.",ar:"حركة... حسنًا، الآن أصبحت دراميًا. لكن حسنًا — السبت، سأكون هناك."},{s:1,t:"I'm not abandoning anything. I'm literally going to pick up trash on Saturday.",ar:"لست أتخلى عن شيء. سأذهب حرفيًا لالتقاط القمامة يوم السبت."},{s:0,t:"Then we're good. One cleanup at a time.",ar:"إذن نحن بخير. حملة تنظيف واحدة في كل مرة."},{s:1,t:"One cleanup at a time. I can live with that.",ar:"حملة تنظيف واحدة في كل مرة. يمكنني التعايش مع ذلك."}]}},{stage:2,topic:"technology",topicAr:"التكنولوجيا والإنترنت",topicEn:"Technology & Internet",topicDe:"Technologie und Internet",emoji:"💻",title:"التكنولوجيا تسيطر على حياتنا",grammar:{id:"en-b2-mixed-conditionals",title:"Mixed conditionals",titleAr:"الشرط المختلط",covers:1},conv:{id:"en-stage2-b2",speakers:["Tech Enthusiast (المتحمس للتكنولوجيا)","Critic (الناقد)"],turns:[{s:0,t:"Look, if you don't love AI, you're living in the past. It's changing everything.",ar:"انظر، إذا كنت لا تحب الذكاء الاصطناعي، فأنت تعيش في الماضي. إنه يغير كل شيء."},{s:1,t:"Oh, come on. If I'd wanted a robot to think for me, I'd have bought one years ago.",ar:"هيا. لو أردت روبوتًا يفكر بدلًا مني، لاشتريت واحدًا قبل سنوات."},{s:0,t:"But that's the thing — if we hadn't invented AI, we wouldn't have these tools today.",ar:"لكن هذا هو الأمر — لو لم نخترع الذكاء الاصطناعي، لما كانت لدينا هذه الأدوات اليوم."},{s:1,t:"Tools? You call it a tool. I call it an addiction. People can't put their phones down.",ar:"أدوات؟ أنت تسميه أداة. أنا أسميه إدمانًا. الناس لا يستطيعون ترك هواتفهم."},{s:0,t:"Addiction is a choice, though. If people used tech wisely, they wouldn't be hooked.",ar:"الإدمان خيار، مع ذلك. لو استخدم الناس التكنولوجيا بحكمة، لما أصبحوا مدمنين عليها."},{s:1,t:"Wisely? The apps are designed to hook you and grab your attention! If the designers hadn't made them addictive, nobody would scroll for hours.",ar:"بحكمة؟ التطبيقات مصممة لتجعلك مدمنًا وتجذب انتباهك! لو لم يصممها المطورون لتكون مسببة للإدمان، لما تصفح أحد لساعات."},{s:0,t:"Okay, fair. But the same tech lets me work from anywhere. If I didn't have my laptop, I'd be stuck in an office.",ar:"حسنًا، صحيح. لكن التكنولوجيا نفسها تتيح لي العمل من أي مكان. لو لم يكن لدي حاسوبي المحمول، لكنت عالقًا في مكتب."},{s:1,t:"Stuck in an office? At least you'd talk to real humans. Now everyone's isolated behind a screen.",ar:"عالق في مكتب؟ على الأقل كنت ستتحدث مع بشر حقيقيين. الآن الجميع معزول خلف شاشة."},{s:0,t:"Isolated? I'm in three group chats right now! If social media didn't exist, I wouldn't know half my friends anymore.",ar:"معزول؟ أنا في ثلاث مجموعات محادثة الآن! لو لم توجد وسائل التواصل الاجتماعي، لما عرفت نصف أصدقائي الآن."},{s:1,t:"Group chats aren't friendship. You barely know those people.",ar:"المحادثات الجماعية ليست صداقة. أنت بالكاد تعرف هؤلاء الناس."},{s:0,t:"Harsh. But look — my grandma video-calls me every week. If she hadn't learned to use a tablet, we'd barely talk.",ar:"قاسٍ. لكن انظر — جدتي تتصل بي بالفيديو كل أسبوع. لو لم تتعلم استخدام الجهاز اللوحي، لما تحدثنا إلا نادرًا."},{s:1,t:"Alright, that's genuinely sweet. I'll give you that one.",ar:"حسنًا، هذا لطيف فعلًا. سأمنحك هذه النقطة."},{s:0,t:"See? Tech connects people. And the innovation isn't stopping — virtual reality, smart homes, everything.",ar:"أرأيت؟ التكنولوجيا تربط الناس. والابتكار لا يتوقف — الواقع الافتراضي، المنازل الذكية، كل شيء."},{s:1,t:"Smart homes... My neighbor's fridge ordered milk by itself. That's not smart, that's creepy.",ar:"منازل ذكية... ثلاجة جاري طلبت الحليب بنفسها. هذا ليس ذكيًا، هذا مخيف."},{s:0,t:"Ha! But if the fridge hadn't ordered it, he'd have run out of milk. It's efficient.",ar:"ها! لكن لو لم تطلب الثلاجة الحليب، لنفد منه. إنها فعالة."},{s:1,t:"Efficiently wasting money, maybe. And what about privacy? These gadgets listen to everything.",ar:"تهدر المال بكفاءة، ربما. وماذا عن الخصوصية؟ هذه الأجهزة تستمع إلى كل شيء."},{s:0,t:"Privacy matters, I agree. If companies were transparent, people would trust them more.",ar:"الخصوصية مهمة، أوافق. لو كانت الشركات شفافة، لثق بها الناس أكثر."},{s:1,t:"Transparent? They sell our data! If I had known that ten years ago, I'd never have signed up.",ar:"شفافة؟ إنهم يبيعون بياناتنا! لو عرفت ذلك قبل عشر سنوات، لما سجلت أبدًا."},{s:0,t:"You can delete your accounts, you know. Nobody's forcing you.",ar:"يمكنك حذف حساباتك، كما تعلم. لا أحد يجبرك."},{s:1,t:"Delete my accounts? Then I'd lose my photos, my contacts — everything. It's a trap.",ar:"أحذف حساباتي؟ عندها سأفقد صوري وجهات اتصالي — كل شيء. إنه فخ."},{s:0,t:"It's a trade-off. You get free services; they get data. If you want total privacy, you'd have to go offline completely.",ar:"إنها مقايضة. تحصل على خدمات مجانية؛ وهم يحصلون على البيانات. إذا أردت خصوصية كاملة، فسيتعين عليك الانقطاع عن الإنترنت تمامًا."},{s:1,t:"Maybe I should! If I went offline for a month, I'd probably feel amazing.",ar:"ربما يجب أن أفعل! لو انقطعت عن الإنترنت لشهر، لشعرت على الأرجح بشعور رائع."},{s:0,t:"You'd last two days, tops. You'd beg for Wi-Fi by Tuesday.",ar:"ستصمد يومين، كحد أقصى. ستتوسل من أجل الواي فاي بحلول الثلاثاء."},{s:1,t:"Two days? Give me some credit. I'd last a week, easy.",ar:"يومان؟ امنحني بعض التقدير. سأصمد أسبوعًا، بسهولة."},{s:0,t:"Wanna bet? Ten bucks says you crack by day three.",ar:"هل تراهن؟ عشرة دولارات أنك ستنهار بحلول اليوم الثالث."},{s:1,t:"Ten bucks? You're on. But no cheating — no sneaky scrolling at midnight.",ar:"عشرة دولارات؟ اتفقنا. لكن بلا غش — لا تصفح خفي في منتصف الليل."},{s:0,t:"Deal. But seriously — tech isn't the villain. It's how we use it.",ar:"اتفقنا. لكن بجدية — التكنولوجيا ليست الشرير. الأمر يتعلق بكيفية استخدامنا لها."},{s:1,t:"Hmm. If schools taught kids that, we wouldn't have this mess.",ar:"همم. لو علمت المدارس الأطفال ذلك، لما كنا في هذه الفوضى."},{s:0,t:"Exactly! Education, not fear. If we'd taught digital skills earlier, kids would be smarter users now.",ar:"بالضبط! التعليم، لا الخوف. لو علمنا المهارات الرقمية مبكرًا، لكان الأطفال مستخدمين أذكى الآن."},{s:1,t:"Okay, I like that. Teach them to question the screen, not worship it.",ar:"حسنًا، يعجبني ذلك. علّمهم أن يشككوا في الشاشة، لا أن يعبدوها."},{s:0,t:"Question everything — including me. That's the whole point.",ar:"شكك في كل شيء — بما في ذلك أنا. هذه هي النقطة كلها."},{s:1,t:"Oh, I question you plenty. Don't worry about that.",ar:"أوه، أنا أشكك فيك كثيرًا. لا تقلق بشأن ذلك."},{s:0,t:"Good. Now — you still in for the bet? Starting Monday?",ar:"جيد. الآن — ما زلت موافقًا على الرهان؟ يبدأ الاثنين؟"},{s:1,t:"Monday it is. One week, no social media. If I win, you buy lunch.",ar:"الاثنين إذن. أسبوع واحد، بلا وسائل تواصل اجتماعي. إذا فزت، تشتري لي الغداء."},{s:0,t:"And if you lose, you admit tech isn't evil.",ar:"وإذا خسرت، تعترف بأن التكنولوجيا ليست شريرة."},{s:1,t:"Not evil... just dangerous. Deal?",ar:"ليست شريرة... فقط خطيرة. اتفقنا؟"},{s:0,t:"Deal. Shake on it — the old-fashioned way, no app needed.",ar:"اتفقنا. نصافح — بالطريقة القديمة، بلا تطبيق."},{s:1,t:"Ha! The old-fashioned way. I like that.",ar:"ها! بالطريقة القديمة. يعجبني ذلك."},{s:0,t:"See? You can survive without tech. At least for a handshake.",ar:"أرأيت؟ يمكنك البقاء دون تكنولوجيا. على الأقل من أجل مصافحة."},{s:1,t:"Don't push it. Monday hasn't even started.",ar:"لا تضغط. الاثنين لم يبدأ حتى."},{s:0,t:"Relax. I'm rooting for you — honestly.",ar:"اهدأ. أنا أشجعك — بصدق."},{s:0,t:"And honestly, the artificial stuff is just the start — the next wave is gonna be wild.",ar:"وبصراحة، الأشياء الاصطناعية مجرد البداية — الموجة التالية ستكون جنونية."},{s:1,t:"Wild how? More gadgets spying on us?",ar:"جنونية كيف؟ المزيد من الأجهزة التي تتجسس علينا؟"},{s:0,t:"Wild like your fridge talking to your car. The electronics in our homes are all connected now.",ar:"جنونية مثل ثلاجتك تتحدث إلى سيارتك. الإلكترونيات في بيوتنا كلها متصلة الآن."},{s:1,t:"Connected... and hackable. My password got stolen last year — total nightmare.",ar:"متصلة... وقابلة للاختراق. سُرقت كلمة مروري العام الماضي — كابوس كامل."},{s:0,t:"Nightmare, yeah. But that's a security problem, not a tech problem. The mechanism is fine; the habits are bad.",ar:"كابوس، نعم. لكن هذه مشكلة أمنية، ليست مشكلة تقنية. الآلية سليمة؛ العادات سيئة."},{s:1,t:"Habits... You mean I should've used a stronger password? I know, I know.",ar:"العادات... تعني أنه كان يجب أن أستخدم كلمة مرور أقوى؟ أعرف، أعرف."},{s:0,t:"You should've, yeah. And turn on two-factor. It takes ten seconds.",ar:"كان يجب عليك، نعم. وفعّل التحقق بخطوتين. يستغرق عشر ثوانٍ."},{s:1,t:"Ten seconds? Fine, I'll do it. But what about the kids — they're online constantly.",ar:"عشر ثوانٍ؟ حسنًا، سأفعل. لكن ماذا عن الأطفال — إنهم على الإنترنت باستمرار."},{s:0,t:"Constantly, yeah. That's why schools gotta teach programming early — not to make coders, but to make kids understand the machine.",ar:"باستمرار، نعم. لهذا يجب أن تعلم المدارس البرمجة مبكرًا — ليس لصنع مبرمجين، بل لجعل الأطفال يفهمون الآلة."},{s:1,t:"Understand the machine... I like that. But who teaches the teachers? They're lost too.",ar:"يفهمون الآلة... يعجبني ذلك. لكن من يعلم المعلمين؟ هم ضائعون أيضًا."},{s:0,t:"Good point. There's a real shortage of trained teachers — that's the gap.",ar:"نقطة جيدة. هناك نقص حقيقي في المعلمين المدربين — هذه هي الفجوة."},{s:1,t:"A shortage of teachers, a flood of screens... no wonder parents are anxious.",ar:"نقص في المعلمين، وفيض من الشاشات... لا عجب أن الآباء قلقون."},{s:0,t:"Anxious, yeah. But banning screens won't work either. Kids will just find a way around it.",ar:"قلقون، نعم. لكن حظر الشاشات لن ينجح أيضًا. سيجد الأطفال طريقًا للالتفاف عليه."},{s:1,t:"Uh-huh.",ar:"أها."},{s:0,t:"Uh-huh? You agree for once?",ar:"أها؟ توافق مرة واحدة؟"},{s:1,t:"For once, yeah. Teach them, don't just ban it. But my Wi-Fi—",ar:"لمرة واحدة، نعم. علمهم، لا تحظر فقط. لكن الواي فاي الخاص بي—"},{s:0,t:"—Your Wi-Fi will survive one week offline. I promise.",ar:"—الواي فاي الخاص بك سيبقى أسبوعًا دون اتصال. أعدك."},{s:0,t:"Here's another angle — the tech giants insist they're helping, but their real incentive is profit. That's it.",ar:"إليك زاوية أخرى — عمالقة التكنولوجيا يصرون على أنهم يساعدون، لكن حافزهم الحقيقي هو الربح. هذا كل شيء."},{s:1,t:"Profit, obviously. But does that make the tools bad? A hammer can build or break things.",ar:"الربح، بديهي. لكن هل هذا يجعل الأدوات سيئة؟ المطرقة يمكن أن تبني أو تكسر."},{s:0,t:"A hammer doesn't track you, though. These companies collect data constantly — every tap, every search.",ar:"لكن المطرقة لا تتعقبك. هذه الشركات تجمع البيانات باستمرار — كل نقرة، كل بحث."},{s:1,t:"Every tap... creepy when you put it that way. But I still love my phone. I'm not giving it up.",ar:"كل نقرة... مخيف عندما تضعه بهذه الطريقة. لكنني ما زلت أحب هاتفي. لن أتخلى عنه."},{s:0,t:"Nobody's asking you to. Just be conscious of it — check your settings, limit the tracking.",ar:"لا أحد يطلب منك ذلك. فقط كن واعيًا — تحقق من إعداداتك، وحدد التتبع."},{s:1,t:"Check my settings... I wouldn't even know where to start. It's all buried in menus.",ar:"أتحقق من إعداداتي... لا أعرف حتى من أين أبدأ. كل شيء مدفون في القوائم."},{s:0,t:"Buried on purpose, probably. But it takes five minutes — I'll walk you through it after the bet.",ar:"مدفون عمدًا، على الأرجح. لكنه يستغرق خمس دقائق — سأرشدك خلاله بعد الرهان."},{s:1,t:"After the bet... which I'm gonna win, by the way.",ar:"بعد الرهان... الذي سأفوز به، بالمناسبة."},{s:1,t:"Yeah, yeah. We'll see who's laughing on Friday.",ar:"نعم، نعم. سنرى من سيضحك يوم الجمعة."},{s:0,t:"Friday. Mark it on your calendar — on paper, if you dare.",ar:"الجمعة. ضع علامة على تقويمك — على الورق، إن تجرأت."},{s:1,t:"On paper. Now that's a challenge.",ar:"على الورق. الآن هذا تحدٍّ."}]}},{stage:3,topic:"news",topicAr:"الأخبار والأحداث الجارية",topicEn:"News & Current Events",topicDe:"Nachrichten und Aktuelles",emoji:"📰",title:"هل نثق بالأخبار؟",grammar:{id:"en-b2-third-conditional",title:"Third conditional",titleAr:"الشرط الثالث",covers:1},conv:{id:"en-stage3-b2",speakers:["Journalist (الصحفي)","Reader (القارئ)"],turns:[{s:0,t:"So, you said you don't trust the news anymore. That's a pretty strong stance.",ar:"إذن، قلت إنك لم تعد تثق بالأخبار. هذا موقف قوي جدًا."},{s:1,t:"Strong? It's honest. Half of what I read turns out to be fake or twisted.",ar:"قوي؟ إنه صادق. نصف ما أقرأه يتبين أنه مزيف أو محرّف."},{s:0,t:"Half? Come on. You must have seen some solid reporting too.",ar:"النصف؟ هيا. لا بد أنك رأيت بعض التقارير الجيدة أيضًا."},{s:1,t:"Sure, some. But the big stories? They should have been accurate before publishing.",ar:"بالتأكيد، بعضها. لكن القصص الكبيرة؟ كان يجب أن يكونوا دقيقين قبل النشر."},{s:0,t:"Fair — they should have. But deadlines are brutal. A reporter can't always wait.",ar:"صحيح — كان يجب عليهم. لكن المواعيد النهائية قاسية. لا يستطيع المراسل الانتظار دائمًا."},{s:1,t:"Then they should have waited. Better late than wrong, right?",ar:"إذن كان يجب أن ينتظروا. متأخرًا أفضل من مخطئ، أليس كذلك؟"},{s:0,t:"In theory, yeah. But if they'd waited, someone else would've broken the story first.",ar:"نظريًا، نعم. لكن لو انتظروا، لكان شخص آخر قد نشر القصة أولًا."},{s:1,t:"That's the problem! Speed over accuracy. They might have gotten it right if they'd slowed down.",ar:"هذه هي المشكلة! السرعة على حساب الدقة. ربما كانوا سيصيبون لو تمهلوا."},{s:0,t:"Look, I get the frustration. But you can't paint all journalists with the same brush.",ar:"انظر، أفهم الإحباط. لكن لا يمكنك أن تحكم على جميع الصحفيين بنفس الطريقة."},{s:1,t:"I'm not. I'm saying the system rewards clicks, not truth. The bias is obvious.",ar:"لست أفعل. أقول إن النظام يكافئ النقرات، لا الحقيقة. التحيز واضح."},{s:0,t:"Bias exists, sure. But a good editor catches it. Our editorial team checks every claim twice.",ar:"التحيز موجود، بالتأكيد. لكن المحرر الجيد يكشفه. فريق التحرير لدينا يتحقق من كل ادعاء مرتين."},{s:1,t:"Twice? Then how did that story about the mayor get through? It was full of errors.",ar:"مرتين؟ إذن كيف مرت تلك القصة عن العمدة؟ كانت مليئة بالأخطاء."},{s:0,t:"That one... yeah, that was a failure. We could have done better. We should have verified the source.",ar:"تلك... نعم، كانت فشلًا. كان بإمكاننا أن نفعل أفضل. كان يجب أن نتحقق من المصدر."},{s:1,t:"See? And the correction came three days later, buried at the bottom of the page.",ar:"أرأيت؟ وجاء التصحيح بعد ثلاثة أيام، مدفونًا في أسفل الصفحة."},{s:0,t:"I won't defend that. We must have rushed it — the pressure was intense that week.",ar:"لن أدافع عن ذلك. لا بد أننا استعجلنا — كان الضغط شديدًا ذلك الأسبوع."},{s:1,t:"Pressure or not, people believed it. The damage was done.",ar:"ضغطًا أم لا، الناس صدقوه. والضرر قد وقع."},{s:0,t:"True. And that's exactly why trust matters. Once it's gone, it's hard to restore.",ar:"صحيح. ولهذا السبب تحديدًا تهم الثقة. بمجرد ذهابها، يصعب استعادتها."},{s:1,t:"Hard? I'd say impossible. Look at the conspiracy theories now — people believe anything.",ar:"صعب؟ أقول مستحيل. انظر إلى نظريات المؤامرة الآن — الناس يصدقون أي شيء."},{s:0,t:"Those theories spread because people feel ignored. If the media had listened more, folks might have trusted it.",ar:"تلك النظريات تنتشر لأن الناس يشعرون بالتجاهل. لو استمعت وسائل الإعلام أكثر، لربما وثق بها الناس."},{s:1,t:"Maybe. But social media made it worse. Anyone can post anything now.",ar:"ربما. لكن وسائل التواصل الاجتماعي جعلت الأمر أسوأ. أي شخص يمكنه نشر أي شيء الآن."},{s:0,t:"Exactly — and that's not journalism. A random post isn't reporting. Real reporting takes investigation.",ar:"بالضبط — وهذا ليس صحافة. منشور عشوائي ليس تقريرًا. التقارير الحقيقية تتطلب تحقيقًا."},{s:1,t:"Investigation takes time and money. Who pays for it now? Nobody reads paid news.",ar:"التحقيق يستغرق وقتًا ومالًا. من يدفع مقابله الآن؟ لا أحد يقرأ الأخبار المدفوعة."},{s:0,t:"Some do. Our subscribers keep us alive. If readers hadn't supported us, we'd have shut down.",ar:"بعضهم يفعل. مشتركونا يبقوننا أحياء. لو لم يدعمنا القراء، لأغلقنا."},{s:1,t:"Hmm. I never thought about it that way. So free news isn't really free.",ar:"همم. لم أفكر في الأمر بهذه الطريقة أبدًا. إذن الأخبار المجانية ليست مجانية فعلًا."},{s:0,t:"Nope. If it's free, you're the product. Your attention gets sold to advertisers.",ar:"لا. إذا كانت مجانية، فأنت المنتج. انتباهك يُباع للمعلنين."},{s:1,t:"Ugh. That's depressing. So what do I do — pay for everything?",ar:"أوه. هذا محبط. إذن ماذا أفعل — أدفع مقابل كل شيء؟"},{s:0,t:"Not everything. Pick one solid source. Compare coverage. Check the facts yourself sometimes.",ar:"ليس كل شيء. اختر مصدرًا واحدًا موثوقًا. قارن التغطية. تحقق من الحقائق بنفسك أحيانًا."},{s:1,t:"Check facts myself? I don't have time for that. I just want the news, plain and simple.",ar:"أتحقق من الحقائق بنفسي؟ ليس لدي وقت لذلك. أريد الأخبار فقط، بسيطة وواضحة."},{s:0,t:"I hear you. But if you'd spent five minutes checking that viral story last week, you'd have spotted the fraud.",ar:"أسمعك. لكن لو قضيت خمس دقائق في التحقق من تلك القصة المنتشرة الأسبوع الماضي، لاكتشفت الاحتيال."},{s:1,t:"Which one? The one about the lottery winner?",ar:"أي قصة؟ التي عن الفائز باليانصيب؟"},{s:0,t:"Yeah, that one. The photo was from five years ago. Total fake.",ar:"نعم، تلك. الصورة كانت من قبل خمس سنوات. مزيفة تمامًا."},{s:1,t:"No way! I shared that with my whole family!",ar:"مستحيل! شاركتها مع عائلتي كلها!"},{s:0,t:"Ha! See — we all fall for it sometimes. Even I shared something dumb once.",ar:"ها! أرأيت — نقع جميعًا في ذلك أحيانًا. حتى أنا شاركت شيئًا سخيفًا مرة."},{s:1,t:"Okay, okay. So we're all gullible. What's the fix?",ar:"حسنًا، حسنًا. إذن نحن جميعًا ساذجون. ما الحل؟"},{s:0,t:"Slow down. Ask who benefits. And remember — if it makes you furious in two seconds, it might have been designed to.",ar:"تمهل. اسأل من المستفيد. وتذكر — إذا أغضبك في ثانيتين، فربما صُمم لذلك."},{s:1,t:"Designed to make me furious? That's... actually, that explains a lot.",ar:"صُمم ليغضبني؟ هذا... في الواقع، هذا يفسر الكثير."},{s:0,t:"Outrage sells. Calm reporting doesn't go viral. That's the trap.",ar:"الغضب يبيع. التقارير الهادئة لا تنتشر. هذا هو الفخ."},{s:1,t:"So the news should have stayed boring? Is that what you're saying?",ar:"إذن كان يجب أن تبقى الأخبار مملة؟ هل هذا ما تقوله؟"},{s:0,t:"Boring is underrated! Boring means someone checked the facts.",ar:"الممل أقل من قيمته! الممل يعني أن شخصًا ما تحقق من الحقائق."},{s:1,t:"Ha! Okay, I'll give boring a chance. One source, slow news, no outrage clicks.",ar:"ها! حسنًا، سأعطي الممل فرصة. مصدر واحد، أخبار بطيئة، بلا نقرات غاضبة."},{s:0,t:"Deal. And hey — you could have been a journalist, you know. You ask good questions.",ar:"اتفقنا. ومهلًا — كان بإمكانك أن تكون صحفيًا، كما تعلم. تطرح أسئلة جيدة."},{s:1,t:"Me? No way. I'd have been fired in a week for arguing with my editor.",ar:"أنا؟ مستحيل. لطُردت في أسبوع لجدالي مع محرري."},{s:0,t:"Arguing with the editor is half the job. You'd fit right in.",ar:"الجدال مع المحرر نصف العمل. ستناسب المكان تمامًا."},{s:0,t:"And it's not just the big outlets — local broadcasters are dying too, and nobody notices.",ar:"وليس فقط المنافذ الكبيرة — المذيعون المحليون يموتون أيضًا، ولا أحد يلاحظ."},{s:1,t:"Dying? Why? Don't people still watch the local news?",ar:"يموتون؟ لماذا؟ ألا يشاهد الناس الأخبار المحلية بعد؟"},{s:0,t:"They watch clips online instead — thirty seconds, no context. The full story never reaches them.",ar:"يشاهدون المقاطع على الإنترنت بدلًا من ذلك — ثلاثون ثانية، بلا سياق. القصة الكاملة لا تصلهم أبدًا."},{s:1,t:"Thirty seconds... no wonder there's so much confusion. You can't explain a war in thirty seconds.",ar:"ثلاثون ثانية... لا عجب أن هناك الكثير من الارتباك. لا يمكنك شرح حرب في ثلاثين ثانية."},{s:0,t:"You can't. And the spokesperson just reads a statement — no questions allowed.",ar:"لا يمكنك. والمتحدث الرسمي يقرأ بيانًا فقط — بلا أسئلة مسموح بها."},{s:1,t:"No questions allowed? That's not a press conference, that's theater.",ar:"بلا أسئلة مسموح بها؟ هذا ليس مؤتمرًا صحفيًا، هذا مسرح."},{s:0,t:"Theater, exactly. Real reporting asks uncomfortable questions — that's the whole job.",ar:"مسرح، بالضبط. التقارير الحقيقية تطرح أسئلة محرجة — هذه هي الوظيفة كلها."},{s:1,t:"Uncomfortable questions... I respect that. But who pays for real reporting now?",ar:"أسئلة محرجة... أحترم ذلك. لكن من يدفع مقابل التقارير الحقيقية الآن؟"},{s:0,t:"Subscribers, mostly. And honestly, it's a reasonable fee — a few bucks a month for the truth.",ar:"المشتركون، غالبًا. وبصراحة، إنها رسوم معقولة — بضعة دولارات شهريًا مقابل الحقيقة."},{s:1,t:"A reasonable fee... okay, you might've convinced me. Which outlet do you recommend?",ar:"رسوم معقولة... حسنًا، ربما أقنعتني. أي منفذ توصي به؟"},{s:0,t:"I can't pick one for you — compare two or three, check their track record, and trust your gut.",ar:"لا أستطيع اختيار واحد لك — قارن اثنين أو ثلاثة، تحقق من سجلهم، وثق بحدسك."},{s:1,t:"I gotta admit, you make a fair case. But the comment sections—",ar:"يجب أن أعترف، أنت تقدم حجة عادلة. لكن أقسام التعليقات—"},{s:0,t:"—Avoid the comment sections. That's where speculation goes to party.",ar:"—تجنب أقسام التعليقات. هناك حيث تتجمع التكهنات."},{s:1,t:"Ha! Speculation goes to party. I'm stealing that line.",ar:"ها! التكهنات تذهب للحفلة. سأسرق هذه الجملة."},{s:0,t:"Steal away. Just don't quote me out of context.",ar:"اسرق كما تشاء. فقط لا تقتبسني خارج السياق."},{s:1,t:"Out of context... never. Cross my heart.",ar:"خارج السياق... أبدًا. أقسم."},{s:0,t:"One more thing — the coverage of the election was a mess. Every channel told a different story.",ar:"شيء آخر — تغطية الانتخابات كانت فوضى. كل قناة روت قصة مختلفة."},{s:1,t:"A different story... Yeah, I noticed that. My dad watches one channel, I watch another, and we argue at dinner.",ar:"قصة مختلفة... نعم، لاحظت ذلك. والدي يشاهد قناة، وأنا أشاهد أخرى، ونتجادل على العشاء."},{s:0,t:"Arguing at dinner — that's the real damage. Families split over headlines.",ar:"الجدال على العشاء — هذا هو الضرر الحقيقي. عائلات تنقسم بسبب العناوين."},{s:1,t:"Split over headlines... sad, but true. So how do we fix it? We can't force people to watch the same news.",ar:"تنقسم بسبب العناوين... محزن، لكنه صحيح. إذن كيف نصلحه؟ لا يمكننا إجبار الناس على مشاهدة نفس الأخبار."},{s:0,t:"We can't force it. But schools could teach media literacy — how to spot a lie, how to check a claim.",ar:"لا يمكننا فرضه. لكن المدارس يمكنها تعليم محو الأمية الإعلامية — كيف تكتشف الكذب، وكيف تتحقق من الادعاء."},{s:1,t:"Media literacy... I like that. It should be compulsory, like math.",ar:"محو الأمية الإعلامية... يعجبني ذلك. يجب أن يكون إلزاميًا، مثل الرياضيات."},{s:0,t:"Compulsory, yeah. If kids learned it early, the fake stuff wouldn't spread so fast.",ar:"إلزامي، نعم. لو تعلم الأطفال ذلك مبكرًا، لما انتشرت الأشياء المزيفة بهذه السرعة."},{s:1,t:"Wouldn't spread so fast... Okay, you've convinced me twice today. That's a record.",ar:"لما انتشرت بهذه السرعة... حسنًا، أقنعتني مرتين اليوم. هذا رقم قياسي."},{s:1,t:"Hmm. Maybe in another life. For now, I'll just be a skeptical reader.",ar:"همم. ربما في حياة أخرى. الآن، سأكون مجرد قارئ متشكك."},{s:0,t:"Skeptical is good. Just don't be cynical. There's a difference.",ar:"التشكك جيد. فقط لا تكن متشائمًا. هناك فرق."},{s:1,t:"Noted. Skeptical, not cynical. I'll try.",ar:"ملاحظة مسجلة. متشكك، لا متشائم. سأحاول."}]}},{stage:4,topic:"culture",topicAr:"الثقافة والقصص اليومية",topicEn:"Culture & Daily Stories",topicDe:"Kultur und Alltagsgeschichten",emoji:"🎭",title:"الفن بين التجديد والتقليد",grammar:{id:"en-b2-passive-modals",title:"Advanced passive",titleAr:"المبني للمجهول المتقدم",covers:1},conv:{id:"en-stage4-b2",speakers:["Artist (الفنان)","Critic (الناقد)"],turns:[{s:0,t:"So, my new show opens Friday. The whole collection is being exhibited for the first time.",ar:"إذن، معرضي الجديد يفتتح يوم الجمعة. المجموعة كلها تُعرض لأول مرة."},{s:1,t:"I heard. Honestly? The posters are everywhere. It's being hyped like crazy.",ar:"سمعت. بصراحة؟ الملصقات في كل مكان. يتم الترويج له بجنون."},{s:0,t:"Hyped? It's called publicity, my friend. Every artist needs it.",ar:"الترويج له بجنون؟ إنها دعاية يا صديقي. كل فنان يحتاجها."},{s:1,t:"Sure, but is it art? A blank canvas with one dot is being sold for thousands.",ar:"بالتأكيد، لكن هل هذا فن؟ لوحة فارغة بنقطة واحدة تُباع بآلاف الدولارات."},{s:0,t:"That dot is being misunderstood, as usual. It's about emptiness — the void we all feel.",ar:"تلك النقطة يُساء فهمها، كالعادة. إنها عن الفراغ — الفراغ الذي نشعر به جميعًا."},{s:1,t:"The void? Come on. My nephew could paint that in five minutes.",ar:"الفراغ؟ هيا. ابن أخي يستطيع رسم ذلك في خمس دقائق."},{s:0,t:"Maybe he could. But would it be shown in a gallery? Art is about context and creativity, not just skill.",ar:"ربما يستطيع. لكن هل سيُعرض في معرض؟ الفن يتعلق بالسياق والإبداع، لا بالمهارة فقط."},{s:1,t:"Context... That's a fancy excuse. The old masters are being forgotten while dots get praised.",ar:"السياق... هذا عذر فاخر. الأساتذة القدامى يُنسون بينما النقاط تُمدح."},{s:0,t:"Nobody's forgetting them. A classic is still a classic — it's being studied in every school.",ar:"لا أحد ينساهم. الكلاسيكي ما زال كلاسيكيًا — يُدرس في كل مدرسة."},{s:1,t:"Studied, sure. But who actually goes to see them? The museums are empty.",ar:"يُدرس، بالتأكيد. لكن من يذهب لرؤيتهم فعلًا؟ المتاحف فارغة."},{s:0,t:"Empty? The ballet last month was sold out. People crave live performance.",ar:"فارغة؟ عرض الباليه الشهر الماضي كان ممتلئًا. الناس يتوقون إلى العروض الحية."},{s:1,t:"Ballet, opera, orchestra — all beautiful, all dying. The young crowd wants short videos.",ar:"الباليه، الأوبرا، الأوركسترا — كلها جميلة، وكلها تموت. الجمهور الشاب يريد مقاطع قصيرة."},{s:0,t:"Then we bring the old forms to the new crowd. My show is being streamed live, did you know?",ar:"إذن نجلب الأشكال القديمة إلى الجمهور الجديد. عرضي يُبث مباشرة، هل تعلم؟"},{s:1,t:"Streamed? Hmm. That's actually smart. If it's being watched worldwide, that's real reach.",ar:"يُبث؟ همم. هذا ذكي فعلًا. إذا كان يُشاهد عالميًا، فهذا وصول حقيقي."},{s:0,t:"Exactly. Tradition doesn't have to be boring. It can be remixed, reimagined.",ar:"بالضبط. التقليد لا يجب أن يكون مملًا. يمكن إعادة مزجه وإعادة تخيله."},{s:1,t:"Remixed... Like that comedian who retells old tales as stand-up?",ar:"إعادة مزجه... مثل ذلك الكوميدي الذي يعيد سرد الحكايات القديمة كعرض كوميدي؟"},{s:0,t:"Yes! He was given a huge award last year, and honestly, he deserved it.",ar:"نعم! مُنح جائزة كبيرة العام الماضي، وبصراحة، كان يستحقها."},{s:1,t:"He's funny, I'll admit. But is a joke a form of art? It feels... lighter.",ar:"إنه مضحك، أعترف. لكن هل النكتة شكل من أشكال الفن؟ تبدو... أخف."},{s:0,t:"Comedy is being taken seriously now — finally. A good joke is crafted like a poem.",ar:"الكوميديا تُؤخذ على محمل الجد الآن — أخيرًا. النكتة الجيدة تُصاغ كقصيدة."},{s:1,t:"A poem... You know, my grandmother's tales were never written down. They were just told, night after night.",ar:"قصيدة... تعلم، حكايات جدتي لم تُكتب أبدًا. كانت تُروى فقط، ليلة بعد ليلة."},{s:0,t:"That's oral tradition — and it's being lost. That's why I paint those stories.",ar:"هذا تراث شفهي — وهو يُفقد. لهذا أرسم تلك القصص."},{s:1,t:"You paint them? Hmm. If those tales were illustrated, kids might actually read them.",ar:"أنت ترسمها؟ همم. لو رُسمت تلك الحكايات، لقرأها الأطفال فعلًا."},{s:0,t:"That's the plan. A graphic novel — old tales, modern drawings. It's being published next spring.",ar:"هذه هي الخطة. رواية مصورة — حكايات قديمة، رسوم حديثة. ستُنشر في الربيع المقبل."},{s:1,t:"A graphic novel? Okay, now you've got my attention. Who's writing it?",ar:"رواية مصورة؟ حسنًا، الآن لفتَّ انتباهي. من يكتبها؟"},{s:0,t:"A novelist I admire. She was praised for her last book — the critics loved it.",ar:"روائية أعجب بها. تم مدحها على كتابها الأخير — أحبه النقاد."},{s:1,t:"Critics loved it... Critics love everything weird. Remember that abstract sculpture?",ar:"أحبه النقاد... النقاد يحبون كل شيء غريب. تذكر ذلك التمثال التجريدي؟"},{s:0,t:"The one that looked like a twisted pipe? It was bought by a museum for a fortune.",ar:"الذي بدا كأنبوب ملتوي؟ اشتراه متحف بثروة."},{s:1,t:"A fortune! For a pipe! The world has gone mad.",ar:"ثروة! من أجل أنبوب! العالم جنّ."},{s:0,t:"Or maybe the world is just changing. Art is supposed to shock a little.",ar:"أو ربما العالم يتغير فقط. من المفترض أن يصدم الفن قليلًا."},{s:1,t:"Shock is easy. Meaning is hard. That's my whole point.",ar:"الصدمة سهلة. المعنى صعب. هذه هي نقطتي كلها."},{s:0,t:"Then come Friday and judge for yourself. The work is being shown — you can hate it in person.",ar:"إذن تعال يوم الجمعة واحكم بنفسك. العمل يُعرض — يمكنك أن تكرهه شخصيًا."},{s:1,t:"Hate it in person... That's an offer I can't refuse. What time?",ar:"أكرهه شخصيًا... هذا عرض لا أستطيع رفضه. في أي وقت؟"},{s:0,t:"Seven. And bring your nephew — the five-minute painter. Let him see the dot up close.",ar:"السابعة. وأحضر ابن أخك — الرسام ذا الخمس دقائق. دعه يرى النقطة عن قرب."},{s:1,t:"Ha! He'd probably say he could do better. Kids are brutally honest.",ar:"ها! ربما سيقول إنه يستطيع فعل أفضل. الأطفال صادقون بوحشية."},{s:0,t:"Brutally honest is the best review. Better than a polite critic.",ar:"الصدق الوحشي هو أفضل مراجعة. أفضل من ناقد مهذب."},{s:1,t:"Fair enough. Alright, Friday, seven o'clock. I'll be there — skeptical, but there.",ar:"حسنًا. إذن الجمعة، السابعة. سأكون هناك — متشككًا، لكن حاضرًا."},{s:0,t:"Skeptical is welcome. Just don't heckle the ballet dancers.",ar:"التشكك مرحب به. فقط لا تسخر من راقصي الباليه."},{s:1,t:"No promises. If the music's bad, I'm leaving at intermission.",ar:"لا وعود. إذا كانت الموسيقى سيئة، سأغادر في الاستراحة."},{s:0,t:"The music was composed by a friend of mine. You'll love it — or else.",ar:"الموسيقى ألفها صديق لي. ستحبها — أو غير ذلك."},{s:1,t:"Or else what? You'll paint my portrait as a villain?",ar:"أو غير ذلك ماذا؟ سترسم صورتي كشرير؟"},{s:0,t:"Worse. I'll make you the hero of the next tale. Everyone will laugh.",ar:"أسوأ. سأجعلك بطل الحكاية التالية. سيضحك الجميع."},{s:0,t:"You know, the funniest thing is — my artwork got rejected by three galleries before this one said yes.",ar:"تعلم، أطرف شيء هو — رُفضت أعمالي الفنية من ثلاث صالات قبل أن تقول هذه نعم."},{s:1,t:"Rejected three times? And you kept going? That's real commitment.",ar:"رُفضت ثلاث مرات؟ واستمررت؟ هذا التزام حقيقي."},{s:0,t:"Commitment, yeah. Or madness. The line is thin.",ar:"التزام، نعم. أو جنون. الخط رفيع."},{s:1,t:"Thin line... So what changed? Was it the evolution of your style, or did the galleries just catch up?",ar:"خط رفيع... إذن ماذا تغير؟ هل كان تطور أسلوبك، أم أن الصالات لحقت بك فحسب؟"},{s:0,t:"Both, honestly. I stopped trying to impress critics and started painting what I actually felt.",ar:"كلاهما، بصراحة. توقفت عن محاولة إبهار النقاد وبدأت أرسم ما شعرت به فعلًا."},{s:1,t:"Painting what you felt... That's when the colorful pieces showed up, right? The work got lively.",ar:"رسم ما شعرت به... عندها ظهرت القطع الملونة، أليس كذلك؟ أصبح العمل حيويًا."},{s:0,t:"Lively, yeah. Color is emotion — a red can shout, a blue can whisper.",ar:"حيوي، نعم. اللون عاطفة — الأحمر يستطيع الصراخ، والأزرق يستطيع الهمس."},{s:1,t:"A blue can whisper... Okay, you're a poet too.",ar:"الأزرق يستطيع الهمس... حسنًا، أنت شاعر أيضًا."},{s:0,t:"A poet with a paintbrush. But seriously — the preview night is gonna be packed. Critics, collectors, the whole crowd.",ar:"شاعر بفرشاة رسم. لكن بجدية — ليلة المعاينة ستكون مزدحمة. النقاد، الجامعون، الجمهور كله."},{s:1,t:"Collectors... So the rich folks decide what's good now?",ar:"الجامعون... إذن الأثرياء يقررون ما الجيد الآن؟"},{s:0,t:"They buy, they don't decide. The public decides — with time. A hundred years from now, we'll see what lasts.",ar:"إنهم يشترون، لا يقررون. الجمهور يقرر — مع الوقت. بعد مئة عام، سنرى ما يبقى."},{s:1,t:"A hundred years... I won't be around to see it. But my nephew—",ar:"مئة عام... لن أكون موجودًا لأراه. لكن ابن أخي—"},{s:0,t:"—Your nephew will. And he'll tell his kids about the dot.",ar:"—ابن أخك سيكون. وسيخبر أطفاله عن النقطة."},{s:1,t:"Ha! The dot lives forever. Fine — Friday, seven o'clock, I'm there.",ar:"ها! النقطة تعيش للأبد. حسنًا — الجمعة، السابعة، سأكون هناك."},{s:0,t:"The dot lives forever. I love it. See you there.",ar:"النقطة تعيش للأبد. أحب ذلك. أراك هناك."},{s:0,t:"Here's the thing nobody admits — most art is judged by its price tag, not its power.",ar:"إليك الأمر الذي لا يعترف به أحد — معظم الفن يُحكم عليه بسعره، لا بقوته."},{s:1,t:"Price tag, yeah. A painting sells for millions and suddenly it's a masterpiece.",ar:"سعره، نعم. لوحة تُباع بالملايين وفجأة تصبح تحفة."},{s:0,t:"Suddenly a masterpiece... Meanwhile, a brilliant street artist gets ignored because there's no gallery behind them.",ar:"فجأة تحفة... بينما فنان شارع لامع يُتجاهل لأنه لا توجد صالة خلفه."},{s:1,t:"Ignored... That's unfair. The street stuff is often more honest than the gallery stuff.",ar:"يُتجاهل... هذا غير عادل. فن الشارع غالبًا أكثر صدقًا من فن الصالات."},{s:0,t:"More honest, absolutely. It's made for people, not for investors.",ar:"أكثر صدقًا، بالتأكيد. إنه مصنوع للناس، لا للمستثمرين."},{s:1,t:"Made for people... So why do we worship the galleries then?",ar:"مصنوع للناس... إذن لماذا نعبد الصالات؟"},{s:0,t:"Because they tell us what's valuable. But value is a story — and stories can change.",ar:"لأنها تخبرنا بما هو قيّم. لكن القيمة قصة — والقصص يمكن أن تتغير."},{s:1,t:"Stories can change... Alright, philosopher-artist. Friday, seven, I'll be there.",ar:"القصص يمكن أن تتغير... حسنًا، أيها الفنان الفيلسوف. الجمعة، السابعة، سأكون هناك."},{s:1,t:"The hero? I can live with that. See you Friday.",ar:"البطل؟ يمكنني التعايش مع ذلك. أراك الجمعة."},{s:0,t:"Friday. And remember — art isn't finished until someone argues about it.",ar:"الجمعة. وتذكر — الفن لا يكتمل حتى يجادل فيه أحد."},{s:1,t:"Then your art is definitely finished. I argue about everything.",ar:"إذن فنك مكتمل بالتأكيد. أنا أجادل في كل شيء."}]}},{stage:5,topic:"philosophy",topicAr:"الفلسفة والأفكار",topicEn:"Philosophy & Ideas",topicDe:"Philosophie und Ideen",emoji:"🤔",title:"ما معنى الحياة؟",grammar:{id:"en-b2-participle-clauses",title:"Participle clauses",titleAr:"جمل اسم الفاعل",covers:1},conv:{id:"en-stage5-b2",speakers:["Philosopher (الفيلسوف)","Student (الطالب)"],turns:[{s:0,t:"So, you asked me what the meaning of life is. Sitting here, drinking coffee, I'll try to answer.",ar:"إذن، سألتني ما معنى الحياة. وأنا جالس هنا، أشرب القهوة، سأحاول الإجابة."},{s:1,t:"Ha! No pressure. Just the biggest question ever, over coffee.",ar:"ها! بلا ضغط. مجرد أكبر سؤال على الإطلاق، فوق فنجان قهوة."},{s:0,t:"Having thought about it for thirty years, I can tell you this: there is no single absolute answer.",ar:"بعد أن فكرت فيه ثلاثين عامًا، أستطيع أن أخبرك هذا: لا توجد إجابة واحدة مطلقة."},{s:1,t:"Thirty years and no answer? That's... not encouraging.",ar:"ثلاثون عامًا وبلا إجابة؟ هذا... ليس مشجعًا."},{s:0,t:"Not having an answer is the point. The question keeps you awake, keeps you searching.",ar:"عدم وجود إجابة هو المقصود. السؤال يبقيك مستيقظًا، يبقيك باحثًا."},{s:1,t:"Searching for what, though? I mean, I wake up, I study, I eat, I sleep. Where's the meaning in that?",ar:"البحث عن ماذا، مع ذلك؟ أعني، أستيقظ، أدرس، آكل، أنام. أين المعنى في ذلك؟"},{s:0,t:"Looking at it that way, life seems small. But zoom out — you're part of something vast.",ar:"بالنظر إلى الأمر بهذه الطريقة، تبدو الحياة صغيرة. لكن ابتعد قليلًا — أنت جزء من شيء واسع."},{s:1,t:"Vast and meaningless? That's worse. Being a tiny dot in a vast universe doesn't comfort me.",ar:"واسع وبلا معنى؟ هذا أسوأ. أن أكون نقطة صغيرة في كون واسع لا يريحني."},{s:0,t:"Feeling small isn't the same as being insignificant. A single note matters in a symphony.",ar:"الشعور بالصغر ليس ككونك غير مهم. نغمة واحدة مهمة في سيمفونية."},{s:1,t:"A symphony... You philosophers love metaphors.",ar:"سيمفونية... أنتم الفلاسفة تحبون الاستعارات."},{s:0,t:"Guilty. Speaking in metaphors, we reach ideas that plain words can't touch.",ar:"مذنب. بالتحدث بالاستعارات، نصل إلى أفكار لا تستطيع الكلمات العادية لمسها."},{s:1,t:"Okay, but here's my problem: if life has no built-in meaning, why bother doing anything?",ar:"حسنًا، لكن إليك مشكلتي: إذا لم يكن للحياة معنى جاهز، فلماذا أبذل جهدًا في أي شيء؟"},{s:0,t:"Because meaning isn't found, it's made. Built day by day, choice by choice.",ar:"لأن المعنى لا يُوجد، بل يُصنع. يُبنى يومًا بعد يوم، خيارًا بعد خيار."},{s:1,t:"Made by whom? Me? I'm barely twenty. I don't know who I am yet.",ar:"يصنعه من؟ أنا؟ عمري بالكاد عشرون. لا أعرف من أنا بعد."},{s:0,t:"Not knowing who you are is a fine place to start. Knowing nothing, you can question everything.",ar:"عدم معرفتك من أنت بداية جيدة. وبمعرفتك لا شيء، يمكنك أن تشكك في كل شيء."},{s:1,t:"Question everything... My parents hate that. They want me to follow the plan: degree, job, marriage.",ar:"أشكك في كل شيء... والداي يكرهان ذلك. يريدانني أن أتبع الخطة: شهادة، وظيفة، زواج."},{s:0,t:"Following their plan, you'd be safe — and miserable. Is safety worth a life you didn't choose?",ar:"باتباع خطتهم، ستكون آمنًا — وبائسًا. هل الأمان يستحق حياة لم تخترها؟"},{s:1,t:"Hmm. Put that way... no. But choosing my own path terrifies me.",ar:"همم. بهذه الطريقة... لا. لكن اختيار طريقي الخاص يرعبني."},{s:0,t:"Being terrified means you care. People who don't care never feel fear — they just drift.",ar:"أن تكون مرعوبًا يعني أنك تهتم. من لا يهتمون لا يشعرون بالخوف أبدًا — إنهم ينجرفون فقط."},{s:1,t:"Drifting... Yeah, I see that everywhere. People scrolling, consuming, not thinking.",ar:"الانجراف... نعم، أرى ذلك في كل مكان. الناس يتصفحون، يستهلكون، لا يفكرون."},{s:0,t:"Consumed by noise, they never hear themselves. Silence is where the real questions live.",ar:"مستهلكين بالضجيج، لا يسمعون أنفسهم أبدًا. الصمت هو حيث تعيش الأسئلة الحقيقية."},{s:1,t:"Silence... I tried meditating once. Lasted three minutes. My brain wouldn't shut up.",ar:"الصمت... جربت التأمل مرة. صمدت ثلاث دقائق. عقلي لم يتوقف."},{s:0,t:"Three minutes is a victory! Sitting still, you met your own mind. Most people run from that.",ar:"ثلاث دقائق انتصار! بجلوسك ساكنًا، قابلت عقلك. معظم الناس يهربون من ذلك."},{s:1,t:"Maybe. But what about happiness? Isn't that the goal — just be happy?",ar:"ربما. لكن ماذا عن السعادة؟ أليست هذه هي الهدف — أن تكون سعيدًا فقط؟"},{s:0,t:"Chasing happiness directly, you'll never catch it. It arrives sideways, while you're doing something meaningful.",ar:"بمطاردة السعادة مباشرة، لن تلحق بها أبدًا. إنها تأتي من الجانب، بينما تفعل شيئًا ذا معنى."},{s:1,t:"Sideways... Like when I helped my neighbor fix his roof last month? I felt great after.",ar:"من الجانب... مثلما ساعدت جاري في إصلاح سقفه الشهر الماضي؟ شعرت بشعور رائع بعدها."},{s:0,t:"Exactly! Helping others, you found meaning without even looking for it.",ar:"بالضبط! بمساعدة الآخرين، وجدت المعنى دون أن تبحث عنه حتى."},{s:1,t:"So meaning is... helping? Creating? Loving? All of it?",ar:"إذن المعنى هو... المساعدة؟ الخلق؟ الحب؟ كل ذلك؟"},{s:0,t:"All of it, and more. Lived fully, a life needs no justification.",ar:"كل ذلك، وأكثر. الحياة التي تُعاش بالكامل لا تحتاج إلى تبرير."},{s:1,t:"Lived fully... I like that. But what about suffering? Life hurts sometimes.",ar:"تُعاش بالكامل... يعجبني ذلك. لكن ماذا عن المعاناة؟ الحياة تؤلم أحيانًا."},{s:0,t:"Suffering, faced honestly, can teach you more than comfort ever will.",ar:"المعاناة، إذا وُوجهت بصدق، يمكن أن تعلمك أكثر مما يعلمك الراحة أبدًا."},{s:1,t:"Teach me what? That life is unfair?",ar:"تعلمني ماذا؟ أن الحياة غير عادلة؟"},{s:0,t:"That you're stronger than you thought. Broken once, you learn how to rebuild.",ar:"أنك أقوى مما ظننت. بعد أن تنكسر مرة، تتعلم كيف تعيد البناء."},{s:1,t:"Rebuild... Okay. I think I'm starting to get it. Meaning isn't a thing — it's a practice.",ar:"إعادة البناء... حسنًا. أعتقد أنني بدأت أفهم. المعنى ليس شيئًا — إنه ممارسة."},{s:0,t:"A practice, yes. Practiced daily, it becomes who you are.",ar:"ممارسة، نعم. وبممارسها يوميًا، تصبح من أنت."},{s:1,t:"Whoa. That actually... makes sense. Did I just have a philosophical moment?",ar:"واو. هذا في الواقع... منطقي. هل مررت للتو بلحظة فلسفية؟"},{s:0,t:"You did. And having had it, you can't unhave it. Welcome to philosophy.",ar:"نعم فعلت. وبعد أن مررت بها، لا يمكنك التراجع عنها. مرحبًا بك في الفلسفة."},{s:1,t:"Welcome? I haven't even paid tuition!",ar:"مرحبًا؟ لم أدفع الرسوم الدراسية حتى!"},{s:0,t:"The first lesson is free. The rest will cost you a lifetime of thinking.",ar:"الدرس الأول مجاني. الباقي سيكلفك عمرًا من التفكير."},{s:1,t:"A lifetime of thinking... I can live with that. Same time next week?",ar:"عمر من التفكير... يمكنني التعايش مع ذلك. نفس الوقت الأسبوع المقبل؟"},{s:0,t:"Next week. Bring a question — the harder, the better.",ar:"الأسبوع المقبل. أحضر سؤالًا — كلما كان أصعب، كان أفضل."},{s:1,t:"I'll bring three. Fair warning.",ar:"سأحضر ثلاثة. تحذير عادل."},{s:0,t:"One more thing — the concept of a good life. What does it actually require?",ar:"شيء آخر — مفهوم الحياة الجيدة. ماذا يتطلب فعلًا؟"},{s:1,t:"Require? Hmm. Health, friends, purpose... and a bit of luck, honestly.",ar:"يتطلب؟ همم. الصحة، الأصدقاء، الهدف... وقليل من الحظ، بصراحة."},{s:0,t:"Luck, yes. But also courage — the courage to choose, even when uncertainty surrounds you.",ar:"الحظ، نعم. لكن أيضًا الشجاعة — شجاعة الاختيار، حتى عندما يحيط بك عدم اليقين."},{s:1,t:"Uncertainty surrounds me daily. Exams, jobs, the future — it's all fog.",ar:"عدم اليقين يحيط بي يوميًا. الامتحانات، الوظائف، المستقبل — كلها ضباب."},{s:0,t:"Fog is a good metaphor. Walking through fog, you can only see the next few steps — and that's enough.",ar:"الضباب استعارة جيدة. بالمشي في الضباب، ترى الخطوات القليلة التالية فقط — وهذا يكفي."},{s:1,t:"The next few steps... Okay, I can do that. But what if I choose wrong?",ar:"الخطوات القليلة التالية... حسنًا، يمكنني فعل ذلك. لكن ماذا لو اخترت خطأ؟"},{s:0,t:"Wrong choices teach you too. A mistake, put through honest examination, is worth more than a lucky guess.",ar:"الخيارات الخاطئة تعلمك أيضًا. الخطأ، إذا فحصته بصدق، يستحق أكثر من تخمين محظوظ."},{s:1,t:"Honest examination... You make failure sound almost noble.",ar:"فحص صادق... تجعل الفشل يبدو نبيلًا تقريبًا."},{s:0,t:"Failure is noble when you learn from it. The tragic part is failing the same way twice.",ar:"الفشل نبيل عندما تتعلم منه. الجزء المأساوي هو الفشل بنفس الطريقة مرتين."},{s:1,t:"Failing the same way twice... Yeah, I've done that. More than twice, honestly.",ar:"الفشل بنفس الطريقة مرتين... نعم، فعلت ذلك. أكثر من مرتين، بصراحة."},{s:0,t:"Then you've got the raw material for a wise life. Wisdom isn't age — it's attention.",ar:"إذن لديك المادة الخام لحياة حكيمة. الحكمة ليست العمر — إنها الانتباه."},{s:1,t:"Attention... So just pay attention? That's the whole secret?",ar:"الانتباه... إذن فقط انتبه؟ هذا هو السر كله؟"},{s:0,t:"Pay attention, and be patient. Patience is the hardest virtue — and the most rewarding.",ar:"انتبه، وكن صبورًا. الصبر أصعب فضيلة — والأكثر مكافأة."},{s:1,t:"Patience... I'm terrible at it. But I'll try. Starting now—",ar:"الصبر... أنا سيئ فيه. لكنني سأحاول. ابتداءً من الآن—"},{s:0,t:"—Starting now is all we ever have. Good. See you next week.",ar:"—البدء الآن هو كل ما لدينا أبدًا. جيد. أراك الأسبوع المقبل."},{s:0,t:"Let me ask you something else — do you think free will is real, or are we just... programmed?",ar:"دعني أسألك شيئًا آخر — هل تعتقد أن الإرادة الحرة حقيقية، أم أننا مجرد... مبرمجين؟"},{s:1,t:"Programmed? Like robots? That's a dark thought for a Tuesday.",ar:"مبرمجون؟ مثل الروبوتات؟ هذه فكرة مظلمة ليوم ثلاثاء."},{s:0,t:"Dark, but fair. Our genes, our upbringing, our habits — how much choice is left?",ar:"مظلمة، لكنها عادلة. جيناتنا، تربيتنا، عاداتنا — كم يتبقى من الاختيار؟"},{s:1,t:"How much choice... I wanna believe I choose. Otherwise, why try at all?",ar:"كم يتبقى من الاختيار... أريد أن أؤمن بأنني أختار. وإلا، لماذا أحاول أصلًا؟"},{s:0,t:"Why try — that's the key question. Even if the choice is an illusion, the effort is real.",ar:"لماذا أحاول — هذا هو السؤال الأساسي. حتى لو كان الاختيار وهمًا، فالجهد حقيقي."},{s:1,t:"The effort is real... I like that. It gives me something to hold on to.",ar:"الجهد حقيقي... يعجبني ذلك. يمنحني شيئًا أتمسك به."},{s:0,t:"Hold on to it. And remember — questioning everything is the most human thing there is.",ar:"تمسك به. وتذكر — التشكيك في كل شيء هو أكثر شيء إنساني موجود."},{s:1,t:"The most human thing... Okay. Next week, I'm bringing the free will debate. Be ready.",ar:"أكثر شيء إنساني... حسنًا. الأسبوع المقبل، سأحضر نقاش الإرادة الحرة. كن مستعدًا."},{s:0,t:"Three? Ambitious. I like it.",ar:"ثلاثة؟ طموح. يعجبني ذلك."},{s:1,t:"Ambitious... or just confused. Either way, see you then.",ar:"طموح... أو مجرد مرتبك. على أي حال، أراك حينها."},{s:0,t:"Confused is good. It means you're thinking. See you then.",ar:"الارتباك جيد. يعني أنك تفكر. أراك حينها."}]}},{stage:6,topic:"science",topicAr:"العلم والاكتشاف",topicEn:"Science & Discovery",topicDe:"Wissenschaft und Entdeckung",emoji:"🔬",title:"العلم بين الشك واليقين",grammar:{id:"en-b2-reported-speech-tense-shifts",title:"Advanced reported speech",titleAr:"الكلام المنقول المتقدم",covers:1},conv:{id:"en-stage6-b2",speakers:["Scientist (العالم)","Journalist (الصحفي)"],turns:[{s:0,t:"So, you wanted to ask about the new gene study. Fire away.",ar:"إذن، أردت أن تسأل عن دراسة الجينات الجديدة. تفضل بالسؤال."},{s:1,t:"Right. First — the headlines said you'd found a cure for aging. Is that true?",ar:"صحيح. أولًا — قالت العناوين إنك وجدت علاجًا للشيخوخة. هل هذا صحيح؟"},{s:0,t:"No! The headlines said that, not us. Our actual words were that we'd slowed aging in mice.",ar:"لا! العناوين قالت ذلك، لا نحن. كلماتنا الفعلية كانت أننا أبطأنا الشيخوخة لدى الفئران."},{s:1,t:"Mice! So the papers exaggerated again. They claimed you'd added twenty years to human life.",ar:"الفئران! إذن الصحف بالغت مجددًا. زعمت أنك أضفت عشرين عامًا إلى حياة الإنسان."},{s:0,t:"They did claim that, and it's nonsense. Our lead researcher told me she was furious when she saw it.",ar:"نعم زعمت ذلك، وهو هراء. أخبرتني الباحثة الرئيسية أنها كانت غاضبة عندما رأته."},{s:1,t:"Furious, huh? What did she say exactly?",ar:"غاضبة، هاه؟ ماذا قالت بالضبط؟"},{s:0,t:"She said that the results had been twisted beyond recognition, and she asked the paper to correct it.",ar:"قالت إن النتائج قد حُرّفت بما لا يمكن التعرف عليه، وطلبت من الصحيفة تصحيحها."},{s:1,t:"Did they correct it?",ar:"هل صححوها؟"},{s:0,t:"They promised they would, but the correction was buried on page twelve.",ar:"وعدوا أنهم سيفعلون، لكن التصحيح دُفن في الصفحة الثانية عشرة."},{s:1,t:"Classic. Okay, so tell me in plain English: what did you actually discover?",ar:"كلاسيكي. حسنًا، أخبرني بلغة بسيطة: ماذا اكتشفت فعلًا؟"},{s:0,t:"We found a genetic variation that seems to protect cells from damage. That's it. No miracle, just a clue.",ar:"وجدنا تغيرًا جينيًا يبدو أنه يحمي الخلايا من التلف. هذا كل شيء. لا معجزة، مجرد دليل."},{s:1,t:"A clue... And how did you find it? Walk me through it.",ar:"دليل... وكيف وجدته؟ اشرح لي خطوة بخطوة."},{s:0,t:"We compared the genes of two groups — one that aged slowly, one that didn't. The difference was evident.",ar:"قارنا جينات مجموعتين — واحدة تشيخ ببطء، وأخرى لا. وكان الفرق واضحًا."},{s:1,t:"Evident to you, maybe. To me it sounds like a needle in a haystack.",ar:"واضح بالنسبة لك، ربما. بالنسبة لي يبدو كإبرة في كومة قش."},{s:0,t:"Ha! It was. We screened thousands of samples. My team said they'd never seen data this messy.",ar:"ها! كان كذلك. فحصنا آلاف العينات. قال فريقي إنهم لم يروا بيانات بهذه الفوضى من قبل."},{s:1,t:"Messy data... So how sure are you? Like, really sure?",ar:"بيانات فوضوية... إذن كم أنت متأكد؟ أعني، متأكد فعلًا؟"},{s:0,t:"We're reasonably confident. The results were confirmed by a second lab — independently, with identical methods.",ar:"نحن واثقون بشكل معقول. تم تأكيد النتائج من مختبر ثانٍ — بشكل مستقل، وبطرق متطابقة."},{s:1,t:"A second lab confirmed it? That's reassuring. What did they say?",ar:"مختبر ثانٍ أكدها؟ هذا مطمئن. ماذا قالوا؟"},{s:0,t:"They said the phenomenon was real, but they warned that human trials were years away.",ar:"قالوا إن الظاهرة حقيقية، لكنهم حذروا من أن التجارب البشرية ما زالت بعيدة بسنوات."},{s:1,t:"Years away. So no miracle pills next month?",ar:"بعيدة بسنوات. إذن لا حبوب معجزة الشهر المقبل؟"},{s:0,t:"No miracle pills. Anyone who tells you otherwise is selling something — probably a useless pill.",ar:"لا حبوب معجزة. أي شخص يخبرك بخلاف ذلك يبيع شيئًا — على الأرجح حبة عديمة الفائدة."},{s:1,t:"Good to know. What about the vaccine story last year? People said you'd hidden the side effects.",ar:"جيد أن أعرف. ماذا عن قصة اللقاح العام الماضي؟ قال الناس إنك أخفيت الآثار الجانبية."},{s:0,t:"We didn't hide anything. The report stated that mild side effects were expected, and they were published openly.",ar:"لم نخفِ شيئًا. ذكر التقرير أن الآثار الجانبية الخفيفة كانت متوقعة، ونُشرت علنًا."},{s:1,t:"Published openly... but in language nobody understands. My readers said it felt like a cover-up.",ar:"نُشرت علنًا... لكن بلغة لا يفهمها أحد. قال قرائي إن الأمر بدا كتغطية."},{s:0,t:"That's fair criticism. The institute admitted that our communication had been terrible.",ar:"هذا نقد عادل. اعترف المعهد بأن تواصلنا كان سيئًا."},{s:1,t:"Terrible is putting it mildly. So what changed since then?",ar:"سيئ تعبير مخفف. إذن ماذا تغير منذ ذلك الحين؟"},{s:0,t:"We hired science communicators. Now, before anything goes public, someone explains it in plain words.",ar:"وظفنا مختصين في التواصل العلمي. الآن، قبل نشر أي شيء، يشرحه شخص بكلمات بسيطة."},{s:1,t:"Plain words — I like that. So, in plain words: will this gene research help my grandmother?",ar:"كلمات بسيطة — يعجبني ذلك. إذن، بكلمات بسيطة: هل سيساعد هذا البحث الجيني جدتي؟"},{s:0,t:"Not tomorrow. But in ten years? Possibly. The researchers believe it could lead to treatments for several diseases.",ar:"ليس غدًا. لكن بعد عشر سنوات؟ ربما. يعتقد الباحثون أنه قد يؤدي إلى علاجات لعدة أمراض."},{s:1,t:"Ten years... My grandmother always says science moves slowly, then all at once.",ar:"عشر سنوات... جدتي تقول دائمًا إن العلم يتحرك ببطء، ثم دفعة واحدة."},{s:0,t:"Your grandmother is wise. That's exactly how evolution works too — slow, then sudden.",ar:"جدتك حكيمة. هكذا يعمل التطور أيضًا — ببطء، ثم فجأة."},{s:1,t:"Evolution... Don't get me started. Half my readers still argue about that.",ar:"التطور... لا تجعلني أبدأ. نصف قرائي ما زالوا يجادلون حول ذلك."},{s:0,t:"Let them argue. The evidence speaks for itself — fossils, genes, the whole picture.",ar:"دعهم يجادلون. الأدلة تتحدث عن نفسها — الحفريات، الجينات، الصورة الكاملة."},{s:1,t:"The whole picture... Okay, last question: what's the one thing you wish people understood about science?",ar:"الصورة الكاملة... حسنًا، سؤال أخير: ما الشيء الواحد الذي تتمنى أن يفهمه الناس عن العلم؟"},{s:0,t:"That uncertainty isn't weakness. When a scientist says 'we don't know yet,' that's honesty, not failure.",ar:"أن عدم اليقين ليس ضعفًا. عندما يقول عالم 'لا نعرف بعد'، فهذا صدقٌ، لا فشل."},{s:1,t:"Honesty, not failure. I like that. Can I quote you on it?",ar:"صدق، لا فشل. يعجبني ذلك. هل يمكنني أن أقتبس منك ذلك؟"},{s:0,t:"You can quote me on it — just quote me correctly this time!",ar:"يمكنك أن تقتبس مني ذلك — فقط اقتبسني بشكل صحيح هذه المرة!"},{s:1,t:"Correctly, I promise. Word for word. No twisted headlines.",ar:"بشكل صحيح، أعدك. كلمة بكلمة. بلا عناوين محرّفة."},{s:0,t:"Actually, one more thing — the radiation study. People keep asking me about it.",ar:"في الواقع، شيء آخر — دراسة الإشعاع. الناس يسألونني عنها باستمرار."},{s:1,t:"Radiation? From phones? My aunt swears her phone gives her headaches.",ar:"الإشعاع؟ من الهواتف؟ خالتي تقسم أن هاتفها يسبب لها الصداع."},{s:0,t:"She swears it, but the data says otherwise. We measured exposure for years — nothing of significance showed up.",ar:"هي تقسم بذلك، لكن البيانات تقول غير ذلك. قسنا التعرض لسنوات — لم يظهر شيء ذو أهمية."},{s:1,t:"Nothing of significance... So she's imagining it?",ar:"لا شيء ذو أهمية... إذن هي تتخيل ذلك؟"},{s:0,t:"Not imagining — the headaches are real. But the cause is probably stress, not the phone.",ar:"ليست تتخيل — الصداع حقيقي. لكن السبب على الأرجح التوتر، لا الهاتف."},{s:1,t:"Stress... Yeah, that tracks. We're all stressed, all the time.",ar:"التوتر... نعم، هذا منطقي. نحن جميعًا متوترون، طوال الوقت."},{s:0,t:"All the time. And stress affects the immune system — that's proven, not speculation.",ar:"طوال الوقت. والتوتر يؤثر على جهاز المناعة — هذا مثبت، ليس تكهنًا."},{s:1,t:"Proven, not speculation. I like that line. What about vitamins — do they actually work?",ar:"مثبت، ليس تكهنًا. يعجبني هذا السطر. ماذا عن الفيتامينات — هل تعمل فعلًا؟"},{s:0,t:"Vitamins work if you're deficient. Otherwise, you're just making expensive urine — as my professor used to say.",ar:"الفيتامينات تعمل إذا كنت تعاني نقصًا. وإلا، فأنت تصنع بولًا غاليًا فحسب — كما اعتاد أستاذي أن يقول."},{s:1,t:"Expensive urine! Ha! Okay, last one — vaccines. People still argue about them.",ar:"بول غالٍ! ها! حسنًا، آخر واحد — اللقاحات. الناس ما زالوا يجادلون حولها."},{s:0,t:"Vaccination is one of the greatest triumphs in history. The evidence is overwhelming — millions of lives rescued.",ar:"التطعيم من أعظم انتصارات التاريخ. الأدلة ساحقة — ملايين الأرواح أُنقذت."},{s:1,t:"Millions of lives... When you put it that way, the argument feels silly.",ar:"ملايين الأرواح... عندما تضعها بهذه الطريقة، يبدو الجدال سخيفًا."},{s:0,t:"Silly, but human. Fear spreads faster than facts — that's why we keep explaining.",ar:"سخيف، لكنه بشري. الخوف ينتشر أسرع من الحقائق — لهذا نواصل الشرح."},{s:1,t:"Keep explaining... I will too. Thanks — this was genuinely useful.",ar:"واصل الشرح... سأفعل أنا أيضًا. شكرًا — كان هذا مفيدًا فعلًا."},{s:0,t:"You know what worries me? People trust a random video more than a peer-reviewed study.",ar:"تعلم ما يقلقني؟ الناس يثقون بفيديو عشوائي أكثر من دراسة محكمة."},{s:1,t:"More than a study... Yeah, because the video is fun and the study is boring.",ar:"أكثر من دراسة... نعم، لأن الفيديو ممتع والدراسة مملة."},{s:0,t:"Fun versus true — that's the battle of our time. And fun is winning.",ar:"الممتع مقابل الحقيقي — هذه معركة عصرنا. والممتع يفوز."},{s:1,t:"Fun is winning... depressing. So how do scientists fight back?",ar:"الممتع يفوز... محبط. إذن كيف يرد العلماء؟"},{s:0,t:"By telling better stories. The facts are solid — we just need to present them like humans, not robots.",ar:"بسرد قصص أفضل. الحقائق قوية — نحتاج فقط إلى تقديمها كبشر، لا كروبوتات."},{s:1,t:"Like humans, not robots... You know, you're pretty good at that yourself.",ar:"كبشر، لا كروبوتات... تعلم، أنت جيد في ذلك بنفسك."},{s:0,t:"Thanks. That's the highest praise a scientist can get — being called human.",ar:"شكرًا. هذا أعلى مديح يمكن أن يحصل عليه عالم — أن يُدعى إنسانًا."},{s:1,t:"Human... Alright, I'll quote you — accurately, I promise.",ar:"إنسان... حسنًا، سأقتبس منك — بدقة، أعدك."},{s:0,t:"Word for word... Now I'm scared. But okay, deal.",ar:"كلمة بكلمة... الآن أنا خائف. لكن حسنًا، اتفقنا."},{s:1,t:"Deal. And hey — thanks for explaining it like a human, not a textbook.",ar:"اتفقنا. ومهلًا — شكرًا لشرحك الأمر كإنسان، لا ككتاب مدرسي."},{s:0,t:"Anytime. Science belongs to everyone — not just the lab.",ar:"في أي وقت. العلم ملك للجميع — ليس للمختبر فقط."}]}},{stage:7,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"المجتمع يتغير بسرعة",grammar:{id:"en-b2-phrasal-verbs-patterns",title:"Phrasal verb patterns",titleAr:"أنماط الأفعال المركبة",covers:1},conv:{id:"en-stage7-b2",speakers:["Sociologist (عالم الاجتماع)","Neighbor (الجار)"],turns:[{s:0,t:"You know what struck me today? I walked down our street and didn't recognize half the faces.",ar:"تعرف ما الذي لفت انتباهي اليوم؟ مشيت في شارعنا ولم أتعرف على نصف الوجوه."},{s:1,t:"Yeah. New people all the time. Nobody stays long anymore — everyone's temporary.",ar:"نعم. أشخاص جدد طوال الوقت. لا أحد يبقى طويلًا بعد الآن — الجميع مؤقتون."},{s:0,t:"Nobody stays, nobody talks. When did we stop knowing our neighbors?",ar:"لا أحد يبقى، لا أحد يتحدث. متى توقفنا عن معرفة جيراننا؟"},{s:1,t:"When everyone got busy, I guess. Work, phones, life. You know how it is.",ar:"عندما انشغل الجميع، أظن. العمل، الهواتف، الحياة. تعرف كيف الأمر."},{s:0,t:"I do. But is busy an excuse, or just a habit we've accepted?",ar:"أعرف. لكن هل الانشغال عذر، أم مجرد عادة قبلناها؟"},{s:1,t:"A habit, probably. A bad one. I barely know the family next door.",ar:"عادة، على الأرجح. عادة سيئة. بالكاد أعرف العائلة المجاورة."},{s:0,t:"Barely know them — and they've lived there two years! That's the problem in a nutshell.",ar:"بالكاد تعرفهم — وقد عاشوا هناك سنتين! هذه هي المشكلة باختصار."},{s:1,t:"Two years... Wow. I should invite them over. Coffee, maybe?",ar:"سنتان... واو. يجب أن أدعوهم. قهوة، ربما؟"},{s:0,t:"Coffee. Simple, human. That's how communities used to start.",ar:"قهوة. بسيطة، إنسانية. هكذا كانت المجتمعات تبدأ."},{s:1,t:"Used to. Now people just wave and rush inside. Sad, really.",ar:"كانت تبدأ. الآن يلوح الناس ويسرعون إلى الداخل. محزن، حقًا."},{s:0,t:"Sad, yes. But not inevitable. One invitation can change a whole street.",ar:"محزن، نعم. لكنه ليس حتميًا. دعوة واحدة يمكن أن تغير شارعًا كاملًا."},{s:1,t:"One invitation? You really think so?",ar:"دعوة واحدة؟ هل تعتقد ذلك فعلًا؟"},{s:0,t:"I do. I study this for a living — small gestures, big effects.",ar:"أعتقد ذلك. أدرس هذا لكسب عيشي — إيماءات صغيرة، آثار كبيرة."},{s:1,t:"Small gestures... Like when old Mr. Harris helped me fix my fence last spring?",ar:"إيماءات صغيرة... مثلما ساعدني السيد هاريس العجوز في إصلاح سياجي الربيع الماضي؟"},{s:0,t:"Exactly like that. And did you help him back?",ar:"تمامًا مثل ذلك. وهل ساعدته بالمقابل؟"},{s:1,t:"I did. Brought him soup when he was sick. His wife loved it.",ar:"فعلت. أحضرت له حساءً عندما كان مريضًا. أحبته زوجته."},{s:0,t:"See? That's community. Not a program, not an app — just people showing up.",ar:"أرأيت؟ هذا هو المجتمع. ليس برنامجًا، ليس تطبيقًا — مجرد أشخاص يحضرون."},{s:1,t:"Showing up... I like that. But what about the bigger stuff — racism, inequality?",ar:"الحضور... يعجبني ذلك. لكن ماذا عن الأمور الأكبر — العنصرية، عدم المساواة؟"},{s:0,t:"The bigger stuff starts small too. Prejudice grows where people never meet.",ar:"الأمور الأكبر تبدأ صغيرة أيضًا. التحيز ينمو حيث لا يلتقي الناس أبدًا."},{s:1,t:"Never meet... Yeah, fear of strangers. I get it. But how do you fix that?",ar:"لا يلتقون أبدًا... نعم، الخوف من الغرباء. أفهم. لكن كيف تصلح ذلك؟"},{s:0,t:"You don't fix it with lectures. You fix it with shared tables, shared work, shared streets.",ar:"لا تصلحه بالمحاضرات. تصلحه بطاولات مشتركة، وعمل مشترك، وشوارع مشتركة."},{s:1,t:"Shared streets... You sound like an optimist. I'm more of a realist.",ar:"شوارع مشتركة... تبدو متفائلًا. أنا واقعي أكثر."},{s:0,t:"A realist? Or just tired? There's a difference, you know.",ar:"واقعي؟ أم متعب فقط؟ هناك فرق، كما تعلم."},{s:1,t:"Tired, maybe. The news doesn't help. Every day, another crisis.",ar:"متعب، ربما. الأخبار لا تساعد. كل يوم، أزمة أخرى."},{s:0,t:"Another crisis, another reason to hide. But hiding never helped anyone.",ar:"أزمة أخرى، سبب آخر للاختباء. لكن الاختباء لم يساعد أحدًا أبدًا."},{s:1,t:"True. Hiding never helped. So — coffee with the new neighbors. This weekend?",ar:"صحيح. الاختباء لم يساعد أبدًا. إذن — قهوة مع الجيران الجدد. هذا الأسبوع؟"},{s:0,t:"This weekend. I'll bring the cake — you bring the introductions.",ar:"هذا الأسبوع. سأحضر الكعكة — وأنت تحضر التعارف."},{s:1,t:"Deal. And if they're weird?",ar:"اتفقنا. وإذا كانوا غريبين؟"},{s:0,t:"If they're weird, we'll find out together. That's half the fun.",ar:"إذا كانوا غريبين، سنكتشف ذلك معًا. هذا نصف المتعة."},{s:1,t:"Together... Alright. I'm in. But you're making the coffee — mine's terrible.",ar:"معًا... حسنًا. أنا معك. لكنك تصنع القهوة — قهوتي سيئة."},{s:0,t:"Mine's terrible too. We'll buy it from the café. No shame in that.",ar:"قهوتي سيئة أيضًا. سنشتريها من المقهى. لا عيب في ذلك."},{s:1,t:"No shame at all. Café coffee, Saturday morning, new friends. Sounds good.",ar:"لا عيب إطلاقًا. قهوة مقهى، صباح السبت، أصدقاء جدد. يبدو جيدًا."},{s:0,t:"Sounds good. And who knows — maybe they'll invite us next time.",ar:"يبدو جيدًا. ومن يدري — ربما يدعوننا هم المرة المقبلة."},{s:1,t:"Maybe. That's how it works, right? One door opens another.",ar:"ربما. هكذا يعمل الأمر، أليس كذلك؟ باب يفتح آخر."},{s:0,t:"Exactly. One door opens another. That's society, really — just doors.",ar:"بالضبط. باب يفتح آخر. هذا هو المجتمع فعلًا — مجرد أبواب."},{s:1,t:"Just doors... I never thought of it that way. Nice image.",ar:"مجرد أبواب... لم أفكر في الأمر بهذه الطريقة أبدًا. صورة جميلة."},{s:0,t:"Thanks. Now go knock on one.",ar:"شكرًا. الآن اذهب واطرق واحدًا."},{s:1,t:"Knocking. Saturday. Don't forget the cake.",ar:"سأطرق. السبت. لا تنسَ الكعكة."},{s:0,t:"You know, there's another side to this street — the homeless shelter two blocks down.",ar:"تعلم، هناك جانب آخر لهذا الشارع — مأوى المشردين على بعد مبنيين."},{s:1,t:"The shelter... Yeah, I walk past it every day. I never stop, though.",ar:"المأوى... نعم، أمر به كل يوم. لكنني لا أتوقف أبدًا."},{s:0,t:"Never stop — most people don't. But those folks are our neighbors too, technically.",ar:"لا تتوقف أبدًا — معظم الناس لا يفعلون. لكن هؤلاء الناس جيراننا أيضًا، تقنيًا."},{s:1,t:"Technically... I guess. But what can one person do? The problem is huge.",ar:"تقنيًا... أظن. لكن ماذا يستطيع شخص واحد أن يفعل؟ المشكلة ضخمة."},{s:0,t:"One person can do an hour of voluntary work a week. That's it — an hour. It matters more than you think.",ar:"شخص واحد يمكنه القيام بساعة من العمل التطوعي في الأسبوع. هذا كل شيء — ساعة. الأمر مهم أكثر مما تظن."},{s:1,t:"An hour of voluntary work... I could do that. Saturday mornings, maybe?",ar:"ساعة من العمل التطوعي... يمكنني فعل ذلك. صباح السبت، ربما؟"},{s:0,t:"Saturday mornings, perfect. And you'd meet people you'd never meet otherwise.",ar:"صباح السبت، ممتاز. وستقابل أشخاصًا لن تقابلهم أبدًا غير ذلك."},{s:1,t:"Meet people... You know, my dad always said charity starts at home. But maybe it starts on your street.",ar:"أقابل الناس... تعلم، والدي كان يقول دائمًا إن الإحسان يبدأ من البيت. لكن ربما يبدأ من شارعك."},{s:0,t:"Starts on your street — I like that. And it's not charity, really. It's community.",ar:"يبدأ من شارعك — يعجبني ذلك. وليس إحسانًا، حقًا. إنه مجتمع."},{s:1,t:"Community... And you know what else shrinks when people meet? Racism. Hard to hate someone you've shared coffee with.",ar:"المجتمع... وتعلم ماذا يتقلص أيضًا عندما يلتقي الناس؟ العنصرية. من الصعب أن تكره شخصًا شاركت معه القهوة."},{s:0,t:"Hard to hate, exactly. So — coffee with the new neighbors, and the shelter after. Deal?",ar:"من الصعب الكراهية، بالضبط. إذن — قهوة مع الجيران الجدد، والمأوى بعدها. اتفقنا؟"},{s:1,t:"Okay, I'm gonna sign up. Where do I go?",ar:"حسنًا، سأسجل. أين أذهب؟"},{s:0,t:"Sign up at the shelter desk — ask for the coordinator. Tell them I sent you.",ar:"سجل في مكتب المأوى — اسأل عن المنسق. أخبرهم أنني أرسلتك."},{s:1,t:"Will do. And hey — thanks for not lecturing me about it. You just... showed me.",ar:"سأفعل. ومهلًا — شكرًا لعدم إلقاء محاضرة عليّ حول ذلك. أنت فقط... أريتني."},{s:0,t:"Showing beats lecturing, every time. See you Saturday — coffee first, shelter after.",ar:"الإظهار يتفوق على الوعظ، في كل مرة. أراك السبت — القهوة أولًا، المأوى بعدها."},{s:1,t:"Coffee first. Deal. And I'm bringing cake too — the shelter folks deserve something sweet.",ar:"القهوة أولًا. اتفقنا. وسأحضر الكعكة أيضًا — أهل المأوى يستحقون شيئًا حلوًا."},{s:0,t:"There's one more thing — the new families on our street. Some folks are... cold toward them.",ar:"هناك شيء آخر — العائلات الجديدة في شارعنا. بعض الناس... باردون تجاههم."},{s:1,t:"Cold toward them? Because they're from somewhere else? That's just prejudice.",ar:"باردون تجاههم؟ لأنهم من مكان آخر؟ هذا مجرد تحيز."},{s:0,t:"Prejudice, yeah. And it grows when people don't talk. Silence feeds it.",ar:"تحيز، نعم. وينمو عندما لا يتحدث الناس. الصمت يغذيه."},{s:1,t:"Silence feeds it... So the coffee invite matters even more than I thought.",ar:"الصمت يغذيه... إذن دعوة القهوة مهمة أكثر مما ظننت."},{s:0,t:"Way more. A shared table does what a hundred speeches can't.",ar:"أكثر بكثير. طاولة مشتركة تفعل ما لا تستطيع مئة خطبة فعله."},{s:1,t:"A hundred speeches... Okay, I'm sold. Saturday, coffee, cake, new friends.",ar:"مئة خطبة... حسنًا، أنا مقتنع. السبت، قهوة، كعكة، أصدقاء جدد."},{s:0,t:"Sold! And if anyone's rude, we'll handle it — together, calmly.",ar:"مقتنع! وإذا كان أحد وقحًا، سنتعامل معه — معًا، بهدوء."},{s:1,t:"Together, calmly. I like that. That's how neighbors should be.",ar:"معًا، بهدوء. يعجبني ذلك. هكذا يجب أن يكون الجيران."},{s:0,t:"Won't forget. Chocolate, your favorite.",ar:"لن أنسى. شوكولاتة، المفضلة لديك."},{s:1,t:"My favorite. You remembered!",ar:"المفضلة لدي. تذكرت!"},{s:0,t:"Of course I remembered. That's what neighbors do.",ar:"بالطبع تذكرت. هذا ما يفعله الجيران."}]}},{stage:8,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"العمل في عصر الذكاء الاصطناعي",grammar:{id:"en-b2-inversion-intro",title:"Inversion",titleAr:"القلب (التقديم والتأخير)",covers:1},conv:{id:"en-stage8-b2",speakers:["Employer (صاحب العمل)","Job Seeker (الباحث عن عمل)"],turns:[{s:0,t:"Thanks for coming in. Let's talk about the future of work — and your place in it.",ar:"شكرًا لحضورك. لنتحدث عن مستقبل العمل — ومكانك فيه."},{s:1,t:"Thanks for having me. Honestly, I'm a bit nervous — AI is changing everything.",ar:"شكرًا لاستضافتي. بصراحة، أنا متوتر قليلًا — الذكاء الاصطناعي يغير كل شيء."},{s:0,t:"Nervous is normal. Never have I seen a shift this fast — not in twenty years of hiring.",ar:"التوتر طبيعي. لم أشهد أبدًا تحولًا بهذه السرعة — ليس في عشرين عامًا من التوظيف."},{s:1,t:"Twenty years... So, be honest: will AI take my job before I even start?",ar:"عشرون عامًا... إذن، كن صريحًا: هل سيأخذ الذكاء الاصطناعي وظيفتي قبل أن أبدأ حتى؟"},{s:0,t:"Take your job? No. Change it? Absolutely — and the change is rapid. Only those who adapt will thrive.",ar:"يأخذ وظيفتك؟ لا. يغيرها؟ بالتأكيد — والتغيير سريع. فقط من يتكيف سيزدهر."},{s:1,t:"Adapt... Everyone says adapt. But how? I studied marketing, not programming.",ar:"التكيف... الجميع يقول تكيف. لكن كيف؟ درست التسويق، لا البرمجة."},{s:0,t:"Marketing is exactly what we need. Rarely do we find someone who understands people and data both.",ar:"التسويق هو بالضبط ما نحتاجه. نادرًا ما نجد شخصًا يفهم الناس والبيانات معًا."},{s:1,t:"People and data... I can do people. Data? I'm still learning.",ar:"الناس والبيانات... أستطيع التعامل مع الناس. البيانات؟ ما زلت أتعلم."},{s:0,t:"Still learning is the best answer I've heard all week. Most candidates pretend they know everything.",ar:"ما زلت أتعلم هي أفضل إجابة سمعتها طوال الأسبوع. معظم المرشحين يتظاهرون بأنهم يعرفون كل شيء."},{s:1,t:"Pretend? No way. I'd rather say what I don't know. So — what does this role actually involve?",ar:"أتظاهر؟ مستحيل. أفضل أن أقول ما لا أعرفه. إذن — ما الذي يتضمنه هذا الدور فعلًا؟"},{s:0,t:"Good question. Not only will you run campaigns, but you'll also train our AI tools.",ar:"سؤال جيد. لن تدير الحملات فقط، بل ستدرب أيضًا أدوات الذكاء الاصطناعي لدينا."},{s:1,t:"Train the AI? Little did I know I'd be teaching a robot on my first job!",ar:"أدرب الذكاء الاصطناعي؟ لم أكن أعلم أنني سأعلّم روبوتًا في وظيفتي الأولى!"},{s:0,t:"Ha! Teaching a robot — that's the job now. The machine learns from your judgment.",ar:"ها! تعليم روبوت — هذه هي الوظيفة الآن. الآلة تتعلم من حكمك."},{s:1,t:"My judgment... Okay, that's kind of exciting. But what about job security? Layoffs are everywhere.",ar:"حكمي... حسنًا، هذا مثير نوعًا ما. لكن ماذا عن الأمان الوظيفي؟ التسريحات في كل مكان."},{s:0,t:"Layoffs happen, I won't lie. But seldom have we let go of people who keep growing.",ar:"التسريحات تحدث، لن أكذب. لكن نادرًا ما نتخلى عن أشخاص يواصلون النمو."},{s:1,t:"Keep growing... So learning never stops? Even after you get the job?",ar:"مواصلة النمو... إذن التعلم لا يتوقف أبدًا؟ حتى بعد الحصول على الوظيفة؟"},{s:0,t:"Especially after. We run workshops every month — new tools, new skills.",ar:"خاصة بعدها. ندير ورش عمل كل شهر — أدوات جديدة، مهارات جديدة."},{s:1,t:"Workshops every month? That sounds great, honestly. My last boss never trained anyone.",ar:"ورش عمل كل شهر؟ هذا يبدو رائعًا، بصراحة. مديري السابق لم يدرّب أحدًا أبدًا."},{s:0,t:"Never trained anyone — and then wondered why people quit. We learned that lesson.",ar:"لم يدرّب أحدًا أبدًا — ثم تساءل لماذا يستقيل الناس. تعلمنا ذلك الدرس."},{s:1,t:"People quit when they feel stuck. I felt stuck for two years.",ar:"الناس يستقيلون عندما يشعرون بالجمود. شعرت بالجمود لمدة سنتين."},{s:0,t:"Stuck is the worst feeling at work. So tell me — what would make you stay somewhere for years?",ar:"الجمود هو أسوأ شعور في العمل. إذن أخبرني — ما الذي يجعلك تبقى في مكان لسنوات؟"},{s:1,t:"Hmm. Respect, growth, and fair pay. Not necessarily in that order.",ar:"همم. الاحترام، النمو، وأجر عادل. ليس بالضرورة بهذا الترتيب."},{s:0,t:"Fair pay — let's talk numbers. What wage are you expecting?",ar:"أجر عادل — لنتحدث عن الأرقام. ما الأجر الذي تتوقعه؟"},{s:1,t:"Expecting... I'd rather hear your range first. I don't want to undersell myself.",ar:"أتوقع... أفضل أن أسمع نطاقك أولًا. لا أريد أن أبخس نفسي حقها."},{s:0,t:"Smart. Our range is competitive, plus benefits. And promotion comes fast if you deliver.",ar:"ذكي. نطاقنا تنافسي، بالإضافة إلى المزايا. والترقية تأتي بسرعة إذا أنجزت."},{s:1,t:"Promotion comes fast... That I like. But fast for whom? Only the loud ones?",ar:"الترقية تأتي بسرعة... هذا يعجبني. لكن بسرعة لمن؟ للصاخبين فقط؟"},{s:0,t:"Not the loud ones — the reliable ones. Quietly excellent beats loudly average, every time.",ar:"ليس للصاخبين — للموثوقين. التميز الهادئ يتفوق على المتوسط الصاخب، في كل مرة."},{s:1,t:"Quietly excellent. I can do that. I may not shout, but I deliver.",ar:"متميز بهدوء. أستطيع فعل ذلك. قد لا أصرخ، لكنني أنجز."},{s:0,t:"Delivering matters more than shouting. So — one last thing. Why us, and not our competitors?",ar:"الإنجاز أهم من الصراخ. إذن — شيء أخير. لماذا نحن، وليس منافسينا؟"},{s:1,t:"Why you? Because your team actually answered my emails. Small thing, huge signal.",ar:"لماذا أنتم؟ لأن فريقكم رد فعلًا على رسائلي. شيء صغير، إشارة ضخمة."},{s:0,t:"We answer emails... Now that's a low bar, but I'll take the compliment!",ar:"نرد على الرسائل... هذا معيار منخفض، لكنني سأقبل المجاملة!"},{s:1,t:"Ha! A low bar that most companies still miss. Anyway — when will I hear back?",ar:"ها! معيار منخفض ما زالت معظم الشركات تفشل فيه. على أي حال — متى سأسمع الرد؟"},{s:0,t:"By Friday. And no ghosting, I promise — we've all been on the other side.",ar:"بحلول الجمعة. وبلا اختفاء، أعدك — كنا جميعًا في الجانب الآخر."},{s:1,t:"Been on the other side... That means a lot. Thanks for your time.",ar:"كنت في الجانب الآخر... هذا يعني الكثير. شكرًا على وقتك."},{s:0,t:"Thank you. And remember — whatever happens, keep learning. The market rewards the curious.",ar:"شكرًا لك. وتذكر — مهما حدث، واصل التعلم. السوق يكافئ الفضوليين."},{s:1,t:"Keep learning. Got it. And hey — if I get the job, lunch is on me.",ar:"واصل التعلم. فهمت. ومهلًا — إذا حصلت على الوظيفة، الغداء على حسابي."},{s:0,t:"Lunch is on you? Now that's an incentive I can get behind. Good luck!",ar:"الغداء على حسابك؟ الآن هذا حافز يمكنني دعمه. حظًا سعيدًا!"},{s:0,t:"Before you go — a quick tip. Your resume is solid, but tailor it for each role.",ar:"قبل أن تذهب — نصيحة سريعة. سيرتك الذاتية قوية، لكن خصصها لكل دور."},{s:1,t:"Tailor it? I sent the same one everywhere. Is that bad?",ar:"أخصصها؟ أرسلت نفسها إلى كل مكان. هل هذا سيئ؟"},{s:0,t:"Not bad — just generic. We recruit fast — six seconds per resume. Make those seconds count.",ar:"ليس سيئًا — فقط عام. نوظف بسرعة — ست ثوانٍ لكل سيرة ذاتية. اجعل تلك الثواني مهمة."},{s:1,t:"Six seconds! Brutal. So what catches your eye in six seconds?",ar:"ست ثوانٍ! قاسٍ. إذن ما الذي يلفت انتباهك في ست ثوانٍ؟"},{s:0,t:"Results, not duties. Don't tell me what you did — tell me what changed because of you.",ar:"النتائج، لا الواجبات. لا تخبرني بما فعلت — أخبرني بما تغير بسببك."},{s:1,t:"What changed because of me... I boosted our campus campaign by forty percent. Does that count?",ar:"ما تغير بسببي... عززت حملة جامعتنا بنسبة أربعين بالمئة. هل هذا يُحسب؟"},{s:0,t:"Forty percent? That counts. Put that at the top — bold, impossible to miss.",ar:"أربعون بالمئة؟ هذا يُحسب. ضع ذلك في الأعلى — بخط عريض، يستحيل تفويته."},{s:1,t:"At the top, bold. Got it. Anything else?",ar:"في الأعلى، بخط عريض. فهمت. أي شيء آخر؟"},{s:0,t:"One more: show curiosity. Ask us questions — about the team, the challenges, the future.",ar:"واحد آخر: أظهر الفضول. اسألنا أسئلة — عن الفريق، التحديات، المستقبل."},{s:1,t:"Ask questions... I was too nervous to ask anything today. Next time, I will.",ar:"أطرح أسئلة... كنت متوترًا جدًا لأسأل أي شيء اليوم. في المرة المقبلة، سأفعل."},{s:0,t:"Next time... or this time? You've still got me here. Ask me one now.",ar:"المرة المقبلة... أو هذه المرة؟ ما زلت هنا. اسألني واحدًا الآن."},{s:1,t:"One question, right now? Okay — what's the hardest part of working here?",ar:"سؤال واحد، الآن؟ حسنًا — ما أصعب جزء في العمل هنا؟"},{s:0,t:"The hardest part? The pace. We move fast, and the deadlines are real.",ar:"أصعب جزء؟ الإيقاع. نتحرك بسرعة، والمواعيد النهائية حقيقية."},{s:1,t:"Deadlines are real... I can handle that. I worked two jobs through college.",ar:"المواعيد النهائية حقيقية... يمكنني التعامل مع ذلك. عملت في وظيفتين خلال الجامعة."},{s:0,t:"Two jobs through college? Now that's the kind of discipline we need. Respect.",ar:"وظيفتان خلال الجامعة؟ الآن هذا هو نوع الانضباط الذي نحتاجه. احترام."},{s:1,t:"I wanna work somewhere that actually values people. Thanks — that means a lot, honestly.",ar:"أريد العمل في مكان يقدر الناس فعلًا. شكرًا — هذا يعني الكثير، بصراحة."},{s:0,t:"One more thing — the workforce here is diverse, and that's a strength, not a problem.",ar:"شيء آخر — القوى العاملة هنا متنوعة، وهذه قوة، ليست مشكلة."},{s:1,t:"Diverse... Yeah, I've worked with people from everywhere. You learn fast.",ar:"متنوعة... نعم، عملت مع أشخاص من كل مكان. تتعلم بسرعة."},{s:0,t:"You learn fast, exactly. Different backgrounds, different ideas — that's where innovation comes from.",ar:"تتعلم بسرعة، بالضبط. خلفيات مختلفة، أفكار مختلفة — من هنا يأتي الابتكار."},{s:1,t:"Innovation comes from diversity... I never thought of it that way. Makes sense, though.",ar:"الابتكار يأتي من التنوع... لم أفكر في الأمر بهذه الطريقة أبدًا. منطقي، مع ذلك."},{s:0,t:"Makes sense. And honestly, the best teams I've seen are the mixed ones — young and old, local and foreign.",ar:"منطقي. وبصراحة، أفضل الفرق التي رأيتها هي المختلطة — صغار وكبار، محليون وأجانب."},{s:1,t:"Mixed teams... Okay. So — do I get the job or what? I'm dying here.",ar:"فرق مختلطة... حسنًا. إذن — هل حصلت على الوظيفة أم ماذا؟ أنا أموت هنا."},{s:0,t:"Ha! Patience — you'll hear by Friday. And whatever happens, you interviewed well.",ar:"ها! صبرًا — ستسمع بحلول الجمعة. ومهما حدث، أديت المقابلة بشكل جيد."},{s:1,t:"Interviewed well... Thanks. That means a lot. Friday, then.",ar:"أديت المقابلة جيدًا... شكرًا. هذا يعني الكثير. الجمعة إذن."},{s:1,t:"Good luck needed. Thanks again — see you Friday, hopefully!",ar:"أحتاج إلى الحظ السعيد. شكرًا مجددًا — أراك الجمعة، آمل ذلك!"},{s:0,t:"Hopefully Friday. Walk out tall — you've got this.",ar:"آمل الجمعة. اخرج مرفوع الرأس — أنت قادر على ذلك."},{s:1,t:"I've got this. Alright — here goes nothing.",ar:"أنا قادر على ذلك. حسنًا — ها نحن نبدأ."}]}},{stage:9,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"رحلة عبر ثلاث قارات",grammar:{id:"en-b2-third-conditional",title:"Third conditional",titleAr:"الشرط الثالث",covers:1},conv:{id:"en-stage9-b2",speakers:["Traveler (المسافر)","Travel Agent (وكيل السفر)"],turns:[{s:0,t:"I've been dreaming about going abroad for ages, and now I've finally got the time off work. We accomplished the booking in one afternoon — the agent altered the dates twice without complaint, and the whole affair felt effortless.",ar:"كنت أحلم بالسفر إلى الخارج منذ زمن طويل، وأخيرًا حصلت على إجازة من العمل. أنجزنا الحجز في بعد ظهر واحد — غيّر الوكيل التواريخ مرتين دون شكوى، وبدا الأمر كله سهلًا."},{s:1,t:"That's wonderful! Where are you thinking of going? Somewhere exotic, or closer to home? The airline broadcasts the gate changes broadly now — check the app closely, or you'll miss the announcement.",ar:"هذا رائع! إلى أين تفكر في الذهاب؟ إلى مكان غريب، أم إلى مكان أقرب؟ شركة الطيران تبث تغييرات البوابات على نطاق واسع الآن — تحقق من التطبيق عن كثب، وإلا ستفوتك الإعلان."},{s:0,t:"Somewhere exotic, honestly. I've been staring at photos of tropical beaches and I just wanna wander around somewhere totally new. Travel light — a casual outfit, a good book, and certainty that your passport is in your pocket.",ar:"إلى مكان غريب، بصراحة. ظللت أحدّق في صور الشواطئ الاستوائية وأريد فقط أن أتجول في مكان جديد تمامًا. سافر خفيفًا — ملابس عادية وكتاب جيد ويقين بأن جواز سفرك في جيبك."},{s:1,t:"Well, our agency has a great deal on Southeast Asia this month — flights, accommodation, the whole package. The captain clarified the delay clearly — a mechanical fault, nothing serious, but safety comes first.",ar:"حسنًا، وكالتنا لديها عرض رائع على جنوب شرق آسيا هذا الشهر — رحلات جوية وإقامة والحزمة كاملة. أوضح القبطان سبب التأخير بوضوح — عطل ميكانيكي، لا شيء خطير، لكن السلامة أولًا."},{s:0,t:"Accommodation included? That's a bargain. What's the fare, roughly? Honestly, the combination of new food, new faces, and new streets is what makes travel addictive — in the best way.",ar:"الإقامة مشمولة؟ هذه صفقة رابحة. كم سعر التذكرة تقريبًا؟ بصراحة، مزيج الطعام الجديد والوجوه الجديدة والشوارع الجديدة هو ما يجعل السفر مسببًا للإدمان — بأفضل طريقة."},{s:1,t:"Around nine hundred dollars, plus taxes. And you'd need a visa for two of the countries on the route. The resort contributes to the local community — they hire locally, and a portion of every booking funds the village school.",ar:"حوالي تسعمئة دولار، إضافة إلى الضرائب. وستحتاج إلى تأشيرة لدولتين على الطريق. يساهم المنتجع في المجتمع المحلي — يوظفون محليًا، وجزء من كل حجز يموّل مدرسة القرية."},{s:0,t:"A visa? Ugh, I hate paperwork. How long does it take to sort out? Don't dismiss the small towns — the craft markets, the family restaurants, the genuine warmth — they're the heart of the trip.",ar:"تأشيرة؟ أوف، أكره الأوراق الرسمية. كم يستغرق ترتيبها؟ لا تستخف بالبلدات الصغيرة — أسواق الحرف والمطاعم العائلية والدفء الحقيقي — إنها قلب الرحلة."},{s:1,t:"About two weeks if you apply online. But don't leave it till the last minute — the embassy can be painfully slow. The view from the balloon at sunrise was astonishing — the whole valley spread out below us like a painting.",ar:"حوالي أسبوعين إذا قدمت الطلب عبر الإنترنت. لكن لا تؤجله إلى اللحظة الأخيرة — فالسفارة قد تكون بطيئة بشكل مؤلم. كان المنظر من المنطاد عند شروق الشمس مذهلًا — الوادي كله ممتد تحتنا كلوحة."},{s:0,t:"Yeah, I've heard the horror stories. Anyway, what about the landscape there — is it really that stunning? The travel blog accurately describes the island — amusing stories, honest prices, and photos from every angle.",ar:"نعم، سمعت القصص المرعبة. على أي حال، ماذا عن المناظر الطبيعية هناك — هل هي مذهلة حقًا؟ مدونة السفر تصف الجزيرة بدقة — قصص مسلية وأسعار صادقة وصور من كل زاوية."},{s:1,t:"Oh, absolutely. Mountains, rice fields, bays you wouldn't believe. You'll wanna capture every second on camera. Besides the beaches, the island offers hiking, markets, and a cute little harbor town worth a day trip.",ar:"أوه، بالتأكيد. جبال وحقول أرز وخلجان لا تصدقها. سترغب في التقاط كل لحظة بالكاميرا. إضافة إلى الشواطئ، تقدم الجزيرة المشي لمسافات طويلة والأسواق وبلدة ميناء صغيرة لطيفة تستحق رحلة يومية."},{s:0,t:"I can picture it already. But to be honest, I'm a bit nervous about navigating a place where I don't speak the language. The hotel's capacity is limited in high season — book early, or the prices increase considerably.",ar:"أستطيع تخيل ذلك بالفعل. لكن بصراحة، أنا متوتر قليلًا بشأن التنقل في مكان لا أتحدث لغته. سعة الفندق محدودة في الموسم المرتفع — احجز مبكرًا، وإلا سترتفع الأسعار بشكل كبير."},{s:1,t:"You'll adapt faster than you think. Most people there speak some English, and a smile goes a long way. The guide will demonstrate the local cooking — a deliberate, slow process, and the desire to taste everything is real.",ar:"ستتكيف أسرع مما تظن. معظم الناس هناك يتحدثون بعض الإنجليزية، والابتسامة تفعل الكثير. سيوضح المرشد الطبخ المحلي — عملية متعمدة وبطيئة، والرغبة في تذوق كل شيء حقيقية."},{s:0,t:"I hope so. Last time I traveled, my flight got canceled and I ended up sleeping at the airport. Never again. A small donation at the temple is appropriate — the locals appreciate it, and the gesture is genuinely warm.",ar:"آمل ذلك. في المرة الماضية التي سافرت فيها، أُلغيت رحلتي وانتهى بي الأمر نائمًا في المطار. لن يتكرر ذلك أبدًا. تبرع صغير في المعبد مناسب — السكان المحليون يقدرونه، والإيماءة دافئة حقًا."},{s:1,t:"No way! That's rough. Did the airline offer you any compensation afterward? The ferry's schedule is constant in summer — departures every hour, and the crossing takes forty minutes.",ar:"مستحيل! هذا قاسٍ. هل عرضت عليك شركة الطيران أي تعويض بعد ذلك؟ جدول العبّارة ثابت في الصيف — مغادرات كل ساعة، والعبور يستغرق أربعين دقيقة."},{s:0,t:"They gave me a meal voucher and an apology, that's it. I was furious, but what could I do?",ar:"أعطوني قسيمة وجبة واعتذارًا، هذا كل شيء. كنت غاضبًا، لكن ماذا كان بإمكاني أن أفعل؟"},{s:1,t:"I get it. Look, this package includes travel insurance, so if there's a delay, you're covered.",ar:"أفهمك. انظر، هذه الحزمة تشمل تأمين السفر، فإذا حدث تأخير فأنت مغطى."},{s:0,t:"That's reassuring. What about the hotels — are they decent? I don't need luxury, just adequate rooms and a good location.",ar:"هذا مطمئن. ماذا عن الفنادق — هل هي لائقة؟ لا أحتاج إلى رفاهية، فقط غرف كافية وموقع جيد."},{s:1,t:"They're solid three-star places, clean and central. One of them even has a rooftop pool overlooking the bay.",ar:"إنها أماكن جيدة من فئة ثلاث نجوم، نظيفة ومركزية. أحدها لديه حتى مسبح على السطح يطل على الخليج."},{s:0,t:"Nice! And food? I'm kinda picky, but I love trying local dishes — well, as long as nothing's too spicy.",ar:"جميل! والطعام؟ أنا انتقائي نوعًا ما، لكني أحب تجربة الأطباق المحلية — حسنًا، طالما لا شيء حار جدًا."},{s:1,t:"You'll love it. The street food is fabulous, and the flavors are incredible. Just avoid the chili sauce if you're unsure.",ar:"ستحبه. طعام الشارع رائع، والنكهات مذهلة. فقط تجنب صلصة الفلفل الحار إذا لم تكن متأكدًا."},{s:0,t:"Okay, I'm nearly sold. But—",ar:"حسنًا، كدت أقتنع. لكن—"},{s:1,t:"—But what? The price? The dates? Spit it out!",ar:"—لكن ماذا؟ السعر؟ التواريخ؟ قلها!"},{s:0,t:"The dates. My boss only approved two weeks, and the trip is eighteen days. I might have to negotiate.",ar:"التواريخ. مديري وافق على أسبوعين فقط، والرحلة ثمانية عشر يومًا. قد أضطر إلى التفاوض."},{s:1,t:"We could shorten it, you know. Cut the last island, keep the highlights. You'd still see plenty.",ar:"يمكننا تقصيرها، كما تعلم. نحذف الجزيرة الأخيرة ونحتفظ بأبرز المعالم. وسترى الكثير مع ذلك."},{s:0,t:"Hmm, that could work. If I'd booked earlier, I would've had more options, but I kept putting it off.",ar:"همم، قد ينجح ذلك. لو حجزت مبكرًا، لكانت لدي خيارات أكثر، لكني ظللت أؤجل الأمر."},{s:1,t:"That's the third conditional talking — if you'd booked earlier, you'd have had more options. Don't beat yourself up.",ar:"هذا هو الشرط الثالث يتحدث — لو حجزت مبكرًا، لكانت لديك خيارات أكثر. لا تلُم نفسك."},{s:0,t:"Ha! You're right. Okay, let's do the shorter version. Can you hold the booking for a couple of days while I check with work?",ar:"ها! أنت محق. حسنًا، لنأخذ النسخة الأقصر. هل يمكنك الاحتفاظ بالحجز لبضعة أيام بينما أتحقق مع العمل؟"},{s:1,t:"Sure, I can put a temporary hold on it. No charge, no pressure. Just let me know by Friday.",ar:"بالتأكيد، يمكنني الاحتفاظ به مؤقتًا. بلا رسوم وبلا ضغط. فقط أخبرني بحلول يوم الجمعة."},{s:0,t:"You're a lifesaver. Oh, one more thing — can I dive there? I've always wanted to try scuba diving.",ar:"أنت منقذ. أوه، شيء آخر — هل يمكنني الغوص هناك؟ لطالما أردت تجربة الغوص."},{s:1,t:"Absolutely! The reefs are spectacular. I'll add an introductory dive to the package — it's an additional forty dollars.",ar:"بالتأكيد! الشعاب المرجانية مذهلة. سأضيف غوصة تمهيدية إلى الحزمة — إنها أربعون دولارًا إضافية."},{s:0,t:"Perfect. And afterward, I wanna spend a day just doing nothing on the beach. No tours, no schedule.",ar:"مثالي. وبعد ذلك، أريد قضاء يوم لا أفعل فيه شيئًا على الشاطئ. لا جولات ولا جدول."},{s:1,t:"That's the best part of traveling, honestly. Doing nothing, somewhere beautiful, with nowhere to be.",ar:"هذا أفضل جزء في السفر، بصراحة. أن لا تفعل شيئًا، في مكان جميل، وليس لديك مكان تذهب إليه."},{s:0,t:"Exactly. You know, if I hadn't saved up all year, I never would've afforded this trip.",ar:"بالضبط. تعلم، لو لم أدخر طوال العام، لما استطعت تحمل تكلفة هذه الرحلة أبدًا."},{s:1,t:"See? You earned it. Now, let me print the guideline sheet — packing tips, local customs, emergency numbers, all that.",ar:"أرأيت؟ لقد استحققتها. الآن، دعني أطبع ورقة الإرشادات — نصائح التعبئة والعادات المحلية وأرقام الطوارئ، كل ذلك."},{s:0,t:"Thanks. I always forget something. Last trip I forgot my charger and had to buy one at triple the price.",ar:"شكرًا. أنسى شيئًا دائمًا. في الرحلة الماضية نسيت شاحني واضطررت لشراء واحد بثلاثة أضعاف السعر."},{s:1,t:"Classic. Well, pack light, bring sunscreen, and keep your passport somewhere safe. The rest you can figure out on the road.",ar:"كلاسيكي. حسنًا، احزم أمتعة خفيفة، وأحضر واقي الشمس، واحتفظ بجواز سفرك في مكان آمن. والباقي يمكنك تدبيره على الطريق."},{s:0,t:"Got it. So, Friday — I'll confirm by Friday, hopefully with my boss's blessing.",ar:"فهمت. إذن، يوم الجمعة — سأؤكد بحلول الجمعة، وآمل بموافقة مديري."},{s:1,t:"Sounds like a plan. And hey, if anything changes, just call me. That's what I'm here for.",ar:"يبدو أنها خطة. وهيّا، إذا تغير أي شيء، فقط اتصل بي. هذا ما أنا هنا من أجله."},{s:0,t:"Will do. I can't wait to tell my friends — they're gonna be so jealous.",ar:"سأفعل. لا أستطيع الانتظار لأخبر أصدقائي — سيشعرون بغيرة شديدة."},{s:1,t:"They should be! Oh, and one last thing — take a photo of your passport and keep it on your phone, just in case.",ar:"يجب أن يغاروا! أوه، وشيء أخير — التقط صورة لجواز سفرك واحتفظ بها على هاتفك، تحسبًا لأي طارئ."},{s:0,t:"Smart. Thanks a million — I mean it. This is gonna be the trip of a lifetime.",ar:"ذكي. شكرًا جزيلًا — أعني ذلك. ستكون هذه رحلة العمر."},{s:1,t:"I believe you. Have an amazing trip — and send me a postcard from that bay!",ar:"أصدقك. أتمنى لك رحلة مذهلة — وأرسل لي بطاقة بريدية من ذلك الخليج!"},{s:0,t:"Deal. You'll hear from me the moment I land — well, after I figure out the local SIM card, anyway.",ar:"اتفقنا. ستسمع مني لحظة وصولي — حسنًا، بعد أن أدبر بطاقة SIM المحلية، على أي حال."},{s:1,t:"Ha! Safe travels, my friend. The globe is waiting for you.",ar:"ها! رحلة آمنة، يا صديقي. العالم بانتظارك."},{s:0,t:"Oh, before I forget — I accidentally booked the wrong date once and showed up at the airport a full day early. Talk about embarrassing.",ar:"أوه، قبل أن أنسى — حجزت التاريخ الخطأ مرة بالصدفة وظهرت في المطار قبل يوم كامل. تحدث عن الإحراج."},{s:1,t:"No way! Did you just wait there? That's the kind of mistake that teaches you to check every detail twice.",ar:"مستحيل! هل انتظرت هناك فقط؟ هذا نوع الخطأ الذي يعلمك التحقق من كل التفاصيل مرتين."},{s:0,t:"Exactly. Now accuracy matters to me — dates, terminals, baggage rules. One small error can ruin the entire trip.",ar:"بالضبط. الآن الدقة مهمة بالنسبة لي — التواريخ والصالات وقواعد الأمتعة. خطأ صغير واحد يمكن أن يفسد الرحلة كلها."},{s:1,t:"Wise approach. And hey, if you're celebrating an anniversary over there, tell me — some hotels offer a free upgrade for special occasions.",ar:"نهج حكيم. وهيّا، إذا كنت تحتفل بذكرى سنوية هناك، أخبرني — بعض الفنادق تقدم ترقية مجانية للمناسبات الخاصة."},{s:0,t:"Really? That's good to know. My parents' anniversary is in July, and I was thinking of sending them somewhere nice as a gift.",ar:"حقًا؟ هذا جيد أن أعرفه. ذكرى والديّ في يوليو، وكنت أفكر في إرسالهما إلى مكان جميل كهدية."},{s:1,t:"That's a lovely idea. Apparently the island resorts are gorgeous that time of year — warm, quiet, and not too crowded.",ar:"هذه فكرة جميلة. يبدو أن منتجعات الجزر رائعة في ذلك الوقت من السنة — دافئة وهادئة وليست مزدحمة جدًا."},{s:0,t:"Uh-huh. I'll keep that in mind. By the way, do you have any tips for coping with jet lag? It always wrecks me for days.",ar:"أها. سأضع ذلك في ذهني. بالمناسبة، هل لديك أي نصائح للتعامل مع اضطراب الرحلات الجوية الطويلة؟ إنه يدمرني دائمًا لأيام."},{s:1,t:"Sure — stay hydrated, avoid alcohol on the plane, and get sunlight as soon as you land. It helps your body adapt gradually. The trip will briefly test your patience, but calculate the memories, not the expense — it's worth every cent.",ar:"بالتأكيد — حافظ على ترطيب جسمك، وتجنب الكحول على متن الطائرة، واحصل على ضوء الشمس فور هبوطك. يساعد ذلك جسدك على التكيف تدريجيًا. ستختبر الرحلة صبرك لفترة وجيزة، لكن احسب الذكريات وليس المصاريف — إنها تستحق كل قرش."},{s:0,t:"Noted. One more thing — how do I handle money over there? Should I carry cash, or will my card work everywhere? Overall, the comfort is consistent — clean rooms, friendly staff, and the convenience of everything nearby.",ar:"ملاحظ. شيء آخر — كيف أتعامل مع المال هناك؟ هل أحمل نقودًا، أم ستعمل بطاقتي في كل مكان؟ بشكل عام، الراحة متسقة — غرف نظيفة وموظفون ودودون وراحة قرب كل شيء."},{s:1,t:"Cards work in cities, but carry some cash for markets and small towns. And inform your bank beforehand, or they might freeze your card. I'm curious about the distinct flavors and the diversity of the markets — every encounter teaches you something new.",ar:"البطاقات تعمل في المدن، لكن احمل بعض النقود للأسواق والبلدات الصغيرة. وأخبر مصرفك مسبقًا، وإلا فقد يجمد بطاقتك. أنا فضولي بشأن النكهات المميزة وتنوع الأسواق — كل لقاء يعلمك شيئًا جديدًا."},{s:0,t:"Good call. I had my card blocked once abroad and spent two hours on the phone sorting it out. Never again. The detailed guide displays every highlight, and your determination to explore it all is genuine.",ar:"قرار جيد. تم حظر بطاقتي مرة في الخارج وقضيت ساعتين على الهاتف لحل الأمر. لن يتكرر أبدًا. الدليل المفصّل يعرض كل المعالم، وتصميمك على استكشافها كلها حقيقي."},{s:1,t:"Exactly. Oh, and take a photo of your travel insurance details — if anything goes wrong, you'll be relieved you did. Embrace the slow pace — efficient travel enhances the journey, and it ensures you actually enjoy each day.",ar:"بالضبط. أوه، والتقط صورة لتفاصيل تأمين سفرك — إذا حدث أي خطأ، ستشعر بالارتياح لأنك فعلت. احتضن الوتيرة البطيئة — السفر الفعّال يعزز الرحلة، ويضمن أن تستمتع فعلًا بكل يوم."},{s:0,t:"Will do. Honestly, I feel way more confident about this trip now. Thanks for all the guidance. Travel evolves you — it exceeds every expectation, and the extraordinary moments are never the planned ones.",ar:"سأفعل. بصراحة، أشعر بثقة أكبر بشأن هذه الرحلة الآن. شكرًا على كل الإرشادات. السفر يطوّرك — يتجاوز كل التوقعات، واللحظات الاستثنائية ليست أبدًا المخطط لها."},{s:1,t:"Anytime! That's what we're here for. Now go home, pack light, and get excited — your adventure is waiting. Don't hesitate to ask the hotel — they often grant a late checkout, and it makes the final day much easier.",ar:"في أي وقت! هذا ما نحن هنا من أجله. الآن اذهب إلى المنزل، واحزم أمتعة خفيفة، وتحمّس — مغامرتك بانتظارك. لا تتردد في سؤال الفندق — غالبًا ما يمنحون تسجيل خروج متأخرًا، وهذا يجعل اليوم الأخير أسهل بكثير."},{s:0,t:"I will. And I'll send you photos from every stop — the beaches, the food, the whole spectacular mess of it. Take the initiative on day one — trust your inner compass, try the innovative local transport, and keep an open mind.",ar:"سأفعل. وسأرسل لك صورًا من كل محطة — الشواطئ والطعام وكل الفوضى المذهلة فيها. خذ زمام المبادرة في اليوم الأول — ثق ببوصلتك الداخلية، وجرّب وسائل النقل المحلية المبتكرة، وحافظ على عقل منفتح."}]}},{stage:10,topic:"american",topicAr:"الحياة الأمريكية والعامية",topicEn:"American Life & Slang",topicDe:"Amerikanisches Leben und Slang",emoji:"🇺🇸",title:"الحياة في أمريكا",grammar:{id:"en-b2-mixed-conditionals",title:"Mixed conditionals",titleAr:"الجمل الشرطية المختلطة",covers:1},conv:{id:"en-stage10-b2",speakers:["Newcomer (الوافد الجديد)","American Friend (الصديق الأمريكي)"],turns:[{s:0,t:"Okay, be honest with me — how long did it take you to get used to life here? I'm still figuring everything out. The applicant process for a visa is tedious — forms, photos, interviews — but it's worth it in the end.",ar:"حسنًا، كن صادقًا معي — كم استغرق منك التعود على الحياة هنا؟ ما زلت أحاول فهم كل شيء. عملية تقديم طلب التأشيرة مملة — نماذج وصور ومقابلات — لكنها تستحق في النهاية."},{s:1,t:"Oh man, months! If I'd known how different things were, I would've prepared better. But you pick it up fast. Americans love their sports — the emphasis on competition starts young, and the enthusiasm is contagious.",ar:"أوه يا رجل، شهور! لو كنت أعرف مدى اختلاف الأمور، لكنت استعددت بشكل أفضل. لكنك تتعلم بسرعة. الأمريكيون يحبون رياضتهم — التركيز على المنافسة يبدأ صغيرًا، والحماس معدٍ."},{s:0,t:"That's a mixed conditional, right? If I'd known, I would've prepared better. My teacher drilled that into me. The local news channels broadcast the election results broadly — every screen in every bar shows the same map.",ar:"هذا شرط مختلط، أليس كذلك؟ لو كنت أعرف، لكنت استعددت بشكل أفضل. معلمي لقّنني ذلك. قنوات الأخبار المحلية تبث نتائج الانتخابات على نطاق واسع — كل شاشة في كل حانة تعرض نفس الخريطة."},{s:1,t:"Ha! Look at you, already sounding like a textbook. Forget the grammar — how's the accent treating you? My coworker is a genius with spreadsheets — she generates reports in minutes that take me hours.",ar:"ها! انظر إليك، تبدو ككتاب مدرسي بالفعل. انسَ القواعد — كيف يتعامل معك اللكنة؟ زميلتي عبقرية في جداول البيانات — تنشئ تقارير في دقائق تستغرق مني ساعات."},{s:0,t:"The accent is wild. Everyone talks so fast, and they swallow half the words. I keep saying 'what?' like a broken record. The gang at work adopted me instantly — lunch together, jokes, the works. I felt at home within a week.",ar:"اللكنة جنونية. الجميع يتحدث بسرعة شديدة، ويبتلعون نصف الكلمات. أظل أقول «ماذا؟» كأسطوانة مكسورة. جماعة العمل تبنّتني فورًا — غداء معًا ونكات وكل شيء. شعرت أنني في بيتي خلال أسبوع."},{s:1,t:"You'll get the hang of it. The trick is, don't try to catch every word — just grab the main idea and roll with it. Freedom here feels tangible — the right to speak, to vote, to criticize openly without fear.",ar:"ستعتاد عليها. الحيلة هي ألا تحاول التقاط كل كلمة — فقط التقط الفكرة الرئيسية وتعامل معها. الحرية هنا تبدو ملموسة — الحق في الكلام والتصويت والانتقاد علنًا دون خوف."},{s:0,t:"Easier said than done. Yesterday a guy at the store asked me something and I just smiled and nodded. No clue what he said. The governor's speech was broadcast live — he declared new funding for schools, and the crowd cheered.",ar:"أسهل قولًا من فعلًا. أمس سألني رجل في المتجر شيئًا وابتسمت وهززت رأسي فقط. لا فكرة عما قاله. تم بث خطاب الحاكم مباشرة — أعلن تمويلًا جديدًا للمدارس، وهتف الجمهور."},{s:1,t:"That's a classic newcomer move. We've all been there. Next time just say, 'Sorry, could you repeat that?' — nobody minds. The holiday parade downtown was spectacular — marching bands, floats, and the whole town in costume.",ar:"هذه حركة كلاسيكية للوافد الجديد. مررنا جميعًا بذلك. في المرة القادمة قل فقط: «عذرًا، هل يمكنك تكرار ذلك؟» — لا أحد يمانع. كان موكب العطلة وسط المدينة مذهلًا — فرق موسيقية وعربات مزينة والبلدة كلها متنكرة."},{s:0,t:"I'll try. So, what's the deal with tipping? I tipped the barista twenty percent and my coworker looked at me like I was crazy. The local paper's illustration of the election was hilarious — a cartoon donkey and elephant arm-wrestling.",ar:"سأحاول. إذن، ما قصة البقشيش؟ أعطيت صانع القهوة عشرين بالمئة وزميلي نظر إليّ كأنني مجنون. كان رسم الصحيفة المحلية للانتخابات مضحكًا — حمار وفيل كرتونيان يتصارعان بالأذرع."},{s:1,t:"Twenty percent at a coffee shop? Dude, that's generous! Usually a dollar in the jar is plenty. You were way too nice. The jury duty letter arrived — every citizen gets one eventually, and there's no escaping it.",ar:"عشرون بالمئة في مقهى؟ يا رجل، هذا كرم! عادة دولار في العلبة يكفي. كنت لطيفًا أكثر من اللازم. وصلت رسالة واجب هيئة المحلفين — كل مواطن يحصل على واحدة في النهاية، ولا مفر منها."},{s:0,t:"I had no idea! In my country, tipping isn't really a thing. If I'd understood the system, I wouldn't have overpaid all week. The local diner's portions are legendary — pancakes the size of dinner plates, and coffee refills forever.",ar:"لم أكن أعرف! في بلدي، البقشيش ليس شيئًا حقيقيًا. لو فهمت النظام، لما دفعت أكثر من اللازم طوال الأسبوع. حصص المطعم المحلي أسطورية — فطائر بحجم أطباق العشاء، وإعادة تعبئة القهوة إلى الأبد."},{s:1,t:"There you go again with the conditionals! But yeah, tipping here is basically a whole science. Restaurants, taxis, delivery guys... The highway patrol is strict — the fines are steep, and nobody argues.",ar:"ها أنت مجددًا مع الجمل الشرطية! لكن نعم، البقشيش هنا علم كامل تقريبًا. المطاعم وسيارات الأجرة وعمال التوصيل... دورية الطرق السريعة صارمة — الغرامات باهظة، ولا أحد يجادل."},{s:0,t:"And small talk! Everyone asks 'how's it going?' but they don't actually wanna hear the answer. That threw me off. The state fair's pie contest is serious business — the winner gets a ribbon and local fame.",ar:"والحديث القصير! الجميع يسأل «كيف حالك؟» لكنهم لا يريدون سماع الإجابة فعلًا. هذا أربكني. مسابقة فطيرة معرض الولاية عمل جاد — الفائز يحصل على شريط وشهرة محلية."},{s:1,t:"Oh yeah, that's just a greeting. You say 'pretty good, you?' and keep walking. It's not a real question — it's like saying hi. The neighborhood block party is an institution — grills, music, and everyone knowing everyone.",ar:"أوه نعم، هذه مجرد تحية. تقول «بخير، وأنت؟» وتواصل المشي. إنه ليس سؤالًا حقيقيًا — إنه مثل قول مرحبًا. حفلة الحي مؤسسة — مشاوٍ وموسيقى والجميع يعرف الجميع."},{s:0,t:"Weird, but okay. What about the whole cowboy thing? I expected hats and horses everywhere, but this city feels so normal.",ar:"غريب، لكن حسنًا. ماذا عن موضوع رعاة البقر؟ توقعت قبعات وخيولًا في كل مكان، لكن هذه المدينة تبدو عادية جدًا."},{s:1,t:"Ha! The cowboy image is mostly movies and Texas. Here it's coffee shops, traffic, and people staring at their phones — like anywhere else.",ar:"ها! صورة راعي البقر معظمها أفلام وتكساس. هنا مقاهٍ وازدحام مروري وأناس يحدقون في هواتفهم — مثل أي مكان آخر."},{s:0,t:"Fair enough. And the food portions! I ordered a small salad and got a mountain of food. I couldn't finish half of it.",ar:"عادل بما فيه الكفاية. وحصص الطعام! طلبت سلطة صغيرة وحصلت على جبل من الطعام. لم أستطع إنهاء نصفه."},{s:1,t:"Welcome to America, my friend. Everything's super-sized. That's why doggy bags exist — you take the leftovers home.",ar:"مرحبًا بك في أمريكا، يا صديقي. كل شيء بحجم ضخم. لهذا توجد أكياس بقايا الطعام — تأخذ الباقي إلى المنزل."},{s:0,t:"Doggy bag — I love that phrase. So, tell me about voting. Everyone keeps talking about the elections like it's the Super Bowl.",ar:"كيس بقايا الطعام — أحب هذه العبارة. إذن، حدثني عن التصويت. الجميع يتحدث عن الانتخابات كأنها السوبر بول."},{s:1,t:"Honestly, politics here is a big deal. The Senate, Congress, the governor — people argue about it at dinner, at work, everywhere.",ar:"بصراحة، السياسة هنا أمر كبير. مجلس الشيوخ والكونغرس والحاكم — الناس يتجادلون حولها على العشاء وفي العمل وفي كل مكان."},{s:0,t:"Sounds intense. Back home, we avoided politics at the table. Here it's like a sport.",ar:"يبدو شديدًا. في بلدي، كنا نتجنب السياسة على المائدة. هنا الأمر مثل الرياضة."},{s:1,t:"Pretty much. And democracy here means everyone has an opinion, and everyone thinks theirs is the right one.",ar:"تقريبًا. والديمقراطية هنا تعني أن لكل شخص رأيًا، وكل شخص يظن أن رأيه هو الصحيح."},{s:0,t:"I noticed! My neighbor and I had a debate about healthcare that lasted two hours. It got pretty heated.",ar:"لاحظت ذلك! أنا وجاري خضنا نقاشًا حول الرعاية الصحية استمر ساعتين. وأصبح حادًا جدًا."},{s:1,t:"Oh boy. Healthcare is the topic you never bring up at a barbecue unless you want a fight. Lesson learned, right?",ar:"يا إلهي. الرعاية الصحية هي الموضوع الذي لا تطرحه أبدًا في حفلة شواء إلا إذا أردت شجارًا. تعلمت الدرس، أليس كذلك؟"},{s:0,t:"Lesson learned, for sure. But I like how open people are. If I were shy, I would've stayed lonely for months.",ar:"تعلمت الدرس، بالتأكيد. لكني أحب انفتاح الناس. لو كنت خجولًا، لبقيت وحيدًا لشهور."},{s:1,t:"Exactly — and that's another mixed one. See, you're getting it without even trying now.",ar:"بالضبط — وهذه أخرى مختلطة. أرأيت، أنت تفهمها دون أن تحاول حتى الآن."},{s:0,t:"Maybe. So, what's this thing about freedom? Everyone throws that word around like it's magic.",ar:"ربما. إذن، ما قصة الحرية؟ الجميع يلقي بهذه الكلمة كأنها سحر."},{s:1,t:"Freedom is huge here — freedom of speech, freedom to do your own thing. It's part of the whole American identity.",ar:"الحرية ضخمة هنا — حرية التعبير وحرية فعل ما تريد. إنها جزء من الهوية الأمريكية كلها."},{s:0,t:"I respect that. Though sometimes it feels like freedom also means nobody helps you when you're stuck.",ar:"أحترم ذلك. رغم أن الأمر يبدو أحيانًا أن الحرية تعني أيضًا أن لا أحد يساعدك عندما تتعثر."},{s:1,t:"Oof, that's deep — and honestly, kind of true. Independence is prized here, sometimes too much. People don't wanna seem needy.",ar:"أوف، هذا عميق — وبصراحة، صحيح نوعًا ما. الاستقلالية مقدّرة هنا، وأحيانًا أكثر من اللازم. الناس لا يريدون أن يبدوا محتاجين."},{s:0,t:"Yeah, I've felt that. Anyway —",ar:"نعم، شعرت بذلك. على أي حال —"},{s:1,t:"—Anyway what? You were gonna say something about your job hunt, weren't you?",ar:"—على أي حال ماذا؟ كنت ستقول شيئًا عن بحثك عن عمل، أليس كذلك؟"},{s:0,t:"Yeah, I was. I applied for a bunch of part-time jobs, but no luck yet. It's frustrating, I won't lie.",ar:"نعم، كنت كذلك. تقدمت للعديد من الوظائف بدوام جزئي، لكن بلا حظ حتى الآن. إنه محبط، لن أكذب."},{s:1,t:"Hang in there. If you'd arrived a month earlier, you would've caught the hiring season. It's just bad timing.",ar:"اصبر. لو وصلت قبل شهر، لكنت لحقت موسم التوظيف. إنه مجرد توقيت سيئ."},{s:0,t:"Story of my life. But my English is improving, and that's the main thing. My landlord even complimented me yesterday.",ar:"قصة حياتي. لكن إنجليزيتي تتحسن، وهذا أهم شيء. حتى مالك منزلي أثنى عليّ أمس."},{s:1,t:"No way! What'd he say?",ar:"مستحيل! ماذا قال؟"},{s:0,t:"He said my accent sounds way more natural now. I nearly hugged the guy.",ar:"قال إن لكنتي تبدو طبيعية أكثر الآن. كدت أعانق الرجل."},{s:1,t:"That's awesome. You're settling in, whether you realize it or not. Give it a few more months.",ar:"هذا رائع. أنت تستقر، سواء أدركت ذلك أم لا. امنح الأمر بضعة أشهر أخرى."},{s:0,t:"I hope you're right. One day I wanna feel like this place is home, not just where I live.",ar:"آمل أنك محق. يومًا لا أريد أن أشعر أن هذا المكان هو بيتي، وليس فقط حيث أعيش."},{s:1,t:"You will. It sneaks up on you. One morning you wake up and realize you belong here.",ar:"ستشعر بذلك. يتسلل إليك. في صباح ما تستيقظ وتدرك أنك تنتمي إلى هنا."},{s:0,t:"I like the sound of that. Thanks for the pep talk — I needed it more than I thought.",ar:"يعجبني هذا الكلام. شكرًا على الحديث التشجيعي — كنت أحتاجه أكثر مما ظننت."},{s:1,t:"Anytime, buddy. That's what friends are for. Now, let's grab a burger — my treat, and no tipping the cook!",ar:"في أي وقت، يا صديقي. هذا ما الأصدقاء من أجله. الآن، لنأخذ برغر — على حسابي، ولا بقشيش للطاهي!"},{s:0,t:"Ha! Deal. But I'm still tipping the waiter — I don't wanna be that guy.",ar:"ها! اتفقنا. لكني سأعطي النادل بقشيشًا — لا أريد أن أكون ذلك الشخص."},{s:1,t:"Fair enough. You're learning fast, my friend. Real fast.",ar:"عادل بما فيه الكفاية. أنت تتعلم بسرعة، يا صديقي. بسرعة حقيقية."},{s:0,t:"You know, there's one aspect of American life I still don't get — the small talk with strangers in elevators. It's so awkward.",ar:"تعلم، هناك جانب واحد من الحياة الأمريكية ما زلت لا أفهمه — الحديث القصير مع الغرباء في المصاعد. إنه محرج جدًا."},{s:1,t:"Ha! Yeah, elevator talk is an art form here. Weather, sports, the traffic — anything to fill the silence.",ar:"ها! نعم، حديث المصعد فن هنا. الطقس والرياضة والمرور — أي شيء لملء الصمت."},{s:0,t:"Uh-huh. And what about dating? I mean, is it normal to just walk up to someone in a coffee shop?",ar:"أها. وماذا عن المواعدة؟ أعني، هل من الطبيعي أن تقترب من شخص في مقهى؟"},{s:1,t:"It happens, but honestly, most people meet through friends or apps nowadays. Walking up to strangers takes serious courage.",ar:"يحدث ذلك، لكن بصراحة، معظم الناس يلتقون عبر الأصدقاء أو التطبيقات في الوقت الحاضر. الاقتراب من الغرباء يتطلب شجاعة حقيقية."},{s:0,t:"Good to know. I was worried I'd offend someone by accident. The rules here feel so different from back home.",ar:"جيد أن أعرف. كنت قلقًا من أن أسيء إلى شخص بالصدفة. القواعد هنا تبدو مختلفة جدًا عن بلدي."},{s:1,t:"Don't stress about it. Americans are generally open-minded, and most people will forgive an honest mistake.",ar:"لا تقلق بشأن ذلك. الأمريكيون عمومًا منفتحون، ومعظم الناس سيسامحون خطأً صادقًا."},{s:0,t:"That's reassuring. Oh — what's the deal with Halloween? People go absolutely crazy over it, right?",ar:"هذا مطمئن. أوه — ما قصة الهالوين؟ الناس يجنون به تمامًا، أليس كذلك؟"},{s:1,t:"Oh yeah, it's huge! People spend a fortune on costumes and decorations. Some houses look like haunted mansions. The initial culture shock fades gradually — nowadays I barely notice the differences that once confused me.",ar:"أوه نعم، إنه ضخم! الناس ينفقون ثروة على الأزياء والزينة. بعض المنازل تبدو كقصور مسكونة. صدمة الثقافة الأولية تتلاشى تدريجيًا — في الوقت الحاضر بالكاد ألاحظ الاختلافات التي كانت تربكني."},{s:0,t:"I saw that! My neighbor's house has a giant skeleton on the roof. It's hilarious and terrifying at the same time. Immigration paperwork tests your patience, but the outcome — a new life — is worth every form and fee.",ar:"رأيت ذلك! منزل جاري به هيكل عظمي عملاق على السطح. إنه مضحك ومرعب في نفس الوقت. أوراق الهجرة تختبر صبرك، لكن النتيجة — حياة جديدة — تستحق كل نموذج ورسم."},{s:1,t:"Ha! That's nothing — wait till you see Christmas. Some streets compete over who has the most lights. It's a whole contest. My neighbor's generosity impressed me — he even offered his ladder when I needed to fix the porch light.",ar:"ها! هذا لا شيء — انتظر حتى ترى عيد الميلاد. بعض الشوارع تتنافس على من لديه أكثر الأضواء. إنها مسابقة كاملة. كرم جاري أثار إعجابي — حتى أنه عرض سلّمه عندما احتجت لإصلاح مصباح الشرفة."},{s:0,t:"A contest for lights? That's wild. I love how seriously people take their holidays here — it's charming, honestly. The jury's still out on the best pizza place — every borough claims the prime slice, and the debate never ends.",ar:"مسابقة للأضواء؟ هذا جنوني. أحب مدى جدية الناس في أعيادهم هنا — إنه ساحر، بصراحة. ما زالت هيئة المحلفين مترددة بشأن أفضل مكان للبيتزا — كل حي يدّعي الشريحة الأفضل، والنقاش لا ينتهي أبدًا."},{s:1,t:"It is charming. And Thanksgiving — that's the big one. Families travel across the country just to eat turkey together. Honesty matters here — people respect a sincere apology far more than a polished excuse.",ar:"إنه ساحر. وعيد الشكر — هذا هو الكبير. العائلات تسافر عبر البلاد فقط لتأكل الديك الرومي معًا. الصدق مهم هنا — الناس يحترمون الاعتذار الصادق أكثر بكثير من العذر المصقول."},{s:0,t:"Turkey, family, football — I think I'm getting the picture. Can I come to your Thanksgiving? I'm serious! The local mosque, church, and temple share one street — a genuine symbol of diversity and mutual respect.",ar:"ديك رومي وعائلة وكرة قدم — أعتقد أنني أفهم الصورة. هل يمكنني المجيء إلى عيد الشكر لديك؟ أنا جاد! المسجد والكنيسة والمعبد المحليون يتشاركون شارعًا واحدًا — رمز حقيقي للتنوع والاحترام المتبادل."},{s:1,t:"Of course! My mom would love it — she always says the more, the merrier. Just bring your appetite. Freedom of speech is fiercely protected — nevertheless, people choose their words carefully at work.",ar:"بالطبع! أمي ستحب ذلك — تقول دائمًا كلما زاد العدد كان أفضل. فقط أحضر شهيتك. حرية التعبير محمية بشدة — ومع ذلك، يختار الناس كلماتهم بعناية في العمل."},{s:0,t:"Deal! I'll bring dessert — well, I'll try to bake something. No promises it won't be a disaster. Small-town America feels different — the pace is slower, the humor warmer, and strangers actually wave at you.",ar:"اتفقنا! سأحضر الحلوى — حسنًا، سأحاول خبز شيء. لا وعود بأنها لن تكون كارثة. البلدات الأمريكية الصغيرة تبدو مختلفة — الوتيرة أبطأ، والفكاهة أدفأ، والغرباء يلوّحون لك فعلًا."}]}},{stage:11,topic:"business",topicAr:"الأعمال والمال",topicEn:"Business & Money",topicDe:"Geschäft und Geld",emoji:"📈",title:"صفقة على المحك",grammar:{id:"en-b2-reported-speech-tense-shifts",title:"Reported speech: tense shifts",titleAr:"الكلام المنقول وتغيير الأزمنة",covers:1},conv:{id:"en-stage11-b2",speakers:["Manager (المدير)","Employee (الموظف)"],turns:[{s:0,t:"Okay, let's cut to the chase. The quarterly numbers are in, and honestly, they're not great. Revenue is down eight percent. The commission reviewed our figures — their evaluation was fair, and the feedback was genuinely useful.",ar:"حسنًا، لندخل في صلب الموضوع. الأرقام الفصلية وصلت، وبصراحة، ليست جيدة. الإيرادات انخفضت ثمانية بالمئة. راجعت اللجنة أرقامنا — كان تقييمها عادلًا، وكانت الملاحظات مفيدة حقًا."},{s:1,t:"Eight percent? Ouch. I thought the new product line would've boosted sales by now. We must eliminate waste — every unnecessary expense weakens the budget, and the board notices everything.",ar:"ثمانية بالمئة؟ أوه. ظننت أن خط المنتجات الجديد كان سيعزز المبيعات الآن. يجب أن نقضي على الهدر — كل مصروف غير ضروري يضعف الميزانية، والمجلس يلاحظ كل شيء."},{s:0,t:"It should have, but the launch was delayed by three weeks, and we missed the whole holiday season. The database tracks every sale — the numbers don't lie, and the trends are clear for anyone who looks.",ar:"كان يجب أن يفعل، لكن الإطلاق تأخر ثلاثة أسابيع، وفاتنا موسم العطلات كله. قاعدة البيانات تتعقب كل عملية بيع — الأرقام لا تكذب، والاتجاهات واضحة لأي شخص ينظر."},{s:1,t:"That's rough. We could've hit our targets if the supply chain hadn't fallen apart in October. Our chief analyst predicts modest growth — the forecast is cautious, but the direction is right.",ar:"هذا قاسٍ. كان بإمكاننا تحقيق أهدافنا لو لم تنهر سلسلة التوريد في أكتوبر. محللنا الرئيسي يتوقع نموًا متواضعًا — التوقع حذر، لكن الاتجاه صحيح."},{s:0,t:"Exactly. And the board isn't happy. They're asking for a recovery plan by Friday, and it has to be convincing. The merger talks collapsed last year — the two companies couldn't agree, and the deal died overnight.",ar:"بالضبط. ومجلس الإدارة غير سعيد. يطلبون خطة تعافٍ بحلول الجمعة، ويجب أن تكون مقنعة. انهارت محادثات الاندماج العام الماضي — لم تستطع الشركتان الاتفاق، وماتت الصفقة بين ليلة وضحاها."},{s:1,t:"Friday? That's tight. But we can pull it off if we focus. What's the budget for the turnaround? We contribute a portion of profits to charity — it's good ethics, and the team is proud of it.",ar:"الجمعة؟ هذا ضيق. لكن يمكننا إنجازه إذا ركزنا. ما الميزانية المخصصة للتحول؟ نساهم بجزء من الأرباح للأعمال الخيرية — إنها أخلاقيات جيدة، والفريق فخور بها."},{s:0,t:"That's the tricky part — the budget's been cut by fifteen percent. We'll have to do more with less, like always. The CEO's vision is bold — expand abroad, invest in technology, and dominate the market within five years.",ar:"هذا هو الجزء الصعب — الميزانية خُفضت بنسبة خمسة عشر بالمئة. سيتعين علينا فعل المزيد بأقل، كالعادة. رؤية الرئيس التنفيذي جريئة — التوسع في الخارج والاستثمار في التكنولوجيا والهيمنة على السوق خلال خمس سنوات."},{s:1,t:"More with less — my favorite corporate slogan. So, where do we start? Marketing? Operations? The contract's fine print matters — read every clause, or the penalty will surprise you later.",ar:"المزيد بأقل — شعاري المفضل في الشركات. إذن، من أين نبدأ؟ التسويق؟ العمليات؟ التفاصيل الدقيقة في العقد مهمة — اقرأ كل بند، وإلا ستفاجئك الغرامة لاحقًا."},{s:0,t:"Marketing first. Our advertising spend is way too high for the return we're getting. We need to rethink the whole strategy. The startup is growing rapidly — the team doubled in a year, and the office can't keep up.",ar:"التسويق أولًا. إنفاقنا على الإعلان مرتفع جدًا مقارنة بالعائد الذي نحصل عليه. نحتاج إلى إعادة التفكير في الاستراتيجية كلها. الشركة الناشئة تنمو بسرعة — تضاعف الفريق في عام، والمكتب لا يستطيع المواكبة."},{s:1,t:"Agreed. The last campaign cost a fortune and barely moved the needle. We might've been better off spending it on the product itself. The quarterly report ranks us third in the sector — respectable, but the board wants first.",ar:"موافق. الحملة الأخيرة كلفت ثروة وبالكاد أحدثت فرقًا. ربما كان الأفضل أن ننفقها على المنتج نفسه. التقرير الفصلي يضعنا في المرتبة الثالثة في القطاع — محترم، لكن المجلس يريد الأولى."},{s:0,t:"Hindsight, right? Look, I've been talking to an entrepreneur friend of mine, and she had a brilliant idea about partnerships. The merger's failure cost millions — the shareholders were furious, and the CEO resigned.",ar:"بعد فوات الأوان، أليس كذلك؟ انظر، تحدثت مع صديقة لي رائدة أعمال، وكانت لديها فكرة رائعة حول الشراكات. كلّف فشل الاندماج الملايين — كان المساهمون غاضبين، واستقال الرئيس التنفيذي."},{s:1,t:"Partnerships? I'm listening. Who'd we team up with? The retirement fund invests cautiously — steady returns matter more than spectacular gains.",ar:"شراكات؟ أنا أستمع. مع من سنتحالف؟ صندوق التقاعد يستثمر بحذر — العوائد الثابتة أهم من المكاسب المذهلة."},{s:0,t:"A logistics firm — they'd handle distribution, we'd handle the brand. It could cut our costs by twenty percent, maybe more. The company's profits soared — the shareholders were satisfied, and the CEO announced bonuses.",ar:"شركة لوجستيات — ستتولى التوزيع، ونتولى نحن العلامة التجارية. قد يخفض تكاليفنا بنسبة عشرين بالمئة، وربما أكثر. ارتفعت أرباح الشركة — كان المساهمون راضين، وأعلن الرئيس التنفيذي عن مكافآت."},{s:1,t:"That sounds promising. But we'd need to negotiate carefully — I don't wanna give away too much control. The tax rules changed again — the accountant spent a week untangling the new requirements.",ar:"يبدو ذلك واعدًا. لكننا نحتاج إلى التفاوض بعناية — لا أريد التخلي عن الكثير من السيطرة. تغيرت قواعد الضرائب مجددًا — قضى المحاسب أسبوعًا في فك تشابك المتطلبات الجديدة."},{s:0,t:"Of course. The negotiation starts next week. I've already asked our attorney to review the draft agreement.",ar:"بالطبع. يبدأ التفاوض الأسبوع المقبل. طلبت بالفعل من محامينا مراجعة مسودة الاتفاقية."},{s:1,t:"Smart move. And what about the team? People are nervous. Rumors are flying around the office.",ar:"خطوة ذكية. وماذا عن الفريق؟ الناس متوترون. الشائعات تطير في أرجاء المكتب."},{s:0,t:"I know, and I hate that. We should've addressed it sooner — silence just feeds the anxiety.",ar:"أعلم، وأكره ذلك. كان يجب أن نعالج الأمر مبكرًا — الصمت يغذي القلق فقط."},{s:1,t:"True. A short, honest update from you would go a long way. People can handle bad news; they can't handle being kept in the dark.",ar:"صحيح. تحديث قصير وصادق منك سيقطع شوطًا طويلًا. الناس يستطيعون تحمل الأخبار السيئة؛ لا يستطيعون تحمل البقاء في الظلام."},{s:0,t:"You're right. I'll hold a meeting tomorrow morning — no spin, just the facts and the plan.",ar:"أنت محق. سأعقد اجتماعًا صباح الغد — بلا تجميل، فقط الحقائق والخطة."},{s:1,t:"Good. Now, about the investment proposal — did the investors respond to our pitch?",ar:"جيد. الآن، بخصوص مقترح الاستثمار — هل رد المستثمرون على عرضنا؟"},{s:0,t:"Not yet. They said they'd get back to us by the end of the month. The funding round is make-or-break for us.",ar:"ليس بعد. قالوا إنهم سيردون علينا بنهاية الشهر. جولة التمويل مصيرية بالنسبة لنا."},{s:1,t:"No pressure, then! If we land this, we could expand into two new markets next year.",ar:"لا ضغط إذن! إذا حصلنا على هذا، يمكننا التوسع إلى سوقين جديدتين العام المقبل."},{s:0,t:"That's the dream. But let's not count our chickens. First, the recovery plan — I need your analysis of the sales data by Wednesday.",ar:"هذا هو الحلم. لكن دعنا لا نستبق الأمور. أولًا، خطة التعافي — أحتاج تحليلك لبيانات المبيعات بحلول الأربعاء."},{s:1,t:"Wednesday, got it. I'll dig into the numbers tonight. The data's messy, but I'll clean it up.",ar:"الأربعاء، فهمت. سأتعمق في الأرقام الليلة. البيانات فوضوية، لكني سأنظفها."},{s:0,t:"Thanks. Oh, and one more thing — the headquarters wants a report on our retail performance too.",ar:"شكرًا. أوه، وشيء آخر — المقر الرئيسي يريد تقريرًا عن أدائنا في البيع بالتجزئة أيضًا."},{s:1,t:"Retail as well? They never stop, do they? Fine, I'll fold it into the same document.",ar:"البيع بالتجزئة أيضًا؟ إنهم لا يتوقفون أبدًا، أليس كذلك؟ حسنًا، سأدمجه في نفس المستند."},{s:0,t:"You're a star. Listen, I know this quarter's been brutal, but I genuinely believe we can turn it around.",ar:"أنت نجم. اسمع، أعلم أن هذا الربع كان قاسيًا، لكني أؤمن حقًا أننا نستطيع قلب الأمور."},{s:1,t:"I believe it too. The product's solid, the team's talented — we just need a bit of luck and a lot of focus.",ar:"أؤمن بذلك أيضًا. المنتج قوي والفريق موهوب — نحتاج فقط إلى قليل من الحظ وكثير من التركيز."},{s:0,t:"Well said. Now, let's get to work — we've got a plan to save and a deadline to beat.",ar:"أحسنت القول. الآن، لنبدأ العمل — لدينا خطة لإنقاذها وموعد نهائي للتغلب عليه."},{s:1,t:"On it. Oh wait —",ar:"سأبدأ. أوه انتظر —"},{s:0,t:"—What now? Don't tell me there's more bad news.",ar:"—ماذا الآن؟ لا تخبرني أن هناك أخبارًا سيئة أخرى."},{s:1,t:"No, good news for once! The client from Chicago just confirmed the big order. That's a huge win.",ar:"لا، أخبار جيدة هذه المرة! عميل شيكاغو أكد للتو الطلب الكبير. هذا فوز ضخم."},{s:0,t:"Are you serious? That's fantastic! That alone covers a big chunk of the shortfall.",ar:"هل أنت جاد؟ هذا رائع! هذا وحده يغطي جزءًا كبيرًا من العجز."},{s:1,t:"I know, right? Maybe our luck is finally turning. Let's celebrate with coffee — my treat.",ar:"أعلم، أليس كذلك؟ ربما حظنا يتغير أخيرًا. لنحتفل بالقهوة — على حسابي."},{s:0,t:"Deal. And hey — we must have done something right, after all.",ar:"اتفقنا. وهيّا — لا بد أننا فعلنا شيئًا صحيحًا، بعد كل شيء."},{s:1,t:"We must have. Now let's keep the momentum going.",ar:"لا بد أننا فعلنا. الآن لنحافظ على الزخم."},{s:0,t:"Agreed. One win at a time — that's how turnarounds happen.",ar:"موافق. فوز واحد في كل مرة — هكذا تحدث التحولات."},{s:1,t:"Exactly. I'll send you the draft analysis tonight, and we'll polish it tomorrow.",ar:"بالضبط. سأرسل لك مسودة التحليل الليلة، وسنصقلها غدًا."},{s:0,t:"Perfect. And remember — if the board asks tough questions, we've got the answers. We've done the homework.",ar:"مثالي. وتذكر — إذا طرح المجلس أسئلة صعبة، فلدينا الإجابات. لقد قمنا بالواجب."},{s:1,t:"We've got this. See you at the meeting tomorrow — bright and early.",ar:"سننجح. أراك في الاجتماع غدًا — باكرًا جدًا."},{s:0,t:"Bright and early. Don't be late — you know how I hate waiting.",ar:"باكرًا جدًا. لا تتأخر — تعلم كم أكره الانتظار."},{s:1,t:"Wouldn't dream of it, boss. Wouldn't dream of it.",ar:"لن أحلم بذلك، يا مدير. لن أحلم بذلك."},{s:0,t:"Ha! Now go — that data won't analyze itself.",ar:"ها! الآن اذهب — تلك البيانات لن تحلل نفسها."},{s:1,t:"On my way. And boss — thanks for trusting me with this. It means a lot.",ar:"في طريقي. مع مدير — شكرًا لثقتك بي في هذا. هذا يعني الكثير."},{s:0,t:"Oh, and one more item — the finance team flagged an issue with our expense reports. Some receipts are missing, and the auditors are coming next month.",ar:"أوه، وبند آخر — فريق المالية أشار إلى مشكلة في تقارير مصروفاتنا. بعض الإيصالات مفقودة، والمدققون قادمون الشهر المقبل."},{s:1,t:"Auditors? Great, just what we need. I'll chase down the missing receipts today — no excuses this time.",ar:"مدققون؟ رائع، هذا بالضبط ما نحتاجه. سأطارد الإيصالات المفقودة اليوم — بلا أعذار هذه المرة."},{s:0,t:"Thanks. Accuracy in finance isn't optional — one error can trigger a full investigation, and we don't need that.",ar:"شكرًا. الدقة في المالية ليست اختيارية — خطأ واحد يمكن أن يطلق تحقيقًا كاملًا، ولا نحتاج ذلك."},{s:1,t:"Agreed. Speaking of numbers, inflation is hitting our costs hard. Suppliers raised prices twice this quarter already.",ar:"موافق. وبالحديث عن الأرقام، التضخم يضرب تكاليفنا بشدة. رفع الموردون الأسعار مرتين هذا الربع بالفعل."},{s:0,t:"I noticed. Our profit margins are shrinking, and if the trend continues, we'll have to adjust our pricing strategy.",ar:"لاحظت ذلك. هوامش أرباحنا تتقلص، وإذا استمر الاتجاه، فسيتعين علينا تعديل استراتيجية التسعير."},{s:1,t:"That's a tough call — raise prices and risk losing customers, or absorb the costs and watch profits fall.",ar:"هذا قرار صعب — نرفع الأسعار ونخاطر بفقدان العملاء، أو نستوعب التكاليف ونشاهد الأرباح تنخفض."},{s:0,t:"Exactly the dilemma. The board wants growth, but the market is brutal right now. There's a recession looming, if you ask me.",ar:"هذا هو المعضلة بالضبط. المجلس يريد النمو، لكن السوق قاسٍ الآن. هناك ركود يلوح في الأفق، إذا سألتني."},{s:1,t:"A recession? You really think so? Our competitors seem optimistic — they're hiring, not firing. The assessment of the proposal takes accuracy — one wrong figure destroys confidence with the board.",ar:"ركود؟ هل تعتقد ذلك حقًا؟ منافسونا يبدون متفائلين — إنهم يوظفون، لا يفصلون. تقييم المقترح يتطلب دقة — رقم واحد خاطئ يدمر الثقة مع المجلس."},{s:0,t:"They're optimistic in public. Behind closed doors, everyone's cautious. I've seen this pattern before — it rarely ends well. Our competitor's aggressive pricing is a real concern — consequently, we must defend our market share.",ar:"إنهم متفائلون علنًا. خلف الأبواب المغلقة، الجميع حذر. رأيت هذا النمط من قبل — ونادرًا ما ينتهي بشكل جيد. تسعير منافسنا العدواني مصدر قلق حقيقي — وبالتالي، يجب أن ندافع عن حصتنا في السوق."},{s:1,t:"Fair point. So what's our move? Cut costs, or invest through the downturn and come out stronger? The contract's terms are consistent — no hidden clauses, and the obligations are clear for both sides.",ar:"نقطة عادلة. إذن ما خطوتنا؟ نخفض التكاليف، أم نستثمر خلال التراجع ونخرج أقوى؟ شروط العقد متسقة — لا بنود خفية، والالتزامات واضحة لكلا الطرفين."},{s:0,t:"A bit of both, honestly. Trim the waste, protect the core team, and keep investing in the product. That's my proposal. We should consult the data before deciding — the evidence supports a cautious expansion, not a reckless one.",ar:"قليل من كليهما، بصراحة. نقلّص الهدر ونحمي الفريق الأساسي ونواصل الاستثمار في المنتج. هذا هو مقترحي. يجب أن نستشير البيانات قبل اتخاذ القرار — الأدلة تدعم توسعًا حذرًا، وليس متهورًا."},{s:1,t:"I like it — balanced and realistic. I'll draft the numbers tonight and we'll present it together on Friday. The recession risk is real — nevertheless, our long-term strategy remains solid if we stay disciplined.",ar:"يعجبني — متوازن وواقعي. سأعد الأرقام الليلة وسنقدمها معًا يوم الجمعة. خطر الركود حقيقي — ومع ذلك، استراتيجيتنا طويلة الأمد تظل قوية إذا بقينا منضبطين."},{s:0,t:"Perfect. And hey — thanks for pushing back in these meetings. A good debate makes the final decision stronger. Revenue growth depends on retention — acquire new clients, but never neglect the loyal ones.",ar:"مثالي. وهيّا — شكرًا لمعارضتك في هذه الاجتماعات. النقاش الجيد يجعل القرار النهائي أقوى. نمو الإيرادات يعتمد على الاحتفاظ بالعملاء — اكتسب عملاء جددًا، لكن لا تهمل المخلصين أبدًا."},{s:1,t:"Anytime, boss. That's what I'm here for — well, that and the free coffee. The board will approve the budget if the projections are realistic and the risks are clearly stated.",ar:"في أي وقت يا مدير. هذا ما أنا هنا من أجله — حسنًا، ذلك والقهوة المجانية. سيوافق المجلس على الميزانية إذا كانت التوقعات واقعية والمخاطر مذكورة بوضوح."},{s:0,t:"Ha! The coffee's the real reason we all show up, let's be honest. Inflation and supply costs squeeze our margins — we must adapt quickly or lose ground to our rivals.",ar:"ها! القهوة هي السبب الحقيقي الذي يجعلنا جميعًا نحضر، لنكن صادقين. التضخم وتكاليف التوريد تضغط على هوامشنا — يجب أن نتكيف بسرعة أو نخسر أمام منافسينا."}]}},{stage:12,topic:"psychology",topicAr:"علم النفس والعقل",topicEn:"Psychology & Mind",topicDe:"Psychologie und Geist",emoji:"🧠",title:"جلسة مع النفس",grammar:{id:"en-b2-passive-modals",title:"Advanced passive",titleAr:"المبني للمجهول المتقدم",covers:1},conv:{id:"en-stage12-b2",speakers:["Therapist (المعالج النفسي)","Client (العميل)"],turns:[{s:0,t:"So, tell me — how have you been feeling since our last session? Take your time. Childhood experiences shape adult patterns — the psychologist explained how early attachment affects trust.",ar:"إذن، أخبرني — كيف تشعر منذ جلستنا الأخيرة؟ خذ وقتك. تجارب الطفولة تشكّل أنماط البالغين — شرح عالم النفس كيف يؤثر التعلق المبكر على الثقة."},{s:1,t:"Honestly? Up and down. Some days I feel fine, and then the anxiety just hits me out of nowhere. The mind's defenses are powerful — denial protects us briefly, but it also blocks healing.",ar:"بصراحة؟ متقلب. بعض الأيام أشعر أنني بخير، ثم يضربني القلق فجأة من العدم. دفاعات العقل قوية — الإنكار يحمينا لفترة وجيزة، لكنه يعيق الشفاء أيضًا."},{s:0,t:"That sounds exhausting. When the anxiety hits, what does it feel like — physically, I mean? Diabetes and depression often travel together — the clinic screens for both, which saves lives.",ar:"يبدو ذلك مرهقًا. عندما يضربك القلق، كيف تشعر — جسديًا، أعني؟ السكري والاكتئاب غالبًا ما يترافقان — العيادة تفحص كليهما، وهذا ينقذ الأرواح."},{s:1,t:"My chest gets tight, my heart races, and my mind just... spirals. I can't focus on anything. Your disagreement with your brother isn't failure — conflict is normal, and repair is possible.",ar:"يضيق صدري، وينبض قلبي بسرعة، وعقلي فقط... يدور في دوامة. لا أستطيع التركيز على أي شيء. خلافك مع أخيك ليس فشلًا — الصراع طبيعي، والإصلاح ممكن."},{s:0,t:"That's a very common pattern, and it's nothing to be ashamed of. Your brain is trying to protect you — it's just overdoing it. The therapist's guidance was precise — small daily practices, not grand gestures, create change.",ar:"هذا نمط شائع جدًا، وليس شيئًا تخجل منه. دماغك يحاول حمايتك — إنه فقط يبالغ في ذلك. كانت إرشادات المعالج دقيقة — ممارسات يومية صغيرة، وليست إيماءات كبيرة، تصنع التغيير."},{s:1,t:"I know that in theory. But in the moment, it feels like I'm losing control completely. Grief has no timeline — it unfolds in waves, and healing is rarely linear.",ar:"أعرف ذلك نظريًا. لكن في اللحظة نفسها، أشعر أنني أفقد السيطرة تمامًا. الحزن ليس له جدول زمني — يتكشف على موجات، والشفاء نادرًا ما يكون خطيًا."},{s:0,t:"Of course it does. Let's talk about what triggers it. Is it work? Social situations? Something else? The group session helped — hearing others' stories reduced my shame, and I felt less alone.",ar:"بالطبع يبدو كذلك. لنتحدث عما يحفزه. هل هو العمل؟ المواقف الاجتماعية؟ شيء آخر؟ ساعدت جلسة المجموعة — سماع قصص الآخرين قلّل خجلي، وشعرت بأنني أقل وحدة."},{s:1,t:"Mostly work, I think. Deadlines, meetings, the fear of messing up in front of everyone. It's relentless. Chronic stress harms the body — headaches, tension, exhaustion — the signals are everywhere.",ar:"معظمه العمل، أعتقد. المواعيد النهائية والاجتماعات والخوف من ارتكاب خطأ أمام الجميع. إنه لا يرحم. الضغط المزمن يضر الجسد — صداع وتوتر وإرهاق — الإشارات في كل مكان."},{s:0,t:"I see. And how's your sleep been? Poor sleep and anxiety tend to feed each other. The study links loneliness to poor health — the findings are stark, and the implications are serious.",ar:"أرى. وكيف كان نومك؟ النوم السيئ والقلق يميلان إلى تغذية بعضهما البعض. الدراسة تربط الوحدة بسوء الصحة — النتائج صارخة، والتداعيات خطيرة."},{s:1,t:"Terrible, honestly. I lie awake for hours, replaying conversations in my head. Then I'm exhausted the next day. The clinic's waiting list is months long — demand is high, and the system is under strain.",ar:"فظيع، بصراحة. أستلقي مستيقظًا لساعات، أعيد المحادثات في رأسي. ثم أكون منهكًا في اليوم التالي. قائمة انتظار العيادة تمتد لشهور — الطلب مرتفع، والنظام تحت الضغط."},{s:0,t:"That cycle is brutal. But it can be broken. Have you tried the breathing exercise we practiced last time? The teenager's anxiety spiked before exams — her parents sought help promptly, and the pressure eased.",ar:"هذه الدورة قاسية. لكن يمكن كسرها. هل جربت تمرين التنفس الذي تدربنا عليه في المرة الماضية؟ ارتفع قلق المراهقة قبل الامتحانات — طلب والداها المساعدة فورًا، وخف الضغط."},{s:1,t:"I did, a few times. It helped a little, but I keep forgetting to use it when I actually need it. The veteran's nightmares faded with treatment — the memories remain, but they no longer dominate his nights.",ar:"فعلت، عدة مرات. ساعد قليلًا، لكني أستمر في نسيان استخدامه عندما أحتاجه فعلًا. تلاشت كوابيس المحارب القديم مع العلاج — الذكريات باقية، لكنها لم تعد تهيمن على لياليه."},{s:0,t:"That's normal — new habits take time. What if we link it to something you already do, like your morning coffee? The couple's counseling saved the marriage — honest talks, not blame, rebuilt the trust.",ar:"هذا طبيعي — العادات الجديدة تستغرق وقتًا. ماذا لو ربطناه بشيء تفعله بالفعل، مثل قهوة الصباح؟ أنقذت استشارة الزوجين الزواج — أحاديث صادقة، وليس اللوم، أعادت بناء الثقة."},{s:1,t:"Hmm, that might work. Coffee, then breathing, then the day starts. I could try that. The widow's grief was immense — the sympathy of friends carried her through the darkest months.",ar:"همم، قد ينجح ذلك. قهوة، ثم تنفس، ثم يبدأ اليوم. يمكنني تجربة ذلك. كان حزن الأرملة هائلًا — تعاطف الأصدقاء حملها عبر أحلك الشهور."},{s:0,t:"Great. Now, I wanna ask about something else — your mood overall. Have you felt down or depressed lately?",ar:"رائع. الآن، أريد أن أسأل عن شيء آخر — مزاجك بشكل عام. هل شعرت بالحزن أو الاكتئاب مؤخرًا؟"},{s:1,t:"A bit, yeah. Not all the time, but some mornings I just don't wanna get out of bed. Everything feels heavy.",ar:"قليلًا، نعم. ليس طوال الوقت، لكن في بعض الصباحات لا أريد النهوض من السرير. كل شيء يبدو ثقيلًا."},{s:0,t:"Thank you for being honest about that. Low mood is often linked to the same patterns — and it's very treatable.",ar:"شكرًا لصدقك في ذلك. المزاج المنخفض غالبًا ما يرتبط بنفس الأنماط — وهو قابل للعلاج جدًا."},{s:1,t:"I hope so. I just feel like I'm falling behind everyone else. My friends seem to have it all figured out.",ar:"آمل ذلك. أشعر فقط أنني متخلف عن الآخرين. أصدقائي يبدون وكأنهم فهموا كل شيء."},{s:0,t:"That's a classic thought trap — comparing your behind-the-scenes to everyone else's highlight reel. It's an illusion.",ar:"هذا فخ فكري كلاسيكي — مقارنة ما وراء الكواليس لديك بأبرز لحظات الآخرين. إنه وهم."},{s:1,t:"An illusion, huh? It sure feels real. My inner critic is loud, and it never takes a day off.",ar:"وهم، هاه؟ إنه يبدو حقيقيًا بالتأكيد. ناقدي الداخلي صاخب، ولا يأخذ يوم عطلة أبدًا."},{s:0,t:"I hear you. Here's a thought — what would you say to a friend who felt exactly like you do right now?",ar:"أسمعك. إليك فكرة — ماذا ستقول لصديق يشعر تمامًا كما تشعر الآن؟"},{s:1,t:"I'd tell him he's doing his best, that he's not a failure, that it's okay to struggle. Funny how hard that is to say to myself.",ar:"سأخبره أنه يبذل قصارى جهده، وأنه ليس فاشلًا، وأنه لا بأس في المعاناة. مضحك كم يصعب قول ذلك لنفسي."},{s:0,t:"Exactly — that's self-compassion, and it's a skill, not a personality trait. It can be learned, step by step.",ar:"بالضبط — هذا هو التعاطف مع الذات، وهو مهارة وليس سمة شخصية. يمكن تعلمه، خطوة بخطوة."},{s:1,t:"Okay, I'll try. But—",ar:"حسنًا، سأحاول. لكن—"},{s:0,t:"—But what? Go on, there's no wrong answer here.",ar:"—لكن ماذا؟ تابع، لا توجد إجابة خاطئة هنا."},{s:1,t:"But what if it doesn't work? What if I'm just... broken? I've felt this way for years.",ar:"لكن ماذا لو لم ينجح؟ ماذا لو كنت فقط... مكسورًا؟ أشعر بهذه الطريقة منذ سنوات."},{s:0,t:"You're not broken. You're a person whose mind learned certain patterns to survive stress — and patterns can be unlearned.",ar:"أنت لست مكسورًا. أنت شخص تعلم عقله أنماطًا معينة للنجاة من الضغط — ويمكن إلغاء تعلم الأنماط."},{s:1,t:"When you put it that way, it sounds almost... hopeful. I haven't felt hopeful in a while.",ar:"عندما تضعها بهذه الطريقة، تبدو... مفعمة بالأمل تقريبًا. لم أشعر بالأمل منذ فترة."},{s:0,t:"Hold on to that feeling. Hope is a powerful thing. Now, let's set one small, realistic goal for this week.",ar:"تمسك بهذا الشعور. الأمل شيء قوي. الآن، لنضع هدفًا صغيرًا وواقعيًا لهذا الأسبوع."},{s:1,t:"One small goal... maybe a short walk every evening? Even ten minutes. It usually clears my head.",ar:"هدف صغير واحد... ربما مشية قصيرة كل مساء؟ حتى عشر دقائق. عادة ما تصفي ذهني."},{s:0,t:"Perfect — that's concrete, doable, and good for both body and mind. How does that sound?",ar:"مثالي — هذا ملموس وقابل للتنفيذ وجيد للجسد والعقل معًا. كيف يبدو ذلك؟"},{s:1,t:"It sounds... manageable. I can do ten minutes. I think I can, anyway.",ar:"يبدو... قابلًا للتدبير. أستطيع فعل عشر دقائق. أعتقد أنني أستطيع، على أي حال."},{s:0,t:"That's the spirit. And if you miss a day, that's fine — no guilt, no punishment. Just pick it up the next day.",ar:"هذه هي الروح. وإذا فاتك يوم، فلا بأس — بلا ذنب وبلا عقاب. فقط استأنف في اليوم التالي."},{s:1,t:"No guilt, huh? That's gonna be the hardest part. I'm an expert at beating myself up.",ar:"بلا ذنب، هاه؟ سيكون هذا أصعب جزء. أنا خبير في جلد نفسي."},{s:0,t:"I know — and that's exactly why we're working on it. Beating yourself up has never helped anyone feel better.",ar:"أعلم — وهذا بالضبط سبب عملنا عليه. جلد الذات لم يساعد أحدًا على الشعور بتحسن أبدًا."},{s:1,t:"You're right. I mean, I know you're right. It's just... hard to believe it sometimes.",ar:"أنت محق. أعني، أعلم أنك محق. إنه فقط... يصعب تصديقه أحيانًا."},{s:0,t:"Belief comes after practice, not before. You act first, and the feeling follows. Trust the process.",ar:"الإيمان يأتي بعد الممارسة، وليس قبلها. تتصرف أولًا، ويتبعك الشعور. ثق بالعملية."},{s:1,t:"Trust the process. Okay, I'll write that on my mirror or something.",ar:"ثق بالعملية. حسنًا، سأكتب ذلك على مرآتي أو شيء من هذا القبيل."},{s:0,t:"Ha! Whatever works. Same time next week? And bring your notes on the breathing exercise.",ar:"ها! مهما كان ما ينجح. نفس الوقت الأسبوع المقبل؟ وأحضر ملاحظاتك عن تمرين التنفس."},{s:1,t:"Deal. Thanks, doc — I mean it. I feel a bit lighter already.",ar:"اتفقنا. شكرًا يا دكتور — أعني ذلك. أشعر بخفة قليلًا بالفعل."},{s:0,t:"That's wonderful to hear. Remember — progress isn't a straight line. Ups and downs are part of it.",ar:"هذا رائع سماعه. تذكر — التقدم ليس خطًا مستقيمًا. الصعود والهبوط جزء منه."},{s:1,t:"I'll remember. See you next week — and I'll try the walk tonight, I promise.",ar:"سأتذكر. أراك الأسبوع المقبل — وسأجرب المشي الليلة، أعدك."},{s:0,t:"I'm holding you to that promise. Take care of yourself this week.",ar:"سأحاسبك على هذا الوعد. اعتنِ بنفسك هذا الأسبوع."},{s:1,t:"You too. Thanks again — really.",ar:"وأنت أيضًا. شكرًا مجددًا — حقًا."},{s:0,t:"Before we wrap up, I wanna ask about your relationships. How are things with your family these days?",ar:"قبل أن ننهي، أريد أن أسأل عن علاقاتك. كيف الأمور مع عائلتك هذه الأيام؟"},{s:1,t:"Complicated, honestly. My parents mean well, but they don't really understand what I'm going through. It creates tension.",ar:"معقدة، بصراحة. والداي يعنيان الخير، لكنهما لا يفهمان حقًا ما أمر به. هذا يخلق توترًا."},{s:0,t:"That's very common, and painful. Have you ever tried explaining it to them — not the details, just how it feels?",ar:"هذا شائع جدًا ومؤلم. هل حاولت يومًا شرحه لهما — ليس التفاصيل، فقط كيف تشعر؟"},{s:1,t:"I tried once, but I froze up. I was afraid they'd judge me, or think I'm weak. So I just said I was fine.",ar:"حاولت مرة، لكني تجمدت. كنت خائفًا من أن يحكموا عليّ، أو يظنوا أنني ضعيف. فقلت فقط إنني بخير."},{s:0,t:"Saying 'I'm fine' when you're not — that's the heaviest mask to wear. It takes real courage to take it off.",ar:"قول «أنا بخير» عندما لست كذلك — هذا أثقل قناع يمكن ارتداؤه. يتطلب شجاعة حقيقية لخلعه."},{s:1,t:"Yeah... maybe I'll try again, slowly. A small honest conversation, not a big dramatic reveal.",ar:"نعم... ربما سأحاول مجددًا، ببطء. محادثة صادقة صغيرة، وليست كشفًا دراميًا كبيرًا."},{s:0,t:"That's a wise plan. Small steps, consistently — that's how real change happens. Not overnight, but steadily.",ar:"هذه خطة حكيمة. خطوات صغيرة باستمرار — هكذا يحدث التغيير الحقيقي. ليس بين ليلة وضحاها، بل بثبات."},{s:1,t:"Steadily. Okay. You know, I used to think therapy was only for people in crisis. Now I see it differently. Depression often hides behind a smile — the stigma keeps people silent, and silence makes it worse.",ar:"بثبات. حسنًا. تعلم، كنت أظن أن العلاج مخصص فقط لمن في أزمة. الآن أراه بشكل مختلف. الاكتئاب غالبًا ما يختبئ خلف ابتسامة — الوصمة تبقي الناس صامتين، والصمت يجعل الأمر أسوأ."},{s:0,t:"How do you see it now? Therapy works gradually — each session builds insight, and insight slowly changes behavior.",ar:"كيف تراه الآن؟ العلاج يعمل تدريجيًا — كل جلسة تبني بصيرة، والبصيرة تغيّر السلوك ببطء."},{s:1,t:"Like maintenance for the mind — like going to the gym, but for your thoughts. Prevention, not just repair. Your perception of failure is distorted — the evidence shows progress, even when your mind denies it.",ar:"مثل الصيانة للعقل — مثل الذهاب إلى صالة الألعاب الرياضية، لكن لأفكارك. وقاية، وليس إصلاحًا فقط. تصورك للفشل مشوّه — الأدلة تُظهر تقدمًا، حتى عندما ينكره عقلك."},{s:0,t:"That's a beautiful way to put it. And honestly, it's one of the healthiest perspectives I've heard in a while. Anxiety and low mood feed each other — breaking the cycle takes patience, not willpower alone.",ar:"هذه طريقة جميلة للتعبير عنها. وبصراحة، إنها واحدة من أصح وجهات النظر التي سمعتها منذ فترة. القلق والمزاج المنخفض يغذيان بعضهما — كسر الدورة يتطلب صبرًا، وليس قوة إرادة فقط."},{s:1,t:"Thanks. I mean, I still have bad days — but now I understand them better. They don't scare me as much. Self-compassion is a skill — practice it daily, and the inner critic gradually loses its power.",ar:"شكرًا. أعني، ما زلت أمر بأيام سيئة — لكنني الآن أفهمها بشكل أفضل. إنها لا تخيفني كثيرًا. التعاطف مع الذات مهارة — مارسها يوميًا، وسيفقد الناقد الداخلي قوته تدريجيًا."},{s:0,t:"Understanding takes away fear's power. That's genuine progress — be proud of it, truly. Disability, illness, loss — life's burdens weigh differently on everyone, and comparison helps no one.",ar:"الفهم يسلب الخوف قوته. هذا تقدم حقيقي — افتخر به، حقًا. الإعاقة والمرض والفقدان — أعباء الحياة تثقل على الجميع بشكل مختلف، والمقارنة لا تساعد أحدًا."},{s:1,t:"I am, a little. Okay, same time next week — and I'll actually do the breathing exercise this time, I promise. Sleep, exercise, connection — the foundations of well-being are simple, though rarely easy.",ar:"أنا فخور، قليلًا. حسنًا، نفس الوقت الأسبوع المقبل — وسأقوم فعلًا بتمرين التنفس هذه المرة، أعدك. النوم والتمارين والتواصل — أسس العافية بسيطة، رغم أنها نادرًا ما تكون سهلة."},{s:0,t:"I'll hold you to it. Take care — and remember, you're doing better than you think. You deserve support — seeking help is strength, not weakness, whatever the old stories told you.",ar:"سأحاسبك على ذلك. اعتنِ بنفسك — وتذكر، أنت تؤدي أفضل مما تظن. أنت تستحق الدعم — طلب المساعدة قوة وليس ضعفًا، مهما قالت لك القصص القديمة."}]}},{stage:13,topic:"education",topicAr:"التعليم والدراسة",topicEn:"Education & Study",topicDe:"Bildung und Studium",emoji:"🎓",title:"منحة دراسية صعبة",grammar:{id:"en-b2-participle-clauses",title:"Participle clauses",titleAr:"جمل اسم الفاعل واسم المفعول",covers:1},conv:{id:"en-stage13-b2",speakers:["Professor (الأستاذ)","Student (الطالب)"],turns:[{s:0,t:"Come in, come in. I read your scholarship application last night — quite impressive, I must say. Think critically about every claim — evidence first, opinion second.",ar:"تفضل، تفضل. قرأت طلب المنحة الدراسية الخاص بك الليلة الماضية — مثير للإعجاب حقًا، يجب أن أقول. فكّر بشكل نقدي في كل ادعاء — الأدلة أولًا، والرأي ثانيًا."},{s:1,t:"Thank you, professor! That means a lot. I worked on it for weeks, honestly. The formation of study groups helps — shared notes, shared stress, shared success.",ar:"شكرًا يا أستاذ! هذا يعني الكثير. عملت عليه لأسابيع، بصراحة. تكوين مجموعات دراسية يساعد — ملاحظات مشتركة وضغط مشترك ونجاح مشترك."},{s:0,t:"It shows. Your essay was well-structured, and your research proposal was genuinely original. But I have a few questions. The university's reputation attracts applicants annually — thousands compete for a few hundred places.",ar:"هذا واضح. كان مقالك منظمًا جيدًا، ومقترحك البحثي أصلي حقًا. لكن لدي بعض الأسئلة. سمعة الجامعة تجذب المتقدمين سنويًا — آلاف يتنافسون على بضع مئات من الأماكن."},{s:1,t:"Of course — fire away. I'm a bit nervous, but I'm ready. Your argument lacks evidence — cite the research, or the claim collapses under scrutiny.",ar:"بالطبع — تفضل بالأسئلة. أنا متوتر قليلًا، لكني مستعد. حجتك تفتقر إلى الأدلة — استشهد بالبحث، وإلا ستنهار المزاعم تحت التدقيق."},{s:0,t:"Good. First, your proposal focuses on urban education — why that topic? What drew you to it? The philosophy department hosts debates weekly — logic, ethics, and the occasional shouting match.",ar:"جيد. أولًا، مقترحك يركز على التعليم الحضري — لماذا هذا الموضوع؟ ما الذي جذبك إليه؟ قسم الفلسفة يستضيف مناظرات أسبوعيًا — المنطق والأخلاقيات ومشاجرة صاخبة عرضية."},{s:1,t:"Well, having grown up in a crowded city neighborhood, I saw firsthand how unequal schools can be. It stuck with me. The conventional structure is introduction, argument, conclusion — master it, then bend it.",ar:"حسنًا، بعد أن نشأت في حي مزدحم بالمدينة، رأيت بنفسي كم يمكن أن تكون المدارس غير متساوية. وقد علق ذلك في ذهني. الهيكل التقليدي هو المقدمة والحجة والخاتمة — أتقنه، ثم اطوِعه."},{s:0,t:"That's a strong motivation — personal experience, turned into research. The committee loves that. Now, what about your methodology? The exchange student's perspective enriched the class — different systems, different assumptions, fresh eyes.",ar:"هذا دافع قوي — تجربة شخصية تحولت إلى بحث. اللجنة تحب ذلك. الآن، ماذا عن منهجيتك؟ منظور طالب التبادل أثرى الصف — أنظمة مختلفة وافتراضات مختلفة وعيون جديدة."},{s:1,t:"I plan to combine surveys with interviews — quantitative data, backed up by real stories from teachers and parents. Research funding is competitive — the grant committee rewards originality, not safe repetition.",ar:"أخطط للجمع بين الاستبيانات والمقابلات — بيانات كمية مدعومة بقصص حقيقية من المعلمين والأهل. تمويل البحث تنافسي — لجنة المنح تكافئ الأصالة، وليس التكرار الآمن."},{s:0,t:"A mixed approach — smart. But it's ambitious. Collecting that much data in one semester will be challenging. The campus library stays open late — students camp there before finals, armed with coffee and notes.",ar:"نهج مختلط — ذكي. لكنه طموح. جمع هذا القدر من البيانات في فصل دراسي واحد سيكون صعبًا. مكتبة الحرم الجامعي تبقى مفتوحة حتى وقت متأخر — الطلاب يعسكرون هناك قبل الامتحانات النهائية، مسلحين بالقهوة والملاحظات."},{s:1,t:"I know, I know. My advisor warned me about that too. But I'd rather aim high and adjust than play it safe. The doctoral program is grueling — years of research, and a defense before a panel of experts.",ar:"أعلم، أعلم. مشرفي حذرني من ذلك أيضًا. لكني أفضل أن أطمح عاليًا وأعدّل بدلًا من اللعب بأمان. برنامج الدكتوراه مرهق — سنوات من البحث، ودفاع أمام لجنة من الخبراء."},{s:0,t:"Fair enough — ambition is good, as long as it's realistic. Have you considered a pilot study first? The course load is heavy — the readings pile up fast, and the deadlines never pause.",ar:"عادل بما فيه الكفاية — الطموح جيد، طالما أنه واقعي. هل فكرت في دراسة تجريبية أولًا؟ عبء المقررات ثقيل — القراءات تتراكم بسرعة، والمواعيد النهائية لا تتوقف أبدًا."},{s:1,t:"A pilot study... that's actually a great idea. I could test the survey on a small group before rolling it out. The research grant was generous — the team purchased new equipment and hired two assistants.",ar:"دراسة تجريبية... هذه فكرة رائعة فعلًا. يمكنني اختبار الاستبيان على مجموعة صغيرة قبل إطلاقه. كانت منحة البحث سخية — اشترى الفريق معدات جديدة ووظف مساعدين اثنين."},{s:0,t:"Exactly. Speaking of the survey — your questions need work. Some are leading, and a few are confusing. The dean's announcement stunned everyone — fees rise again, and the protesters gathered within hours.",ar:"بالضبط. وبالحديث عن الاستبيان — أسئلتك تحتاج إلى عمل. بعضها موجِّه، وبعضها مربك. أذهل إعلان العميد الجميع — الرسوم ترتفع مجددًا، وتجمع المحتجون خلال ساعات."},{s:1,t:"Ouch, okay. I thought they were clear, but I guess when you're too close to your own work, you miss things. The graduation ceremony was emotional — the speeches, the applause, the pride in every parent's eyes.",ar:"آه، حسنًا. ظننت أنها واضحة، لكن أعتقد أنك عندما تكون قريبًا جدًا من عملك، تفوتك أشياء. كان حفل التخرج مؤثرًا — الخطب والتصفيق والفخر في عيون كل والد."},{s:0,t:"That's precisely why we have peer review. Bring a revised draft to the faculty seminar next week — you'll get honest feedback.",ar:"لهذا السبب بالتحديد لدينا مراجعة الأقران. أحضر مسودة منقحة إلى ندوة الكلية الأسبوع المقبل — ستحصل على ملاحظات صادقة."},{s:1,t:"The faculty seminar? In front of all the professors? That's terrifying — but also kind of exciting.",ar:"ندوة الكلية؟ أمام كل الأساتذة؟ هذا مرعب — لكنه مثير نوعًا ما أيضًا."},{s:0,t:"Ha! You'll survive. Everyone's been through it. And frankly, presenting early makes your final work much stronger.",ar:"ها! ستنجو. الجميع مر بذلك. وبصراحة، العرض المبكر يجعل عملك النهائي أقوى بكثير."},{s:1,t:"I'll take your word for it. So, about the scholarship itself — when will the decision be made?",ar:"سأصدق كلامك. إذن، بخصوص المنحة نفسها — متى سيتم اتخاذ القرار؟"},{s:0,t:"The committee meets in two weeks. Your grades are excellent, your proposal is solid — I'd say your chances are genuinely promising.",ar:"تجتمع اللجنة خلال أسبوعين. درجاتك ممتازة، ومقترحك قوي — أقول إن فرصك واعدة حقًا."},{s:1,t:"That's a relief to hear. If I get it, I can finally quit my part-time job and focus on the research full-time.",ar:"هذا مريح سماعه. إذا حصلت عليها، أستطيع أخيرًا ترك وظيفتي بدوام جزئي والتركيز على البحث بدوام كامل."},{s:0,t:"That would make a real difference. Juggling work and study is exhausting — I've seen too many bright students burn out that way.",ar:"سيحدث ذلك فرقًا حقيقيًا. الموازنة بين العمل والدراسة مرهقة — رأيت طلابًا أذكياء كثيرين يحترقون بهذه الطريقة."},{s:1,t:"Tell me about it. Last semester I was working nights and studying days. I barely slept for a month.",ar:"حدثني عن ذلك. في الفصل الماضي كنت أعمل ليلًا وأدرس نهارًا. بالكاد نمت لمدة شهر."},{s:0,t:"That explains the dip in your grades last spring — I was wondering about that. No judgment, just context.",ar:"هذا يفسر انخفاض درجاتك في الربيع الماضي — كنت أتساءل عن ذلك. لا حكم، فقط سياق."},{s:1,t:"Yeah, that was a rough patch. But I bounced back, and my grades this semester are the best I've ever had.",ar:"نعم، كانت فترة صعبة. لكني تعافيت، ودرجاتي هذا الفصل هي الأفضل على الإطلاق."},{s:0,t:"I noticed — and so will the committee. Resilience counts for a lot in academia, believe me.",ar:"لاحظت ذلك — وستلاحظه اللجنة أيضًا. المرونة مهمة جدًا في الأوساط الأكاديمية، صدقني."},{s:1,t:"Thanks, professor. That really means a lot. Is there anything else I should fix before I submit the final version?",ar:"شكرًا يا أستاذ. هذا يعني الكثير حقًا. هل هناك شيء آخر يجب أن أصلحه قبل تقديم النسخة النهائية؟"},{s:0,t:"One thing — your bibliography. A few citations are incomplete, and the formatting is inconsistent. Clean that up.",ar:"شيء واحد — قائمة مراجعك. بعض الاستشهادات غير مكتملة، والتنسيق غير متسق. نظّف ذلك."},{s:1,t:"Ugh, citations — my least favorite part. But you're right, I'll fix them tonight.",ar:"أوف، الاستشهادات — الجزء الأقل تفضيلًا لدي. لكنك محق، سأصلحها الليلة."},{s:0,t:"Good. And listen — whatever the outcome, this proposal is strong work. You should be proud of it.",ar:"جيد. واسمع — مهما كانت النتيجة، هذا المقترح عمل قوي. يجب أن تفخر به."},{s:1,t:"I am, honestly. Even getting this far feels like an accomplishment.",ar:"أنا فخور، بصراحة. حتى الوصول إلى هنا يبدو إنجازًا."},{s:0,t:"It is. Now —",ar:"إنه كذلك. الآن —"},{s:1,t:"—Now what? Don't tell me there's another form to fill out.",ar:"—الآن ماذا؟ لا تخبرني أن هناك نموذجًا آخر يجب ملؤه."},{s:0,t:"Ha! No more forms, I promise. I just wanted to say — the department is lucky to have students like you.",ar:"ها! لا مزيد من النماذج، أعدك. أردت فقط أن أقول — القسم محظوظ بوجود طلاب مثلك."},{s:1,t:"Wow. Thank you — I don't even know what to say.",ar:"واو. شكرًا — لا أعرف حتى ماذا أقول."},{s:0,t:"You don't need to say anything. Just keep doing the work — and send me that revised draft by Monday.",ar:"لا تحتاج لقول أي شيء. فقط واصل العمل — وأرسل لي تلك المسودة المنقحة بحلول الاثنين."},{s:1,t:"Monday, got it. I'll have it in your inbox by Sunday night, hopefully.",ar:"الاثنين، فهمت. ستكون في بريدك بحلول ليلة الأحد، آمل ذلك."},{s:0,t:"Sunday night works. And hey — try to get some sleep this weekend. You've earned it.",ar:"ليلة الأحد تناسبني. وهيّا — حاول أن تنام قليلًا في عطلة نهاية الأسبوع هذه. لقد استحققت ذلك."},{s:1,t:"I'll try, I promise. Thanks again, professor — for everything.",ar:"سأحاول، أعدك. شكرًا مجددًا يا أستاذ — على كل شيء."},{s:0,t:"Anytime. Now go — and good luck with the seminar. You're gonna do great.",ar:"في أي وقت. الآن اذهب — وحظًا سعيدًا في الندوة. ستؤدي بشكل رائع."},{s:1,t:"Thanks! I'll make you proud — or at least, I'll try not to faint on stage.",ar:"شكرًا! سأجعلك فخورًا — أو على الأقل، سأحاول ألا أُغمى عليّ على المسرح."},{s:0,t:"Ha! Fainting is not recommended. Break a leg — figuratively, of course.",ar:"ها! الإغماء غير موصى به. بالتوفيق — مجازيًا، بالطبع."},{s:1,t:"I'll take it. See you Monday, professor!",ar:"سأقبل ذلك. أراك يوم الاثنين يا أستاذ!"},{s:0,t:"See you Monday. And remember — having revised the draft, you'll feel much more confident.",ar:"أراك يوم الاثنين. وتذكر — بعد مراجعة المسودة، ستشعر بثقة أكبر بكثير."},{s:1,t:"Noted! Bye, professor!",ar:"ملاحظ! وداعًا يا أستاذ!"},{s:0,t:"One more thing — the university library just acquired a rare collection of historical manuscripts. You should check it out.",ar:"شيء آخر — مكتبة الجامعة اقتنت للتو مجموعة نادرة من المخطوطات التاريخية. يجب أن تلقي نظرة عليها."},{s:1,t:"Manuscripts? That sounds fascinating. My research touches on that era, actually — it could be a goldmine.",ar:"مخطوطات؟ هذا يبدو رائعًا. بحثي يتطرق إلى تلك الحقبة، في الواقع — قد يكون منجم ذهب."},{s:0,t:"Exactly why I mentioned it. The historian in charge is brilliant — ask for her, and mention my name.",ar:"لهذا السبب بالتحديد ذكرته. المؤرخة المسؤولة رائعة — اسأل عنها، واذكر اسمي."},{s:1,t:"Will do! Oh, and professor — I wanted to ask about the exchange program. Is it too late to apply?",ar:"سأفعل! أوه، مع أستاذ — أردت أن أسأل عن برنامج التبادل. هل فات الأوان للتقديم؟"},{s:0,t:"The deadline is Friday, so hurry. A semester abroad would transform your perspective — and your research.",ar:"الموعد النهائي يوم الجمعة، لذا أسرع. فصل دراسي في الخارج سيحوّل وجهة نظرك — وبحثك."},{s:1,t:"Transform, huh? That's a big word. But yeah, I've always wanted to study overseas — new culture, new ideas.",ar:"يحوّل، هاه؟ هذه كلمة كبيرة. لكن نعم، لطالما أردت الدراسة في الخارج — ثقافة جديدة وأفكار جديدة."},{s:0,t:"It broadens the mind like nothing else. My own semester abroad shaped my entire career — I wouldn't be here without it.",ar:"إنه يوسّع العقل كما لا يفعل أي شيء آخر. فصلي الدراسي في الخارج شكّل مسيرتي المهنية كلها — لما كنت هنا بدونه."},{s:1,t:"Wow, really? Okay, I'm applying tonight. What's the worst that could happen — they say no? The assessment criteria are strict — cite your sources properly, or the markers will penalize you.",ar:"واو، حقًا؟ حسنًا، سأقدم الليلة. ما أسوأ ما يمكن أن يحدث — يقولون لا؟ معايير التقييم صارمة — استشهد بمصادرك بشكل صحيح، وإلا سيعاقبك المصححون."},{s:0,t:"Exactly. And if they say yes, you'll have the experience of a lifetime. No downside, really. Your thesis needs a clear hypothesis — test it rigorously, and let the evidence speak.",ar:"بالضبط. وإذا قالوا نعم، فستحصل على تجربة العمر. لا جانب سلبي، حقًا. أطروحتك تحتاج إلى فرضية واضحة — اختبرها بدقة، ودع الأدلة تتحدث."},{s:1,t:"You're right. Uh-huh, okay — application tonight, revised draft Sunday, seminar next week. Busy week ahead! Academic integrity matters — plagiarism ends careers, so always acknowledge your sources.",ar:"أنت محق. أها، حسنًا — الطلب الليلة، والمسودة المنقحة الأحد، والندوة الأسبوع المقبل. أسبوع مزدحم قادم! النزاهة الأكاديمية مهمة — السرقة الأدبية تنهي المسيرات المهنية، لذا اذكر مصادرك دائمًا."},{s:0,t:"Busy, but exciting. That's what university is for — stretching yourself, not coasting. The faculty expects independent research — assign yourself deadlines and honor them.",ar:"مزدحم، لكنه مثير. هذا ما الجامعة من أجله — أن تمد نفسك، لا أن تنساب. الكلية تتوقع بحثًا مستقلًا — حدد لنفسك مواعيد نهائية والتزم بها."},{s:1,t:"Stretching myself — I like that. Alright, professor, I'm off to the library. Wish me luck! A scholarship transforms lives — it grants freedom to study without the burden of debt.",ar:"أمد نفسي — يعجبني ذلك. حسنًا يا أستاذ، أنا ذاهب إلى المكتبة. تمنَّ لي الحظ! المنحة الدراسية تحوّل الحياة — إنها تمنح حرية الدراسة دون عبء الديون."},{s:0,t:"Good luck — though with your work ethic, you won't need much of it. University broadens horizons — you encounter ideas that challenge every assumption you arrived with.",ar:"حظًا سعيدًا — رغم أنك مع أخلاقيات عملك، لن تحتاج إلى الكثير منه. الجامعة توسع الآفاق — تواجه أفكارًا تتحدى كل افتراض وصلت به."},{s:1,t:"Thanks! That means the world to me. See you Monday! The library's archives hold centuries of wisdom — a treasure for any curious researcher.",ar:"شكرًا! هذا يعني لي الكثير. أراك يوم الاثنين! أرشيف المكتبة يحمل قرونًا من الحكمة — كنز لأي باحث فضولي."},{s:0,t:"See you Monday. And don't forget — the library closes at ten! Graduation feels distant now — but steadily, semester by semester, you'll get there.",ar:"أراك يوم الاثنين. ولا تنسَ — المكتبة تغلق في العاشرة! التخرج يبدو بعيدًا الآن — لكن بثبات، فصلًا بعد فصل، ستصل إلى هناك."}]}},{stage:14,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"ماراثون المدينة",grammar:{id:"en-b2-reported-speech-tense-shifts",title:"Advanced reported speech",titleAr:"الكلام المنقول المتقدم",covers:1},conv:{id:"en-stage14-b2",speakers:["Coach (المدرب)","Player (اللاعب)"],turns:[{s:0,t:"Alright, listen up! The city marathon is in six weeks, and I need to know — are you in, or are you out? The defender blocked the shot brilliantly — the crowd erupted, and the stadium shook.",ar:"حسنًا، اسمعوا! ماراثون المدينة بعد ستة أسابيع، وأحتاج أن أعرف — هل أنت معنا أم خارج؟ أوقف المدافع التسديدة ببراعة — انفجر الجمهور، واهتز الملعب."},{s:1,t:"I'm in, coach — a hundred percent. I've been training for this since January. The coach enforces the rules strictly — no exceptions, no favorites.",ar:"أنا معكم يا مدرب — مئة بالمئة. أتدرب لهذا منذ يناير. يفرض المدرب القواعد بصرامة — بلا استثناءات وبلا محاباة."},{s:0,t:"Good, that's what I wanna hear. But I gotta be honest — your long runs are still too slow. You're fading after mile twenty. The team's unity is its strength — they celebrate together and suffer together.",ar:"جيد، هذا لا أريد سماعه. لكن يجب أن أكون صادقًا — جولاتك الطويلة ما زالت بطيئة جدًا. تتلاشى بعد الميل العشرين. وحدة الفريق هي قوته — يحتفلون معًا ويعانون معًا."},{s:1,t:"I know, I know. My legs just give out. It's like I hit a wall and everything shuts down. The referee's decision was controversial — half the stadium cheered, half booed.",ar:"أعلم، أعلم. ساقاي فقط تستسلمان. كأنني أصطدم بجدار وكل شيء يتوقف. كان قرار الحكم مثيرًا للجدل — نصف الملعب هتف، والنصف الآخر أطلق صيحات الاستهجان."},{s:0,t:"That's the wall every marathoner hits. The trick is training your body to push through it — and your mind too. The fans are passionate — win or lose, they sing until the final whistle.",ar:"هذا هو الجدار الذي يصطدم به كل عداء ماراثون. الحيلة هي تدريب جسدك على تجاوزه — وعقلك أيضًا. المشجعون شغوفون — فوزًا أو خسارة، يغنون حتى صافرة النهاية."},{s:1,t:"So what's the plan? More miles? Different workouts? The coach paused the drill — 'Breathe,' he said, 'the game is won in the mind first.'",ar:"إذن ما الخطة؟ أميال أكثر؟ تمارين مختلفة؟ أوقف المدرب التدريب — «تنفس»، قال، «المباراة تُكسب في العقل أولًا»."},{s:0,t:"Both, but smart. We'll add one long run a week, gradually — no jumping from fifteen miles to twenty-five overnight. The player was severely injured — he'll miss the season, and the team must adapt.",ar:"كلاهما، لكن بذكاء. سنضيف جولة طويلة واحدة أسبوعيًا، تدريجيًا — بلا قفز من خمسة عشر ميلًا إلى خمسة وعشرين بين ليلة وضحاها. أصيب اللاعب بجروح خطيرة — سيغيب عن الموسم، ويجب على الفريق التكيف."},{s:1,t:"Gradually — got it. And nutrition? I've been reading about carb-loading, but honestly, it's confusing. The legs scream for rest, but the will decides the finish.",ar:"تدريجيًا — فهمت. والتغذية؟ كنت أقرأ عن تحميل الكربوهيدرات، لكن بصراحة، إنه مربك. الساقان تصرخان طلبًا للراحة، لكن الإرادة تقرر النهاية."},{s:0,t:"Keep it simple. Eat well all week, hydrate properly, and the night before the race, have a solid pasta dinner. That's it. The stadium's capacity is eighty thousand — the atmosphere on derby day is unreal.",ar:"أبقِ الأمر بسيطًا. كُل جيدًا طوال الأسبوع، واشرب الماء بشكل صحيح، وفي الليلة السابقة للسباق، تناول عشاء معكرونة جيدًا. هذا كل شيء. سعة الملعب ثمانون ألفًا — الأجواء في يوم الديربي غير حقيقية."},{s:1,t:"Pasta dinner — now that's a plan I can get behind. What about race day itself? Any tips? The athlete's diet is strict — the nutritionist measures every portion, every day.",ar:"عشاء المعكرونة — هذه خطة تعجبني. ماذا عن يوم السباق نفسه؟ أي نصائح؟ حمية الرياضي صارمة — أخصائي التغذية يقيس كل حصة، كل يوم."},{s:0,t:"Start slow. I mean it — everyone sprints at the start, and they pay for it by mile ten. Run your own race. The championship final was dramatic — a last-minute goal, and the underdogs took the title.",ar:"ابدأ ببطء. أعني ذلك — الجميع يركض بسرعة في البداية، ويدفعون الثمن بحلول الميل العاشر. اركض سباقك الخاص. كانت المباراة النهائية للبطولة درامية — هدف في اللحظة الأخيرة، وأخذ المستضعفون اللقب."},{s:1,t:"Run my own race. Okay. And the crowd? I've heard the city marathon has massive crowds cheering. The referee's whistle ended it — the underdogs had won, and the favorites stood in shock.",ar:"اركض سباقي الخاص. حسنًا. والجمهور؟ سمعت أن ماراثون المدينة لديه حشود ضخمة تهتف. أنهت صافرة الحكم الأمر — فاز المستضعفون، ووقف المرشحون في صدمة."},{s:0,t:"Oh yeah, the crowd is incredible — thousands of people, music, signs. It'll carry you through the tough miles. The team's captain lifted the trophy — the crowd roared, and the victory felt inevitable.",ar:"أوه نعم، الجمهور مذهل — آلاف الناس والموسيقى واللافتات. سيحملك عبر الأميال الصعبة. رفع قائد الفريق الكأس — هتف الجمهور، وبدا النصر حتميًا."},{s:1,t:"I can't wait. You know, my rival from the running club said he'd beat me by ten minutes. That lit a fire under me. The marathon's route is brutal — hills, heat, and endless testing of every runner's will.",ar:"لا أستطيع الانتظار. تعلم، منافسي من نادي الجري قال إنه سيهزمني بعشر دقائق. هذا أشعل نارًا بداخلي. مسار الماراثون قاسٍ — تلال وحرارة واختبار لا نهائي لإرادة كل عداء."},{s:0,t:"He said that, did he? Well, let him talk. Talk is cheap — the road will decide who's faster.",ar:"قال ذلك، أليس كذلك؟ حسنًا، دعه يتحدث. الكلام رخيص — الطريق سيقرر من الأسرع."},{s:1,t:"Ha! He also said I didn't have the discipline for a marathon. That one stung, I won't lie.",ar:"ها! قال أيضًا إنني لا أملك الانضباط للماراثون. هذا آلمني، لن أكذب."},{s:0,t:"Use it. Let it fuel you on those cold morning runs. The best revenge is crossing that finish line ahead of him.",ar:"استخدمه. دعه يغذيك في جولات الصباح الباردة. أفضل انتقام هو عبور خط النهاية قبله."},{s:1,t:"That's the plan. So, what about the league race next weekend — should I run it, or rest?",ar:"هذه هي الخطة. إذن، ماذا عن سباق الدوري في عطلة نهاية الأسبوع المقبلة — هل أركض فيه، أم أستريح؟"},{s:0,t:"Run it, but treat it as training, not a competition. Easy pace, no sprinting at the end. Save your legs.",ar:"اركض فيه، لكن عامله كتدريب وليس منافسة. وتيرة سهلة، بلا ركض سريع في النهاية. وفّر ساقيك."},{s:1,t:"Easy pace, got it. My teammate told me he'd pace me if I wanted — is that allowed?",ar:"وتيرة سهلة، فهمت. زميلي أخبرني أنه سيضبط إيقاعي إذا أردت — هل هذا مسموح؟"},{s:0,t:"Sure, that's fine. A good pacer is worth their weight in gold. Just don't let him drag you too fast.",ar:"بالتأكيد، هذا جيد. ضابط الإيقاع الجيد يستحق وزنه ذهبًا. فقط لا تدعه يجرك بسرعة كبيرة."},{s:1,t:"Will do. Oh, and coach — my shoes are falling apart. The soles are worn through. Any recommendations?",ar:"سأفعل. أوه، مع مدرب — حذائي يتفكك. النعال مهترئة. أي توصيات؟"},{s:0,t:"Get fitted at the running store downtown — don't just buy online. The wrong shoes will wreck your knees.",ar:"احصل على مقاس مناسب في متجر الجري وسط المدينة — لا تشترِ عبر الإنترنت فقط. الحذاء الخاطئ سيدمر ركبتيك."},{s:1,t:"Good call. I learned that the hard way last year — shin splints for a month. Never again.",ar:"قرار جيد. تعلمت ذلك بالطريقة الصعبة العام الماضي — التهاب قصبة الساق لمدة شهر. لن يتكرر أبدًا."},{s:0,t:"Yeah, I remember — you were miserable. Okay, let's talk about the medal. Do you have a time goal in mind?",ar:"نعم، أتذكر — كنت بائسًا. حسنًا، لنتحدث عن الميدالية. هل لديك هدف زمني في ذهنك؟"},{s:1,t:"Under four hours. That's the dream. My personal best is four-twenty, so it's a stretch, but I think I can do it.",ar:"أقل من أربع ساعات. هذا هو الحلم. أفضل وقت شخصي لي هو أربع ساعات وعشرون دقيقة، لذا فهو تحدٍّ، لكني أعتقد أنني أستطيع."},{s:0,t:"Under four hours — ambitious, but doable. If you stick to the plan, I'd say you've got a real shot.",ar:"أقل من أربع ساعات — طموح، لكنه ممكن. إذا التزمت بالخطة، أقول إن لديك فرصة حقيقية."},{s:1,t:"That's what I needed to hear. What about the weather? Last year it was brutally hot.",ar:"هذا ما احتجت سماعه. ماذا عن الطقس؟ العام الماضي كان حارًا بوحشية."},{s:0,t:"We'll see. If it's hot, we'll adjust — more water stops, slower pace early. You adapt to the conditions, you don't fight them.",ar:"سنرى. إذا كان حارًا، سنتكيف — نقاط ماء أكثر ووتيرة أبطأ في البداية. تتكيف مع الظروف، ولا تحاربها."},{s:1,t:"Adapt — got it. You know, my dad said he'd come watch the finish. He never misses a race.",ar:"أتكيف — فهمت. تعلم، والدي قال إنه سيأتي لمشاهدة النهاية. لا يفوت سباقًا أبدًا."},{s:0,t:"That's lovely. Having family at the finish line — there's nothing like it. It'll push you through the last mile.",ar:"هذا جميل. وجود العائلة عند خط النهاية — لا شيء مثله. سيدفعك عبر الميل الأخير."},{s:1,t:"For sure. Okay, coach —",ar:"بالتأكيد. حسنًا يا مدرب —"},{s:0,t:"—Yes? Spit it out, what's on your mind?",ar:"—نعم؟ قلها، ما الذي يدور في ذهنك؟"},{s:1,t:"What if I fail? What if I don't finish? Everyone's expecting me to do well, and that pressure is... heavy.",ar:"ماذا لو فشلت؟ ماذا لو لم أُنهِ السباق؟ الجميع يتوقع مني أداءً جيدًا، وهذا الضغط... ثقيل."},{s:0,t:"Listen to me. Finishing is the victory. The medal is just metal — the real win is what you prove to yourself.",ar:"استمع إليّ. الإنهاء هو النصر. الميدالية مجرد معدن — الفوز الحقيقي هو ما تثبته لنفسك."},{s:1,t:"Wow. Okay. That's... that's actually really helpful. Thanks, coach.",ar:"واو. حسنًا. هذا... مفيد حقًا فعلًا. شكرًا يا مدرب."},{s:0,t:"Anytime. Now get out there and run — ten easy miles today, and don't forget to stretch afterward.",ar:"في أي وقت. الآن اخرج واركض — عشرة أميال سهلة اليوم، ولا تنسَ التمدد بعد ذلك."},{s:1,t:"Ten miles, stretch, pasta later. Got it. See you at practice tomorrow, coach!",ar:"عشرة أميال، تمدد، معكرونة لاحقًا. فهمت. أراك في التدريب غدًا يا مدرب!"},{s:0,t:"See you tomorrow. And hey — remember what your rival said, and make him eat his words.",ar:"أراك غدًا. وهيّا — تذكر ما قاله منافسك، واجعله يبتلع كلماته."},{s:1,t:"Oh, I will. He doesn't know what's coming. Not a clue.",ar:"أوه، سأفعل. لا يعرف ما هو قادم. لا فكرة لديه."},{s:0,t:"That's the spirit. Now go — the road is waiting.",ar:"هذه هي الروح. الآن اذهب — الطريق بانتظارك."},{s:1,t:"On my way, coach. On my way!",ar:"في طريقي يا مدرب. في طريقي!"},{s:0,t:"And don't forget your water bottle this time!",ar:"ولا تنسَ زجاجة الماء هذه المرة!"},{s:1,t:"I won't! I swear — it's already in my bag!",ar:"لن أنسى! أقسم — إنها في حقيبتي بالفعل!"},{s:0,t:"Oh, and I heard the news — the league is expanding next season. More teams, more games, bigger crowds.",ar:"أوه، وسمعت الأخبار — الدوري يتوسع الموسم المقبل. فرق أكثر ومباريات أكثر وحشود أكبر."},{s:1,t:"More teams? That's exciting! But doesn't that mean tougher competition for a spot on the team?",ar:"فرق أكثر؟ هذا مثير! لكن ألا يعني ذلك منافسة أصعب على مكان في الفريق؟"},{s:0,t:"It does — which is exactly why you need to keep improving. Complacency is the enemy of every athlete.",ar:"نعم — وهذا بالضبط سبب حاجتك إلى مواصلة التحسن. الرضا عن النفس هو عدو كل رياضي."},{s:1,t:"No complacency here, coach, I promise. I've been watching videos of the top runners, studying their technique.",ar:"لا رضا عن النفس هنا يا مدرب، أعدك. كنت أشاهد مقاطع فيديو لأفضل العدائين، وأدرس تقنيتهم."},{s:0,t:"Good — studying the best is smart. But remember, your body is different. Adapt their methods to your own strengths.",ar:"جيد — دراسة الأفضل ذكية. لكن تذكر، جسدك مختلف. كيّف أساليبهم مع نقاط قوتك الخاصة."},{s:1,t:"Adapt — right. My strength is endurance, not speed. So I should focus on the long game, not the sprint.",ar:"أتكيف — صحيح. قوتي هي التحمل، وليس السرعة. لذا يجب أن أركز على اللعبة الطويلة، وليس العدو السريع."},{s:0,t:"Exactly. Play to your strengths, and the results will follow. That's true in sports — and in life.",ar:"بالضبط. العب على نقاط قوتك، وستتبعها النتائج. هذا صحيح في الرياضة — وفي الحياة."},{s:1,t:"Wise words, coach. Uh-huh, okay — endurance focus, easy pace this week, and I'll see you at the track. The opponent's strategy was aggressive — but our defense held firm, and the crowd went wild.",ar:"كلمات حكيمة يا مدرب. أها، حسنًا — التركيز على التحمل ووتيرة سهلة هذا الأسبوع، وسأراك في المضمار. كانت استراتيجية الخصم عدوانية — لكن دفاعنا صمد، والجمهور جن جنونه."},{s:0,t:"See you there. Oh — and stretch properly this time. I saw you skipping it last week! Defeat stings, but it teaches — analyze the loss, adjust the training, and come back stronger.",ar:"أراك هناك. أوه — وتمدد بشكل صحيح هذه المرة. رأيتك تتخطاه الأسبوع الماضي! الهزيمة تؤلم، لكنها تعلّم — حلّل الخسارة، وعدّل التدريب، وعد أقوى."},{s:1,t:"Busted! Okay, okay — stretching, I promise. No shortcuts anymore. A marathon tests determination — every mile demands focus, and the final stretch is pure will.",ar:"انكشفت! حسنًا، حسنًا — التمدد، أعدك. لا اختصارات بعد الآن. الماراثون يختبر التصميم — كل ميل يتطلب تركيزًا، والامتداد الأخير إرادة خالصة."},{s:0,t:"Good. Shortcuts are how injuries happen — and we've got a marathon to win. The league's new regulations limit substitutions — consequently, fitness matters more than ever.",ar:"جيد. الاختصارات هي كيف تحدث الإصابات — ولدينا ماراثون لنفوز به. لوائح الدوري الجديدة تحد من التبديلات — وبالتالي، اللياقة مهمة أكثر من أي وقت مضى."},{s:1,t:"A marathon to win — I like the sound of that. Let's do this, coach! Sponsorship covers the kit and travel — without it, amateur athletes couldn't compete at this level.",ar:"ماراثون لنفوز به — يعجبني هذا الكلام. لنفعلها يا مدرب! الرعاية تغطي المعدات والسفر — بدونها، لا يستطيع الرياضيون الهواة المنافسة على هذا المستوى."},{s:0,t:"Let's do it. Now go warm up — the track's waiting, and so is your future medal. The medal ceremony was spectacular — flags, anthems, tears — a moment I'll never forget.",ar:"لنفعلها. الآن اذهب للإحماء — المضمار بانتظارك، وكذلك ميداليتك المستقبلية. كان حفل توزيع الميداليات مذهلًا — أعلام وأنشيد ودموع — لحظة لن أنساها أبدًا."},{s:1,t:"On it! Race you to the track — loser buys the sports drinks! Rivalries fuel the sport — respect your rival, but never fear him.",ar:"سأفعل! أسابقك إلى المضمار — الخاسر يشتري مشروبات الطاقة! المنافسات تغذي الرياضة — احترم منافسك، لكن لا تخشه أبدًا."},{s:0,t:"Ha! You're on — but remember, I'm old, not slow! The coach's feedback was precise — adjust your stride, breathe steadily, and trust the training.",ar:"ها! اتفقنا — لكن تذكر، أنا كبير في السن، ولست بطيئًا! كانت ملاحظات المدرب دقيقة — عدّل خطوتك، وتنفس بثبات، وثق بالتدريب."}]}},{stage:15,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"بيت جديد ومشاكل قديمة",grammar:{id:"en-b2-wish-if-only",title:"Wish and regret",titleAr:"التمني والندم",covers:1},conv:{id:"en-stage15-b2",speakers:["Landlord (مالك المنزل)","Tenant (المستأجر)"],turns:[{s:0,t:"Morning! Come on in. I wanted to walk through the place together before you move in next week. The landlord's inspection was thorough — he checked every tap, every socket, every window.",ar:"صباح الخير! تفضل بالدخول. أردت أن نتجول في المكان معًا قبل انتقالك الأسبوع المقبل. كان تفتيش المالك شاملًا — فحص كل صنبور وكل مقبس وكل نافذة."},{s:1,t:"Morning! Thanks for showing me around. I wish I'd seen it in daylight last time — the evening viewing didn't show much. The apartment's layout is efficient — every meter counts, and the storage is generous.",ar:"صباح الخير! شكرًا لعرضك المكان عليّ. أتمنى لو رأيته في ضوء النهار في المرة الماضية — المعاينة المسائية لم تُظهر الكثير. تصميم الشقة فعّال — كل متر مهم، والتخزين سخي."},{s:0,t:"No problem at all. Daylight makes a big difference, doesn't it? The living room gets great light in the morning. The building's foundation is solid — brick walls, new wiring, and a roof replaced last year.",ar:"لا مشكلة إطلاقًا. ضوء النهار يحدث فرقًا كبيرًا، أليس كذلك؟ غرفة المعيشة تحصل على إضاءة رائعة في الصباح. أساس المبنى صلب — جدران من الطوب وأسلاك جديدة وسقف استُبدل العام الماضي."},{s:1,t:"It does! And the kitchen is bigger than I remembered. I love the wooden floors — they give the place real character. The previous owner installed new windows — double-glazed, quiet, and warm in winter.",ar:"بالفعل! والمطبخ أكبر مما تذكرت. أحب الأرضيات الخشبية — إنها تعطي المكان طابعًا حقيقيًا. ركّب المالك السابق نوافذ جديدة — مزدوجة الزجاج وهادئة ودافئة في الشتاء."},{s:0,t:"The floors are original, from the 1920s. The previous tenants loved them too. Now, let me show you the basement. The garden's soil is rich — tomatoes, herbs, and roses all thrive here.",ar:"الأرضيات أصلية، من عشرينيات القرن الماضي. المستأجرون السابقون أحبوها أيضًا. الآن، دعني أريك القبو. تربة الحديقة غنية — الطماطم والأعشاب والورود كلها تزدهر هنا."},{s:1,t:"The basement? Is it damp down there? I need storage space, but I don't wanna ruin my books. The hallway's lighting is warm — it makes the whole place feel welcoming at night.",ar:"القبو؟ هل هو رطب هناك؟ أحتاج مساحة تخزين، لكني لا أريد إتلاف كتبي. إضاءة الممر دافئة — تجعل المكان كله يبدو مرحبًا في الليل."},{s:0,t:"It's dry, I promise — we waterproofed it two years ago. There's shelving down there, and plenty of room for boxes. The rent is due on the first — pay promptly, and the landlord will never chase you.",ar:"إنه جاف، أعدك — قمنا بعزله ضد الماء قبل عامين. توجد أرفف هناك، ومساحة واسعة للصناديق. الإيجار مستحق في الأول من الشهر — ادفع فورًا، ولن يطاردك المالك أبدًا."},{s:1,t:"Perfect. I wish the apartment upstairs had this much storage — my last place had literally one closet. The moving van arrives at eight — boxes labeled, furniture wrapped, and coffee ready.",ar:"مثالي. أتمنى لو كانت الشقة في الطابق العلوي بها هذا القدر من التخزين — مكاني الأخير كان به خزانة واحدة حرفيًا. تصل شاحنة النقل في الثامنة — صناديق موسومة وأثاث ملفوف وقهوة جاهزة."},{s:0,t:"Ha! One closet — that's brutal. Well, here you've got closets in both bedrooms, plus the hallway cupboard. The estate agent showed us three flats — the third was perfect, and we signed the next day.",ar:"ها! خزانة واحدة — هذا قاسٍ. حسنًا، هنا لديك خزائن في غرفتي النوم، إضافة إلى خزانة الممر. أرانا وكيل العقارات ثلاث شقق — الثالثة كانت مثالية، ووقّعنا في اليوم التالي."},{s:1,t:"That's a huge relief. Now, about the rent — the listing said twelve hundred a month, plus utilities, right? The property market is fierce — prices rise monthly, and young families need luck and savings.",ar:"هذا ارتياح كبير. الآن، بخصوص الإيجار — الإعلان قال ألفًا ومئتين شهريًا، إضافة إلى المرافق، صحيح؟ سوق العقارات شرس — الأسعار ترتفع شهريًا، والعائلات الشابة تحتاج إلى الحظ والمدخرات."},{s:0,t:"Right — twelve hundred, utilities separate. Water and heating are included in the building fee, electricity is on you. The landlord raised the rent again — the tenants were furious, and several threatened to leave.",ar:"صحيح — ألف ومئتان، والمرافق منفصلة. الماء والتدفئة مشمولان في رسوم المبنى، والكهرباء عليك. رفع المالك الإيجار مجددًا — كان المستأجرون غاضبين، وهدد عدة منهم بالمغادرة."},{s:1,t:"Fair enough. And the deposit — one month's rent? I wanna make sure I budget for everything upfront. The upstairs neighbor flooded the bathroom — water dripped through our ceiling, and the damage was extensive.",ar:"عادل بما فيه الكفاية. والتأمين — إيجار شهر واحد؟ أريد التأكد من أنني أضع ميزانية لكل شيء مقدمًا. أغرق جار الطابق العلوي الحمام — تسرب الماء عبر سقفنا، وكان الضرر واسعًا."},{s:0,t:"One month, yes. It goes into a protected account, and you get it back when you move out — assuming no damage, of course. The building's elevator breaks constantly — the residents climb five floors, and the complaints pile up.",ar:"شهر واحد، نعم. يذهب إلى حساب محمي، وتسترده عند انتقالك — بافتراض عدم وجود ضرر، بالطبع. مصعد المبنى يتعطل باستمرار — يتسلق السكان خمسة طوابق، والشكاوى تتراكم."},{s:1,t:"Of course, that makes sense. What about the neighbors? Are they quiet? My last building was a nightmare. The street's parking is impossible — cars circle for hours, and the fines are steep.",ar:"بالطبع، هذا منطقي. ماذا عن الجيران؟ هل هم هادئون؟ مبناي الأخير كان كابوسًا. مواقف الشارع مستحيلة — السيارات تدور لساعات، والغرامات باهظة."},{s:0,t:"The neighbors here are lovely — mostly families and a retired couple upstairs. It's a peaceful building, honestly.",ar:"الجيران هنا لطيفون — معظمهم عائلات وزوجان متقاعدان في الطابق العلوي. إنه مبنى هادئ، بصراحة."},{s:1,t:"Music to my ears. My last neighbor practiced drums at midnight. I regret not moving out sooner, truly.",ar:"يسعدني سماع ذلك. جاري الأخير كان يتدرب على الطبول في منتصف الليل. أندم على عدم انتقالي مبكرًا، حقًا."},{s:0,t:"Drums at midnight? That's awful! Well, you won't have that problem here. The walls are thick — solid brick.",ar:"طبول في منتصف الليل؟ هذا فظيع! حسنًا، لن تواجه هذه المشكلة هنا. الجدران سميكة — طوب صلب."},{s:1,t:"Brick walls — nice. I wish all landlords were this upfront. My last one hid every problem until I'd signed.",ar:"جدران من الطوب — جميل. أتمنى لو كان كل الملاك صريحين هكذا. مالكي الأخير أخفى كل مشكلة حتى وقّعت."},{s:0,t:"That's no way to do business. I'd rather you know everything now than discover surprises later.",ar:"هذه ليست طريقة لإدارة العمل. أفضل أن تعرف كل شيء الآن بدلًا من اكتشاف مفاجآت لاحقًا."},{s:1,t:"I appreciate that, really. Speaking of surprises — is there anything that needs fixing before I move in?",ar:"أقدر ذلك حقًا. وبالحديث عن المفاجآت — هل هناك شيء يحتاج إلى إصلاح قبل انتقالي؟"},{s:0,t:"Just the bathroom tap — it drips a little. I've already called the plumber; it'll be fixed by Friday.",ar:"فقط صنبور الحمام — يقطر قليلًا. اتصلت بالسباك بالفعل؛ سيتم إصلاحه بحلول الجمعة."},{s:1,t:"A dripping tap, that's nothing. I can live with that for a few days, no worries.",ar:"صنبور يقطر، هذا لا شيء. أستطيع التعايش مع ذلك لبضعة أيام، لا مشكلة."},{s:0,t:"Good. Now, the lease — it's a one-year agreement, renewable. Have you had a chance to read through it?",ar:"جيد. الآن، عقد الإيجار — إنه اتفاقية لمدة سنة، قابلة للتجديد. هل أتيحت لك فرصة لقراءته؟"},{s:1,t:"I skimmed it last night. Most of it is standard, but I had one question about the clause on pets.",ar:"تصفحته الليلة الماضية. معظمه قياسي، لكن لدي سؤال واحد حول بند الحيوانات الأليفة."},{s:0,t:"Pets — sure. Small pets are fine, cats and small dogs. Anything bigger, we'd need to discuss. Do you have a pet?",ar:"الحيوانات الأليفة — بالتأكيد. الحيوانات الصغيرة مقبولة، القطط والكلاب الصغيرة. أي شيء أكبر، نحتاج إلى مناقشته. هل لديك حيوان أليف؟"},{s:1,t:"Not yet — but I've been thinking about getting a cat. I wish I'd gotten one years ago, honestly.",ar:"ليس بعد — لكني أفكر في الحصول على قطة. أتمنى لو حصلت على واحدة قبل سنوات، بصراحة."},{s:0,t:"A cat would be lovely here — there's a sunny windowsill in the kitchen they'd adore. Just let me know when you get one.",ar:"قطة ستكون جميلة هنا — توجد عتبة نافذة مشمسة في المطبخ ستعشقها. فقط أخبرني عندما تحصل على واحدة."},{s:1,t:"Will do. Oh, and parking — is there a spot for my car? Street parking around here looks tricky.",ar:"سأفعل. أوه، ومواقف السيارات — هل توجد بقعة لسيارتي؟ مواقف الشارع هنا تبدو صعبة."},{s:0,t:"There's one garage space with the apartment — it's included. The previous tenant didn't drive, so it's been empty.",ar:"توجد بقعة مرآب واحدة مع الشقة — إنها مشمولة. المستأجر السابق لم يكن يقود، لذا كانت فارغة."},{s:1,t:"A garage space included? That's amazing — parking alone would've cost me two hundred a month elsewhere.",ar:"بقعة مرآب مشمولة؟ هذا مذهل — مواقف السيارات وحدها كانت ستكلفني مئتي دولار شهريًا في مكان آخر."},{s:0,t:"Exactly. It's one of the perks of this place. Now, shall we go over the move-in checklist?",ar:"بالضبط. إنها إحدى مزايا هذا المكان. الآن، هل نراجع قائمة الانتقال؟"},{s:1,t:"Sure —",ar:"بالتأكيد —"},{s:0,t:"—Actually, before that, let me show you the garden. It's small, but it's yours to use.",ar:"—في الحقيقة، قبل ذلك، دعني أريك الحديقة. إنها صغيرة، لكنها لك لتستخدمها."},{s:1,t:"A garden too? This place just keeps getting better. I could grow herbs out there — basil, mint, the works.",ar:"حديقة أيضًا؟ هذا المكان يزداد جمالًا. يمكنني زراعة الأعشاب هناك — ريحان ونعناع وكل شيء."},{s:0,t:"Go for it! The last tenant grew tomatoes — huge ones. The soil here is surprisingly good.",ar:"افعلها! المستأجر الأخير زرع طماطم — ضخمة. التربة هنا جيدة بشكل مفاجئ."},{s:1,t:"Tomatoes, herbs... I can already picture it. I think I'm gonna love living here.",ar:"طماطم وأعشاب... أستطيع تخيل ذلك بالفعل. أعتقد أنني سأحب العيش هنا."},{s:0,t:"I hope you do. A home should feel like home, not just four walls and a roof.",ar:"آمل أن تحبه. البيت يجب أن يبدو كبيت، وليس مجرد أربعة جدران وسقف."},{s:1,t:"Well said. Okay, let's do the checklist — and then I'll sign, and we can make it official.",ar:"أحسنت القول. حسنًا، لنراجع القائمة — ثم سأوقع، ويمكننا جعل الأمر رسميًا."},{s:0,t:"Let's do it. Keys, meter readings, condition report — we'll go through it all, nice and slow.",ar:"لنفعلها. المفاتيح وقراءات العدادات وتقرير الحالة — سنمر على كل شيء، بهدوء وببطء."},{s:1,t:"Sounds good. You know, I wish I'd found this place a year ago — it would've saved me so much hassle.",ar:"يبدو جيدًا. تعلم، أتمنى لو وجدت هذا المكان قبل عام — كان سيوفر عليّ الكثير من المتاعب."},{s:0,t:"Better late than never, right? Welcome home — almost, anyway.",ar:"أفضل متأخرًا من ألا يحدث أبدًا، أليس كذلك؟ مرحبًا بك في بيتك — تقريبًا، على أي حال."},{s:1,t:"Ha! Thanks — I can't wait to move in. Next week can't come fast enough.",ar:"ها! شكرًا — لا أستطيع الانتظار للانتقال. الأسبوع المقبل لا يمكن أن يأتي بسرعة كافية."},{s:0,t:"I'll have everything ready for you. Just call me if anything comes up before then.",ar:"سأجهز كل شيء لك. فقط اتصل بي إذا حدث أي شيء قبل ذلك."},{s:1,t:"Will do. Thanks again — for the tour, the honesty, all of it.",ar:"سأفعل. شكرًا مجددًا — على الجولة والصراحة وكل شيء."},{s:0,t:"My pleasure. See you next week — with boxes, I assume!",ar:"بكل سرور. أراك الأسبوع المقبل — مع الصناديق، أفترض!"},{s:1,t:"With boxes, with a cat carrier, with everything. See you then!",ar:"مع الصناديق، ومع حامل قطة، ومع كل شيء. أراك حينها!"},{s:0,t:"Oh, I nearly forgot — the building has a shared laundry room in the basement, and there's a small gym too. Both included.",ar:"أوه، كدت أنسى — المبنى به غرفة غسيل مشتركة في القبو، وصالة ألعاب رياضية صغيرة أيضًا. كلاهما مشمول."},{s:1,t:"A gym too? This place is unbelievable. My old building didn't even have a working elevator.",ar:"صالة ألعاب أيضًا؟ هذا المكان لا يصدق. مبناي القديم لم يكن به حتى مصعد يعمل."},{s:0,t:"Ha! Well, here everything works — mostly. If anything breaks, just call me and I'll send someone the same day.",ar:"ها! حسنًا، هنا كل شيء يعمل — في الغالب. إذا تعطل أي شيء، فقط اتصل بي وسأرسل شخصًا في نفس اليوم."},{s:1,t:"That's reassuring. My last landlord took three weeks to fix a broken heater — in winter! I was freezing.",ar:"هذا مطمئن. مالكي الأخير استغرق ثلاثة أسابيع لإصلاح سخان مكسور — في الشتاء! كنت أتجمد."},{s:0,t:"Three weeks? That's unacceptable. A home should be warm and safe — that's the bare minimum, honestly.",ar:"ثلاثة أسابيع؟ هذا غير مقبول. البيت يجب أن يكون دافئًا وآمنًا — هذا هو الحد الأدنى، بصراحة."},{s:1,t:"I agree completely. Uh-huh, so — the lease, the keys, the checklist... anything else I should know?",ar:"أوافق تمامًا. أها، إذن — عقد الإيجار والمفاتيح والقائمة... أي شيء آخر يجب أن أعرفه؟"},{s:0,t:"Just one thing — the neighborhood. There's a lovely park nearby, a market on Saturdays, and a great bakery on the corner.",ar:"شيء واحد فقط — الحي. توجد حديقة جميلة قريبة، وسوق يوم السبت، ومخبز رائع على الزاوية."},{s:1,t:"A bakery on the corner? Now you're speaking my language. Fresh bread every morning — I can already smell it. The rental agreement is clear — the landlord maintains the structure, and you maintain the interior.",ar:"مخبز على الزاوية؟ الآن تتحدث لغتي. خبز طازج كل صباح — أستطيع شم رائحته بالفعل. اتفاقية الإيجار واضحة — المالك يصون الهيكل، وأنت تصون الداخل."},{s:0,t:"Ha! You'll be best friends with the baker within a week, I guarantee it. Housing costs keep rising — nevertheless, this neighborhood offers genuine value for the price.",ar:"ها! ستصبح أفضل أصدقاء الخباز خلال أسبوع، أضمن لك ذلك. تكاليف السكن تستمر في الارتفاع — ومع ذلك، يقدم هذا الحي قيمة حقيقية مقابل السعر."},{s:1,t:"Probably! Okay, I'm sold — completely. Where do I sign? The lease requires a signature, a deposit, and proof of income — standard, but thorough.",ar:"على الأرجح! حسنًا، أنا مقتنع — تمامًا. أين أوقع؟ يتطلب العقد توقيعًا وتأمينًا وإثبات دخل — قياسي، لكنه شامل."},{s:0,t:"Right here — and here. Welcome to the building. I think you're gonna be very happy here. Privacy matters — the thick walls and quiet street give you genuine peace after a long day.",ar:"هنا تمامًا — وهنا. مرحبًا بك في المبنى. أعتقد أنك ستكون سعيدًا جدًا هنا. الخصوصية مهمة — الجدران السميكة والشارع الهادئ يمنحانك سلامًا حقيقيًا بعد يوم طويل."},{s:1,t:"I think so too. Thanks for everything — really. This already feels like home. The suburb is peaceful — nearby parks, good schools, and a real sense of community.",ar:"أعتقد ذلك أيضًا. شكرًا على كل شيء — حقًا. هذا يبدو كبيت بالفعل. الضاحية هادئة — حدائق قريبة ومدارس جيدة وشعور حقيقي بالمجتمع."},{s:0,t:"That's the best thing a landlord can hear. See you next week — and don't forget the boxes! The garden needs care — mow the lawn, trim the bush, and it'll stay lovely all summer.",ar:"هذا أفضل شيء يمكن أن يسمعه مالك منزل. أراك الأسبوع المقبل — ولا تنسَ الصناديق! الحديقة تحتاج إلى عناية — جزّ العشب، وقصّ الشجيرة، وستبقى جميلة طوال الصيف."},{s:1,t:"Never! Boxes, cat carrier, plants — the whole moving circus. See you then! I wish I'd negotiated the rent — a small discount would've added to my savings over the year.",ar:"أبدًا! صناديق وحامل قطة ونباتات — سيرك الانتقال كله. أراك حينها! أتمنى لو تفاوضت على الإيجار — خصم صغير كان سيضيف إلى مدخراتي على مدار العام."},{s:0,t:"Ha! Safe moving — and welcome home! A home is shelter from the world — four walls that keep the noise out and the warmth in.",ar:"ها! انتقال آمن — ومرحبًا بك في بيتك! البيت ملاذ من العالم — أربعة جدران تبقي الضجيج خارجًا والدفء داخلًا."}]}},{stage:16,topic:"space",topicAr:"الفضاء والكون",topicEn:"Space & the Universe",topicDe:"Weltraum und Universum",emoji:"🚀",title:"رحلة إلى المريخ",grammar:{id:"en-b2-future-perfect-continuous",title:"Future perfect and future continuous",titleAr:"المستقبل التام والمستقبل المستمر",covers:1},conv:{id:"en-stage16-b2",speakers:["Astronaut (رائد الفضاء)","Engineer (المهندس)"],turns:[{s:0,t:"Okay, walk me through it one more time. By the time we launch, how long will we have been training? The spacecraft's systems are redundant — if one fails, another takes over instantly.",ar:"حسنًا، اشرح لي الأمر مرة أخرى. بحلول وقت الإطلاق، كم ستكون مدة تدريبنا؟ أنظمة المركبة الفضائية احتياطية — إذا فشل أحدها، يتولى آخر مكانه فورًا."},{s:1,t:"By launch day, you will have been training for nearly three years. Three years of simulations, centrifuge runs, the works. The astronaut's suit is a marvel — it maintains temperature, oxygen, and pressure perfectly.",ar:"بحلول يوم الإطلاق، ستكون قد تدربت لما يقرب من ثلاث سنوات. ثلاث سنوات من المحاكاة وتدريبات الطرد المركزي وكل شيء. بدلة رائد الفضاء أعجوبة — تحافظ على درجة الحرارة والأكسجين والضغط بشكل مثالي."},{s:0,t:"Three years! And the trip itself is seven months, each way. That's a long time to be stuck in a tin can. The rover's cameras transmit images daily — rust-red deserts, pale skies, and endless horizons.",ar:"ثلاث سنوات! والرحلة نفسها سبعة أشهر، في كل اتجاه. هذا وقت طويل للبقاء عالقًا في علبة قصدير. كاميرات المركبة الجوالة تنقل الصور يوميًا — صحارٍ حمراء صدئة وسماوات شاحبة وآفاق لا نهائية."},{s:1,t:"Ha! It's a very advanced tin can, I'll have you know. But yeah, the isolation is the hardest part — that's what the psychologists keep telling us. The crew trains for emergencies — fire, decompression, unconscious crewmates — every scenario rehearsed.",ar:"ها! إنها علبة قصدير متقدمة جدًا، لأعلمك. لكن نعم، العزلة هي أصعب جزء — هذا ما يخبرنا به علماء النفس باستمرار. يتدرب الطاقم على الطوارئ — حريق وفقدان ضغط وزملاء فاقدون للوعي — كل سيناريو متدرب عليه."},{s:0,t:"I believe it. Seven months with the same three people, no fresh air, no real sky. How do you even prepare for that? The launch pad is a cathedral of steel — floodlights, steam, and the roar of ignition.",ar:"أصدق ذلك. سبعة أشهر مع نفس الأشخاص الثلاثة، بلا هواء نقي وبلا سماء حقيقية. كيف تستعد لذلك أصلًا؟ منصة الإطلاق كاتدرائية من الفولاذ — أضواء كاشفة وبخار وهدير الاشتعال."},{s:1,t:"We practice in a sealed habitat in the desert — same crew, same routine, for months. It builds trust, and it exposes the cracks early. The countdown's final seconds stretch forever — ten, nine, eight — then the sky splits open.",ar:"نتدرب في موطن مغلق في الصحراء — نفس الطاقم ونفس الروتين، لشهور. هذا يبني الثقة، ويكشف الشقوق مبكرًا. الثواني الأخيرة للعد التنازلي تمتد إلى الأبد — عشرة، تسعة، ثمانية — ثم تنشق السماء."},{s:0,t:"Smart. So, tell me about the ship. What's new compared to the last mission? The stars from orbit shine steadily — no twinkle, just fierce points of light in the black.",ar:"ذكي. إذن، حدثني عن السفينة. ما الجديد مقارنة بالمهمة الأخيرة؟ النجوم من المدار تلمع بثبات — بلا وميض، فقط نقاط ضوء شرسة في الظلام."},{s:1,t:"Almost everything. The life-support system is more efficient, the radiation shielding is thicker, and we've got a proper greenhouse now. The journey is an undertaking — bold, dangerous, and utterly human.",ar:"تقريبًا كل شيء. نظام دعم الحياة أكثر كفاءة، والدرع الإشعاعي أكثر سمكًا، ولدينا الآن دفيئة حقيقية. الرحلة مهمة جسيمة — جريئة وخطيرة وإنسانية تمامًا."},{s:0,t:"A greenhouse? In space? That's wild. What are you growing up there — lettuce? The mission's funding is secure — Congress approved it, and the work proceeds on schedule.",ar:"دفيئة؟ في الفضاء؟ هذا جنوني. ماذا تزرعون هناك — خس؟ تمويل المهمة مؤمّن — وافق عليه الكونغرس، والعمل يسير وفق الجدول."},{s:1,t:"Lettuce, tomatoes, herbs — fresh food makes a massive difference to morale. After months of packaged meals, a real tomato tastes like heaven. The spacecraft's navigation is crucial — a tiny error now means missing Mars by thousands of miles.",ar:"خس وطماطم وأعشاب — الطعام الطازج يحدث فرقًا ضخمًا في الروح المعنوية. بعد شهور من الوجبات المعلبة، طماطم حقيقية طعمها مثل الجنة. ملاحة المركبة الفضائية حاسمة — خطأ صغير الآن يعني تفويت المريخ بآلاف الأميال."},{s:0,t:"I can imagine. And water? I heard you recycle almost everything on board. The planet's moons are tiny — Phobos and Deimos, lumpy rocks that barely hold together.",ar:"أستطيع التخيل. والماء؟ سمعت أنكم تعيدون تدوير كل شيء تقريبًا على متن السفينة. أقمار الكوكب صغيرة — فوبوس وديموس، صخور متكتلة بالكاد تتماسك."},{s:1,t:"We recycle about ninety-eight percent of it — sweat, breath, everything. It's not glamorous, but it works. By the time we reach Mars, the system will have processed thousands of liters. The astronaut's family watches from Earth — proud, anxious, and whispering prayers.",ar:"نعيد تدوير حوالي ثمانية وتسعين بالمئة منه — العرق والتنفس وكل شيء. إنه ليس براقًا، لكنه يعمل. بحلول وصولنا إلى المريخ، سيكون النظام قد عالج آلاف اللترات. عائلة رائد الفضاء تراقب من الأرض — فخورة وقلقة وتتمتم بالصلوات."},{s:0,t:"Thousands of liters of recycled sweat. Lovely. Remind me never to complain about tap water again. The mission control room erupts at touchdown — cheers, tears, and years of work justified.",ar:"آلاف اللترات من العرق المعاد تدويره. جميل. ذكّرني ألا أشتكي من ماء الصنبور مجددًا أبدًا. تنفجر غرفة التحكم بالمهمة عند الهبوط — هتافات ودموع وسنوات من العمل التي وجدت ما يبررها."},{s:1,t:"Ha! Now, the landing — that's the part that keeps me up at night. Mars has a thin atmosphere, so parachutes alone won't cut it. The first footstep on Mars will be unique — a boot print in red dust, never before made by human feet.",ar:"ها! الآن، الهبوط — هذا هو الجزء الذي يبقيني مستيقظًا ليلًا. المريخ لديه غلاف جوي رقيق، لذا المظلات وحدها لن تكفي. ستكون أول خطوة على المريخ فريدة — بصمة حذاء في غبار أحمر، لم تصنعها أقدام بشرية من قبل."},{s:0,t:"Right, you'll be using retrorockets for the final descent. How many tests have you run on those?",ar:"صحيح، ستستخدمون الصواريخ العكسية للهبوط النهائي. كم اختبارًا أجريتم على تلك؟"},{s:1,t:"Dozens. And the simulations will have run hundreds of scenarios by the time we go. Still, nothing beats the real thing.",ar:"عشرات. وستكون المحاكاة قد شغلت مئات السيناريوهات بحلول وقت ذهابنا. مع ذلك، لا شيء يضاهي الشيء الحقيقي."},{s:0,t:"True. What's the first thing you'll do when you step onto the surface?",ar:"صحيح. ما أول شيء ستفعله عندما تخطو على السطح؟"},{s:1,t:"Honestly? Probably just stand there for a minute. Take it in. After seven months of dreaming about it, the reality will be... overwhelming.",ar:"بصراحة؟ ربما سأقف هناك لدقيقة فقط. أستوعب الأمر. بعد سبعة أشهر من الحلم به، سيكون الواقع... ساحقًا."},{s:0,t:"I get goosebumps just thinking about it. And the science — what are you most excited to study up there?",ar:"أشعر بقشعريرة بمجرد التفكير في الأمر. والعلم — ما الذي أنت متحمس أكثر لدراسته هناك؟"},{s:1,t:"The geology, for sure. Mars has canyons deeper than the Grand Canyon, and ancient riverbeds. If there was ever life, the evidence will be in the rocks.",ar:"الجيولوجيا، بالتأكيد. المريخ لديه أخاديد أعمق من جراند كانيون، ومجاري أنهار قديمة. إذا وُجدت حياة يومًا، فالدليل سيكون في الصخور."},{s:0,t:"Ancient riverbeds... it's mind-blowing. Do you think we'll find signs of past life?",ar:"مجاري أنهار قديمة... إنه أمر مذهل للعقل. هل تعتقد أننا سنجد علامات على حياة سابقة؟"},{s:1,t:"I think it's possible — maybe microbes, fossils, something subtle. We won't find little green men, but we might find something even more profound.",ar:"أعتقد أنه ممكن — ربما ميكروبات أو أحافير أو شيء خفي. لن نجد رجالًا خضرًا صغارًا، لكننا قد نجد شيئًا أعمق بكثير."},{s:0,t:"Little green men — ha! My kids still ask me if aliens are real. What should I tell them?",ar:"رجال خضر صغار — ها! أطفالي ما زالوا يسألونني إن كان الفضائيون حقيقيين. ماذا يجب أن أخبرهم؟"},{s:1,t:"Tell them the universe is enormous — trillions of stars, countless planets. It'd be stranger if we were the only ones, wouldn't it?",ar:"أخبرهم أن الكون هائل — تريليونات النجوم وكواكب لا تُحصى. سيكون أغرب لو كنا الوحيدين، أليس كذلك؟"},{s:0,t:"That's a good answer. They'll love that. So, communication delay — how long will a message take to reach Earth?",ar:"هذه إجابة جيدة. سيحبون ذلك. إذن، تأخير الاتصالات — كم يستغرق وصول رسالة إلى الأرض؟"},{s:1,t:"Up to twenty minutes each way. So no real-time calls — we'll be sending video messages, like old-fashioned letters.",ar:"حتى عشرين دقيقة في كل اتجاه. لذا لا مكالمات فورية — سنرسل رسائل فيديو، مثل الرسائل القديمة."},{s:0,t:"Twenty minutes... that'll feel strange. By the time your family replies, you'll have been waiting for nearly an hour.",ar:"عشرون دقيقة... سيبدو ذلك غريبًا. بحلول رد عائلتك، ستكون قد انتظرت لما يقرب من ساعة."},{s:1,t:"Yeah, that's the part I'm dreading most, honestly. Missing birthdays, school plays, the everyday stuff. That's the real price.",ar:"نعم، هذا الجزء الذي أخشاه أكثر، بصراحة. تفويت أعياد الميلاد والمسرحيات المدرسية والأشياء اليومية. هذا هو الثمن الحقيقي."},{s:0,t:"That's tough, no doubt. But your kids will be so proud — their parent, walking on another planet.",ar:"هذا صعب، بلا شك. لكن أطفالك سيكونون فخورين جدًا — والدهم، يمشي على كوكب آخر."},{s:1,t:"I hope so. I keep telling myself the sacrifice is worth it — for science, for the future, for them.",ar:"آمل ذلك. أستمر في إخبار نفسي أن التضحية تستحق — من أجل العلم والمستقبل ومن أجلهم."},{s:0,t:"It is worth it. And hey —",ar:"إنها تستحق. وهيّا —"},{s:1,t:"—Hey what? Don't tell me there's a problem with the heat shield.",ar:"—هيّا ماذا؟ لا تخبرني أن هناك مشكلة في الدرع الحراري."},{s:0,t:"No, no problem! I was just gonna say — the satellite images of the landing site came back, and it looks perfect. Flat, clear, ideal.",ar:"لا، لا مشكلة! كنت فقط سأقول — صور الأقمار الصناعية لموقع الهبوط عادت، وتبدو مثالية. مسطح وواضح ومثالي."},{s:1,t:"That's fantastic news! A flat landing site makes everything easier. I was worried about the boulders.",ar:"هذه أخبار رائعة! موقع هبوط مسطح يجعل كل شيء أسهل. كنت قلقًا بشأن الصخور."},{s:0,t:"The team picked it carefully. We've been mapping that region for two years — every rock, every slope.",ar:"اختاره الفريق بعناية. كنا نرسم خريطة تلك المنطقة لمدة عامين — كل صخرة وكل منحدر."},{s:1,t:"Two years of mapping, three years of training... by the time we land, we will have spent half a decade getting ready.",ar:"عامان من رسم الخرائط، وثلاث سنوات من التدريب... بحلول وقت هبوطنا، سنكون قد أمضينا نصف عقد في الاستعداد."},{s:0,t:"Half a decade — and it'll all be worth it the moment your boots touch that red dust.",ar:"نصف عقد — وسيكون كل ذلك يستحق الأمر لحظة لمس حذائك ذلك الغبار الأحمر."},{s:1,t:"Red dust... I dream about it. Okay, one last question — what's the one thing you're taking with you that isn't on the official list?",ar:"غبار أحمر... أحلم به. حسنًا، سؤال أخير — ما الشيء الواحد الذي تأخذه معك وليس في القائمة الرسمية؟"},{s:0,t:"A photo of my family, tucked inside my flight suit. Cheesy, I know — but it keeps me going.",ar:"صورة لعائلتي، مدسوسة داخل بدلة الطيران. مبتذل، أعلم — لكنها تبقيني مستمرًا."},{s:1,t:"Not cheesy at all. That's the most important cargo on the whole ship.",ar:"ليست مبتذلة إطلاقًا. هذه أهم حمولة على السفينة كلها."},{s:0,t:"Thanks. Alright — back to the simulator. If I'm gonna walk on Mars, I better nail this landing first.",ar:"شكرًا. حسنًا — عودة إلى المحاكي. إذا كنت سأمشي على المريخ، من الأفضل أن أتقن هذا الهبوط أولًا."},{s:1,t:"Go nail it. And remember — by this time next year, you'll be standing on another world.",ar:"اذهب وأتقنه. وتذكر — في مثل هذا الوقت من العام المقبل، ستقف على عالم آخر."},{s:0,t:"Another world... still sounds like science fiction when you say it out loud.",ar:"عالم آخر... ما زال يبدو كخيال علمي عندما تقوله بصوت عالٍ."},{s:1,t:"Give it a year — it'll be history. Now go, the simulator's waiting.",ar:"امنحه عامًا — سيصبح تاريخًا. الآن اذهب، المحاكي بانتظارك."},{s:0,t:"On my way. See you at the debrief — and thanks for everything, truly.",ar:"في طريقي. أراك في جلسة المراجعة — وشكرًا على كل شيء، حقًا."},{s:0,t:"One more thing I keep wondering about — the view. What's Earth like from up there? Does it change how you see everything?",ar:"شيء آخر أستمر في التساؤل عنه — المنظر. كيف تبدو الأرض من هناك؟ هل يغير ذلك نظرتك لكل شيء؟"},{s:1,t:"Completely. You see this fragile blue sphere floating in blackness, and suddenly borders and conflicts seem so small. It's humbling.",ar:"تمامًا. ترى هذه الكرة الزرقاء الهشة تطفو في السواد، وفجأة تبدو الحدود والصراعات صغيرة جدًا. إنه أمر متواضع."},{s:0,t:"The overview effect — I've read about it. Astronauts say it transforms their whole perspective on life.",ar:"تأثير النظرة الشاملة — قرأت عنه. رواد الفضاء يقولون إنه يحوّل منظورهم الكامل للحياة."},{s:1,t:"It does. You come back different — more patient, more grateful. At least, that's what the veterans tell us.",ar:"إنه يفعل. تعود مختلفًا — أكثر صبرًا وأكثر امتنانًا. على الأقل، هذا ما يخبرنا به القدامى."},{s:0,t:"I believe it. And the stars — without atmosphere, they must be unbelievable. No twinkling, just pure light.",ar:"أصدق ذلك. والنجوم — بلا غلاف جوي، لا بد أنها لا تصدق. لا وميض، فقط ضوء نقي."},{s:1,t:"Exactly — sharp, brilliant points of light everywhere you look. The universe feels close enough to touch up there.",ar:"بالضبط — نقاط ضوء حادة وبراقة في كل مكان تنظر إليه. الكون يبدو قريبًا بما يكفي للمسه هناك."},{s:0,t:"Close enough to touch... wow. Okay, last question, I promise — will you have been missing Earth by the time you land?",ar:"قريب بما يكفي للمسه... واو. حسنًا، سؤال أخير، أعدك — هل ستكون قد اشتقت إلى الأرض بحلول وقت هبوطك؟"},{s:1,t:"Oh, I'll have been missing it for months by then — the rain, the ocean, my family. But that's part of the journey. The satellite network relays data constantly — without it, the mission would be flying blind.",ar:"أوه، سأكون قد اشتققت إليها لشهور بحلول ذلك الوقت — المطر والمحيط وعائلتي. لكن هذا جزء من الرحلة. شبكة الأقمار الصناعية ترسل البيانات باستمرار — بدونها، ستكون المهمة تحلق عمياء."},{s:0,t:"Missing home while reaching for the stars — that's the astronaut's life, I guess. The universe is vast — trillions of stars, and we have explored only a fraction of it.",ar:"الاشتياق إلى الوطن أثناء الوصول إلى النجوم — هذه حياة رائد الفضاء، أعتقد. الكون شاسع — تريليونات النجوم، وقد استكشفنا جزءًا صغيرًا منه فقط."},{s:1,t:"It is. And you know what? I wouldn't trade it for anything in the world. Not for all the comfort on Earth. A solar storm could disrupt communications — the engineers monitor the sensors around the clock.",ar:"إنها كذلك. وتعلم ماذا؟ لن أستبدلها بأي شيء في العالم. ولا بكل الراحة على الأرض. عاصفة شمسية قد تعطل الاتصالات — المهندسون يراقبون أجهزة الاستشعار على مدار الساعة."},{s:0,t:"That's the spirit. Alright — simulator time. Go make history, my friend. The crew will have been living in zero gravity for months — muscles weaken, bones thin, and exercise is vital.",ar:"هذه هي الروح. حسنًا — وقت المحاكي. اذهب واصنع التاريخ، يا صديقي. سيكون الطاقم قد عاش في انعدام الجاذبية لشهور — العضلات تضعف، والعظام ترق، والتمارين حيوية."},{s:1,t:"History — no pressure! See you at the debrief. And thanks for the chat — it helped more than you know. The mission's ultimate goal is a permanently crewed base — a foothold for humanity beyond Earth.",ar:"التاريخ — بلا ضغط! أراك في جلسة المراجعة. وشكرًا على الحديث — لقد ساعد أكثر مما تعرف. الهدف النهائي للمهمة هو قاعدة مأهولة بشكل دائم — موطئ قدم للبشرية خارج الأرض."},{s:0,t:"Anytime. Now go — Mars is waiting, and so is your destiny. The launch window demands precise timing — miss it by a day, and the geometry is wrong.",ar:"في أي وقت. الآن اذهب — المريخ بانتظارك، وكذلك مصيرك. نافذة الإطلاق تتطلب توقيتًا دقيقًا — تفوتها بيوم، وتكون الهندسة خاطئة."},{s:1,t:"Mars is waiting. I love the sound of that. See you soon! The telescope reveals galaxies billions of light-years away — a spectacular reminder of our scale.",ar:"المريخ بانتظارنا. أحب هذا الكلام. أراك قريبًا! التلسكوب يكشف مجرات تبعد مليارات السنين الضوئية — تذكير مذهل بحجمنا."},{s:0,t:"See you soon — and godspeed, astronaut. Subsequent missions will build on everything we learn — each one bolder than the last.",ar:"أراك قريبًا — وبالتوفيق يا رائد الفضاء. المهمات اللاحقة ستبني على كل ما نتعلمه — كل واحدة أجرأ من سابقتها."}]}},{stage:17,topic:"street",topicAr:"كلام الشارع",topicEn:"Street Talk",topicDe:"Street Talk",emoji:"",title:"زبون غاضب في المتجر",grammar:{id:"en-b2-mixed-conditionals",title:"Mixed conditionals",titleAr:"الشرط المختلط",covers:1},conv:{id:"en-stage17-b2",speakers:["Customer (الزبون)","Shopkeeper (صاحب المتجر)"],turns:[{s:0,t:"I want to speak to the manager. Now.",ar:"أريد التحدث إلى المدير. الآن."},{s:1,t:"I'm the manager. How can I help you, sir?",ar:"أنا المدير. كيف يمكنني مساعدتك يا سيدي؟"},{s:0,t:"Help me? You sold me a broken TV! It died after two days!",ar:"تساعدني؟ بعتني تلفازًا معطلًا! توقف عن العمل بعد يومين!"},{s:1,t:"I'm sorry to hear that. Did you keep the receipt?",ar:"يؤسفني سماع ذلك. هل احتفظت بالإيصال؟"},{s:0,t:"Don't give me that crap. I want my money back — all of it.",ar:"لا تعطني هذا الهراء. أريد أموالي كاملة."},{s:1,t:"Sir, please calm down. We can check the warranty and—",ar:"سيدي، من فضلك اهدأ. يمكننا التحقق من الضمان و—"},{s:0,t:"Calm down? I paid five hundred dollars for this piece of shit!",ar:"أهدأ؟ دفعت خمسمئة دولار مقابل هذا الشيء الحقير!"},{s:1,t:"There's no need for that language. I can offer you a repair, or—",ar:"لا داعي لهذه اللغة. يمكنني أن أعرض عليك إصلاحًا، أو—"},{s:0,t:"Fuck your repair! I don't want it fixed, I want a refund!",ar:"تبًا لإصلاحك! لا أريد إصلاحه، أريد استرجاع أموالي!"},{s:1,t:"Then I'll need the receipt and the box. That's the policy.",ar:"إذن سأحتاج الإيصال والعلبة. هذه هي السياسة."},{s:0,t:"Policy? Goddamn it, I threw the box away! Are you calling me a liar?",ar:"سياسة؟ اللعنة، رميت العلبة! هل تتهمني بالكذب؟"},{s:1,t:"No, sir. But without the receipt, I can't give a refund.",ar:"لا يا سيدي. لكن دون الإيصال، لا أستطيع إعادة المال."},{s:0,t:"Fuck you, then. And fuck this shop. I'll never come back here, son of a bitch!",ar:"تبًا لك إذن. وتبًا لهذا المتجر. لن أعود إلى هنا أبدًا يا ابن الكلبة!"},{s:1,t:"Have a good day, sir. The door is that way.",ar:"أتمنى لك يومًا سعيدًا يا سيدي. الباب من هناك."}]}}],de:[{conv:{id:"de-stage1-b2",speakers:["Mitarbeiter (الموظف)","Chefin (المديرة)"],turns:[{ar:"صباح الخير، شكرًا جزيلًا لأنك خصصتِ وقتًا لهذا اللقاء.",s:0,t:"Guten Morgen, vielen Dank, dass Sie sich die Zeit für dieses Gespräch nehmen."},{ar:"صباح الخير، بكل سرور. أردتِ التحدث عن راتبكِ، صحيح؟",s:1,t:"Guten Morgen, gerne. Sie wollten über Ihr Gehalt sprechen, richtig?"},{ar:"بالضبط. أريد أن أطرح هذا الموضوع اليوم، لأنني أعمل في هذا المنصب منذ ثلاث سنوات.",s:0,t:"Genau. Ich möchte das Thema heute zur Sprache bringen, weil ich seit drei Jahren in dieser Position arbeite."},{ar:"هذا صحيح، وأنا أقدّر عملك كثيرًا. تفضّلي وأخبريني بما تتصورينه.",s:1,t:"Das stimmt, und ich schätze Ihre Arbeit sehr. Bitte erzählen Sie mir, was Sie sich vorstellen."},{ar:"في العامين الماضيين تحمّلتُ مسؤوليات إضافية ودرّبتُ زميلين جديدين.",s:0,t:"In den letzten zwei Jahren habe ich zusätzliche Verantwortung übernommen und zwei neue Kollegen eingearbeitet."},{ar:"لاحظتُ ذلك. مشاريعك تسير بموثوقية، والفريق يستفيد من دعمك بسرور.",s:1,t:"Das habe ich bemerkt. Ihre Projekte laufen zuverlässig, und das Team nimmt Ihre Unterstützung gerne in Anspruch."},{ar:"شكرًا. لذلك أريد أن نأخذ زيادة الراتب بعين الاعتبار وأن نتحدث عن تعديله.",s:0,t:"Danke. Deshalb möchte ich eine Gehaltserhöhung in Betracht ziehen und mit Ihnen über eine Anpassung sprechen."},{ar:"أفهم. ما الزيادة التي تتصورها تحديدًا؟",s:1,t:"Verstehe. Welche Erhöhung stellen Sie sich konkret vor?"},{ar:"قارنتُ السوق وأعتقد أن زيادة بنسبة عشرة بالمئة ستكون مناسبة.",s:0,t:"Ich habe den Markt verglichen und denke, dass eine Erhöhung von zehn Prozent angemessen wäre."},{ar:"عشرة بالمئة زيادة كبيرة. هل يمكنك أن تشرح لي أسبابك بتفصيل أكبر؟",s:1,t:"Zehn Prozent sind eine deutliche Erhöhung. Können Sie mir Ihre Gründe genauer erläutern?"},{ar:"بالطبع. في العام الماضي أنجزتُ بنجاح ثلاثة مشاريع كبيرة.",s:0,t:"Natürlich. Im letzten Jahr habe ich drei große Projekte erfolgreich zum Abschluss gebracht."},{ar:"هذا صحيح، وقد أشاد الزبائن بعملك صراحة.",s:1,t:"Das ist richtig, und die Kunden haben Ihre Arbeit ausdrücklich gelobt."},{ar:"إضافة إلى ذلك، أضع خبرتي بتصرف الفريق بانتظام عندما تظهر أسئلة صعبة.",s:0,t:"Außerdem stelle ich dem Team regelmäßig meine Erfahrung zur Verfügung, wenn schwierige Fragen auftreten."},{ar:"أقدّر ذلك. لكن علينا أيضًا أن نأخذ الوضع المالي للشركة بعين الاعتبار.",s:1,t:"Das weiß ich zu schätzen. Aber wir müssen auch die finanzielle Lage des Unternehmens in Betracht ziehen."},{ar:"أفهم ذلك تمامًا. لذلك أنا مستعد لأن آخذ حلًا وسطًا بعين الاعتبار.",s:0,t:"Das verstehe ich vollkommen. Deshalb bin ich bereit, einen Kompromiss in Erwägung zu ziehen."},{ar:"حسنًا، لنتحدث بصراحة إذن. يمكنني الموافقة فورًا على زيادة بنسبة خمسة بالمئة.",s:1,t:"Gut, dann sprechen wir offen. Eine Erhöhung von fünf Prozent könnte ich sofort genehmigen."},{ar:"خمسة بالمئة بداية، لكنها لا تعكس مسؤوليتي الإضافية بما فيه الكفاية.",s:0,t:"Fünf Prozent sind ein Anfang, aber sie spiegeln meine zusätzliche Verantwortung nicht ausreichend wider."},{ar:"ما رأيك في سبعة بالمئة ودورة تدريبية إضافية؟",s:1,t:"Was halten Sie von sieben Prozent und einem zusätzlichen Weiterbildungskurs?"},{ar:"هذا يبدو مثيرًا للاهتمام. أريد أن أفكّر في العرض بهدوء، لكن الدورة اقتراح جيد.",s:0,t:"Das klingt interessant. Ich möchte das Angebot in Ruhe in Betracht ziehen, aber der Kurs ist ein guter Vorschlag."},{ar:"بالطبع، خذ وقتك. لا يجب أن نتخذ قرارًا نهائيًا اليوم.",s:1,t:"Natürlich, nehmen Sie sich Zeit. Wir müssen heute keine endgültige Entscheidung treffen."},{ar:"شكرًا. هل يمكنني أن أطرح نقطة أخرى؟ ساعات العمل الإضافية في الأشهر الماضية كانت مرتفعة جدًا.",s:0,t:"Danke. Darf ich noch einen Punkt zur Sprache bringen? Die Überstunden in den letzten Monaten waren sehr hoch."},{ar:"هذا صحيح، وأريد أن أشكرك على ذلك. سنعيد تنظيم توزيع العمل.",s:1,t:"Das stimmt, und dafür möchte ich mich bedanken. Wir werden die Arbeitsverteilung neu in Angriff nehmen."},{ar:"هذا سيساعدني كثيرًا. أريد أن أحافظ على أدائي على هذا المستوى على المدى الطويل.",s:0,t:"Das würde mir sehr helfen. Ich möchte meine Leistung langfristig auf diesem Niveau halten."},{ar:"هذا في مصلحتنا أيضًا. الحفاظ على الموظفين الجيدين له أولوية عالية عندنا.",s:1,t:"Das ist auch in unserem Interesse. Gute Mitarbeiter zu halten, hat für uns hohe Priorität."},{ar:"إذن سأقدّم طلبًا بسبعة بالمئة والدورة ومراجعة بعد ستة أشهر.",s:0,t:"Dann stelle ich einen Antrag auf sieben Prozent, den Kurs und eine Überprüfung in sechs Monaten."},{ar:"موافقة. سأطّلع على طلبك وأناقشه مع الإدارة.",s:1,t:"Einverstanden. Ich werde Ihren Antrag zur Kenntnis nehmen und mit der Geschäftsführung besprechen."},{ar:"شكرًا جزيلًا. متى يمكننا أن نتوقع قرارًا نهائيًا؟",s:0,t:"Vielen Dank. Wann können wir eine endgültige Entscheidung erwarten?"},{ar:"في غضون أسبوعين على الأكثر سأعطيك ردًا. سأبقيك على اطلاع.",s:1,t:"Spätestens in zwei Wochen gebe ich Ihnen eine Rückmeldung. Ich halte Sie auf dem Laufenden."},{ar:"هذا عادل. حتى ذلك الحين سأواصل أداء مهامي بكل جهد.",s:0,t:"Das ist fair. Ich werde bis dahin weiterhin meine Aufgaben mit vollem Einsatz erfüllen."},{ar:"أنا مقتنعة بذلك. هل هناك شيء آخر تريد طرحه؟",s:1,t:"Davon bin ich überzeugt. Gibt es sonst noch etwas, das Sie zur Sprache bringen möchten?"},{ar:"شيء واحد فقط: أود أن أتحمّل في المستقبل مسؤولية أكبر في إدارة المشاريع.",s:0,t:"Nur noch eines: Ich würde gerne in Zukunft mehr Verantwortung im Projektmanagement übernehmen."},{ar:"هذه فكرة جيدة. يمكننا أن نأخذ ذلك بعين الاعتبار في التخطيط القادم.",s:1,t:"Das ist ein guter Gedanke. Wir können das bei der nächsten Planung in Betracht ziehen."},{ar:"هذا يسعدني. أريد أن أتطور مهنيًا وأن أكتسب خبرات جديدة.",s:0,t:"Das freut mich. Ich möchte mich beruflich weiterentwickeln und neue Erfahrungen sammeln."},{ar:"عروض التدريب لدينا متاحة لك لذلك. تحدّث معي ببساطة.",s:1,t:"Dafür stehen Ihnen unsere Weiterbildungsangebote zur Verfügung. Sprechen Sie mich einfach an."},{ar:"سأفعل ذلك. أقدّر كثيرًا أنك تأخذ طلبي على محمل الجد.",s:0,t:"Das werde ich tun. Ich schätze es sehr, dass Sie mein Anliegen ernst nehmen."},{ar:"بالطبع. الحوار المفتوح هو أساس التعاون الجيد.",s:1,t:"Selbstverständlich. Ein offenes Gespräch ist die Grundlage für eine gute Zusammenarbeit."},{ar:"إذن سألخّص: سبعة بالمئة، ودورة، ومراجعة بعد ستة أشهر.",s:0,t:"Dann fasse ich zusammen: sieben Prozent, ein Kurs und eine Überprüfung in sechs Monaten."},{ar:"بالضبط هكذا. سأدوّن كل شيء كتابةً وأرسل لك تأكيدًا.",s:1,t:"Genau so. Ich werde alles schriftlich festhalten und Ihnen eine Bestätigung schicken."},{ar:"ممتاز، شكرًا جزيلًا على هذا الحوار البنّاء.",s:0,t:"Perfekt, vielen Dank für das konstruktive Gespräch."},{ar:"على الرحب والسعة. أتطلع إلى استمرار تعاوننا.",s:1,t:"Gern geschehen. Ich freue mich auf unsere weitere Zusammenarbeit."},{ar:"وأنا أيضًا. أتمنى لك يومًا سعيدًا!",s:0,t:"Ich mich auch. Einen schönen Tag noch!"},{ar:"ولك أيضًا، وإلى اللقاء بعد أسبوعين!",s:1,t:"Ihnen auch, und bis in zwei Wochen!"}]},emoji:"💰",grammar:{covers:1,id:"de-b2-funktionsverbgefuege",title:"Funktionsverbgefüge",titleAr:"تراكيب الفعل الوظيفي"},stage:1,title:"مفاوضة على الراتب",topic:"jobs",topicAr:"المهن والعمل",topicDe:"Gehaltsverhandlung",topicEn:"Salary negotiation"},{conv:{id:"de-stage2-b2",speakers:["Mitarbeiter (الموظف)","Personalchef (مدير الموارد البشرية)"],turns:[{ar:"مرحبًا، شكرًا لأنك خصصتَ لي وقتًا بهذه السرعة.",s:0,t:"Guten Tag, danke, dass Sie sich so kurzfristig Zeit für mich genommen haben."},{ar:"مرحبًا، لا مشكلة. ما الموضوع؟",s:1,t:"Guten Tag, kein Problem. Worum geht es denn?"},{ar:"للأسف يجب أن أبلغك بأنني أريد الاستقالة من منصبي.",s:0,t:"Ich muss Ihnen leider mitteilen, dass ich meine Stelle kündigen möchte."},{ar:"يؤسفني سماع ذلك. هل يمكنني أن أسأل لماذا اتخذتَ هذا القرار؟",s:1,t:"Das tut mir leid zu hören. Darf ich fragen, warum Sie diese Entscheidung getroffen haben?"},{ar:"فكّرتُ في الأمر طويلًا. لو تحدثتُ معك في وقت أبكر، لربما سارت الأمور بشكل مختلف.",s:0,t:"Ich habe lange darüber nachgedacht. Wenn ich früher mit Ihnen gesprochen hätte, wäre die Situation vielleicht anders verlaufen."},{ar:"أستطيع أن أفهم ذلك. هل كنتَ تتمنى دعمًا أكبر؟",s:1,t:"Das kann ich verstehen. Hätten Sie sich mehr Unterstützung gewünscht?"},{ar:"نعم، كنتُ أتمنى فرص تطوير أكبر. كنتُ سأبقى لفترة أطول لو كانت هناك آفاق.",s:0,t:"Ja, ich hätte mir mehr Entwicklungsmöglichkeiten gewünscht. Ich wäre gerne länger geblieben, wenn es eine Perspektive gegeben hätte."},{ar:"هذا مؤسف. كنّا سنعرض عليك مهمة جديدة بسرور لو كنّا نعرف رغباتك.",s:1,t:"Das ist schade. Wir hätten Ihnen gerne eine neue Aufgabe angeboten, wenn wir von Ihren Wünschen gewusst hätten."},{ar:"أقدّر ذلك. لكن كان يجب أن أقول بوضوح قبل عام ما الذي ينقصني.",s:0,t:"Das weiß ich zu schätzen. Aber ich hätte schon vor einem Jahr deutlicher sagen sollen, was mir fehlt."},{ar:"ربما كنّا حينها سنجد حلًا معًا. ما الذي دفعك في النهاية إلى الاستقالة؟",s:1,t:"Vielleicht hätten wir dann gemeinsam eine Lösung gefunden. Was hat Sie letztlich zum Kündigen bewegt?"},{ar:"تلقّيتُ عرضًا في مدينة أخرى. كان سيكون من المؤسف ألا أستغل هذه الفرصة.",s:0,t:"Ich habe ein Angebot in einer anderen Stadt erhalten. Es wäre schade gewesen, diese Chance nicht zu nutzen."},{ar:"أفهم. لو كان العرض أقرب، هل كنتَ سترغب في البقاء؟",s:1,t:"Verstehe. Wäre das Angebot näher gewesen, hätten Sie dann bleiben wollen?"},{ar:"بصراحة، كنتُ سأغيّر على الأرجح رغم ذلك، لأنني أريد إعادة توجيه مساري المهني.",s:0,t:"Ehrlich gesagt, ich hätte wahrscheinlich trotzdem gewechselt, weil ich mich beruflich neu orientieren möchte."},{ar:"أحترم ذلك. لو أبلغتَنا في وقت أبكر، لكنّا خططنا للتسليم بشكل أفضل.",s:1,t:"Das respektiere ich. Hätten Sie uns früher informiert, hätten wir die Übergabe besser planen können."},{ar:"أنت محق في ذلك. كان يجب أن أقدّم الاستقالة في وقت أبكر، لكنني كنتُ مترددًا طويلًا.",s:0,t:"Da haben Sie recht. Ich hätte die Kündigung früher einreichen sollen, aber ich war mir lange unsicher."},{ar:"لا مشكلة، سنجد حلًا. متى تريد أن يكون آخر يوم عمل لك؟",s:1,t:"Kein Problem, wir finden eine Lösung. Wann möchten Sie Ihren letzten Arbeitstag haben?"},{ar:"فترة الإشعار الخاصة بي ثلاثة أشهر. إذا فهمتُ كل شيء بشكل صحيح، فنهاية الشهر القادم ستكون ممكنة.",s:0,t:"Meine Kündigungsfrist beträgt drei Monate. Wenn ich alles richtig verstanden habe, wäre das Ende nächsten Monats möglich."},{ar:"سنراجع ذلك. لو غادرتَ في وقت أبكر، لكان علينا البحث عن بديل بسرعة أكبر.",s:1,t:"Wir prüfen das. Wenn Sie früher gegangen wären, hätten wir einen Ersatz schneller suchen müssen."},{ar:"سأبقى بسرور حتى النهاية وأساعد في تدريب من سيخلفني.",s:0,t:"Ich bleibe gerne bis zum Ende und helfe bei der Einarbeitung meiner Nachfolge."},{ar:"هذا عادل جدًا منك. لو تصرّف الجميع هكذا، لكان الكثير أسهل.",s:1,t:"Das ist sehr fair von Ihnen. Hätten alle so gehandelt, wäre vieles einfacher gewesen."},{ar:"لا أريد أن أترك الفريق. وإلا لكان علينا تأجيل مشاريع كثيرة.",s:0,t:"Ich möchte das Team nicht im Stich lassen. Wir hätten sonst viele Projekte verzögern müssen."},{ar:"بالضبط. هل يمكنك أن تعطيني استقالتك كتابةً أيضًا من فضلك؟",s:1,t:"Genau. Können Sie mir bitte Ihre Kündigung auch schriftlich geben?"},{ar:"بالطبع، لقد جهّزتُ الرسالة بالفعل. كنتُ أود أن أعطيك إياها أمس.",s:0,t:"Natürlich, ich habe den Brief schon vorbereitet. Ich hätte ihn Ihnen gerne schon gestern gegeben."},{ar:"جيد جدًا. هل فكّرتَ بالفعل في شهادة العمل الخاصة بك؟",s:1,t:"Sehr gut. Haben Sie schon über Ihr Arbeitszeugnis nachgedacht?"},{ar:"نعم، سأكون ممتنًا لو أصدرتَ لي شهادة جيدة.",s:0,t:"Ja, ich wäre Ihnen dankbar, wenn Sie mir ein gutes Zeugnis ausstellen könnten."},{ar:"بالطبع. لو بقيتَ لفترة أطول، لكنّا رقّيناك حتى.",s:1,t:"Selbstverständlich. Wenn Sie länger geblieben wären, hätten wir Sie sogar befördert."},{ar:"سماع ذلك يسعدني ويجعل الوداع أصعب. كنتُ أود أن أستغل هذه الفرصة.",s:0,t:"Das zu hören freut mich und macht mir den Abschied schwerer. Ich hätte diese Chance gerne genutzt."},{ar:"أحيانًا تأتي مثل هذه الأخبار متأخرة. هل ستكون مستعدًا للعودة في المستقبل؟",s:1,t:"Manchmal kommt eine solche Nachricht zu spät. Wären Sie bereit, in Zukunft wiederzukommen?"},{ar:"ربما. لو تغيّرت الظروف، لكنتُ بقيتُ بالتأكيد.",s:0,t:"Vielleicht. Wenn sich die Umstände geändert hätten, wäre ich sicher geblieben."},{ar:"الباب مفتوح لك. ماذا ستفعل في الوظيفة الجديدة؟",s:1,t:"Die Tür steht Ihnen offen. Was werden Sie in der neuen Stelle machen?"},{ar:"سأقود فريقًا صغيرًا. كنتُ أود أن أفعل ذلك هنا أيضًا لو كانت الوظيفة شاغرة.",s:0,t:"Ich werde ein kleines Team leiten. Das hätte ich hier auch gerne gemacht, wenn die Stelle frei gewesen wäre."},{ar:"أتمنى لك الكثير من التوفيق. هل لديك أسئلة أخرى عن إجراءات الاستقالة؟",s:1,t:"Ich wünsche Ihnen viel Erfolg. Hätten Sie noch Fragen zum Ablauf der Kündigung?"},{ar:"نعم، سؤال واحد: هل سأحصل على بدل أيام إجازتي المتبقية؟",s:0,t:"Ja, eine Frage: Bekomme ich meine restlichen Urlaubstage ausgezahlt?"},{ar:"نعم، سنرتّب ذلك. لو أخذتَ الإجازة في وقت أبكر لكان أسهل، لكن لا مشكلة.",s:1,t:"Ja, das regeln wir. Wenn Sie den Urlaub früher genommen hätten, wäre das einfacher gewesen, aber es ist kein Problem."},{ar:"شكرًا. لديّ أيضًا ساعات إضافية يمكنني تعويضها.",s:0,t:"Danke. Ich hätte sonst noch Überstunden, die ich abbauen könnte."},{ar:"سننظر في ذلك معًا. كنتُ أتمنى أن تبقى، لكنني أفهم قرارك.",s:1,t:"Wir schauen uns das gemeinsam an. Ich hätte mir gewünscht, dass Sie bleiben, aber ich verstehe Ihre Entscheidung."},{ar:"شكرًا جزيلًا على تفهّمك. تعلّمتُ هنا الكثير وأنا ممتن لهذه الفترة.",s:0,t:"Vielen Dank für Ihr Verständnis. Ich habe hier viel gelernt und bin dankbar für die Zeit."},{ar:"هذا يسعدني. سنفتقدك، وأتمنى لك كل الخير.",s:1,t:"Das freut mich. Wir werden Sie vermissen, und ich wünsche Ihnen alles Gute."},{ar:"شكرًا، هذا يعني لي الكثير. سأودّع الفريق في الأسبوع الأخير.",s:0,t:"Danke, das bedeutet mir viel. Ich verabschiede mich dann vom Team in der letzten Woche."},{ar:"فكرة جيدة. سننظّم أيضًا حفل وداع صغير لك.",s:1,t:"Gute Idee. Wir organisieren auch eine kleine Abschiedsfeier für Sie."},{ar:"هذا لطيف جدًا. أتطلع إلى ذلك، وشكرًا على الحوار الصريح.",s:0,t:"Das ist sehr nett. Ich freue mich darauf, und danke für das offene Gespräch."},{ar:"على الرحب والسعة. كل التوفيق في طريقك الجديد!",s:1,t:"Gern geschehen. Alles Gute für Ihren neuen Weg!"}]},emoji:"📄",grammar:{covers:1,id:"de-b2-konjunktiv2-vergangenheit",title:"Konjunktiv II in der Vergangenheit",titleAr:"صيغة التمني في الماضي"},stage:2,title:"الاستقالة",topic:"jobs",topicAr:"المهن والعمل",topicDe:"Kündigung",topicEn:"Resignation"},{conv:{id:"de-stage3-b2",speakers:["Umweltschützerin (ناشطة بيئية)","Skeptiker (مشكك)"],turns:[{ar:"مساء الخير، يسعدني أنك تشارك في هذا النقاش حول حماية البيئة.",s:0,t:"Guten Abend, schön, dass Sie an dieser Diskussion über Umweltschutz teilnehmen."},{ar:"مساء الخير. أنا متشوق، رغم أن لديّ رأيًا مختلفًا في هذا الموضوع.",s:1,t:"Guten Abend. Ich bin gespannt, auch wenn ich bei diesem Thema eine andere Meinung habe."},{ar:"هذا جيد، لأن النقاش الصادق يحتاج إلى وجهات نظر مختلفة. ورغم أن الوضع خطير، ما زال هناك أمل.",s:0,t:"Das ist gut so, denn eine ehrliche Diskussion braucht verschiedene Standpunkte. Obwohl die Lage ernst ist, gibt es noch Hoffnung."},{ar:"خطير، نعم، لكنني أتساءل إن كانت الإجراءات فعالة حقًا كما يُزعم.",s:1,t:"Ernst, ja, aber ich frage mich, ob die Maßnahmen wirklich so wirksam sind, wie behauptet wird."},{ar:"العلم واضح: رغم أننا نعرف الكثير بالفعل، ما زلنا نتحرك ببطء شديد.",s:0,t:"Die Wissenschaft ist eindeutig: Obwohl wir schon viel wissen, handeln wir immer noch zu langsam."},{ar:"حتى لو كانت البيانات صحيحة، لا يجوز تجاهل التكاليف على الناس.",s:1,t:"Auch wenn die Daten stimmen, darf man die Kosten für die Menschen nicht ignorieren."},{ar:"هذا صحيح، ومع ذلك يجب أن نفكّر في تكلفة عدم فعل شيء، وهي أعلى بكثير.",s:0,t:"Das stimmt, trotzdem müssen wir die Kosten des Nichtstuns bedenken, und die sind viel höher."},{ar:"ومع ذلك أتساءل: رغم أن الطاقات المتجددة جيدة، فهي ليست موثوقة في كل مكان.",s:1,t:"Trotzdem frage ich mich: Wenngleich erneuerbare Energien gut sind, sind sie nicht überall zuverlässig."},{ar:"كان ذلك مشكلة في السابق، رغم أن التقنية تحسّنت كثيرًا في هذه الأثناء.",s:0,t:"Das war früher ein Problem, obwohl die Technik sich inzwischen stark verbessert hat."},{ar:"حتى لو تحسّنت التقنية، تبقى الكهرباء من الرياح والشمس معتمدةً على الطقس.",s:1,t:"Auch wenn die Technik besser ist, bleibt Strom aus Wind und Sonne wetterabhängig."},{ar:"صحيح، ومع ذلك يمكن للبطاريات والشبكات الذكية أن تحل هذه المشكلة إلى حد كبير.",s:0,t:"Richtig, dennoch können Speicher und intelligente Netze dieses Problem weitgehend lösen."},{ar:"رغم أنني أفهم ذلك، أخشى أن الشركات الصغيرة لا تستطيع دفع تكاليف هذا التحول.",s:1,t:"Obwohl ich das verstehe, fürchte ich, dass kleine Unternehmen die Umstellung nicht bezahlen können."},{ar:"لذلك نحتاج إلى دعم مالي. حتى لو أنفقت الدولة المال، فإنها توفّر على المدى الطويل أكثر بكثير.",s:0,t:"Deshalb brauchen wir Förderungen. Auch wenn der Staat Geld ausgibt, spart er langfristig viel mehr."},{ar:"ومع ذلك يبقى السؤال: من الذي يدفع الفاتورة في النهاية؟",s:1,t:"Trotzdem bleibt die Frage, wer am Ende die Rechnung bezahlt."},{ar:"نحن جميعًا، سواء أردنا أم لا، لأن عواقب تغيّر المناخ تصيبنا جميعًا.",s:0,t:"Wir alle, ob wir wollen oder nicht, denn die Folgen des Klimawandels treffen uns alle."},{ar:"رغم أنني أرى الخطر، لا أعتقد أن الحظر هو الحل الأفضل.",s:1,t:"Obwohl ich die Gefahr sehe, glaube ich nicht, dass Verbote die beste Lösung sind."},{ar:"الحظر وحده لا يكفي، هذا صحيح. ومع ذلك نحتاج إلى قواعد واضحة، حتى لو كانت مزعجة.",s:0,t:"Verbote allein reichen nicht, das stimmt. Dennoch brauchen wir klare Regeln, auch wenn sie unbequem sind."},{ar:"حتى لو ساعدت القواعد، يجب أن تكون الحوافز في المقدمة، لا العقوبات.",s:1,t:"Auch wenn Regeln helfen, sollten Anreize im Mittelpunkt stehen, nicht Strafen."},{ar:"أوافقك في ذلك، رغم أن الحوافز بدون قواعد غالبًا ما تكون بطيئة الأثر.",s:0,t:"Da stimme ich Ihnen zu, obwohl Anreize ohne Regeln oft zu langsam wirken."},{ar:"ربما. رغم أنني متشكك، أجد اقتراحك بشأن الدعم المالي معقولًا.",s:1,t:"Vielleicht. Wenngleich ich skeptisch bin, finde ich Ihren Vorschlag mit den Förderungen vernünftig."},{ar:"شكرًا. رغم أننا نختلف في أمور كثيرة، فنحن متفقون في هذه النقطة.",s:0,t:"Danke. Obwohl wir uns in vielem unterscheiden, sind wir uns in diesem Punkt einig."},{ar:"موافق. لكن ماذا عن النقل؟ حتى لو تخلّى الكثيرون عن السيارة، يبقى الطيران مشكلة.",s:1,t:"Einverstanden. Aber was ist mit dem Verkehr? Auch wenn viele aufs Auto verzichten, bleibt der Flugverkehr ein Problem."},{ar:"صحيح، ومع ذلك يمكننا باستعمال نقل عام أفضل أن نستبدل الكثير من رحلات السيارات.",s:0,t:"Richtig, trotzdem können wir mit besserem Nahverkehr viele Autofahrten ersetzen."},{ar:"رغم أن النقل العام في المدينة جيد، فهو يكاد يكون غائبًا تمامًا في الريف.",s:1,t:"Obwohl der Nahverkehr in der Stadt gut ist, fehlt er auf dem Land fast völlig."},{ar:"لهذا السبب بالذات يجب الاستثمار هناك، حتى لو كان ذلك مكلفًا.",s:0,t:"Genau deshalb muss man dort investieren, auch wenn das teuer ist."},{ar:"ومع ذلك أشك في أن جميع الناس سيغيّرون سلوكهم بسرعة.",s:1,t:"Trotzdem bezweifle ich, dass alle Menschen ihr Verhalten schnell ändern werden."},{ar:"السلوك يتغير ببطء، هذا صحيح. ورغم أنه يسير ببطء، نرى بالفعل تقدمًا.",s:0,t:"Verhalten ändert sich langsam, das ist wahr. Obwohl es langsam geht, sehen wir schon Fortschritte."},{ar:"ما التقدم الذي تقصده؟ حتى لو أصبحت الكهرباء أنظف، يستمر الاستهلاك في النمو.",s:1,t:"Welche Fortschritte meinen Sie? Auch wenn der Strom sauberer wird, wächst der Verbrauch weiter."},{ar:"هذا تناقض، ومع ذلك تنخفض الانبعاثات للفرد في كثير من البلدان.",s:0,t:"Das ist ein Widerspruch, trotzdem sinken die Emissionen pro Person in vielen Ländern."},{ar:"رغم أن هذا صحيح، فهو لا يكفي لتحقيق أهداف المناخ.",s:1,t:"Obwohl das stimmt, reicht es nicht, um die Klimaziele zu erreichen."},{ar:"أنت محق في ذلك. لذلك يجب أن نفعل المزيد، حتى لو كان مرهقًا.",s:0,t:"Da haben Sie recht. Deshalb müssen wir mehr tun, auch wenn es anstrengend ist."},{ar:"رغم أنني أشاركك قلقك، أجد أنه لا يجوز أن نعرّض الاقتصاد للخطر.",s:1,t:"Wenngleich ich Ihre Sorge teile, finde ich, dass wir die Wirtschaft nicht gefährden dürfen."},{ar:"حماية البيئة والاقتصاد لا يتعارضان. ورغم أن التغيير يكلّف المال، فهو يخلق أيضًا وظائف جديدة.",s:0,t:"Umweltschutz und Wirtschaft schließen sich nicht aus. Obwohl der Wandel Geld kostet, schafft er auch neue Arbeitsplätze."},{ar:"حتى لو نشأت وظائف جديدة، يفقد آخرون وظائفهم القديمة.",s:1,t:"Auch wenn neue Jobs entstehen, verlieren andere Menschen ihre alten Stellen."},{ar:"لذلك نحتاج إلى إعادة تأهيل. ومع ذلك فإن الجمود ليس حلًا.",s:0,t:"Deshalb brauchen wir Umschulungen. Trotzdem ist Stillstand keine Lösung."},{ar:"أدرك ذلك، حتى لو كنتُ أتمنى انتقالًا أبطأ.",s:1,t:"Das sehe ich ein, auch wenn ich mir einen langsameren Übergang wünschen würde."},{ar:"الانتقال البطيء أفضل من لا شيء. ورغم أن الوقت يضغط علينا، يمكننا التقدم خطوة بخطوة.",s:0,t:"Ein langsamer Übergang ist besser als keiner. Obwohl die Zeit drängt, können wir Schritt für Schritt vorgehen."},{ar:"يمكنني أن أقبل بذلك. ورغم أنني أبقى متشككًا، كان هذا النقاش مفيدًا.",s:1,t:"Damit kann ich leben. Wenngleich ich skeptisch bleibe, war diese Diskussion nützlich."},{ar:"هذا يسعدني. رغم أننا لا نتفق في كل شيء، فقد استمعنا إلى بعضنا.",s:0,t:"Das freut mich. Obwohl wir nicht in allem übereinstimmen, haben wir einander zugehört."},{ar:"بالضبط، ومع ذلك وجدنا نقطة مشتركة: العمل ضروري.",s:1,t:"Genau, und trotzdem haben wir einen gemeinsamen Punkt gefunden: Handeln ist nötig."},{ar:"إذن لنثبّت هذه النقطة ولنتحدث في المرة القادمة عن اقتراحات ملموسة.",s:0,t:"Dann lassen Sie uns diesen Punkt festhalten und beim nächsten Mal über konkrete Vorschläge sprechen."},{ar:"بكل سرور. شكرًا جزيلًا على الحوار العادل!",s:1,t:"Gerne. Vielen Dank für das faire Gespräch!"}]},emoji:"🌍",grammar:{covers:1,id:"de-b2-konzessivsaetze",title:"Konzessivsätze",titleAr:"جمل التنازل (obwohl…)"},stage:3,title:"نقاش: حماية البيئة",topic:"environment",topicAr:"البيئة والطبيعة",topicDe:"Diskussion: Umweltschutz",topicEn:"Debate: environmental protection"},{conv:{id:"de-stage4-b2",speakers:["Beschwerdeführer (المشتكي)","Kundendienstmitarbeiterin (موظفة خدمة الزبائن)"],turns:[{ar:"مرحبًا، أتصل بخصوص شكواي من يوم الاثنين الماضي. فيما يتعلق بطلبي، هناك مشكلة خطيرة.",s:0,t:"Guten Tag, ich rufe an wegen meiner Beschwerde vom letzten Montag. Im Hinblick auf meine Bestellung gibt es ein ernstes Problem."},{ar:"مرحبًا، يؤسفني سماع ذلك. فيما يخص طلبك يمكنني مساعدتك بسرور. ما رقم الزبون الخاص بك؟",s:1,t:"Guten Tag, es tut mir leid, das zu hören. In Bezug auf Ihre Bestellung kann ich Ihnen gerne weiterhelfen. Wie ist Ihre Kundennummer?"},{ar:"رقم الزبون الخاص بي هو 48219. وبسبب خطأ ما، تلقّيتُ جهازًا تالفًا.",s:0,t:"Meine Kundennummer ist 48219. Aufgrund eines Fehlers habe ich ein beschädigtes Gerät erhalten."},{ar:"شكرًا جزيلًا. ورغم الإزعاج، سأراجع طلبك فورًا.",s:1,t:"Vielen Dank. Trotz der Unannehmlichkeiten werde ich Ihr Anliegen sofort prüfen."},{ar:"آمل ذلك. وعلى عكس إعلانكم، لم يكن الجهاز جديدًا، بل مستعملًا ومخدوشًا.",s:0,t:"Das hoffe ich. Im Gegensatz zu Ihrer Werbung war das Gerät nicht neu, sondern gebraucht und zerkratzt."},{ar:"هذا غير مقبول. وبالنظر إلى الصور التي أرسلتَها مع الشكوى، أرى الضرر بوضوح.",s:1,t:"Das ist inakzeptabel. Mit Blick auf Ihre Fotos, die Sie mitgeschickt haben, sehe ich den Schaden deutlich."},{ar:"بالضبط. إضافة إلى ذلك، تأخر التسليم ثلاثة أيام، وذلك رغم وعدكم بتسليم سريع.",s:0,t:"Genau. Außerdem war die Lieferung drei Tage verspätet, und das trotz Ihrer Zusage einer schnellen Lieferung."},{ar:"يؤسفني ذلك جدًا. وفي إطار ضماننا، يحق لك الحصول على بديل أو استرداد المبلغ.",s:1,t:"Das tut mir sehr leid. Im Rahmen unserer Garantie haben Sie Anspruch auf Ersatz oder Erstattung."},{ar:"أريد جهازًا بديلًا، لكن فقط بشرط أن يتم فحص الجهاز الجديد.",s:0,t:"Ich möchte einen Ersatz, aber nur unter der Bedingung, dass das neue Gerät geprüft wird."},{ar:"بالطبع. في هذه الحالة سنرسل لك جهازًا مفحوصًا ونتحمّل تكاليف الإرجاع.",s:1,t:"Selbstverständlich. In diesem Fall schicken wir Ihnen ein geprüftes Gerät und übernehmen die Rücksendung."},{ar:"حسنًا. وماذا عن التكاليف؟ وبسبب التأخير فاتني موعد مهم.",s:0,t:"Gut. Was ist mit den Kosten? Ich habe aufgrund der Verzögerung einen wichtigen Termin verpasst."},{ar:"أفهم ذلك. وفيما يتعلق بالضرر الحاصل، يمكنني أن أعرض عليك قسيمة إضافية.",s:1,t:"Das verstehe ich. Im Hinblick auf den entstandenen Schaden kann ich Ihnen zusätzlich einen Gutschein anbieten."},{ar:"القسيمة لطيفة، لكن فيما يتعلق بوقتي وجهدي فهذا لا يكفي.",s:0,t:"Ein Gutschein ist nett, aber in Bezug auf meine Zeit und meine Mühe ist das nicht genug."},{ar:"أفهم غضبك. ونظرًا للظروف، سأتحدث مع مشرفتي عن تعويض إضافي.",s:1,t:"Ich verstehe Ihren Ärger. Aufgrund der Umstände spreche ich mit meiner Vorgesetzten über eine weitere Entschädigung."},{ar:"شكرًا، هذا سيكون عادلًا. سأكتب شكواي أيضًا في رسالة رسمية، بهدف الحصول على تأكيد كتابي.",s:0,t:"Danke, das wäre fair. Ich schreibe meine Beschwerde auch in einem formellen Brief, mit Blick auf eine schriftliche Bestätigung."},{ar:"هذه فكرة جيدة. وعلى عكس المكالمة، تبقى الرسالة دليلًا.",s:1,t:"Das ist eine gute Idee. Im Gegensatz zu einem Anruf bleibt ein Brief als Nachweis bestehen."},{ar:"بالضبط. هل يمكنك من فضلك أن تخبريني لمن أرسل الرسالة في حال حدوث تأخير آخر؟",s:0,t:"Genau. Könnten Sie mir bitte sagen, an wen ich den Brief im Falle einer weiteren Verzögerung schicken soll?"},{ar:"بالطبع. أرسلها إلى قسم الشكاوى لدينا، مع ذكر رقم الزبون وتاريخ الطلب.",s:1,t:"Natürlich. Senden Sie ihn an unsere Beschwerdeabteilung, unter Angabe Ihrer Kundennummer und des Bestelldatums."},{ar:"واضح تمامًا. آمل أن تُحل المسألة خلال أسبوع واحد.",s:0,t:"Alles klar. Ich hoffe, dass die Angelegenheit innerhalb von einer Woche gelöst wird."},{ar:"هذا هو هدفنا. وفي غضون الأيام الثلاثة القادمة ستتلقى تأكيدًا كتابيًا منا.",s:1,t:"Das ist unser Ziel. Im Laufe der nächsten drei Tage erhalten Sie eine schriftliche Bestätigung von uns."},{ar:"والجهاز البديل؟ متى سيصل فيما يتعلق بوقت التسليم؟",s:0,t:"Und das Ersatzgerät? Wann wird es im Hinblick auf die Lieferzeit ankommen?"},{ar:"سيُشحن الجهاز البديل خلال خمسة أيام عمل، رغم الطلب المرتفع حاليًا.",s:1,t:"Das Ersatzgerät wird innerhalb von fünf Werktagen verschickt, trotz der hohen Nachfrage im Moment."},{ar:"هذا مقبول. لكنني أتوقع أن يعمل الجهاز الجديد، على عكس القديم، بشكل لا تشوبه شائبة.",s:0,t:"Das ist akzeptabel. Aber ich erwarte, dass das neue Gerät im Gegensatz zum alten einwandfrei funktioniert."},{ar:"أضمن لك ذلك. قبل الشحن سيُفحص في إطار مراقبة الجودة لدينا.",s:1,t:"Das garantiere ich Ihnen. Vor dem Versand wird es im Rahmen unserer Qualitätskontrolle geprüft."},{ar:"جيد جدًا. ماذا يحدث إذا كان الجهاز البديل تالفًا أيضًا؟",s:0,t:"Sehr gut. Was passiert, wenn das Ersatzgerät ebenfalls beschädigt ist?"},{ar:"في هذه الحالة ستحصل فورًا على استرداد كامل، دون إجراءات إضافية.",s:1,t:"In diesem Fall erhalten Sie sofort eine vollständige Erstattung, ohne weitere Formalitäten."},{ar:"هذا يطمئنني. أريد أن أشكرك مرة أخرى على صبرك، رغم كلماتي الواضحة.",s:0,t:"Das beruhigt mich. Ich möchte mich noch einmal für Ihre Geduld bedanken, trotz meiner deutlichen Worte."},{ar:"لا مشكلة، هذا جزء من مهمتي. شكواك تساعدنا على التحسّن فيما يتعلق بجودتنا.",s:1,t:"Kein Problem, das gehört zu meiner Aufgabe. Ihre Beschwerde hilft uns, im Hinblick auf unsere Qualität besser zu werden."},{ar:"يسعدني سماع ذلك. آمل ألا يضطر زبائن آخرون إلى خوض التجربة نفسها.",s:0,t:"Das freut mich zu hören. Ich hoffe, dass andere Kunden nicht dieselbe Erfahrung machen müssen."},{ar:"نأخذ ذلك على محمل الجد. وبسبب شكواك نراجع الآن عملية الشحن بأكملها.",s:1,t:"Wir nehmen das sehr ernst. Aufgrund Ihrer Beschwerde prüfen wir jetzt den gesamten Versandprozess."},{ar:"هذه خطوة جيدة. هل يمكنك من فضلك أن ترسلي لي ملخصًا بالبريد الإلكتروني؟",s:0,t:"Das ist ein guter Schritt. Können Sie mir bitte eine Zusammenfassung per E-Mail schicken?"},{ar:"بالطبع. سأرسل لك اليوم بريدًا إلكترونيًا يتضمن جميع الاتفاقات والمواعيد.",s:1,t:"Selbstverständlich. Ich schicke Ihnen heute noch eine E-Mail mit allen Vereinbarungen und Fristen."},{ar:"شكرًا جزيلًا. سأرسل رسالة الشكوى رغم ذلك، كتكملة كتابية لهذا الحديث.",s:0,t:"Vielen Dank. Ich werde den Beschwerdebrief trotzdem abschicken, als schriftliche Ergänzung zu diesem Gespräch."},{ar:"هذا حقك الكامل. من فضلك اذكر في الرسالة أيضًا اتفاقنا اليوم.",s:1,t:"Das ist Ihr gutes Recht. Bitte erwähnen Sie im Brief auch unsere heutige Absprache."},{ar:"سأفعل ذلك. سألخّص: جهاز بديل، وقسيمة، ومراجعة للتعويض.",s:0,t:"Das werde ich tun. Ich fasse zusammen: Ersatzgerät, Gutschein und eine Prüfung der Entschädigung."},{ar:"بالضبط. وفي حال وجود أسئلة يمكنك الوصول إليّ مباشرة على هذا الرقم.",s:1,t:"Genau. Und im Falle von Fragen können Sie mich direkt unter dieser Nummer erreichen."},{ar:"ممتاز. آمل أن نتمكن من حل الأمر باتفاق جيد.",s:0,t:"Perfekt. Ich hoffe, dass wir die Sache in gutem Einvernehmen lösen können."},{ar:"أنا مقتنعة بذلك. شكرًا جزيلًا على صبرك وثقتك.",s:1,t:"Davon bin ich überzeugt. Vielen Dank für Ihre Geduld und Ihr Vertrauen."},{ar:"شكرًا لك. أتمنى لك يومًا سعيدًا!",s:0,t:"Danke Ihnen. Ich wünsche Ihnen noch einen schönen Tag!"},{ar:"ولك أيضًا، وسنتواصل معك في الأيام القادمة!",s:1,t:"Ihnen auch, und wir melden uns in den nächsten Tagen bei Ihnen!"},{ar:"إلى اللقاء!",s:0,t:"Auf Wiederhören!"},{ar:"إلى اللقاء!",s:1,t:"Auf Wiederhören!"}]},emoji:"✉️",grammar:{covers:1,id:"de-b2-praepositionale-ausdruecke",title:"Präpositionale Ausdrücke",titleAr:"التعابير بحروف الجر"},stage:4,title:"رسالة شكوى رسمية",topic:"services",topicAr:"الخدمات والطوارئ",topicDe:"Beschwerdebrief",topicEn:"Formal complaint letter"},{conv:{id:"de-stage5-b2",speakers:["Projektleiterin (مديرة المشروع)","Kollege (زميل)"],turns:[{ar:"صباح الخير، سيد ويبر. شكرًا جزيلًا لأنك خصصت وقتًا للاطلاع على مشروعنا الجديد.",s:0,t:"Guten Morgen, Herr Weber. Vielen Dank, dass Sie sich für die Vorstellung unseres neuen Projekts Zeit genommen haben."},{ar:"صباح الخير، سيدة شنايدر. أنا متحمس جدًا للعرض وللتخطيط للخطوات التالية.",s:1,t:"Guten Morgen, Frau Schneider. Ich bin sehr gespannt auf die Präsentation und auf die Planung der nächsten Schritte."},{ar:"مشروعنا يهتم بتطوير منصة رقمية لعملائنا في جميع أنحاء البلاد.",s:0,t:"Unser Projekt beschäftigt sich mit der Entwicklung einer digitalen Plattform für unsere Kunden im ganzen Land."},{ar:"تطوير منصة كهذه يبدو طموحًا. ما الهدف الرئيسي من إطلاقها؟",s:1,t:"Die Entwicklung einer solchen Plattform klingt ehrgeizig. Was ist das Hauptziel der Einführung?"},{ar:"الهدف هو تحسين خدمة العملاء وتبسيط طلب منتجاتنا.",s:0,t:"Das Ziel ist die Verbesserung des Kundenservice und die Vereinfachung der Bestellung unserer Produkte."},{ar:"تحسين الخدمة مهم بالتأكيد. كم تستغرق مدة تنفيذ المشروع؟",s:1,t:"Die Verbesserung des Service ist sicher wichtig. Wie lange dauert die Umsetzung des Projekts?"},{ar:"التنفيذ يستغرق نحو ثمانية أشهر، من التخطيط حتى نشر المنصة.",s:0,t:"Die Durchführung dauert etwa acht Monate, von der Planung bis zur Veröffentlichung der Plattform."},{ar:"ثمانية أشهر مدة واقعية. من المسؤول عن قيادة كل مرحلة؟",s:1,t:"Acht Monate sind realistisch. Wer ist für die Leitung der einzelnen Phasen verantwortlich?"},{ar:"قيادة المرحلة التقنية يتولاها السيد براندت، وتصميم الواجهة عند السيدة ليمان.",s:0,t:"Die Leitung der technischen Phase übernimmt Herr Brandt, und die Gestaltung der Oberfläche liegt bei Frau Lehmann."},{ar:"التعاون بين التقنية والتصميم حاسم. كم مرة يتم التنسيق؟",s:1,t:"Die Zusammenarbeit zwischen Technik und Gestaltung ist entscheidend. Wie oft findet die Abstimmung statt?"},{ar:"تنسيق الفرق يتم كل أسبوع في اجتماع قصير صباح الاثنين.",s:0,t:"Die Abstimmung der Teams erfolgt jede Woche in einer kurzen Besprechung am Montagmorgen."},{ar:"هذا حل جيد. ما تكلفة تنفيذ المشروع؟",s:1,t:"Das ist eine gute Lösung. Wie hoch sind die Kosten für die Realisierung des Projekts?"},{ar:"حساب التكاليف يصل إلى نحو 250 ألف يورو، بما فيها تدريب الموظفين.",s:0,t:"Die Berechnung der Kosten ergibt etwa 250.000 Euro, einschließlich der Schulung der Mitarbeiter."},{ar:"لا يجوز الاستهانة بتدريب الموظفين. متى يبدأ تطبيق البرنامج الجديد؟",s:1,t:"Die Schulung der Mitarbeiter darf man nicht unterschätzen. Wann beginnt die Einführung der neuen Software?"},{ar:"إطلاق البرنامج مخطط له في سبتمبر، بعد اختبار جميع الوظائف.",s:0,t:"Die Einführung der Software ist für den September geplant, nach der Testung aller Funktionen."},{ar:"اختبار الوظائف مهم جدًا. من يتولى تقييم نتائج الاختبار؟",s:1,t:"Die Testung der Funktionen ist sehr wichtig. Wer übernimmt die Auswertung der Testergebnisse?"},{ar:"تقييم النتائج يقوم به فريق الجودة لدينا، وإصلاح الأخطاء يستغرق نحو أسبوعين.",s:0,t:"Die Auswertung der Ergebnisse macht unser Qualitätsteam, und die Behebung der Fehler dauert etwa zwei Wochen."},{ar:"إصلاح الأخطاء قبل الانطلاق ضروري تمامًا. هل توجد أيضًا دراسة للمخاطر؟",s:1,t:"Die Behebung der Fehler vor dem Start ist unbedingt nötig. Gibt es auch eine Analyse der Risiken?"},{ar:"نعم، تحليل المخاطر يُظهر ثلاث مشكلات محتملة: التأخير، وارتفاع التكاليف، والصعوبات التقنية.",s:0,t:"Ja, die Analyse der Risiken zeigt drei mögliche Probleme: Verzögerungen, höhere Kosten und technische Schwierigkeiten."},{ar:"تجنب التأخير يعتمد على التخطيط. كيف نتصرف عند حدوث مشكلات؟",s:1,t:"Die Vermeidung von Verzögerungen hängt von der Planung ab. Wie reagieren wir bei Problemen?"},{ar:"عند حدوث مشكلات يتم إبلاغ الإدارة فورًا، ويُقرَّر تعديل الجدول الزمني معًا.",s:0,t:"Bei Problemen erfolgt die Information der Geschäftsführung sofort, und die Anpassung des Zeitplans wird gemeinsam beschlossen."},{ar:"تعديل الجدول الزمني يجب أن يكون شفافًا. ماذا يتوقع العملاء من المنصة الجديدة؟",s:1,t:"Die Anpassung des Zeitplans muss transparent sein. Was erwarten die Kunden von der neuen Plattform?"},{ar:"استطلاع العملاء يُظهر أنهم يريدون طلبًا سريعًا ودفعًا سهلًا.",s:0,t:"Die Befragung der Kunden zeigt, dass sie eine schnelle Bestellung und eine einfache Bezahlung wünschen."},{ar:"تبسيط الدفع سيقنع كثيرًا من العملاء. هل ستكون هناك أيضًا تطبيقات للهاتف؟",s:1,t:"Die Vereinfachung der Bezahlung wird viele Kunden überzeugen. Wird es auch eine App für das Handy geben?"},{ar:"نعم، تطوير التطبيق يسير بالتوازي مع تطوير الموقع، ليتمكنا من الانطلاق معًا.",s:0,t:"Ja, die Entwicklung der App läuft parallel zur Entwicklung der Webseite, damit beide gleichzeitig starten können."},{ar:"نشر النسختين في اليوم نفسه إشارة قوية. كيف نقيس النجاح؟",s:1,t:"Die Veröffentlichung beider Versionen am gleichen Tag ist ein starkes Signal. Wie messen wir den Erfolg?"},{ar:"قياس النجاح يتم من خلال عدد الطلبات ورضا العملاء بعد ثلاثة أشهر.",s:0,t:"Die Messung des Erfolgs erfolgt durch die Zahl der Bestellungen und die Zufriedenheit der Kunden nach drei Monaten."},{ar:"قياس رضا العملاء يجب أن يتم بانتظام. من المسؤول عن رعاية العملاء؟",s:1,t:"Die Erhebung der Kundenzufriedenheit sollte regelmäßig stattfinden. Wer ist für die Betreuung der Kunden zuständig?"},{ar:"رعاية العملاء يتولاها فريق الخدمة لدينا، الذي سيُدرَّب على الإجابة عن كل الأسئلة.",s:0,t:"Die Betreuung der Kunden übernimmt unser Serviceteam, das für die Beantwortung aller Fragen geschult wird."},{ar:"تدريب فريق الخدمة استثمار جيد. هل ما زالت هناك أسئلة مفتوحة حول التمويل؟",s:1,t:"Die Schulung des Serviceteams ist eine gute Investition. Gibt es noch offene Fragen zur Finanzierung?"},{ar:"تمويل المشروع مضمون، وموافقة الإدارة موجودة بالفعل.",s:0,t:"Die Finanzierung des Projekts ist gesichert, und die Genehmigung der Geschäftsführung liegt bereits vor."},{ar:"موافقة الإدارة شرط مهم. متى الاجتماع التالي؟",s:1,t:"Die Genehmigung der Geschäftsführung ist eine wichtige Voraussetzung. Wann ist die nächste Besprechung?"},{ar:"الاجتماع التالي لمراجعة التقدم سيكون بعد أسبوعين.",s:0,t:"Die nächste Besprechung zur Überprüfung des Fortschritts findet in zwei Wochen statt."},{ar:"أرى أن مراجعة التقدم كل أسبوعين أمر منطقي. هل يمكنني الحصول على العرض التقديمي؟",s:1,t:"Die Überprüfung des Fortschritts alle zwei Wochen halte ich für sinnvoll. Kann ich die Präsentation bekommen?"},{ar:"بالطبع، سيتم إرسال العرض التقديمي عصر اليوم بالبريد الإلكتروني إلى جميع المعنيين.",s:0,t:"Natürlich, die Zusendung der Präsentation erfolgt heute Nachmittag per E-Mail an alle Beteiligten."},{ar:"إرسال المواد يساعدني في التحضير. هل توجد خلاصة لأهم النقاط؟",s:1,t:"Die Zusendung der Unterlagen hilft mir bei der Vorbereitung. Gibt es eine Zusammenfassung der wichtigsten Punkte?"},{ar:"نعم، ستجد خلاصة أهم القرارات في الصفحة الأخيرة من العرض.",s:0,t:"Ja, die Zusammenfassung der wichtigsten Entscheidungen finden Sie auf der letzten Seite der Präsentation."},{ar:"سأطّلع على الخلاصة بدقة. أجد التخطيط مقنعًا جدًا بشكل عام.",s:1,t:"Die Zusammenfassung werde ich mir genau ansehen. Ich finde die Planung insgesamt sehr überzeugend."},{ar:"شكرًا جزيلًا على ثقتك وعلى دعم المشروع منذ البداية.",s:0,t:"Vielen Dank für Ihr Vertrauen und für die Unterstützung des Projekts von Anfang an."},{ar:"دعم المشروع أمر بديهي لقسمنا. أتطلع إلى التنفيذ.",s:1,t:"Die Unterstützung des Projekts ist für unsere Abteilung selbstverständlich. Ich freue mich auf die Umsetzung."},{ar:"إذن ألخص: الموافقة موجودة، والتنفيذ يبدأ الأسبوع المقبل، والنشر مخطط له في سبتمبر.",s:0,t:"Dann fasse ich zusammen: Die Genehmigung liegt vor, die Durchführung beginnt nächste Woche, und die Veröffentlichung ist für September geplant."},{ar:"الخلاصة واضحة. أشكرك على العرض المفصل وأتمنى للفريق كل التوفيق.",s:1,t:"Die Zusammenfassung ist klar. Ich danke Ihnen für die ausführliche Vorstellung und wünsche dem Team viel Erfolg."}]},emoji:"📊",grammar:{covers:1,id:"de-b2-nominalisierung",title:"Nominalisierung",titleAr:"تحويل الأفعال إلى أسماء"},stage:5,title:"عرض مشروع في اجتماع",topic:"jobs",topicAr:"المهن والعمل",topicDe:"Meeting: Projekt vorstellen",topicEn:"Presenting a project in a meeting"},{conv:{id:"de-stage6-b2",speakers:["Mandant (الموكّل)","Anwältin (المحامية)"],turns:[{ar:"نهارك سعيد، دكتورة هوفمان. شكرًا جزيلًا لأنك خصصت وقتًا لعقدي.",s:0,t:"Guten Tag, Frau Doktor Hoffmann. Vielen Dank, dass Sie sich für meinen Vertrag Zeit nehmen."},{ar:"نهارك سعيد. بكل سرور، لقد قرأت مسودة العقد بالفعل. هناك بعض النقاط التي يجب تغييرها.",s:1,t:"Guten Tag. Gern, ich habe den Vertragsentwurf bereits gelesen. Es gibt einige Punkte, die geändert werden müssen."},{ar:"هذا ما خشيته. أي بند يجب فحصه أولًا؟",s:0,t:"Das habe ich befürchtet. Welche Klausel muss zuerst geprüft werden?"},{ar:"أولًا يجب فحص مهلة الإنهاء بدقة. لا يمكن إنهاؤه إلا كتابيًا، والمهلة ثلاثة أشهر.",s:1,t:"Zuerst muss die Kündigungsfrist genau geprüft werden. Sie kann nur schriftlich gekündigt werden, und die Frist beträgt drei Monate."},{ar:"ثلاثة أشهر مدة طويلة. ألا يمكن تقصير المهلة؟",s:0,t:"Drei Monate sind lang. Kann die Frist nicht verkürzt werden?"},{ar:"يمكن تقصير المهلة، لكن فقط بموافقة الطرفين. ويجب الاتفاق على ذلك كتابيًا.",s:1,t:"Die Frist kann verkürzt werden, aber nur mit der Zustimmung beider Parteien. Das muss schriftlich vereinbart werden."},{ar:"مفهوم. وماذا عن الدفع؟ متى يجب تحويل المبلغ؟",s:0,t:"Verstanden. Was ist mit der Zahlung? Wann muss der Betrag überwiesen werden?"},{ar:"يجب تحويل المبلغ خلال 30 يومًا من إصدار الفاتورة. وعند التأخير يجب دفع فوائد تأخير.",s:1,t:"Der Betrag muss innerhalb von 30 Tagen nach Rechnungsstellung überwiesen werden. Bei Verzug müssen Verzugszinsen gezahlt werden."},{ar:"هذا عادل. هل يجوز إنهاء العقد مبكرًا إذا لم يُقدَّم الأداء؟",s:0,t:"Das ist fair. Darf der Vertrag auch vorzeitig beendet werden, wenn die Leistung nicht erbracht wird?"},{ar:"نعم، يمكن إنهاء العقد مبكرًا إذا لم يفِ أحد الطرفين بالتزاماته. لكن يجب التنبيه على ذلك كتابيًا مسبقًا.",s:1,t:"Ja, der Vertrag kann vorzeitig beendet werden, wenn eine Partei ihre Pflichten nicht erfüllt. Das muss aber vorher schriftlich angemahnt werden."},{ar:"من الجيد معرفة ذلك. كيف يجب تنظيم السرية؟ هل يجوز تمرير المعلومات؟",s:0,t:"Gut zu wissen. Wie soll die Vertraulichkeit geregelt werden? Dürfen Informationen weitergegeben werden?"},{ar:"لا يجوز تمرير المعلومات السرية إلى أطراف ثالثة. ويجب أن يلتزم الطرفان بذلك بصرامة.",s:1,t:"Vertrauliche Informationen dürfen nicht an Dritte weitergegeben werden. Das muss von beiden Seiten streng eingehalten werden."},{ar:"موافق. ماذا يحدث عند النزاع؟ هل يجب اللجوء إلى المحكمة فورًا؟",s:0,t:"Einverstanden. Was passiert bei einem Streit? Muss dann sofort ein Gericht eingeschaltet werden?"},{ar:"لا، أولًا يجب محاولة التوصل إلى اتفاق عبر المفاوضات. ولا يمكن اللجوء إلى المحكمة إلا إذا فشل ذلك.",s:1,t:"Nein, zuerst soll eine Einigung durch Verhandlungen versucht werden. Erst wenn das scheitert, kann ein Gericht angerufen werden."},{ar:"هذا يبدو معقولًا. هل يمكن تحديد المسؤولية في العقد؟",s:0,t:"Das klingt vernünftig. Kann die Haftung im Vertrag begrenzt werden?"},{ar:"يمكن تحديد المسؤولية، لكن ليس عن الأضرار التي تُسبَّب عمدًا. ولا يجوز استثناء ذلك.",s:1,t:"Die Haftung kann begrenzt werden, aber nicht für Schäden, die vorsätzlich verursacht wurden. Das darf nicht ausgeschlossen werden."},{ar:"أفهم. هل يجب أن يوقّع الطرفان العقد قبل أن يصبح ساريًا؟",s:0,t:"Verstehe. Muss der Vertrag von beiden Parteien unterschrieben werden, bevor er gültig ist?"},{ar:"نعم، يجب أن يوقّع الطرفان العقد. ولا يمكن اعتباره ساريًا إلا بعد ذلك.",s:1,t:"Ja, der Vertrag muss von beiden Parteien unterschrieben werden. Erst danach kann er als gültig betrachtet werden."},{ar:"هل يجب أن أوقّع العقد شخصيًا، أم يمكن توقيعه رقميًا أيضًا؟",s:0,t:"Soll ich den Vertrag persönlich unterschreiben, oder kann er auch digital unterschrieben werden?"},{ar:"يمكن توقيع العقد رقميًا أيضًا، إذا استُخدم توقيع إلكتروني مؤهل.",s:1,t:"Der Vertrag kann auch digital unterschrieben werden, wenn eine qualifizierte elektronische Signatur verwendet wird."},{ar:"هذا يسهّل كثيرًا. كم يجب أن تستمر مدة العقد؟",s:0,t:"Das erleichtert vieles. Wie lange soll der Vertrag gelten?"},{ar:"يجب أن يسري العقد أولًا لمدة سنتين. وبعدها يمكن تمديده سنة في كل مرة.",s:1,t:"Der Vertrag soll zunächst für zwei Jahre gelten. Danach kann er jeweils um ein Jahr verlängert werden."},{ar:"سنتان مناسبتان. هل يجوز تغيير العقد خلال هذه المدة؟",s:0,t:"Zwei Jahre sind in Ordnung. Darf der Vertrag während dieser Zeit geändert werden?"},{ar:"لا يجوز إجراء التغييرات إلا كتابيًا. ولا يمكن الاعتراف بالاتفاقات الشفهية كاتفاقات سارية.",s:1,t:"Änderungen dürfen nur schriftlich vorgenommen werden. Mündliche Absprachen können nicht als gültig anerkannt werden."},{ar:"هذا مهم. وماذا عن مواعيد التسليم؟ هل يجب الالتزام بها بدقة؟",s:0,t:"Das ist wichtig. Was ist mit den Lieferterminen? Müssen sie genau eingehalten werden?"},{ar:"نعم، يجب الالتزام بمواعيد التسليم بدقة. وعند التأخير يجب إبلاغ العميل فورًا.",s:1,t:"Ja, die Liefertermine müssen genau eingehalten werden. Bei Verzögerungen muss der Kunde sofort informiert werden."},{ar:"هل يمكن المطالبة بغرامة إذا تأخر التسليم؟",s:0,t:"Kann eine Strafe verlangt werden, wenn die Lieferung zu spät kommt?"},{ar:"يمكن المطالبة بغرامة تعاقدية إذا كانت محددة بوضوح في العقد. ويجب إضافة ذلك بالتأكيد.",s:1,t:"Eine Vertragsstrafe kann verlangt werden, wenn sie im Vertrag klar festgelegt wurde. Das sollte unbedingt ergänzt werden."},{ar:"من فضلك أضيفي هذه النقطة. هل ما زال هناك شيء يجب تغييره؟",s:0,t:"Bitte ergänzen Sie diesen Punkt. Gibt es noch etwas, das geändert werden muss?"},{ar:"نعم، يجب توضيح بند حقوق النشر أكثر. ويجب تنظيم الحقوق بوضوح.",s:1,t:"Ja, die Klausel über das Urheberrecht muss noch präzisiert werden. Die Rechte sollen klar geregelt werden."},{ar:"موافق. متى يمكن أن تكون الصيغة الجديدة من العقد جاهزة؟",s:0,t:"Einverstanden. Wann kann die neue Fassung des Vertrags fertig sein?"},{ar:"يمكن إنجاز الصيغة الجديدة بحلول يوم الجمعة. وبعدها يجب أن تفحصها مرة أخرى.",s:1,t:"Die neue Fassung kann bis Freitag fertiggestellt werden. Dann muss sie noch einmal von Ihnen geprüft werden."},{ar:"هذا يناسبني. هل يجب أن أوقّع التغييرات مباشرة بعد ذلك؟",s:0,t:"Das passt mir gut. Soll ich die Änderungen dann direkt unterschreiben?"},{ar:"لا، أولًا يجب أن يؤكد الطرفان كل التغييرات. ولا يجوز توقيع العقد إلا بعد ذلك.",s:1,t:"Nein, erst müssen alle Änderungen von beiden Seiten bestätigt werden. Erst danach darf der Vertrag unterschrieben werden."},{ar:"مفهوم. ما تكلفة استشارتك إجمالًا؟ هل يجب دفع المبلغ فورًا؟",s:0,t:"Verstanden. Was kostet Ihre Beratung insgesamt? Muss der Betrag sofort bezahlt werden?"},{ar:"يمكن إصدار الفاتورة بعد انتهاء العمل. ويجب دفعها بعد ذلك خلال 14 يومًا.",s:1,t:"Die Rechnung kann nach Abschluss der Arbeit gestellt werden. Sie muss dann innerhalb von 14 Tagen bezahlt werden."},{ar:"هذا عادل. هل يمكننا تحديد موعد التوقيع بالفعل؟",s:0,t:"Das ist fair. Können wir den Termin für die Unterzeichnung schon festlegen?"},{ar:"نعم، يمكن أن يتم التوقيع يوم الاثنين المقبل الساعة العاشرة في مكتبي. ويجب تجهيز كل المستندات حتى ذلك الحين.",s:1,t:"Ja, die Unterzeichnung kann nächsten Montag um 10 Uhr in meinem Büro stattfinden. Alle Unterlagen müssen bis dahin vorbereitet werden."},{ar:"الاثنين الساعة العاشرة يناسبني. أشكرك على الاستشارة المفصلة.",s:0,t:"Montag um 10 Uhr passt mir. Ich danke Ihnen für die ausführliche Beratung."},{ar:"على الرحب والسعة. وإذا ظهرت أسئلة أخرى، يمكن توضيحها هاتفيًا في أي وقت.",s:1,t:"Gern geschehen. Wenn noch Fragen auftauchen, können sie jederzeit telefonisch geklärt werden."},{ar:"شكرًا جزيلًا. يسعدني أن العقد سيتمكن من التوقيع قريبًا.",s:0,t:"Vielen Dank. Ich freue mich, dass der Vertrag bald unterschrieben werden kann."},{ar:"وأنا أيضًا. وبعد التوقيع يجب أن تُرسل إليك نسخة فورًا.",s:1,t:"Ich auch. Nach der Unterzeichnung soll Ihnen eine Kopie sofort zugeschickt werden."}]},emoji:"⚖️",grammar:{covers:1,id:"de-b2-passiv-modalverben",title:"Passiv mit Modalverben",titleAr:"المبني للمجهول مع الأفعال الناقصة"},stage:6,title:"العقد والمحامي",topic:"business",topicAr:"الأعمال والاقتصاد",topicDe:"Vertrag und Anwalt",topicEn:"Contract / lawyer"},{conv:{id:"de-stage7-b2",speakers:["Journalistin (الصحفية)","Medienexperte (خبير إعلام)"],turns:[{ar:"نهارك سعيد وأهلًا بك في نقاشنا حول وسائل التواصل الاجتماعي. ما رأيك في دورها في مجتمعنا؟",s:0,t:"Guten Tag und herzlich willkommen zu unserer Diskussion über soziale Medien. Was halten Sie von ihrer Rolle in unserer Gesellschaft?"},{ar:"شكرًا على الدعوة. يقول كثير من الباحثين إن وسائل التواصل الاجتماعي هي اليوم أهم مصدر للمعلومات لدى الشباب.",s:1,t:"Vielen Dank für die Einladung. Viele Forscher sagen, soziale Medien seien heute die wichtigste Informationsquelle für junge Menschen."},{ar:"هذا صحيح. لكن النقاد يزعمون أن المنصات تنشر أساسًا أخبارًا كاذبة وشائعات.",s:0,t:"Das stimmt. Kritiker behaupten aber, die Plattformen verbreiteten vor allem falsche Nachrichten und Gerüchte."},{ar:"هذا النقد مبرر جزئيًا. تُظهر الدراسات أن المعلومات الخاطئة تنتشر هناك أسرع من الأخبار الموثوقة.",s:1,t:"Diese Kritik ist teilweise berechtigt. Studien zeigen, dass Falschinformationen sich dort schneller verbreiteten als geprüfte Nachrichten."},{ar:"يطالب بعض السياسيين بأن تخضع الشركات لرقابة أشد. هل تشاركهم هذا المطلب؟",s:0,t:"Manche Politiker fordern, die Konzerne müssten stärker kontrolliert werden. Teilen Sie diese Forderung?"},{ar:"أعتقد أن الحكومة تعلن أنها تريد مزيدًا من الشفافية، لكنها لم تقدم حتى الآن قواعد واضحة.",s:1,t:"Ich denke, die Regierung erklärt, sie wolle mehr Transparenz, aber sie habe bisher keine klaren Regeln vorgelegt."},{ar:"تقول الشركات نفسها إنها تعمل بالفعل على مرشحات أفضل ضد الكراهية والعنف.",s:0,t:"Die Unternehmen selbst sagen, sie arbeiteten bereits an besseren Filtern gegen Hass und Gewalt."},{ar:"هذا ما تدعيه، لكن الخبراء يشككون في أن هذه المرشحات تكفي فعلًا. فالخوارزميات غالبًا ما تكون غير شفافة.",s:1,t:"Das behaupten sie, aber Experten bezweifeln, dass diese Filter wirklich ausreichten. Die Algorithmen seien oft undurchsichtig."},{ar:"يقول كثير من الأهل إن أطفالهم يقضون ساعات عدة يوميًا أمام الشاشة. هل هذا خطير؟",s:0,t:"Viele Eltern berichten, ihre Kinder verbrächten täglich mehrere Stunden vor dem Bildschirm. Ist das gefährlich?"},{ar:"يحذر الأطباء من أن الاستخدام المفرط قد يضعف التركيز ويعطل النوم. ويقولون إن الخطر مرتفع خاصة لدى المراهقين.",s:1,t:"Ärzte warnen, übermäßige Nutzung könne die Konzentration schwächen und den Schlaf stören. Das Risiko sei besonders bei Jugendlichen hoch."},{ar:"من ناحية أخرى، يقول الشباب أنفسهم إن وسائل التواصل تساعدهم على الحفاظ على الصداقات وعلى الاطلاع.",s:0,t:"Andererseits sagen Jugendliche selbst, soziale Medien hülfen ihnen, Freundschaften zu pflegen und sich zu informieren."},{ar:"هذه نقطة مهمة. ويقول المعلمون إن التلاميذ يستخدمون المنصات أيضًا للواجبات والمشاريع الجماعية.",s:1,t:"Das ist ein wichtiger Punkt. Lehrer berichten, Schüler nutzten die Plattformen auch für Hausaufgaben und Gruppenprojekte."},{ar:"كثيرًا ما نسمع أن وسائل التواصل خطر على الديمقراطية. ما رأيك في ذلك؟",s:0,t:"Man hört oft, die sozialen Medien seien eine Gefahr für die Demokratie. Was meinen Sie dazu?"},{ar:"يوضح علماء السياسة أن المحتوى المتلاعب به قد يؤثر في الانتخابات. لذلك يجب توعية المستخدمين بشكل أفضل.",s:1,t:"Politikwissenschaftler erklären, manipulierte Inhalte könnten Wahlen beeinflussen. Deshalb müsse man die Nutzer besser aufklären."},{ar:"تذكر وسائل الإعلام نفسها أن عددًا متزايدًا من الناس يثقون بالصحف التقليدية أقل من قبل.",s:0,t:"Die Medien selbst berichten, immer mehr Menschen vertrauten klassischen Zeitungen weniger als früher."},{ar:"هذه مشكلة. ويقول الصحفيون إن الصحافة الجيدة تحتاج وقتًا ومالًا، وكلاهما لا يُدفع غالبًا على الإنترنت.",s:1,t:"Das ist ein Problem. Journalisten sagen, guter Journalismus brauche Zeit und Geld, und beides werde im Netz oft nicht bezahlt."},{ar:"يقترح بعض الخبراء أن تُدخل المدارس الثقافة الإعلامية كمادة إلزامية. هل ترى ذلك منطقيًا؟",s:0,t:"Einige Experten schlagen vor, Schulen sollten Medienkompetenz als Pflichtfach einführen. Halten Sie das für sinnvoll?"},{ar:"بالتأكيد. ويؤكد التربويون أن الأطفال يجب أن يتعلموا مبكرًا فحص المصادر والتمييز بين الإعلان والمعلومة.",s:1,t:"Absolut. Pädagogen betonen, Kinder müssten früh lernen, Quellen zu prüfen und Werbung von Information zu unterscheiden."},{ar:"تدعي بعض الشركات أن المؤثرين أكثر مصداقية من الإعلان التقليدي. هل هذا صحيح؟",s:0,t:"Manche Firmen behaupten, Influencer seien glaubwürdiger als klassische Werbung. Stimmt das?"},{ar:"تُظهر الدراسات أن المستهلكين الشباب يثقون بالمؤثرين فعلًا أكثر، رغم أن كثيرًا من المنشورات إعلانات مدفوعة.",s:1,t:"Studien zeigen, dass junge Konsumenten Influencern tatsächlich mehr vertrauten, obwohl viele Beiträge bezahlte Werbung seien."},{ar:"هذا مقلق. ويطالب حماة المستهلك بأن تُميَّز الإعلانات بوضوح.",s:0,t:"Das ist bedenklich. Verbraucherschützer fordern, Werbung müsse klar gekennzeichnet werden."},{ar:"أوافق على ذلك. وتقول السلطات إنها تراقب التمييز، لكن الرقابة صعبة عمليًا.",s:1,t:"Da stimme ich zu. Die Behörden sagen, sie kontrollierten die Kennzeichnung, aber die Kontrolle sei in der Praxis schwierig."},{ar:"موضوع آخر هو حماية البيانات. يشتكي المستخدمون من أن بياناتهم تُجمع دون موافقة واضحة.",s:0,t:"Ein anderes Thema ist der Datenschutz. Nutzer klagen, ihre Daten würden ohne klare Zustimmung gesammelt."},{ar:"يحذر المدافعون عن الخصوصية من أن الشركات تجمع بيانات أكثر مما تعترف به. ويجب تقييد ذلك قانونيًا.",s:1,t:"Datenschützer warnen, die Konzerne sammelten mehr Daten, als sie zugäben. Das müsse gesetzlich begrenzt werden."},{ar:"هل توجد أيضًا تطورات إيجابية؟ يقول البعض إن وسائل التواصل هي ما جعلت الحركات الاحتجاجية ممكنة أصلًا.",s:0,t:"Gibt es auch positive Entwicklungen? Manche sagen, soziale Medien hätten Protestbewegungen erst möglich gemacht."},{ar:"نعم، يقول الناشطون إنهم تنظّموا بسرعة عبر وسائل التواصل ونشروا قضاياهم عالميًا.",s:1,t:"Ja, Aktivisten berichten, sie hätten sich über soziale Medien schnell organisiert und ihre Anliegen weltweit verbreitet."},{ar:"يقول المؤرخون إنه لولا هذه المنصات لنمت بعض الحركات ببطء أكبر بكثير. وهذه حجة قوية.",s:0,t:"Historiker sagen, ohne diese Plattformen wäre manche Bewegung viel langsamer gewachsen. Das ist ein starkes Argument."},{ar:"صحيح. لذلك أزعم أنه لا يجوز شيطنة وسائل التواصل ولا تمجيدها. بل يجب استخدامها بوعي.",s:1,t:"Richtig. Deshalb behaupte ich, man dürfe soziale Medien weder verteufeln noch verherrlichen. Man müsse sie bewusst nutzen."},{ar:"هذا موقف متوازن. بماذا تنصح الأهل عمليًا؟",s:0,t:"Das ist eine ausgewogene Position. Was raten Sie Eltern konkret?"},{ar:"أنصح بأن يتحدث الأهل مع أطفالهم ويضعوا قواعد معًا. فالمنع وحده لا يكفي.",s:1,t:"Ich rate, Eltern sollten mit ihren Kindern sprechen und gemeinsam Regeln festlegen. Verbote allein reichten nicht aus."},{ar:"يوصي علماء النفس بأن يتعلم الأطفال أخذ فترات راحة ووضع الهاتف جانبًا بوعي.",s:0,t:"Psychologen empfehlen, Kinder sollten lernen, Pausen zu machen und das Handy bewusst wegzulegen."},{ar:"بالضبط. وتقول دراسة جديدة إن المدارس يجب أن تكون قدوة وأن تستخدم وقت شاشة أقل في الدرس.",s:1,t:"Genau. Und die Schulen, so heißt es in einer neuen Studie, sollten Vorbilder sein und selbst weniger Bildschirmzeit im Unterricht nutzen."},{ar:"في الختام: هل تعتقد أن وسائل التواصل ستتحسن في السنوات المقبلة؟",s:0,t:"Zum Schluss: Glauben Sie, dass sich die sozialen Medien in den nächsten Jahren verbessern werden?"},{ar:"يقول المتفائلون إن التقنية ستصبح أكثر أمانًا وشفافية. ويخشى المتشائمون أن يبقى ضغط الإعلان قويًا جدًا.",s:1,t:"Optimisten sagen, die Technik werde sicherer und transparenter. Pessimisten befürchten, der Druck der Werbung bleibe zu stark."},{ar:"يرى بعض الباحثين أن المستقبل يعتمد أساسًا على المستخدمين، لا على الشركات.",s:0,t:"Manche Forscher meinen, die Zukunft hänge vor allem von den Nutzern ab, nicht von den Konzernen."},{ar:"أوافق على ذلك. فإذا بقي المستخدمون ناقدين، فقد تتغير المنصات نحو الأفضل.",s:1,t:"Dem stimme ich zu. Wenn die Nutzer kritisch blieben, könnten die Plattformen sich zum Besseren verändern."},{ar:"شكرًا جزيلًا على هذا الحوار الممتع وعلى إجاباتك الواضحة.",s:0,t:"Vielen Dank für dieses interessante Gespräch und für Ihre klaren Antworten."},{ar:"على الرحب والسعة. آمل أن يكون النقاش قد ساعد المستمعين على تكوين رأيهم الخاص.",s:1,t:"Gern geschehen. Ich hoffe, die Diskussion habe den Zuhörern geholfen, sich eine eigene Meinung zu bilden."},{ar:"آمل ذلك أيضًا. ويقول كثيرون إن مستمعينا تعلموا اليوم الكثير من الجديد. إلى اللقاء!",s:0,t:"Das hoffe ich auch. Unsere Zuhörer, so sagen viele, hätten heute viel Neues gelernt. Auf Wiedersehen!"},{ar:"إلى اللقاء، وشكرًا جزيلًا على الدعوة إلى النقاش.",s:1,t:"Auf Wiedersehen, und vielen Dank für die Einladung zur Diskussion."},{ar:"ونشكر مستمعينا أيضًا. إلى الحلقة المقبلة!",s:0,t:"Wir bedanken uns auch bei unseren Zuhörern. Bis zur nächsten Sendung!"}]},emoji:"📱",grammar:{covers:1,id:"de-b2-konjunktiv1-indirekte-rede",title:"Konjunktiv I: indirekte Rede",titleAr:"الكلام المنقول غير المباشر (Konjunktiv I)"},stage:7,title:"نقاش: وسائل التواصل",topic:"media",topicAr:"وسائل الإعلام والأخبار",topicDe:"Diskussion: Social Media",topicEn:"Debate: social media"},{conv:{id:"de-stage8-b2",speakers:["Mitarbeiterin (موظفة)","Geschäftsführer (المدير العام)"],turns:[{ar:"صباح الخير، سيد المدير. شكرًا لأنك خصصت وقتًا لفكرتي.",s:0,t:"Guten Morgen, Herr Direktor. Vielen Dank, dass Sie sich Zeit für meine Idee genommen haben."},{ar:"صباح الخير. أنا متحمس، لأنك قلت لي هاتفيًا إن الأمر يتعلق بعملائنا.",s:1,t:"Guten Morgen. Ich bin gespannt, weil Sie mir schon am Telefon gesagt haben, dass es um unsere Kunden geht."},{ar:"بالضبط. أريد أن أعرض عليك خدمة جديدة، حتى يمكن خدمة عملائنا بسرعة أكبر.",s:0,t:"Genau. Ich möchte Ihnen eine neue Dienstleistung vorstellen, damit unsere Kunden schneller bedient werden können."},{ar:"هذا يبدو مثيرًا للاهتمام. حدثيني أكثر، بينما أدوّن ملاحظات.",s:1,t:"Das klingt interessant. Erzählen Sie mir mehr, während ich mir Notizen mache."},{ar:"كثير من العملاء ينتظرون طويلًا، رغم أن لديهم موعدًا. لذلك أقترح نظامًا إلكترونيًا للمواعيد.",s:0,t:"Viele Kunden warten zu lange, obwohl sie einen Termin haben. Deshalb schlage ich ein Online-System für Termine vor."},{ar:"سيكون النظام الإلكتروني عمليًا، إذا كان سهل الاستخدام. كيف سيعمل؟",s:1,t:"Ein Online-System wäre praktisch, wenn es einfach zu bedienen ist. Wie soll es funktionieren?"},{ar:"يختار العميل موعدًا، حالما يفتح موقعنا. وبعدها يتلقى تأكيدًا فورًا بالبريد الإلكتروني.",s:0,t:"Der Kunde wählt einen Termin, sobald er unsere Webseite öffnet. Danach bekommt er sofort eine Bestätigung per E-Mail."},{ar:"هذا يوفر الوقت، لأن الموظفين سيضطرون حينها للإجابة عن مكالمات أقل. ما تكلفة التطوير؟",s:1,t:"Das spart Zeit, weil die Mitarbeiter dann weniger Anrufe beantworten müssen. Was kostet die Entwicklung?"},{ar:"التطوير يكلف نحو 40 ألف يورو، حتى نتمكن من إطلاق النظام خلال ثلاثة أشهر.",s:0,t:"Die Entwicklung kostet etwa 40.000 Euro, damit wir das System in drei Monaten einführen können."},{ar:"ثلاثة أشهر سريعة. ماذا يحدث إذا ظهرت مشكلات تقنية؟",s:1,t:"Drei Monate sind schnell. Was passiert, falls es technische Probleme gibt?"},{ar:"إذا ظهرت مشكلات، ستساعدنا شركة تقنية المعلومات التي نتعاون معها منذ سنوات.",s:0,t:"Falls es Probleme gibt, hilft uns die IT-Firma, mit der wir schon seit Jahren zusammenarbeiten."},{ar:"جيد. كيف يستفيد العملاء عندما يستخدمون النظام؟",s:1,t:"Gut. Wie profitieren die Kunden, wenn sie das System benutzen?"},{ar:"يوفرون الوقت، لأنهم لن يضطروا إلى الاتصال بعد الآن، ويمكنهم تغيير موعدهم في أي وقت إذا طرأ شيء.",s:0,t:"Sie sparen Zeit, weil sie nicht mehr anrufen müssen, und sie können ihren Termin jederzeit ändern, wenn etwas dazwischenkommt."},{ar:"هذه ميزة واضحة. كم عميلًا يستخدم موقعنا بالفعل لحجز المواعيد؟",s:1,t:"Das ist ein klarer Vorteil. Wie viele Kunden nutzen schon unsere Webseite, um Termine zu machen?"},{ar:"نحو 60 بالمئة من عملائنا يزورون الموقع بانتظام، رغم أن كثيرين ما زالوا يفضلون الاتصال.",s:0,t:"Etwa 60 Prozent unserer Kunden besuchen die Webseite regelmäßig, obwohl viele noch lieber anrufen."},{ar:"إذا روّجنا للنظام جيدًا، فسيحجز مزيد من العملاء عبر الإنترنت بالتأكيد. كيف تريدين التعريف به؟",s:1,t:"Wenn wir das System gut bewerben, werden sicher mehr Kunden online buchen. Wie wollen Sie es bekannt machen?"},{ar:"سنُعلم العملاء بالبريد الإلكتروني حالما ينطلق النظام، وسنعرضه أيضًا في فرعنا.",s:0,t:"Wir informieren die Kunden per E-Mail, sobald das System startet, und wir zeigen es auch in unserer Filiale."},{ar:"هذه استراتيجية جيدة. هل يجب تدريب الموظفين قبل انطلاق النظام؟",s:1,t:"Das ist eine gute Strategie. Müssen die Mitarbeiter geschult werden, bevor das System startet?"},{ar:"نعم، سيُدرَّب الموظفون حتى يتمكنوا من مساعدة العملاء عند وجود أسئلة.",s:0,t:"Ja, die Mitarbeiter werden geschult, damit sie die Kunden bei Fragen unterstützen können."},{ar:"التدريب مهم، لأن النظام لا يعمل إلا إذا عرفه الجميع جيدًا. كم يستغرق؟",s:1,t:"Die Schulung ist wichtig, weil das System nur funktioniert, wenn alle es gut kennen. Wie lange dauert sie?"},{ar:"التدريب يستغرق يومين، بعد أن يتم اختبار النظام بالكامل.",s:0,t:"Die Schulung dauert zwei Tage, nachdem das System fertig getestet wurde."},{ar:"يومان ممكنان. ماذا لو لم يكن لدى العميل اتصال بالإنترنت؟",s:1,t:"Zwei Tage sind machbar. Was ist, wenn ein Kunde keinen Internetzugang hat?"},{ar:"إذا لم يكن لدى العميل اتصال بالإنترنت، فيمكنه الاستمرار في حجز موعد هاتفيًا، كما قبل.",s:0,t:"Wenn ein Kunde keinen Internetzugang hat, kann er weiterhin telefonisch einen Termin vereinbaren, wie bisher."},{ar:"هذا عادل، حتى لا يُستبعد أحد. هل توجد أنظمة مشابهة لدى المنافسين؟",s:1,t:"Das ist fair, damit niemand ausgeschlossen wird. Gibt es schon ähnliche Systeme bei der Konkurrenz?"},{ar:"نعم، يقدم منافسونا مواعيد إلكترونية بالفعل، منذ أن ارتفع الطلب على العروض الرقمية.",s:0,t:"Ja, unsere Konkurrenz bietet schon Online-Termine an, seitdem die Nachfrage nach digitalen Angeboten gestiegen ist."},{ar:"إذن يجب أن نتحرك بسرعة، قبل أن نخسر مزيدًا من العملاء. ماذا تحتاجين مني؟",s:1,t:"Dann müssen wir schnell handeln, bevor wir noch mehr Kunden verlieren. Was brauchen Sie von mir?"},{ar:"أحتاج موافقتك على الميزانية، حتى نتمكن من البدء بالتطوير هذا الأسبوع.",s:0,t:"Ich brauche Ihre Zustimmung zum Budget, damit wir noch in dieser Woche mit der Entwicklung beginnen können."},{ar:"يمكنني الموافقة على الميزانية، إذا لم ترتفع التكاليف عن المخطط. هل يمكنك ضمان ذلك؟",s:1,t:"Das Budget kann ich genehmigen, wenn die Kosten nicht höher werden als geplant. Können Sie das garantieren?"},{ar:"يمكنني ضمان ذلك، ما دمنا لا نضيف وظائف إضافية لم تكن مخططة.",s:0,t:"Ich kann es garantieren, solange wir keine zusätzlichen Funktionen einbauen, die nicht geplant waren."},{ar:"موافق. كم مرة ستبلغينني عن التقدم، بينما يتم تطوير النظام؟",s:1,t:"Einverstanden. Wie oft berichten Sie mir über den Fortschritt, während das System entwickelt wird?"},{ar:"سأبلغك كل أسبوع، حتى يكتمل النظام، وسأعلمك فورًا إذا حدث أي تأخير.",s:0,t:"Ich berichte Ihnen jede Woche, bis das System fertig ist, und ich informiere Sie sofort, falls es Verzögerungen gibt."},{ar:"هذا بالضبط ما أتوقعه. متى يمكننا البدء بالاختبارات الأولى؟",s:1,t:"Das ist genau das, was ich erwarte. Wann können wir mit den ersten Tests beginnen?"},{ar:"تبدأ الاختبارات الأولى بعد شهرين، بعد برمجة أهم الوظائف.",s:0,t:"Die ersten Tests beginnen in zwei Monaten, nachdem die wichtigsten Funktionen programmiert wurden."},{ar:"جيد. من يختبر النظام قبل إتاحته للعملاء؟",s:1,t:"Gut. Wer testet das System, bevor es für die Kunden freigegeben wird?"},{ar:"سيختبر النظام عشرة موظفين وعشرون عميلًا مختارًا، حتى نكتشف الأخطاء مبكرًا.",s:0,t:"Zehn Mitarbeiter und zwanzig ausgewählte Kunden testen das System, damit wir Fehler früh entdecken."},{ar:"هذه فكرة ذكية، لأن العملاء الحقيقيين يقدمون أفضل الملاحظات. ماذا يحدث بعد الانطلاق؟",s:1,t:"Das ist eine kluge Idee, weil echte Kunden die besten Rückmeldungen geben. Was passiert nach dem Start?"},{ar:"بعد الانطلاق سنقيّم التجارب الأولى، لتحسين النظام أكثر.",s:0,t:"Nach dem Start werten wir die ersten Erfahrungen aus, um das System weiter zu verbessern."},{ar:"أنا مقتنع، لأن فكرتك واضحة وعملية ومدروسة جيدًا. أعطي الضوء الأخضر.",s:1,t:"Ich bin überzeugt, weil Ihre Idee klar, praktisch und gut durchdacht ist. Ich gebe grünes Licht."},{ar:"شكرًا جزيلًا على ثقتك! أنا سعيدة جدًا لأننا سننفذ المشروع معًا.",s:0,t:"Vielen Dank für Ihr Vertrauen! Ich freue mich sehr, dass wir das Projekt gemeinsam umsetzen können."},{ar:"وأنا سعيد أيضًا. من فضلك أرسلي لي الجدول الزمني حالما يجهز.",s:1,t:"Ich freue mich auch. Bitte schicken Sie mir den Zeitplan, sobald er fertig ist."},{ar:"بالطبع، سأرسل لك الجدول الزمني اليوم، حتى نتمكن من بدء التخطيط غدًا.",s:0,t:"Natürlich, ich schicke Ihnen den Zeitplan noch heute, damit wir morgen mit der Planung beginnen können."},{ar:"ممتاز. إذن أتمنى لك وللفريق كل التوفيق في التنفيذ.",s:1,t:"Perfekt. Dann wünsche ich Ihnen und dem Team viel Erfolg bei der Umsetzung."}]},emoji:"💡",grammar:{covers:1,id:"de-b2-adverbiale-nebensaetze",title:"Adverbiale Nebensätze",titleAr:"الجمل الظرفية التابعة"},stage:8,title:"عرض فكرة",topic:"jobs",topicAr:"المهن والعمل",topicDe:"Eine Idee vorstellen",topicEn:"Pitching an idea"},{stage:9,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Resolving a conflict at work",topicDe:"Konflikt lösen",emoji:"🤝",title:"حل خلاف في العمل",grammar:{id:"de-b2-irreale-bedingungssaetze",title:"Irreale Bedingungssätze",titleAr:"الجمل الشرطية غير الواقعية",covers:1},conv:{id:"de-stage9-b2",speakers:["Teamleiter (قائد الفريق)","Mitarbeiterin (موظفة)"],turns:[{s:0,t:"Guten Morgen. Danke, dass Sie sich die Zeit für dieses Gespräch nehmen.",ar:"صباح الخير، شكرًا لأنك خصصت وقتًا لهذا الحديث."},{s:1,t:"Guten Morgen. Ich bin froh, dass wir endlich darüber sprechen können.",ar:"صباح الخير، أنا سعيدة لأننا سنتحدث أخيرًا عن هذا الموضوع."},{s:0,t:"Ich habe gehört, dass es zwischen Ihnen und einem Kollegen aus Ihrem Team Spannungen gibt.",ar:"سمعت أن هناك توترًا بينك وبين أحد الزملاء في فريقك."},{s:1,t:"Ja, das stimmt. Seit Wochen arbeiten wir kaum noch miteinander, und das belastet mich sehr.",ar:"نعم، هذا صحيح. منذ أسابيع بالكاد نعمل معًا، وهذا يضغط عليّ كثيرًا."},{s:0,t:"Das tut mir leid. Können Sie mir erzählen, womit die Schwierigkeiten begonnen haben?",ar:"يؤسفني ذلك. هل يمكنك أن تخبريني كيف بدأت الصعوبات؟"},{s:1,t:"Es begann mit dem Projekt im letzten Monat. Ich hatte die Aufgabe übernommen, den Bericht zu schreiben, und plötzlich wurde er ohne Absprache an jemand anderen gegeben.",ar:"بدأت مع المشروع في الشهر الماضي. كنت قد توليت كتابة التقرير، وفجأة أُعطي لشخص آخر دون مشاورتي."},{s:0,t:"Wenn ich das richtig verstehe, fühlten Sie sich übergangen. Das kann ich nachvollziehen.",ar:"إن فهمت بشكل صحيح، شعرتِ بأنه تم تجاهلك. أستطيع أن أتفهم ذلك."},{s:1,t:"Genau. Wenn man mich vorher gefragt hätte, hätte ich die Aufgabe gern geteilt. So aber stand ich vor vollendeten Tatsachen.",ar:"بالضبط. لو سألوني مسبقًا، لكنت شاركت المهمة بكل سرور. لكنني وجدت نفسي أمام أمر واقع."},{s:0,t:"Das ist verständlich. Wenn wir früher miteinander gesprochen hätten, wäre der Konflikt vielleicht gar nicht entstanden.",ar:"هذا مفهوم. لو تحدثنا معًا في وقت أبكر، لما نشأ الخلاف أصلًا."},{s:1,t:"Das denke ich auch. Ich hätte mich sofort gemeldet, wenn ich gewusst hätte, dass es ein Missverständnis war.",ar:"أعتقد ذلك أيضًا. كنت سأتواصل فورًا لو عرفت أنه سوء فهم."},{s:0,t:"Manchmal entstehen solche Situationen, weil Informationen nicht rechtzeitig weitergegeben werden. Das müssen wir verbessern.",ar:"أحيانًا تنشأ مثل هذه المواقف لأن المعلومات لا تصل في الوقت المناسب. يجب أن نحسّن ذلك."},{s:1,t:"Ich bin einverstanden. Aber es gab noch etwas: In der Besprechung wurde meine Idee als die Idee eines anderen dargestellt.",ar:"أوافقك. لكن كان هناك أمر آخر: في الاجتماع عُرضت فكرتي على أنها فكرة شخص آخر."},{s:0,t:"Das ist ein ernstes Problem. Wenn das wirklich so passiert ist, müssen wir das klarstellen.",ar:"هذه مشكلة جدية. إذا حدث ذلك فعلًا، فعلينا توضيح الأمر."},{s:1,t:"Ich habe die E-Mails noch. Wenn Sie möchten, kann ich sie Ihnen zeigen.",ar:"ما زلت أحتفظ برسائل البريد الإلكتروني. إذا أردت، يمكنني أن أريك إياها."},{s:0,t:"Das wäre hilfreich. Würden Sie mir die entsprechenden Nachrichten nach unserem Gespräch schicken?",ar:"سيكون ذلك مفيدًا. هل ترسلين لي الرسائل المعنية بعد حديثنا؟"},{s:1,t:"Selbstverständlich. Ich möchte nur, dass meine Arbeit anerkannt wird. Mehr verlange ich nicht.",ar:"بالطبع. أريد فقط أن يُعترف بعملي. لا أطلب أكثر من ذلك."},{s:0,t:"Das ist ein berechtigter Wunsch. Anerkennung ist wichtig für die Motivation des ganzen Teams.",ar:"هذا طلب مشروع. التقدير مهم لتحفيز الفريق كله."},{s:1,t:"Wenn mein Kollege sich entschuldigen würde, wäre die Sache für mich erledigt.",ar:"لو اعتذر زميلي، لانتهى الأمر بالنسبة لي."},{s:0,t:"Ich werde mit ihm sprechen. Vielleicht wäre ein gemeinsames Gespräch zu dritt der beste Weg.",ar:"سأتحدث معه. ربما يكون الحديث المشترك بيننا نحن الثلاثة أفضل طريق."},{s:1,t:"Das finde ich gut. Wenn wir uns an einen Tisch setzen, könnten wir alles offen besprechen.",ar:"أجد ذلك جيدًا. لو جلسنا معًا إلى طاولة واحدة، لاستطعنا مناقشة كل شيء بصراحة."},{s:0,t:"Ich schlage vor, dass wir das Treffen noch in dieser Woche organisieren. Passt Ihnen der Donnerstag?",ar:"أقترح أن ننظم اللقاء خلال هذا الأسبوع. هل يناسبك يوم الخميس؟"},{s:1,t:"Donnerstag passt mir sehr gut. Ich hätte gern, dass wir dabei klare Regeln für die Zusammenarbeit vereinbaren.",ar:"الخميس يناسبني جدًا. أود أن نتفق خلاله على قواعد واضحة للتعاون."},{s:0,t:"Das ist eine gute Idee. Wenn wir die Aufgaben künftig schriftlich verteilen, gäbe es weniger Missverständnisse.",ar:"هذه فكرة جيدة. لو وزعنا المهام كتابيًا في المستقبل، لقلّ سوء الفهم."},{s:1,t:"Genau. Und wenn jeder seine Ideen selbst vorstellen dürfte, würde sich niemand übergangen fühlen.",ar:"بالضبط. ولو سُمح لكل شخص بعرض أفكاره بنفسه، لما شعر أحد بأنه مُتجاهَل."},{s:0,t:"Ich werde das im Team ansprechen. Transparenz hilft uns allen.",ar:"سأطرح ذلك في الفريق. الشفافية تساعدنا جميعًا."},{s:1,t:"Ich hoffe nur, dass mein Kollege das Gespräch nicht als Angriff versteht.",ar:"آمل فقط ألا يفهم زميلي الحديث على أنه هجوم."},{s:0,t:"Keine Sorge. Ich werde deutlich machen, dass es um eine Lösung geht, nicht um Schuldzuweisungen.",ar:"لا تقلقي. سأوضح أن الأمر يتعلق بإيجاد حل، وليس بتوجيه اللوم."},{s:1,t:"Das beruhigt mich. Wenn ich gewusst hätte, dass Sie so offen reagieren, hätte ich viel früher mit Ihnen gesprochen.",ar:"هذا يطمئنني. لو عرفت أنك ستتفاعل بهذا الانفتاح، لتحدثت معك قبل ذلك بكثير."},{s:0,t:"Es ist nie zu spät. Wichtig ist, dass wir jetzt handeln.",ar:"لم يفت الأوان أبدًا. المهم أن نتصرف الآن."},{s:1,t:"Was würden Sie mir raten, wenn sich die Situation wiederholen sollte?",ar:"ماذا تنصحني لو تكرر الموقف؟"},{s:0,t:"Sprechen Sie sofort mit mir oder mit der Person selbst. Je früher wir reagieren, desto leichter ist die Lösung.",ar:"تحدثي معي فورًا أو مع الشخص نفسه. كلما تحركنا مبكرًا، كان الحل أسهل."},{s:1,t:"Das werde ich tun. Ich habe gelernt, dass Schweigen die Probleme nur größer macht.",ar:"سأفعل ذلك. تعلمت أن الصمت يجعل المشاكل أكبر فقط."},{s:0,t:"Das ist eine wichtige Erkenntnis. Würden Sie auch bereit sein, an einem Workshop zur Kommunikation teilzunehmen?",ar:"هذه ملاحظة مهمة. هل تكونين مستعدة أيضًا للمشاركة في ورشة عمل حول التواصل؟"},{s:1,t:"Sehr gern. Wenn das ganze Team teilnehmen würde, wäre das noch besser.",ar:"بكل سرور. لو شارك الفريق كله، لكان ذلك أفضل."},{s:0,t:"Ich werde das organisieren. Solche Schulungen stärken das Vertrauen untereinander.",ar:"سأنظم ذلك. مثل هذه الدورات تعزز الثقة بين الزملاء."},{s:1,t:"Ich freue mich darauf. Ich möchte, dass wir wieder gut zusammenarbeiten.",ar:"أتطلع إلى ذلك. أريد أن نعمل معًا بشكل جيد من جديد."},{s:0,t:"Das wollen wir alle. Wenn wir ehrlich miteinander umgehen, wird das Team stärker.",ar:"هذا ما نريده جميعًا. لو تعاملنا بصدق مع بعضنا، سيصبح الفريق أقوى."},{s:1,t:"Da bin ich ganz Ihrer Meinung. Ich danke Ihnen für Ihre Unterstützung.",ar:"أوافقك تمامًا. أشكرك على دعمك."},{s:0,t:"Gern geschehen. Ich schicke Ihnen heute noch die Einladung für Donnerstag.",ar:"على الرحب والسعة. سأرسل لك دعوة يوم الخميس اليوم."},{s:1,t:"Perfekt. Ich bereite mich bis dahin vor und bringe die E-Mails mit.",ar:"ممتاز. سأستعد حتى ذلك الحين وسأحضر رسائل البريد."},{s:0,t:"Sehr gut. Dann sehen wir uns am Donnerstag, und ich bin sicher, dass wir eine Lösung finden.",ar:"جيد جدًا. إذن نلتقي يوم الخميس، وأنا واثق أننا سنجد حلًا."},{s:1,t:"Das hoffe ich auch. Vielen Dank für das Gespräch. Auf Wiedersehen!",ar:"آمل ذلك أيضًا. شكرًا جزيلًا على الحديث. إلى اللقاء!"}]}},{stage:10,topic:"news",topicAr:"الأخبار والسياسة",topicEn:"Discussing politics",topicDe:"Über Politik diskutieren",emoji:"🗳️",title:"نقاش حول السياسة",grammar:{id:"de-b2-textzusammenhang",title:"Textzusammenhang",titleAr:"ترابط النص",covers:1},conv:{id:"de-stage10-b2",speakers:["Wählerin (ناخبة)","Politiker (سياسي)"],turns:[{s:0,t:"Guten Tag. Vielen Dank, dass Sie sich heute die Zeit für uns Bürger nehmen.",ar:"مرحبًا، شكرًا لأنك خصصت وقتك اليوم لنا نحن المواطنين."},{s:1,t:"Guten Tag! Es freut mich sehr, mit Ihnen zu sprechen. Was beschäftigt Sie zurzeit am meisten?",ar:"مرحبًا! يسعدني جدًا أن أتحدث معك. ما الذي يشغلك أكثر في الوقت الحالي؟"},{s:0,t:"Zunächst einmal beschäftigt mich die Frage der bezahlbaren Wohnungen. In unserer Stadt steigen die Mieten immer weiter.",ar:"أولًا، يشغلني موضوع المساكن بأسعار معقولة. في مدينتنا ترتفع الإيجارات باستمرار."},{s:1,t:"Das ist ein wichtiges Thema. Einerseits brauchen wir mehr neue Wohnungen, andererseits müssen die bestehenden Mieten bezahlbar bleiben.",ar:"هذا موضوع مهم. من جهة نحتاج إلى مساكن جديدة أكثر، ومن جهة أخرى يجب أن تبقى الإيجارات الحالية معقولة."},{s:0,t:"Genau. Außerdem frage ich mich, was mit den Familien passiert, die sich die Stadt bald nicht mehr leisten können.",ar:"بالضبط. إضافة إلى ذلك، أتساءل ماذا سيحدث للعائلات التي لن تستطيع قريبًا تحمل تكاليف العيش في المدينة."},{s:1,t:"Deswegen plant unsere Partei ein Programm für sozialen Wohnungsbau. Wir wollen in den nächsten fünf Jahren zehntausend neue Wohnungen bauen.",ar:"لذلك يخطط حزبنا لبرنامج للإسكان الاجتماعي. نريد بناء عشرة آلاف مسكن جديد خلال السنوات الخمس المقبلة."},{s:0,t:"Das klingt gut. Aber wie wollen Sie das finanzieren, ohne die Steuern stark zu erhöhen?",ar:"يبدو ذلك جيدًا. لكن كيف ستمولون ذلك دون رفع الضرائب بشكل كبير؟"},{s:1,t:"Im Gegensatz zu anderen Vorschlägen wollen wir keine Steuererhöhung. Stattdessen nutzen wir freie Grundstücke der Stadt und arbeiten mit Genossenschaften zusammen.",ar:"على عكس المقترحات الأخرى، لا نريد زيادة الضرائب. بدلًا من ذلك نستخدم الأراضي الشاغرة التابعة للمدينة ونتعاون مع الجمعيات التعاونية."},{s:0,t:"Das ist ein interessanter Ansatz. Trotzdem bleibt die Frage, ob das schnell genug geht.",ar:"هذا نهج مثير للاهتمام. ومع ذلك يبقى السؤال: هل سيتم ذلك بسرعة كافية؟"},{s:1,t:"Sie haben recht, der Bau dauert. Folglich brauchen wir gleichzeitig einen besseren Schutz für Mieter, zum Beispiel eine strengere Mietpreisbremse.",ar:"أنت محقة، البناء يستغرق وقتًا. وبالتالي نحتاج في الوقت نفسه إلى حماية أفضل للمستأجرين، مثل تشديد قانون كبح الإيجارات."},{s:0,t:"Darüber hinaus mache ich mir Sorgen um die Schulen. Die Klassen sind überfüllt, und es fehlen Lehrer.",ar:"علاوة على ذلك، أشعر بالقلق بشأن المدارس. الصفوف مكتظة، وهناك نقص في المعلمين."},{s:1,t:"Auch hier gilt: Einerseits fehlt Geld, andererseits fehlt Personal. Deswegen wollen wir die Ausbildung von Lehrern verkürzen und besser bezahlen.",ar:"هنا أيضًا ينطبق الأمر نفسه: من جهة ينقص المال، ومن جهة أخرى ينقص الكادر. لذلك نريد تقصير مدة تأهيل المعلمين وتحسين أجورهم."},{s:0,t:"Das wäre ein Schritt in die richtige Richtung. Allerdings höre ich solche Versprechen schon seit Jahren.",ar:"ستكون هذه خطوة في الاتجاه الصحيح. لكنني أسمع مثل هذه الوعود منذ سنوات."},{s:1,t:"Ich verstehe Ihre Skepsis. Im Gegensatz zu früher gibt es jetzt jedoch einen festen Zeitplan mit messbaren Zielen.",ar:"أتفهم شكوكك. لكن على عكس السابق، يوجد الآن جدول زمني ثابت بأهداف قابلة للقياس."},{s:0,t:"Einen Zeitplan finde ich gut. Was passiert aber, wenn die Ziele nicht erreicht werden?",ar:"الجدول الزمني فكرة جيدة. لكن ماذا يحدث إذا لم تتحقق الأهداف؟"},{s:1,t:"Dann müssen wir uns öffentlich dazu bekennen und den Plan anpassen. Transparenz ist für mich entscheidend.",ar:"عندها يجب أن نعترف بذلك علنًا وأن نعدّل الخطة. الشفافية بالنسبة لي أمر حاسم."},{s:0,t:"Das freut mich zu hören. Kommen wir zum Klima: Was tut Ihre Partei für den öffentlichen Verkehr?",ar:"يسعدني سماع ذلك. لننتقل إلى المناخ: ماذا يفعل حزبك من أجل النقل العام؟"},{s:1,t:"Zunächst wollen wir die Busse und Bahnen in der Stadt günstiger machen. Außerdem sollen neue Linien in die Vororte gebaut werden.",ar:"أولًا، نريد جعل الحافلات والقطارات في المدينة أرخص. إضافة إلى ذلك، يجب بناء خطوط جديدة إلى الضواحي."},{s:0,t:"Das würde vielen Menschen helfen. Trotzdem fahren viele weiter mit dem Auto, weil der Verkehr unzuverlässig ist.",ar:"سيساعد ذلك كثيرًا من الناس. ومع ذلك، يواصل كثيرون القيادة بسياراتهم لأن النقل غير موثوق."},{s:1,t:"Deswegen investieren wir zuerst in die Pünktlichkeit. Wenn die Bahnen zuverlässig fahren, steigen mehr Menschen um.",ar:"لذلك نستثمر أولًا في الالتزام بالمواعيد. عندما تسير القطارات بانتظام، يتحول مزيد من الناس إليها."},{s:0,t:"Das ist logisch. Wie stehen Sie zur Einführung eines kostenlosen Nahverkehrs?",ar:"هذا منطقي. ما موقفك من إدخال نقل عام مجاني؟"},{s:1,t:"Einerseits wäre das sozial gerecht, andererseits kostet es sehr viel Geld. Wir prüfen es Schritt für Schritt.",ar:"من جهة سيكون ذلك عادلًا اجتماعيًا، ومن جهة أخرى يكلف مالًا كثيرًا. ندرسه خطوة بخطوة."},{s:0,t:"Verstehe. Und was ist mit der Sicherheit in unserer Stadt? Abends fühle ich mich in manchen Vierteln nicht sicher.",ar:"أفهم. وماذا عن الأمان في مدينتنا؟ في المساء لا أشعر بالأمان في بعض الأحياء."},{s:1,t:"Das nehme ich ernst. Im Gegensatz zu reiner Überwachung setzen wir auf mehr Personal, bessere Beleuchtung und Jugendarbeit.",ar:"آخذ ذلك على محمل الجد. على عكس المراقبة وحدها، نعتمد على مزيد من الكوادر وإضاءة أفضل وعمل مع الشباب."},{s:0,t:"Jugendarbeit finde ich besonders wichtig. Schließlich entstehen viele Probleme, weil junge Menschen keine Perspektive haben.",ar:"أجد العمل مع الشباب مهمًا بشكل خاص. ففي النهاية تنشأ كثير من المشاكل لأن الشباب بلا أفق."},{s:1,t:"Genau. Deswegen wollen wir mehr Ausbildungsplätze schaffen und die Zusammenarbeit mit den Betrieben verstärken.",ar:"بالضبط. لذلك نريد توفير مزيد من أماكن التدريب المهني وتعزيز التعاون مع الشركات."},{s:0,t:"Das klingt vernünftig. Nun eine letzte Frage: Warum sollte ich ausgerechnet Ihre Partei wählen?",ar:"يبدو ذلك معقولًا. والآن سؤال أخير: لماذا يجب أن أنتخب حزبك تحديدًا؟"},{s:1,t:"Zusammenfassend gesagt: Wir verbinden soziale Gerechtigkeit mit wirtschaftlicher Vernunft, und wir arbeiten mit klaren Zielen statt mit leeren Versprechen.",ar:"باختصار: نجمع بين العدالة الاجتماعية والعقلانية الاقتصادية، ونعمل بأهداف واضحة بدل الوعود الفارغة."},{s:0,t:"Das ist eine klare Antwort. Allerdings muss ich noch die Programme der anderen Parteien vergleichen.",ar:"هذه إجابة واضحة. لكن ما زلت بحاجة إلى مقارنة برامج الأحزاب الأخرى."},{s:1,t:"Das ist Ihr gutes Recht, und ich ermutige Sie sogar dazu. Eine informierte Entscheidung ist die beste Entscheidung.",ar:"هذا حقك، بل أشجعك على ذلك. القرار المستنير هو أفضل قرار."},{s:0,t:"Darüber hinaus würde mich interessieren, wie Sie die Bürger nach der Wahl einbeziehen wollen.",ar:"علاوة على ذلك، يهمني أن أعرف كيف ستشملون المواطنين بعد الانتخابات."},{s:1,t:"Wir planen regelmäßige Bürgersprechstunden und eine Online-Plattform, auf der jeder Vorschläge einreichen kann.",ar:"نخطط لساعات استقبال منتظمة للمواطنين ومنصة إلكترونية يمكن للجميع تقديم المقترحات عليها."},{s:0,t:"Das finde ich sehr gut. Viele Politiker verschwinden nach der Wahl und kommen erst vor der nächsten Wahl zurück.",ar:"أجد ذلك جيدًا جدًا. كثير من السياسيين يختفون بعد الانتخابات ولا يعودون إلا قبل الانتخابات التالية."},{s:1,t:"Das will ich anders machen. Ich werde jeden Monat hier im Stadtteil sein und Rede und Antwort stehen.",ar:"أريد أن أفعل ذلك بشكل مختلف. سأكون هنا في الحي كل شهر وأجيب عن الأسئلة."},{s:0,t:"Das werde ich mir merken. Versprechen kann man leicht geben — halten ist schwieriger.",ar:"سأتذكر ذلك. الوعود سهلة، أما الوفاء بها فأصعب."},{s:1,t:"Da haben Sie völlig recht. Folglich lade ich Sie ein, mich in einem Jahr an meinen heutigen Worten zu messen.",ar:"أنت محقة تمامًا. وبالتالي أدعوك إلى محاسبتي على كلماتي اليوم بعد عام."},{s:0,t:"Diese Einladung nehme ich gern an. Vielen Dank für das offene Gespräch.",ar:"أقبل هذه الدعوة بسرور. شكرًا جزيلًا على الحديث الصريح."},{s:1,t:"Ich danke Ihnen für Ihre Fragen. Solche Gespräche sind für mich die wichtigste Grundlage meiner Arbeit.",ar:"أشكرك على أسئلتك. مثل هذه المحادثات هي أهم أساس لعملي."},{s:0,t:"Ich wünsche Ihnen viel Erfolg. Ich werde meine Entscheidung in Ruhe treffen.",ar:"أتمنى لك التوفيق. سأتخذ قراري بهدوء."},{s:1,t:"Das ist der richtige Weg. Auf Wiedersehen, und einen schönen Tag noch!",ar:"هذا هو الطريق الصحيح. إلى اللقاء، وأتمنى لك يومًا سعيدًا!"},{s:0,t:"Ach, und noch etwas: Wo finde ich Ihr vollständiges Wahlprogramm?",ar:"بالمناسبة، أين أجد برنامجك الانتخابي الكامل؟"},{s:1,t:"Sie finden es in unserem Büro und auf unserer Internetseite. Dort stehen alle Punkte ausführlich erklärt. Auf Wiedersehen!",ar:"ستجده في مكتبنا وعلى موقعنا الإلكتروني. هناك كل النقاط مشروحة بالتفصيل. إلى اللقاء!"}]}},{stage:11,topic:"health",topicAr:"الصحة والجسم",topicEn:"Medical test results",topicDe:"Untersuchungsergebnisse",emoji:"🏥",title:"نتائج الفحوصات الطبية",grammar:{id:"de-b2-partizip-attribute",title:"Partizipien als Attribute",titleAr:"اسم الفاعل والمفعول كصفة",covers:1},conv:{id:"de-stage11-b2",speakers:["Patientin (المريضة)","Arzt (الطبيب)"],turns:[{s:0,t:"Guten Tag, Herr Doktor. Ich bin wegen meiner Untersuchungsergebnisse hier.",ar:"مرحبًا دكتور، أنا هنا من أجل نتائج فحوصاتي."},{s:1,t:"Guten Tag. Bitte nehmen Sie Platz. Die vorliegenden Ergebnisse habe ich mir bereits angesehen.",ar:"مرحبًا، تفضلي بالجلوس. لقد اطلعت بالفعل على النتائج الموجودة."},{s:0,t:"Ich war die ganze Woche nervös. Sind die Ergebnisse gut oder schlecht?",ar:"كنت متوترة طوال الأسبوع. هل النتائج جيدة أم سيئة؟"},{s:1,t:"Zuerst die gute Nachricht: Die durchgeführte Blutuntersuchung zeigt keine ernsthaften Erkrankungen.",ar:"أولًا الخبر الجيد: فحص الدم الذي أُجري لا يُظهر أي أمراض خطيرة."},{s:0,t:"Das ist eine Erleichterung. Aber es gab doch einen auffälligen Wert, oder?",ar:"هذا مريح. لكن كان هناك قيمة لافتة، أليس كذلك؟"},{s:1,t:"Ja, die gemessenen Blutzuckerwerte sind leicht erhöht. Das müssen wir beobachten.",ar:"نعم، قيم سكر الدم المقاسة مرتفعة قليلًا. يجب أن نراقب ذلك."},{s:0,t:"Was bedeutet das genau? Muss ich jetzt Medikamente nehmen?",ar:"ماذا يعني ذلك بالضبط؟ هل يجب أن أتناول الأدوية الآن؟"},{s:1,t:"Nein, noch nicht. Die festgestellten Werte liegen nur knapp über dem Normalbereich.",ar:"لا، ليس بعد. القيم الملاحظة أعلى بقليل فقط من المعدل الطبيعي."},{s:0,t:"Und was empfehlen Sie mir stattdessen?",ar:"وماذا توصي بدلًا من ذلك؟"},{s:1,t:"Die empfohlene Behandlung ist zunächst eine Umstellung der Ernährung und mehr Bewegung.",ar:"العلاج الموصى به أولًا هو تغيير النظام الغذائي وزيادة الحركة."},{s:0,t:"Das klingt machbar. Wie oft soll ich mich bewegen?",ar:"يبدو ذلك ممكنًا. كم مرة يجب أن أتحرك؟"},{s:1,t:"Ich empfehle Ihnen dreimal pro Woche dreißig Minuten zügiges Gehen oder Radfahren.",ar:"أوصيك بالمشي السريع أو ركوب الدراجة ثلاث مرات أسبوعيًا لمدة ثلاثين دقيقة."},{s:0,t:"Das schaffe ich. Gibt es Lebensmittel, die ich besonders vermeiden sollte?",ar:"أستطيع ذلك. هل هناك أطعمة يجب أن أتجنبها بشكل خاص؟"},{s:1,t:"Die betroffenen Lebensmittel sind vor allem stark gezuckerte Getränke und Weißbrot. Vollkornprodukte sind besser.",ar:"الأطعمة المعنية هي بالأساس المشروبات المحلاة بكثرة والخبز الأبيض. منتجات الحبوب الكاملة أفضل."},{s:0,t:"Ich trinke tatsächlich viel Limonade. Das werde ich sofort ändern.",ar:"أشرب فعلًا الكثير من المشروبات الغازية. سأغير ذلك فورًا."},{s:1,t:"Das ist ein guter Anfang. Auch die anstehende Kontrolluntersuchung in drei Monaten ist wichtig.",ar:"هذه بداية جيدة. كما أن فحص المتابعة القادم بعد ثلاثة أشهر مهم."},{s:0,t:"In drei Monaten also. Wird dann wieder Blut abgenommen?",ar:"إذن بعد ثلاثة أشهر. هل سيتم سحب الدم مرة أخرى؟"},{s:1,t:"Ja, die wiederholte Untersuchung zeigt uns, ob sich die Werte verbessert haben.",ar:"نعم، الفحص المكرر سيُظهر لنا ما إذا كانت القيم قد تحسنت."},{s:0,t:"Und was ist mit meinem Blutdruck? Der war bei der letzten Messung auch etwas hoch.",ar:"وماذا عن ضغط دمي؟ كان مرتفعًا قليلًا أيضًا في القياس الأخير."},{s:1,t:"Die gemessenen Blutdruckwerte sind grenzwertig, aber noch im akzeptablen Bereich. Mit mehr Bewegung sinken sie oft von selbst.",ar:"قيم ضغط الدم المقاسة حدّية، لكنها ما زالت في النطاق المقبول. ومع مزيد من الحركة تنخفض غالبًا من تلقاء نفسها."},{s:0,t:"Das beruhigt mich. Brauche ich ein verordnetes Medikament für den Blutdruck?",ar:"هذا يطمئنني. هل أحتاج إلى دواء موصوف لضغط الدم؟"},{s:1,t:"Zurzeit nicht. Das verschriebene Medikament wäre erst nötig, wenn die Werte weiter steigen.",ar:"في الوقت الحالي لا. الدواء الموصوف لن يكون ضروريًا إلا إذا استمرت القيم في الارتفاع."},{s:0,t:"Verstehe. Gibt es noch andere auffällige Werte in den Ergebnissen?",ar:"أفهم. هل هناك قيم لافتة أخرى في النتائج؟"},{s:1,t:"Die untersuchten Cholesterinwerte sind in Ordnung. Nur der Vitamin-D-Wert ist etwas niedrig.",ar:"قيم الكوليسترول المفحوصة جيدة. فقط قيمة فيتامين د منخفضة قليلًا."},{s:0,t:"Was kann ich gegen den festgestellten Vitamin-D-Mangel tun?",ar:"ماذا يمكنني أن أفعل حيال نقص فيتامين د الملاحظ؟"},{s:1,t:"Die empfohlene Lösung ist einfach: täglich eine halbe Stunde an die frische Luft und im Winter ein Präparat aus der Apotheke.",ar:"الحل الموصى به بسيط: نصف ساعة يوميًا في الهواء الطلق، وفي الشتاء مستحضر من الصيدلية."},{s:0,t:"Das werde ich tun. Gibt es Nebenwirkungen bei dem Präparat?",ar:"سأفعل ذلك. هل للمستحضر آثار جانبية؟"},{s:1,t:"Das verordnete Präparat ist gut verträglich. Nehmen Sie es bitte immer zum Essen ein.",ar:"المستحضر الموصوف جيد التحمل. تناوليه دائمًا مع الطعام."},{s:0,t:"In Ordnung. Muss ich wegen der erhöhten Werte auch einen Facharzt aufsuchen?",ar:"حسنًا. هل يجب أن أراجع طبيبًا مختصًا بسبب القيم المرتفعة؟"},{s:1,t:"Nein, das ist nicht nötig. Die vorliegenden Befunde kann ich als Ihr Hausarzt selbst weiter betreuen.",ar:"لا، ليس ضروريًا. يمكنني كطبيب عائلتك متابعة النتائج الموجودة بنفسي."},{s:0,t:"Gut. Und was ist mit dem Ultraschall, der letzte Woche gemacht wurde?",ar:"جيد. وماذا عن فحص الموجات فوق الصوتية الذي أُجري الأسبوع الماضي؟"},{s:1,t:"Die durchgeführte Ultraschalluntersuchung war völlig unauffällig. Alle Organe sehen gesund aus.",ar:"فحص الموجات فوق الصوتية الذي أُجري كان طبيعيًا تمامًا. جميع الأعضاء تبدو سليمة."},{s:0,t:"Das freut mich sehr. Ich hatte mir wegen der Bauchschmerzen Sorgen gemacht.",ar:"هذا يسعدني كثيرًا. كنت قلقة بسبب آلام البطن."},{s:1,t:"Die gemeldeten Beschwerden hängen wahrscheinlich mit Ihrer Ernährung zusammen. Mit der Umstellung sollten sie verschwinden.",ar:"الشكاوى المذكورة ترتبط على الأرجح بنظامك الغذائي. مع تغيير النظام يجب أن تختفي."},{s:0,t:"Das hoffe ich. Wann soll ich wiederkommen, wenn die Beschwerden bleiben?",ar:"آمل ذلك. متى يجب أن أعود إذا استمرت الأعراض؟"},{s:1,t:"Die vereinbarte Regel ist: Wenn die Schmerzen nach vier Wochen nicht besser sind, melden Sie sich bitte sofort.",ar:"القاعدة المتفق عليها هي: إذا لم تتحسن الآلام بعد أربعة أسابيع، فتواصلي معنا فورًا."},{s:0,t:"Das werde ich tun. Vielen Dank für die ausführliche Erklärung.",ar:"سأفعل ذلك. شكرًا جزيلًا على الشرح المفصل."},{s:1,t:"Gern geschehen. Hier ist der schriftliche Befund mit der empfohlenen Behandlung für zu Hause.",ar:"على الرحب والسعة. هذه نتيجة الفحص المكتوبة مع العلاج الموصى به في المنزل."},{s:0,t:"Danke. Ich lese mir alles in Ruhe durch und fange morgen mit dem Gehen an.",ar:"شكرًا. سأقرأ كل شيء بهدوء وسأبدأ المشي غدًا."},{s:1,t:"Sehr gut. Die anstehende Kontrolle in drei Monaten trage ich schon in Ihren Terminplan ein.",ar:"جيد جدًا. فحص المتابعة القادم بعد ثلاثة أشهر سأسجله بالفعل في جدول مواعيدك."},{s:0,t:"Perfekt. Ich wünsche Ihnen noch einen schönen Tag.",ar:"ممتاز. أتمنى لك يومًا سعيدًا."},{s:1,t:"Ihnen auch. Und denken Sie daran: Kleine Schritte führen zu großen Verbesserungen. Auf Wiedersehen!",ar:"وأنت أيضًا. وتذكري: الخطوات الصغيرة تؤدي إلى تحسينات كبيرة. إلى اللقاء!"}]}},{stage:12,topic:"home",topicAr:"المنزل والسكن",topicEn:"Dispute with a neighbour",topicDe:"Nachbarschaftsstreit",emoji:"🏘️",title:"خلاف مع الجار",grammar:{id:"de-b2-genitiv-praepositionen",title:"Genitiv und Präpositionen",titleAr:"المضاف إليه وحروف الجر",covers:1},conv:{id:"de-stage12-b2",speakers:["Nachbar (جار)","Nachbarin (جارة)"],turns:[{s:0,t:"Guten Abend. Entschuldigen Sie die Störung, aber wir müssen über den Lärm sprechen.",ar:"مساء الخير، عذرًا على الإزعاج، لكن يجب أن نتحدث عن الضجيج."},{s:1,t:"Guten Abend. Ja, ich habe schon vermutet, dass Sie wegen des Lärms kommen.",ar:"مساء الخير، نعم، لقد توقعت أنك قادم بسبب الضجيج."},{s:0,t:"Seit Wochen ist es abends sehr laut bei Ihnen. Wegen des ständigen Lärms kann meine Tochter nicht schlafen.",ar:"منذ أسابيع والضجيج عندكم مرتفع جدًا في المساء. بسبب الضجيج المستمر لا تستطيع ابنتي النوم."},{s:1,t:"Das tut mir leid. Mir war nicht bewusst, dass der Lärm so stark in Ihre Wohnung dringt.",ar:"يؤسفني ذلك. لم أكن أدرك أن الضجيج يصل إلى شقتكم بهذه القوة."},{s:0,t:"Besonders während der Nacht ist es schlimm. Gestern ging die Musik bis nach Mitternacht.",ar:"الأمر سيئ بشكل خاص أثناء الليل. بالأمس استمرت الموسيقى حتى بعد منتصف الليل."},{s:1,t:"Gestern hatten wir Besuch. Anlässlich des Geburtstags meines Sohnes haben wir etwas länger gefeiert.",ar:"بالأمس كان لدينا ضيوف. بمناسبة عيد ميلاد ابني احتفلنا لفترة أطول قليلًا."},{s:0,t:"Das verstehe ich. Aber laut der Hausordnung gilt ab 22 Uhr Nachtruhe.",ar:"أفهم ذلك. لكن وفقًا لنظام المنزل، يبدأ الهدوء الليلي من الساعة العاشرة مساءً."},{s:1,t:"Sie haben recht. Trotz der Feier hätten wir früher leiser werden müssen.",ar:"أنت محق. رغم الاحتفال، كان يجب أن نخفض الصوت مبكرًا."},{s:0,t:"Es ist nicht nur die Musik. Auch tagsüber ist es oft laut, zum Beispiel das Bohren am Wochenende.",ar:"ليست الموسيقى فقط. ففي النهار أيضًا يكون الضجيج مرتفعًا غالبًا، مثل الحفر في عطلة نهاية الأسبوع."},{s:1,t:"Das Bohren war aufgrund der Renovierung nötig. Wir haben ein neues Regal angebracht.",ar:"كان الحفر ضروريًا بسبب أعمال التجديد. قمنا بتركيب رف جديد."},{s:0,t:"Innerhalb der Ruhezeiten sollte man solche Arbeiten eigentlich nicht machen. Samstags nach 13 Uhr ist Ruhezeit.",ar:"داخل أوقات الهدوء لا يجوز القيام بمثل هذه الأعمال. يوم السبت بعد الواحدة ظهرًا وقت هدوء."},{s:1,t:"Das wusste ich nicht. Ich dachte, am Samstag sei das Bohren den ganzen Tag erlaubt.",ar:"لم أكن أعرف ذلك. ظننت أن الحفر مسموح يوم السبت طوال اليوم."},{s:0,t:"Nein, leider nicht. Laut der Hausordnung sind laute Arbeiten nur bis 13 Uhr erlaubt.",ar:"لا، للأسف ليس كذلك. وفقًا لنظام المنزل، الأعمال الصاخبة مسموحة فقط حتى الواحدة ظهرًا."},{s:1,t:"Gut, dass Sie es mir sagen. In Zukunft werde ich mich an die Zeiten halten.",ar:"من الجيد أنك أخبرتني. في المستقبل سألتزم بالأوقات."},{s:0,t:"Das freut mich. Es geht mir nicht um einen Streit, sondern um eine Lösung.",ar:"يسعدني ذلك. الأمر لا يتعلق بخلاف، بل بإيجاد حل."},{s:1,t:"Mir auch nicht. Infolge des Missverständnisses ist die Stimmung zwischen uns leider schlechter geworden.",ar:"ولا بالنسبة لي. نتيجة لسوء الفهم، ساءت الأجواء بيننا للأسف."},{s:0,t:"Das stimmt. Seitens meiner Familie gibt es aber keinen Groll. Wir wollen einfach wieder ruhig wohnen.",ar:"هذا صحيح. لكن من جانب عائلتي لا يوجد أي حقد. نريد فقط أن نعيش بهدوء مجددًا."},{s:1,t:"Das verstehe ich vollkommen. Wegen der Renovierung war es in den letzten Wochen besonders laut, aber die Arbeiten sind jetzt fast fertig.",ar:"أفهم ذلك تمامًا. بسبب أعمال التجديد كان الضجيج مرتفعًا بشكل خاص في الأسابيع الأخيرة، لكن الأعمال شارفت على الانتهاء."},{s:0,t:"Das ist eine gute Nachricht. Wie lange dauern die Arbeiten noch?",ar:"هذا خبر جيد. كم ستدوم الأعمال بعد؟"},{s:1,t:"Noch etwa eine Woche. Mithilfe eines Handwerkers werden wir die letzten Arbeiten schnell abschließen.",ar:"نحو أسبوع آخر. بمساعدة عامل حرفي سننهي الأعمال الأخيرة بسرعة."},{s:0,t:"In Ordnung. Und was ist mit den Abenden? Könnten wir uns auf eine Uhrzeit einigen?",ar:"حسنًا. وماذا عن الأمسيات؟ هل يمكننا الاتفاق على وقت معين؟"},{s:1,t:"Selbstverständlich. Außerhalb der Ruhezeiten, also bis 22 Uhr, ist normale Lautstärke kein Problem, oder?",ar:"بالطبع. خارج أوقات الهدوء، أي حتى العاشرة مساءً، لا مشكلة في الصوت العادي، أليس كذلك؟"},{s:0,t:"Genau. Bis 22 Uhr ist alles in Ordnung. Danach sollte es leise sein.",ar:"بالضبط. حتى العاشرة مساءً كل شيء على ما يرام. بعد ذلك يجب أن يكون الأمر هادئًا."},{s:1,t:"Einverstanden. Und falls wir einmal eine Feier planen, sage ich Ihnen vorher Bescheid.",ar:"متفق عليه. وإذا خططنا لحفلة مرة، سأخبرك مسبقًا."},{s:0,t:"Das wäre sehr nett. Dank Ihrer Ankündigung könnten wir uns darauf einstellen.",ar:"سيكون ذلك لطيفًا جدًا. وبفضل إخبارك المسبق، يمكننا الاستعداد لذلك."},{s:1,t:"Gern. Und wenn Sie einmal eine Feier haben, sagen Sie mir ebenfalls Bescheid.",ar:"بكل سرور. وإذا كان لديك حفلة مرة، أخبرني أيضًا."},{s:0,t:"Natürlich. Gegenseitige Rücksicht ist die Grundlage des guten Zusammenlebens.",ar:"بالطبع. الاحترام المتبادل هو أساس حسن الجوار."},{s:1,t:"Da stimme ich Ihnen zu. Vielleicht sollten wir auch mit der Hausverwaltung sprechen, um die Ruhezeiten für alle klarzustellen.",ar:"أوافقك على ذلك. ربما يجب أن نتحدث أيضًا مع إدارة المنزل لتوضيح أوقات الهدوء للجميع."},{s:0,t:"Das ist eine gute Idee. Seitens der Hausverwaltung könnte ein Aushang im Treppenhaus helfen.",ar:"هذه فكرة جيدة. من جانب إدارة المنزل، قد يساعد إعلان في الدرج."},{s:1,t:"Genau. Ein Aushang würde allen Nachbarn die Regeln ins Gedächtnis rufen.",ar:"بالضبط. الإعلان سيُذكّر جميع الجيران بالقواعد."},{s:0,t:"Ich schreibe morgen eine kurze Nachricht an die Verwaltung. Wären Sie einverstanden, wenn ich unsere Vereinbarung erwähne?",ar:"سأكتب غدًا رسالة قصيرة إلى الإدارة. هل توافق إذا ذكرت اتفاقنا فيها؟"},{s:1,t:"Ja, gern. Je mehr Nachbarn von der Vereinbarung wissen, desto besser.",ar:"نعم، بكل سرور. كلما عرف مزيد من الجيران بالاتفاق، كان ذلك أفضل."},{s:0,t:"Perfekt. Dann ist die Sache für mich erledigt. Ich hoffe, wir können wieder gut miteinander auskommen.",ar:"ممتاز. إذن الأمر منتهٍ بالنسبة لي. آمل أن نتعايش جيدًا مجددًا."},{s:1,t:"Das hoffe ich auch. Trotz der Schwierigkeiten in den letzten Wochen schätze ich Sie als Nachbarn sehr.",ar:"آمل ذلك أيضًا. رغم الصعوبات في الأسابيع الأخيرة، أقدّرك كثيرًا كجار."},{s:0,t:"Das freut mich zu hören. Dank Ihrer Offenheit haben wir das Problem schnell gelöst.",ar:"يسعدني سماع ذلك. وبفضل انفتاحك، حللنا المشكلة بسرعة."},{s:1,t:"Offenheit hilft immer. Übrigens: Wenn Sie einmal Hilfe brauchen, klopfen Sie einfach an.",ar:"الانفتاح يساعد دائمًا. بالمناسبة: إذا احتجت إلى مساعدة مرة، اطرق بابي فقط."},{s:0,t:"Das werde ich tun. Und dasselbe gilt für Sie.",ar:"سأفعل ذلك. والشيء نفسه ينطبق عليك."},{s:1,t:"Abgemacht. Dann wünsche ich Ihnen und Ihrer Tochter eine ruhige Nacht.",ar:"اتفقنا. إذن أتمنى لك ولابنتك ليلة هادئة."},{s:0,t:"Vielen Dank. Ihnen auch einen schönen Abend.",ar:"شكرًا جزيلًا. وأتمنى لك أمسية سعيدة."},{s:1,t:"Danke. Auf Wiedersehen!",ar:"شكرًا. إلى اللقاء!"},{s:0,t:"Auf Wiedersehen — und bis zum nächsten Mal im Treppenhaus!",ar:"إلى اللقاء — وإلى اللقاء القادم في الدرج!"},{s:1,t:"Bis bald!",ar:"إلى اللقاء قريبًا!"}]}}]};var CONV_DATA_C1={en:[{stage:1,topic:"philosophy",topicAr:"الفلسفة والأفكار",topicEn:"Philosophy & Ideas",topicDe:"Philosophie und Ideen",emoji:"🤔",title:"هل الوعي مجرد وهم؟",grammar:{id:"en-c1-inversion-full",title:"Inversion",titleAr:"القلب (التقديم والتأخير)",covers:1},conv:{id:"en-stage1-c1",speakers:["Professor (الأستاذ)","Student (الطالب)"],turns:[{s:0,t:"Okay, so let me get this straight. You're saying consciousness is just a side effect of the brain?",ar:"حسنًا، دعني أفهم هذا جيدًا. أنت تقول إن الوعي مجرد أثر جانبي للدماغ؟"},{s:1,t:"That's the proposition, yeah. Not some magical spark — just what happens when neurons fire in a certain pattern.",ar:"هذا هو الاقتراح، نعم. ليس شرارة سحرية — بل ما يحدث حين تُطلق الخلايا العصبية إشاراتها بنمط معين."},{s:0,t:"But that feels wrong, doesn't it? I mean, the feeling of being me — it's so... real.",ar:"لكن هذا يبدو خاطئًا، أليس كذلك؟ أعني، شعوري بأنني أنا — إنه حقيقي جدًا."},{s:1,t:"Real, sure. But real doesn't mean separate from the brain. Pain is real too, and it's wholly physical.",ar:"حقيقي، بالتأكيد. لكن الحقيقي لا يعني منفصلًا عن الدماغ. الألم حقيقي أيضًا، وهو جسدي بالكامل."},{s:0,t:"Hmm. So where does that leave free will? If everything's just chemistry, then—",ar:"همم. إذن أين يترك ذلك الإرادة الحرة؟ إذا كان كل شيء مجرد كيمياء، فعندها—"},{s:1,t:"—Then choice is an illusion? That's the classic move, and honestly, it's a lazy one.",ar:"—إذن فالاختيار وهم؟ هذه هي الحجة الكلاسيكية، وبصراحة، إنها حجة كسولة."},{s:0,t:"Lazy? Come on, it's the logical conclusion of your own argument!",ar:"كسولة؟ هيا، إنها النتيجة المنطقية لحجتك أنت!"},{s:1,t:"Not necessarily. Look, even if the underlying process is physical, the level where decisions happen still matters.",ar:"ليس بالضرورة. انظر، حتى لو كانت العملية الكامنة جسدية، فإن المستوى الذي تحدث فيه القرارات ما زال مهمًا."},{s:0,t:"Okay, I guess what I'm saying is — if I couldn't have done otherwise, how can you blame me?",ar:"حسنًا، أظن أن ما أقوله هو — إذا لم أكن أستطيع أن أفعل غير ذلك، فكيف يمكنك أن تلومني؟"},{s:1,t:"Because blame isn't about metaphysics. It's about shaping behavior. We hold people responsible so they'll act differently next time.",ar:"لأن اللوم لا يتعلق بالميتافيزيقا. بل بتشكيل السلوك. نحن نُحمّل الناس المسؤولية لكي يتصرفوا بشكل مختلف في المرة القادمة."},{s:0,t:"That sounds... practical, I guess. But it dodges the real question.",ar:"هذا يبدو... عمليًا، أظن. لكنه يتجنب السؤال الحقيقي."},{s:1,t:"Does it? Or does it just refuse to play a game with no winner? Some questions aren't deep — they're just badly framed.",ar:"هل يتجنبه؟ أم أنه يرفض فقط لعب لعبة بلا فائز؟ بعض الأسئلة ليست عميقة — بل مصاغة بشكل سيئ."},{s:0,t:"Whoa. Okay, so you're telling me two thousand years of philosophy was just bad framing?",ar:"واو. حسنًا، إذن أنت تقول لي إن ألفي سنة من الفلسفة كانت مجرد صياغة سيئة؟"},{s:1,t:"Not all of it. But a lot of it, yeah. Take the old debates about the soul — they presume there's a thing to find.",ar:"ليس كلها. لكن الكثير منها، نعم. خذ النقاشات القديمة عن الروح — إنها تفترض وجود شيء يمكن العثور عليه."},{s:0,t:"And you think there's nothing to find.",ar:"وأنت تظن أنه لا يوجد شيء يمكن العثور عليه."},{s:1,t:"I think the search itself tells us something. People have worshipped the idea of a soul for centuries — and that longing is data too.",ar:"أظن أن البحث نفسه يخبرنا بشيء. لقد عبد الناس فكرة الروح لقرون — وذلك الشوق هو بحد ذاته معطيات."},{s:0,t:"Interesting. So religion, in your view, is just... psychology in fancy dress?",ar:"مثير للاهتمام. إذن فالدين، في رأيك، هو مجرد... علم نفس بملابس فاخرة؟"},{s:1,t:"That's a bit reductive, but... yeah, partly. Though I'd say the longing for glory, for meaning — that's inherent to being human.",ar:"هذا تبسيط بعض الشيء، لكن... نعم، جزئيًا. مع أنني أقول إن التوق إلى المجد، إلى المعنى — متأصل في كوننا بشرًا."},{s:0,t:"Inherent, huh? So we're wired to want meaning, even if there is none?",ar:"متأصل، هاه؟ إذن نحن مبرمجون على الرغبة في المعنى، حتى لو لم يكن هناك معنى؟"},{s:1,t:"Pretty much. And that's not a tragedy — it's the starting point. Meaning isn't found, it's made.",ar:"تقريبًا. وهذا ليس مأساة — بل نقطة البداية. المعنى لا يُعثر عليه، بل يُصنع."},{s:0,t:"I like that. But hold on — if meaning is made up, isn't it just a comforting lie?",ar:"يعجبني هذا. لكن انتظر — إذا كان المعنى مُختلقًا، أليس مجرد كذبة مريحة؟"},{s:1,t:"Only if you think truth has to come from outside us. A story can be invented and still be worthy of living by.",ar:"فقط إذا كنت تظن أن الحقيقة يجب أن تأتي من خارجنا. القصة يمكن أن تكون مخترعة وما زالت جديرة بأن نعيش وفقها."},{s:0,t:"Hmm. The devil's advocate in me says that's a slippery slope. If we invent our own truth, anything goes.",ar:"همم. محامي الشيطان في داخلي يقول إن هذا منحدر زلق. إذا اخترعنا حقيقتنا الخاصة، فكل شيء مباح."},{s:1,t:"No way. That's the stereotype of relativism, and it's wrong. Invented doesn't mean arbitrary — some stories hold up, others collapse.",ar:"مستحيل. هذه هي الصورة النمطية عن النسبية، وهي خاطئة. المخترع لا يعني العشوائي — بعض القصص تصمد، وبعضها ينهار."},{s:0,t:"Collapse how? Who decides?",ar:"تنهار كيف؟ من يقرر؟"},{s:1,t:"Reality does, eventually. A belief that helps you navigate the world survives. One that doesn't... fades.",ar:"الواقع يقرر، في النهاية. الاعتقاد الذي يساعدك على التنقل في العالم يبقى. والذي لا يساعد... يتلاشى."},{s:0,t:"Okay, but what about ideology? People cling to beliefs that clearly hurt them.",ar:"حسنًا، لكن ماذا عن الأيديولوجيا؟ الناس يتمسكون بمعتقدات تؤذيهم بوضوح."},{s:1,t:"Because ideology isn't about truth — it's about belonging. Giving it up can feel like betraying your whole tribe.",ar:"لأن الأيديولوجيا لا تتعلق بالحقيقة — بل بالانتماء. التخلي عنها قد يبدو كخيانة لقبيلتك كلها."},{s:0,t:"So reason loses to loyalty. That's... depressing, honestly.",ar:"إذن العقل يخسر أمام الولاء. هذا... محبط، بصراحة."},{s:1,t:"Seemingly, yeah. But reflection is a skill — you can train it. People do change their minds, just slowly.",ar:"ظاهريًا، نعم. لكن التأمل مهارة — يمكنك تدريبها. الناس يغيرون آراءهم فعلًا، لكن ببطء."},{s:0,t:"Slowly is right. My uncle's believed the same conspiracy for twenty years.",ar:"ببطء هذا صحيح. عمي يؤمن بنفس نظرية المؤامرة منذ عشرين سنة."},{s:1,t:"And presumably he'll keep believing it. The contrary evidence just bounces off — that's how the mind protects itself.",ar:"ومن المفترض أنه سيستمر في الإيمان بها. الأدلة المخالفة ترتد عنه ببساطة — هكذا يحمي العقل نفسه."},{s:0,t:"So what's the point of philosophy, then? If nobody changes their mind?",ar:"إذن ما فائدة الفلسفة؟ إذا لم يغير أحد رأيه؟"},{s:1,t:"The point isn't winning arguments. It's learning to notice your own blind spots. That's the whole game.",ar:"الهدف ليس الفوز بالحجج. بل تعلّم ملاحظة نقاطك العمياء. هذه هي اللعبة كلها."},{s:0,t:"Blind spots. Yeah, I guess everyone has a demon or two hiding in theirs.",ar:"النقاط العمياء. نعم، أظن أن لدى كل شخص شيطانًا أو اثنين يختبئان فيها."},{s:1,t:"Exactly. And a thoughtful person doesn't pretend otherwise — they go looking for them.",ar:"بالضبط. والشخص المتأمل لا يتظاهر بخلاف ذلك — بل يذهب للبحث عنها."},{s:0,t:"That's a miracle in itself, if you ask me. Most people would rather be right than be honest.",ar:"هذا معجزة بحد ذاته، إذا سألتني. معظم الناس يفضلون أن يكونوا على صواب على أن يكونوا صادقين."},{s:1,t:"Nonetheless, the ones who try — they're the ones worth listening to.",ar:"ومع ذلك، الذين يحاولون — هم الذين يستحقون الاستماع إليهم."},{s:0,t:"Wit and wisdom in one package, huh? You should put that on a poster.",ar:"ذكاء وحكمة في حزمة واحدة، هاه؟ يجب أن تضع ذلك على ملصق."},{s:1,t:"Ha! I'll pass. But seriously — the realm of ideas is the only place where losing an argument can actually make you richer.",ar:"ها! سأمتنع. لكن بجدية — عالم الأفكار هو المكان الوحيد حيث خسارة الحجة يمكن أن تجعلك أغنى فعلًا."},{s:0,t:"Wait — one more thing. Do you think our ideas about the mind originate in the brain, or in the culture we grow up in?",ar:"انتظر — شيء آخر. هل تظن أن أفكارنا عن العقل تنشأ في الدماغ، أم في الثقافة التي نكبر فيها؟"},{s:1,t:"Both, I'd say — the brain gives the raw material, culture gives it shape. You can't draw a clean separation between the two spheres.",ar:"كلاهما، أقول — الدماغ يعطي المادة الخام، والثقافة تعطيها الشكل. لا يمكنك رسم فصل نظيف بين العالمين."},{s:0,t:"So philosophers who contend the mind is purely physical — are they missing the cultural half?",ar:"إذن الفلاسفة الذين يجادلون بأن العقل جسدي بحت — هل يفوتهم النصف الثقافي؟"},{s:1,t:"Some are. The best ones embody both sides — they strive for a view that holds the brain and the meaning together, in harmony.",ar:"بعضهم كذلك. أفضلهم يجسدون الجانبين — يسعون إلى رؤية تجمع الدماغ والمعنى معًا، في تناغم."},{s:0,t:"Actually, let me characterize the other side fairly — even ideas I defy deserve a steelman, not a strawman.",ar:"في الواقع، دعني أوصف الجانب الآخر بإنصاف — حتى الأفكار التي أتحداها تستحق أقوى حجة، لا حجة رجل القش."},{s:1,t:"Ironically, that's where most debates collapse — the intent is to win, not to understand. Embark on a real conversation and the dominance game falls apart.",ar:"ومن المفارقات أن هذا هو حيث تنهار معظم النقاشات — النية هي الفوز، لا الفهم. ابدأ محادثة حقيقية وتنهار لعبة الهيمنة."},{s:0,t:"Alright, alright. You've convinced me — at least for today.",ar:"حسنًا، حسنًا. لقد أقنعتني — على الأقل لهذا اليوم."},{s:1,t:"I'll take it. A viable conversion, even a temporary one, counts.",ar:"سأقبل بذلك. تحوّل قابل للاستمرار، حتى لو كان مؤقتًا، يُحسب."}]}},{stage:2,topic:"science",topicAr:"العلم والاكتشاف",topicEn:"Science & Discovery",topicDe:"Wissenschaft und Entdeckung",emoji:"🔬",title:"العلم حين يصطدم باليقين",grammar:{id:"en-c1-cleft-sentences",title:"Cleft sentences",titleAr:"الجمل المنقسمة",covers:1},conv:{id:"en-stage2-c1",speakers:["Scientist (العالم)","Colleague (الزميل)"],turns:[{s:0,t:"So the results are in — and honestly, I'm stunned. The new drug actually works?",ar:"إذن النتائج صدرت — وبصراحة، أنا مندهش. الدواء الجديد يعمل فعلًا؟"},{s:1,t:"It does. The trial data is robust — three thousand patients, double-blind, and the effect held up across every group.",ar:"نعم يعمل. بيانات التجربة قوية — ثلاثة آلاف مريض، مزدوجة التعمية، والتأثير صمد في كل المجموعات."},{s:0,t:"Wow. But wait — didn't the earlier study say the opposite? How do we explain that?",ar:"واو. لكن انتظر — ألم تقل الدراسة السابقة العكس؟ كيف نفسر ذلك؟"},{s:1,t:"The earlier study had a tiny sample and a flawed configuration. Different dose, different timing — it wasn't even measuring the same thing.",ar:"الدراسة السابقة كانت بعينة صغيرة وتكوين معيب. جرعة مختلفة، توقيت مختلف — لم تكن تقيس الشيء نفسه أصلًا."},{s:0,t:"That's the part that drives me crazy about science. One week coffee kills you, the next week it saves you.",ar:"هذا هو الجزء الذي يجننني في العلم. أسبوع يقولون القهوة تقتلك، والأسبوع التالي تقول إنها تنقذك."},{s:1,t:"Yeah, but that's the media, not science. A single study is a clue, not a verdict.",ar:"نعم، لكن هذه وسائل الإعلام، وليس العلم. دراسة واحدة هي دليل، وليست حكمًا نهائيًا."},{s:0,t:"Fair point. Still, how's the average person supposed to tell what's credible?",ar:"نقطة عادلة. مع ذلك، كيف يُفترض بالشخص العادي أن يعرف ما هو موثوق؟"},{s:1,t:"Look for replication. If five independent labs get the same result, that's a signal. If it's one flashy paper — be skeptical.",ar:"ابحث عن التكرار. إذا حصلت خمسة مختبرات مستقلة على النتيجة نفسها، فهذه إشارة. أما إذا كانت ورقة واحدة براقة — فكن متشككًا."},{s:0,t:"And what about the stuff that never gets published? The failed experiments?",ar:"وماذا عن الأشياء التي لا تُنشر أبدًا؟ التجارب الفاشلة؟"},{s:1,t:"That's a real problem. Journals love a positive result. Negative results just... vanish.",ar:"هذه مشكلة حقيقية. المجلات تحب النتائج الإيجابية. أما النتائج السلبية فتختفي ببساطة."},{s:0,t:"Which means the literature is biased toward what worked. That's kind of terrifying.",ar:"مما يعني أن الأدبيات منحازة نحو ما نجح. هذا مخيف نوعًا ما."},{s:1,t:"It is. And it can distort the whole field — people keep chasing an effect that was never real.",ar:"إنه كذلك. ويمكن أن يشوه المجال كله — الناس يستمرون في مطاردة تأثير لم يكن حقيقيًا أبدًا."},{s:0,t:"So how do we fix it? Pre-registration? Open data?",ar:"إذن كيف نصلح ذلك؟ التسجيل المسبق؟ البيانات المفتوحة؟"},{s:1,t:"Both, and more. The composition of a good study now includes sharing raw data — no more black boxes.",ar:"كلاهما، وأكثر. تكوين الدراسة الجيدة الآن يشمل مشاركة البيانات الخام — لا مزيد من الصناديق السوداء."},{s:0,t:"I love that. But let's be honest — a lot of researchers won't do it unless they're forced to.",ar:"يعجبني هذا. لكن لنكن صادقين — كثير من الباحثين لن يفعلوا ذلك ما لم يُجبروا عليه."},{s:1,t:"True. Change in science is slow — the old guard defends its turf. But the momentum is shifting.",ar:"صحيح. التغيير في العلم بطيء — الحرس القديم يدافع عن أرضه. لكن الزخم يتغير."},{s:0,t:"Speaking of momentum — what about AI in the lab? Is it actually helping, or just hype?",ar:"بالحديث عن الزخم — ماذا عن الذكاء الاصطناعي في المختبر؟ هل يساعد فعلًا، أم مجرد ضجة؟"},{s:1,t:"Both, honestly. It can scan thousands of variables in minutes — stuff that'd take a grad student years. But it can also hallucinate patterns.",ar:"كلاهما، بصراحة. يمكنه فحص آلاف المتغيرات في دقائق — أشياء تستغرق طالب دراسات عليا سنوات. لكنه قد يتوهم أنماطًا أيضًا."},{s:0,t:"Hallucinate patterns — that's a great phrase. So the human still has to check the work.",ar:"يتوهم أنماطًا — هذه عبارة رائعة. إذن ما زال على الإنسان أن يتحقق من العمل."},{s:1,t:"Absolutely. The tool doesn't replace judgment — it amplifies it, for better or worse.",ar:"بالتأكيد. الأداة لا تحل محل الحكم — بل تضخمه، للأفضل أو للأسوأ."},{s:0,t:"Okay, switching gears — the climate models. People say they're always wrong. Are they?",ar:"حسنًا، لنغيّر الموضوع — نماذج المناخ. الناس يقولون إنها مخطئة دائمًا. هل هي كذلك؟"},{s:1,t:"They're not wrong — they're ranges. A model gives you a span of outcomes, and people cherry-pick the edge they like.",ar:"ليست مخطئة — بل نطاقات. النموذج يعطيك مدى من النتائج، والناس ينتقون الطرف الذي يعجبهم."},{s:0,t:"So the uncertainty is the feature, not the bug.",ar:"إذن عدم اليقين هو الميزة، وليس الخلل."},{s:1,t:"Exactly. And the fluid dynamics alone — oceans, atmosphere, ice — it's insanely complex. The fact that models work at all is a miracle.",ar:"بالضبط. وديناميكا الموائع وحدها — المحيطات والغلاف الجوي والجليد — معقدة بشكل جنوني. كون النماذج تعمل أصلًا معجزة."},{s:0,t:"But then how do we act on them? If the range is huge, policymakers just freeze.",ar:"لكن كيف نتصرف بناءً عليها إذن؟ إذا كان المدى ضخمًا، فإن صناع السياسة يتجمدون ببساطة."},{s:1,t:"That's where risk thinking comes in. You don't need certainty — you need to weigh the odds. And the odds here are ugly.",ar:"هنا يأتي دور التفكير بالمخاطر. لا تحتاج إلى يقين — بل إلى موازنة الاحتمالات. والاحتمالات هنا قبيحة."},{s:0,t:"Yeah... the hydrogen economy, geoengineering — everyone wants a magic fix.",ar:"نعم... اقتصاد الهيدروجين، والهندسة الجيولوجية — الجميع يريد حلًا سحريًا."},{s:1,t:"There's no magic fix. There's a cluster of partial fixes, and they all need to happen at once.",ar:"لا يوجد حل سحري. هناك مجموعة من الحلول الجزئية، ويجب أن تحدث جميعها دفعة واحدة."},{s:0,t:"Depressing. But let me ask you something more hopeful — what's the most exciting thing in your field right now?",ar:"محبط. لكن دعني أسألك شيئًا أكثر تفاؤلًا — ما أكثر شيء مثير في مجالك الآن؟"},{s:1,t:"Oh, that's easy. CRISPR in the liver — we can now edit genes in a living organ, in a living person. That's tremendous.",ar:"أوه، هذا سهل. كريسبر في الكبد — يمكننا الآن تعديل الجينات في عضو حي، في شخص حي. هذا هائل."},{s:0,t:"Whoa. In a living person? That sounds like science fiction.",ar:"واو. في شخص حي؟ هذا يبدو كخيال علمي."},{s:1,t:"It did, five years ago. Now it's a clinical reality — and the adaptation of the technique keeps getting faster.",ar:"كان كذلك قبل خمس سنوات. الآن أصبح واقعًا سريريًا — وتكييف التقنية يستمر في التسارع."},{s:0,t:"But the risks — what if the edit goes wrong? A lethal mistake in someone's kidney or limb?",ar:"لكن المخاطر — ماذا لو حدث خطأ في التعديل؟ خطأ قاتل في كلية شخص أو طرفه؟"},{s:1,t:"That's the nightmare scenario, and we take it seriously. Every edit is tracked, every variable controlled.",ar:"هذا هو السيناريو الكابوسي، ونأخذه بجدية. كل تعديل يُتتبع، وكل متغير يُضبط."},{s:0,t:"Still, it makes me nervous. Science moves fast, but regulation moves slow.",ar:"مع ذلك، هذا يجعلني متوترًا. العلم يتحرك بسرعة، لكن التنظيم يتحرك ببطء."},{s:1,t:"That's the eternal tension. Disrupt too fast and you hurt people; move too slow and people die waiting.",ar:"هذا هو التوتر الأبدي. أحدث تغييرًا سريعًا جدًا فتؤذي الناس؛ وتحرك ببطء شديد فيموت الناس وهم ينتظرون."},{s:0,t:"So where's the balance? Who decides when it's safe enough?",ar:"إذن أين التوازن؟ من يقرر متى يكون آمنًا بما يكفي؟"},{s:1,t:"Committees, regulators, patients themselves. It's messy — but messy beats a vacuum where nobody's in charge.",ar:"اللجان والمنظمون والمرضى أنفسهم. إنه فوضوي — لكن الفوضى أفضل من فراغ لا أحد فيه مسؤول."},{s:0,t:"A vacuum of responsibility. Yeah, I've seen that in every institution.",ar:"فراغ في المسؤولية. نعم، رأيت ذلك في كل مؤسسة."},{s:1,t:"Right? The width of the gap between what we can do and what we should do just keeps growing.",ar:"صحيح؟ اتساع الفجوة بين ما نستطيع فعله وما يجب أن نفعله يستمر في النمو."},{s:0,t:"Okay, last question — if you could bolster one thing in science, what would it be?",ar:"حسنًا، سؤال أخير — إذا استطعت تعزيز شيء واحد في العلم، فما هو؟"},{s:1,t:"Trust. Not blind trust — earned trust. We need to show our work, admit our mistakes, and let people in.",ar:"الثقة. ليست ثقة عمياء — بل ثقة مكتسبة. نحتاج أن نُظهر عملنا، ونعترف بأخطائنا، ونسمح للناس بالدخول."},{s:0,t:"One more thing — can a drug induce a change in the liver without injecting anything directly into it?",ar:"شيء آخر — هل يمكن لدواء أن يُحدث تغييرًا في الكبد دون حقن أي شيء مباشرة فيه؟"},{s:1,t:"Yeah, that's the goal — an oral dose that the gut absorbs. The effectiveness depends on the delivery, not the needle.",ar:"نعم، هذا هو الهدف — جرعة فموية يمتصها الأمعاء. الفعالية تعتمد على التوصيل، وليس على الإبرة."},{s:0,t:"And the implementation? Hospitals would need new protocols, right?",ar:"والتنفيذ؟ المستشفيات ستحتاج إلى بروتوكولات جديدة، صحيح؟"},{s:1,t:"Exactly. And every indicator we track — recovery time, side effects — has to show the treatment is integral to care, not just an instrumental add-on.",ar:"بالضبط. وكل مؤشر نتتبعه — وقت التعافي والآثار الجانبية — يجب أن يُظهر أن العلاج جزء أساسي من الرعاية، وليس مجرد إضافة ثانوية."},{s:0,t:"Is this treatment applicable to kids too, or only adults? The dose question changes everything.",ar:"هل هذا العلاج قابل للتطبيق على الأطفال أيضًا، أم على البالغين فقط؟ سؤال الجرعة يغير كل شيء."},{s:1,t:"Good question — the trial designates adults only for now. A modification for younger patients is planned, and the remainder of the data comes next year.",ar:"سؤال جيد — التجربة تحدد البالغين فقط في الوقت الحالي. تعديل للمرضى الأصغر سنًا مخطط له، وبقية البيانات تأتي العام المقبل."},{s:0,t:"Show your work. Like in math class.",ar:"أظهر عملك. مثل حصة الرياضيات."},{s:1,t:"Exactly like math class. The answer matters less than the reasoning that got you there.",ar:"تمامًا مثل حصة الرياضيات. الإجابة أقل أهمية من التفكير الذي أوصلك إليها."}]}},{stage:3,topic:"psychology",topicAr:"علم النفس والعقل",topicEn:"Psychology & Mind",topicDe:"Psychologie und Geist",emoji:"🧠",title:"لماذا نفعل ما نفعله؟",grammar:{id:"en-c1-subjunctive",title:"Subjunctive mood",titleAr:"صيغة التمني والافتراض",covers:1},conv:{id:"en-stage3-c1",speakers:["Psychologist (الطبيب النفسي)","Client (العميل)"],turns:[{s:0,t:"Can I ask you something honest? Why do I keep doing the thing I know is bad for me?",ar:"هل يمكنني أن أسألك شيئًا بصراحة؟ لماذا أستمر في فعل الشيء الذي أعرف أنه سيئ بالنسبة لي؟"},{s:1,t:"Because knowing isn't the same as feeling. Your brain can know a thing is toxic and still crave it.",ar:"لأن المعرفة ليست مثل الشعور. دماغك قد يعرف أن شيئًا ما سام ومع ذلك يشتهيه."},{s:0,t:"That feels... unfair. Like I'm wired to sabotage myself.",ar:"هذا يبدو... ظالمًا. كأنني مبرمج على تخريب نفسي."},{s:1,t:"Not sabotage — protection. A lot of self-defeating habits started as coping strategies. They worked once, in a different context.",ar:"ليس تخريبًا — بل حماية. كثير من العادات المدمرة للذات بدأت كاستراتيجيات للتأقلم. لقد نجحت مرة، في سياق مختلف."},{s:0,t:"So my brain is running old software. Great.",ar:"إذن دماغي يعمل ببرنامج قديم. رائع."},{s:1,t:"Pretty much. And the tricky part is, the old software feels safe. Change feels like a threat, even when it's good for you.",ar:"تقريبًا. والجزء الصعب هو أن البرنامج القديم يبدو آمنًا. التغيير يبدو كتهديد، حتى عندما يكون جيدًا لك."},{s:0,t:"That explains why I snap at people when I'm stressed. It's automatic.",ar:"هذا يفسر لماذا أنفجر في وجه الناس عندما أكون متوترًا. إنه تلقائي."},{s:1,t:"Exactly — a persistent pattern, not a character flaw. The frustration builds, and the grip on your temper just... slips.",ar:"بالضبط — نمط مستمر، وليس عيبًا في الشخصية. الإحباط يتراكم، وقبضتك على أعصابك تنزلق ببساطة."},{s:0,t:"But then how do I stop it? I can't just think my way out of it — I've tried.",ar:"لكن كيف أوقفه إذن؟ لا أستطيع أن أفكر في الخروج منه — لقد حاولت."},{s:1,t:"Right, because willpower alone doesn't work. You need to interrupt the pattern — pause, breathe, name what you're feeling.",ar:"صحيح، لأن قوة الإرادة وحدها لا تعمل. تحتاج إلى مقاطعة النمط — توقف، تنفس، وسمِّ ما تشعر به."},{s:0,t:"Name it? Like, say 'I'm angry' out loud?",ar:"أسمّيه؟ مثل أن أقول 'أنا غاضب' بصوت عالٍ؟"},{s:1,t:"Yeah, seriously. Labeling a sensation — anger, shame, fear — actually calms the brain down. It's one of the most robust findings we have.",ar:"نعم، بجدية. تسمية الإحساس — الغضب، الخزي، الخوف — تهدئ الدماغ فعلًا. إنها من أقوى النتائج التي لدينا."},{s:0,t:"Huh. That sounds too simple to work.",ar:"همم. هذا يبدو بسيطًا جدًا لينجح."},{s:1,t:"Simple isn't the same as easy. In the heat of the moment, pausing feels impossible.",ar:"البسيط ليس مثل السهل. في لحظة الغضب، التوقف يبدو مستحيلًا."},{s:0,t:"Tell me about it. Last week my boss criticized my report and I just... froze. Then I stewed about it for days.",ar:"حدثني عن ذلك. الأسبوع الماضي انتقد مديري تقريري وتجمدت ببساطة. ثم ظللت أفكر فيه لأيام."},{s:1,t:"That's classic. The criticism hits an old wound — maybe a parent who was never satisfied — and suddenly it's not about the report anymore.",ar:"هذا كلاسيكي. النقد يصيب جرحًا قديمًا — ربما والد لم يكن راضيًا أبدًا — وفجأة لم يعد الأمر يتعلق بالتقرير."},{s:0,t:"Whoa. You think my boss triggered something from childhood?",ar:"واو. تظن أن مديري أثار شيئًا من الطفولة؟"},{s:1,t:"It's possible. The brain doesn't timestamp emotions well. A present threat can feel like a past one — same alarm, different decade.",ar:"هذا ممكن. الدماغ لا يؤرخ المشاعر جيدًا. تهديد حاضر قد يبدو كتهديد ماضٍ — نفس الإنذار، عقد مختلف."},{s:0,t:"That's both fascinating and kind of terrifying.",ar:"هذا مدهش ومخيف نوعًا ما في الوقت نفسه."},{s:1,t:"Welcome to psychology. But here's the hopeful part: once you see the pattern, you can work with it. Awareness is half the battle.",ar:"مرحبًا بك في علم النفس. لكن إليك الجزء المفعم بالأمل: حين ترى النمط، يمكنك العمل معه. الوعي هو نصف المعركة."},{s:0,t:"And the other half?",ar:"والنصف الآخر؟"},{s:1,t:"Practice. New responses, repeated until they stick. It takes time — there's no shortcut, no miracle cure.",ar:"الممارسة. استجابات جديدة، تتكرر حتى تثبت. يستغرق ذلك وقتًا — لا يوجد اختصار، ولا علاج معجزة."},{s:0,t:"What about trauma? People throw that word around a lot now. Is everything trauma?",ar:"ماذا عن الصدمة؟ الناس يرمون هذه الكلمة كثيرًا الآن. هل كل شيء صدمة؟"},{s:1,t:"Good question. Not everything is trauma — but the word got stretched. Real trauma overwhelms your ability to cope. A bad day doesn't.",ar:"سؤال جيد. ليس كل شيء صدمة — لكن الكلمة تمددت. الصدمة الحقيقية تطغى على قدرتك على التأقلم. اليوم السيئ لا يفعل ذلك."},{s:0,t:"So we need to be careful with the label.",ar:"إذن نحتاج أن نكون حذرين مع التسمية."},{s:1,t:"We do. Overusing it can minimize what survivors actually went through — and it can make ordinary pain feel like a syndrome you can't escape.",ar:"نعم نحتاج. الإفراط في استخدامها قد يقلل مما مر به الناجون فعلًا — وقد يجعل الألم العادي يبدو كمتلازمة لا يمكنك الهروب منها."},{s:0,t:"Okay, but what about the other side — people who say therapy is just talking? Like, how does talking fix anything?",ar:"حسنًا، لكن ماذا عن الجانب الآخر — الناس الذين يقولون إن العلاج مجرد كلام؟ كيف يصلح الكلام أي شيء؟"},{s:1,t:"Because talking, done right, rewires how you relate to your own thoughts. You learn to observe them instead of obeying them.",ar:"لأن الكلام، إذا تم بشكل صحيح، يعيد توصيل كيفية علاقتك بأفكارك. تتعلم مراقبتها بدلًا من طاعتها."},{s:0,t:"Observe, not obey. I like that.",ar:"راقب، لا تطع. يعجبني هذا."},{s:1,t:"It's the core of it. Thoughts are events in the mind, not orders. You can nod at them and let them pass.",ar:"هذا هو جوهر الأمر. الأفكار أحداث في العقل، وليست أوامر. يمكنك أن تومئ لها وتدعها تمر."},{s:0,t:"Easier said than done. My thoughts are loud.",ar:"أسهل قولًا من فعلًا. أفكاري صاخبة."},{s:1,t:"Everyone's are. The goal isn't silence — it's distance. A little space between you and the noise.",ar:"أفكار الجميع كذلك. الهدف ليس الصمت — بل المسافة. مساحة صغيرة بينك وبين الضجيج."},{s:0,t:"Distance... yeah. I guess that's what I'm looking for. Not a fix, just some breathing room.",ar:"المسافة... نعم. أظن أن هذا ما أبحث عنه. ليس إصلاحًا، بل بعض المساحة للتنفس."},{s:1,t:"That's a thoughtful goal, honestly. And a viable one — more viable than 'fix me overnight.'",ar:"هذا هدف متأمل، بصراحة. وقابل للتحقيق — أكثر قابلية من 'أصلحني بين ليلة وضحاها.'"},{s:0,t:"Ha. Okay, one last thing — do you ever get frustrated with clients who don't change?",ar:"ها. حسنًا، شيء أخير — هل تشعر بالإحباط من العملاء الذين لا يتغيرون؟"},{s:1,t:"Sure, sometimes. But then I remember — change isn't linear. Someone can seem stuck for months, then suddenly... something clicks.",ar:"بالتأكيد، أحيانًا. لكنني أتذكر بعدها — التغيير ليس خطيًا. قد يبدو شخص ما عالقًا لأشهر، ثم فجأة... تتضح الأمور."},{s:0,t:"Something clicks. I hope that's true for me.",ar:"تتضح الأمور. آمل أن يكون هذا صحيحًا بالنسبة لي."},{s:1,t:"It already started — you're here, asking the right questions. That's not nothing.",ar:"لقد بدأ بالفعل — أنت هنا، تطرح الأسئلة الصحيحة. هذا ليس شيئًا تافهًا."},{s:0,t:"Can I ask something harder? What about people who feel compelled to hurt themselves — is that the same mechanism?",ar:"هل يمكنني أن أسأل شيئًا أصعب؟ ماذا عن الأشخاص الذين يشعرون بأنهم مجبرون على إيذاء أنفسهم — هل هذه نفس الآلية؟"},{s:1,t:"It's related, but deeper — and I want to be careful here. Thoughts of suicide are a signal to get support, not a verdict. The supportive thing is to listen, not to judge.",ar:"إنها مرتبطة، لكنها أعمق — وأريد أن أكون حذرًا هنا. أفكار الانتحار إشارة لطلب الدعم، وليست حكمًا. الشيء الداعم هو الاستماع، لا الحكم."},{s:0,t:"That makes sense. And what about sexuality — clients who feel ashamed of who they are?",ar:"هذا منطقي. وماذا عن الحياة الجنسية — العملاء الذين يشعرون بالخجل مما هم عليه؟"},{s:1,t:"Shame is learned, and it can be unlearned. Therapy gives people room to explore it safely — under supervision, at their own pace, with someone who fosters honesty, not fear.",ar:"الخجل مُتعلم، ويمكن التخلص منه. العلاج يمنح الناس مساحة لاستكشافه بأمان — تحت إشراف، وبوتيرتهم الخاصة، مع شخص يعزز الصدق، لا الخوف."},{s:0,t:"What about consent in therapy — do clients really understand what they're agreeing to?",ar:"ماذا عن الموافقة في العلاج — هل يفهم العملاء حقًا ما يوافقون عليه؟"},{s:1,t:"That's a delicate point. Consent has to be ongoing, not a form you sign once. And if a session stirs up something raw, we slow down — a defensive reaction is information, not resistance.",ar:"هذه نقطة حساسة. الموافقة يجب أن تكون مستمرة، وليست نموذجًا توقعه مرة واحدة. وإذا أثارت جلسة شيئًا مؤلمًا، نبطئ — رد الفعل الدفاعي معلومة، وليس مقاومة."},{s:0,t:"Thanks. I needed to hear that.",ar:"شكرًا. كنت بحاجة لسماع ذلك."},{s:1,t:"Anytime. And hey — be patient with yourself. You're doing the work.",ar:"في أي وقت. وهيّا — كن صبورًا مع نفسك. أنت تقوم بالعمل."}]}},{stage:4,topic:"space",topicAr:"الفضاء والكون",topicEn:"Space & the Universe",topicDe:"Weltraum und Universum",emoji:"🚀",title:"هل نحن وحدنا في الكون؟",grammar:{id:"en-c1-nominalisation",title:"Nominalisation",titleAr:"التحويل إلى اسم",covers:1},conv:{id:"en-stage4-c1",speakers:["Astronomer (عالم الفلك)","Journalist (الصحفي)"],turns:[{s:0,t:"So, level with me — are we actually gonna find life out there, or is this all just expensive wishful thinking?",ar:"إذن، كن صريحًا معي — هل سنجد حياة هناك فعلًا، أم أن كل هذا مجرد تفكير رغبوي مكلف؟"},{s:1,t:"Ha! Fair question. Honestly? The odds are decent — but 'life' might mean microbes in a frozen ocean, not little green men.",ar:"ها! سؤال عادل. بصراحة؟ الاحتمالات جيدة — لكن 'الحياة' قد تعني ميكروبات في محيط متجمد، وليس رجالًا خضرًا صغارًا."},{s:0,t:"Microbes. After all this money, all these telescopes — microbes?",ar:"ميكروبات. بعد كل هذا المال، وكل هذه التلسكوبات — ميكروبات؟"},{s:1,t:"Don't underestimate microbes. Finding even one alien cell would be tremendous — it would mean life isn't a cosmic accident.",ar:"لا تستهين بالميكروبات. العثور على خلية غريبة واحدة سيكون هائلًا — سيعني أن الحياة ليست حادثًا كونيًا."},{s:0,t:"Okay, I'll give you that. But where? Mars? Europa?",ar:"حسنًا، سأمنحك ذلك. لكن أين؟ المريخ؟ أوروبا؟"},{s:1,t:"Europa's the most promising — a whole ocean under the ice, kept warm by tidal forces. The data's been tantalizing for years.",ar:"أوروبا هو الأكثر وعدًا — محيط كامل تحت الجليد، تدفئه قوى المد والجزر. البيانات مغرية منذ سنوات."},{s:0,t:"And how would we even check? Drill through kilometers of ice?",ar:"وكيف سنفحص ذلك أصلًا؟ نحفر عبر كيلومترات من الجليد؟"},{s:1,t:"That's the plan, eventually. First, though, we fly through the plumes — the geysers that burst through the cracks and spray ocean water into space.",ar:"هذه هي الخطة، في النهاية. أولًا، نطير عبر الأعمدة — النوافير التي تنفجر عبر الشقوق وترش مياه المحيط في الفضاء."},{s:0,t:"Wait, the ocean just... sprays into space? That's wild.",ar:"انتظر، المحيط يرش... في الفضاء؟ هذا جنوني."},{s:1,t:"Wild and convenient. A spacecraft can scoop up a sample without ever landing. It's like the moon is offering us a taste.",ar:"جنوني ومريح. مركبة فضائية يمكنها التقاط عينة دون الهبوط أبدًا. كأن القمر يقدم لنا تذوقًا."},{s:0,t:"A taste of alien soup. Lovely.",ar:"تذوق من حساء غريب. جميل."},{s:1,t:"Hey, soup is where life started here too. Don't knock it.",ar:"هيّا، الحساء هو حيث بدأت الحياة هنا أيضًا. لا تسخر منه."},{s:0,t:"Alright, alright. But let me push back — even if we find microbes, so what? How does that change anything for people down here?",ar:"حسنًا، حسنًا. لكن دعني أعترض — حتى لو وجدنا ميكروبات، فماذا؟ كيف يغير ذلك أي شيء للناس هنا؟"},{s:1,t:"It changes the realm of what's possible. If life started twice in one solar system, it probably started everywhere. We're not special — we're inevitable.",ar:"إنه يغير عالم ما هو ممكن. إذا بدأت الحياة مرتين في نظام شمسي واحد، فمن المحتمل أنها بدأت في كل مكان. نحن لسنا مميزين — وجودنا حتمي."},{s:0,t:"Inevitable. Hmm. That actually makes me feel less lonely, somehow.",ar:"حتميون. همم. هذا يجعلني أشعر بوحدة أقل، بطريقة ما."},{s:1,t:"Exactly. And there's a practical side too — the technology we build for space comes back down. GPS, weather forecasts, disaster warnings.",ar:"بالضبط. وهناك جانب عملي أيضًا — التكنولوجيا التي نبنيها للفضاء تعود إلينا. نظام تحديد المواقع، وتوقعات الطقس، وتحذيرات الكوارث."},{s:0,t:"Okay, but what about the big dream — Mars colonies? People living there? Is that real, or just a billionaire's fantasy?",ar:"حسنًا، لكن ماذا عن الحلم الكبير — مستعمرات المريخ؟ ناس يعيشون هناك؟ هل هذا حقيقي، أم مجرد خيال ملياردير؟"},{s:1,t:"It's real as an engineering challenge, but the timeline people quote? Pure fantasy. Living on Mars means living in a vacuum-sealed can, forever.",ar:"إنه حقيقي كتحدٍّ هندسي، لكن الجدول الزمني الذي يذكره الناس؟ خيال محض. العيش على المريخ يعني العيش في علبة محكمة الإغلاق ضد الفراغ، إلى الأبد."},{s:0,t:"A can. With no sky, no air, no... anything.",ar:"علبة. بلا سماء، بلا هواء، بلا... أي شيء."},{s:1,t:"Pretty much. And the radiation — a solar storm could be lethal in hours. We'd need shielding we haven't invented yet.",ar:"تقريبًا. والإشعاع — عاصفة شمسية قد تكون قاتلة خلال ساعات. نحتاج إلى دروع لم نخترعها بعد."},{s:0,t:"So the Mars hype is overblown.",ar:"إذن ضجة المريخ مبالغ فيها."},{s:1,t:"The hype, yeah. But the science — the rovers, the samples — that's magnificent. We're reading Mars's history rock by rock.",ar:"الضجة، نعم. لكن العلم — المركبات والعينات — رائع. نحن نقرأ تاريخ المريخ صخرة صخرة."},{s:0,t:"Rock by rock. I love that image. What have the rocks told us so far?",ar:"صخرة صخرة. أحب هذه الصورة. ماذا أخبرتنا الصخور حتى الآن؟"},{s:1,t:"That Mars was once warm and wet — rivers, lakes, maybe an ocean. Then something went wrong, and the atmosphere just... bled away.",ar:"أن المريخ كان دافئًا ورطبًا ذات مرة — أنهار وبحيرات وربما محيط. ثم حدث خطأ ما، والغلاف الجوي نزف ببساطة."},{s:0,t:"Bled away. That's a haunting phrase.",ar:"نزف بعيدًا. هذه عبارة مؤثرة."},{s:1,t:"It is. And it's a warning — planets can lose their habitability. Ours isn't guaranteed.",ar:"إنها كذلك. وهي تحذير — الكواكب يمكن أن تفقد صلاحيتها للحياة. كوكبنا ليس مضمونًا."},{s:0,t:"Okay, that's dark. Let me change the subject — black holes. What's the deal with the new images?",ar:"حسنًا، هذا مظلم. دعني أغير الموضوع — الثقوب السوداء. ما قصة الصور الجديدة؟"},{s:1,t:"Oh, they're superb. A ring of fire around pure darkness — light bending around a point where physics breaks down.",ar:"أوه، إنها ممتازة. حلقة من النار حول ظلام خالص — ضوء ينحني حول نقطة تنهار فيها الفيزياء."},{s:0,t:"Physics breaks down. So what happens inside? Anyone's guess?",ar:"الفيزياء تنهار. إذن ماذا يحدث في الداخل؟ تخمين أي شخص؟"},{s:1,t:"Pretty much anyone's guess. The math says time stops, space collapses — but the math also says it can't be right. Something's missing.",ar:"تخمين أي شخص تقريبًا. الرياضيات تقول إن الزمن يتوقف والفضاء ينهار — لكن الرياضيات تقول أيضًا إن هذا لا يمكن أن يكون صحيحًا. شيء ما مفقود."},{s:0,t:"Something's missing. I love how scientists just admit that.",ar:"شيء ما مفقود. أحب كيف يعترف العلماء بذلك ببساطة."},{s:1,t:"It's the best part of the job. The spotlight moments are fun, but the mystery is the point.",ar:"إنه أفضل جزء في العمل. لحظات الأضواء ممتعة، لكن الغموض هو الهدف."},{s:0,t:"Alright, one more — the James Webb telescope. Has it lived up to the hype?",ar:"حسنًا، سؤال أخير — تلسكوب جيمس ويب. هل كان على مستوى الضجة؟"},{s:1,t:"And then some. It's seeing galaxies from the first few hundred million years — the span of cosmic history we could only guess at before.",ar:"وأكثر من ذلك. إنه يرى مجرات من أول مئات الملايين من السنين — المدى من التاريخ الكوني الذي كنا نخمنه فقط من قبل."},{s:0,t:"The first galaxies. That gives me chills.",ar:"المجرات الأولى. هذا يمنحني قشعريرة."},{s:1,t:"Me too. And every image raises ten new questions. That's how you know it's working.",ar:"وأنا أيضًا. وكل صورة تثير عشرة أسئلة جديدة. هكذا تعرف أنه يعمل."},{s:0,t:"So the universe keeps getting bigger, and we keep getting smaller.",ar:"إذن الكون يستمر في التوسع، ونحن نستمر في التصاغر."},{s:1,t:"Smaller, yeah — but also more connected. Every atom in your body was forged in a star. You're literally stardust.",ar:"أصغر، نعم — لكن أكثر ترابطًا أيضًا. كل ذرة في جسمك تشكلت في نجم. أنت حرفيًا غبار نجوم."},{s:0,t:"Quick question — what happens when two galaxies collide? A cosmic collision, right?",ar:"سؤال سريع — ماذا يحدث عندما تتصادم مجرتان؟ تصادم كوني، صحيح؟"},{s:1,t:"Yeah — a slow-motion crash over billions of years. The stars almost never hit each other, but the gas clouds slam together and burst into new stars.",ar:"نعم — تحطم بالحركة البطيئة على مدى مليارات السنين. النجوم لا تصطدم ببعضها أبدًا تقريبًا، لكن سحب الغاز تصطدم معًا وتنفجر إلى نجوم جديدة."},{s:0,t:"And the bang from that — is it visible from Earth?",ar:"والانفجار من ذلك — هل هو مرئي من الأرض؟"},{s:1,t:"Not the bang itself — but the light show is situated right in our telescopes' sweet spot, and it coincides with a dip in the background glow.",ar:"ليس الانفجار نفسه — لكن عرض الضوء يقع تمامًا في النقطة المثالية لتلسكوباتنا، ويتزامن مع انخفاض في التوهج الخلفي."},{s:0,t:"Secondly — and this matters — what's the sole reason we keep funding telescopes when Earth has so many problems?",ar:"ثانيًا — وهذا مهم — ما السبب الوحيد الذي يجعلنا نستمر في تمويل التلسكوبات بينما للأرض مشاكل كثيرة؟"},{s:1,t:"Because the two aren't in competition. The same instruments that map distant galaxies also track asteroids that could wipe us out — and, thankfully, give us years of warning.",ar:"لأن الاثنين ليسا في منافسة. نفس الأدوات التي ترسم خرائط المجرات البعيدة تتعقب أيضًا الكويكبات التي قد تمحو وجودنا — ولحسن الحظ، تمنحنا سنوات من التحذير."},{s:0,t:"Stardust. Okay, that's a good place to end.",ar:"غبار نجوم. حسنًا، هذا مكان جيد للانتهاء."},{s:1,t:"It is. Same time next week? The fleet of new missions launches soon — we'll have plenty to talk about.",ar:"إنه كذلك. نفس الوقت الأسبوع المقبل؟ أسطول المهمات الجديدة يُطلق قريبًا — سيكون لدينا الكثير لنتحدث عنه."}]}},{stage:5,topic:"environment",topicAr:"البيئة والطبيعة",topicEn:"Environment & Nature",topicDe:"Umwelt und Natur",emoji:"🌳",title:"كوكب على حافة الهاوية",grammar:{id:"en-c1-discourse-markers",title:"Discourse markers",titleAr:"روابط الخطاب (Discourse markers)",covers:1},conv:{id:"en-stage5-c1",speakers:["Activist (الناشط البيئي)","Engineer (المهندس)"],turns:[{s:0,t:"Okay, be honest with me — is it too late? I read the news and it feels like we're done for.",ar:"حسنًا، كن صادقًا معي — هل فات الأوان؟ أقرأ الأخبار وأشعر أننا انتهينا."},{s:1,t:"It's not too late — but the window is closing fast. The next ten years will decide a lot.",ar:"لم يفت الأوان بعد — لكن النافذة تُغلق بسرعة. السنوات العشر المقبلة ستقرر الكثير."},{s:0,t:"Ten years. That's... urgent. And yet nothing seems to change.",ar:"عشر سنوات. هذا... عاجل. ومع ذلك لا شيء يبدو أنه يتغير."},{s:1,t:"Things are changing — just not fast enough. Solar is now the cheapest energy in history, but we're still building new gas plants.",ar:"الأشياء تتغير — لكن ليس بسرعة كافية. الطاقة الشمسية الآن هي أرخص طاقة في التاريخ، لكننا ما زلنا نبني محطات غاز جديدة."},{s:0,t:"Why? If solar's cheaper, why would anyone build gas?",ar:"لماذا؟ إذا كانت الشمسية أرخص، فلماذا يبني أحد الغاز؟"},{s:1,t:"Because the system is rigged for the old stuff — subsidies, infrastructure, politics. The market alone won't fix it.",ar:"لأن النظام منحاز لصالح القديم — الدعم والبنية التحتية والسياسة. السوق وحده لن يصلح ذلك."},{s:0,t:"So what actually works? I feel like individual action is a drop in the ocean.",ar:"إذن ما الذي يعمل فعلًا؟ أشعر أن الفعل الفردي قطرة في المحيط."},{s:1,t:"A drop, yeah — but drops add up. And more importantly, individual choices signal demand. Companies follow the money.",ar:"قطرة، نعم — لكن القطرات تتراكم. والأهم من ذلك، الخيارات الفردية تشير إلى الطلب. الشركات تتبع المال."},{s:0,t:"Hmm. But isn't that just letting corporations off the hook? They cause most of the damage.",ar:"همم. لكن أليس هذا مجرد إعفاء للشركات من المسؤولية؟ إنها تسبب معظم الضرر."},{s:1,t:"They do — a hundred companies produce most emissions. But they produce them making stuff we buy. It's both, not either-or.",ar:"نعم تفعل — مئة شركة تنتج معظم الانبعاثات. لكنها تنتجها وهي تصنع أشياء نشتريها. إنه كلاهما، وليس أحدهما أو الآخر."},{s:0,t:"Both. Okay. So where should the pressure go?",ar:"كلاهما. حسنًا. إذن أين يجب أن يذهب الضغط؟"},{s:1,t:"Policy, mostly. A carbon price, building codes, transit investment — the boring stuff that actually moves the needle.",ar:"السياسة، في الغالب. سعر للكربون، وقوانين بناء، واستثمار في النقل — الأشياء المملة التي تحرك الإبرة فعلًا."},{s:0,t:"Boring stuff. Nobody marches in the street for building codes.",ar:"أشياء مملة. لا أحد يتظاهر في الشارع من أجل قوانين البناء."},{s:1,t:"Ha! True. But that's the gap — the spectacle gets the spotlight, the substance gets ignored.",ar:"ها! صحيح. لكن هذه هي الفجوة — الاستعراض يحصل على الأضواء، والجوهر يُتجاهل."},{s:0,t:"What about the disasters, though? The floods, the fires — people are losing their homes right now.",ar:"لكن ماذا عن الكوارث؟ الفيضانات والحرائق — الناس يفقدون بيوتهم الآن."},{s:1,t:"And evacuation plans are still a mess in most places. When the water rises, people drown because nobody told them where to go.",ar:"وخطط الإخلاء ما زالت فوضوية في معظم الأماكن. عندما ترتفع المياه، يغرق الناس لأن أحدًا لم يخبرهم إلى أين يذهبون."},{s:0,t:"That's heartbreaking. And it's always the poorest who get hit hardest.",ar:"هذا مفجع. ودائمًا الفقراء هم من يتضررون بشدة."},{s:1,t:"Always. Climate change is a hazard multiplier — it takes existing inequality and intensifies it.",ar:"دائمًا. تغير المناخ مضاعف للمخاطر — يأخذ عدم المساواة القائم ويكثفه."},{s:0,t:"So what's the sustainability plan that actually includes those people? Not just rich countries going green.",ar:"إذن ما خطة الاستدامة التي تشمل هؤلاء الناس فعلًا؟ وليس فقط الدول الغنية التي تتحول للأخضر."},{s:1,t:"That's the trillion-dollar question. The global south needs energy to develop — and if we deny them that, they'll burn coal. Fairly, I might add.",ar:"هذا هو السؤال الذي يساوي تريليون دولار. الجنوب العالمي يحتاج إلى طاقة ليتطور — وإذا حرمناهم منها، سيحرقون الفحم. وهذا من حقهم."},{s:0,t:"So rich countries have to pay. Transfer technology, fund the transition.",ar:"إذن على الدول الغنية أن تدفع. تنقل التكنولوجيا وتمول التحول."},{s:1,t:"Exactly. And historically, they've promised billions and delivered a fraction. The trust is gone.",ar:"بالضبط. وتاريخيًا، وعدوا بمليارات وسلموا جزءًا صغيرًا. الثقة ذهبت."},{s:0,t:"Ugh. Okay, let me ask something more hopeful — is there any ecosystem that's actually recovering?",ar:"آه. حسنًا، دعني أسأل شيئًا أكثر تفاؤلًا — هل هناك نظام بيئي يتعافى فعلًا؟"},{s:1,t:"Yeah, actually — several. Whale populations are bouncing back where hunting stopped. Forests regrow when you let them.",ar:"نعم، فعلًا — عدة أنظمة. أعداد الحيتان تتعافى حيث توقف الصيد. الغابات تنمو مجددًا عندما تتركها."},{s:0,t:"Bouncing back. I love hearing that.",ar:"تتعافى. أحب سماع ذلك."},{s:1,t:"Nature is resilient — if we give it room. The problem is we keep taking the room. Wetlands drained, nests destroyed, rivers dammed.",ar:"الطبيعة مرنة — إذا منحناها مساحة. المشكلة أننا نستمر في أخذ المساحة. الأراضي الرطبة تُجفف، والأعشاش تُدمر، والأنهار تُسد بالسدود."},{s:0,t:"And the species that depend on them just... vanish.",ar:"والأنواع التي تعتمد عليها تختفي ببساطة."},{s:1,t:"Vanish, yeah. A thousand species a year, maybe more. And each one takes something irreplaceable with it.",ar:"تختفي، نعم. ألف نوع في السنة، وربما أكثر. وكل نوع يأخذ معه شيئًا لا يمكن تعويضه."},{s:0,t:"What about farming? I hear cattle are a huge part of the problem.",ar:"ماذا عن الزراعة؟ أسمع أن الماشية جزء كبير من المشكلة."},{s:1,t:"They are — methane, land use, water. But the answer isn't just 'stop eating meat.' It's how the meat is produced.",ar:"إنها كذلك — الميثان واستخدام الأرض والمياه. لكن الإجابة ليست مجرد 'توقف عن أكل اللحم.' بل كيف يُنتج اللحم."},{s:0,t:"So regenerative farming, that kind of thing?",ar:"إذن الزراعة المتجددة، هذا النوع من الأشياء؟"},{s:1,t:"Exactly. Rotational grazing, diverse crops — it can actually rebuild soil. Some farms are pulling carbon out of the air.",ar:"بالضبط. الرعي التناوبي والمحاصيل المتنوعة — يمكنها فعلًا إعادة بناء التربة. بعض المزارع تسحب الكربون من الهواء."},{s:0,t:"Pulling carbon out of the air. Okay, that's genuinely hopeful.",ar:"تسحب الكربون من الهواء. حسنًا، هذا مفعم بالأمل حقًا."},{s:1,t:"It is. But scale matters — a hundred good farms won't offset a million bad ones. We need the whole system to shift.",ar:"إنه كذلك. لكن الحجم مهم — مئة مزرعة جيدة لن تعوض مليون مزرعة سيئة. نحتاج أن يتحول النظام كله."},{s:0,t:"The whole system. That's a big ask.",ar:"النظام كله. هذا طلب كبير."},{s:1,t:"It is. But look — the alternative is worse. We either steer this ship now, or the ocean steers it for us.",ar:"إنه كذلك. لكن انظر — البديل أسوأ. إما أن نوجه هذه السفينة الآن، أو أن المحيط يوجهها بدلًا منا."},{s:0,t:"Steer the ship. Alright, I'm in. Where do I start?",ar:"أوجه السفينة. حسنًا، أنا معك. من أين أبدأ؟"},{s:1,t:"Start where you are. Eat a little less meat, waste nothing, vote like it matters — because it does.",ar:"ابدأ من حيث أنت. كُل لحمًا أقل قليلًا، ولا تهدر شيئًا، وصوّت كأن الأمر مهم — لأنه مهم."},{s:0,t:"What about waste — the disposal of solar panels and batteries? Aren't we creating a new problem?",ar:"ماذا عن النفايات — التخلص من الألواح الشمسية والبطاريات؟ ألسنا نخلق مشكلة جديدة؟"},{s:1,t:"We are, if we're careless. But recycling programs are scaling up — and the alternative, burning coal, is worse by a mile.",ar:"نعم، إذا كنا مهملين. لكن برامج إعادة التدوير تتوسع — والبديل، حرق الفحم، أسوأ بكثير."},{s:0,t:"And the dams? I hear a new dam upstream could displace whole villages.",ar:"وماذا عن السدود؟ أسمع أن سدًا جديدًا في المنبع قد يُهجّر قرى كاملة."},{s:1,t:"It could — and that's why any imminent project needs a real evacuation plan and honest alignment with the people who live there, not just the engineers.",ar:"قد يفعل — ولهذا أي مشروع وشيك يحتاج إلى خطة إخلاء حقيقية ومواءمة صادقة مع الناس الذين يعيشون هناك، وليس فقط مع المهندسين."},{s:0,t:"Should we just evacuate the coastal towns now, before the next storm? Waiting feels irresponsible.",ar:"هل يجب أن نخلي المدن الساحلية الآن، قبل العاصفة المقبلة؟ الانتظار يبدو غير مسؤول."},{s:1,t:"Some towns, yeah — and the sooner we embark on planned relocation, the cheaper and kinder it is. Forced flight in a crisis is the worst version.",ar:"بعض المدن، نعم — وكلما بدأنا الانتقال المخطط مبكرًا، كان أرخص وألطف. الفرار القسري في أزمة هو أسوأ نسخة."},{s:0,t:"Vote like it matters. Got it.",ar:"صوّت كأن الأمر مهم. فهمت."},{s:1,t:"And talk about it. The silence is the real killer — everyone's worried, nobody says so.",ar:"وتحدث عنه. الصمت هو القاتل الحقيقي — الجميع قلق، ولا أحد يقول ذلك."}]}},{stage:6,topic:"technology",topicAr:"التكنولوجيا والإنترنت",topicEn:"Technology & Internet",topicDe:"Technologie und Internet",emoji:"💻",title:"من يملك الإنترنت؟",grammar:{id:"en-c1-discourse-markers",title:"Discourse markers",titleAr:"أدوات الربط الخطابية",covers:1},conv:{id:"en-stage6-c1",speakers:["Developer (المطوّر)","Product Manager (مدير المنتج)"],turns:[{s:0,t:"Okay, I gotta ask — is AI gonna take my job, or is that just hype to sell newsletters?",ar:"حسنًا، يجب أن أسأل — هل سيأخذ الذكاء الاصطناعي وظيفتي، أم أن هذه مجرد ضجة لبيع النشرات؟"},{s:1,t:"Honestly? Both. Some jobs will vanish — that's real. But the 'all jobs' panic is hype.",ar:"بصراحة؟ كلاهما. بعض الوظائف ستختفي — هذا حقيقي. لكن ذعر 'كل الوظائف' ضجة."},{s:0,t:"So which jobs are safe? Asking for a friend. And by friend I mean me.",ar:"إذن أي الوظائف آمنة؟ أسأل من أجل صديق. وأعني بالصديق نفسي."},{s:1,t:"Ha! The safe ones are the messy human ones — care, craft, judgment calls. Anything with a fluid situation and real stakes.",ar:"ها! الآمنة هي الفوضوية الإنسانية — الرعاية والحرفة وقرارات الحكم. أي شيء فيه موقف متغير ومخاطر حقيقية."},{s:0,t:"And the unsafe ones?",ar:"وغير الآمنة؟"},{s:1,t:"Repetitive, text-heavy, predictable. If your day is mostly processing forms, yeah — that's on the chopping block.",ar:"المتكررة والمليئة بالنصوص والمتوقعة. إذا كان يومك معظمه معالجة نماذج، نعم — فهي على قائمة القطع."},{s:0,t:"Processing forms. That hits close to home.",ar:"معالجة النماذج. هذا يصيبني في الصميم."},{s:1,t:"Sorry. But look — every tech wave does this. The question isn't whether jobs change, it's whether we help people through the change.",ar:"آسف. لكن انظر — كل موجة تقنية تفعل هذا. السؤال ليس ما إذا كانت الوظائف ستتغير، بل ما إذا كنا سنساعد الناس خلال التغيير."},{s:0,t:"And do we? Help people, I mean.",ar:"وهل نفعل؟ أعني نساعد الناس."},{s:1,t:"Historically? Not well. We celebrate the disruption and forget the disrupted. The turnover in some industries is brutal.",ar:"تاريخيًا؟ ليس جيدًا. نحتفل بالتغيير الجذري وننسى من تضرروا منه. معدل الدوران في بعض الصناعات قاسٍ."},{s:0,t:"Okay, darker question — what about privacy? Every app wants my data now.",ar:"حسنًا، سؤال أظلم — ماذا عن الخصوصية؟ كل تطبيق يريد بياناتي الآن."},{s:1,t:"And they get it, mostly because we hand it over for a free service. The deal was never free — you were the product.",ar:"ويحصلون عليها، لأننا نسلمها غالبًا مقابل خدمة مجانية. الصفقة لم تكن مجانية أبدًا — أنت كنت المنتج."},{s:0,t:"Yeah, I've heard that line. But what can I actually do? Delete everything and live in a cave?",ar:"نعم، سمعت هذه الجملة. لكن ماذا يمكنني أن أفعل فعلًا؟ أحذف كل شيء وأعيش في كهف؟"},{s:1,t:"No — just be deliberate. Check the permissions, use the privacy settings, and ask who's profiting from your attention.",ar:"لا — كن واعيًا فقط. تحقق من الأذونات، واستخدم إعدادات الخصوصية، واسأل من يستفيد من انتباهك."},{s:0,t:"Speaking of attention — social media. Is it rotting our brains, or are old people just panicking again?",ar:"بالحديث عن الانتباه — وسائل التواصل الاجتماعي. هل تفسد أدمغتنا، أم أن كبار السن يصابون بالذعر مجددًا؟"},{s:1,t:"A bit of both, honestly. The apps are designed to hook you — infinite scroll, notifications, all of it. That's not an accident.",ar:"قليل من كلاهما، بصراحة. التطبيقات مصممة لإدمانك — التمرير اللانهائي والإشعارات وكل ذلك. هذا ليس صدفة."},{s:0,t:"Designed to hook me. So I'm not weak — I'm up against a thousand engineers?",ar:"مصممة لإدماني. إذن أنا لست ضعيفًا — بل أواجه ألف مهندس؟"},{s:1,t:"Pretty much. The deployment of those tricks is deliberate — every color, every vibration is tested.",ar:"تقريبًا. نشر تلك الحيل متعمد — كل لون وكل اهتزاز يُختبَر."},{s:0,t:"That's... creepy, honestly. And the kids growing up with this?",ar:"هذا... مخيف، بصراحة. والأطفال الذين يكبرون مع هذا؟"},{s:1,t:"They're the experiment. We don't know the long-term effects yet — and that's what worries me most.",ar:"إنهم التجربة. لا نعرف الآثار طويلة المدى بعد — وهذا ما يقلقني أكثر."},{s:0,t:"Okay, so what do we do? Ban phones in schools? That feels like a band-aid.",ar:"حسنًا، ماذا نفعل إذن؟ نمنع الهواتف في المدارس؟ هذا يبدو حلًا ترقيعيًا."},{s:1,t:"It's a start, not a solution. The real fix is teaching kids how the machine works — so they're users, not used.",ar:"إنها بداية، وليست حلًا. الإصلاح الحقيقي هو تعليم الأطفال كيف تعمل الآلة — ليكونوا مستخدمين، لا مُستخدَمين."},{s:0,t:"Users, not used. I like that. What about the good side, though? Tech does amazing things too.",ar:"مستخدمون، لا مُستخدَمون. يعجبني هذا. لكن ماذا عن الجانب الجيد؟ التكنولوجيا تفعل أشياء مذهلة أيضًا."},{s:1,t:"Oh, absolutely. A kid in a village can now learn coding on a cheap desktop — that was science fiction twenty years ago.",ar:"أوه، بالتأكيد. طفل في قرية يمكنه الآن تعلم البرمجة على حاسوب مكتبي رخيص — كان هذا خيالًا علميًا قبل عشرين سنة."},{s:0,t:"And medicine, remote work, all of it.",ar:"والطب والعمل عن بعد، وكل ذلك."},{s:1,t:"Right. The tool isn't the problem — the business model is. When profit depends on addiction, addiction is what you get.",ar:"صحيح. الأداة ليست المشكلة — نموذج العمل هو المشكلة. عندما يعتمد الربح على الإدمان، فالإدمان هو ما تحصل عليه."},{s:0,t:"So regulate the model, not the tool.",ar:"إذن نظّم النموذج، وليس الأداة."},{s:1,t:"Exactly. And that's where copyright fights, crypto scams, e-commerce monopolies — it all connects.",ar:"بالضبط. وهنا تتصل معارك حقوق النشر واحتيالات العملات المشفرة واحتكارات التجارة الإلكترونية — كلها مترابطة."},{s:0,t:"Crypto — don't get me started. My cousin lost his savings on some coin.",ar:"العملات المشفرة — لا تجعلني أبدأ. ابن عمي خسر مدخراته في عملة ما."},{s:1,t:"Ugh, I'm sorry. The hype machine there is ruthless — influencers pumping coins they own, then vanishing.",ar:"آه، آسف. آلة الضجة هناك قاسية — مؤثرون يضخون عملات يملكونها ثم يختفون."},{s:0,t:"And nobody stops them?",ar:"ولا أحد يوقفهم؟"},{s:1,t:"Regulators are always three steps behind. By the time the rules arrive, the money's gone offshore.",ar:"المنظمون دائمًا متأخرون بثلاث خطوات. بحلول وصول القواعد، يكون المال قد ذهب إلى الخارج."},{s:0,t:"Offshore. Of course. Okay, last thing — what tech are you actually excited about?",ar:"إلى الخارج. بالطبع. حسنًا، شيء أخير — ما التكنولوجيا التي تثير حماسك فعلًا؟"},{s:1,t:"Honestly? The boring stuff. Better batteries, cheaper sensors, open-source tools. The quiet revolutions.",ar:"بصراحة؟ الأشياء المملة. بطاريات أفضل وحساسات أرخص وأدوات مفتوحة المصدر. الثورات الهادئة."},{s:0,t:"Quiet revolutions. I'll take it.",ar:"ثورات هادئة. سأقبل بذلك."},{s:1,t:"Good. And hey — plug in your phone. We're at two percent and this conversation is too good to lose.",ar:"جيد. وهيّا — اشحن هاتفك. نحن عند اثنين بالمئة وهذه المحادثة جيدة جدًا لنفقدها."},{s:0,t:"My friend's account got hacked last week — someone stole his cryptocurrency. Is there any way to get it back?",ar:"حساب صديقي تعرض للاختراق الأسبوع الماضي — سرق أحدهم عملته المشفرة. هل هناك طريقة لاستعادتها؟"},{s:1,t:"Almost never. Once it's gone, it's gone — that's the dark side of a system with no undo button. And the subscription traps are just as bad — free trial, then they charge you forever.",ar:"تقريبًا أبدًا. بمجرد ذهابها، ذهبت — هذا هو الجانب المظلم لنظام بلا زر تراجع. وفخاخ الاشتراك سيئة بنفس القدر — تجربة مجانية، ثم يفرضون عليك رسومًا إلى الأبد."},{s:0,t:"Ugh, I've fallen for that. I keep meaning to terminate those subscriptions.",ar:"آه، لقد وقعت في ذلك. أنوي دائمًا إلغاء تلك الاشتراكات."},{s:1,t:"Do it today — and postpone nothing. It takes five minutes, and it's the handiest way to stop the bleed.",ar:"افعل ذلك اليوم — ولا تؤجل شيئًا. يستغرق خمس دقائق، وهي أسهل طريقة لوقف النزيف."},{s:0,t:"I want to subscribe to that security newsletter, but I never read the ones I already get. Is it worth it?",ar:"أريد الاشتراك في تلك النشرة الأمنية، لكنني لا أقرأ أبدًا تلك التي أحصل عليها بالفعل. هل تستحق ذلك؟"},{s:1,t:"Only if you'll actually use it. The coordinator of our team sends one weekly digest — short, applicable, no fluff. That's the model that works.",ar:"فقط إذا كنت ستستخدمها فعلًا. منسق فريقنا يرسل ملخصًا أسبوعيًا واحدًا — قصير وقابل للتطبيق وبلا حشو. هذا هو النموذج الذي يعمل."},{s:0,t:"Ha! Fine, fine. Same time next week?",ar:"ها! حسنًا، حسنًا. نفس الوقت الأسبوع المقبل؟"},{s:1,t:"You got it. Bring your cousin — I wanna talk him out of the next coin.",ar:"اتفقنا. أحضر ابن عمك — أريد أن أثنيه عن العملة التالية."}]}},{stage:7,topic:"business",topicAr:"الأعمال والمال",topicEn:"Business & Money",topicDe:"Geschäft und Geld",emoji:"📈",title:"الرأسمالية: نجاح أم فشل؟",grammar:{id:"en-c1-hedging-stance",title:"Hedging",titleAr:"التحفظ والتخفيف في الكلام",covers:1},conv:{id:"en-stage7-c1",speakers:["CEO (المدير التنفيذي)","Investor (المستثمر)"],turns:[{s:0,t:"Alright, pitch me. Why should I put my money in your company and not, say, a savings account?",ar:"حسنًا، أقنعني. لماذا أضع أموالي في شركتك وليس، مثلًا، في حساب توفير؟"},{s:1,t:"Because a savings account pays you two percent while inflation eats five. You're losing money slowly — we're offering a chance to grow it.",ar:"لأن حساب التوفير يدفع لك اثنين بالمئة بينما التضخم يأكل خمسة. أنت تخسر المال ببطء — ونحن نعرض فرصة لتنميته."},{s:0,t:"A chance. That's doing a lot of work in that sentence.",ar:"فرصة. هذه الكلمة تحمل الكثير في تلك الجملة."},{s:1,t:"Fair. Let me be concrete — our revenue grew forty percent last year, and our turnover is the lowest in the sector.",ar:"عادل. دعني أكون ملموسًا — إيراداتنا نمت أربعين بالمئة العام الماضي، ومعدل دوران الموظفين لدينا هو الأدنى في القطاع."},{s:0,t:"Low turnover — that means people actually like working there?",ar:"دوران منخفض — هذا يعني أن الناس يحبون العمل هناك فعلًا؟"},{s:1,t:"It does. And in our business, that matters — experienced staff, happy clients, fewer mistakes. It's all connected.",ar:"نعم. وفي عملنا، هذا مهم — موظفون ذوو خبرة وعملاء سعداء وأخطاء أقل. كل شيء مترابط."},{s:0,t:"Okay, but let's talk about the elephant in the room — your last product launch flopped. The cancellation numbers were ugly.",ar:"حسنًا، لكن لنتحدث عن الفيل في الغرفة — إطلاق منتجك الأخير فشل. أرقام الإلغاء كانت قبيحة."},{s:1,t:"I'm not gonna dodge that. We misread the market — the price point was wrong, and the timing was worse. We learned from it.",ar:"لن أتجنب ذلك. أسأنا قراءة السوق — نقطة السعر كانت خاطئة، والتوقيت كان أسوأ. تعلمنا من ذلك."},{s:0,t:"Learned how, exactly? What changed?",ar:"تعلمتم كيف، بالضبط؟ ما الذي تغير؟"},{s:1,t:"Everything about our decision-making. We now test with real users before launch, and we kill projects early instead of throwing good money after bad.",ar:"كل شيء في صنع القرار لدينا. نختبر الآن مع مستخدمين حقيقيين قبل الإطلاق، ونقتل المشاريع مبكرًا بدلًا من الاستمرار في تمويل مشروع خاسر."},{s:0,t:"Kill projects early. That's hard for founders — they fall in love with their ideas.",ar:"قتل المشاريع مبكرًا. هذا صعب على المؤسسين — يقعون في حب أفكارهم."},{s:1,t:"It is hard. But discipline is what separates a business from a hobby. A hobby you fund forever; a business has to stand on its own.",ar:"إنه صعب. لكن الانضباط هو ما يفصل العمل التجاري عن الهواية. الهواية تمولها إلى الأبد؛ أما العمل فيجب أن يقف على قدميه."},{s:0,t:"Alright, let me switch gears — what's your take on capitalism right now? It's under fire from all sides.",ar:"حسنًا، دعني أغير الموضوع — ما رأيك في الرأسمالية الآن؟ إنها تحت النار من كل الجهات."},{s:1,t:"Honestly? The system needs reform, not a funeral. Markets are brilliant at innovation and terrible at fairness — you need both engines.",ar:"بصراحة؟ النظام يحتاج إلى إصلاح، لا إلى جنازة. الأسواق رائعة في الابتكار وسيئة في العدالة — تحتاج إلى المحركين معًا."},{s:0,t:"Both engines. So regulation, not revolution.",ar:"كلا المحركين. إذن تنظيم، لا ثورة."},{s:1,t:"Pretty much. Look at the countries that work best — strong markets plus strong safety nets. It's not either-or.",ar:"تقريبًا. انظر إلى الدول التي تعمل بشكل أفضل — أسواق قوية بالإضافة إلى شبكات أمان قوية. ليس أحدهما أو الآخر."},{s:0,t:"But the safety net costs money. Taxes go up, businesses complain, and—",ar:"لكن شبكة الأمان تكلف مالًا. الضرائب ترتفع، والشركات تشتكي، و—"},{s:1,t:"—And yet those countries outperform everyone else on health, education, happiness. The data's pretty clear on that.",ar:"—ومع ذلك تتفوق تلك الدول على الجميع في الصحة والتعليم والسعادة. البيانات واضحة جدًا في ذلك."},{s:0,t:"Touché. Okay, what about inequality within companies? The CEO makes three hundred times the average worker.",ar:"أصبتَ. حسنًا، ماذا عن عدم المساواة داخل الشركات؟ المدير التنفيذي يكسب ثلاثمئة ضعف العامل العادي."},{s:1,t:"That's indefensible, in my view. No one's contribution is worth three hundred times another's. It corrodes trust from the inside.",ar:"هذا لا يمكن الدفاع عنه، في رأيي. مساهمة أحد لا تساوي ثلاثمئة ضعف مساهمة آخر. إنه يفسد الثقة من الداخل."},{s:0,t:"So you'd cap executive pay?",ar:"إذن ستضع سقفًا لأجور التنفيذيين؟"},{s:1,t:"I'd tie it to something real — say, a ratio to the median worker, plus long-term performance. No more bonuses for short-term tricks.",ar:"سأربطه بشيء حقيقي — مثلًا، نسبة إلى العامل المتوسط، بالإضافة إلى الأداء طويل المدى. لا مزيد من المكافآت على الحيل قصيرة المدى."},{s:0,t:"I like that. But shareholders would revolt.",ar:"يعجبني هذا. لكن المساهمين سيثورون."},{s:1,t:"Some would. But the smart ones already see it — a company that treats people well performs better. The evidence is stacking up.",ar:"بعضهم سيثور. لكن الأذكياء يرون ذلك بالفعل — الشركة التي تعامل الناس جيدًا تؤدي بشكل أفضل. الأدلة تتراكم."},{s:0,t:"Alright, let's talk about your competition. There's a rival launching a cheaper product next month.",ar:"حسنًا، لنتحدث عن منافسيك. هناك منافس يطلق منتجًا أرخص الشهر المقبل."},{s:1,t:"Let them. Cheaper isn't better — it's just cheaper. Our customers stay because the product works and the support is human.",ar:"دعهم. الأرخص ليس الأفضل — بل أرخص فقط. عملاؤنا يبقون لأن المنتج يعمل والدعم بشري."},{s:0,t:"Human support. In an age of chatbots, that's actually a selling point.",ar:"دعم بشري. في عصر روبوتات المحادثة، هذه نقطة بيع فعلًا."},{s:1,t:"Exactly. And our availability is twenty-four seven — a real person, not a phone tree from hell.",ar:"بالضبط. وتوفرنا على مدار الساعة — شخص حقيقي، وليس قائمة هاتفية آلية لا تنتهي."},{s:0,t:"Okay, I'm warming up. But one more thing — the auction for that smaller competitor. Are you buying them?",ar:"حسنًا، بدأت أقتنع. لكن شيء آخر — المزاد على ذلك المنافس الأصغر. هل ستشتريهم؟"},{s:1,t:"We're looking at it. Their tech would complement ours nicely — but only at the right price. I won't overpay for a shiny object.",ar:"نحن ننظر في الأمر. تقنيتهم ستكمل تقنيتنا بشكل جيد — لكن فقط بالسعر المناسب. لن أدفع أكثر من اللازم مقابل شيء لامع."},{s:0,t:"Discipline again. I respect that.",ar:"الانضباط مجددًا. أحترم ذلك."},{s:1,t:"Thanks. Look, I know this is a big decision for you. Take your time — read the numbers, talk to our clients, kick the tires.",ar:"شكرًا. انظر، أعرف أن هذا قرار كبير بالنسبة لك. خذ وقتك — اقرأ الأرقام، وتحدث إلى عملائنا، وافحص كل شيء."},{s:0,t:"Kick the tires. Alright — I'll do my homework. But I'm leaning yes.",ar:"افحص كل شيء. حسنًا — سأقوم بواجبي. لكنني أميل إلى الموافقة."},{s:1,t:"That's all I ask. And hey — whatever you decide, the door's open.",ar:"هذا كل ما أطلبه. وهيّا — مهما قررت، الباب مفتوح."},{s:0,t:"What about the commodity markets — oil, wheat, coffee? Prices swing wildly, and small producers get crushed.",ar:"ماذا عن أسواق السلع — النفط والقمح والقهوة؟ الأسعار تتأرجح بشدة، والمنتجون الصغار يُسحقون."},{s:1,t:"They're brutal. And the ranking of who profits is upside down — the farmers get pennies, the middlemen get the margin. Equity in the supply chain is the real issue.",ar:"إنها قاسية. وترتيب من يجني الأرباح مقلوب — المزارعون يحصلون على فتات، والوسطاء يحصلون على الهامش. العدالة في سلسلة التوريد هي القضية الحقيقية."},{s:0,t:"So would a quota system help — guaranteeing farmers a minimum price?",ar:"إذن هل يساعد نظام الحصص — ضمان حد أدنى للسعر للمزارعين؟"},{s:1,t:"It can, if it's enforced. But sanctions and trade rules complicate everything — and a celebrity endorsement won't fix a broken market.",ar:"يمكنه ذلك، إذا طُبق. لكن العقوبات وقواعد التجارة تعقد كل شيء — وتأييد المشاهير لن يصلح سوقًا مكسورًا."},{s:0,t:"Here's my worry — if we abolish the bonus culture entirely, won't our best people leave?",ar:"إليك قلقي — إذا ألغينا ثقافة المكافآت تمامًا، ألن يغادر أفضل موظفينا؟"},{s:1,t:"Some might. But the benchmark for retention isn't pay alone — it's respect, growth, and a fair share. A surplus shared honestly beats a bonus handed out in secret.",ar:"قد يغادر بعضهم. لكن معيار الاحتفاظ ليس الأجر وحده — بل الاحترام والنمو وحصة عادلة. فائض يُشارك بصدق يتفوق على مكافأة تُمنح سرًا."},{s:0,t:"Appreciate it. Let's talk again next week.",ar:"أقدر ذلك. لنتحدث مجددًا الأسبوع المقبل."},{s:1,t:"Done. I'll have the full projections ready — and the coffee's on me.",ar:"تم. سأجهز التوقعات الكاملة — والقهوة على حسابي."}]}},{stage:8,topic:"news",topicAr:"الأخبار والأحداث الجارية",topicEn:"News & Current Events",topicDe:"Nachrichten und Aktuelles",emoji:"📰",title:"الأخبار: بين الحقيقة والإثارة",grammar:{id:"en-c1-hedging-stance",title:"Hedging and stance",titleAr:"التحفظ والتعبير عن الموقف (Hedging)",covers:1},conv:{id:"en-stage8-c1",speakers:["Anchor (مقدّم الأخبار)","Reporter (المراسل)"],turns:[{s:0,t:"Okay, I need to vent. I watched the news last night and I felt... manipulated. Am I paranoid?",ar:"حسنًا، أحتاج أن أفرغ. شاهدت الأخبار الليلة الماضية وشعرت... بأنني مُتلاعَب بي. هل أنا مصاب بجنون الارتياب؟"},{s:1,t:"You're not paranoid — you're paying attention. A lot of news now is engineered to provoke, not inform.",ar:"أنت لست مصابًا بجنون الارتياب — بل منتبه. كثير من الأخبار الآن مصممة للاستفزاز، لا للإعلام."},{s:0,t:"Engineered how? Give me an example.",ar:"مصممة كيف؟ أعطني مثالًا."},{s:1,t:"Take the riot coverage last week. The footage looped the same burning car for six hours — meanwhile the peaceful march of ten thousand people got thirty seconds.",ar:"خذ تغطية أعمال الشغب الأسبوع الماضي. اللقطات كررت نفس السيارة المحترقة لست ساعات — بينما المسيرة السلمية لعشرة آلاف شخص حصلت على ثلاثين ثانية."},{s:0,t:"Thirty seconds. That's insane.",ar:"ثلاثون ثانية. هذا جنوني."},{s:1,t:"It's ratings logic. Calm doesn't sell. Fear does. And the algorithm rewards whatever keeps you watching.",ar:"إنه منطق نسب المشاهدة. الهدوء لا يبيع. الخوف يبيع. والخوارزمية تكافئ كل ما يبقيك تشاهد."},{s:0,t:"So we're stuck in a loop — the scarier the news, the more we watch, the scarier it gets.",ar:"إذن نحن عالقون في حلقة — كلما كانت الأخبار أخوف، شاهدنا أكثر، وكلما صارت أخوف."},{s:1,t:"Pretty much. And the worst part? It distorts what we think the world is like. People think crime is rising when it's actually falling.",ar:"تقريبًا. والأسوأ؟ إنه يشوه ما نظن أن العالم عليه. الناس يظنون أن الجريمة ترتفع بينما هي تنخفض فعلًا."},{s:0,t:"Wait, is that true? Crime is falling?",ar:"انتظر، هل هذا صحيح؟ الجريمة تنخفض؟"},{s:1,t:"In most rich countries, yeah — homicide rates are way down from the nineties. But you'd never know it from the headlines.",ar:"في معظم الدول الغنية، نعم — معدلات القتل أقل بكثير من التسعينيات. لكنك لن تعرف ذلك أبدًا من العناوين."},{s:0,t:"Because a falling crime rate isn't a story.",ar:"لأن انخفاض معدل الجريمة ليس قصة."},{s:1,t:"Exactly. 'Things slowly getting better' doesn't trend. A single shocking case does — and suddenly everyone's terrified.",ar:"بالضبط. 'الأشياء تتحسن ببطء' لا ينتشر. أما حالة صادمة واحدة فتنتشر — وفجأة الجميع مرعوب."},{s:0,t:"Okay, but what about the big stuff — war, genocide? That has to be covered.",ar:"حسنًا، لكن ماذا عن الأشياء الكبيرة — الحرب، والإبادة الجماعية؟ يجب تغطيتها."},{s:1,t:"It does, and it is — but selectively. Some victims get wall-to-wall coverage, others get nothing. The difference is politics, not suffering.",ar:"يجب، وهي تُغطى — لكن بانتقائية. بعض الضحايا يحصلون على تغطية شاملة، والبعض الآخر لا يحصل على شيء. الفرق هو السياسة، وليس المعاناة."},{s:0,t:"That's bleak. So how do I stay informed without losing my mind?",ar:"هذا قاتم. إذن كيف أبقى مطلعًا دون أن أفقد عقلي؟"},{s:1,t:"Diversify. Read sources you disagree with, check the original data, and — this is key — limit the dose. News is like sugar: a little is fine, a flood is toxic.",ar:"نوّع. اقرأ مصادر تختلف معها، وتحقق من البيانات الأصلية، و— وهذا أساسي — حدد الجرعة. الأخبار مثل السكر: القليل جيد، والفيضان سام."},{s:0,t:"Limit the dose. I like that. But what about misinformation? The fake stuff spreads faster than the truth.",ar:"حدد الجرعة. يعجبني هذا. لكن ماذا عن المعلومات المضللة؟ الأشياء المزيفة تنتشر أسرع من الحقيقة."},{s:1,t:"It does — lies are simpler and more exciting. The fix is boring: verification, corrections, media literacy. Nobody wants to fund boring.",ar:"نعم تنتشر — الأكاذيب أبسط وأكثر إثارة. الإصلاح ممل: التحقق والتصحيحات ومحو الأمية الإعلامية. لا أحد يريد تمويل الممل."},{s:0,t:"Media literacy — teaching kids to spot a fake. Does that even work?",ar:"محو الأمية الإعلامية — تعليم الأطفال اكتشاف المزيف. هل يعمل ذلك أصلًا؟"},{s:1,t:"It does, actually — when it's done well. The trick is teaching doubt without teaching cynicism. Skeptical, not suspicious of everything.",ar:"يعمل فعلًا — عندما يُنفذ جيدًا. الحيلة هي تعليم الشك دون تعليم الارتياب في كل شيء. متشكك، وليس مرتابًا من كل شيء."},{s:0,t:"Skeptical, not cynical. That's a fine line.",ar:"متشكك، وليس متشائمًا. هذا خط رفيع."},{s:1,t:"It is. But it's the line that keeps democracy alive. Without it, anyone with a megaphone can steer the crowd.",ar:"إنه كذلك. لكنه الخط الذي يبقي الديمقراطية حية. بدونه، أي شخص لديه مكبر صوت يمكنه توجيه الحشد."},{s:0,t:"Speaking of steering — what about the trials? The big corruption case. The coverage feels like a circus.",ar:"بالحديث عن التوجيه — ماذا عن المحاكمات؟ قضية الفساد الكبيرة. التغطية تبدو كسيرك."},{s:1,t:"Because it is one, partly. The cameras turn a proceeding into a spectacle — and the lawyers play to the audience, not the judge.",ar:"لأنها كذلك، جزئيًا. الكاميرات تحول الإجراءات إلى استعراض — والمحامون يلعبون للجمهور، وليس للقاضي."},{s:0,t:"And the defendant testifying on live TV — is that justice or theater?",ar:"والمتهم يشهد على التلفزيون المباشر — هل هذا عدالة أم مسرح؟"},{s:1,t:"Both, unfortunately. The public has a right to know — but the circus can poison the jury pool before the trial even starts.",ar:"كلاهما، للأسف. للجمهور الحق في المعرفة — لكن السيرك قد يسمم هيئة المحلفين قبل بدء المحاكمة أصلًا."},{s:0,t:"Poison the jury. Yeah, I hadn't thought of that.",ar:"يسمم هيئة المحلفين. نعم، لم أفكر في ذلك."},{s:1,t:"Most people don't. And meanwhile the really important stories — the slow ones, the systemic ones — get buried.",ar:"معظم الناس لا يفكرون. وفي الوقت نفسه القصص المهمة حقًا — البطيئة والمنهجية — تُدفن."},{s:0,t:"Like what? Give me one buried story.",ar:"مثل ماذا؟ أعطني قصة مدفونة واحدة."},{s:1,t:"Incarceration rates. Millions locked up, mostly poor, mostly for nonviolent offenses — and it barely makes the news anymore.",ar:"مثل معدلات السجن. ملايين مسجونون، معظمهم فقراء، ومعظمهم لجرائم غير عنيفة — وبالكاد تظهر في الأخبار بعد الآن."},{s:0,t:"Millions. And we just... accept it?",ar:"ملايين. ونحن فقط... نقبل ذلك؟"},{s:1,t:"We accept what we don't see. That's why the spotlight matters — where it points, that's what we think is real.",ar:"نقبل ما لا نراه. لهذا تهم الأضواء — حيث تشير، هذا ما نظن أنه حقيقي."},{s:0,t:"Where it points. Okay, that's going to stick with me.",ar:"حيث تشير. حسنًا، هذا سيبقى معي."},{s:1,t:"Good. And hey — reportedly, the network's launching a slow-news segment next month. Actual depth, no shouting.",ar:"جيد. وهيّا — يُقال إن الشبكة ستطلق فقرة أخبار بطيئة الشهر المقبل. عمق حقيقي، بلا صراخ."},{s:0,t:"Slow news? I'll believe it when I see it.",ar:"أخبار بطيئة؟ سأصدق ذلك عندما أراه."},{s:1,t:"Fair enough. But if it works, it could change the whole game.",ar:"عادل بما يكفي. لكن إذا نجح، فقد يغير اللعبة كلها."},{s:0,t:"What about the extremist groups — the militia that stormed the building? The coverage made them sound almost heroic.",ar:"ماذا عن الجماعات المتطرفة — الميليشيا التي اقتحمت المبنى؟ التغطية جعلتهم يبدون أبطالًا تقريبًا."},{s:1,t:"That's the danger — an infamous leader gets a spotlight, and suddenly the mob grows. A notorious face on every screen becomes a recruiting poster.",ar:"هذا هو الخطر — قائد سيئ السمعة يحصل على الأضواء، وفجأة ينمو الغوغاء. وجه سيئ السمعة على كل شاشة يصبح ملصق تجنيد."},{s:0,t:"And the courts? Who has jurisdiction when the crime crosses state lines?",ar:"والمحاكم؟ من له الولاية القضائية عندما تعبر الجريمة حدود الولايات؟"},{s:1,t:"That's the messy part — federal and state prosecutors fight over it, while the trafficking and slavery cases wait in line for years.",ar:"هذا هو الجزء الفوضوي — المدعون الفيدراليون ومدعو الولايات يتنازعون عليه، بينما قضايا الاتجار والعبودية تنتظر في الطابور لسنوات."},{s:0,t:"The city councilor resigned today — reportedly after the inquiry into the contracts. Did you see the press conference?",ar:"استقال عضو المجلس اليوم — يُقال بعد التحقيق في العقود. هل رأيت المؤتمر الصحفي؟"},{s:1,t:"I did. He presided over the committee for a decade, and his predecessor warned about the same deals. The squad covering it says a warrant may be next — but let's wait for facts, not rumors.",ar:"رأيته. ترأس اللجنة لعقد، وسلفه حذر من نفس الصفقات. الفريق الذي يغطي الأمر يقول إن مذكرة قد تكون التالية — لكن لننتظر الحقائق، لا الشائعات."},{s:0,t:"Alright. Same time tomorrow? I'll bring the coffee — and my skepticism.",ar:"حسنًا. نفس الوقت غدًا؟ سأحضر القهوة — وتشككي."},{s:1,t:"Deal. Bring both — we'll need them.",ar:"اتفقنا. أحضر كليهما — سنحتاجهما."}]}},{stage:9,topic:"culture",topicAr:"الثقافة والقصص اليومية",topicEn:"Culture & Daily Stories",topicDe:"Kultur und Alltagsgeschichten",emoji:"🎭",title:"السينما مرآة المجتمع",grammar:{id:"en-c1-participle-perfect-advanced",title:"Participle clauses",titleAr:"الجمل الوصفية بالمصدر",covers:1},conv:{id:"en-stage9-c1",speakers:["Filmmaker (المخرج)","Critic (الناقد)"],turns:[{s:0,t:"So I finally watched your film. And I've gotta say — I was not expecting that ending.",ar:"إذن شاهدت فيلمك أخيرًا. ويجب أن أقول — لم أكن أتوقع تلك النهاية."},{s:1,t:"Ha! Nobody does. That was the point — I wanted the audience to leave arguing.",ar:"ها! لا أحد يتوقعها. كان هذا هو الهدف — أردت أن يغادر الجمهور وهم يتجادلون."},{s:0,t:"Oh, we argued alright. My friend loved it, I thought it was... indulgent. Too long, too in love with itself.",ar:"أوه، تجادلنا بالتأكيد. صديقي أحبه، وأنا ظننت أنه... مُسرف. طويل جدًا، وعاشق لنفسه أكثر من اللازم."},{s:1,t:"Fair criticism — I hear it a lot. But the length was deliberate. The slowness is the argument.",ar:"نقد عادل — أسمعه كثيرًا. لكن الطول كان متعمدًا. البطء هو الحجة."},{s:0,t:"The slowness is the argument. Okay, explain that to me like I'm not a film student.",ar:"البطء هو الحجة. حسنًا، اشرح ذلك لي كأنني لست طالب سينما."},{s:1,t:"Sure. The film is about waiting — a woman waiting for a beloved who never comes. If I cut it fast, the waiting means nothing. You have to feel it.",ar:"بالتأكيد. الفيلم عن الانتظار — امرأة تنتظر حبيبًا لا يأتي أبدًا. إذا قطعت المشاهد بسرعة، فالانتظار لا يعني شيئًا. يجب أن تشعر به."},{s:0,t:"Hmm. Okay, I can respect that — even if I checked my phone twice.",ar:"همم. حسنًا، يمكنني احترام ذلك — حتى لو تفقدت هاتفي مرتين."},{s:1,t:"Twice? I'll take it. Some people check it ten times.",ar:"مرتين؟ سأقبل بذلك. بعض الناس يتفقدونه عشر مرات."},{s:0,t:"Ha! Alright, let me ask about the casting. A solo performance, basically one actor for two hours — that was brave.",ar:"ها! حسنًا، دعني أسأل عن التمثيل. أداء منفرد، ممثل واحد تقريبًا لساعتين — كان ذلك شجاعًا."},{s:1,t:"It was a gamble. But she's superb — every flicker of doubt, every sigh, it's all there on her face. No dialogue needed.",ar:"كان مقامرة. لكنها ممتازة — كل ومضة شك وكل تنهيدة، كلها هناك على وجهها. لا حاجة إلى حوار."},{s:0,t:"No dialogue needed. That's true — the silent scenes were the strongest.",ar:"لا حاجة إلى حوار. هذا صحيح — المشاهد الصامتة كانت الأقوى."},{s:1,t:"Thank you. That's the highest praise for a filmmaker — when the image does the talking.",ar:"شكرًا. هذا أعلى مديح لمخرج — عندما تتحدث الصورة."},{s:0,t:"But let me push you on something — the film's politics. Some critics called it feminist, others said it stereotypes women as passive.",ar:"لكن دعني أضغط عليك في شيء — سياسة الفيلم. بعض النقاد وصفوه بالنسوي، وآخرون قالوا إنه يُنمّط النساء كسلبيات."},{s:1,t:"Both readings are in there, honestly. She's waiting — but the waiting is her choice, her defiance. Passivity can be a form of resistance.",ar:"كلا القراءتين موجودتان، بصراحة. إنها تنتظر — لكن الانتظار هو خيارها وتحديها. السلبية يمكن أن تكون شكلًا من أشكال المقاومة."},{s:0,t:"Defiance through waiting. That's a stretch, isn't it?",ar:"التحدي عبر الانتظار. هذا مبالغة، أليس كذلك؟"},{s:1,t:"Maybe. But the best films leave room for the stretch — the audience completes the meaning.",ar:"ربما. لكن أفضل الأفلام تترك مساحة للمبالغة — الجمهور يكمل المعنى."},{s:0,t:"Okay, what about the music? That bass line in the final scene — it just... shook the theater.",ar:"حسنًا، ماذا عن الموسيقى؟ خط الجهير في المشهد الأخير — لقد هزّ المسرح ببساطة."},{s:1,t:"That's the composer — a genius. We wanted the sound to hit you physically, like a heartbeat getting louder.",ar:"هذا هو الملحن — عبقري. أردنا أن يصيبك الصوت جسديًا، مثل نبض قلب يزداد ارتفاعًا."},{s:0,t:"It worked. My chest was pounding. And the trio of musicians in the café scene — were they real?",ar:"لقد نجح. كان صدري يخفق. والثلاثي من الموسيقيين في مشهد المقهى — هل كانوا حقيقيين؟"},{s:1,t:"Real musicians, yeah — a local trio we found by accident. They improvised the whole scene. Pure magic.",ar:"موسيقيون حقيقيون، نعم — ثلاثي محلي وجدناه بالصدفة. ارتجلوا المشهد كله. سحر خالص."},{s:0,t:"By accident. I love that — the best moments aren't planned.",ar:"بالصدفة. أحب ذلك — أفضل اللحظات ليست مخططة."},{s:1,t:"Exactly. You plan the frame, then you let life in. That's the whole job, really.",ar:"بالضبط. تخطط للإطار، ثم تدع الحياة تدخل. هذه هي الوظيفة كلها، حقًا."},{s:0,t:"Alright, bigger question — cinema in the age of streaming. Is the theater dying?",ar:"حسنًا، سؤال أكبر — السينما في عصر البث. هل دور السينما تحتضر؟"},{s:1,t:"Dying? No. Changing, yeah. The spectacle films will always need a big screen — but the quiet ones, like mine, they struggle.",ar:"يحتضر؟ لا. يتغير، نعم. أفلام الاستعراض ستحتاج دائمًا إلى شاشة كبيرة — لكن الهادئة، مثل فيلمي، تكافح."},{s:0,t:"Because people watch them on their phones, half-distracted.",ar:"لأن الناس يشاهدونها على هواتفهم، مشتتين بنصف انتباه."},{s:1,t:"Right. And a film like this demands your full attention — it doesn't work as background noise.",ar:"صحيح. وفيلم مثل هذا يتطلب انتباهك الكامل — لا يعمل كضجيج خلفي."},{s:0,t:"So what's the future? Smaller theaters, curated screenings?",ar:"إذن ما المستقبل؟ صالات أصغر وعروض منتقاة؟"},{s:1,t:"Probably. Intimate rooms, engaged audiences — quality over quantity. The glory days of the megaplex are over, I think.",ar:"على الأرجح. غرف حميمة وجماهير منخرطة — الجودة على الكمية. أيام مجد المجمعات الضخمة انتهت، أظن."},{s:0,t:"The glory days are over. That's sad — I grew up in those megaplexes.",ar:"أيام المجد انتهت. هذا محزن — لقد نشأت في تلك المجمعات."},{s:1,t:"Me too. But culture moves on — the novel didn't kill theater, TV didn't kill film. Something new will come.",ar:"وأنا أيضًا. لكن الثقافة تمضي — الرواية لم تقتل المسرح، والتلفزيون لم يقتل السينما. سيأتي شيء جديد."},{s:0,t:"Something new. Like what — VR films?",ar:"شيء جديد. مثل ماذا — أفلام الواقع الافتراضي؟"},{s:1,t:"Maybe. Or something we can't even picture yet. That's the exciting part — and the scary part.",ar:"ربما. أو شيء لا نستطيع حتى تخيله بعد. هذا هو الجزء المثير — والجزء المخيف."},{s:0,t:"Exciting and scary. Sounds like every art form, ever.",ar:"مثير ومخيف. يبدو مثل كل شكل فني، على الإطلاق."},{s:1,t:"Pretty much. And hey — thanks for watching it, really. Even the criticism. Especially the criticism.",ar:"تقريبًا. وهيّا — شكرًا لمشاهدته، حقًا. حتى النقد. وخاصة النقد."},{s:0,t:"Anytime. Next one's on me — I'll bring the popcorn.",ar:"في أي وقت. المرة القادمة عليّ — سأحضر الفشار."},{s:0,t:"One more thing — the dub. I watched the dubbed version first, and it felt... off. The voices didn't match the faces.",ar:"شيء آخر — الدبلجة. شاهدت النسخة المدبلجة أولًا، وشعرت... بأنها غريبة. الأصوات لم تطابق الوجوه."},{s:1,t:"Dubbing is an art, and a bad dub kills a film. The original voices carry the emotion — a good dub is appealing, a bad one is just noise.",ar:"الدبلجة فن، والدبلجة السيئة تقتل الفيلم. الأصوات الأصلية تحمل العاطفة — الدبلجة الجيدة جذابة، والسيئة مجرد ضجيج."},{s:0,t:"And the comeback of the old director — everyone said he was finished, then this film.",ar:"وعودة المخرج القديم — قال الجميع إنه انتهى، ثم جاء هذا الفيلم."},{s:1,t:"Yeah, a charming comeback, honestly. The critics were skeptical, but the film is engaging from the first minute — bless the producer who backed him.",ar:"نعم، عودة ساحرة، بصراحة. كان النقاد متشككين، لكن الفيلم جذاب من الدقيقة الأولى — بارك الله في المنتج الذي دعمه."},{s:0,t:"I have to congratulate you, by the way — the film got a standing ovation. I was thrilled for you.",ar:"يجب أن أهنئك، بالمناسبة — حصل الفيلم على تصفيق حار. كنت متحمسًا من أجلك."},{s:1,t:"Thank you — honestly, I was stunned. And the best part? The audience stayed for the Q&A — a full hour, no one left. That's rare.",ar:"شكرًا — بصراحة، كنت مندهشًا. وأفضل جزء؟ بقي الجمهور لجلسة الأسئلة والأجوبة — ساعة كاملة، لم يغادر أحد. هذا نادر."},{s:1,t:"Deal. And no checking your phone this time.",ar:"اتفقنا. وبدون تفقد هاتفك هذه المرة."},{s:0,t:"No promises.",ar:"لا وعود."}]}},{stage:10,topic:"education",topicAr:"التعليم والدراسة",topicEn:"Education & Study",topicDe:"Bildung und Studium",emoji:"🎓",title:"التعليم: حفظ أم تفكير؟",grammar:{id:"en-c1-modal-meanings-advanced",title:"Advanced modal meanings",titleAr:"معاني الأفعال الناقصة المتقدمة",covers:1},conv:{id:"en-stage10-c1",speakers:["Teacher (المعلم)","Parent (ولي الأمر)"],turns:[{s:0,t:"Thanks for coming in. I wanted to talk about your daughter — she's bright, but her grades have slipped this term.",ar:"شكرًا لحضورك. أردت التحدث عن ابنتك — إنها ذكية، لكن درجاتها تراجعت هذا الفصل."},{s:1,t:"Slipped? She studies every night! I see her at her desk for hours.",ar:"تراجعت؟ إنها تدرس كل ليلة! أراها على مكتبها لساعات."},{s:0,t:"I believe you. But hours at a desk don't always mean learning. Sometimes it means staring at a page, stuck.",ar:"أصدقك. لكن ساعات على المكتب لا تعني دائمًا التعلم. أحيانًا تعني التحديق في صفحة، عالقة."},{s:1,t:"Stuck on what? She's always been good at school.",ar:"عالقة في ماذا؟ لطالما كانت جيدة في المدرسة."},{s:0,t:"On the shift, I think. The work this year asks for analysis, not memorization — and that's a different muscle.",ar:"في التحول، أظن. العمل هذا العام يطلب التحليل، لا الحفظ — وهذه عضلة مختلفة."},{s:1,t:"Analysis. So she's memorizing when she should be thinking?",ar:"التحليل. إذن هي تحفظ بينما يجب أن تفكر؟"},{s:0,t:"Pretty much. She can recite the whole chapter — but ask her what it means, and she goes blank.",ar:"تقريبًا. يمكنها تسميع الفصل كله — لكن اسألها ماذا يعني، فيخلو ذهنها تمامًا."},{s:1,t:"That worries me. Is that my fault? Did I push the memorizing?",ar:"هذا يقلقني. هل هذا خطئي؟ هل دفعتها نحو الحفظ؟"},{s:0,t:"Not your fault at all. The old system rewarded it — and honestly, most schools still do. We're trying to change that here.",ar:"ليس خطأك على الإطلاق. النظام القديم كان يكافئه — وبصراحة، معظم المدارس ما زالت تفعل. نحن نحاول تغيير ذلك هنا."},{s:1,t:"How? What does that change look like in practice?",ar:"كيف؟ كيف يبدو هذا التغيير في الممارسة؟"},{s:0,t:"Fewer lectures, more discussion. We give them a real problem — a genuine query with no single answer — and let them argue it out.",ar:"محاضرات أقل ونقاش أكثر. نعطيهم مشكلة حقيقية — سؤال حقيقي بلا إجابة واحدة — وندعهم يجادلون فيه."},{s:1,t:"Argue it out. In class? That sounds chaotic.",ar:"يجادلون فيه. في الصف؟ هذا يبدو فوضويًا."},{s:0,t:"It is chaotic — gloriously so. But that's where the learning lives. A student who defends an idea remembers it.",ar:"إنه فوضوي — بشكل رائع. لكن التعلم يعيش هناك. الطالب الذي يدافع عن فكرة يتذكرها."},{s:1,t:"Okay, I can see that. But what about exams? They still test memorization, don't they?",ar:"حسنًا، أستطيع رؤية ذلك. لكن ماذا عن الامتحانات؟ ما زالت تختبر الحفظ، أليس كذلك؟"},{s:0,t:"Some do — and that's a problem we're fighting. Our own assessments now focus on reasoning: explain, compare, critique.",ar:"بعضها يفعل — وهذه مشكلة نحاربها. تقييماتنا الآن تركز على التفكير: اشرح وقارن وانتقد."},{s:1,t:"Critique — at her age? She's fourteen.",ar:"انتقد — في عمرها؟ إنها في الرابعة عشرة."},{s:0,t:"Fourteen is plenty old enough. Give a teenager a weak argument and watch what happens — they'll tear it apart.",ar:"الرابعة عشرة كبيرة بما يكفي. أعطِ مراهقًا حجة ضعيفة وراقب ما يحدث — سيمزقها."},{s:1,t:"Ha! True — my daughter tears my arguments apart every night at dinner.",ar:"ها! صحيح — ابنتي تمزق حججي كل ليلة على العشاء."},{s:0,t:"See? The skill is there. We just need to point it at the right material — and give her timely feedback when she tries.",ar:"أرأيت؟ المهارة موجودة. نحتاج فقط إلى توجيهها نحو المادة المناسبة — ومنحها تغذية راجعة في الوقت المناسب عندما تحاول."},{s:1,t:"Timely feedback. Her old teacher took three weeks to return essays.",ar:"تغذية راجعة في الوقت المناسب. معلمها القديم كان يستغرق ثلاثة أسابيع لإعادة المقالات."},{s:0,t:"Three weeks is useless — by then she's moved on. We aim for forty-eight hours, max.",ar:"ثلاثة أسابيع عديمة الفائدة — بحلول ذلك الوقت تكون قد انتقلت. نهدف إلى ثمانٍ وأربعين ساعة، كحد أقصى."},{s:1,t:"That's a big difference. What else can I do at home?",ar:"هذا فرق كبير. ماذا يمكنني أن أفعل أيضًا في المنزل؟"},{s:0,t:"Talk with her, not at her. Ask what she's reading, what she disagrees with. And — this matters — let her see you struggle with something hard.",ar:"تحدث معها، لا إليها. اسألها عما تقرأ وما تختلف معه. و— وهذا مهم — دعها تراك تكافح مع شيء صعب."},{s:1,t:"Let her see me struggle? That's... counterintuitive.",ar:"أدعها تراني أكافح؟ هذا... غير بديهي."},{s:0,t:"It works, though. Kids who see adults wrestle with difficulty learn that struggle is normal — not a sign of failure.",ar:"لكنه يعمل. الأطفال الذين يرون الكبار يصارعون الصعوبة يتعلمون أن الكفاح طبيعي — وليس علامة فشل."},{s:1,t:"Normal, not failure. I wish someone had told me that at her age.",ar:"طبيعي، وليس فشلًا. أتمنى لو أن أحدًا أخبرني بذلك في عمرها."},{s:0,t:"Me too. And one more thing — her dedication is real. She cares deeply; she's just using the wrong tools. That we can fix.",ar:"وأنا أيضًا. وشيء آخر — تفانيها حقيقي. إنها تهتم بعمق؛ فقط تستخدم الأدوات الخاطئة. وهذا يمكننا إصلاحه."},{s:1,t:"So it's not ability — it's strategy.",ar:"إذن ليست القدرة — بل الاستراتيجية."},{s:0,t:"Exactly. And the scope of the fix is small — a few habits, a little guidance, and she'll be flying.",ar:"بالضبط. ونطاق الإصلاح صغير — بعض العادات وقليل من التوجيه، وستطير."},{s:1,t:"Flying. I like the sound of that. What habits, specifically?",ar:"تطير. يعجبني صوت ذلك. ما العادات، تحديدًا؟"},{s:0,t:"Three things. First, summarize each lesson in her own words — no copying. Second, test herself before she feels ready. Third, sleep — a tired brain retains nothing.",ar:"ثلاثة أشياء. أولًا، تلخيص كل درس بكلماتها الخاصة — بدون نسخ. ثانيًا، اختبار نفسها قبل أن تشعر بالاستعداد. ثالثًا، النوم — الدماغ المتعب لا يحتفظ بشيء."},{s:1,t:"Sleep. Yeah, she's up till midnight most nights.",ar:"النوم. نعم، تسهر حتى منتصف الليل معظم الليالي."},{s:0,t:"That's the first thing to fix, honestly. A rested brain beats a cramming brain every single time.",ar:"هذا أول شيء يجب إصلاحه، بصراحة. الدماغ المرتاح يتفوق على الدماغ الذي يحشو في كل مرة."},{s:1,t:"Alright — midnight curfew, starting tonight. She'll hate me for a week.",ar:"حسنًا — النوم عند منتصف الليل، بدءًا من الليلة. ستكرهني لأسبوع."},{s:0,t:"She'll thank you later. And look — let's meet again in a month. I'll bring her new work, and we'll see the progress together.",ar:"ستشكرك لاحقًا. وانظر — لنتقابل مجددًا بعد شهر. سأحضر عملها الجديد، وسنرى التقدم معًا."},{s:1,t:"A month. Deal. And thank you — I came in worried, and I'm leaving with a plan.",ar:"شهر. اتفقنا. وشكرًا — جئت قلقًا، وأغادر بخطة."},{s:0,t:"That's the job. She's going to be fine — she's got a thoughtful parent and a good brain. That's a strong combination.",ar:"هذه هي الوظيفة. ستكون بخير — لديها والد متأمل وعقل جيد. هذا مزيج قوي."},{s:0,t:"What about the kids who fall behind — do you foster them differently, or just let them catch up on their own?",ar:"ماذا عن الأطفال المتأخرين — هل ترعاهم بشكل مختلف، أم تدعهم يلحقون بأنفسهم؟"},{s:1,t:"We empower them with extra support — small groups, a supportive tutor, and a plan that fits their pace. Nobody gets left to sink.",ar:"نمكّنهم بدعم إضافي — مجموعات صغيرة ومعلم داعم وخطة تناسب وتيرتهم. لا يُترك أحد ليغرق."},{s:0,t:"And how do you measure it? The ranking of schools feels so crude.",ar:"وكيف تقيس ذلك؟ تصنيف المدارس يبدو فظًا جدًا."},{s:1,t:"It is crude. A single ranking can't capture relevance or growth — I'd rather show parents a specification of what their child can actually do, partially through portfolios, not just test scores.",ar:"إنه فظ. تصنيف واحد لا يمكنه التقاط الأهمية أو النمو — أفضل أن أُظهر للآباء بيانًا بما يستطيع طفلهم فعله فعلًا فعلًا، جزئيًا عبر ملفات الأعمال، وليس فقط درجات الاختبار."},{s:0,t:"Do parents get a say in the curriculum, or is that solely the school's call?",ar:"هل للآباء رأي في المنهج، أم أن هذا قرار المدرسة وحدها؟"},{s:1,t:"They do — we hold an open forum each term. And regardless of the topic, a parent can inquire about any lesson, any time. The latter part matters most: transparency builds trust.",ar:"نعم — نعقد منتدى مفتوحًا كل فصل. وبغض النظر عن الموضوع، يمكن لأي ولي أمر أن يستفسر عن أي درس، في أي وقت. الجزء الأخير هو الأهم: الشفافية تبني الثقة."},{s:1,t:"Thank you. Really.",ar:"شكرًا. حقًا."},{s:0,t:"Anytime. Now go — and remember, the midnight rule starts tonight.",ar:"في أي وقت. الآن اذهب — وتذكر، قاعدة منتصف الليل تبدأ الليلة."}]}},{stage:11,topic:"jobs",topicAr:"المهن والعمل",topicEn:"Professions & Work",topicDe:"Berufe und Arbeit",emoji:"💼",title:"مقابلة عمل ومفاوضات",grammar:{id:"en-c1-inversion-full",title:"Inversion",titleAr:"العكس",covers:1},conv:{id:"en-stage11-c1",speakers:["Interviewer (المقابِل)","Candidate (المرشَّح)"],turns:[{s:0,t:"Thanks for coming in. Let's jump right in — tell me why you're here.",ar:"شكرًا لحضورك. لنبدأ مباشرة — أخبرني لماذا أنت هنا."},{s:1,t:"Honestly? I've been following your company for years, and this role finally fits my capability.",ar:"بصراحة؟ أتابع شركتكم منذ سنوات، وهذا الدور يناسب قدراتي أخيرًا."},{s:0,t:"Good answer. So, walk me through your last job. What did you actually do there?",ar:"إجابة جيدة. حدّثني عن وظيفتك الأخيرة. ماذا كنت تفعل فيها فعلًا؟"},{s:1,t:"I ran the intake team — fifteen people, three shifts, and a whole lot of coordination every single day.",ar:"كنت أدير فريق الاستقبال — خمسة عشر شخصًا، ثلاث ورديات، وتنسيق كثير كل يوم."},{s:0,t:"Fifteen people? That's a big crew. How'd you handle the scheduling chaos?",ar:"خمسة عشر شخصًا؟ هذا فريق كبير. كيف تعاملت مع فوضى الجدولة؟"},{s:1,t:"Not only did I rebuild the schedule, I also set up a backup lineup so nobody got stuck covering two shifts.",ar:"لم أُعِد بناء الجدول فحسب، بل جهّزت أيضًا فريقًا احتياطيًا حتى لا يضطر أحد لتغطية ورديتين."},{s:0,t:"Nice. Now, be straight with me — what's your biggest weakness?",ar:"جميل. والآن، كن صريحًا معي — ما أكبر نقطة ضعف لديك؟"},{s:1,t:"I used to say yes to everything. It had an adverse effect on my focus, so I learned to delegate.",ar:"كنت أوافق على كل شيء. وكان لذلك أثر سلبي على تركيزي، فتعلمت تفويض المهام."},{s:0,t:"Delegation — that's huge here. Who did you delegate to, exactly?",ar:"التفويض — هذا مهم جدًا هنا. لمن كنت تفوّض المهام بالضبط؟"},{s:1,t:"Mostly to the contractors. They're specialists, so I'd instruct them on the goal and get out of their way.",ar:"غالبًا للمقاولين. إنهم متخصصون، فكنت أوجههم نحو الهدف وأتركهم يعملون."},{s:0,t:"Hmm. And when a contractor missed a deadline, what then?",ar:"همم. وعندما يتأخر المقاول عن موعد التسليم، ماذا كنت تفعل؟"},{s:1,t:"Rarely did that happen, but when it did, I'd call them the same—",ar:"نادرًا ما كان يحدث ذلك، لكن عندما يحدث، كنت أتصل بهم في اليوم—"},{s:0,t:"—Wait, same day? Okay, that's impressive. Now tell me about a time you had to comply with a rule you disagreed with.",ar:"—انتظر، في اليوم نفسه؟ حسنًا، هذا مثير للإعجاب. الآن حدّثني عن مرة اضطررت فيها للالتزام بقاعدة لم توافق عليها."},{s:1,t:"Oh man, the new regulatory paperwork. It doubled our handling time, but I complied — and then I fixed the process.",ar:"يا رجل، الأوراق التنظيمية الجديدة. ضاعفت وقت المعالجة، لكنني التزمت بها — ثم أصلحت العملية."},{s:0,t:"You fixed it? How?",ar:"أصلحتها؟ كيف؟"},{s:1,t:"I built a simple checklist and trained the team on it. Accordingly, our error rate dropped by half in a month.",ar:"وضعت قائمة تحقق بسيطة ودرّبت الفريق عليها. وبناءً على ذلك، انخفض معدل الأخطاء إلى النصف خلال شهر."},{s:0,t:"That's the kind of initiative we need. What about collaboration across departments?",ar:"هذا هو نوع المبادرة الذي نحتاجه. وماذا عن التعاون بين الأقسام؟"},{s:1,t:"I love it, honestly. I was a regular contributor to the cross-team meetings, and I even ran a few.",ar:"أحبه بصراحة. كنت مشاركًا منتظمًا في اجتماعات الفرق المشتركة، بل أدرت بعضها."},{s:0,t:"Okay, let's talk money. What's your salary expectation?",ar:"حسنًا، لنتحدث عن المال. ما الراتب الذي تتوقعه؟"},{s:1,t:"To be honest, I'm looking for something that'll compensate me fairly for the interim work I did as acting lead.",ar:"بصراحة، أبحث عن شيء يعوّضني بشكل عادل عن العمل المؤقت الذي قمت به كقائد بالنيابة."},{s:0,t:"Acting lead — I saw that. Did anyone nominate you for the permanent role?",ar:"قائد بالنيابة — رأيت ذلك. هل رشّحك أحد للدور الدائم؟"},{s:1,t:"My director did, yeah. But the establishment froze hiring, so the role never opened.",ar:"مديري فعل، نعم. لكن المؤسسة جمّدت التوظيف، فلم يُفتح الدور أبدًا."},{s:0,t:"That's rough. So why leave now?",ar:"هذا صعب. إذن لماذا ترحل الآن؟"},{s:1,t:"Because I wanna grow, not just survive. Your orientation program and the mentorship here are desirable to me.",ar:"لأنني أريد أن أنمو، لا أن أنجو فقط. برنامج التوجيه والإرشاد هنا يعجبني كثيرًا."},{s:0,t:"Fair enough. Are you eligible to work weekends if we need you?",ar:"عادل بما فيه الكفاية. هل يحق لك العمل في عطلات نهاية الأسبوع إذا احتجناك؟"},{s:1,t:"Yeah, mostly. I just need notice — my kid's daycare pickup is mandatory at five.",ar:"نعم، غالبًا. أحتاج فقط إلى إشعار مسبق — موعد استلام طفلي من الحضانة إلزامي في الخامسة."},{s:0,t:"Understood. One more thing — we do background checks and identification verification. Any issue with that?",ar:"مفهوم. شيء أخير — نجري فحوصات خلفية والتحقق من الهوية. هل لديك مشكلة في ذلك؟"},{s:1,t:"None at all. My record's clean, and my references will vouch for my reliability.",ar:"لا مشكلة إطلاقًا. سجلي نظيف، ومراجعي سيشهدون على موثوقيتي."},{s:0,t:"Great. Now, sell me on yourself in one sentence. Go.",ar:"رائع. الآن، أقنعني بنفسك في جملة واحدة. هيّا."},{s:1,t:"I'm the person who turns messy operational problems into systems that actually work.",ar:"أنا الشخص الذي يحوّل المشاكل التشغيلية الفوضوية إلى أنظمة تعمل فعلًا."},{s:0,t:"Hah! Short and confident. I like it. What if we offered you the job but at a lower level?",ar:"ها! قصيرة وواثقة. يعجبني ذلك. ماذا لو عرضنا عليك الوظيفة لكن بمستوى أدنى؟"},{s:1,t:"I'd have to think about it. The proceeds from my side work help, but I won't take a step back in title.",ar:"سيتعين عليّ التفكير في الأمر. عائدات عملي الجانبي تساعد، لكنني لن أقبل التراجع في المسمى الوظيفي."},{s:0,t:"Understood, understood. Look, the recruitment team meets Thursday. You'll hear from us by Friday.",ar:"مفهوم، مفهوم. اسمع، فريق التوظيف يجتمع يوم الخميس. ستسمع منا بحلول الجمعة."},{s:1,t:"I appreciate that. And — sorry, one last thing — when could I enroll in the health plan?",ar:"أقدّر ذلك. وعذرًا، شيء أخير — متى يمكنني التسجيل في خطة التأمين الصحي؟"},{s:0,t:"Day one. And your spouse would be a beneficiary too, if you choose the family plan.",ar:"من اليوم الأول. وسيكون شريكك مستفيدًا أيضًا إذا اخترت الخطة العائلية."},{s:1,t:"Perfect. Thanks for your time — and for the tough questions. I mean it.",ar:"ممتاز. شكرًا على وقتك — وعلى الأسئلة الصعبة. أعني ذلك."},{s:0,t:"Anytime. Oh — and don't sweat the rejection stories. Everybody's got one.",ar:"في أي وقت. أوه — ولا تقلق بشأن قصص الرفض. لكل شخص قصة منها."},{s:1,t:"Ha! Yeah, rejection builds character, right?",ar:"ها! نعم، الرفض يبني الشخصية، أليس كذلك؟"},{s:0,t:"Exactly. We'll be in touch. Have a great day.",ar:"بالضبط. سنكون على تواصل. أتمنى لك يومًا سعيدًا."},{s:1,t:"You too. Fingers crossed!",ar:"وأنت أيضًا. أتمنى أن يحالفني الحظ!"}]}},{stage:12,topic:"american",topicAr:"الحياة الأمريكية والعامية",topicEn:"American Life & Slang",topicDe:"Amerikanisches Leben und Slang",emoji:"🇺🇸",title:"حياة أمريكية يومية",grammar:{id:"en-c1-discourse-markers",title:"Discourse markers",titleAr:"أدوات الربط في الكلام",covers:1},conv:{id:"en-stage12-c1",speakers:["Roommate (رفيق السكن)","Friend (الصديق)"],turns:[{s:0,t:"Dude, you gotta see this — my cousin's band just dropped their debut album.",ar:"يا صاح، يجب أن ترى هذا — فرقة ابن عمي أصدرت للتو ألبومها الأول."},{s:1,t:"No way! The duo from Ohio? I thought they broke up last year.",ar:"مستحيل! الثنائي من أوهايو؟ ظننت أنهما انفصلا العام الماضي."},{s:0,t:"Nah, they got back together. Anyway, they're playing downtown Friday. You in?",ar:"لا، عادا معًا. على أي حال، سيعزفان وسط المدينة يوم الجمعة. هل أنت معنا؟"},{s:1,t:"Yeah, I'm in. But first — did you see the buzz about the new food truck hub?",ar:"نعم، أنا معكم. لكن أولًا — هل رأيت الضجة حول مركز عربات الطعام الجديد؟"},{s:0,t:"The one by the river? I went yesterday. The tacos were an all-time favorite, man.",ar:"الذي بجانب النهر؟ ذهبت أمس. التاكو كان من الأطباق المفضلة على الإطلاق يا رجل."},{s:1,t:"Tacos again? You eat those like three times a week.",ar:"تاكو مجددًا؟ تأكله ثلاث مرات في الأسبوع تقريبًا."},{s:0,t:"Hey, don't judge. My gut says tacos are a blessing, not a problem.",ar:"مهلًا، لا تحكم عليّ. حدسي يقول إن التاكو نعمة، وليست مشكلة."},{s:1,t:"Ha! Your gut's gonna get you in trouble one day. So, how's the new job going?",ar:"ها! حدسك سيوقعك في مشكلة يومًا ما. إذن، كيف تسير وظيفتك الجديدة؟"},{s:0,t:"Honestly? It's a grind. My boss is a total beast — in a good way, though. She pushes everybody.",ar:"بصراحة؟ إنه عمل شاق. مديرتي وحش حقيقي — بالمعنى الجيد، مع ذلك. إنها تدفع الجميع."},{s:1,t:"That's actually kind of terrific. Better than a boss who doesn't care at all.",ar:"هذا رائع فعلًا. أفضل من مدير لا يهتم إطلاقًا."},{s:0,t:"True. And the team's chill, which helps. We're a hybrid crew — half in the office, half remote.",ar:"صحيح. والفريق هادئ، وهذا يساعد. نحن فريق هجين — نصفه في المكتب ونصفه عن بُعد."},{s:1,t:"Nice. Speaking of chill, did you hear about my old coworker? He finally quit his job to travel.",ar:"جميل. وبمناسبة الهدوء، هل سمعت عن زميلي القديم في العمل؟ استقال أخيرًا من وظيفته ليسافر."},{s:0,t:"Wait, seriously? That guy's been talking about—",ar:"انتظر، بجد؟ هذا الرجل يتحدث عن—"},{s:1,t:"—Yeah, forever. Longtime dream of his — he's on some quest to visit every national park.",ar:"—نعم، منذ زمن طويل. حلم قديم له — إنه في مهمة لزيارة كل المنتزهات الوطنية."},{s:0,t:"Man, I respect that. Meanwhile I'm just trying to survive my sophomore year of grad school.",ar:"يا رجل، أحترم ذلك. بينما أنا أحاول فقط النجاة في سنتي الثانية من الدراسات العليا."},{s:1,t:"Oh, come on. You're killing it. Your professor even called your paper magnetic or something.",ar:"أوه، هيّا. أنت تتألق. حتى أن أستاذك وصف ورقتك بأنها جذابة أو شيء من هذا القبيل."},{s:0,t:"He said my argument had a magnetic pull, yeah. I was delighted, not gonna lie.",ar:"قال إن حجتي ذات جاذبية مغناطيسية، نعم. كنت مسرورًا، ولن أكذب."},{s:1,t:"See? Ego check — you're way smarter than you admit.",ar:"أرأيت؟ كفّ عن التقليل من نفسك — أنت أذكى بكثير مما تعترف."},{s:0,t:"Okay, okay. Enough about me. What's up with you and your date from last week? You two still hanging out?",ar:"حسنًا، حسنًا. كفى عني. ما أخبارك أنت وموعدك من الأسبوع الماضي؟ هل ما زلتما تخرجان معًا؟"},{s:1,t:"Uh-huh. We went to that cocktail bar last night — the one with the rooftop.",ar:"نعم. ذهبنا إلى حانة الكوكتيل تلك الليلة الماضية — التي لها تراس على السطح."},{s:0,t:"Ooh, fancy! Did she like it?",ar:"أوه، فاخر! هل أعجبها؟"},{s:1,t:"She loved it. The view was vibrant — all those city lights — and the music was just right.",ar:"أحبته. كان المنظر نابضًا بالحياة — كل أضواء المدينة تلك — وكانت الموسيقى مناسبة تمامًا."},{s:0,t:"Nice. So are you two, like, official now?",ar:"جميل. إذن هل أنتما رسميان الآن؟"},{s:1,t:"I mean... we're getting there. I'm hopeful, let's put it that way.",ar:"أعني... نحن نقترب. أنا متفائل، لنقلها بهذه الطريقة."},{s:0,t:"Ha! Look at you, all hopeful and stuff. What changed your mindset?",ar:"ها! انظر إليك، متفائل وكل شيء. ما الذي غيّر عقليتك؟"},{s:1,t:"I dunno, man. She just... she's got this charm, you know? Makes everything feel easy.",ar:"لا أعرف يا رجل. هي فقط... لديها هذا السحر، تعرف؟ تجعل كل شيء يبدو سهلًا."},{s:0,t:"Aww. That's sweet. And bizarre — I never thought I'd hear you say that.",ar:"آه. هذا لطيف. وغريب — لم أظن أبدًا أنني سأسمعك تقول ذلك."},{s:1,t:"Shut up. Anyway, what are you wearing to the game Saturday?",ar:"اصمت. على أي حال، ماذا سترتدي لمباراة السبت؟"},{s:0,t:"Probably my old jersey. The new apparel at the team store is way too pricey.",ar:"غالبًا قميصي القديم. الملابس الجديدة في متجر الفريق غالية جدًا."},{s:1,t:"Yeah, forty bucks for a T-shirt is nonsense. But hey, the rookie's supposed to be amazing.",ar:"نعم، أربعون دولارًا لقميص قطني هراء. لكن مهلًا، يُفترض أن اللاعب الجديد مذهل."},{s:0,t:"The rookie? He scored twenty points in his first game. Notably, nobody expected that.",ar:"اللاعب الجديد؟ سجّل عشرين نقطة في مباراته الأولى. والجدير بالذكر أن أحدًا لم يتوقع ذلك."},{s:1,t:"For real? Okay, now I'm pumped. What time's tip-off?",ar:"حقًا؟ حسنًا، الآن أنا متحمس. متى تبدأ المباراة؟"},{s:0,t:"Seven. But we should get there early — traffic by the arena is a nightmare, and parking's a mess.",ar:"السابعة. لكن يجب أن نصل مبكرًا — حركة المرور قرب الملعب كابوس، والمواقف فوضى."},{s:1,t:"True. Let's take the auto train? No wait — I mean the subway. My brain's fried.",ar:"صحيح. لنأخذ القطار الآلي؟ لا انتظر — أعني المترو. عقلي منهك."},{s:0,t:"Ha! Yeah, subway it is. And after the game, we bow out early — I've got an early shift.",ar:"ها! نعم، المترو إذن. وبعد المباراة، ننسحب مبكرًا — لدي وردية مبكرة."},{s:1,t:"Deal. Oh — and my outlook for the season? We're going all the way this year.",ar:"اتفقنا. أوه — وتوقعاتي للموسم؟ سنصل إلى النهاية هذا العام."},{s:0,t:"You say that every year, man.",ar:"تقول ذلك كل عام يا رجل."},{s:1,t:"And every year I'm right eventually. Just wait — peak season's coming.",ar:"وفي كل عام أكون على حق في النهاية. فقط انتظر — ذروة الموسم قادمة."},{s:0,t:"Uh-huh. Sure. Let's grab food first, I'm starving.",ar:"نعم. بالتأكيد. لنتعشَ أولًا، أنا جائع جدًا."},{s:1,t:"Ha! And that taco truck guy? A true creator — he crowns every plate like it's art.",ar:"ها! وصاحب عربة التاكو؟ مبدع حقيقي — يقدّم كل طبق كأنه تحفة فنية كأنه فن."},{s:0,t:"That song always evokes senior year for me — problematic nostalgia, honestly.",ar:"تلك الأغنية تستحضر دائمًا السنة الأخيرة بالنسبة لي — حنين إشكالي، بصراحة."}]}},{stage:13,topic:"media",topicAr:"وسائل الإعلام والأخبار",topicEn:"Media & News",topicDe:"Medien und Nachrichten",emoji:"📺",title:"بودكاست عن الأخبار والإعلام",grammar:{id:"en-c1-cleft-sentences",title:"Cleft sentences",titleAr:"الجمل المنقسمة",covers:1},conv:{id:"en-stage13-c1",speakers:["Podcast Host (مقدِّم البودكاست)","Guest (الضيف)"],turns:[{s:0,t:"Welcome back, folks. Today we're digging into the week's wildest headlines — and trust me, it's a lot.",ar:"مرحبًا بعودتكم يا أصدقاء. اليوم نتعمق في أغرب عناوين الأسبوع — وصدقوني، إنها كثيرة."},{s:1,t:"Thanks for having me. Honestly, I barely keep up anymore — my browser has like forty tabs open right now.",ar:"شكرًا لاستضافتك. بصراحة، بالكاد أتابع بعد الآن — متصفحي فيه نحو أربعين علامة تبويب مفتوحة الآن."},{s:0,t:"Ha! Same. Okay, first story: the congressional hearing yesterday. What a clash that was.",ar:"ها! وأنا كذلك. حسنًا، القصة الأولى: جلسة الكونغرس أمس. يا له من صدام كان."},{s:1,t:"Oh yeah. It wasn't a debate, it was a straight-up confrontation — shouting, interruptions, the whole thing.",ar:"أوه نعم. لم تكن مناظرة، بل مواجهة صريحة — صراخ ومقاطعات وكل شيء."},{s:0,t:"And what struck me was the discourse afterward. Everybody online picked a side in like five minutes.",ar:"وما لفتني هو الخطاب بعد ذلك. اختار الجميع على الإنترنت طرفًا في خمس دقائق تقريبًا."},{s:1,t:"That's the thing — it's not what happened that matters now, it's how it's portrayed.",ar:"هذه هي المشكلة — ليس ما حدث هو المهم الآن، بل كيف يُصوَّر."},{s:0,t:"Exactly. One clip goes viral and suddenly that's the whole story. The commentary writes itself.",ar:"بالضبط. مقطع واحد ينتشر وفجأة يصبح هو القصة كاملة. والتعليق يكتب نفسه."},{s:1,t:"Right. And the contention at the center — the new bill — barely got explained at all.",ar:"صحيح. والنزاع في المركز — مشروع القانون الجديد — بالكاد تم شرحه على الإطلاق."},{s:0,t:"Let's break it down then. The bill would expand abortion access in three states. Huge stakes.",ar:"لنشرحه إذن. مشروع القانون سيوسّع إمكانية الحصول على الإجهاض في ثلاث ولايات. رهانات ضخمة."},{s:1,t:"Undoubtedly huge. And both sides are digging in — neither one's gonna budge an inch.",ar:"ضخمة بلا شك. وكلا الطرفين متمسكان بموقفهما — ولن يتراجع أي منهما قيد أنملة."},{s:0,t:"Yeah. Now, second story — the kidnap trial. Did you follow it?",ar:"نعم. الآن، القصة الثانية — محاكمة الاختطاف. هل تابعتها؟"},{s:1,t:"I did. The guy's facing felony charges, and the prosecutors wanna put him away for decades.",ar:"تابعتها. الرجل يواجه اتهامات جنائية، والمدعون يريدون سجنه لعقود."},{s:0,t:"And they'll probably prosecute the accomplice too, right?",ar:"ومن المحتمل أن يحاكموا الشريك أيضًا، أليس كذلك؟"},{s:1,t:"That's what the reporting suggests. What gets me is how the coverage renders him — like a movie villain.",ar:"هذا ما تشير إليه التقارير. ما يزعجني هو كيف تصوّره التغطية — كشرير في فيلم."},{s:0,t:"Versus the victim, who barely gets mentioned. That imbalance drives me crazy.",ar:"مقابل الضحية، الذي بالكاد يُذكر. هذا الخلل يجنّني."},{s:1,t:"Same here. Okay — lighter topic? The spy movie that just came out?",ar:"وأنا كذلك. حسنًا — موضوع أخف؟ فيلم الجاسوسية الذي صدر للتو؟"},{s:0,t:"Oh, I saw it! The combat scenes were wild, but the plot was a mess. Still fun, though.",ar:"أوه، شاهدته! مشاهد القتال كانت جنونية، لكن الحبكة كانت فوضوية. ما زال ممتعًا، مع ذلك."},{s:1,t:"Ha! Critics were vicious about it. One review called it a scam on moviegoers.",ar:"ها! كان النقاد شرسين بشأنه. وصفت إحدى المراجعات الفيلم بأنه خدعة لرواد السينما."},{s:0,t:"A scam? Come on. It's a popcorn movie — nobody presumes it's art.",ar:"خدعة؟ هيّا. إنه فيلم تسلية — لا أحد يفترض أنه فن."},{s:1,t:"True. Speaking of presuming — the presidency race. Who's your pick so far?",ar:"صحيح. وبمناسبة الافتراض — سباق الرئاسة. من هو اختيارك حتى الآن؟"},{s:0,t:"Ugh, don't get me started. The socialist candidate and the communist label fight — it's exhausting.",ar:"أوه، لا تجعلني أبدأ. المرشح الاشتراكي ومعركة وصفه بالشيوعي — إنه أمر مرهق."},{s:1,t:"Yeah, every election it's the same labels. Meanwhile, the lobby groups are spending millions behind the scenes.",ar:"نعم، في كل انتخابات نفس التسميات. وفي الوقت نفسه، تنفق جماعات الضغط الملايين خلف الكواليس."},{s:0,t:"Millions of taxpayer dollars in ads alone. And what do voters actually get? A newsletter and a slogan.",ar:"ملايين من أموال دافعي الضرائب في الإعلانات وحدها. وماذا يحصل الناخبون فعلًا؟ نشرة بريدية وشعار."},{s:1,t:"Don't forget the firearm debate — that flares up every single cycle.",ar:"لا تنسَ نقاش الأسلحة النارية — إنه يشتعل في كل دورة انتخابية."},{s:0,t:"Right, the rifle laws. Rural versus urban — it's like two different countries on that one.",ar:"صحيح، قوانين البنادق. الريف مقابل المدينة — كأنهما بلدان مختلفان في هذا الموضوع."},{s:1,t:"And the precedent set by the last court ruling? Nobody even talks about it now.",ar:"والسابقة التي وضعها حكم المحكمة الأخير؟ لا أحد يتحدث عنها الآن."},{s:0,t:"Because outrage moves faster than law. Hey — quick break? We've got subscribers waiting on the Q&A.",ar:"لأن الغضب يتحرك أسرع من القانون. مهلًا — استراحة سريعة؟ لدينا مشتركون ينتظرون فقرة الأسئلة."},{s:1,t:"Sure. But one more thing — the rape trial coverage. That was handled terribly, in my opinion.",ar:"بالتأكيد. لكن شيء أخير — تغطية محاكمة الاغتصاب. تم التعامل معها بشكل سيئ للغاية، في رأيي."},{s:0,t:"I agree. Too much detail, too little respect for representation of the survivor's side.",ar:"أوافق. تفاصيل كثيرة جدًا، واحترام قليل جدًا لتمثيل جانب الناجية."},{s:1,t:"Exactly. It's what the victim advocates have been saying for years — incarcerate the offender, protect the survivor.",ar:"بالضبط. هذا ما يقوله المدافعون عن الضحايا منذ سنوات — اسجنوا الجاني، واحموا الناجية."},{s:0,t:"Well said. Okay, let's take that break. When we're back: your questions, live.",ar:"أحسنت القول. حسنًا، لنأخذ تلك الاستراحة. وعندما نعود: أسئلتكم، مباشرة."},{s:1,t:"Sounds good. And folks — hit subscribe, seriously, it keeps the lights on.",ar:"يبدو جيدًا. وأيها الأصدقاء — اضغطوا زر الاشتراك، بجدية، فهو ما يبقي الأضواء مضاءة."},{s:0,t:"Ha! Smooth. We'll be right back.",ar:"ها! بسلاسة. سنعود فورًا."},{s:1,t:"One more headline — the inmate who escaped last month got caught. The whole town's relieved.",ar:"عنوان آخر — السجين الذي هرب الشهر الماضي تم القبض عليه. البلدة كلها مرتاحة."},{s:0,t:"Yeah, I saw that. The coverage was explosive — every channel ran the same imagery for days.",ar:"نعم، رأيت ذلك. كانت التغطية متفجرة — كل قناة عرضت الصور نفسها لأيام."},{s:1,t:"And the spin afterward? Every outlet tried to twist the story to fit its own angle.",ar:"والتلاعب بعد ذلك؟ حاولت كل وسيلة أن تحرّف القصة لتناسب زاويتها."},{s:0,t:"Classic. Meanwhile, the stimulus bill — economists say it'll facilitate growth, but who knows.",ar:"كلاسيكي. وفي الوقت نفسه، مشروع قانون التحفيز — يقول الاقتصاديون إنه سيسهّل النمو، لكن من يعلم."},{s:1,t:"Right. And the school board trustee vowed to uphold the new rules, no matter the backlash.",ar:"صحيح. وتعهد أمين مجلس المدرسة بالتمسك بالقواعد الجديدة مهما كانت ردة الفعل."},{s:0,t:"Swing voters, man — they decide everything in the end. Presumed losers win all the time.",ar:"الناخبون المتأرجحون يا رجل — إنهم يقررون كل شيء في النهاية. الخاسرون المفترضون يفوزون طوال الوقت."},{s:1,t:"Ha! True. Okay, that's a wrap for today — same time next week?",ar:"ها! صحيح. حسنًا، هذا ختام اليوم — في نفس الوقت الأسبوع القادم؟"}]}},{stage:14,topic:"social",topicAr:"المواقف الاجتماعية",topicEn:"Social Situations",topicDe:"Soziale Situationen",emoji:"🤝",title:"أحاديث الأصدقاء العميقة",grammar:{id:"en-c1-hedging-stance",title:"Hedging",titleAr:"التخفيف والتردد",covers:1},conv:{id:"en-stage14-c1",speakers:["Best Friend (أفضل صديق)","Friend (الصديق)"],turns:[{s:0,t:"Okay, spill it. You've been weird all week. What's going on?",ar:"حسنًا، اعترف. كنت غريبًا طوال الأسبوع. ما الذي يحدث؟"},{s:1,t:"Ugh. It's kind of a mess. My engagement is... I dunno, man. I'm having doubts.",ar:"أوه. إنه نوع من الفوضى. خطوبتي... لا أعرف يا رجل. تراودني شكوك."},{s:0,t:"Whoa, whoa. Doubts? You two seemed so solid last month.",ar:"مهلًا، مهلًا. شكوك؟ بدوتما متماسكين جدًا الشهر الماضي."},{s:1,t:"Yeah, I know. But lately every little thing turns into a fight. It's utterly exhausting.",ar:"نعم، أعرف. لكن مؤخرًا كل شيء صغير يتحول إلى شجار. إنه مرهق تمامًا."},{s:0,t:"Like what? Give me an example.",ar:"مثل ماذا؟ أعطني مثالًا."},{s:1,t:"Okay, so — her parents wanna cater the wedding themselves, right? And my mom freaked out.",ar:"حسنًا، إذن — والداها يريدان تجهيز حفل الزفاف بنفسهما، صحيح؟ وجنّت أمي."},{s:0,t:"Oh no. The wedding planning chaos begins.",ar:"أوه لا. تبدأ فوضى التخطيط لحفل الزفاف."},{s:1,t:"Exactly. And my mom's like, it's our family tradition, and her mom's like, no way, we do it our way.",ar:"بالضبط. وأمي تقول إنها تقاليد عائلتنا، وأمها تقول لا، نفعلها بطريقتنا."},{s:0,t:"Classic. But that's not a reason to call it off, is it?",ar:"كلاسيكي. لكن هذا ليس سببًا لإلغائه، أليس كذلك؟"},{s:1,t:"I mean, sort of. It's not just the wedding. It's like we can't conceive of a future where both families chill.",ar:"أعني، نوعًا ما. الأمر ليس الزفاف فقط. يبدو أننا لا نستطيع تصور مستقبل تهدأ فيه العائلتان."},{s:0,t:"Hmm. That sounds bigger than catering. What's the real issue here?",ar:"همم. يبدو هذا أكبر من تجهيز الطعام. ما المشكلة الحقيقية هنا؟"},{s:1,t:"I think... I think we got engaged too fast. The proposal felt glorious in the moment, you know?",ar:"أعتقد... أعتقد أننا خطبنا بسرعة كبيرة. بدا عرض الزواج رائعًا في تلك اللحظة، تعرف؟"},{s:0,t:"Yeah, the rooftop, the ring, the whole thing. I remember.",ar:"نعم، السطح، والخاتم، وكل شيء. أتذكر."},{s:1,t:"Right. But a proposal isn't a marriage. And now the pressure's heightening every single day.",ar:"صحيح. لكن عرض الزواج ليس زواجًا. والآن الضغط يزداد كل يوم."},{s:0,t:"Okay, I'm gonna be straight with you — is there someone else?",ar:"حسنًا، سأكون صريحًا معك — هل هناك شخص آخر؟"},{s:1,t:"No! No, it's not that. It's not revenge or—",ar:"لا! لا، ليس ذلك. ليس انتقامًا أو—"},{s:0,t:"—Okay, okay. Confined? By her, or by the whole situation?",ar:"—حسنًا، حسنًا. محصور؟ بها، أم بالوضع كله؟"},{s:1,t:"By the situation, mostly. The guest list, the venue, the money — it's an excess of everything.",ar:"بالوضع غالبًا. قائمة الضيوف، والمكان، والمال — إنه إفراط في كل شيء."},{s:0,t:"So maybe the problem isn't her. Maybe it's the wedding machine.",ar:"إذن ربما المشكلة ليست هي. ربما آلة الزفاف."},{s:1,t:"Maybe. I mean, when it's just us two, it's still good. She still makes me laugh.",ar:"ربما. أعني، عندما نكون نحن الاثنين فقط، ما زال الأمر جيدًا. ما زالت تضحكني."},{s:0,t:"That's a pretty big hint, don't you think? The relationship's fine — the circus around it isn't.",ar:"هذا تلميح كبير جدًا، ألا تعتقد؟ العلاقة بخير — السيرك حولها ليس كذلك."},{s:1,t:"Yeah... you're probably right. I just hate disappointing people.",ar:"نعم... ربما أنت على حق. أكره فقط خيبة أمل الناس."},{s:0,t:"Look, man. Your spouse for life — that's a decisive choice. Not a party plan.",ar:"اسمع يا رجل. زوجتك مدى الحياة — هذا خيار حاسم. وليس خطة حفلة."},{s:1,t:"When you put it that way... yeah. I need to talk to her. Like, really talk.",ar:"عندما تضعها بهذه الطريقة... نعم. أحتاج إلى التحدث معها. أعني، التحدث حقًا."},{s:0,t:"Do it tonight. Don't let it fester. And hey — don't bring your mom into it this time.",ar:"افعل ذلك الليلة. لا تدعه يتفاقم. ومهلًا — لا تُدخل أمك في الأمر هذه المرة."},{s:1,t:"Ha! Fair. Oh man, what a night. Wanna grab a beer and just chill for a bit?",ar:"ها! عادل. يا رجل، يا لها من ليلة. هل تريد أن نشرب بيرة ونهدأ قليلًا؟"},{s:0,t:"Sure. But first — tell me about the burial thing. Your grandpa's service is Saturday, right?",ar:"بالتأكيد. لكن أولًا — أخبرني عن موضوع الدفن. جنازة جدك يوم السبت، صحيح؟"},{s:1,t:"Yeah, Saturday morning. It's gonna be rough. He was like a second dad to me.",ar:"نعم، صباح السبت. سيكون صعبًا. كان مثل أب ثانٍ لي."},{s:0,t:"I'm so sorry, man. I'll be there. And I'll bring food — my mom's already cooking.",ar:"أنا آسف جدًا يا رجل. سأكون هناك. وسأحضر طعامًا — أمي تطبخ بالفعل."},{s:1,t:"Thanks. That means a lot. Honestly, grief is just... it creeps up on you at weird moments.",ar:"شكرًا. هذا يعني الكثير. بصراحة، الحزن فقط... يتسلل إليك في لحظات غريبة."},{s:0,t:"I know. When my uncle passed, I couldn't even hear his favorite song without losing it.",ar:"أعرف. عندما توفي عمي، لم أستطع حتى سماع أغنيته المفضلة دون أن أنهار."},{s:1,t:"Yeah. Hey, can I ask you something kinda vague and weird?",ar:"نعم. مهلًا، هل يمكنني أن أسألك شيئًا غامضًا وغريبًا نوعًا ما؟"},{s:0,t:"Shoot.",ar:"تفضل."},{s:1,t:"Do you ever feel like our whole friend group is drifting? Like, everyone's coupled up now?",ar:"هل تشعر أحيانًا أن مجموعة أصدقائنا كلها تتباعد؟ مثل، الجميع مرتبط الآن؟"},{s:0,t:"Uh-huh, I feel it. But look — we're still here, right? Two guys, one booth, zero plans.",ar:"نعم، أشعر بذلك. لكن انظر — ما زلنا هنا، صحيح؟ رجلان، طاولة واحدة، ولا خطط."},{s:1,t:"Ha! True. Okay, here's my vow: no more secrets between us. Deal?",ar:"ها! صحيح. حسنًا، هذا وعدي: لا مزيد من الأسرار بيننا. اتفقنا؟"},{s:0,t:"Deal. Now let's get out of here before I start crying into my fries.",ar:"اتفقنا. الآن لنخرج من هنا قبل أن أبدأ بالبكاء على بطاطسي."},{s:1,t:"Too late for me, man. Too late.",ar:"فات الأوان بالنسبة لي يا رجل. فات الأوان."},{s:0,t:"Come here, you big softie.",ar:"تعال هنا، أيها العاطفي الكبير."},{s:1,t:"Shut up and hug me already.",ar:"اصمت وعانقني بالفعل."},{s:0,t:"Wait — before we go, I gotta ask. Do you ever invoke your grandma's advice when things get hard?",ar:"انتظر — قبل أن نذهب، يجب أن أسأل. هل تستحضر نصيحة جدتك عندما تصعب الأمور؟"},{s:1,t:"All the time. She'd say, indulge the good days, don't just survive them. That was her inspiration, I think.",ar:"طوال الوقت. كانت تقول: استمتع بالأيام الجيدة، ولا تكتفِ بتجاوزها. كان ذلك مصدر إلهامها، أعتقد."},{s:0,t:"Beautiful. And the wedding — the forthcoming one, I mean — is it gonna be exclusive, or open to everyone?",ar:"جميل. والزفاف — القادم، أعني — هل سيكون حصريًا أم مفتوحًا للجميع؟"},{s:1,t:"Solely family, I think. The stakes are high enough without a hundred guests judging the food.",ar:"العائلة فقط، أعتقد. الرهانات عالية بما فيه الكفاية دون مئة ضيف يحكمون على الطعام."},{s:0,t:"No hatred, no drama — just us. That's the whole plan.",ar:"لا كراهية ولا دراما — نحن فقط. هذه هي الخطة كلها."}]}},{stage:15,topic:"travel",topicAr:"السفر والمواصلات",topicEn:"Travel & Transport",topicDe:"Reisen und Verkehr",emoji:"✈️",title:"رحلة برية عبر البلاد",grammar:{id:"en-c1-ellipsis-substitution",title:"Ellipsis and substitution",titleAr:"الحذف والاستبدال (Ellipsis & substitution)",covers:1},conv:{id:"en-stage15-c1",speakers:["Traveler (المسافر)","Friend (الصديق)"],turns:[{s:0,t:"Okay, so the road trip. Three days, two thousand miles, one very old car. What could go wrong?",ar:"حسنًا، إذن الرحلة البرية. ثلاثة أيام، ألفا ميل، وسيارة قديمة جدًا. ما الذي يمكن أن يحدث خطأ؟"},{s:1,t:"Ha! Famous last words. You should've checked the car first — you could've avoided the whole mess.",ar:"ها! كلمات أخيرة مشهورة. كان يجب أن تفحص السيارة أولًا — كان بإمكانك تجنب كل هذه الفوضى."},{s:0,t:"I know, I know. Day one, the AC died in the middle of the desert. It was disastrous.",ar:"أعرف، أعرف. في اليوم الأول، تعطّل التكييف في وسط الصحراء. كان كارثيًا."},{s:1,t:"In the desert? Oh man, you must've been melting.",ar:"في الصحراء؟ يا رجل، لا بد أنك كنت تذوب."},{s:0,t:"We were. And the GPS kept rerouting us through these tiny towns with one gas station each.",ar:"كنا كذلك. وكان نظام تحديد المواقع يعيد توجيهنا عبر بلدات صغيرة فيها محطة وقود واحدة لكل منها."},{s:1,t:"That's actually kind of charming, though. Did you stop anywhere good?",ar:"هذا ساحر نوعًا ما، مع ذلك. هل توقفت في أي مكان جيد؟"},{s:0,t:"Yeah! We found this diner run by an indigenous family — third generation. The food was unreal.",ar:"نعم! وجدنا مطعمًا تديره عائلة من السكان الأصليين — الجيل الثالث. كان الطعام لا يصدق."},{s:1,t:"Nice. See, that's the stuff you never get on a plane. Planes just deprive you of the whole journey.",ar:"جميل. أرأيت، هذه الأشياء التي لا تحصل عليها أبدًا في الطائرة. الطائرات تحرمك فقط من الرحلة كلها."},{s:0,t:"We were. And the tire blew out on day two as well — the spare deteriorated fast.",ar:"كنا كذلك. وانفجر الإطار في اليوم الثاني أيضًا — تدهور الإطار الاحتياطي بسرعة."},{s:1,t:"You should've rented a car. I told you that, didn't I?",ar:"كان يجب أن تستأجر سيارة. أخبرتك بذلك، أليس كذلك؟"},{s:0,t:"You did. I just didn't listen. Anyway, we limped into a town with a dual highway and one mechanic.",ar:"فعلت. لكنني لم أستمع. على أي حال، وصلنا بصعوبة إلى بلدة فيها طريق مزدوج وميكانيكي واحد."},{s:1,t:"One mechanic? That's a monopoly. How much did he charge you?",ar:"ميكانيكي واحد؟ هذا احتكار. كم تقاضى منك؟"},{s:0,t:"Two hundred bucks. But hey, he was liable for the work, gave us a warranty and everything.",ar:"مئتا دولار. لكن مهلًا، كان مسؤولًا عن العمل، وأعطانا ضمانًا وكل شيء."},{s:1,t:"Two hundred's not bad, honestly. So what'd you do while you waited?",ar:"مئتان ليست سيئة بصراحة. إذن ماذا فعلت أثناء الانتظار؟"},{s:0,t:"We walked around. The town had this ecological farm tour — solar panels, rainwater tanks, the works.",ar:"تجولنا. كان في البلدة جولة في مزرعة بيئية — ألواح شمسية، وخزانات مياه أمطار، وكل شيء."},{s:1,t:"Oh cool, I love that stuff. Was it interactive, or just a boring walk?",ar:"أوه رائع، أحب هذه الأشياء. هل كانت تفاعلية، أم مجرد جولة مملة؟"},{s:0,t:"Super interactive. You could pick vegetables, feed the goats — my girlfriend loved it.",ar:"تفاعلية جدًا. كان بإمكانك قطف الخضروات وإطعام الماعز — أحبت صديقتي ذلك."},{s:1,t:"Okay, that's adorable. Did you learn anything, or just pet goats all day?",ar:"حسنًا، هذا لطيف. هل تعلمت شيئًا، أم دلّلت الماعز طوال اليوم؟"},{s:0,t:"I learned that my inability to tell a goat from a sheep is a real deficiency.",ar:"تعلمت أن عجزي عن التمييز بين الماعز والخروف نقص حقيقي."},{s:1,t:"Ha! That's not a deficiency, that's just city life. So, day three?",ar:"ها! هذا ليس نقصًا، إنها حياة المدينة فقط. إذن، اليوم الثالث؟"},{s:0,t:"Day three was smooth — until the flight home got canceled. Total disruption at the airport.",ar:"كان اليوم الثالث سلسًا — حتى أُلغيت رحلة العودة. فوضى عارمة في المطار."},{s:1,t:"Ugh, the worst. What'd you do, sleep on the floor?",ar:"أوه، الأسوأ. ماذا فعلت، نمت على الأرض؟"},{s:0,t:"Almost. We got the last two seats on a later flight, but we had to dispose of half our luggage to make weight.",ar:"تقريبًا. حصلنا على آخر مقعدين في رحلة لاحقة، لكن اضطررنا للتخلص من نصف أمتعتنا لتخفيف الوزن."},{s:1,t:"You threw stuff away? What kind of stuff?",ar:"رميت أشياء؟ أي نوع من الأشياء؟"},{s:0,t:"Mostly generic souvenirs — keychains, magnets, that kind of junk. Nothing that mattered.",ar:"غالبًا تذكارات عامة — سلاسل مفاتيح ومغناطيسات، هذا النوع من الخردة. لا شيء مهم."},{s:1,t:"Good call. So, would you do it again?",ar:"قرار جيد. إذن، هل ستفعلها مجددًا؟"},{s:0,t:"In a heartbeat. The trip encompassed everything — good food, weird towns, total chaos.",ar:"في غمضة عين. شملت الرحلة كل شيء — طعام جيد، وبلدات غريبة، وفوضى كاملة."},{s:1,t:"Ha! You're such a romantic. What about the car, though — is it still alive?",ar:"ها! أنت رومانسي جدًا. وماذا عن السيارة، مع ذلك — هل ما زالت حية؟"},{s:0,t:"Barely. The mechanic said the engine's got a functional problem that'll cost more than the car's worth.",ar:"بالكاد. قال الميكانيكي إن المحرك فيه مشكلة وظيفية ستكلف أكثر من قيمة السيارة."},{s:1,t:"So you're gonna sell it for parts? Or just let it drain your wallet forever?",ar:"إذن ستبيعها كقطع غيار؟ أم ستتركها تستنزف محفظتك إلى الأبد؟"},{s:0,t:"Sell it. I've already formulated a plan — list it online, take the first decent offer.",ar:"سأبيعها. لقد صيغت خطة بالفعل — أعرضها على الإنترنت، وأقبل أول عرض لائق."},{s:1,t:"Smart. And next trip, I'm coming with you. But we're renting, and I'm driving.",ar:"ذكي. وفي الرحلة القادمة، سآتي معك. لكننا سنستأجر، وأنا سأقود."},{s:0,t:"Deal. But fair warning — I'm inclined to take the scenic route every single time.",ar:"اتفقنا. لكن تحذير عادل — أميل إلى اتخاذ الطريق ذي المناظر الخلابة في كل مرة."},{s:1,t:"Fine by me. Scenic routes, weird diners, no schedule. That's the whole point.",ar:"لا بأس لديّ. طرق ذات مناظر، ومطاعم غريبة، ولا جدول. هذه هي الفكرة كلها."},{s:0,t:"Exactly. Oh — one more thing. The motel we stayed at? The layout was so weird, the bathroom was in the kitchen.",ar:"بالضبط. أوه — شيء أخير. النزل الذي أقمنا فيه؟ كان تصميمه غريبًا جدًا، الحمام كان في المطبخ."},{s:1,t:"No way! That's not a motel, that's an experimental art project.",ar:"مستحيل! هذا ليس نزلًا، بل مشروع فني تجريبي."},{s:0,t:"Ha! And the shower had, like, a liter of hot water total. A liter! Then ice cold.",ar:"ها! وكان الدش فيه لتر واحد من الماء الساخن إجمالًا. لتر واحد! ثم بارد كالثلج."},{s:1,t:"Okay, that's genuinely terrible. But the emergence of indoor plumbing was, what, a hundred years ago?",ar:"حسنًا، هذا سيئ حقًا. لكن ظهور السباكة الداخلية كان، ماذا، قبل مئة عام؟"},{s:0,t:"Right? Anyway, the place was cheap, the people were kind, and the stars at night were unreal.",ar:"صحيح؟ على أي حال، كان المكان رخيصًا، والناس لطفاء، والنجوم ليلًا لا تصدق."},{s:1,t:"See, that's the good stuff. The rest is just noise — irrelevant in the end.",ar:"أرأيت، هذه هي الأشياء الجيدة. والباقي مجرد ضجيج — غير مهم في النهاية."},{s:0,t:"Oh, and the rental company? They charged me a default fee for the late return. Total scam.",ar:"أوه، وشركة التأجير؟ فرضت عليّ رسم تأخير للتأخير في الإعادة. خدعة كاملة."},{s:1,t:"Ugh. Those fees are gross. Did you read the fine print at all?",ar:"أوه. تلك الرسوم فظيعة. هل قرأت التفاصيل الدقيقة على الإطلاق؟"},{s:0,t:"Barely. The travel app lets you embed your whole route in one map. Handy, but the company behind it is a shady entity.",ar:"بالكاد. تطبيق السفر يتيح لك تضمين مسارك كله في خريطة واحدة. مفيد، لكن الشركة وراءه كيان مشبوه."},{s:1,t:"Yeah, and the intensive driving messed with my immunity — I caught something infectious on the plane home, I swear.",ar:"نعم، والقيادة المكثفة أفسدت مناعتي — أصبت بشيء معدٍ على متن الطائرة عائدًا، أقسم."},{s:0,t:"Ha! Well, a lesser evil than the desert breakdown. The integrated GPS barely inhibited our wrong turns, though.",ar:"ها! حسنًا، شر أقل من تعطل الصحراء. لكن نظام تحديد المواقع المدمج بالكاد منع انعطافاتنا الخاطئة."},{s:1,t:"True. Next time, I drive the first lap and you navigate. Deal?",ar:"صحيح. في المرة القادمة، أقود اللفة الأولى وأنت توجه. اتفقنا؟"}]}},{stage:16,topic:"health",topicAr:"الصحة والجسم",topicEn:"Health & Body",topicDe:"Gesundheit und Körper",emoji:"🩺",title:"في عيادة الطبيب",grammar:{id:"en-c1-hedging-stance",title:"Hedging and stance",titleAr:"التحفظ والتعبير عن الموقف (Hedging)",covers:1},conv:{id:"en-stage16-c1",speakers:["Doctor (الطبيب)","Patient (المريض)"],turns:[{s:0,t:"Good morning. So, what brings you in today?",ar:"صباح الخير. إذن، ما الذي جاء بك اليوم؟"},{s:1,t:"Honestly, doc, I've been feeling wiped out for weeks. My appetite's gone, my sleep's a mess.",ar:"بصراحة يا دكتور، أشعر بالإرهاق منذ أسابيع. شهيتي اختفت، ونومي فوضى."},{s:0,t:"Okay, let's dig in. When did it start? Any particular trigger?",ar:"حسنًا، لنتعمق. متى بدأ ذلك؟ هل هناك محفز معين؟"},{s:1,t:"Around the time I started the night shift. My whole routine got flipped upside down.",ar:"في وقت بدء وردية الليل. انقلب روتيني كله رأسًا على عقب."},{s:0,t:"Night shifts are brutal on the body. Are you eating regularly at least?",ar:"ورديات الليل قاسية على الجسم. هل تأكل بانتظام على الأقل؟"},{s:1,t:"Not really. I skip meals, then binge at 3 a.m. My stomach's in a constant state of protest.",ar:"ليس حقًا. أتخطى الوجبات، ثم أفرط في الأكل في الثالثة فجرًا. معدتي في حالة احتجاج مستمر."},{s:0,t:"That'll do it. Your blood sugar's probably on a roller coaster. Let's check your labs — they're substantially overdue.",ar:"هذا يفسر الأمر. سكر دمك على الأرجح في تقلبات مستمرة. لنفحص تحاليلك — إنها متأخرة جدًا."},{s:1,t:"Yeah, I figured. Is it bad? Like, how bad are we talking?",ar:"نعم، توقعت ذلك. هل الأمر سيئ؟ أعني، كم هو سيئ؟"},{s:0,t:"Let's not panic before the results. But I will say this — your circulation numbers were borderline last time.",ar:"دعنا لا نذعر قبل النتائج. لكن سأقول هذا — أرقام دورتك الدموية كانت على الحدود في المرة الأخيرة."},{s:1,t:"Borderline? Ugh. My dad had circulation issues too. It's kind of a family thing.",ar:"على الحدود؟ أوه. كان والدي يعاني من مشاكل في الدورة الدموية أيضًا. إنها نوعًا ما مشكلة عائلية."},{s:0,t:"I see. And the smoking — are you still on tobacco?",ar:"أرى. والتدخين — هل ما زلت تتعاطى التبغ؟"},{s:1,t:"Yeah... a pack a day. I know, I know. I've tried to quit like five times.",ar:"نعم... علبة في اليوم. أعرف، أعرف. حاولت الإقلاع نحو خمس مرات."},{s:0,t:"Five attempts is five more than most people manage. Quitting is a process, not a single decision.",ar:"خمس محاولات أكثر بخمس مما ينجح فيه معظم الناس. الإقلاع عملية، وليس قرارًا واحدًا."},{s:1,t:"That's kind of you to say. My wife's been on my case about it nonstop.",ar:"هذا لطف منك. زوجتي تلاحقني بشأنه بلا توقف."},{s:0,t:"Good — let her. Now, your knee: you mentioned pain when you climb stairs?",ar:"جيد — دعها. الآن، ركبتك: ذكرت ألمًا عند صعود السلالم؟"},{s:1,t:"Yeah, it clicks and aches. And my mobility has gotten worse — I can't even squat anymore.",ar:"نعم، تصدر صوتًا وتؤلم. وتدهورت حركتي — لم أعد أستطيع حتى القرفصاء."},{s:0,t:"We'll get an X-ray. The joint may have some structural wear — pretty common at your age and weight.",ar:"سنأخذ أشعة سينية. قد يكون في المفصل بعض التآكل الهيكلي — شائع جدًا في عمرك ووزنك."},{s:1,t:"Ouch. So what do I do — just stop moving? That sounds worse.",ar:"مؤلم. إذن ماذا أفعل — أتوقف عن الحركة فقط؟ هذا يبدو أسوأ."},{s:0,t:"No, no — the opposite. Gentle movement helps. Swimming, cycling, short walks. No heavy lifting.",ar:"لا، لا — العكس. الحركة اللطيفة تساعد. السباحة وركوب الدراجة والمشي القصير. لا رفع أثقال."},{s:1,t:"What about my workout routine? I lift three times a week.",ar:"وماذا عن روتين تماريني؟ أرفع الأثقال ثلاث مرات في الأسبوع."},{s:0,t:"Keep the upper body, drop the heavy squats for now. And add stretching — your muscle fiber density needs recovery time.",ar:"احتفظ بتمارين الجزء العلوي، وتوقف عن القرفصاء الثقيلة الآن. وأضف تمارين الإطالة — كثافة ألياف عضلاتك تحتاج وقتًا للتعافي."},{s:1,t:"Okay, I can live with that. What about food? Should I take a supplement or something?",ar:"حسنًا، يمكنني العيش مع ذلك. وماذا عن الطعام؟ هل يجب أن آخذ مكملًا أو شيئًا؟"},{s:0,t:"A vitamin D supplement makes sense in winter. But food first — more fiber, less processed stuff, more water.",ar:"مكمل فيتامين د منطقي في الشتاء. لكن الطعام أولًا — ألياف أكثر، وأطعمة معالجة أقل، وماء أكثر."},{s:1,t:"Got it. And the headaches? They hit me like a ray of pain behind my eyes.",ar:"فهمت. والصداع؟ يضربني مثل شعاع ألم خلف عينيّ."},{s:0,t:"That sounds like tension headaches — stress plus bad sleep. Have you tried meditation?",ar:"يبدو ذلك مثل صداع التوتر — إجهاد إضافة إلى نوم سيئ. هل جربت التأمل؟"},{s:1,t:"Meditation? Me? I can't sit still for two minutes, doc.",ar:"التأمل؟ أنا؟ لا أستطيع الجلوس ساكنًا لدقيقتين يا دكتور."},{s:0,t:"Ha! Start with two minutes, then. Even that can shrink your stress response over time.",ar:"ها! ابدأ بدقيقتين إذن. حتى ذلك يمكن أن يقلّص استجابتك للتوتر مع الوقت."},{s:1,t:"Alright, alright, I'll try it. What about the nosebleeds? I bleed a little when I blow my nose hard.",ar:"حسنًا، حسنًا، سأجربه. وماذا عن نزيف الأنف؟ أنزف قليلًا عندما أنفخ أنفي بقوة."},{s:0,t:"Probably dry air plus the night-shift heating. Use saline spray — and don't pick at it.",ar:"على الأرجح هواء جاف إضافة إلى تدفئة وردية الليل. استخدم رذاذًا ملحيًا — ولا تعبث به."},{s:1,t:"Guilty as charged. Okay, last thing — my mom's in a nursery home now, and I worry about her meds.",ar:"مذنب كما تتهمني. حسنًا، شيء أخير — أمي في دار رعاية الآن، وأقلق بشأن أدويتها."},{s:0,t:"That's a lot on your plate. Is her pharmaceutical list being reviewed regularly?",ar:"هذا كثير على عاتقك. هل تُراجَع قائمة أدويتها بانتظام؟"},{s:1,t:"I think so. The nurse there is great — she walks me through the whole pipeline of doses.",ar:"أعتقد ذلك. الممرضة هناك رائعة — تشرح لي خط الإعطاء الكامل للجرعات."},{s:0,t:"Good. Now — one more dimension to all this: your mood. How's your mood been, honestly?",ar:"جيد. الآن — بُعد آخر لكل هذا: مزاجك. كيف كان مزاجك بصراحة؟"},{s:1,t:"Up and down. Some days I'm fine, other days I feel like I'm stuck in a pit.",ar:"متقلب. بعض الأيام أكون بخير، وأيامًا أخرى أشعر بأنني عالق في حفرة."},{s:0,t:"That's worth tracking. Mood, sleep, appetite — the stem of a lot of this is the shift work.",ar:"هذا يستحق التتبع. المزاج والنوم والشهية — جذر الكثير من هذا هو عمل الورديات."},{s:1,t:"Yeah. I mean, the job pays well, but it rips my health apart.",ar:"نعم. أعني، الوظيفة تدفع جيدًا، لكنها تمزّق صحتي."},{s:0,t:"I hear you. Let's run the labs, get the X-ray, and meet again in two weeks. No suspension of anything yet — just adjustments.",ar:"أسمعك. لنجرِ التحاليل، ونأخذ الأشعة، ونلتقي مجددًا خلال أسبوعين. لا تعليق لأي شيء بعد — فقط تعديلات."},{s:1,t:"Thanks, doc. For the first time in a while, I actually feel hopeful about fixing this.",ar:"شكرًا يا دكتور. لأول مرة منذ فترة، أشعر فعلًا بالأمل في إصلاح هذا."},{s:0,t:"That's the spirit. And hey — bring your wife next time. She's part of the team now.",ar:"هذه هي الروح. ومهلًا — أحضر زوجتك في المرة القادمة. إنها جزء من الفريق الآن."},{s:1,t:"Oh, one more thing — the lab needs a specimen from me, right? And can you check the vein in my arm? It looks weird.",ar:"أوه، شيء أخير — المختبر يحتاج عينة مني، صحيح؟ وهل يمكنك فحص الوريد في ذراعي؟ يبدو غريبًا."},{s:0,t:"We'll draw it today. And that texture on your skin — that's just dryness, nothing on the spectrum of concern.",ar:"سنأخذها اليوم. وذلك الملمس على جلدك — مجرد جفاف، لا شيء في نطاق القلق."},{s:1,t:"Good. My goal's to shed a few pounds too — a small stimulus for the new routine, you know?",ar:"جيد. هدفي أن أفقد بضعة أرطال أيضًا — حافز صغير للروتين الجديد، تعرف؟"}]}},{stage:17,topic:"food",topicAr:"الطعام والشراب",topicEn:"Food & Drink",topicDe:"Essen und Trinken",emoji:"🍽️",title:"في مطعم مع ناقد طعام",grammar:{id:"en-c1-participle-perfect-advanced",title:"Participle clauses",titleAr:"جمل اسم الفاعل والمفعول",covers:1},conv:{id:"en-stage17-c1",speakers:["Chef (الطاهي)","Food Critic (ناقد الطعام)"],turns:[{s:0,t:"Welcome to the kitchen. You caught us mid-service — it's chaos back here, but the good kind.",ar:"مرحبًا بك في المطبخ. أدركتنا في وسط الخدمة — إنها فوضى هنا، لكن من النوع الجيد."},{s:1,t:"Ha! I love it. Kitchens are my happy place. So — what's on the menu tonight?",ar:"ها! أحب ذلك. المطابخ هي مكاني المفضل. إذن — ما في القائمة الليلة؟"},{s:0,t:"We've got a seasonal tasting menu — seven courses, all local. It changes every few weeks.",ar:"لدينا قائمة تذوق موسمية — سبعة أطباق، كلها محلية. تتغير كل بضعة أسابيع."},{s:1,t:"Seven courses? That's ambitious. Walk me through the first one.",ar:"سبع دورات؟ هذا طموح. حدّثني عن الطبق الأول."},{s:0,t:"Roasted beets with goat cheese, served in a copper bowl — purely for the look, honestly.",ar:"شمندر محمص مع جبن الماعز، يُقدم في وعاء نحاسي — للشكل فقط بصراحة."},{s:1,t:"Copper bowls, huh? Fancy. Does it actually change the flavor?",ar:"أوعية نحاسية، هاه؟ فاخر. هل يغيّر النكهة فعلًا؟"},{s:0,t:"Not really. But presentation matters — people eat with their eyes first.",ar:"ليس حقًا. لكن العرض مهم — الناس يأكلون بأعينهم أولًا."},{s:1,t:"Fair point. What's the main course? I hear your duck is the star.",ar:"نقطة عادلة. ما الطبق الرئيسي؟ سمعت أن البط لديك هو النجم."},{s:0,t:"The duck, yeah. It's brined for two days, then roasted slow. The skin comes out like glass.",ar:"البط، نعم. يُنقع في محلول ملحي ليومين، ثم يُحمص ببطء. يخرج الجلد مثل الزجاج."},{s:1,t:"Oh wow. And the side? Something to offset the richness?",ar:"أوه واو. والطبق الجانبي؟ شيء يوازن الدسامة؟"},{s:0,t:"Exactly. A sharp cherry sauce and pickled fennel — the acidity cuts right through it.",ar:"بالضبط. صلصة كرز حادة وشمر مخلل — الحموضة تقطعها تمامًا."},{s:1,t:"Smart. Now, be honest — how do you keep the costs down with all this local sourcing?",ar:"ذكي. الآن، كن صادقًا — كيف تحافظ على انخفاض التكاليف مع كل هذا التوريد المحلي؟"},{s:0,t:"It's costly, no lie. But we conserve where we can — we use the whole animal, stems to bones.",ar:"إنه مكلف، بلا كذب. لكننا نحافظ حيث نستطيع — نستخدم الحيوان كله، من السيقان إلى العظام."},{s:1,t:"Nose to tail. I respect that. A lot of places just scrap the good parts.",ar:"من الأنف إلى الذيل. أحترم ذلك. كثير من الأماكن تتخلص فقط من الأجزاء الجيدة."},{s:0,t:"Right? Waste drives me crazy. We even pickle the watermelon rinds.",ar:"صحيح؟ الهدر يجنّني. حتى أننا نخلل قشور البطيخ."},{s:1,t:"Ha! Okay, now I'm curious — what's the dessert? Don't tell me it's—",ar:"ها! حسنًا، الآن أنا فضولي — ما الحلوى؟ لا تقل لي إنها—"},{s:0,t:"—Something basic? Never. Chocolate mousse in a barrel-aged stout sauce. It's the sequel to last year's hit, but better.",ar:"—شيء أساسي؟ أبدًا. موس الشوكولاتة في صلصة بيرة معتقة في برميل. إنها تكملة لنجاح العام الماضي، لكن أفضل."},{s:1,t:"A sequel, huh? High expectations then. What made you bring it back?",ar:"تكملة، هاه؟ توقعات عالية إذن. ما الذي جعلك تعيدها؟"},{s:0,t:"The customers demanded it. I mean, people literally wrote letters about that dessert.",ar:"الزبائن طلبوها. أعني، كتب الناس رسائل حرفيًا عن تلك الحلوى."},{s:1,t:"That's a beautiful problem to have. Now — the wine list. Who put it together?",ar:"هذه مشكلة جميلة. الآن — قائمة النبيذ. من وضعها؟"},{s:0,t:"Our sommelier. She's specialized in natural wines — small producers, minimal intervention.",ar:"خبيرة النبيذ لدينا. إنها متخصصة في النبيذ الطبيعي — منتجون صغار، تدخل ضئيل."},{s:1,t:"Nice. Pairing natural wine with duck is bold. I like bold.",ar:"جميل. إقران النبيذ الطبيعي مع البط جريء. أحب الجرأة."},{s:0,t:"Speaking of bold — we've got a new segment on the menu for dietary needs. Gluten-free, vegan, the works.",ar:"وبمناسبة الجرأة — لدينا قسم جديد في القائمة للاحتياجات الغذائية. خالٍ من الغلوتين، نباتي، وكل شيء."},{s:1,t:"That's smart business. More people can eat here, and nobody feels like an afterthought.",ar:"هذا عمل ذكي. يمكن لعدد أكبر من الناس أن يأكلوا هنا، ولا يشعر أحد بأنه فكرة لاحقة."},{s:0,t:"Exactly. We even label the allergens — nut sensitivity, dairy, all of it, right on the menu.",ar:"بالضبط. حتى أننا نضع علامات على مسببات الحساسية — حساسية المكسرات والألبان وكل شيء، مباشرة على القائمة."},{s:1,t:"Good. Now, the dining room — the setup in there is gorgeous. Who designed it?",ar:"جيد. الآن، غرفة الطعام — التجهيز فيها رائع. من صممها؟"},{s:0,t:"An architectural designer from the neighborhood. She wanted the room to feel warm — wood, low light, no white tablecloths.",ar:"مصممة معمارية من الحي. أرادت أن تشعر الغرفة بالدفء — خشب وإضاءة خافتة، ولا مفارش بيضاء."},{s:1,t:"It works. It feels like a dinner party, not a restaurant. That's a rare realization for a chef, I think.",ar:"إنه يعمل. يبدو كحفل عشاء، وليس مطعمًا. هذا إدراك نادر لطاهٍ، أعتقد."},{s:0,t:"Thanks — that means a lot. Honestly, I just wanna cook food I'd serve my own family.",ar:"شكرًا — هذا يعني الكثير. بصراحة، أريد فقط طهي طعام أقدمه لعائلتي."},{s:1,t:"And that's exactly what shows. One more thing — the bread. Where's it from?",ar:"وهذا بالضبط ما يظهر. شيء أخير — الخبز. من أين يأتي؟"},{s:0,t:"We bake it in-house, twice a day. The starter's three years old — older than my kid.",ar:"نخبزه في المطعم، مرتين في اليوم. الخميرة عمرها ثلاث سنوات — أكبر من طفلي."},{s:1,t:"Ha! A three-year-old starter. That's commitment. Okay, final question — any preliminary plans for a second location?",ar:"ها! خميرة عمرها ثلاث سنوات. هذا التزام. حسنًا، سؤال أخير — هل هناك خطط أولية لموقع ثانٍ؟"},{s:0,t:"We're thinking about it. But first I need to regain some sleep — this place runs me ragged.",ar:"نفكر في ذلك. لكن أولًا أحتاج إلى استعادة بعض النوم — هذا المكان يرهقني."},{s:1,t:"Ha! Fair enough. Well, chef — the meal was terrific. I'll write it up this week.",ar:"ها! عادل بما فيه الكفاية. حسنًا، أيها الطاهي — كانت الوجبة رائعة. سأكتب عنها هذا الأسبوع."},{s:0,t:"Thank you. And hey — if anything needs a correction, just notify me before it goes live.",ar:"شكرًا لك. ومهلًا — إذا احتاج أي شيء إلى تصحيح، فقط أخطرني قبل نشره."},{s:1,t:"Will do. Oh — and the array of desserts? Purely outstanding. Every single one.",ar:"سأفعل. أوه — ومجموعة الحلويات؟ متميزة تمامًا. كل واحدة منها."},{s:0,t:"You're too kind. Come back soon — the rear garden patio opens next month.",ar:"أنت لطيف جدًا. عُد قريبًا — يفتح فناء الحديقة الخلفية الشهر القادم."},{s:1,t:"I'll be there. And I'll bring friends — the more, the merrier.",ar:"سأكون هناك. وسأحضر أصدقاء — كلما زاد العدد، زاد المرح."},{s:0,t:"Perfect. Now get out of my kitchen before the next rotation starts!",ar:"ممتاز. الآن اخرج من مطبخي قبل أن تبدأ الوردية التالية!"},{s:1,t:"Oh — I almost forgot. The bread's counterpart in Paris, namely the bakery across from the Louvre, does the same thing.",ar:"أوه — كدت أنسى. المخبز المماثل في باريس، أي المخبز المقابل للوفر، يفعل الشيء نفسه."},{s:0,t:"Ha! A partial comparison, but I'll take it. A good loaf can boost a whole meal, honestly.",ar:"ها! مقارنة جزئية، لكنني سأقبلها. رغيف جيد يمكن أن يعزز وجبة كاملة بصراحة."},{s:1,t:"True. And the provision of local flour — that's the real pathway to flavor like this.",ar:"صحيح. وتوفير الدقيق المحلي — هذا هو الطريق الحقيقي إلى نكهة كهذه."}]}},{stage:18,topic:"hobbies",topicAr:"الهوايات والرياضة وأوقات الفراغ",topicEn:"Hobbies, Sports & Leisure",topicDe:"Hobbys, Sport und Freizeit",emoji:"⚽",title:"هوايات ورياضة",grammar:{id:"en-c1-subjunctive",title:"Subjunctive",titleAr:"صيغة التمني والافتراض",covers:1},conv:{id:"en-stage18-c1",speakers:["Teammate (زميل الفريق)","Friend (الصديق)"],turns:[{s:0,t:"Dude, you missed practice again. Coach is gonna lose it.",ar:"يا رجل، فاتتك التدريب مجددًا. المدرب سيفقد أعصابه."},{s:1,t:"I know, I know. My car broke down — again. If I had a reliable ride, I'd be there every time.",ar:"أعرف، أعرف. تعطلت سيارتي — مجددًا. لو كان لديّ وسيلة موثوقة، لكنت هناك في كل مرة."},{s:0,t:"Man, that's the third time this month. You gotta figure something out.",ar:"يا رجل، هذه المرة الثالثة هذا الشهر. يجب أن تجد حلًا."},{s:1,t:"I know. It's just... money's tight. And honestly, I've been in misery over this season.",ar:"أعرف. الأمر فقط... المال ضيق. وبصراحة، كنت في بؤس بسبب هذا الموسم."},{s:0,t:"Misery? Come on, we're winning! What's actually wrong?",ar:"بؤس؟ هيّا، نحن نفوز! ما الخطأ فعلًا؟"},{s:1,t:"It's my game, man. My shots are off, my timing's off. I feel like I'm letting the team down.",ar:"إنها لعبتي يا رجل. تسديداتي خاطئة، وتوقيتي خاطئ. أشعر بأنني أخذل الفريق."},{s:0,t:"Stop that. Last game you had twelve points and eight assists. That's not letting anyone down.",ar:"توقف عن ذلك. في المباراة الأخيرة سجلت اثنتي عشرة نقطة وثماني تمريرات حاسمة. هذا ليس خذلانًا لأحد."},{s:1,t:"Yeah, but the turnovers... I keep tossing the ball away at the worst moments.",ar:"نعم، لكن فقدان الكرة... أستمر في رمي الكرة بعيدًا في أسوأ اللحظات."},{s:0,t:"Okay, so what if you slowed down? Like, what if you stopped forcing the fast break every time?",ar:"حسنًا، ماذا لو أبطأت؟ مثل، ماذا لو توقفت عن فرض الهجمة السريعة في كل مرة؟"},{s:1,t:"Hmm. Coach said the same thing, actually. He wants me to tighten up my decision-making.",ar:"همم. قال المدرب الشيء نفسه فعلًا. يريد مني أن أشدد اتخاذ قراراتي."},{s:0,t:"There you go. And hey — your defense is elite. The stats guys track it, you know.",ar:"ها أنت ذا. ومهلًا — دفاعك ممتاز. رجال الإحصائيات يتتبعونه، تعرف."},{s:1,t:"Really? I didn't think anybody noticed defense. It's not exactly glamorous.",ar:"حقًا؟ لم أظن أن أحدًا يلاحظ الدفاع. إنه ليس براقًا بالضبط."},{s:0,t:"Trust me, they notice. The analytics crew has this whole mathematical model for it now.",ar:"صدقني، إنهم يلاحظون. لدى فريق التحليلات نموذج رياضي كامل لذلك الآن."},{s:1,t:"Oh great, math. Just what basketball needed.",ar:"أوه رائع، الرياضيات. بالضبط ما تحتاجه كرة السلة."},{s:0,t:"Ha! But seriously — if you maximize your strengths instead of obsessing over the misses, you'll be fine.",ar:"ها! لكن بجدية — إذا عظّمت نقاط قوتك بدلًا من الهوس بالأخطاء، ستكون بخير."},{s:1,t:"You're right. I do obsess, huh? My girlfriend says the same thing.",ar:"أنت على حق. أنا مهووس، أليس كذلك؟ صديقتي تقول الشيء نفسه."},{s:0,t:"Well, she's right. Okay, change of subject — you still gaming at night?",ar:"حسنًا، إنها على حق. حسنًا، تغيير الموضوع — هل ما زلت تلعب ألعاب الفيديو ليلًا؟"},{s:1,t:"Yeah, a little. My processor died last week, though, so I'm on my old laptop. It's brutal.",ar:"نعم، قليلًا. لكن معالجي تعطل الأسبوع الماضي، لذا أنا على حاسوبي المحمول القديم. إنه وحشي."},{s:0,t:"Ouch. That explains the late nights — you're compensating with old hardware.",ar:"مؤلم. هذا يفسر الليالي المتأخرة — تعوّض بأجهزة قديمة."},{s:1,t:"Pretty much. Hey, did you see the trailer for the new game? It looks insane.",ar:"إلى حد كبير. مهلًا، هل رأيت المقطع الدعائي للعبة الجديدة؟ يبدو جنونيًا."},{s:0,t:"I did! The graphics are unreal. But the price — seventy bucks? That's a threshold I won't cross.",ar:"رأيته! الرسومات لا تصدق. لكن السعر — سبعون دولارًا؟ هذا حد لن أتجاوزه."},{s:1,t:"Ha! Wait for a sale, then. Or split it — you know, share the account.",ar:"ها! انتظر تخفيضًا إذن. أو قسّمها — تعرف، شارك الحساب."},{s:0,t:"Sharing accounts is supposedly against the rules, but everybody does it.",ar:"مشاركة الحسابات يُفترض أنها ضد القواعد، لكن الجميع يفعلها."},{s:1,t:"True. Okay, back to basketball — Saturday's game is huge. The tribal rivalry game, right?",ar:"صحيح. حسنًا، عودة إلى كرة السلة — مباراة السبت ضخمة. مباراة التنافس القبلي، صحيح؟"},{s:0,t:"Yeah, the big one. Their crowd is loud, their bench is deep, and they hate us. Perfect.",ar:"نعم، الكبيرة. جمهورهم صاخب، ومقاعد بدلائهم عميقة، ويكرهوننا. مثالي."},{s:1,t:"Ha! I love that energy. What time's the bus? The transit out there's a nightmare.",ar:"ها! أحب هذه الطاقة. متى موعد الحافلة؟ المواصلات إلى هناك كابوس."},{s:0,t:"Bus leaves at four. And bring your lucky socks — the team's record with them is, like, undefeated.",ar:"تغادر الحافلة في الرابعة. وأحضر جواربك المحظوظة — سجل الفريق معها، مثل، بلا هزيمة."},{s:1,t:"My socks? You're superstitious now? That's predominantly a you thing, not a me thing.",ar:"جواربي؟ أصبحت خرافيًا الآن؟ هذا غالبًا شيء خاص بك، وليس بي."},{s:0,t:"Hey, I don't make the rules. The socks stay. It's symbolic at this point.",ar:"مهلًا، أنا لا أضع القواعد. الجوارب تبقى. إنها رمزية في هذه المرحلة."},{s:1,t:"Fine, fine. The socks stay. Anything else? Should I bring my trademark headband?",ar:"حسنًا، حسنًا. الجوارب تبقى. أي شيء آخر؟ هل يجب أن أحضر عصابة رأسي المميزة؟"},{s:0,t:"Obviously. The headband, the socks, the whole ritual. We don't mess with what works.",ar:"بديهيًا. عصابة الرأس والجوارب والطقس كله. لا نعبث بما يعمل."},{s:1,t:"Okay, okay. But if we lose, I'm blaming the socks. Just so we're clear.",ar:"حسنًا، حسنًا. لكن إذا خسرنا، سألوم الجوارب. فقط لنتفق."},{s:0,t:"Deal. Now — one more thing. After the game, we're all going out. No excuses.",ar:"اتفقنا. الآن — شيء أخير. بعد المباراة، سنخرج جميعًا. بلا أعذار."},{s:1,t:"Out where? Somewhere with actual food this time, I hope.",ar:"إلى أين؟ إلى مكان فيه طعام حقيقي هذه المرة، آمل."},{s:0,t:"Yeah, the taco place. And then maybe the arcade — the new racing game is unreal.",ar:"نعم، مكان التاكو. ثم ربما صالة الألعاب — لعبة السباق الجديدة لا تصدق."},{s:1,t:"Sounds good. Hey — thanks for the pep talk, man. I needed it.",ar:"يبدو جيدًا. مهلًا — شكرًا على الحديث التحفيزي يا رجل. كنت بحاجة إليه."},{s:0,t:"Anytime. That's what teammates are for. Now go home and rest — tomorrow we run drills.",ar:"في أي وقت. هذا ما يفعله زملاء الفريق. الآن اذهب إلى المنزل واسترح — غدًا نجري التدريبات."},{s:1,t:"Ugh, drills. Fine. See you at nine.",ar:"أوه، التدريبات. حسنًا. أراك في التاسعة."},{s:0,t:"Nine sharp. Don't be late — or I'll tell coach about the socks.",ar:"التاسعة بالضبط. لا تتأخر — وإلا سأخبر المدرب عن الجوارب."},{s:1,t:"Wait — one more thing. The ref's call last week? A total overturn would've changed everything.",ar:"انتظر — شيء أخير. قرار الحكم الأسبوع الماضي؟ قلب كامل كان سيغيّر كل شيء."},{s:0,t:"Yeah, and the coach's yell from the stands was a rare occurrence — he's usually so calm.",ar:"نعم، وصراخ المدرب من المدرجات كان حدثًا نادرًا — إنه هادئ عادة."},{s:1,t:"True. He weaves through the rules like that — a utility player in life, not just on court.",ar:"صحيح. ينسج طريقه عبر القواعد هكذا — لاعب متعدد الاستخدامات في الحياة، وليس في الملعب فقط."},{s:0,t:"Ha! And the new kid's got a pronounced limp, but he still whips passes like a pro. Widen the lead and we're golden.",ar:"ها! والفتى الجديد لديه عرج واضح، لكنه ما زال يمرر بسرعة كالمحترفين. وسّع الفارق وسنكون بخير."},{s:1,t:"Exactly. The theoretical stuff matters less than heart — thereby, we win. Worthwhile season, man.",ar:"بالضبط. الأمور النظرية أقل أهمية من القلب — وبذلك نفوز. موسم يستحق العناء يا رجل."},{s:0,t:"Our point guard dropped twenty in the secular winter tournament and thirty in the summer league, respectively — the scouts' radar is all over him.",ar:"سجّل صانع ألعابنا عشرين نقطة في بطولة الشتاء العلمانية وثلاثين في دوري الصيف على التوالي — رادار الكشافين يتابعه في كل مكان."},{s:1,t:"Nice. Hey, does he reside near campus? I keep seeing him at the gym.",ar:"جميل. مهلًا، هل يقيم قرب الحرم الجامعي؟ أستمر في رؤيته في الصالة الرياضية."}]}},{stage:19,topic:"home",topicAr:"المنزل والسكن",topicEn:"Home & Housing",topicDe:"Zuhause und Wohnen",emoji:"🏠",title:"شقة جديدة ومشاكلها",grammar:{id:"en-c1-nominalisation",title:"Nominalisation",titleAr:"تحويل الأفعال إلى أسماء",covers:1},conv:{id:"en-stage19-c1",speakers:["Landlord (صاحب العقار)","Tenant (المستأجر)"],turns:[{s:0,t:"Good morning. You asked to meet — what's on your mind?",ar:"صباح الخير. طلبت الاجتماع — ما الذي يدور في ذهنك؟"},{s:1,t:"Morning. Yeah, look — I love the place, I really do. But the heating's been broken for two weeks.",ar:"صباح الخير. نعم، اسمع — أحب المكان، حقًا. لكن التدفئة معطلة منذ أسبوعين."},{s:0,t:"Two weeks? I thought the repair crew came last Tuesday.",ar:"أسبوعان؟ ظننت أن فريق الإصلاح جاء الثلاثاء الماضي."},{s:1,t:"They came, they looked, they left. Nothing got—",ar:"جاءوا ونظروا وغادروا. لم يُصلح—"},{s:0,t:"—Nothing got fixed? I'm sorry to hear that. Let me check the work order — there may have been a mix-up.",ar:"—لم يُصلح شيء؟ آسف لسماع ذلك. دعني أتحقق من أمر العمل — ربما حدث خلط."},{s:1,t:"I'd appreciate that. And it's not just the heat. The faucet in the bathroom leaks all night — drip, drip, drip.",ar:"سأقدّر ذلك. وليست التدفئة فقط. صنبور الحمام يتسرب طوال الليل — تقطير، تقطير، تقطير."},{s:0,t:"Okay, noted. Anything else? I'd rather hear it all now than in pieces.",ar:"حسنًا، تم تسجيله. أي شيء آخر؟ أفضل أن أسمع كل شيء الآن بدلًا من أجزاء."},{s:1,t:"Well... the back door doesn't lock properly. I have to squeeze the handle and lift it just right.",ar:"حسنًا... الباب الخلفي لا يُقفل بشكل صحيح. يجب أن أضغط على المقبض وأرفعه بالطريقة الصحيحة."},{s:0,t:"That's a safety issue — I'll get someone out this week. I take that seriously.",ar:"هذه مسألة سلامة — سأرسل شخصًا هذا الأسبوع. آخذ ذلك بجدية."},{s:1,t:"Thanks. I mean, I pay on time every month. I just want the basics to work.",ar:"شكرًا. أعني، أدفع في الوقت المحدد كل شهر. أريد فقط أن تعمل الأساسيات."},{s:0,t:"And you should. Look, the previous tenant never reported anything — I had no idea things were this bad.",ar:"ويجب أن تعمل. اسمع، المستأجر السابق لم يبلّغ عن أي شيء — لم أكن أعلم أن الأمور بهذا السوء."},{s:1,t:"That explains a lot. The whole place has a kind of... passive neglect feel to it, you know?",ar:"هذا يفسر الكثير. المكان كله فيه نوع من... شعور الإهمال السلبي، تعرف؟"},{s:0,t:"I hear you. The building's old — the preservation of these old places costs a fortune.",ar:"أسمعك. المبنى قديم — الحفاظ على هذه الأماكن القديمة يكلف ثروة."},{s:1,t:"I get that. But the rent went up this year, so I expected the upkeep to match.",ar:"أفهم ذلك. لكن الإيجار ارتفع هذا العام، فتوقعت أن تواكبه الصيانة."},{s:0,t:"Fair point. Tell you what — I'll waive the late fee from last month as a gesture, and we'll fix the big stuff first.",ar:"نقطة عادلة. أقول لك — سأتنازل عن رسوم التأخير من الشهر الماضي كبادرة، وسنصلح الأشياء الكبيرة أولًا."},{s:1,t:"That's a good start. What about the mold in the bathroom? That's a health thing, not cosmetic.",ar:"هذه بداية جيدة. وماذا عن العفن في الحمام؟ هذه مسألة صحية، وليست تجميلية."},{s:0,t:"Mold? Where exactly? Show me — I wanna see it myself.",ar:"عفن؟ أين بالضبط؟ أرني — أريد أن أراه بنفسي."},{s:1,t:"Behind the tub, along the wall. It's small, but it's spreading. And my kid's got asthma.",ar:"خلف حوض الاستحمام، على طول الجدار. إنه صغير، لكنه ينتشر. وطفلي مصاب بالربو."},{s:0,t:"Okay, that jumps to the top of the list. I'll call the remediation company today.",ar:"حسنًا، هذا يقفز إلى أعلى القائمة. سأتصل بشركة المعالجة اليوم."},{s:1,t:"Thank you. Seriously. I was starting to contemplate moving out, and I really don't wanna.",ar:"شكرًا لك. بجدية. كنت أبدأ بالتفكير في الانتقال، ولا أريد ذلك حقًا."},{s:0,t:"I'm glad you came to me first. Moving is a pain for everyone. Let's fix this properly.",ar:"سعيد لأنك جئت إليّ أولًا. الانتقال مؤلم للجميع. لنصلح هذا بشكل صحيح."},{s:1,t:"Agreed. One more thing — the lease says I can't paint the walls. Is that a hard rule?",ar:"متفق. شيء أخير — عقد الإيجار يقول إنني لا أستطيع طلاء الجدران. هل هذه قاعدة صارمة؟"},{s:0,t:"It's in the lease, yeah. But if you pick a neutral color and restore it when you leave, I'm flexible.",ar:"إنها في العقد، نعم. لكن إذا اخترت لونًا محايدًا وأعدته كما كان عند المغادرة، فأنا مرن."},{s:1,t:"Deal. My wife wants a warm yellow in the kitchen — nothing crazy.",ar:"اتفقنا. زوجتي تريد أصفر دافئًا في المطبخ — لا شيء جنوني."},{s:0,t:"Yellow's fine. Just no dark colors — they're a nightmare to cover up later.",ar:"الأصفر جيد. فقط لا ألوان داكنة — إنها كابوس لتغطيتها لاحقًا."},{s:1,t:"Got it. Oh — the neighbors upstairs. The noise at night is... a lot.",ar:"فهمت. أوه — الجيران في الأعلى. الضجيج ليلًا... كثير."},{s:0,t:"The couple with the baby? Or the guy with the drum set?",ar:"الزوجان مع الطفل؟ أم الرجل مع طقم الطبول؟"},{s:1,t:"The drummer. He practices at midnight. I swear, it's like a cult ritual up there.",ar:"عازف الطبول. يتدرب في منتصف الليل. أقسم، إنه مثل طقس طائفي هناك."},{s:0,t:"Ha! I'll have a word with him. Quiet hours start at ten — that's in his lease too.",ar:"ها! سأتحدث معه. ساعات الهدوء تبدأ في العاشرة — هذا في عقده أيضًا."},{s:1,t:"Thanks. I know it's not your fault — but you're the only one who can do something about it.",ar:"شكرًا. أعرف أنه ليس خطأك — لكنك الوحيد الذي يستطيع فعل شيء حيال ذلك."},{s:0,t:"That's my job. Now, the parking — you mentioned the spot situation?",ar:"هذه وظيفتي. الآن، موقف السيارات — ذكرت وضع الموقف؟"},{s:1,t:"Yeah, someone keeps taking my spot. I've left notes, but nothing changes.",ar:"نعم، شخص ما يستمر في أخذ موقفي. تركت ملاحظات، لكن لا شيء يتغير."},{s:0,t:"I'll put up a sign with your unit number. And if it happens again, tell me — I'll tow.",ar:"سأضع لافتة برقم وحدتك. وإذا حدث مجددًا، أخبرني — سأسحب السيارة."},{s:1,t:"Perfect. Okay, I think that's everything. Thanks for actually listening.",ar:"ممتاز. حسنًا، أعتقد أن هذا كل شيء. شكرًا لاستماعك فعلًا."},{s:0,t:"Of course. Hey — one thing in return: keep me posted if anything else breaks. Don't wait.",ar:"بالطبع. مهلًا — شيء واحد في المقابل: أبقني على اطلاع إذا تعطل أي شيء آخر. لا تنتظر."},{s:1,t:"Will do. And I'll pay the rent early this month — call it a peace offering.",ar:"سأفعل. وسأدفع الإيجار مبكرًا هذا الشهر — اعتبره عرض سلام."},{s:0,t:"Ha! Now that's what I like to hear. Have a good day.",ar:"ها! الآن هذا ما أحب سماعه. أتمنى لك يومًا سعيدًا."},{s:1,t:"You too. And thanks again — this went way better than I expected.",ar:"وأنت أيضًا. وشكرًا مجددًا — سار هذا أفضل بكثير مما توقعت."},{s:0,t:"By the way — the superintendent wants a strategic plan for the building's upgrades. A formal submission by Friday.",ar:"بالمناسبة — يريد المشرف خطة استراتيجية لترقيات المبنى. تقديم رسمي بحلول الجمعة."},{s:1,t:"A submission? For what — the suburban office crowd? We're tenants, not a corporation.",ar:"تقديم؟ لماذا — لأصحاب مكاتب الضواحي؟ نحن مستأجرون، وليس شركة."},{s:0,t:"Ha! Fair. But the suite upstairs is being renovated into offices, and they might sue the contractor if it's late.",ar:"ها! عادل. لكن الجناح في الأعلى يُجدد إلى مكاتب، وقد يقاضون المقاول إذا تأخر."},{s:1,t:"Sue the contractor? Man, this building's more drama than TV. The hardware store guy says the costs correlate with the delays.",ar:"يقاضون المقاول؟ يا رجل، هذا المبنى دراما أكثر من التلفاز. يقول صاحب متجر الأدوات إن التكاليف ترتبط بالتأخيرات."},{s:0,t:"They do. And frankly, only a capitalist landlord would charge extra for a broken heater — I'm not that guy.",ar:"إنها كذلك. وبصراحة، فقط مالك رأسمالي يفرض رسومًا إضافية على مدفأة معطلة — لست ذلك الشخص."},{s:1,t:"It's frustrating — every fix feels like a slap on the wrist for the building, not a real repair.",ar:"إنه محبط — كل إصلاح يبدو كصفعة خفيفة على معصم المبنى، وليس إصلاحًا حقيقيًا."}]}},{stage:20,topic:"intro",topicAr:"التعارف والبيانات الشخصية",topicEn:"Introductions & Personal Details",topicDe:"Kennenlernen und persönliche Angaben",emoji:"👋",title:"جيران جدد",grammar:{id:"en-c1-ellipsis-substitution",title:"Ellipsis",titleAr:"الحذف",covers:1},conv:{id:"en-stage20-c1",speakers:["New Neighbor (الجار الجديد)","Neighbor (الجار)"],turns:[{s:0,t:"Hi! Sorry — I just moved in next door. I'm still living out of boxes, honestly.",ar:"مرحبًا! عذرًا — انتقلت للتو إلى المنزل المجاور. ما زلت أعيش بين الصناديق بصراحة."},{s:1,t:"Hey, welcome to the street! Don't worry — everybody here took weeks to—",ar:"مهلًا، مرحبًا بك في الشارع! لا تقلق — استغرق الجميع هنا أسابيع لـ—"},{s:0,t:"—Weeks to unpack? Oh good, so I'm not behind. What's the neighborhood like? I've only been here two days.",ar:"—أسابيع لتفريغ الأمتعة؟ أوه جيد، إذن لست متأخرة. كيف الحي؟ لم أكن هنا سوى يومين."},{s:1,t:"It's great, mostly. Quiet, friendly — a varied mix of families, students, old folks. You'll like it.",ar:"إنه رائع غالبًا. هادئ وودود — مزيج متنوع من العائلات والطلاب وكبار السن. سيعجبك."},{s:0,t:"Good to hear. I'm a nurse, so I work weird hours — I hope the night shifts won't be a problem.",ar:"سعيد بسماع ذلك. أنا ممرضة، لذا أعمل ساعات غريبة — آمل ألا تكون ورديات الليل مشكلة."},{s:1,t:"A nurse? That's wonderful. My wife's a nurse too — night shifts, same deal. You two will get along.",ar:"ممرضة؟ هذا رائع. زوجتي ممرضة أيضًا — ورديات ليلية، نفس الأمر. ستتفقان."},{s:0,t:"Oh, nice! Yeah, the night shift life — you either love it or it wrecks you. No in-between.",ar:"أوه، جميل! نعم، حياة الوردية الليلية — إما أن تحبها أو تدمرك. لا حل وسط."},{s:1,t:"Ha! She says the same thing. So where'd you move from?",ar:"ها! تقول الشيء نفسه. إذن من أين انتقلت؟"},{s:0,t:"Chicago. I grew up there, but the winters finally broke me. I needed sun, you know?",ar:"شيكاغو. نشأت هناك، لكن الشتاء كسرني أخيرًا. احتجت إلى الشمس، تعرف؟"},{s:1,t:"I get it. Cold like that gets into your flesh and bones. You'll love it here — we get sun year-round.",ar:"أفهم ذلك. برد كهذا يتغلغل في لحمك وعظامك. ستحب المكان هنا — نحصل على الشمس طوال العام."},{s:0,t:"That's the dream. So, what do you do? If you don't mind me asking.",ar:"هذا هو الحلم. إذن، ماذا تعمل؟ إذا لم تمانع سؤالي."},{s:1,t:"Not at all. I work in tech — hardware testing, mostly. We run simulations all day to break things on purpose.",ar:"إطلاقًا. أعمل في التكنولوجيا — اختبار الأجهزة غالبًا. نجري محاكاة طوال اليوم لكسر الأشياء عن قصد."},{s:0,t:"Break things on purpose? That sounds like a dream job, honestly.",ar:"تكسر الأشياء عن قصد؟ يبدو ذلك وظيفة أحلام بصراحة."},{s:1,t:"It is, mostly. Though the paperwork... the reports alone could kill a person.",ar:"إنها كذلك غالبًا. مع أن الأوراق... التقارير وحدها يمكن أن تقتل شخصًا."},{s:0,t:"Ha! Every job's got its paperwork. So, do you have family here, or is it just you?",ar:"ها! كل وظيفة فيها أوراق. إذن، هل لديك عائلة هنا، أم أنت وحدك؟"},{s:1,t:"Just me and my wife, and our dog — a rescue mutt named Biscuit. He's a sweetheart.",ar:"أنا وزوجتي فقط، وكلبنا — كلب إنقاذ هجين اسمه بسكويت. إنه لطيف جدًا."},{s:0,t:"A rescue dog! I love that. I had one growing up — best friend I ever had.",ar:"كلب إنقاذ! أحب ذلك. كان لديّ واحد في طفولتي — أفضل صديق لي على الإطلاق."},{s:1,t:"They're the best. Hey — we're having a barbecue Saturday. You should come, meet everybody.",ar:"إنهم الأفضل. مهلًا — سنقيم حفل شواء يوم السبت. يجب أن تأتي وتقابل الجميع."},{s:0,t:"Oh, I'd love to! Can I bring anything? I make a mean potato salad.",ar:"أوه، سأحب ذلك! هل يمكنني إحضار شيء؟ أصنع سلطة بطاطس رائعة."},{s:1,t:"Bring the potato salad, then. And yourself — that's the main provision, honestly.",ar:"أحضري سلطة البطاطس إذن. ونفسك — هذا هو الأهم بصراحة."},{s:0,t:"Deal. So, tell me — any good restaurants around here? I'm starving most nights after a shift.",ar:"اتفقنا. إذن، أخبرني — هل توجد مطاعم جيدة هنا؟ أكون جائعة معظم الليالي بعد الوردية."},{s:1,t:"Oh yeah, plenty. There's a taco truck on the corner — the real deal. And a bakery two blocks down.",ar:"أوه نعم، الكثير. هناك عربة تاكو على الزاوية — الحقيقية. ومخبز على بعد مبنيين."},{s:0,t:"A taco truck and a bakery? I'm gonna gain ten pounds in a month.",ar:"عربة تاكو ومخبز؟ سأكتسب عشرة أرطال في شهر."},{s:1,t:"Ha! We all did. The bakery's croissants are a legitimate health hazard.",ar:"ها! فعلنا جميعًا. كرواسان المخبز خطر صحي حقيقي."},{s:0,t:"Okay, noted — avoid the bakery. Or, you know, don't. Life's short.",ar:"حسنًا، تم تسجيله — تجنب المخبز. أو، تعرف، لا تفعل. الحياة قصيرة."},{s:1,t:"That's the spirit. Now — the practical stuff. Trash day is Tuesday, recycling Thursday.",ar:"هذه هي الروح. الآن — الأشياء العملية. يوم القمامة الثلاثاء، وإعادة التدوير الخميس."},{s:0,t:"Tuesday and Thursday, got it. And parking? Is it always this packed?",ar:"الثلاثاء والخميس، فهمت. والموقف؟ هل هو مزدحم دائمًا هكذا؟"},{s:1,t:"Pretty much. It's a partial mess — the city keeps promising more spots, but nothing changes.",ar:"إلى حد كبير. إنها فوضى نوعًا ما — المدينة تستمر في الوعد بمزيد من المواقف، لكن لا شيء يتغير."},{s:0,t:"Classic city promise. Well, I'll figure it out. Hey, thanks for the warm welcome.",ar:"وعد مدينة كلاسيكي. حسنًا، سأتدبر الأمر. مهلًا، شكرًا على الترحيب الحار."},{s:1,t:"Anytime. Oh — one last thing. If you ever need anything — a ladder, sugar, a jump-start — just knock.",ar:"في أي وقت. أوه — شيء أخير. إذا احتجت أي شيء — سلمًا أو سكرًا أو تشغيل سيارة — فقط اطرق الباب."},{s:0,t:"That's really kind. Same goes for you — if you need a nurse at 2 a.m., I'm your neighbor.",ar:"هذا لطيف حقًا. وينطبق الأمر عليك أيضًا — إذا احتجت ممرضة في الثانية فجرًا، فأنا جارتك."},{s:1,t:"Ha! I'll keep that in mind. Alright, I'll let you get back to the boxes.",ar:"ها! سأضع ذلك في اعتباري. حسنًا، سأدعك تعودين إلى الصناديق."},{s:0,t:"Thanks. See you Saturday — and I'll bring the potato salad, I promise.",ar:"شكرًا. أراك يوم السبت — وسأحضر سلطة البطاطس، أعدك."},{s:1,t:"Looking forward to it. Welcome home!",ar:"أتطلع إلى ذلك. مرحبًا بك في بيتك!"},{s:0,t:"Thanks — it already feels like it.",ar:"شكرًا — يبدو كذلك بالفعل."},{s:1,t:"Oh, I should mention — I work consecutive night shifts sometimes, three in a row. The likelihood I'm asleep at noon is pretty high.",ar:"أوه، يجب أن أذكر — أعمل ورديات ليلية متتالية أحيانًا، ثلاث على التوالي. احتمال أن أكون نائمة عند الظهر مرتفع جدًا."},{s:0,t:"Noted — I'll keep Biscuit quiet. My kid's behavioral therapist says routine helps, so a regular schedule matters.",ar:"تم تسجيله — سأبقي بسكويت هادئًا. يقول معالج سلوك طفلي إن الروتين يساعد، لذا الجدول المنتظم مهم."},{s:1,t:"Makes sense. Hey, where'd you grow up? I grew up in a mining town — my dad worked the mines.",ar:"منطقي. مهلًا، أين نشأت؟ نشأت في بلدة تعدين — كان والدي يعمل في المناجم."},{s:0,t:"A mining town, wow. And you test optical sensors now? That's quite a jump.",ar:"بلدة تعدين، واو. وأنت تختبر أجهزة استشعار بصرية الآن؟ هذه قفزة كبيرة."},{s:1,t:"Yeah, life twists. I test optical hardware, and on weekends I build a smart-home module for fun.",ar:"نعم، الحياة تلتف. أختبر الأجهزة البصرية، وفي عطلات نهاية الأسبوع أبني وحدة منزل ذكي للمتعة."},{s:0,t:"Nice! Well, the old fence between our yards — the remains of it — I'll haul it away this weekend if you want.",ar:"جميل! حسنًا، السياج القديم بين حديقتيْنا — بقاياه — سأنقله بعيدًا في عطلة نهاية الأسبوع إذا أردت."},{s:1,t:"That'd be great. And hey — if I bail on the barbecue, it's not you, it's the night shift. I promise I'll try.",ar:"سيكون ذلك رائعًا. ومهلًا — إذا تخلفت عن حفل الشواء، فالأمر ليس بسببك، بل بسبب الوردية الليلية. أعدك بأنني سأحاول."},{s:0,t:"No worries. Oh — the parking slot by the gate? That's yours. The residential permit covers both our spots.",ar:"لا تقلق. أوه — موقف السيارات بجانب البوابة؟ إنه لك. تصريح السكن يغطي موقفينا."},{s:1,t:"Perfect. My sister and I both reside in this neighborhood — she lives two doors down.",ar:"ممتاز. أختي وأنا نقيمان في هذا الحي — تعيش على بعد بابين."},{s:0,t:"It's a sin to waste a Saturday like this — let's grab coffee after the boxes.",ar:"من الخطيئة إهدار يوم سبت كهذا — لنشرب القهوة بعد الصناديق."}]}},{stage:21,topic:"street",topicAr:"كلام الشارع",topicEn:"Street Talk",topicDe:"Street Talk",emoji:"",title:"خيانة وانفصال",grammar:{id:"en-c1-discourse-markers",title:"Discourse markers",titleAr:"روابط الخطاب (Discourse markers)",covers:1},conv:{id:"en-stage21-c1",speakers:["Emma (إيما)","Jake (جايك)"],turns:[{s:0,t:"Don't lie to me, Jake. I saw the messages.",ar:"لا تكذب عليّ يا جايك. رأيت الرسائل."},{s:1,t:"Emma, it's not what you think. Let me explain.",ar:"إيما، الأمر ليس كما تظنين. دعيني أشرح."},{s:0,t:"Explain what? Three months of messages to her? What the fuck were you thinking?",ar:"تشرح ماذا؟ ثلاثة أشهر من الرسائل إليها؟ ما الذي كنت تفكر فيه بحق الجحيم؟"},{s:1,t:"Okay, I messed up. But it didn't mean anything.",ar:"حسنًا، أخطأت. لكن الأمر لم يعنِ شيئًا."},{s:0,t:"Didn't mean anything? You told her you loved her!",ar:"لم يعنِ شيئًا؟ أخبرتها أنك تحبها!"},{s:1,t:"I was lonely. You were never home — always working, always busy.",ar:"كنت وحيدًا. لم تكوني في البيت أبدًا — دائمًا تعملين، دائمًا مشغولة."},{s:0,t:"Oh, so it's MY fault? That's fucked up, Jake. Really fucked up.",ar:"أوه، إذن إنه خطئي أنا؟ هذا أمرٌ مقرف يا جايك. مقرف حقًا."},{s:1,t:"I'm not saying it's your fault. I'm saying we were already broken.",ar:"لا أقول إنه خطؤك. أقول إننا كنا منكسرين أصلًا."},{s:0,t:"No. WE were fine until you went behind my back. You screwed me over, Jake.",ar:"لا. كنا بخير حتى طعنتني من الخلف. لقد غدرت بي يا جايك."},{s:1,t:"I know. And I'm sorry. I don't expect you to forgive me.",ar:"أعرف. وأنا آسف. لا أتوقع منك أن تسامحيني."},{s:0,t:"Sorry? You cheated on me with that whore from your office — and all you have is 'sorry'?",ar:"آسف؟ خنتني مع تلك العاهرة من مكتبك — وكل ما لديك هو 'آسف'؟"},{s:1,t:"Don't call her that. This is between you and me.",ar:"لا تناديها هكذا. الأمر بيني وبينك."},{s:0,t:"I don't give a fuck what you think anymore. You don't get to defend her.",ar:"لم أعد أهتم إطلاقًا بما تفكر به. لا يحق لك الدفاع عنها."},{s:1,t:"Emma, please. Five years — you're just going to throw it all away?",ar:"إيما، من فضلك. خمس سنوات — سترمين كل شيء هكذا؟"},{s:0,t:"YOU threw it away. I'm pissed off, I'm hurt — and I'm done.",ar:"أنت من رميته. أنا غاضبة، أنا مجروحة — وانتهيت."},{s:1,t:"...Then I guess this is goodbye.",ar:"...إذن أظن أن هذا وداع."}]}}]}}